static ds4_gpu_rms_norm_args ds4_gpu_make_rms_norm_3d_args(
 uint32_t n0,
 uint32_t n1,
 uint32_t n2,
 float eps) {
 const uint64_t row_bytes = (uint64_t)n0 * sizeof(float);
 const uint64_t plane_bytes = row_bytes * n1;
 return (ds4_gpu_rms_norm_args) {
 .ne00 = (int32_t)n0,
 .ne00_t = (int32_t)(n0 / 4u),
 .nb1 = row_bytes,
 .nb2 = plane_bytes,
