int ds4_gpu_indexer_topk_tensor(
 ds4_gpu_tensor *selected,
 const ds4_gpu_tensor *scores,
 uint32_t n_comp,
 uint32_t n_tokens,
 uint32_t top_k) {
 if (!g_initialized && !ds4_gpu_init()) return 0;
 if (!selected || !scores || n_comp == 0 || n_tokens == 0 || top_k == 0 || top_k > n_comp) return 0;

 @autoreleasepool {
 const uint64_t score_bytes = (uint64_t)n_comp * n_tokens * sizeof(float);
 const uint64_t selected_bytes = (uint64_t)top_k * n_tokens * sizeof(uint32_t);
 id<MTLBuffer> scorebuf = ds4_gpu_tensor_buffer(scores);
 id<MTLBuffer> selbuf = ds4_gpu_tensor_buffer(selected);
 if (!scorebuf || !selbuf ||
 ds4_gpu_tensor_bytes(scores) < score_bytes ||
 ds4_gpu_tensor_bytes(selected) < selected_bytes) {
 fprintf(stderr, "ds4: Metal graph indexer top-k received undersized buffers\n");
 return 0;
 }
 NSUInteger max_threads = g_argsort_f32_i32_desc_pipeline.maxTotalThreadsPerThreadgroup;
 if (max_threads == 0) max_threads = 256;
 int32_t nth = 1;
 while ((uint32_t)nth < n_comp && (uint64_t)2u * (uint64_t)nth <= (uint64_t)max_threads) {
 nth *= 2;
 }
 const int32_t npr = (int32_t)((n_comp + (uint32_t)nth - 1u) / (uint32_t)nth);
 const int32_t block_top_k = (int32_t)(top_k < (uint32_t)nth ? top_k : (uint32_t)nth);
 int32_t work_width = (int32_t)top_k;
 if (npr > 1) {
 const int32_t last_block = (int32_t)n_comp - (npr - 1) * nth;
 work_width = (npr - 1) * block_top_k + (last_block < block_top_k ? last_block : block_top_k);
 }
 const uint64_t scratch_row_bytes = (uint64_t)work_width * sizeof(uint32_t);
 const bool one_pass = npr <= 1;
 const uint64_t scratch_bytes = one_pass ? scratch_row_bytes * n_tokens :
 2u * scratch_row_bytes * n_tokens;
 if (!ds4_gpu_ensure_scratch_buffer(&g_indexer_topk_buffer,
 &g_indexer_topk_bytes,
 (NSUInteger)scratch_bytes,
 "ds4_indexer_topk")) {
 return 0;
 }

 ds4_gpu_kargs_argsort args = {
 .ne00 = (int32_t)n_comp,
 .ne01 = (int32_t)n_tokens,
 .ne02 = 1,
 .ne03 = 1,
 .nb00 = sizeof(float),
 .nb01 = (uint64_t)n_comp * sizeof(float),
 .nb02 = (uint64_t)n_comp * n_tokens * sizeof(float),
 .nb03 = (uint64_t)n_comp * n_tokens * sizeof(float),
 .ne0 = work_width,
 .ne1 = (int32_t)n_tokens,
 .ne2 = 1,
 .ne3 = 1,
 .top_k = block_top_k,
 };
 const NSUInteger smem = (((NSUInteger)nth * sizeof(int32_t)) + 15u) & ~(NSUInteger)15u;

 NSUInteger cur_off = 0;
 NSUInteger next_off = (NSUInteger)scratch_row_bytes * n_tokens;
 int owned = 0;
 id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
 if (!cb) return 0;

 id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
 [enc setComputePipelineState:g_argsort_f32_i32_desc_pipeline];
 [enc setBytes:&args length:sizeof(args) atIndex:0];
 [enc setBuffer:scorebuf offset:ds4_gpu_tensor_offset(scores) atIndex:1];
 [enc setBuffer:one_pass ? selbuf : g_indexer_topk_buffer
 offset:one_pass ? ds4_gpu_tensor_offset(selected) : cur_off
 atIndex:2];
 [enc setThreadgroupMemoryLength:smem atIndex:0];
 [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)npr * n_tokens, 1, 1)
 threadsPerThreadgroup:MTLSizeMake((NSUInteger)nth, 1, 1)];
 ds4_gpu_end_compute_encoder(cb, enc);

 int32_t len = block_top_k;
 while (len < work_width) {
 const int32_t nm = (work_width + 2 * len - 1) / (2 * len);
 const bool final_merge = nm == 1;
 NSUInteger merge_threads = g_argsort_merge_f32_i32_desc_pipeline.maxTotalThreadsPerThreadgroup;
 if (merge_threads == 0 || merge_threads > 512u) merge_threads = 512u;
 if (merge_threads > (NSUInteger)len) merge_threads = (NSUInteger)len;
 if (merge_threads == 0) merge_threads = 1;

 ds4_gpu_kargs_argsort_merge merge_args = {
 .ne00 = (int64_t)n_comp,
 .ne01 = (int64_t)n_tokens,
 .ne02 = 1,
 .ne03 = 1,
 .nb00 = sizeof(float),
 .nb01 = (uint64_t)n_comp * sizeof(float),
 .nb02 = (uint64_t)n_comp * n_tokens * sizeof(float),
 .nb03 = (uint64_t)n_comp * n_tokens * sizeof(float),
 .ne0 = work_width,
 .ne1 = (int32_t)n_tokens,
 .ne2 = 1,
 .ne3 = 1,
 .top_k = nm == 1 ? (int32_t)top_k : work_width,
 .len = len,
 };

 enc = ds4_gpu_compute_encoder(cb);
 [enc setComputePipelineState:g_argsort_merge_f32_i32_desc_pipeline];
 [enc setBytes:&merge_args length:sizeof(merge_args) atIndex:0];
 [enc setBuffer:scorebuf offset:ds4_gpu_tensor_offset(scores) atIndex:1];
 [enc setBuffer:g_indexer_topk_buffer offset:cur_off atIndex:2];
 [enc setBuffer:final_merge ? selbuf : g_indexer_topk_buffer
 offset:final_merge ? ds4_gpu_tensor_offset(selected) : next_off
 atIndex:3];
 [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)nm * n_tokens, 1, 1)
 threadsPerThreadgroup:MTLSizeMake(merge_threads, 1, 1)];
 ds4_gpu_end_compute_encoder(cb, enc);

 const NSUInteger tmp = cur_off;
 cur_off = next_off;
 next_off = tmp;
 len <<= 1;
 }

 if (!ds4_gpu_finish_command_buffer(cb, owned, "indexer top-k")) return 0;
 }

 return 1;
}

/* #557 ICB Phase 3 helper for kernel_dsv4_topk_mask + scatter pair.
 * Returns 1 if ICB path executed, 0 if fell through (caller does direct).
 * Slot key: (top_k, n_tokens, n_comp, topk_ptr, mask_ptr) — re-records on mismatch. */
static int ds4_topk_mask_dispatch_icb(id<MTLCommandBuffer> cb,
                                       uint32_t slot_idx,
                                       const ds4_gpu_dsv4_topk_mask_args *args,
                                       id<MTLBuffer> topkbuf, NSUInteger topk_off,
                                       id<MTLBuffer> maskbuf, NSUInteger mask_off,
                                       uint32_t n_comp, uint32_t n_tokens, uint32_t top_k) {
    static int s_env_checked = 0;
    static int s_env_active = 0;
    if (!s_env_checked) {
        s_env_active = getenv("DS4_ICB_TOPK_MASK") != NULL ? 1 : 0;
        s_env_checked = 1;
        if (s_env_active) {
            fprintf(stderr, "ds4: DS4_ICB_TOPK_MASK=1 — topk_mask 2-kernel ICB engaged (opt-in; measurement pending)\n");
        }
    }
    if (!s_env_active) return 0;
    if (slot_idx >= DS4_TOPK_MASK_ICB_SLOTS) return 0;
    if (!g_dsv4_topk_mask_pipeline || !g_dsv4_topk_mask_scatter_pipeline) return 0;

    /* Cycle 9e (silv 2026-05-28 task #673/#795) — migrated to unified
     * ds4_icb_slot API. 2 commands per slot (mask + scatter) so
     * max_commands = DS4_TOPK_MASK_ICB_SLOTS * 2; slot_idx*2+0 = mask
     * command, slot_idx*2+1 = scatter command. The bespoke
     * ds4_topk_mask_icb_slot's per-call (top_k, n_tokens, n_comp)
     * scalars become signature extras (grid size derives from them,
     * already in the signature; extras let two records with same grid
     * but different scalars be distinct). */
    if (!g_topk_mask_slot.icb) {
        if (!ds4_icb_slot_acquire(&g_topk_mask_slot,
                                  /*max_commands=*/(NSUInteger)(DS4_TOPK_MASK_ICB_SLOTS * 2),
                                  /*max_bindings=*/3)) return 0;
    }
    if (!g_topk_mask_icb_args_buffers[slot_idx]) {
        g_topk_mask_icb_args_buffers[slot_idx] =
            [g_device newBufferWithLength:sizeof(*args)
                                  options:MTLResourceStorageModeShared];
        if (!g_topk_mask_icb_args_buffers[slot_idx]) return 0;
    }
    /* Args must be refreshed every replay (struct contents may change
     * even when buffer pointer doesn't). The args struct is small
     * (~64 bytes); memcpy cost negligible. */
    memcpy([g_topk_mask_icb_args_buffers[slot_idx] contents], args, sizeof(*args));

    const NSUInteger groups_mask    = ((NSUInteger)n_comp * n_tokens + 255u) / 256u;
    const NSUInteger groups_scatter = ((NSUInteger)top_k  * n_tokens + 255u) / 256u;
    __unsafe_unretained id<MTLBuffer> bufs[3] = {
        g_topk_mask_icb_args_buffers[slot_idx], topkbuf, maskbuf };
    NSUInteger offs[3] = { 0, topk_off, mask_off };
    uint64_t extras[3] = { top_k, n_tokens, n_comp };
    if (!ds4_icb_slot_record_command(&g_topk_mask_slot,
                                     /*cmd_idx=*/(NSUInteger)(slot_idx * 2 + 0),
                                     g_dsv4_topk_mask_pipeline, bufs, offs, 3,
                                     MTLSizeMake(groups_mask, 1, 1),
                                     MTLSizeMake(256, 1, 1), 0,
                                     extras, 3)) return 0;
    if (!ds4_icb_slot_record_command(&g_topk_mask_slot,
                                     /*cmd_idx=*/(NSUInteger)(slot_idx * 2 + 1),
                                     g_dsv4_topk_mask_scatter_pipeline, bufs, offs, 3,
                                     MTLSizeMake(groups_scatter, 1, 1),
                                     MTLSizeMake(256, 1, 1), 0,
                                     extras, 3)) return 0;

    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc useResource:g_topk_mask_icb_args_buffers[slot_idx] usage:MTLResourceUsageRead];
    [enc useResource:topkbuf usage:MTLResourceUsageRead];
    [enc useResource:maskbuf usage:MTLResourceUsageRead | MTLResourceUsageWrite];
    ds4_icb_slot_execute(&g_topk_mask_slot, enc,
                         /*start=*/(NSUInteger)(slot_idx * 2), /*n=*/2);
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

int ds4_gpu_dsv4_topk_mask_tensor(
 ds4_gpu_tensor *mask,
 const ds4_gpu_tensor *topk,
 uint32_t n_comp,
 uint32_t n_tokens,
 uint32_t top_k) {
 if (!g_initialized && !ds4_gpu_init()) return 0;
 if (!mask || !topk || n_comp == 0 || n_tokens == 0 || top_k == 0) return 0;

 @autoreleasepool {
 const uint64_t topk_bytes = (uint64_t)top_k * n_tokens * sizeof(int32_t);
 const uint64_t mask_bytes = (uint64_t)n_comp * n_tokens * sizeof(float);
 id<MTLBuffer> topkbuf = ds4_gpu_tensor_buffer(topk);
 id<MTLBuffer> maskbuf = ds4_gpu_tensor_buffer(mask);
 if (!topkbuf || !maskbuf ||
 ds4_gpu_tensor_bytes(topk) < topk_bytes ||
 ds4_gpu_tensor_bytes(mask) < mask_bytes) {
 fprintf(stderr, "ds4: Metal dsv4 top-k mask received undersized buffers\n");
 return 0;
 }

 ds4_gpu_dsv4_topk_mask_args args = {
 .ne00 = (int64_t)top_k,
 .ne01 = (int64_t)n_tokens,
 .nb00 = sizeof(int32_t),
 .nb01 = (uint64_t)top_k * sizeof(int32_t),
 .ne0 = (int64_t)n_comp,
 .ne1 = (int64_t)n_tokens,
 .nb0 = sizeof(float),
 .nb1 = (uint64_t)n_comp * sizeof(float),
 };

 int owned = 0;
 id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
 if (!cb) return 0;

 /* #557 ICB Phase 3: try ICB path first (opt-in via DS4_ICB_TOPK_MASK=1).
  * Slot 0 = this single call-site path (indexer top-k mask).
  * On miss / opt-out, fall through to direct encoding below. */
 const int icb_ran = ds4_topk_mask_dispatch_icb(cb, 0, &args,
                                                topkbuf, ds4_gpu_tensor_offset(topk),
                                                maskbuf, ds4_gpu_tensor_offset(mask),
                                                n_comp, n_tokens, top_k);
 if (!icb_ran) {
 id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
 [enc setComputePipelineState:g_dsv4_topk_mask_pipeline];
 [enc setBytes:&args length:sizeof(args) atIndex:0];
 [enc setBuffer:topkbuf offset:ds4_gpu_tensor_offset(topk) atIndex:1];
 [enc setBuffer:maskbuf offset:ds4_gpu_tensor_offset(mask) atIndex:2];
 [enc dispatchThreadgroups:MTLSizeMake((((NSUInteger)n_comp * n_tokens) + 255u) / 256u, 1, 1)
 threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
 ds4_gpu_end_compute_encoder(cb, enc);

 enc = ds4_gpu_compute_encoder(cb);
 [enc setComputePipelineState:g_dsv4_topk_mask_scatter_pipeline];
 [enc setBytes:&args length:sizeof(args) atIndex:0];
 [enc setBuffer:topkbuf offset:ds4_gpu_tensor_offset(topk) atIndex:1];
 [enc setBuffer:maskbuf offset:ds4_gpu_tensor_offset(mask) atIndex:2];
 [enc dispatchThreadgroups:MTLSizeMake((((NSUInteger)top_k * n_tokens) + 255u) / 256u, 1, 1)
 threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
 ds4_gpu_end_compute_encoder(cb, enc);
 }

 if (!ds4_gpu_finish_command_buffer(cb, owned, "dsv4 top-k mask")) return 0;
 }

 return 1;
}

/* silv 2026-05-28 #796 Increment 3 — unified Q8_0 matmul kernel dispatch.
 *
 * Same shape as F16's kernel_dispatch helper (#796 Increment 2d): one
 * kernel-selection path, two weight-source variants (mmap-tensor +
 * heap-storage). Q8_0-specific details vs F16:
 *   - row_bytes = (in_dim/32) * 34 (per-block FP16 scale + 32 INT8 values)
 *   - matvec uses make_q8_0_mv_args + nsg=8 tweak for out_dim > 65536
 *   - mul_mv_ext fn name uses index 1 (vs F16's 0)
 *   - NAX path requires in_dim % 64 == 0 (vs F16's 32)
 *   - NAX pipeline uses kernel_mul_mm_q8_0_f32_nax_direct_rhs* variants
 *   - default mul_mm uses kernel_mul_mm_q8_0_f32 with bc_inp/bc_out
 *
 * Returns 1 on success, 0 on failure. Caller owns wbuf retention. */
static int ds4_gpu_matmul_q8_0_kernel_dispatch(
 ds4_gpu_tensor *out,
 id<MTLBuffer> wbuf,
 uint64_t inner_offset,
 uint64_t in_dim,
 uint64_t out_dim,
 const ds4_gpu_tensor *x,
 uint64_t n_tok,
 const char *label) {
 id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
 id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
 if (!xbuf || !outbuf) return 0;

 int owned = 0;
 id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
 if (!cb) return 0;

 const uint64_t blocks = in_dim / 32;
 const uint64_t row_bytes = blocks * 34;

 if (n_tok == 1) {
  ds4_gpu_q8_0_matvec_args mv_args = ds4_gpu_make_q8_0_mv_args(in_dim, out_dim);
  ds4_gpu_mv_dispatch mv_dispatch = ds4_gpu_make_q8_0_mv_dispatch();
  if (out_dim > 65536u) mv_dispatch.nsg = 8;
  mv_args.nr0 = mv_dispatch.nr0;
  id<MTLComputePipelineState> pipeline =
   ds4_gpu_get_mul_mv_pipeline(mv_dispatch.function_name, mv_dispatch.nsg);
  if (!pipeline) return 0;

  id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
  [enc setComputePipelineState:pipeline];
  [enc setBytes:&mv_args length:sizeof(mv_args) atIndex:0];
  [enc setBuffer:wbuf offset:(NSUInteger)inner_offset atIndex:1];
  [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
  [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
  [enc setThreadgroupMemoryLength:mv_dispatch.smem atIndex:0];
  [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)out_dim + (NSUInteger)mv_dispatch.nr0 - 1u) / (NSUInteger)mv_dispatch.nr0,
   1,
   1)
   threadsPerThreadgroup:MTLSizeMake(32, (NSUInteger)mv_dispatch.nsg, 1)];
  ds4_gpu_end_compute_encoder(cb, enc);

  if (!ds4_gpu_finish_command_buffer(cb, owned, label ? label : "Q8_0 matvec")) return 0;
  return 1;
 }

 if (n_tok <= 8 && (in_dim % 128u) == 0) {
  const int16_t nsg = 2;
  const int16_t nxpsg = ds4_gpu_mv_ext_nxpsg(in_dim, n_tok);
  const int16_t r1ptg = ds4_gpu_mv_ext_r1ptg(n_tok);
  const char *fn_name = ds4_gpu_mv_ext_name(1, r1ptg);
  id<MTLComputePipelineState> pipeline =
   fn_name ? ds4_gpu_get_mul_mv_ext_pipeline(fn_name, nsg, nxpsg) : nil;
  if (!pipeline) return 0;

  const int16_t nypsg = 32 / nxpsg;
  const uint64_t r0ptg = (uint64_t)nypsg * (uint64_t)nsg;
  ds4_gpu_mul_mv_ext_args args =
   ds4_gpu_make_mv_ext_args(in_dim, out_dim, n_tok, 34, row_bytes);

  id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
  [enc setComputePipelineState:pipeline];
  [enc setBytes:&args length:sizeof(args) atIndex:0];
  [enc setBuffer:wbuf offset:(NSUInteger)inner_offset atIndex:1];
  [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
  [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
  [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)out_dim + (NSUInteger)r0ptg - 1u) / (NSUInteger)r0ptg,
   ((NSUInteger)n_tok + (NSUInteger)r1ptg - 1u) / (NSUInteger)r1ptg,
   1)
   threadsPerThreadgroup:MTLSizeMake(32, (NSUInteger)nsg, 1)];
  ds4_gpu_end_compute_encoder(cb, enc);

  if (!ds4_gpu_finish_command_buffer(cb, owned, label ? label : "Q8_0 mul_mv_ext")) return 0;
  return 1;
 }

 if (ds4_gpu_mpp_available() &&
     n_tok >= 32u &&
     (in_dim % 64u) == 0 &&
     (out_dim % 64u) == 0 &&
     (n_tok % 32u) == 0) {
  uint64_t nax_tile_n = 32u;
  if ((n_tok % 128u) == 0) {
   nax_tile_n = 128u;
  } else if ((n_tok % 64u) == 0) {
   nax_tile_n = 64u;
  }
  const char *nax_fn = nax_tile_n == 128u
   ? "kernel_mul_mm_q8_0_f32_nax_direct_rhs_n128"
   : (nax_tile_n == 64u
    ? "kernel_mul_mm_q8_0_f32_nax_direct_rhs_n64"
    : "kernel_mul_mm_q8_0_f32_nax_direct_rhs");
  id<MTLComputePipelineState> pipeline =
   ds4_gpu_get_mul_mm_pipeline(nax_fn, false, false);
  if (pipeline) {
   ds4_gpu_mul_mm_args args = ds4_gpu_make_mm_args(in_dim, out_dim, n_tok, row_bytes);

   id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
   [enc setComputePipelineState:pipeline];
   [enc setBytes:&args length:sizeof(args) atIndex:0];
   [enc setBuffer:wbuf offset:(NSUInteger)inner_offset atIndex:1];
   [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
   [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
   [enc setThreadgroupMemoryLength:64u * 32u * sizeof(uint16_t) atIndex:0];
   [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)(n_tok / nax_tile_n),
    (NSUInteger)out_dim / 64u,
    1)
    threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
   ds4_gpu_end_compute_encoder(cb, enc);

   if (!ds4_gpu_finish_command_buffer(cb, owned, label ? label : "Q8_0 NAX matmul")) {
    return 0;
   }
   return 1;
  }
  ds4_gpu_warn_mpp_fallback();
 }

 {
  const bool bc_inp = (in_dim % 32u) != 0;
  const bool bc_out = (out_dim % 64u) != 0 || (n_tok % 32u) != 0;
  id<MTLComputePipelineState> pipeline =
   ds4_gpu_get_mul_mm_pipeline("kernel_mul_mm_q8_0_f32", bc_inp, bc_out);
  if (!pipeline) return 0;

  ds4_gpu_mul_mm_args args = ds4_gpu_make_mm_args(in_dim, out_dim, n_tok, row_bytes);

  id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
  [enc setComputePipelineState:pipeline];
  [enc setBytes:&args length:sizeof(args) atIndex:0];
  [enc setBuffer:wbuf offset:(NSUInteger)inner_offset atIndex:1];
  [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
  [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
  [enc setThreadgroupMemoryLength:(bc_out ? 8192u : 6144u) atIndex:0];
  [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)n_tok + 31u) / 32u,
   ((NSUInteger)out_dim + 63u) / 64u,
   1)
   threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
  ds4_gpu_end_compute_encoder(cb, enc);

  if (!ds4_gpu_finish_command_buffer(cb, owned, label ? label : "Q8_0 matmul")) return 0;
 }
 return 1;
}

static int ds4_gpu_matmul_q8_0_legacy_tensor(
 ds4_gpu_tensor *out,
 const void *model_map,
 uint64_t model_size,
 uint64_t weight_offset,
 uint64_t in_dim,
 uint64_t out_dim,
 const ds4_gpu_tensor *x,
 uint64_t n_tok) {
 if (!g_initialized && !ds4_gpu_init()) return 0;
 if ((in_dim & 31u) != 0 ||
 in_dim > UINT32_MAX || out_dim > UINT32_MAX || n_tok > UINT32_MAX) {
 return 0;
 }

 @autoreleasepool {
 id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
 id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
 const uint64_t x_bytes = n_tok * in_dim * sizeof(float);
 const uint64_t out_bytes = n_tok * out_dim * sizeof(float);
 if (!xbuf || !outbuf ||
 ds4_gpu_tensor_bytes(x) < x_bytes ||
 ds4_gpu_tensor_bytes(out) < out_bytes) {
 fprintf(stderr, "ds4: Metal Q8_0 tensor matmul received undersized activation buffers\n");
 return 0;
 }

 const uint64_t blocks = in_dim / 32;
 const uint64_t row_bytes = blocks * 34;
 const uint64_t weight_bytes = out_dim * row_bytes;
 if (!ds4_gpu_range_resolvable(model_map, model_size, weight_offset, weight_bytes)) {
 fprintf(stderr, "ds4: Metal Q8_0 tensor matmul range is outside the mapped model\n");
 return 0;
 }

 uint64_t inner_offset = 0;
 id<MTLBuffer> wbuf = ds4_gpu_wrap_model_range(model_map, model_size, weight_offset, weight_bytes, &inner_offset);
 if (!wbuf) {
 return 0;
 }

 return ds4_gpu_matmul_q8_0_kernel_dispatch(out, wbuf, inner_offset, in_dim, out_dim, x, n_tok, "Q8_0 tensor matmul");
 }
}

/* silv 2026-05-28 #796 Increment 3 — heap-storage-aware Q8_0 matmul.
 *
 * Parallel to ds4_gpu_matmul_f16_storage. Consumes a pre-wrapped MTLBuffer
 * (storage.metal_buffer from Phase 2b override-fill) instead of doing
 * ds4_gpu_wrap_model_range. All 4 kernel paths (matvec/mul_mv_ext/NAX/
 * mul_mm) available via the unified kernel_dispatch helper.
 *
 * weight_buf: void* opaque (id<MTLBuffer> across the ObjC boundary). Must
 *   contain the entire Q8_0 weight matrix at offset 0 — the heap wrap from
 *   posix_memalign + wrap_heap_bytes covers the full allocation.
 *
 * Returns 1 on success, 0 on failure. */
int ds4_gpu_matmul_q8_0_storage(
 ds4_gpu_tensor *out,
 void *weight_buf,
 uint64_t in_dim,
 uint64_t out_dim,
 const ds4_gpu_tensor *x,
 uint64_t n_tok) {
 if (!g_initialized && !ds4_gpu_init()) return 0;
 if (!weight_buf || !out || !x) return 0;
 if ((in_dim & 31u) != 0 ||
     in_dim > UINT32_MAX || out_dim > UINT32_MAX || n_tok > UINT32_MAX) {
  return 0;
 }

 @autoreleasepool {
  id<MTLBuffer> wbuf = (__bridge id<MTLBuffer>)weight_buf;
  id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
  id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
  const uint64_t x_bytes = n_tok * in_dim * sizeof(float);
  const uint64_t out_bytes = n_tok * out_dim * sizeof(float);
  if (!xbuf || !outbuf ||
      ds4_gpu_tensor_bytes(x) < x_bytes ||
      ds4_gpu_tensor_bytes(out) < out_bytes) {
   fprintf(stderr, "ds4: matmul_q8_0_storage received undersized activation buffers\n");
   return 0;
  }
  const uint64_t blocks = in_dim / 32;
  const uint64_t row_bytes = blocks * 34;
  const uint64_t weight_bytes = out_dim * row_bytes;
  if ((uint64_t)wbuf.length < weight_bytes) {
   fprintf(stderr,
           "ds4: matmul_q8_0_storage weight buffer too small (%llu < %llu)\n",
           (unsigned long long)wbuf.length,
           (unsigned long long)weight_bytes);
   return 0;
  }
  /* heap wrap is exactly the weight matrix → inner_offset = 0 */
  return ds4_gpu_matmul_q8_0_kernel_dispatch(out, wbuf, 0, in_dim, out_dim, x, n_tok, "Q8_0 storage matmul");
 }
}

/* === ICB dense-path (silv 2026-05-29 task #822) ===========================================
 * Route the fixed-shape dense Q8_0 MATVEC (n_tok==1: q_a/q_b/kv/attn_o/shared gate/up/down)
 * through ds4_icb_slot record→replay to kill ~252 per-token re-encodes (0.52 t/s is dispatch-
 * bound, ~600x below the bandwidth ceiling). Mirrors the WORKING g_vqb2_decode_matmul_slot.
 * CRUX: ICB indirect commands cannot use setBytes — so mv_args lives in a per-slot MTLBuffer
 * at binding 0 (the mul_mv kernel reads [[buffer(0)]] identically whether fed by setBytes or a
 * buffer, so NO kernel change). Signature is token-stable (fixed weight buf, reused scratch
 * x/out, fixed grid/tg/smem/args per (layer,role)) ⇒ replay hits every token after the first. */
#ifndef DS4_DENSE_ICB_SLOTS
#define DS4_DENSE_ICB_SLOTS 320  /* 43 layers × ~6 dense GEMVs + headroom; >128 ⇒ its own ICB */
#endif
static ds4_icb_slot_t g_dense_matvec_slot;
static id<MTLBuffer>  g_dense_matvec_uniforms = nil;  /* 256B/slot, holds mv_args (binding 0) */

/* Record→replay one dense Q8_0 matvec at slot_idx. caller supplies the decode cb. Returns 1 ok. */
static int ds4_gpu_matmul_q8_0_matvec_icb(
        id<MTLCommandBuffer> cb, uint32_t slot_idx,
        id<MTLBuffer> wbuf, uint64_t inner_offset,
        uint64_t in_dim, uint64_t out_dim,
        const ds4_gpu_tensor *x, ds4_gpu_tensor *out) {
 if (slot_idx >= DS4_DENSE_ICB_SLOTS) return 0;
 id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
 id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
 if (!cb || !wbuf || !xbuf || !outbuf) return 0;

 ds4_gpu_q8_0_matvec_args mv_args = ds4_gpu_make_q8_0_mv_args(in_dim, out_dim);
 ds4_gpu_mv_dispatch mv_dispatch = ds4_gpu_make_q8_0_mv_dispatch();
 if (out_dim > 65536u) mv_dispatch.nsg = 8;
 mv_args.nr0 = mv_dispatch.nr0;
 id<MTLComputePipelineState> pipeline =
  ds4_gpu_get_mul_mv_pipeline_icb(mv_dispatch.function_name, mv_dispatch.nsg);
 if (!pipeline) { fprintf(stderr, "icb-dense: pipeline nil (%s nsg=%d)\n", mv_dispatch.function_name, (int)mv_dispatch.nsg); return 0; }

 if (!g_dense_matvec_slot.icb &&
     !ds4_icb_slot_acquire(&g_dense_matvec_slot, (NSUInteger)DS4_DENSE_ICB_SLOTS, 4)) {
  fprintf(stderr, "icb-dense: slot_acquire failed\n"); return 0;
 }
 if (!g_dense_matvec_uniforms) {
  g_dense_matvec_uniforms = [g_device newBufferWithLength:(NSUInteger)(256u * DS4_DENSE_ICB_SLOTS)
                                                  options:MTLResourceStorageModeShared];
  if (!g_dense_matvec_uniforms) { fprintf(stderr, "icb-dense: uniforms alloc failed\n"); return 0; }
 }
 NSUInteger args_off = (NSUInteger)slot_idx * 256u;  /* args-as-buffer, NOT setBytes (ICB rule) */
 memcpy((char *)g_dense_matvec_uniforms.contents + args_off, &mv_args, sizeof(mv_args));

 __unsafe_unretained id<MTLBuffer> bufs[4] = { g_dense_matvec_uniforms, wbuf, xbuf, outbuf };
 NSUInteger offs[4] = { args_off, (NSUInteger)inner_offset,
                        ds4_gpu_tensor_offset(x), ds4_gpu_tensor_offset(out) };
 uint64_t extras[2] = { in_dim, out_dim };
 if (!ds4_icb_slot_record_command(&g_dense_matvec_slot, (NSUInteger)slot_idx, pipeline,
         bufs, offs, 4,
         MTLSizeMake(((NSUInteger)out_dim + (NSUInteger)mv_dispatch.nr0 - 1u) / (NSUInteger)mv_dispatch.nr0, 1, 1),
         MTLSizeMake(32, (NSUInteger)mv_dispatch.nsg, 1),
         (uint32_t)mv_dispatch.smem, extras, 2)) {
  return 0;
 }
 id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
 [enc useResource:g_dense_matvec_uniforms usage:MTLResourceUsageRead];
 [enc useResource:wbuf   usage:MTLResourceUsageRead];
 [enc useResource:xbuf   usage:MTLResourceUsageRead];
 [enc useResource:outbuf usage:MTLResourceUsageRead | MTLResourceUsageWrite];
 ds4_icb_slot_execute(&g_dense_matvec_slot, enc, (NSUInteger)slot_idx, 1);
 ds4_gpu_end_compute_encoder(cb, enc);
 return 1;
}

/* Increment 1b canary (task #822): ICB-replay must be BIT-IDENTICAL to direct dispatch for the
 * same (pipeline, weight, x, args) — only the dispatch mechanism differs, so the math is identical.
 * This de-risks the production wiring (increment 2): if max|direct-icb|==0, replacing direct dispatch
 * with the ICB path in decode cannot change output. Returns 1 on bit-exact PASS. */
int ds4_gpu_dense_matvec_icb_canary(uint32_t M, uint32_t N) {
 if (!g_initialized && !ds4_gpu_init()) return 0;
 if (M == 0 || N == 0 || (N % 32u) != 0) return 0;
 @autoreleasepool {
  fprintf(stderr, "ds4: ICB-dense canary START M=%u N=%u\n", M, N);
  const uint64_t blocks = N / 32u, row_bytes = blocks * 34u, wbytes = (uint64_t)M * row_bytes;
  const size_t page = (size_t)getpagesize();
  const size_t padded = (size_t)(((uint64_t)wbytes + page - 1u) & ~(uint64_t)(page - 1u));
  void *host_w = NULL;
  if (posix_memalign(&host_w, page, padded) != 0 || !host_w) return 0;
  uint8_t *q8 = (uint8_t *)host_w;
  for (uint32_t r = 0; r < M; r++) for (uint64_t b = 0; b < blocks; b++) {
   uint8_t *blk = q8 + (uint64_t)r * row_bytes + b * 34u;
   _Float16 hs = (_Float16)0.05f; memcpy(blk, &hs, 2);
   for (int k = 0; k < 32; k++) blk[2 + k] = (uint8_t)(int8_t)((int)((r * 7u + b * 3u + (uint32_t)k) % 255u) - 128);
  }
  void *wbuf_v = ds4_gpu_wrap_heap_bytes(host_w, (uint64_t)padded);
  if (!wbuf_v) { free(host_w); return 0; }
  id<MTLBuffer> wbuf = (__bridge id<MTLBuffer>)wbuf_v;
  ds4_gpu_tensor *x  = ds4_gpu_tensor_alloc((uint64_t)N * sizeof(float));
  ds4_gpu_tensor *od = ds4_gpu_tensor_alloc((uint64_t)M * sizeof(float));
  ds4_gpu_tensor *oi = ds4_gpu_tensor_alloc((uint64_t)M * sizeof(float));
  float *hx = (float *)calloc(N, sizeof(float));
  float *hd = (float *)calloc(M, sizeof(float));
  float *hi = (float *)calloc(M, sizeof(float));
  int rc = 0;
  if (x && od && oi && hx && hd && hi) {
   for (uint32_t c = 0; c < N; c++) hx[c] = (float)((int)(c % 13u)) * 0.07f - 0.3f;
   if (ds4_gpu_tensor_write(x, 0, hx, (size_t)N * sizeof(float)) > 0) {
    int ok1 = ds4_gpu_matmul_q8_0_kernel_dispatch(od, wbuf, 0, N, M, x, 1, "icb canary direct");
    int owned = 0;
    id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
    int ok2 = (cb != nil) && ds4_gpu_matmul_q8_0_matvec_icb(cb, 0, wbuf, 0, N, M, x, oi);
    if (ok2) ok2 = ds4_gpu_finish_command_buffer(cb, owned, "icb canary replay");
    fprintf(stderr, "ds4: ICB-dense canary ok_direct=%d ok_icb=%d cb=%p\n", ok1, ok2, (__bridge void *)cb);
    if (ok1 && ok2 &&
        ds4_gpu_tensor_read(od, 0, hd, (size_t)M * sizeof(float)) > 0 &&
        ds4_gpu_tensor_read(oi, 0, hi, (size_t)M * sizeof(float)) > 0) {
     int mism = 0; float maxd = 0.0f;
     for (uint32_t r = 0; r < M; r++) { float d = fabsf(hd[r] - hi[r]); if (d > maxd) maxd = d; if (d != 0.0f) mism++; }
     fprintf(stderr, "ds4: ICB-dense canary M=%u N=%u  max|direct-icb|=%.3e  mism=%d/%u  %s\n",
             M, N, (double)maxd, mism, M, mism == 0 ? "BIT-EXACT PASS" : "DIVERGE");
     rc = (mism == 0);
    }
   }
  }
  ds4_gpu_tensor_free(x); ds4_gpu_tensor_free(od); ds4_gpu_tensor_free(oi);
  free(hx); free(hd); free(hi);
  return rc;
 }
}

/* Increment 1c speed bench (task #822): does ICB record→replay actually REDUCE
 * the per-forward dispatch cost of the dense GEMV batch? The ledger's "dispatch
 * -bound" diagnosis predicts YES. A/B times n_iter forwards, each issuing n_gemv
 * dense matvecs inside ONE begin/end_commands batch — DIRECT (re-encode every
 * forward) vs ICB (iter>=2 = cached replay, no re-encode). Reports ms/forward +
 * speedup. No model load — isolates the dense-GEMV dispatch lever from MoE/
 * attention/paging so the lever can be refuted cheaply before production wiring. */
int ds4_gpu_dense_matvec_icb_bench(uint32_t M, uint32_t N, uint32_t n_gemv, uint32_t n_iter) {
 if (!g_initialized && !ds4_gpu_init()) return 0;
 if (M == 0 || N == 0 || (N % 32u) != 0) return 0;
 if (n_gemv == 0 || n_gemv > (uint32_t)DS4_DENSE_ICB_SLOTS) n_gemv = (uint32_t)DS4_DENSE_ICB_SLOTS;
 if (n_iter == 0) n_iter = 20;
 @autoreleasepool {
  fprintf(stderr, "ds4: ICB-dense BENCH M=%u N=%u n_gemv=%u n_iter=%u\n", M, N, n_gemv, n_iter);
  const uint64_t blocks = N / 32u, row_bytes = blocks * 34u, wbytes = (uint64_t)M * row_bytes;
  const size_t page = (size_t)getpagesize();
  const size_t padded = (size_t)(((uint64_t)wbytes + page - 1u) & ~(uint64_t)(page - 1u));
  void *host_w = NULL;
  if (posix_memalign(&host_w, page, padded) != 0 || !host_w) return 0;
  uint8_t *q8 = (uint8_t *)host_w;
  for (uint32_t r = 0; r < M; r++) for (uint64_t b = 0; b < blocks; b++) {
   uint8_t *blk = q8 + (uint64_t)r * row_bytes + b * 34u;
   _Float16 hs = (_Float16)0.05f; memcpy(blk, &hs, 2);
   for (int k = 0; k < 32; k++) blk[2 + k] = (uint8_t)(int8_t)((int)((r + b + (uint32_t)k) % 255u) - 128);
  }
  void *wbuf_v = ds4_gpu_wrap_heap_bytes(host_w, (uint64_t)padded);
  if (!wbuf_v) { free(host_w); return 0; }
  id<MTLBuffer> wbuf = (__bridge id<MTLBuffer>)wbuf_v;
  ds4_gpu_tensor *x  = ds4_gpu_tensor_alloc((uint64_t)N * sizeof(float));
  ds4_gpu_tensor *od = ds4_gpu_tensor_alloc((uint64_t)M * sizeof(float));
  int rc = 0;
  if (x && od) {
   float *hx = (float *)calloc(N, sizeof(float));
   if (hx) { for (uint32_t c = 0; c < N; c++) hx[c] = (float)((int)(c % 13u)) * 0.07f - 0.3f;
             (void)ds4_gpu_tensor_write(x, 0, hx, (size_t)N * sizeof(float)); free(hx); }
   /* warm-up both paths: builds pipelines + records all n_gemv ICB slots once */
   for (int w2 = 0; w2 < 2; w2++) {
    ds4_gpu_begin_commands();
    int owned = 0; id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
    for (uint32_t g = 0; g < n_gemv; g++) {
     if (w2 == 0) ds4_gpu_matmul_q8_0_kernel_dispatch(od, wbuf, 0, N, M, x, 1, "bench-warm");
     else         ds4_gpu_matmul_q8_0_matvec_icb(cb, g, wbuf, 0, N, M, x, od);
    }
    ds4_gpu_end_commands();
   }
   /* DIRECT: re-encode all n_gemv dispatches every forward */
   double t0 = ds4_gpu_now_ms();
   for (uint32_t it = 0; it < n_iter; it++) {
    ds4_gpu_begin_commands();
    for (uint32_t g = 0; g < n_gemv; g++)
     ds4_gpu_matmul_q8_0_kernel_dispatch(od, wbuf, 0, N, M, x, 1, "bench-direct");
    ds4_gpu_end_commands();
   }
   const double t_direct = ds4_gpu_now_ms() - t0;
   /* ICB: cached replay (no re-encode) every forward */
   t0 = ds4_gpu_now_ms();
   for (uint32_t it = 0; it < n_iter; it++) {
    ds4_gpu_begin_commands();
    int owned = 0; id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
    for (uint32_t g = 0; g < n_gemv; g++)
     ds4_gpu_matmul_q8_0_matvec_icb(cb, g, wbuf, 0, N, M, x, od);
    ds4_gpu_end_commands();
   }
   const double t_icb = ds4_gpu_now_ms() - t0;
   const double per_direct = t_direct / (double)n_iter, per_icb = t_icb / (double)n_iter;
   fprintf(stderr,
           "ds4: ICB-dense BENCH direct=%.3f ms/fwd  icb=%.3f ms/fwd  speedup=%.2fx  "
           "(%u GEMV/fwd: %.0f vs %.0f GEMV/s)\n",
           per_direct, per_icb, per_icb > 0.0 ? per_direct / per_icb : 0.0, n_gemv,
           per_direct > 0.0 ? (double)n_gemv / (per_direct / 1000.0) : 0.0,
           per_icb    > 0.0 ? (double)n_gemv / (per_icb    / 1000.0) : 0.0);
   rc = 1;
  }
  ds4_gpu_tensor_free(x); ds4_gpu_tensor_free(od);
  return rc;
 }
}

int ds4_gpu_matmul_q8_0_tensor(
 ds4_gpu_tensor *out,
 const void *model_map,
 uint64_t model_size,
 uint64_t weight_offset,
 uint64_t in_dim,
 uint64_t out_dim,
 const ds4_gpu_tensor *x,
 uint64_t n_tok) {
 if (!g_initialized && !ds4_gpu_init()) return 0;
 if ((in_dim & 31u) != 0 ||
 in_dim > UINT32_MAX || out_dim > UINT32_MAX || n_tok > UINT32_MAX) {
 return 0;
 }

 const int profile_requested =
 n_tok > 8u && ds4_gpu_env_bool("DS4_METAL_Q8_PREFILL_PROFILE") > 0;
 int profile_prefill = 0;
 int split_batch_for_profile = 0;
 const char *profile_label = NULL;
 char profile_label_buf[128];
 char profile_fallback[128];
 if (profile_requested) {
 snprintf(profile_fallback, sizeof(profile_fallback),
 "q8 weight_off=%llu in=%llu out=%llu tok=%llu",
 (unsigned long long)weight_offset,
 (unsigned long long)in_dim,
 (unsigned long long)out_dim,
 (unsigned long long)n_tok);
 snprintf(profile_label_buf, sizeof(profile_label_buf), "%s", profile_fallback);
 profile_label = profile_label_buf;
 const char *profile_filter = getenv("DS4_METAL_Q8_PREFILL_PROFILE_FILTER");
 profile_prefill =
 profile_requested &&
 (!profile_filter || !profile_filter[0] ||
 strstr(profile_label, profile_filter) != NULL);
 }
 if (profile_prefill) {
 if (g_batch_cb) {
 if (ds4_gpu_end_commands() == 0 || ds4_gpu_begin_commands() == 0) {
 return 0;
 }
 split_batch_for_profile = 1;
 }
 }

 const double profile_t0 = profile_prefill ? ds4_gpu_now_ms() : 0.0;
 int ok = ds4_gpu_matmul_q8_0_legacy_tensor(out, model_map, model_size,
 weight_offset, in_dim, out_dim,
 x, n_tok);
 if (profile_prefill) {
 if (split_batch_for_profile && ds4_gpu_end_commands() == 0) {
 ok = 0;
 }
 const double elapsed_ms = ds4_gpu_now_ms() - profile_t0;
 fprintf(stderr,
 "ds4: Metal Q8_0 prefill profile %s in=%llu out=%llu tok=%llu %.3f ms\n",
 profile_label ? profile_label : profile_fallback,
 (unsigned long long)in_dim,
 (unsigned long long)out_dim,
 (unsigned long long)n_tok,
 elapsed_ms);
 if (split_batch_for_profile && ds4_gpu_begin_commands() == 0) {
 ok = 0;
 }
 }
 return ok;
}

int ds4_gpu_shared_gate_up_swiglu_q8_0_tensor(
 ds4_gpu_tensor *gate,
 ds4_gpu_tensor *up,
 ds4_gpu_tensor *mid,
 const void *model_map,
 uint64_t model_size,
 uint64_t gate_offset,
 uint64_t up_offset,
 uint64_t in_dim,
 uint64_t out_dim,
 const ds4_gpu_tensor *x,
 float clamp) {
 if (!g_initialized && !ds4_gpu_init()) return 0;
 if (!gate || !up || !mid || !x || !model_map ||
 (in_dim & 31u) != 0 ||
 in_dim > UINT32_MAX || out_dim > UINT32_MAX ||
 !isfinite(clamp) || clamp < 0.0f) {
 return 0;
 }

 @autoreleasepool {
 id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
 id<MTLBuffer> gatebuf = ds4_gpu_tensor_buffer(gate);
 id<MTLBuffer> upbuf = ds4_gpu_tensor_buffer(up);
 id<MTLBuffer> midbuf = ds4_gpu_tensor_buffer(mid);
 const uint64_t x_bytes = in_dim * sizeof(float);
 const uint64_t out_bytes = out_dim * sizeof(float);
 if (!xbuf || !gatebuf || !upbuf || !midbuf ||
 ds4_gpu_tensor_bytes(x) < x_bytes ||
 ds4_gpu_tensor_bytes(gate) < out_bytes ||
 ds4_gpu_tensor_bytes(up) < out_bytes ||
 ds4_gpu_tensor_bytes(mid) < out_bytes) {
 fprintf(stderr, "ds4: Metal shared expert fused gate/up received undersized activation buffers\n");
 return 0;
 }

 const uint64_t blocks = in_dim / 32;
 const uint64_t row_bytes = blocks * 34;
 const uint64_t weight_bytes = out_dim * row_bytes;
 if (!ds4_gpu_range_resolvable(model_map, model_size, gate_offset, weight_bytes) ||

     !ds4_gpu_range_resolvable(model_map, model_size, up_offset, weight_bytes)) {
 fprintf(stderr, "ds4: Metal shared expert fused gate/up range is outside the mapped model\n");
 return 0;
 }

 uint64_t gate_inner = 0;
 uint64_t up_inner = 0;
 id<MTLBuffer> gate_wbuf =
 ds4_gpu_wrap_model_range(model_map, model_size, gate_offset, weight_bytes, &gate_inner);
 id<MTLBuffer> up_wbuf =
 ds4_gpu_wrap_model_range(model_map, model_size, up_offset, weight_bytes, &up_inner);
 if (!gate_wbuf || !up_wbuf) return 0;

 ds4_gpu_q8_0_matvec_args args = ds4_gpu_make_q8_0_mv_args(in_dim, out_dim);
 ds4_gpu_mv_dispatch mv_dispatch = ds4_gpu_make_q8_0_mv_dispatch();
 args.nr0 = mv_dispatch.nr0;
 id<MTLComputePipelineState> pipeline =
 ds4_gpu_get_mul_mv_pipeline("kernel_dsv4_shared_gate_up_swiglu_q8_0",
 mv_dispatch.nsg);
 if (!pipeline) return 0;

 int owned = 0;
 id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
 if (!cb) return 0;

 id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
 [enc setComputePipelineState:pipeline];
 [enc setBytes:&args length:sizeof(args) atIndex:0];
 [enc setBuffer:gate_wbuf offset:(NSUInteger)gate_inner atIndex:1];
 [enc setBuffer:up_wbuf offset:(NSUInteger)up_inner atIndex:2];
 [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:3];
 [enc setBuffer:gatebuf offset:ds4_gpu_tensor_offset(gate) atIndex:4];
 [enc setBuffer:upbuf offset:ds4_gpu_tensor_offset(up) atIndex:5];
 [enc setBuffer:midbuf offset:ds4_gpu_tensor_offset(mid) atIndex:6];
 [enc setBytes:&clamp length:sizeof(clamp) atIndex:7];
 [enc setThreadgroupMemoryLength:2u * mv_dispatch.smem atIndex:0];
 [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)out_dim + (NSUInteger)mv_dispatch.nr0 - 1u) /
 (NSUInteger)mv_dispatch.nr0,
 1,
 1)
 threadsPerThreadgroup:MTLSizeMake(32, (NSUInteger)mv_dispatch.nsg, 1)];
 ds4_gpu_end_compute_encoder(cb, enc);

 if (!ds4_gpu_finish_command_buffer(cb, owned, "shared expert fused gate/up")) {
 return 0;
 }
 }

 return 1;
}

/* silv 2026-05-28 #796 Increment 2d — unified F16 matmul kernel dispatch.
 *
 * Inner kernel selection + encode + finish, given an already-resolved
 * weight buffer + offset. Used by BOTH ds4_gpu_matmul_f16_tensor (mmap
 * weight source) AND ds4_gpu_matmul_f16_storage (heap weight source) so
 * the kernel-selection logic exists exactly once in the codebase.
 *
 * Engineer-roster motivation:
 *   Linus:   one kernel path, two ways to source the buffer
 *   Carmack: if mmap and heap variants drift, future bug fixes diverge
 *   Knuth:   the algorithm and the data source are separate concerns
 *   DJB:     no dead-code paths; each branch tested in both variants
 *
 * 4 kernel paths:
 *   n_tok==1                                 → matvec
 *   n_tok<=8, in_dim%128==0                  → mul_mv_ext (small batch)
 *   mpp_available, n_tok>=32, special align  → NAX direct-RHS
 *   default                                  → mul_mm with bc_inp/bc_out
 *
 * Returns 1 on success, 0 on failure. Caller owns wbuf retention. */
static int ds4_gpu_matmul_f16_kernel_dispatch(
 ds4_gpu_tensor *out,
 id<MTLBuffer> wbuf,
 uint64_t inner_offset,
 uint64_t in_dim,
 uint64_t out_dim,
 const ds4_gpu_tensor *x,
 uint64_t n_tok,
 const char *label) {
 id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
 id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
 if (!xbuf || !outbuf) return 0;

 int owned = 0;
 id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
 if (!cb) return 0;

 const uint64_t row_bytes = in_dim * sizeof(uint16_t);

 if (n_tok == 1) {
  ds4_gpu_f16_matvec_args mv_args = ds4_gpu_make_f16_mv_args(in_dim, out_dim);
  ds4_gpu_mv_dispatch mv_dispatch = ds4_gpu_make_plain_mv_dispatch(in_dim, 0);
  if (!g_quality_mode && (out_dim == 512u || out_dim == 1024u) && in_dim >= 4096u) {
   mv_dispatch.nr0 = 4;
   mv_dispatch.smem = 32u * 4u * sizeof(float);
  }
  mv_args.nr0 = mv_dispatch.nr0;
  id<MTLComputePipelineState> pipeline =
   ds4_gpu_get_mul_mv_pipeline(mv_dispatch.function_name, mv_dispatch.nsg);
  if (!pipeline) return 0;

  id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
  [enc setComputePipelineState:pipeline];
  [enc setBytes:&mv_args length:sizeof(mv_args) atIndex:0];
  [enc setBuffer:wbuf offset:(NSUInteger)inner_offset atIndex:1];
  [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
  [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
  if (mv_dispatch.smem) {
   [enc setThreadgroupMemoryLength:mv_dispatch.smem atIndex:0];
  }
  [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)out_dim + (NSUInteger)mv_dispatch.nr0 - 1u) / (NSUInteger)mv_dispatch.nr0,
   1,
   1)
   threadsPerThreadgroup:MTLSizeMake(32, (NSUInteger)mv_dispatch.nsg, 1)];
  ds4_gpu_end_compute_encoder(cb, enc);

  if (!ds4_gpu_finish_command_buffer(cb, owned, label ? label : "F16 matvec")) return 0;
  return 1;
 }

 if (n_tok <= 8 && (in_dim % 128u) == 0) {
  const int16_t nsg = 2;
  const int16_t nxpsg = ds4_gpu_mv_ext_nxpsg(in_dim, n_tok);
  const int16_t r1ptg = ds4_gpu_mv_ext_r1ptg(n_tok);
  const char *fn_name = ds4_gpu_mv_ext_name(0, r1ptg);
  id<MTLComputePipelineState> pipeline =
   fn_name ? ds4_gpu_get_mul_mv_ext_pipeline(fn_name, nsg, nxpsg) : nil;
  if (!pipeline) return 0;

  const int16_t nypsg = 32 / nxpsg;
  const uint64_t r0ptg = (uint64_t)nypsg * (uint64_t)nsg;
  ds4_gpu_mul_mv_ext_args args =
   ds4_gpu_make_mv_ext_args(in_dim, out_dim, n_tok, sizeof(uint16_t), row_bytes);

  id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
  [enc setComputePipelineState:pipeline];
  [enc setBytes:&args length:sizeof(args) atIndex:0];
  [enc setBuffer:wbuf offset:(NSUInteger)inner_offset atIndex:1];
  [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
  [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
  [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)out_dim + (NSUInteger)r0ptg - 1u) / (NSUInteger)r0ptg,
   ((NSUInteger)n_tok + (NSUInteger)r1ptg - 1u) / (NSUInteger)r1ptg,
   1)
   threadsPerThreadgroup:MTLSizeMake(32, (NSUInteger)nsg, 1)];
  ds4_gpu_end_compute_encoder(cb, enc);

  if (!ds4_gpu_finish_command_buffer(cb, owned, label ? label : "F16 mul_mv_ext")) return 0;
  return 1;
 }

 if (ds4_gpu_mpp_available() &&
     n_tok >= 32u &&
     (in_dim % 32u) == 0 &&
     (out_dim % 64u) == 0 &&
     (n_tok % 32u) == 0) {
  uint64_t nax_tile_n = 32u;
  if ((n_tok % 128u) == 0) {
   nax_tile_n = 128u;
  } else if ((n_tok % 64u) == 0) {
   nax_tile_n = 64u;
  }
  const char *nax_fn = nax_tile_n == 128u
   ? "kernel_mul_mm_f16_f32_mpp_direct_rhs_n128"
   : (nax_tile_n == 64u
    ? "kernel_mul_mm_f16_f32_mpp_direct_rhs_n64"
    : "kernel_mul_mm_f16_f32_mpp_direct_rhs");
  id<MTLComputePipelineState> pipeline =
   ds4_gpu_get_mul_mm_pipeline(nax_fn, false, false);
  if (pipeline) {
   ds4_gpu_mul_mm_args args = ds4_gpu_make_mm_args(in_dim, out_dim, n_tok, row_bytes);

   id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
   [enc setComputePipelineState:pipeline];
   [enc setBytes:&args length:sizeof(args) atIndex:0];
   [enc setBuffer:wbuf offset:(NSUInteger)inner_offset atIndex:1];
   [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
   [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
   [enc setThreadgroupMemoryLength:64u * 32u * sizeof(uint16_t) atIndex:0];
   [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)(n_tok / nax_tile_n),
    (NSUInteger)out_dim / 64u,
    1)
    threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
   ds4_gpu_end_compute_encoder(cb, enc);

   if (!ds4_gpu_finish_command_buffer(cb, owned, label ? label : "F16 NAX matmul")) {
    return 0;
   }
   return 1;
  }
  ds4_gpu_warn_mpp_fallback();
 }

 {
  const bool bc_inp = (in_dim % 32u) != 0;
  const bool bc_out = (out_dim % 64u) != 0 || (n_tok % 32u) != 0;
  id<MTLComputePipelineState> pipeline =
   ds4_gpu_get_mul_mm_pipeline("kernel_mul_mm_f16_f32", bc_inp, bc_out);
  if (!pipeline) return 0;

  ds4_gpu_mul_mm_args args = ds4_gpu_make_mm_args(in_dim, out_dim, n_tok, row_bytes);

  id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
  [enc setComputePipelineState:pipeline];
  [enc setBytes:&args length:sizeof(args) atIndex:0];
  [enc setBuffer:wbuf offset:(NSUInteger)inner_offset atIndex:1];
  [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
  [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
  [enc setThreadgroupMemoryLength:(bc_out ? 8192u : 6144u) atIndex:0];
  [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)n_tok + 31u) / 32u,
   ((NSUInteger)out_dim + 63u) / 64u,
   1)
   threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
  ds4_gpu_end_compute_encoder(cb, enc);

  if (!ds4_gpu_finish_command_buffer(cb, owned, label ? label : "F16 matmul")) return 0;
 }
 return 1;
}

int ds4_gpu_matmul_f16_tensor(
 ds4_gpu_tensor *out,
 const void *model_map,
 uint64_t model_size,
 uint64_t weight_offset,
 uint64_t in_dim,
 uint64_t out_dim,
 const ds4_gpu_tensor *x,
 uint64_t n_tok) {
 if (!g_initialized && !ds4_gpu_init()) return 0;
 if (in_dim > UINT32_MAX || out_dim > UINT32_MAX || n_tok > UINT32_MAX) return 0;

 @autoreleasepool {
 id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
 id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
 const uint64_t x_bytes = n_tok * in_dim * sizeof(float);
 const uint64_t out_bytes = n_tok * out_dim * sizeof(float);
 if (!xbuf || !outbuf ||
 ds4_gpu_tensor_bytes(x) < x_bytes ||
 ds4_gpu_tensor_bytes(out) < out_bytes) {
 fprintf(stderr, "ds4: Metal F16 tensor matmul received undersized activation buffers\n");
 return 0;
 }

 const uint64_t row_bytes = in_dim * sizeof(uint16_t);
 const uint64_t weight_bytes = row_bytes * out_dim;
 if (!ds4_gpu_range_resolvable(model_map, model_size, weight_offset, weight_bytes)) {
 fprintf(stderr, "ds4: Metal F16 tensor matmul range is outside the mapped model\n");
 return 0;
 }

 uint64_t inner_offset = 0;
 id<MTLBuffer> wbuf = ds4_gpu_wrap_model_range(model_map, model_size, weight_offset, weight_bytes, &inner_offset);
 if (!wbuf) return 0;

 return ds4_gpu_matmul_f16_kernel_dispatch(out, wbuf, inner_offset, in_dim, out_dim, x, n_tok, "F16 tensor matmul");
 }
}

