  float freq_scale;
  float ext_factor;
  float attn_factor;
  float beta_fast;
  float beta_slow;
 } args = {
  .n_tok = n_tok,
  .n_head = n_head,
  .head_dim = head_dim,
  .n_rot = n_rot,
  .pos0 = pos0,
  .n_ctx_orig = n_ctx_orig,
  .eps = eps,
  .freq_base = freq_base,
  .freq_scale = freq_scale,
  .ext_factor = ext_factor,
