 score_offset,
 score_nb0,
 score_nb1,
 score_nb2,
 n_rows,
 head_dim);
 }

 ds4_gpu_dsv4_softmax_pool_args args = {
 .ne00 = (int64_t)n_rows,
 .ne01 = (int64_t)head_dim,
 .ne02 = (int64_t)n_comp,
 .nb00 = kv_nb0,
 .nb01 = kv_nb1,
 .nb02 = kv_nb2,
 .nb10 = score_nb0,
 .nb11 = score_nb1,
 .nb12 = score_nb2,
 .ne0 = (int64_t)head_dim,
 .ne1 = (int64_t)n_comp,
 .nb0 = sizeof(float),
 .nb1 = (uint64_t)head_dim * sizeof(float),
 };
