 g_compressor_pool_score_buffer,
 0,
 head_dim,
 ratio,
 1,
 src_row_stride,
 (uint64_t)ratio * src_row_stride,
 dst_row_stride,
 dst_plane_stride);
 }
 if (ok) {
 ok = ds4_gpu_encode_cpy_f32_f32_3d(cb,
 kvbuf,
 ds4_gpu_tensor_offset(kv) +
 (NSUInteger)head_dim * sizeof(float),
 g_compressor_pool_kv_buffer,
 (NSUInteger)4u * head_dim * sizeof(float),
 head_dim,
 ratio,
 n_comp,
 src_row_stride,
 src_plane_stride,
 dst_row_stride,
 dst_plane_stride) &&
 ds4_gpu_encode_cpy_f32_f32_3d(cb,
 g_compressor_store_score_buffer,
 (NSUInteger)head_dim * sizeof(float),
 g_compressor_pool_score_buffer,
 (NSUInteger)4u * head_dim * sizeof(float),
 head_dim,
 ratio,
 n_comp,
 src_row_stride,
 src_plane_stride,
 dst_row_stride,
 dst_plane_stride);
 }
 if (ok && n_comp > 1u) {
 ok = ds4_gpu_encode_cpy_f32_f32_3d(cb,
 kvbuf,
 ds4_gpu_tensor_offset(kv),
 g_compressor_pool_kv_buffer,
 dst_plane_stride,
 head_dim,
 ratio,
 n_comp - 1u,
 src_row_stride,
 src_plane_stride,
 dst_row_stride,
 dst_plane_stride) &&
 ds4_gpu_encode_cpy_f32_f32_3d(cb,
 g_compressor_store_score_buffer,
 0,
 g_compressor_pool_score_buffer,
