 head_dim,
 ratio,
 n_comp - 1u,
 src_row_stride,
 src_plane_stride,
 dst_row_stride,
 dst_plane_stride);
 }
 if (ok) {
 ok = ds4_gpu_encode_dsv4_softmax_pool(cb,
 comp_cache,
 g_compressor_pool_kv_buffer,
 0,
 dst_row_stride,
 sizeof(float),
 dst_plane_stride,
 g_compressor_pool_score_buffer,
 0,
 dst_row_stride,
 sizeof(float),
 dst_plane_stride,
 8,
 head_dim,
 n_comp);
 }
