 if (flash_stage_profile) {
 if (ds4_gpu_end_commands() == 0 || ds4_gpu_begin_commands() == 0) {
 return 0;
 }
 int profile_owned = 0;
 cb = ds4_gpu_command_buffer(&profile_owned);
