 id<MTLBuffer> bbuf = ds4_gpu_tensor_buffer(b);
 id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
 const uint64_t bytes = (uint64_t)n * sizeof(float);
 if (!abuf || !bbuf || !outbuf ||
 ds4_gpu_tensor_bytes(a) < bytes ||
 ds4_gpu_tensor_bytes(b) < bytes ||
