 return 0;
 }

 int owned = 0;
 id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
 if (!cb) return 0;

 const uint64_t row_bytes = (uint64_t)n * sizeof(float);
 ds4_gpu_bin_args args = {
 .ne00 = (int32_t)n,
 .ne01 = 1,
 .ne02 = 1,
 .ne03 = 1,
 .nb00 = sizeof(float),
 .nb01 = row_bytes,
 .nb02 = row_bytes,
 .nb03 = row_bytes,
 .ne10 = (int32_t)n,
 .ne11 = 1,
 .ne12 = 1,
 .ne13 = 1,
 .nb10 = sizeof(float),
 .nb11 = row_bytes,
 .nb12 = row_bytes,
 .nb13 = row_bytes,
 .ne0 = (int32_t)n,
 .ne1 = 1,
 .ne2 = 1,
 .ne3 = 1,
 .nb0 = sizeof(float),
 .nb1 = row_bytes,
 .nb2 = row_bytes,
 .nb3 = row_bytes,
 .offs = 0,
 .o1 = { 0 },
 };
 NSUInteger nth_max = g_add_pipeline.maxTotalThreadsPerThreadgroup;
 if (nth_max > 256u) nth_max = 256u;
 NSUInteger nth = 1;
 while (2u * nth < (NSUInteger)args.ne0 && nth < nth_max) {
 nth *= 2u;
 }

 id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
 [enc setComputePipelineState:g_add_pipeline];
 [enc setBytes:&args length:sizeof(args) atIndex:0];
 [enc setBuffer:abuf offset:ds4_gpu_tensor_offset(a) atIndex:1];
 [enc setBuffer:bbuf offset:ds4_gpu_tensor_offset(b) atIndex:2];
 [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
 [enc dispatchThreadgroups:MTLSizeMake(1, 1, 1)
 threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
 ds4_gpu_end_compute_encoder(cb, enc);

 if (!ds4_gpu_finish_command_buffer(cb, owned, "tensor add")) return 0;
 }

 return 1;
}

typedef struct {
 uint32_t width;
 uint32_t rows;
 uint32_t layer;
 uint32_t n_threads;
 float scale;
} ds4_gpu_directional_steering_project_args;

int ds4_gpu_directional_steering_project_tensor(
 ds4_gpu_tensor *x,
 const ds4_gpu_tensor *directions,
 uint32_t layer,
 uint32_t width,
 uint32_t rows,
 float scale) {
 if (!g_initialized && !ds4_gpu_init()) return 0;
 if (!x || !directions || width == 0 || rows == 0 || scale == 0.0f) return 0;

 @autoreleasepool {
 id<MTLComputePipelineState> pipeline =
 ds4_gpu_get_pipeline("kernel_dsv4_directional_steering_project_f32");
 if (!pipeline) return 0;

 id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
 id<MTLBuffer> dbuf = ds4_gpu_tensor_buffer(directions);
 const uint64_t x_bytes = (uint64_t)width * rows * sizeof(float);
 const uint64_t dir_bytes = (uint64_t)(layer + 1u) * width * sizeof(float);
 if (!xbuf || !dbuf ||
 ds4_gpu_tensor_bytes(x) < x_bytes ||
 ds4_gpu_tensor_bytes(directions) < dir_bytes) {
 fprintf(stderr, "ds4: Metal directional steering received undersized buffers\n");
 return 0;
 }

 int owned = 0;
 id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
 if (!cb) return 0;

 NSUInteger nth = pipeline.maxTotalThreadsPerThreadgroup;
 if (nth > 256u) nth = 256u;
 while (nth > width && nth > 1u) nth >>= 1;
 if (nth == 0) nth = 1;

 ds4_gpu_directional_steering_project_args args = {
 .width = width,
 .rows = rows,
 .layer = layer,
 .n_threads = (uint32_t)nth,
 .scale = scale,
 };

 id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
 [enc setComputePipelineState:pipeline];
 [enc setBytes:&args length:sizeof(args) atIndex:0];
 [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:1];
 [enc setBuffer:dbuf offset:ds4_gpu_tensor_offset(directions) atIndex:2];
 [enc setThreadgroupMemoryLength:nth * sizeof(float) atIndex:0];
 [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)rows, 1, 1)
 threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
 ds4_gpu_end_compute_encoder(cb, enc);

 if (!ds4_gpu_finish_command_buffer(cb, owned, "directional steering")) return 0;
 }

 return 1;
}

static NSUInteger ds4_gpu_bin_threads(uint32_t width, id<MTLComputePipelineState> pipeline) {
 NSUInteger nth_max = pipeline.maxTotalThreadsPerThreadgroup;
 if (nth_max > 256u) nth_max = 256u;
 NSUInteger nth = 1u;
 while (2u * nth < (NSUInteger)width && nth < nth_max) nth *= 2u;
 return nth ? nth : 1u;
}

/* #558 ICB Phase 4 helper for kernel_dsv4_softplus_sqrt_f32_4. The fixed
 * dispatch shape (width=256, rows=1, c4=1, min=0, max=0) means args + grid
 * are constant across both call sites; only src/dst buffers vary.
 *
 * Cycle 9c (silv 2026-05-28 task #673/#795) — migrated to unified
 * ds4_icb_slot API. The old bespoke ds4_softplus_sqrt_icb_slot + inline
 * sig check + record body is subsumed by ds4_icb_slot_record_command's
 * memcmp-based signature compare. */
static ds4_icb_slot_t g_softplus_sqrt_slot;
static int ds4_softplus_sqrt_dispatch_icb(id<MTLCommandBuffer> cb,
                                           uint32_t slot_idx,
                                           id<MTLComputePipelineState> pipeline,
                                           id<MTLBuffer> src, NSUInteger src_off,
                                           id<MTLBuffer> dst, NSUInteger dst_off) {
    static int s_env_checked = 0;
    static int s_env_active = 0;
    if (!s_env_checked) {
        s_env_active = getenv("DS4_ICB_SOFTPLUS") != NULL ? 1 : 0;
        s_env_checked = 1;
        if (s_env_active) {
            fprintf(stderr, "ds4: DS4_ICB_SOFTPLUS=1 — softplus_sqrt ICB engaged via "
                            "unified ds4_icb_slot API (Cycle 9c)\n");
        }
    }
    if (!s_env_active) return 0;
    if (slot_idx >= DS4_SOFTPLUS_SQRT_ICB_SLOTS) return 0;
    if (!pipeline) return 0;

    if (!g_softplus_sqrt_slot.icb) {
        if (!ds4_icb_slot_acquire(&g_softplus_sqrt_slot,
                                  /*max_commands=*/(NSUInteger)DS4_SOFTPLUS_SQRT_ICB_SLOTS,
                                  /*max_bindings=*/3)) return 0;
    }
    if (!g_softplus_sqrt_icb_args_buffer) {
        ds4_gpu_unary_args args = ds4_gpu_make_unary_rows_args(256u, 1u, 1, 0.0f, 0.0f);
        args.min = 0.0f;
        args.max = 0.0f;
        g_softplus_sqrt_icb_args_buffer =
            [g_device newBufferWithBytes:&args length:sizeof(args)
                                 options:MTLResourceStorageModeShared];
        if (!g_softplus_sqrt_icb_args_buffer) return 0;
    }

    __unsafe_unretained id<MTLBuffer> bufs[3] = {
        g_softplus_sqrt_icb_args_buffer, src, dst };
    NSUInteger offs[3] = { 0, src_off, dst_off };
    MTLSize grid = MTLSizeMake(1, 1, 1);
    MTLSize tg   = MTLSizeMake(64, 1, 1);
    if (!ds4_icb_slot_record_command(&g_softplus_sqrt_slot, /*cmd_idx=*/slot_idx,
                                     pipeline, bufs, offs, /*n_bindings=*/3,
                                     grid, tg, /*tg_mem=*/0,
                                     /*extras=*/NULL, /*n_extras=*/0)) {
        return 0;
    }

    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc useResource:g_softplus_sqrt_icb_args_buffer usage:MTLResourceUsageRead];
    [enc useResource:src usage:MTLResourceUsageRead];
    [enc useResource:dst usage:MTLResourceUsageRead | MTLResourceUsageWrite];
    ds4_icb_slot_execute(&g_softplus_sqrt_slot, enc, slot_idx, 1);
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

static int ds4_gpu_encode_unary_f32_rows(
 id<MTLCommandBuffer> cb,
 id<MTLComputePipelineState> pipeline,
 id<MTLBuffer> src,
 NSUInteger src_off,
 id<MTLBuffer> dst,
 NSUInteger dst_off,
 uint32_t width,
 uint32_t rows,
 int c4,
 float min,
 float max) {
 if (!cb || !pipeline || !src || !dst || width == 0 || rows == 0) return 0;
 if (c4 && (width & 3u) != 0) return 0;

 ds4_gpu_unary_args args = ds4_gpu_make_unary_rows_args(width, rows, c4, 0.0f, 0.0f);
 args.min = min;
 args.max = max;

 NSUInteger nth_max = pipeline.maxTotalThreadsPerThreadgroup;
 if (nth_max > 256u) nth_max = 256u;
 NSUInteger nth = (NSUInteger)args.ne00;
 if (nth > nth_max) nth = nth_max;
 if (nth == 0) nth = 1u;
 const NSUInteger nk0 = ((NSUInteger)args.ne00 + nth - 1u) / nth;

 id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
 [enc setComputePipelineState:pipeline];
 [enc setBytes:&args length:sizeof(args) atIndex:0];
 [enc setBuffer:src offset:src_off atIndex:1];
 [enc setBuffer:dst offset:dst_off atIndex:2];
 [enc dispatchThreadgroups:MTLSizeMake(nk0 * (NSUInteger)args.ne01,
 (NSUInteger)args.ne02,
 (NSUInteger)args.ne03)
 threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
 ds4_gpu_end_compute_encoder(cb, enc);
 return 1;
}

static int ds4_gpu_encode_bin_f32_rows(
 id<MTLCommandBuffer> cb,
 id<MTLComputePipelineState> pipeline,
 const ds4_gpu_bin_args *args,
 id<MTLBuffer> a,
 NSUInteger a_off,
 id<MTLBuffer> b,
 NSUInteger b_off,
 id<MTLBuffer> out,
 NSUInteger out_off) {
 if (!cb || !pipeline || !args || !a || !b || !out || args->ne0 <= 0 || args->ne1 <= 0) {
 return 0;
 }

 const NSUInteger nth = ds4_gpu_bin_threads((uint32_t)args->ne0, pipeline);
 id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
 [enc setComputePipelineState:pipeline];
 [enc setBytes:args length:sizeof(*args) atIndex:0];
 [enc setBuffer:a offset:a_off atIndex:1];
 [enc setBuffer:b offset:b_off atIndex:2];
 [enc setBuffer:out offset:out_off atIndex:3];
 [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)args->ne1,
 (NSUInteger)args->ne2,
 (NSUInteger)args->ne3)
 threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
 ds4_gpu_end_compute_encoder(cb, enc);
 return 1;
}

