 sizeof(float));
}

static ds4_gpu_mul_mm_id_args ds4_gpu_make_mul_mm_id_args_src1_size(
 uint32_t src0_cols,
 uint32_t src0_rows,
 uint32_t src0_experts,
 uint64_t src0_row_bytes,
 uint64_t src0_expert_bytes,
 uint32_t src1_expert_rows,
 uint32_t selected_experts,
 uint32_t n_tokens,
 uint32_t src1_elem_size) {
 const uint64_t src1_row_bytes = (uint64_t)src0_cols * src1_elem_size;
 return (ds4_gpu_mul_mm_id_args) {
 .ne00 = (int32_t)src0_cols,
 .ne02 = (int32_t)src0_experts,
 .nb01 = src0_row_bytes,
 .nb02 = src0_expert_bytes,
 .nb03 = (uint64_t)src0_experts * src0_expert_bytes,
 .ne11 = (int32_t)src1_expert_rows,
 .nb10 = src1_elem_size,
 .nb11 = src1_row_bytes,
 .nb12 = (uint64_t)src1_expert_rows * src1_row_bytes,
 .nb13 = (uint64_t)n_tokens * (uint64_t)src1_expert_rows * src1_row_bytes,
 .ne20 = (int32_t)selected_experts,
 .ne21 = (int32_t)n_tokens,
 .ne0 = (int32_t)src0_rows,
 .ne1 = (int32_t)selected_experts,
 .r2 = 1,
 .r3 = 1,
 };
}

static uint32_t ds4_gpu_routed_mv_nr0(uint32_t type) {
 switch (type) {
 case DS4_METAL_TENSOR_Q4_K: return 2;
 case DS4_METAL_TENSOR_Q2_K:
 case DS4_METAL_TENSOR_IQ2_XXS: return 4;
 default: return 0;
 }
}

static const char *ds4_gpu_metal_tensor_type_name(uint32_t type) {
 switch (type) {
 case DS4_METAL_TENSOR_IQ2_XXS: return "iq2_xxs";
 case DS4_METAL_TENSOR_Q2_K: return "q2_k";
 case DS4_METAL_TENSOR_Q4_K: return "q4_k";
 default: return "unknown";
 }
}

static NSUInteger ds4_gpu_routed_mv_smem(uint32_t type) {
 if (type == DS4_METAL_TENSOR_IQ2_XXS) {
 return 256u * sizeof(uint64_t) + 128u * sizeof(uint8_t);
 }
 return 0;
}

static id<MTLComputePipelineState> ds4_gpu_routed_mv_pipeline(uint32_t type) {
 switch (type) {
 case DS4_METAL_TENSOR_IQ2_XXS: return g_moe_mul_mv_id_iq2_xxs_pipeline;
 case DS4_METAL_TENSOR_Q2_K: return g_moe_mul_mv_id_q2_k_pipeline;
 case DS4_METAL_TENSOR_Q4_K: return g_moe_mul_mv_id_q4_k_pipeline;
 default: return nil;
 }
}

/* silv 2026-05-28 I-1: forward-decl MTL4-fixed wide-tile pipelines + init fns.
 * The mc[NR1/4] structural fix lives only in the MTL4 MSL strings; antirez's
 * moe.metal `kernel_mul_mm_id` template hardcodes mc[8] which silently
 * miscomputes rows 32+ at NR1=64 and rows 32+/96+ at NR1=128. For wide-tile
 * paths (n64/n128) we redirect to the MTL4-fixed pipelines; n32 stays on
 * antirez (correct at NR1=32). */
static int ds4_mul_mm_id_iq2_xxs_f32_n64_mtl4_pipeline_init(void);
static int ds4_mul_mm_id_iq2_xxs_f32_n128_mtl4_pipeline_init(void);
static int ds4_mul_mm_id_q4_K_f32_n64_mtl4_pipeline_init(void);
static int ds4_mul_mm_id_q4_K_f32_n128_mtl4_pipeline_init(void);
static int ds4_mul_mm_id_q2_K_f32_n64_mtl4_pipeline_init(void);
static int ds4_mul_mm_id_q2_K_f32_n128_mtl4_pipeline_init(void);
static id<MTLComputePipelineState> g_mul_mm_id_iq2_xxs_f32_n64_mtl4_pipeline;
static id<MTLComputePipelineState> g_mul_mm_id_iq2_xxs_f32_n128_mtl4_pipeline;
static id<MTLComputePipelineState> g_mul_mm_id_q4_K_f32_n64_mtl4_pipeline;
static id<MTLComputePipelineState> g_mul_mm_id_q4_K_f32_n128_mtl4_pipeline;
static id<MTLComputePipelineState> g_mul_mm_id_q2_K_f32_n64_mtl4_pipeline;
static id<MTLComputePipelineState> g_mul_mm_id_q2_K_f32_n128_mtl4_pipeline;

/* silv 2026-05-28 I-1 instrumentation: env-gated log of which pipeline got
 * selected. Set DS4_METAL_LOG_ROUTED_MM=1 to verify MTL4 redirect fires in
 * production. Dedupes per (type, tile_n, kind) — at most ~24 lines per run. */
static void ds4_gpu_log_routed_mm_pick(uint32_t type, uint32_t tile_n,
                                       const char *kind, const char *name) {
    static int s_init;
    static int s_enabled;
    if (!s_init) { s_enabled = getenv("DS4_METAL_LOG_ROUTED_MM") != NULL; s_init = 1; }
    if (!s_enabled) return;
    static char s_seen[32];
    int t = -1, n = -1, k = (kind[0] == 'M') ? 1 : 0;
    if (type == DS4_METAL_TENSOR_IQ2_XXS) t = 0;
    else if (type == DS4_METAL_TENSOR_Q2_K) t = 1;
    else if (type == DS4_METAL_TENSOR_Q4_K) t = 2;
    if (tile_n == 32u) n = 0; else if (tile_n == 64u) n = 1; else if (tile_n == 128u) n = 2;
    if (t < 0 || n < 0) return;
    int slot = t * 8 + n * 2 + k;
    if (slot < 0 || slot >= 32 || s_seen[slot]) return;
    s_seen[slot] = 1;
    fprintf(stderr, "ds4: routed_mm dispatch: type=%u tile_n=%u kind=%s pipeline=%s\n",
            type, tile_n, kind, name);
}

static id<MTLComputePipelineState> ds4_gpu_routed_mm_pipeline_for_tile(uint32_t type,
                                                                         uint32_t tile_n) {
    switch (type) {
    case DS4_METAL_TENSOR_IQ2_XXS:
        if (tile_n == 128u) {
            if (ds4_mul_mm_id_iq2_xxs_f32_n128_mtl4_pipeline_init()) {
                ds4_gpu_log_routed_mm_pick(type, tile_n, "MTL4", "iq2_xxs_f32_n128_mtl4");
                return g_mul_mm_id_iq2_xxs_f32_n128_mtl4_pipeline;
            }
            ds4_gpu_log_routed_mm_pick(type, tile_n, "antirez", "kernel_mul_mm_id_iq2_xxs_f32_n128");
            return ds4_gpu_get_mul_mm_id_pipeline("kernel_mul_mm_id_iq2_xxs_f32_n128", false);
        }
        if (tile_n == 64u) {
            if (ds4_mul_mm_id_iq2_xxs_f32_n64_mtl4_pipeline_init()) {
                ds4_gpu_log_routed_mm_pick(type, tile_n, "MTL4", "iq2_xxs_f32_n64_mtl4");
                return g_mul_mm_id_iq2_xxs_f32_n64_mtl4_pipeline;
            }
            ds4_gpu_log_routed_mm_pick(type, tile_n, "antirez", "kernel_mul_mm_id_iq2_xxs_f32_n64");
            return ds4_gpu_get_mul_mm_id_pipeline("kernel_mul_mm_id_iq2_xxs_f32_n64", false);
        }
        ds4_gpu_log_routed_mm_pick(type, tile_n, "antirez", "kernel_mul_mm_id_iq2_xxs_f32");
        return ds4_gpu_get_mul_mm_id_pipeline("kernel_mul_mm_id_iq2_xxs_f32", false);
    case DS4_METAL_TENSOR_Q2_K:
        if (tile_n == 128u) {
            if (ds4_mul_mm_id_q2_K_f32_n128_mtl4_pipeline_init()) {
                ds4_gpu_log_routed_mm_pick(type, tile_n, "MTL4", "q2_K_f32_n128_mtl4");
                return g_mul_mm_id_q2_K_f32_n128_mtl4_pipeline;
            }
            ds4_gpu_log_routed_mm_pick(type, tile_n, "antirez", "kernel_mul_mm_id_q2_K_f32_n128");
            return ds4_gpu_get_mul_mm_id_pipeline("kernel_mul_mm_id_q2_K_f32_n128", false);
        }
        if (tile_n == 64u) {
            if (ds4_mul_mm_id_q2_K_f32_n64_mtl4_pipeline_init()) {
                ds4_gpu_log_routed_mm_pick(type, tile_n, "MTL4", "q2_K_f32_n64_mtl4");
                return g_mul_mm_id_q2_K_f32_n64_mtl4_pipeline;
            }
            ds4_gpu_log_routed_mm_pick(type, tile_n, "antirez", "kernel_mul_mm_id_q2_K_f32_n64");
            return ds4_gpu_get_mul_mm_id_pipeline("kernel_mul_mm_id_q2_K_f32_n64", false);
        }
        ds4_gpu_log_routed_mm_pick(type, tile_n, "antirez", "kernel_mul_mm_id_q2_K_f32");
        return ds4_gpu_get_mul_mm_id_pipeline("kernel_mul_mm_id_q2_K_f32", false);
    case DS4_METAL_TENSOR_Q4_K:
        if (tile_n == 128u) {
            if (ds4_mul_mm_id_q4_K_f32_n128_mtl4_pipeline_init()) {
                ds4_gpu_log_routed_mm_pick(type, tile_n, "MTL4", "q4_K_f32_n128_mtl4");
                return g_mul_mm_id_q4_K_f32_n128_mtl4_pipeline;
            }
            ds4_gpu_log_routed_mm_pick(type, tile_n, "antirez", "kernel_mul_mm_id_q4_K_f32_n128");
            return ds4_gpu_get_mul_mm_id_pipeline("kernel_mul_mm_id_q4_K_f32_n128", false);
        }
        if (tile_n == 64u) {
            if (ds4_mul_mm_id_q4_K_f32_n64_mtl4_pipeline_init()) {
                ds4_gpu_log_routed_mm_pick(type, tile_n, "MTL4", "q4_K_f32_n64_mtl4");
                return g_mul_mm_id_q4_K_f32_n64_mtl4_pipeline;
            }
            ds4_gpu_log_routed_mm_pick(type, tile_n, "antirez", "kernel_mul_mm_id_q4_K_f32_n64");
            return ds4_gpu_get_mul_mm_id_pipeline("kernel_mul_mm_id_q4_K_f32_n64", false);
        }
        ds4_gpu_log_routed_mm_pick(type, tile_n, "antirez", "kernel_mul_mm_id_q4_K_f32");
        return ds4_gpu_get_mul_mm_id_pipeline("kernel_mul_mm_id_q4_K_f32", false);
    default:
        return nil;
    }
}

static uint32_t ds4_gpu_moe_mm_tile_n(uint32_t gate_type, uint32_t n_tokens) {
    const uint32_t tile_max = ds4_gpu_env_u32("DS4_METAL_MOE_TILE_MAX", 128u);
    if (tile_max <= 32u) {
        return 32u;
    }
    if (gate_type == DS4_METAL_TENSOR_Q4_K ||
        gate_type == DS4_METAL_TENSOR_Q2_K ||
        gate_type == DS4_METAL_TENSOR_IQ2_XXS) {
        if (tile_max >= 128u && n_tokens >= 128u && (n_tokens % 128u) == 0) {
            return 128u;
        }
        if (tile_max >= 64u && n_tokens >= 64u && (n_tokens % 64u) == 0) {
            return 64u;
        }
    }
    return 32u;
}

static id<MTLComputePipelineState> ds4_gpu_routed_mm_f16_rhs_pipeline_for_tile(uint32_t type,
                                                                                uint32_t tile_n) {
    switch (type) {
    case DS4_METAL_TENSOR_IQ2_XXS:
        if (tile_n == 128u) {
            return ds4_gpu_get_mul_mm_id_pipeline("kernel_mul_mm_id_iq2_xxs_f16_n128", false);
        }
        if (tile_n == 64u) {
            return ds4_gpu_get_mul_mm_id_pipeline("kernel_mul_mm_id_iq2_xxs_f16_n64", false);
        }
        return ds4_gpu_get_mul_mm_id_pipeline("kernel_mul_mm_id_iq2_xxs_f16", false);
    case DS4_METAL_TENSOR_Q2_K:
        if (tile_n == 128u) {
            return ds4_gpu_get_mul_mm_id_pipeline("kernel_mul_mm_id_q2_K_f16_n128", false);
        }
        if (tile_n == 64u) {
            return ds4_gpu_get_mul_mm_id_pipeline("kernel_mul_mm_id_q2_K_f16_n64", false);
        }
        return ds4_gpu_get_mul_mm_id_pipeline("kernel_mul_mm_id_q2_K_f16", false);
    case DS4_METAL_TENSOR_Q4_K:
        if (tile_n == 128u) {
            return ds4_gpu_get_mul_mm_id_pipeline("kernel_mul_mm_id_q4_K_f16_n128", false);
        }
        if (tile_n == 64u) {
            return ds4_gpu_get_mul_mm_id_pipeline("kernel_mul_mm_id_q4_K_f16_n64", false);
        }
        return ds4_gpu_get_mul_mm_id_pipeline("kernel_mul_mm_id_q4_K_f16", false);
    default:
        return nil;
    }
}

/* silv 2026-05-28: the backward-compat ds4_gpu_routed_mm_pipeline and
 * ds4_gpu_routed_mm_f16_rhs_pipeline wrappers (called nothing — every
 * call site now uses *_for_tile directly with explicit tile size) were
 * removed here. The _for_tile primaries below carry the dispatch. */

static int ds4_gpu_encode_mul_mv_id(
 id<MTLCommandBuffer> cb,
 id<MTLComputePipelineState> pipeline,
 const ds4_gpu_mul_mv_id_args *args,
 id<MTLBuffer> src0,
 NSUInteger src0_off,
 id<MTLBuffer> src1,
 NSUInteger src1_off,
 id<MTLBuffer> dst,
 NSUInteger dst_off,
 id<MTLBuffer> ids,
 NSUInteger ids_off,
 NSUInteger threadgroup_bytes,
 NSUInteger nsg,
 bool rows_per_group_is_nr0) {
 if (!cb || !pipeline || !args || !src0 || !src1 || !dst || !ids ||
 args->ne00 <= 0 || args->ne01 <= 0 || args->nei0 <= 0 || args->nei1 <= 0) {
 return 0;
 }

 const NSUInteger nr0 = (NSUInteger)args->nr0;
 const NSUInteger rows_per_group = rows_per_group_is_nr0 ? nr0 : nr0 * nsg;
 const NSUInteger row_groups = ((NSUInteger)args->ne01 + rows_per_group - 1u) / rows_per_group;
 const NSUInteger pairs = (NSUInteger)args->nei0 * (NSUInteger)args->nei1;

 id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
 [enc setComputePipelineState:pipeline];
 [enc setBytes:args length:sizeof(*args) atIndex:0];
 [enc setBuffer:src0 offset:src0_off atIndex:1];
 [enc setBuffer:src1 offset:src1_off atIndex:2];
 [enc setBuffer:dst offset:dst_off atIndex:3];
 [enc setBuffer:ids offset:ids_off atIndex:4];
 if (threadgroup_bytes != 0) {
 [enc setThreadgroupMemoryLength:threadgroup_bytes atIndex:0];
 }
 [enc dispatchThreadgroups:MTLSizeMake(row_groups, 1, pairs)
 threadsPerThreadgroup:MTLSizeMake(32, nsg, 1)];
 ds4_gpu_end_compute_encoder(cb, enc);
 return 1;
}

