        const uint64_t hc_bytes = (uint64_t)n_tokens * n_hc * n_embd * sizeof(float);
        const uint64_t post_bytes = (uint64_t)n_tokens * n_hc * sizeof(float);
        const uint64_t comb_bytes = (uint64_t)n_tokens * n_hc * n_hc * sizeof(float);
        if (ds4_gpu_tensor_bytes(heads) < heads_bytes ||
            ds4_gpu_tensor_bytes(low) < low_bytes ||
            ds4_gpu_tensor_bytes(block_out) < block_bytes ||
            ds4_gpu_tensor_bytes(residual_hc) < hc_bytes ||
            ds4_gpu_tensor_bytes(post) < post_bytes ||
            ds4_gpu_tensor_bytes(comb) < comb_bytes ||
            ds4_gpu_tensor_bytes(out_hc) < hc_bytes) {
            fprintf(stderr, "ds4: FP8 attn-out onecb received undersized activation buffers\n");
            return 0;
        }

        struct {
            uint32_t group_dim;
            uint32_t rank;
            uint32_t n_groups;
            uint32_t n_tokens;
            uint32_t scale_cols;
        } low_args;
        low_args.group_dim = (uint32_t)group_dim;
        low_args.rank = (uint32_t)rank;
        low_args.n_groups = n_groups;
        low_args.n_tokens = n_tokens;
        low_args.scale_cols = (uint32_t)a_scale_cols;

        struct {
            uint32_t in_dim;
            uint32_t out_dim;
            uint32_t scale_cols;
            uint32_t n_tok;
            uint32_t store_block_out;
        } hc_args;
        hc_args.in_dim = (uint32_t)low_dim;
        hc_args.out_dim = n_embd;
        hc_args.scale_cols = (uint32_t)b_scale_cols;
        hc_args.n_tok = n_tokens;
        hc_args.store_block_out = store_block_out ? 1u : 0u;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:g_attn_low_fp8_e4m3_e8m0_storage_mtl4_pipeline];
        [enc setBytes:&low_args length:sizeof(low_args) atIndex:0];
        [enc setBuffer:awbuf offset:0 atIndex:1];
        [enc setBuffer:asbuf offset:0 atIndex:2];
        [enc setBuffer:headsbuf offset:ds4_gpu_tensor_offset(heads) atIndex:3];
        [enc setBuffer:lowbuf offset:ds4_gpu_tensor_offset(low) atIndex:4];
        [enc setThreadgroupMemoryLength:128u * sizeof(float) atIndex:0];
        [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)low_dim, (NSUInteger)n_tokens, 1)
            threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
        [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
        [enc setComputePipelineState:g_matmul_fp8_e4m3_e8m0_hc_expand4_mtl4_pipeline];
        [enc setBytes:&hc_args length:sizeof(hc_args) atIndex:0];
        [enc setBuffer:bwbuf offset:0 atIndex:1];
        [enc setBuffer:bsbuf offset:0 atIndex:2];
        [enc setBuffer:lowbuf offset:ds4_gpu_tensor_offset(low) atIndex:3];
        [enc setBuffer:blockbuf offset:ds4_gpu_tensor_offset(block_out) atIndex:4];
        [enc setBuffer:resbuf offset:ds4_gpu_tensor_offset(residual_hc) atIndex:5];
        [enc setBuffer:postbuf offset:ds4_gpu_tensor_offset(post) atIndex:6];
        [enc setBuffer:combbuf offset:ds4_gpu_tensor_offset(comb) atIndex:7];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out_hc) atIndex:8];
        [enc setThreadgroupMemoryLength:128u * sizeof(float) atIndex:0];
        [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)n_embd, (NSUInteger)n_tokens, 1)
            threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        if (!ds4_gpu_finish_command_buffer(cb, owned, "FP8_E4M3/E8M0 attention out HC onecb")) return 0;
    }
    return 1;
}

typedef struct {
    uint32_t group_dim;
    uint32_t rank;
    uint32_t n_groups;
    uint32_t n_tokens;
    uint32_t scale_cols;
} ds4_fp8_attn_low_icb_args;

typedef struct {
    uint32_t in_dim;
    uint32_t out_dim;
    uint32_t scale_cols;
    uint32_t n_tok;
} ds4_fp8_matmul_icb_args;

static void *ds4_fp8_icb_page_alloc(uint64_t used_bytes, uint64_t *padded_bytes_out) {
    const uint64_t page = (uint64_t)getpagesize();
    const uint64_t padded_bytes = (used_bytes + page - 1u) & ~(page - 1u);
    void *ptr = NULL;
    if (posix_memalign(&ptr, (size_t)page, (size_t)padded_bytes) != 0 || !ptr) return NULL;
    memset(ptr, 0, (size_t)padded_bytes);
    if (padded_bytes_out) *padded_bytes_out = padded_bytes;
    return ptr;
}

static void ds4_fp8_icb_fill_bytes(uint8_t *dst, uint64_t bytes, uint32_t salt) {
    for (uint64_t i = 0; i < bytes; i++) {
        dst[i] = (uint8_t)(0x20u + ((uint32_t)i * 17u + salt * 29u) % 0x3fu);
    }
}

int ds4_gpu_fp8_attn_out_icb_canary(uint32_t group_dim,
                                    uint32_t rank,
                                    uint32_t n_groups,
                                    uint32_t out_dim,
                                    uint32_t n_tokens,
                                    uint32_t rounds,
                                    uint32_t mode) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_attn_low_fp8_e4m3_e8m0_storage_mtl4_pipeline_init()) return 0;
    if (!ds4_matmul_fp8_e4m3_e8m0_storage_mtl4_pipeline_init()) return 0;
    if (group_dim == 0 || rank == 0 || n_groups == 0 || out_dim == 0 || n_tokens == 0) return 0;
    if (rounds == 0) rounds = 1;
    if (mode > 1) mode = 0;

    const uint64_t low_dim = (uint64_t)n_groups * rank;
    const uint64_t a_weight_bytes = low_dim * group_dim;
    const uint64_t a_scale_cols = ((uint64_t)group_dim + 127u) / 128u;
    const uint64_t a_scale_rows = (low_dim + 127u) / 128u;
    const uint64_t a_scale_bytes = a_scale_rows * a_scale_cols;
    const uint64_t b_weight_bytes = (uint64_t)out_dim * low_dim;
    const uint64_t b_scale_cols = (low_dim + 127u) / 128u;
    const uint64_t b_scale_rows = ((uint64_t)out_dim + 127u) / 128u;
    const uint64_t b_scale_bytes = b_scale_rows * b_scale_cols;
    const uint64_t heads_count = (uint64_t)n_tokens * n_groups * group_dim;
    const uint64_t low_count = (uint64_t)n_tokens * low_dim;
    const uint64_t out_count = (uint64_t)n_tokens * out_dim;
    if (low_dim > UINT32_MAX || heads_count > UINT32_MAX || low_count > UINT32_MAX || out_count > UINT32_MAX) return 0;

    uint64_t a_weight_padded = 0, a_scale_padded = 0, b_weight_padded = 0, b_scale_padded = 0;
    void *a_weight_host = ds4_fp8_icb_page_alloc(a_weight_bytes, &a_weight_padded);
    void *a_scale_host = ds4_fp8_icb_page_alloc(a_scale_bytes, &a_scale_padded);
    void *b_weight_host = ds4_fp8_icb_page_alloc(b_weight_bytes, &b_weight_padded);
    void *b_scale_host = ds4_fp8_icb_page_alloc(b_scale_bytes, &b_scale_padded);
    float *heads_host = (float *)calloc((size_t)heads_count, sizeof(float));
    float *direct_host = (float *)calloc((size_t)out_count, sizeof(float));
    float *icb_host = (float *)calloc((size_t)out_count, sizeof(float));
    if (!a_weight_host || !a_scale_host || !b_weight_host || !b_scale_host ||
        !heads_host || !direct_host || !icb_host) {
        free(a_weight_host); free(a_scale_host); free(b_weight_host); free(b_scale_host);
        free(heads_host); free(direct_host); free(icb_host);
        return 0;
    }
    ds4_fp8_icb_fill_bytes((uint8_t *)a_weight_host, a_weight_bytes, 1);
    ds4_fp8_icb_fill_bytes((uint8_t *)b_weight_host, b_weight_bytes, 2);
    memset(a_scale_host, 127, (size_t)a_scale_bytes);
    memset(b_scale_host, 127, (size_t)b_scale_bytes);
    for (uint64_t i = 0; i < heads_count; i++) {
        heads_host[i] = ((float)((int)(i % 17u)) - 8.0f) * 0.03125f;
    }

    int rc = 0;
    @autoreleasepool {
        void *a_weight_opaque = ds4_gpu_wrap_heap_bytes(a_weight_host, a_weight_padded);
        void *a_scale_opaque = ds4_gpu_wrap_heap_bytes(a_scale_host, a_scale_padded);
        void *b_weight_opaque = ds4_gpu_wrap_heap_bytes(b_weight_host, b_weight_padded);
        void *b_scale_opaque = ds4_gpu_wrap_heap_bytes(b_scale_host, b_scale_padded);
        id<MTLBuffer> a_weight_buf = (__bridge id<MTLBuffer>)a_weight_opaque;
        id<MTLBuffer> a_scale_buf = (__bridge id<MTLBuffer>)a_scale_opaque;
        id<MTLBuffer> b_weight_buf = (__bridge id<MTLBuffer>)b_weight_opaque;
        id<MTLBuffer> b_scale_buf = (__bridge id<MTLBuffer>)b_scale_opaque;
        ds4_gpu_tensor *heads = ds4_gpu_tensor_alloc(heads_count * sizeof(float));
        ds4_gpu_tensor *direct_low = ds4_gpu_tensor_alloc(low_count * sizeof(float));
        ds4_gpu_tensor *icb_low = ds4_gpu_tensor_alloc(low_count * sizeof(float));
        ds4_gpu_tensor *direct_out = ds4_gpu_tensor_alloc(out_count * sizeof(float));
        ds4_gpu_tensor *icb_out = ds4_gpu_tensor_alloc(out_count * sizeof(float));
        id<MTLBuffer> args_buf = [g_device newBufferWithLength:512 options:MTLResourceStorageModeShared];
        fprintf(stderr,
                "ds4: FP8-attn-out ICB canary START group_dim=%u rank=%u n_groups=%u out_dim=%u n_tokens=%u rounds=%u mode=%s\n",
                group_dim, rank, n_groups, out_dim, n_tokens, rounds, mode == 0 ? "separate-cb" : "one-cb-barrier");
        if (a_weight_buf && a_scale_buf && b_weight_buf && b_scale_buf &&
            heads && direct_low && icb_low && direct_out && icb_out && args_buf &&
            ds4_gpu_tensor_write(heads, 0, heads_host, heads_count * sizeof(float)) > 0) {
            ds4_fp8_attn_low_icb_args low_args = {
                .group_dim = group_dim,
                .rank = rank,
                .n_groups = n_groups,
                .n_tokens = n_tokens,
                .scale_cols = (uint32_t)a_scale_cols,
            };
            ds4_fp8_matmul_icb_args out_args = {
                .in_dim = (uint32_t)low_dim,
                .out_dim = out_dim,
                .scale_cols = (uint32_t)b_scale_cols,
                .n_tok = n_tokens,
            };
            memcpy((uint8_t *)args_buf.contents + 0, &low_args, sizeof(low_args));
            memcpy((uint8_t *)args_buf.contents + 256, &out_args, sizeof(out_args));

            ds4_icb_slot_t slot;
            memset((void *)&slot, 0, sizeof(slot));
            if (ds4_icb_slot_acquire(&slot, 2, 5)) {
                id<MTLBuffer> headsbuf = ds4_gpu_tensor_buffer(heads);
                id<MTLBuffer> lowbuf = ds4_gpu_tensor_buffer(icb_low);
                id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(icb_out);
                __unsafe_unretained id<MTLBuffer> low_bindings[5] = { args_buf, a_weight_buf, a_scale_buf, headsbuf, lowbuf };
                NSUInteger low_offsets[5] = { 0, 0, 0, ds4_gpu_tensor_offset(heads), ds4_gpu_tensor_offset(icb_low) };
                __unsafe_unretained id<MTLBuffer> out_bindings[5] = { args_buf, b_weight_buf, b_scale_buf, lowbuf, outbuf };
                NSUInteger out_offsets[5] = { 256, 0, 0, ds4_gpu_tensor_offset(icb_low), ds4_gpu_tensor_offset(icb_out) };
                uint64_t low_extras[5] = { group_dim, rank, n_groups, n_tokens, low_dim };
                uint64_t out_extras[5] = { low_dim, out_dim, n_tokens, b_scale_cols, 0 };
                const int low_ready = ds4_icb_slot_record_command(
                    &slot, 0, g_attn_low_fp8_e4m3_e8m0_storage_mtl4_pipeline,
                    low_bindings, low_offsets, 5,
                    MTLSizeMake((NSUInteger)low_dim, (NSUInteger)n_tokens, 1),
                    MTLSizeMake(128, 1, 1),
                    128u * sizeof(float), low_extras, 5);
                const int out_ready = ds4_icb_slot_record_command(
                    &slot, 1, g_matmul_fp8_e4m3_e8m0_storage_mtl4_pipeline,
                    out_bindings, out_offsets, 5,
                    MTLSizeMake((NSUInteger)out_dim, (NSUInteger)n_tokens, 1),
                    MTLSizeMake(128, 1, 1),
                    128u * sizeof(float), out_extras, 5);

                int direct_ok = low_ready && out_ready;
                const double direct_start_ms = ds4_gpu_now_ms();
                for (uint32_t iter = 0; direct_ok && iter < rounds; iter++) {
                    direct_ok = ds4_gpu_attention_output_low_fp8_e4m3_e8m0_storage(
                                    direct_low, a_weight_opaque, a_scale_opaque, a_scale_bytes,
                                    group_dim, rank, n_groups, heads, n_tokens) != 0;
                    if (direct_ok) {
                        direct_ok = ds4_gpu_matmul_fp8_e4m3_e8m0_storage(
                                        direct_out, b_weight_opaque, b_scale_opaque, b_scale_bytes,
                                        low_dim, out_dim, direct_low, n_tokens) != 0;
                    }
                }
                const double direct_ms = ds4_gpu_now_ms() - direct_start_ms;

                int icb_ok = direct_ok;
                const double icb_start_ms = ds4_gpu_now_ms();
                for (uint32_t iter = 0; icb_ok && iter < rounds; iter++) {
                    if (mode == 0) {
                        int owned_low = 0;
                        id<MTLCommandBuffer> cb_low = ds4_gpu_command_buffer(&owned_low);
                        id<MTLComputeCommandEncoder> enc_low = cb_low ? ds4_gpu_compute_encoder(cb_low) : nil;
                        if (!enc_low) { icb_ok = 0; break; }
                        ds4_icb_slot_use_resources(&slot, enc_low, 0, 1, MTLResourceUsageRead | MTLResourceUsageWrite);
                        icb_ok = ds4_icb_slot_execute(&slot, enc_low, 0, 1);
                        ds4_gpu_end_compute_encoder(cb_low, enc_low);
                        if (icb_ok) icb_ok = ds4_gpu_finish_command_buffer(cb_low, owned_low, "fp8 attn low icb canary");
                        if (!icb_ok) break;
                        int owned_out = 0;
                        id<MTLCommandBuffer> cb_out = ds4_gpu_command_buffer(&owned_out);
                        id<MTLComputeCommandEncoder> enc_out = cb_out ? ds4_gpu_compute_encoder(cb_out) : nil;
                        if (!enc_out) { icb_ok = 0; break; }
                        ds4_icb_slot_use_resources(&slot, enc_out, 1, 1, MTLResourceUsageRead | MTLResourceUsageWrite);
                        icb_ok = ds4_icb_slot_execute(&slot, enc_out, 1, 1);
                        ds4_gpu_end_compute_encoder(cb_out, enc_out);
                        if (icb_ok) icb_ok = ds4_gpu_finish_command_buffer(cb_out, owned_out, "fp8 attn out icb canary");
                    } else {
                        int owned = 0;
                        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
                        id<MTLComputeCommandEncoder> enc = cb ? ds4_gpu_compute_encoder(cb) : nil;
                        if (!enc) { icb_ok = 0; break; }
                        ds4_icb_slot_use_resources(&slot, enc, 0, 1, MTLResourceUsageRead | MTLResourceUsageWrite);
                        icb_ok = ds4_icb_slot_execute(&slot, enc, 0, 1);
                        if (icb_ok) {
                            [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
                            ds4_icb_slot_use_resources(&slot, enc, 1, 1, MTLResourceUsageRead | MTLResourceUsageWrite);
                            icb_ok = ds4_icb_slot_execute(&slot, enc, 1, 1);
                        }
                        ds4_gpu_end_compute_encoder(cb, enc);
                        if (icb_ok) icb_ok = ds4_gpu_finish_command_buffer(cb, owned, "fp8 attn out icb barrier canary");
                    }
                }
                const double icb_ms = ds4_gpu_now_ms() - icb_start_ms;

                if (direct_ok && icb_ok &&
                    ds4_gpu_tensor_read(direct_out, 0, direct_host, out_count * sizeof(float)) > 0 &&
                    ds4_gpu_tensor_read(icb_out, 0, icb_host, out_count * sizeof(float)) > 0) {
                    uint64_t mismatches = 0;
                    float max_abs_delta = 0.0f;
                    for (uint64_t i = 0; i < out_count; i++) {
                        const float delta = fabsf(direct_host[i] - icb_host[i]);
                        if (delta > max_abs_delta) max_abs_delta = delta;
                        if (delta > 1e-5f) mismatches++;
                    }
                    const double direct_per = direct_ms / (double)rounds;
                    const double icb_per = icb_ms / (double)rounds;
                    fprintf(stderr,
                            "ds4: FP8-attn-out ICB canary direct=%.3f ms/round icb=%.3f ms/round speedup=%.2fx max_abs_delta=%.3e mismatches=%llu/%llu %s\n",
                            direct_per, icb_per, icb_per > 0.0 ? direct_per / icb_per : 0.0,
                            (double)max_abs_delta,
                            (unsigned long long)mismatches,
                            (unsigned long long)out_count,
                            mismatches == 0 ? "PASS" : "DIVERGE");
                    rc = (mismatches == 0);
                } else {
                    fprintf(stderr,
                            "ds4: FP8-attn-out ICB canary failed direct_ok=%d icb_ok=%d low_ready=%d out_ready=%d\n",
                            direct_ok, icb_ok, low_ready, out_ready);
                }
            }
        }
        ds4_gpu_tensor_free(heads);
        ds4_gpu_tensor_free(direct_low);
        ds4_gpu_tensor_free(icb_low);
        ds4_gpu_tensor_free(direct_out);
        ds4_gpu_tensor_free(icb_out);
        ds4_gpu_release_heap_buffer(a_weight_opaque);
        ds4_gpu_release_heap_buffer(a_scale_opaque);
        ds4_gpu_release_heap_buffer(b_weight_opaque);
        ds4_gpu_release_heap_buffer(b_scale_opaque);
    }
    free(a_weight_host);
    free(a_scale_host);
    free(b_weight_host);
    free(b_scale_host);
    free(heads_host);
    free(direct_host);
    free(icb_host);
    return rc;
}

int ds4_gpu_fp8_hc_fuse_canary(uint32_t in_dim,
                               uint32_t out_dim,
                               uint32_t n_tokens,
                               uint32_t rounds) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_matmul_fp8_e4m3_e8m0_storage_mtl4_pipeline_init()) return 0;
    if (!ds4_matmul_fp8_e4m3_e8m0_hc_expand4_mtl4_pipeline_init()) return 0;
    if (in_dim == 0 || out_dim == 0 || n_tokens == 0) return 0;
    if (rounds == 0) rounds = 1;

    const uint32_t n_hc = 4;
    const uint64_t weight_bytes = (uint64_t)out_dim * in_dim;
    const uint64_t scale_cols = ((uint64_t)in_dim + 127u) / 128u;
    const uint64_t scale_rows = ((uint64_t)out_dim + 127u) / 128u;
    const uint64_t scale_bytes = scale_cols * scale_rows;
    const uint64_t input_count = (uint64_t)n_tokens * in_dim;
    const uint64_t block_count = (uint64_t)n_tokens * out_dim;
    const uint64_t hc_count = (uint64_t)n_tokens * n_hc * out_dim;
    const uint64_t post_count = (uint64_t)n_tokens * n_hc;
    const uint64_t comb_count = (uint64_t)n_tokens * n_hc * n_hc;
    if (input_count == 0 || block_count == 0 || hc_count == 0 ||
        weight_bytes == 0 || scale_bytes == 0) {
        return 0;
    }

    uint64_t weight_padded = 0, scale_padded = 0;
    void *weight_host = ds4_fp8_icb_page_alloc(weight_bytes, &weight_padded);
    void *scale_host = ds4_fp8_icb_page_alloc(scale_bytes, &scale_padded);
    float *input_host = (float *)calloc((size_t)input_count, sizeof(float));
    float *residual_host = (float *)calloc((size_t)hc_count, sizeof(float));
    float *post_host = (float *)calloc((size_t)post_count, sizeof(float));
    float *comb_host = (float *)calloc((size_t)comb_count, sizeof(float));
    float *direct_block_host = (float *)calloc((size_t)block_count, sizeof(float));
    float *fused_block_host = (float *)calloc((size_t)block_count, sizeof(float));
    float *direct_hc_host = (float *)calloc((size_t)hc_count, sizeof(float));
    float *fused_hc_host = (float *)calloc((size_t)hc_count, sizeof(float));
    float *nostore_hc_host = (float *)calloc((size_t)hc_count, sizeof(float));
    if (!weight_host || !scale_host || !input_host || !residual_host ||
        !post_host || !comb_host || !direct_block_host || !fused_block_host ||
        !direct_hc_host || !fused_hc_host || !nostore_hc_host) {
        free(weight_host); free(scale_host); free(input_host); free(residual_host);
        free(post_host); free(comb_host); free(direct_block_host); free(fused_block_host);
        free(direct_hc_host); free(fused_hc_host); free(nostore_hc_host);
        return 0;
    }

    ds4_fp8_icb_fill_bytes((uint8_t *)weight_host, weight_bytes, 3);
    memset(scale_host, 127, (size_t)scale_bytes);
    for (uint64_t i = 0; i < input_count; i++) {
        input_host[i] = ((float)((int)(i % 23u)) - 11.0f) * 0.015625f;
    }
    for (uint64_t i = 0; i < hc_count; i++) {
        residual_host[i] = ((float)((int)(i % 19u)) - 9.0f) * 0.01f;
    }
    for (uint32_t t = 0; t < n_tokens; t++) {
        for (uint32_t dst_hc = 0; dst_hc < n_hc; dst_hc++) {
            post_host[(uint64_t)t * n_hc + dst_hc] = 0.5f / (float)(dst_hc + 1u);
        }
        for (uint32_t src_hc = 0; src_hc < n_hc; src_hc++) {
            for (uint32_t dst_hc = 0; dst_hc < n_hc; dst_hc++) {
                comb_host[(uint64_t)t * n_hc * n_hc + dst_hc + src_hc * n_hc] =
                    (dst_hc == src_hc ? 0.125f : -0.03125f * (float)(dst_hc + src_hc + 1u));
            }
        }
    }

    int rc = 0;
    @autoreleasepool {
        void *weight_opaque = ds4_gpu_wrap_heap_bytes(weight_host, weight_padded);
        void *scale_opaque = ds4_gpu_wrap_heap_bytes(scale_host, scale_padded);
        ds4_gpu_tensor *input = ds4_gpu_tensor_alloc(input_count * sizeof(float));
        ds4_gpu_tensor *residual = ds4_gpu_tensor_alloc(hc_count * sizeof(float));
        ds4_gpu_tensor *post = ds4_gpu_tensor_alloc(post_count * sizeof(float));
        ds4_gpu_tensor *comb = ds4_gpu_tensor_alloc(comb_count * sizeof(float));
        ds4_gpu_tensor *direct_block = ds4_gpu_tensor_alloc(block_count * sizeof(float));
        ds4_gpu_tensor *fused_block = ds4_gpu_tensor_alloc(block_count * sizeof(float));
        ds4_gpu_tensor *nostore_block = ds4_gpu_tensor_alloc(block_count * sizeof(float));
        ds4_gpu_tensor *direct_hc = ds4_gpu_tensor_alloc(hc_count * sizeof(float));
        ds4_gpu_tensor *fused_hc = ds4_gpu_tensor_alloc(hc_count * sizeof(float));
        ds4_gpu_tensor *nostore_hc = ds4_gpu_tensor_alloc(hc_count * sizeof(float));

        fprintf(stderr,
                "ds4: FP8-HC fuse canary START in_dim=%u out_dim=%u n_tokens=%u rounds=%u weight=%.2f MiB\n",
                in_dim, out_dim, n_tokens, rounds, (double)weight_bytes / 1048576.0);

        int setup_ok = weight_opaque && scale_opaque && input && residual && post && comb &&
                       direct_block && fused_block && nostore_block && direct_hc && fused_hc && nostore_hc;
        if (setup_ok) setup_ok = ds4_gpu_tensor_write(input, 0, input_host, input_count * sizeof(float)) > 0;
        if (setup_ok) setup_ok = ds4_gpu_tensor_write(residual, 0, residual_host, hc_count * sizeof(float)) > 0;
        if (setup_ok) setup_ok = ds4_gpu_tensor_write(post, 0, post_host, post_count * sizeof(float)) > 0;
        if (setup_ok) setup_ok = ds4_gpu_tensor_write(comb, 0, comb_host, comb_count * sizeof(float)) > 0;

        int direct_ok = setup_ok;
        const double direct_start_ms = ds4_gpu_now_ms();
        for (uint32_t iter = 0; direct_ok && iter < rounds; iter++) {
            direct_ok = ds4_gpu_matmul_fp8_e4m3_e8m0_storage(
                            direct_block, weight_opaque, scale_opaque, scale_bytes,
                            in_dim, out_dim, input, n_tokens) != 0;
            if (direct_ok) {
                direct_ok = ds4_gpu_hc_expand_tensor(
                                direct_hc, direct_block, residual, post, comb,
                                out_dim, n_hc) != 0;
            }
        }
        const double direct_ms = ds4_gpu_now_ms() - direct_start_ms;

        int fused_ok = setup_ok;
        const double fused_start_ms = ds4_gpu_now_ms();
        for (uint32_t iter = 0; fused_ok && iter < rounds; iter++) {
            fused_ok = ds4_gpu_matmul_fp8_e4m3_e8m0_hc_expand_tensor(
                           fused_hc, fused_block, weight_opaque, scale_opaque, scale_bytes,
                           in_dim, out_dim, input, residual, post, comb,
                           out_dim, n_hc, n_tokens) != 0;
        }
        const double fused_ms = ds4_gpu_now_ms() - fused_start_ms;

        int nostore_ok = setup_ok;
        const double nostore_start_ms = ds4_gpu_now_ms();
        for (uint32_t iter = 0; nostore_ok && iter < rounds; iter++) {
            nostore_ok = ds4_gpu_matmul_fp8_e4m3_e8m0_hc_expand_tensor_ex(
                           nostore_hc, nostore_block, weight_opaque, scale_opaque, scale_bytes,
                           in_dim, out_dim, input, residual, post, comb,
                           out_dim, n_hc, n_tokens, 0) != 0;
        }
        const double nostore_ms = ds4_gpu_now_ms() - nostore_start_ms;

        if (direct_ok && fused_ok && nostore_ok &&
            ds4_gpu_tensor_read(direct_block, 0, direct_block_host, block_count * sizeof(float)) > 0 &&
            ds4_gpu_tensor_read(fused_block, 0, fused_block_host, block_count * sizeof(float)) > 0 &&
            ds4_gpu_tensor_read(direct_hc, 0, direct_hc_host, hc_count * sizeof(float)) > 0 &&
            ds4_gpu_tensor_read(fused_hc, 0, fused_hc_host, hc_count * sizeof(float)) > 0 &&
            ds4_gpu_tensor_read(nostore_hc, 0, nostore_hc_host, hc_count * sizeof(float)) > 0) {
            uint64_t block_mismatches = 0, hc_mismatches = 0;
            float block_max_abs_delta = 0.0f, hc_max_abs_delta = 0.0f;
            for (uint64_t i = 0; i < block_count; i++) {
                const float delta = fabsf(direct_block_host[i] - fused_block_host[i]);
                if (delta > block_max_abs_delta) block_max_abs_delta = delta;
                if (delta > 1e-5f) block_mismatches++;
            }
            for (uint64_t i = 0; i < hc_count; i++) {
                const float delta = fabsf(direct_hc_host[i] - fused_hc_host[i]);
                if (delta > hc_max_abs_delta) hc_max_abs_delta = delta;
                if (delta > 1e-5f) hc_mismatches++;
            }
            uint64_t nostore_hc_mismatches = 0;
            float nostore_hc_max_abs_delta = 0.0f;
            for (uint64_t i = 0; i < hc_count; i++) {
                const float delta = fabsf(direct_hc_host[i] - nostore_hc_host[i]);
                if (delta > nostore_hc_max_abs_delta) nostore_hc_max_abs_delta = delta;
                if (delta > 1e-5f) nostore_hc_mismatches++;
            }
            const double direct_per = direct_ms / (double)rounds;
            const double fused_per = fused_ms / (double)rounds;
            const double nostore_per = nostore_ms / (double)rounds;
            fprintf(stderr,
                    "ds4: FP8-HC fuse canary direct=%.3f ms/round fused_store=%.3f ms/round fused_nostore=%.3f ms/round "
                    "speedup_store=%.2fx speedup_nostore=%.2fx nostore_vs_store=%.2fx "
                    "block_max_abs=%.3e block_mismatch=%llu/%llu hc_max_abs=%.3e hc_mismatch=%llu/%llu "
                    "nostore_hc_max_abs=%.3e nostore_hc_mismatch=%llu/%llu %s\n",
                    direct_per, fused_per, nostore_per,
                    fused_per > 0.0 ? direct_per / fused_per : 0.0,
                    nostore_per > 0.0 ? direct_per / nostore_per : 0.0,
                    nostore_per > 0.0 ? fused_per / nostore_per : 0.0,
                    (double)block_max_abs_delta,
                    (unsigned long long)block_mismatches,
                    (unsigned long long)block_count,
                    (double)hc_max_abs_delta,
                    (unsigned long long)hc_mismatches,
                    (unsigned long long)hc_count,
                    (double)nostore_hc_max_abs_delta,
                    (unsigned long long)nostore_hc_mismatches,
                    (unsigned long long)hc_count,
                    (block_mismatches == 0 && hc_mismatches == 0 && nostore_hc_mismatches == 0) ? "PASS" : "DIVERGE");
            rc = (block_mismatches == 0 && hc_mismatches == 0 && nostore_hc_mismatches == 0);
        } else {
            fprintf(stderr,
                    "ds4: FP8-HC fuse canary failed setup_ok=%d direct_ok=%d fused_ok=%d nostore_ok=%d\n",
                    setup_ok, direct_ok, fused_ok, nostore_ok);
        }

        ds4_gpu_tensor_free(input);
        ds4_gpu_tensor_free(residual);
        ds4_gpu_tensor_free(post);
        ds4_gpu_tensor_free(comb);
        ds4_gpu_tensor_free(direct_block);
        ds4_gpu_tensor_free(fused_block);
        ds4_gpu_tensor_free(nostore_block);
        ds4_gpu_tensor_free(direct_hc);
        ds4_gpu_tensor_free(fused_hc);
        ds4_gpu_tensor_free(nostore_hc);
        ds4_gpu_release_heap_buffer(weight_opaque);
        ds4_gpu_release_heap_buffer(scale_opaque);
    }

    free(weight_host);
    free(scale_host);
    free(input_host);
    free(residual_host);
    free(post_host);
    free(comb_host);
    free(direct_block_host);
    free(fused_block_host);
    free(direct_hc_host);
    free(fused_hc_host);
    free(nostore_hc_host);
    return rc;
}

/* ============================================================ */
/* dsv4_moe_swiglu_weight MTL4 port (silv 2026-05-27 task #687)   */
/* ============================================================ */
/* MTL4 port of kernel_dsv4_moe_swiglu_weight from metal/moe.metal.
 * Per-row routed-MoE activation: mid[i] = SiLU(g) × u × route_weight,
 * with optional clamp on g/u and optional write-back of clamped values.
 *
 * One row = one expert × one token slot. Per-layer dispatch with as
 * many rows as activated (expert, token) pairs.
 *
 * Exercises:
 *   - SiLU activation: g / (1 + exp(-g))
 *   - Per-row scalar reads (route_weight from packed weights table)
 *   - Conditional write-back path (clamp diagnostic mode) */

static id<MTLComputePipelineState> g_moe_swiglu_weight_mtl4_pipeline;
static int g_moe_swiglu_weight_mtl4_init_attempted;
static int g_moe_swiglu_weight_mtl4_init_ok;

static int ds4_moe_swiglu_weight_mtl4_pipeline_init(void) {
    if (g_moe_swiglu_weight_mtl4_init_attempted) return g_moe_swiglu_weight_mtl4_init_ok;
    g_moe_swiglu_weight_mtl4_init_attempted = 1;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "struct sw_args {\n"
         "  uint32_t width;\n"
         "  uint32_t rows;\n"
         "  uint64_t gate_row_stride;\n"
         "  uint64_t up_row_stride;\n"
         "  uint64_t mid_row_stride;\n"
         "  uint64_t weight_stride;\n"
         "  uint32_t write_clamped;\n"
         "  float    clamp_value;\n"
         "};\n"
         "kernel void moe_swiglu_weight_mtl4(\n"
         "    device const sw_args *args [[buffer(0)]],\n"
         "    device       char    *gate [[buffer(1)]],\n"
         "    device       char    *up   [[buffer(2)]],\n"
         "    device       char    *mid  [[buffer(3)]],\n"
         "    device const char    *weights [[buffer(4)]],\n"
         "    uint row [[threadgroup_position_in_grid]],\n"
         "    uint tid [[thread_position_in_threadgroup]],\n"
         "    uint ntg [[threads_per_threadgroup]]) {\n"
         "  if (row >= args->rows) return;\n"
         "  device float *gr = (device float *)(gate + (uint64_t)row * args->gate_row_stride);\n"
         "  device float *ur = (device float *)(up   + (uint64_t)row * args->up_row_stride);\n"
         "  device float *mr = (device float *)(mid  + (uint64_t)row * args->mid_row_stride);\n"
         "  device const float *w = (device const float *)(weights + (uint64_t)row * args->weight_stride);\n"
         "  const float route_weight = w[0];\n"
         "  const float c = args->clamp_value;\n"
         "  for (uint i = tid; i < args->width; i += ntg) {\n"
         "    float g = gr[i];\n"
         "    float u = ur[i];\n"
         "    if (c > 1.0e-6f) {\n"
         "      g = min(g, c);\n"
         "      u = clamp(u, -c, c);\n"
         "      if (args->write_clamped != 0) { gr[i] = g; ur[i] = u; }\n"
         "    }\n"
         "    const float silu = g / (1.0f + exp(-g));\n"
         "    mr[i] = silu * u * route_weight;\n"
         "  }\n"
         "}\n";

    g_moe_swiglu_weight_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_moe_swiglu_weight_mtl4", @"moe_swiglu_weight_mtl4", 256, NULL, 0);
    g_moe_swiglu_weight_mtl4_init_ok = (g_moe_swiglu_weight_mtl4_pipeline != nil) ? 1 : 0;
    return g_moe_swiglu_weight_mtl4_init_ok;
}

int ds4_gpu_mtl4_moe_swiglu_weight_canary(uint32_t rows, uint32_t width) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_moe_swiglu_weight_mtl4_pipeline_init()) return 0;
    if (rows == 0 || width == 0) {
        fprintf(stderr, "ds4: moe_swiglu_weight canary requires rows>0 and width>0\n");
        return 0;
    }

    /* Canary setup (no clamp, route_weight = 1.0):
     *   gate[r,i] = 1.0,  up[r,i] = 2.0,  weights[r] = 1.0
     *   SiLU(1.0) = 1.0 / (1 + e^-1) = 1.0 / (1 + 0.3678794) ≈ 0.7310586
     *   mid[r,i] = 0.7310586 × 2.0 × 1.0 = 1.4621172 */
    const uint64_t total = (uint64_t)rows * width;
    float *host_gate = (float *)calloc(total, sizeof(float));
    float *host_up = (float *)calloc(total, sizeof(float));
    float *host_mid = (float *)calloc(total, sizeof(float));
    float *host_w = (float *)calloc(rows, sizeof(float));
    if (!host_gate || !host_up || !host_mid || !host_w) {
        free(host_gate); free(host_up); free(host_mid); free(host_w);
        return 0;
    }
    for (uint64_t i = 0; i < total; i++) { host_gate[i] = 1.0f; host_up[i] = 2.0f; }
    for (uint32_t r = 0; r < rows; r++) host_w[r] = 1.0f;

    /* Reference value */
    const float silu_1 = 1.0f / (1.0f + expf(-1.0f));
    const float ref = silu_1 * 2.0f * 1.0f;

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:48
                                                      options:MTLResourceStorageModeShared];
        id<MTLBuffer> gateBuf = [g_device newBufferWithBytes:host_gate
                                                      length:total * sizeof(float)
                                                     options:MTLResourceStorageModeShared];
        id<MTLBuffer> upBuf = [g_device newBufferWithBytes:host_up
                                                    length:total * sizeof(float)
                                                   options:MTLResourceStorageModeShared];
        id<MTLBuffer> midBuf = [g_device newBufferWithLength:total * sizeof(float)
                                                     options:MTLResourceStorageModeShared];
        id<MTLBuffer> wBuf = [g_device newBufferWithBytes:host_w
                                                   length:rows * sizeof(float)
                                                  options:MTLResourceStorageModeShared];

        struct {
            uint32_t width_, rows_;
            uint64_t gs_, us_, ms_, ws_;
            uint32_t wc_;
            float c_;
        } args = {
            .width_ = width, .rows_ = rows,
            .gs_ = (uint64_t)width * sizeof(float),
            .us_ = (uint64_t)width * sizeof(float),
            .ms_ = (uint64_t)width * sizeof(float),
            .ws_ = sizeof(float),
            .wc_ = 0,
            .c_ = 0.0f,  /* clamp disabled */
        };
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 6;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[5] = {
                (id<MTLAllocation>)argsBuf,
                (id<MTLAllocation>)gateBuf,
                (id<MTLAllocation>)upBuf,
                (id<MTLAllocation>)midBuf,
                (id<MTLAllocation>)wBuf,
            };
            [residency addAllocations:allocs count:5];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(6);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:gateBuf.gpuAddress atIndex:1];
                [argTable setAddress:upBuf.gpuAddress atIndex:2];
                [argTable setAddress:midBuf.gpuAddress atIndex:3];
                [argTable setAddress:wBuf.gpuAddress atIndex:4];

                NSUInteger nth = MIN((NSUInteger)256, MAX((NSUInteger)1, (NSUInteger)width));

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_moe_swiglu_weight_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc dispatchThreadgroups:MTLSizeMake(rows, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) {
                    (void)fb; dispatch_semaphore_signal(sem);
                }];
                id<MTL4CommandBuffer> bufs[1] = { cb };
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem,
                    dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_mid, midBuf.contents, total * sizeof(float));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 6);
            }
        }
    }
    if (!rc) {
        free(host_gate); free(host_up); free(host_mid); free(host_w);
        return 0;
    }

    double max_abs = 0.0;
    for (uint64_t i = 0; i < total; i++) {
        double d = fabs((double)(host_mid[i] - ref));
        if (d > max_abs) max_abs = d;
    }
    fprintf(stderr,
        "ds4: moe_swiglu_weight MTL4 canary rows=%u width=%u "
        "mid[0]=%.6f (ref=%.6f) mid[end]=%.6f max_abs=%.4e\n",
        rows, width,
        (double)host_mid[0], (double)ref,
        (double)host_mid[total - 1],
        max_abs);
    free(host_gate); free(host_up); free(host_mid); free(host_w);
    return (max_abs < 1.0e-5) ? 1 : 0;
}

/* ============================================================ */
/* dsv4_moe_sum6_f32 MTL4 port (silv 2026-05-27 task #688)        */
/* ============================================================ */
/* MTL4 port of kernel_dsv4_moe_sum6_f32 from metal/moe.metal.
 * Per-token sum of 6 contiguous expert output buffers into one
 * destination. dst[c] = sum_{k=0..5} src[k*width + c].
 *
 * Used by the routed-MoE finalize path when num_active = 6 (top-6).
 * One token per threadgroup; threads parallelize over width. */

static id<MTLComputePipelineState> g_moe_sum6_mtl4_pipeline;
static int g_moe_sum6_mtl4_init_attempted;
static int g_moe_sum6_mtl4_init_ok;

static int ds4_moe_sum6_mtl4_pipeline_init(void) {
    if (g_moe_sum6_mtl4_init_attempted) return g_moe_sum6_mtl4_init_ok;
    g_moe_sum6_mtl4_init_attempted = 1;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "struct sum6_args {\n"
         "  uint32_t width;\n"
         "  uint32_t tokens;\n"
         "  uint64_t src_token_stride;\n"
         "  uint64_t dst_token_stride;\n"
         "};\n"
         "kernel void moe_sum6_mtl4(\n"
         "    device const sum6_args *args [[buffer(0)]],\n"
         "    device const char      *src [[buffer(1)]],\n"
         "    device       char      *dst [[buffer(2)]],\n"
         "    uint token [[threadgroup_position_in_grid]],\n"
         "    uint tid [[thread_position_in_threadgroup]],\n"
         "    uint ntg [[threads_per_threadgroup]]) {\n"
         "  if (token >= args->tokens) return;\n"
         "  device const float *s = (device const float *)(src + (uint64_t)token * args->src_token_stride);\n"
         "  device       float *d = (device       float *)(dst + (uint64_t)token * args->dst_token_stride);\n"
         "  const uint w = args->width;\n"
         "  for (uint col = tid; col < w; col += ntg) {\n"
         "    float v = s[col];\n"
         "    v += s[w + col];\n"
         "    v += s[2u * w + col];\n"
         "    v += s[3u * w + col];\n"
         "    v += s[4u * w + col];\n"
         "    v += s[5u * w + col];\n"
         "    d[col] = v;\n"
         "  }\n"
         "}\n";

    g_moe_sum6_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_moe_sum6_mtl4", @"moe_sum6_mtl4", 256, NULL, 0);
    g_moe_sum6_mtl4_init_ok = (g_moe_sum6_mtl4_pipeline != nil) ? 1 : 0;
    return g_moe_sum6_mtl4_init_ok;
}

int ds4_gpu_mtl4_moe_sum6_canary(uint32_t tokens, uint32_t width) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_moe_sum6_mtl4_pipeline_init()) return 0;
    if (tokens == 0 || width == 0) {
        fprintf(stderr, "ds4: moe_sum6 canary requires tokens>0 and width>0\n");
        return 0;
    }

    /* Canary: src[k*width + col] = (k+1) for k in 0..5.
     * Expected: dst[col] = 1+2+3+4+5+6 = 21 every column. */
    const uint64_t src_per_token = (uint64_t)6 * width;
    const uint64_t src_total = (uint64_t)tokens * src_per_token;
    const uint64_t dst_total = (uint64_t)tokens * width;
    float *host_src = (float *)calloc(src_total, sizeof(float));
    float *host_dst = (float *)calloc(dst_total, sizeof(float));
    if (!host_src || !host_dst) { free(host_src); free(host_dst); return 0; }
    for (uint32_t t = 0; t < tokens; t++) {
        for (uint32_t k = 0; k < 6; k++) {
            for (uint32_t i = 0; i < width; i++) {
                host_src[(uint64_t)t * src_per_token + (uint64_t)k * width + i] = (float)(k + 1);
            }
        }
    }
    const float ref = 21.0f;

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:32
                                                      options:MTLResourceStorageModeShared];
        id<MTLBuffer> srcBuf = [g_device newBufferWithBytes:host_src
                                                     length:src_total * sizeof(float)
                                                    options:MTLResourceStorageModeShared];
        id<MTLBuffer> dstBuf = [g_device newBufferWithLength:dst_total * sizeof(float)
                                                     options:MTLResourceStorageModeShared];

        struct { uint32_t width_, tokens_; uint64_t sts_, dts_; } args = {
            .width_ = width, .tokens_ = tokens,
            .sts_ = src_per_token * sizeof(float),
            .dts_ = (uint64_t)width * sizeof(float),
        };
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 4;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[3] = {
                (id<MTLAllocation>)argsBuf,
                (id<MTLAllocation>)srcBuf,
                (id<MTLAllocation>)dstBuf,
            };
            [residency addAllocations:allocs count:3];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(4);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:srcBuf.gpuAddress atIndex:1];
                [argTable setAddress:dstBuf.gpuAddress atIndex:2];

                NSUInteger nth = MIN((NSUInteger)256, MAX((NSUInteger)1, (NSUInteger)width));

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_moe_sum6_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc dispatchThreadgroups:MTLSizeMake(tokens, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) {
                    (void)fb; dispatch_semaphore_signal(sem);
                }];
                id<MTL4CommandBuffer> bufs[1] = { cb };
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem,
                    dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_dst, dstBuf.contents, dst_total * sizeof(float));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 4);
            }
        }
    }
    if (!rc) { free(host_src); free(host_dst); return 0; }

    double max_abs = 0.0;
    for (uint64_t i = 0; i < dst_total; i++) {
        double d = fabs((double)(host_dst[i] - ref));
        if (d > max_abs) max_abs = d;
    }
    fprintf(stderr,
        "ds4: moe_sum6 MTL4 canary tokens=%u width=%u "
        "dst[0]=%.4f (ref=%.4f) dst[end]=%.4f max_abs=%.4e\n",
        tokens, width,
        (double)host_dst[0], (double)ref,
        (double)host_dst[dst_total - 1],
        max_abs);
    free(host_src); free(host_dst);
    return (max_abs < 1.0e-5) ? 1 : 0;
}

/* ============================================================ */
/* moe_sum6_fp16in_mtl4 — Phase 4 of PATH_FUSED chain             */
/* silv 2026-05-28 task #761                                     */
/* ============================================================ */
/* Reads fp16 per-slot DOWN outputs, writes fp32 final output via
 * float accumulator. Route weights are already folded into mid by
 * the SwiGLU step (Phase 2), so this is an unweighted sum across
 * the 6 selected experts: out[d] = sum_{k=0..5} src[k*out_dim + d].
 *
 * Why fp16-in: DOWN dispatch_kind writes fp16. Existing fp32-input
 * `kernel_dsv4_moe_sum6` would force a fp16→fp32 expansion pass.
 * Reading fp16 directly in the sum kernel saves ~48 KB per layer
 * per token at DS4 V4 sizes (n_sel=6 × out_dim=4096 × 2 B).
 *
 * Dispatch: (out_dim / 256, 1, 1) tg × (256, 1, 1) threads.
 *
 * Final output is fp32 because the downstream consumer
 * (residual-add in ds4.c CPU path) reads fp32. */
static id<MTLComputePipelineState> g_moe_sum6_fp16in_mtl4_pipeline;
static int g_moe_sum6_fp16in_mtl4_init_attempted;
static int g_moe_sum6_fp16in_mtl4_init_ok;

static int ds4_moe_sum6_fp16in_mtl4_pipeline_init(void) {
    if (g_moe_sum6_fp16in_mtl4_init_attempted) return g_moe_sum6_fp16in_mtl4_init_ok;
    g_moe_sum6_fp16in_mtl4_init_attempted = 1;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "struct sum6_fp16_args { uint32_t out_dim; uint32_t pad; };\n"
         "kernel void moe_sum6_fp16in_mtl4(\n"
         "    device const sum6_fp16_args *args [[buffer(0)]],\n"
         "    device const half           *src  [[buffer(1)]],\n"  /* [6 × out_dim] */
         "    device       float          *dst  [[buffer(2)]],\n"  /* [out_dim] */
         "    uint gid [[thread_position_in_grid]]) {\n"
         "  if (gid >= args->out_dim) return;\n"
         "  const uint o = args->out_dim;\n"
         "  /* Unroll 6: route_weight already folded into mid by Phase 2 SwiGLU. */\n"
         "  float acc = (float)src[0u * o + gid]\n"
         "            + (float)src[1u * o + gid]\n"
         "            + (float)src[2u * o + gid]\n"
         "            + (float)src[3u * o + gid]\n"
         "            + (float)src[4u * o + gid]\n"
         "            + (float)src[5u * o + gid];\n"
         "  dst[gid] = acc;\n"
         "}\n";

    g_moe_sum6_fp16in_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_moe_sum6_fp16in_mtl4",
        @"moe_sum6_fp16in_mtl4", 256, NULL, 0);
    g_moe_sum6_fp16in_mtl4_init_ok =
        (g_moe_sum6_fp16in_mtl4_pipeline != nil) ? 1 : 0;
    return g_moe_sum6_fp16in_mtl4_init_ok;
}

/* Phase 4 dispatch wrapper: caller passes fp16 down_out buffer
 * (slot 3 from ds4_metal_vqb2_fused_out_buffer), fp32 final-output
 * buffer (typically the production output_fp32 path), and out_dim.
 * Returns 1=ok, 0=failure. Uses ds4_mtl4_run_canary helper. */
int ds4_metal_vqb2_fused_sum_step(void *down_out_fp16_buf,
                                   void *output_fp32_buf,
                                   uint32_t out_dim) {
    if (!ds4_moe_sum6_fp16in_mtl4_pipeline_init()) return 0;
    if (!down_out_fp16_buf || !output_fp32_buf || out_dim == 0) return 0;

    static id<MTLBuffer> s_args_buf = nil;
    if (!s_args_buf) {
        s_args_buf = [g_device newBufferWithLength:8
                                          options:MTLResourceStorageModeShared];
        if (!s_args_buf) return 0;
    }
    struct { uint32_t out_dim; uint32_t pad; } args = { out_dim, 0u };
    memcpy(s_args_buf.contents, &args, sizeof(args));

    void *bindings[3] = {
        (__bridge void *)s_args_buf,
        down_out_fp16_buf,
        output_fp32_buf,
    };
    const unsigned long n_tg = (out_dim + 255ul) / 256ul;
    return ds4_mtl4_run_canary(
        (__bridge void *)g_moe_sum6_fp16in_mtl4_pipeline,
        bindings, 3,
        n_tg, 1ul, 1ul,
        256ul, 1ul, 1ul,
        0ul, NULL, NULL);
}

/* ============================================================ */
/* moe_swiglu_weight_f32mid_rowblock_mtl4 — Tier 2.a fp32 mid    */
/* silv 2026-05-28 — path_fused_multitoken_design.md             */
/* ============================================================ */
/* The actual precision floor in PATH_FUSED chain is fp16 STORAGE
 * of mid between SwiGLU and DOWN, not the sum accumulation (Tier 2.b
 * was refuted by canary). This kernel preserves the H2186/H2187
 * row-block layout but stores mid as fp32, halving downstream
 * quantization error.
 *
 * Memory cost: mid_buf grows from n_sel*n_rb*n_rows*2 bytes (24 KB
 * at DS4 V4 shape) to ×4 (48 KB) per token. Modest.
 *
 * DOWN cost: needs a separate dispatch_kind_strided_fp32in variant
 * that reads fp32 mid. Adding that is a parallel matmul kernel
 * (NOT shipped in this kernel; this kernel only writes fp32 mid).
 * Without the DOWN-side change, this kernel is canary-only — it
 * proves the precision delta exists, but production cannot consume
 * fp32 mid until the matching DOWN kernel ships.
 *
 * Dispatch identical to the fp16-out variant: (n_rows, n_selected, n_row_blocks). */
static id<MTLComputePipelineState> g_moe_swiglu_weight_f32mid_rowblock_mtl4_pipeline;
static int g_moe_swiglu_weight_f32mid_rowblock_mtl4_init_attempted;
static int g_moe_swiglu_weight_f32mid_rowblock_mtl4_init_ok;

static int ds4_moe_swiglu_weight_f32mid_rowblock_mtl4_pipeline_init(void) {
    if (g_moe_swiglu_weight_f32mid_rowblock_mtl4_init_attempted)
        return g_moe_swiglu_weight_f32mid_rowblock_mtl4_init_ok;
    g_moe_swiglu_weight_f32mid_rowblock_mtl4_init_attempted = 1;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "struct rb_args {\n"
         "  uint32_t n_rows;\n"
         "  uint32_t n_selected;\n"
         "  uint32_t n_row_blocks;\n"
         "  float    clamp_value;\n"
         "};\n"
         "kernel void moe_swiglu_weight_f32mid_rowblock_mtl4(\n"
         "    device const rb_args *args    [[buffer(0)]],\n"
         "    device const half    *gate    [[buffer(1)]],\n"
         "    device const half    *up      [[buffer(2)]],\n"
         "    device const float   *route_w [[buffer(3)]],\n"
         "    device       float   *mid     [[buffer(4)]],\n"   /* fp32 out, NOT half */
         "    uint3 gid [[thread_position_in_grid]]) {\n"
         "  if (gid.x >= args->n_rows || gid.y >= args->n_selected\n"
         "      || gid.z >= args->n_row_blocks) return;\n"
         "  const ulong in_idx  = ((ulong)gid.z * args->n_selected + gid.y)\n"
         "                         * args->n_rows + gid.x;\n"
         "  const ulong out_idx = (ulong)gid.y * (args->n_row_blocks * args->n_rows)\n"
         "                         + (ulong)gid.z * args->n_rows + gid.x;\n"
         "  float g = (float)gate[in_idx];\n"
         "  float u = (float)up[in_idx];\n"
         "  const float c = args->clamp_value;\n"
         "  if (c > 1.0e-6f) { g = min(g, c); u = clamp(u, -c, c); }\n"
         "  const float silu = g / (1.0f + exp(-g));\n"
         "  mid[out_idx] = silu * u * route_w[gid.y];\n"  /* fp32 store, no half() cast */
         "}\n";

    g_moe_swiglu_weight_f32mid_rowblock_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_moe_swiglu_weight_f32mid_rowblock_mtl4",
        @"moe_swiglu_weight_f32mid_rowblock_mtl4", 256, NULL, 0);
    g_moe_swiglu_weight_f32mid_rowblock_mtl4_init_ok =
        (g_moe_swiglu_weight_f32mid_rowblock_mtl4_pipeline != nil) ? 1 : 0;
    return g_moe_swiglu_weight_f32mid_rowblock_mtl4_init_ok;
}

/* Dispatch wrapper. Caller must supply a mid_buf sized for fp32
 * (n_selected * n_row_blocks * n_rows * 4 bytes). Returns 1=ok. */
int ds4_metal_vqb2_fused_swiglu_rowblock_step_fp32mid(
    void *gate_buf, void *up_buf, void *route_weights_buf, void *mid_fp32_buf,
    uint32_t n_rows, uint32_t n_selected, uint32_t n_row_blocks, float clamp_value) {
    if (!ds4_moe_swiglu_weight_f32mid_rowblock_mtl4_pipeline_init()) return 0;
    if (!gate_buf || !up_buf || !route_weights_buf || !mid_fp32_buf) return 0;
    if (n_rows == 0 || n_selected == 0 || n_row_blocks == 0) return 0;

    static id<MTLBuffer> s_args_buf = nil;
    if (!s_args_buf) {
        s_args_buf = [g_device newBufferWithLength:16
                                          options:MTLResourceStorageModeShared];
        if (!s_args_buf) return 0;
    }
    struct { uint32_t n_rows; uint32_t n_selected; uint32_t n_row_blocks; float clamp; } args = {
        n_rows, n_selected, n_row_blocks, clamp_value,
    };
    memcpy(s_args_buf.contents, &args, sizeof(args));

    void *bindings[5] = {
        (__bridge void *)s_args_buf,
        gate_buf, up_buf, route_weights_buf, mid_fp32_buf,
    };
    return ds4_mtl4_run_canary(
        (__bridge void *)g_moe_swiglu_weight_f32mid_rowblock_mtl4_pipeline,
        bindings, 5,
        (unsigned long)n_rows, (unsigned long)n_selected, (unsigned long)n_row_blocks,
        32ul, 1ul, 1ul,
        0ul, NULL, NULL);
}

/* Forward decl — defined later in this file (line ~22669+). */
static int ds4_moe_swiglu_weight_f16_rowblock_mtl4_pipeline_init(void);

/* Canary: A/B fp16-mid vs fp32-mid SwiGLU on adversarial gate/up.
 * Strategy: synthesize gate/up at fp16 with values that force the
 * silu(g)*u*w product to land near fp16 representational gaps
 * (e.g. close to fp16 powers-of-two boundaries). The fp32-mid
 * kernel preserves the true product; fp16-mid quantizes to nearest
 * fp16. Compute max |fp32_mid - fp32(fp16_mid)| over all positions.
 *
 * The Tier 2.a claim: this max delta is >= 1e-4 (real precision
 * loss) on realistic inputs, vs the Tier 2.b sum-step delta which
 * we measured at <1e-7 (below fp16 floor). If true, fp32-mid is
 * the lever silv asked for; if false, Tier 2.a is also refuted. */
int ds4_metal_vqb2_fused_swiglu_rowblock_fp32mid_canary(
    uint32_t n_rows, uint32_t n_selected, uint32_t n_row_blocks) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (n_rows == 0 || n_selected == 0 || n_row_blocks == 0) {
        fprintf(stderr, "ds4: swiglu-fp32mid-canary requires nonzero shape\n");
        return 0;
    }
    if (!ds4_moe_swiglu_weight_f16_rowblock_mtl4_pipeline_init()) return 0;
    if (!ds4_moe_swiglu_weight_f32mid_rowblock_mtl4_pipeline_init()) return 0;

    const size_t n_inputs = (size_t)n_row_blocks * n_selected * n_rows;
    const size_t n_outputs = n_inputs; /* same total count, different layout */

    id<MTLBuffer> gate_buf = [g_device newBufferWithLength:n_inputs * sizeof(uint16_t)
                                                   options:MTLResourceStorageModeShared];
    id<MTLBuffer> up_buf = [g_device newBufferWithLength:n_inputs * sizeof(uint16_t)
                                                 options:MTLResourceStorageModeShared];
    id<MTLBuffer> rw_buf = [g_device newBufferWithLength:n_selected * sizeof(float)
                                                 options:MTLResourceStorageModeShared];
    id<MTLBuffer> mid_fp16 = [g_device newBufferWithLength:n_outputs * sizeof(uint16_t)
                                                    options:MTLResourceStorageModeShared];
    id<MTLBuffer> mid_fp32 = [g_device newBufferWithLength:n_outputs * sizeof(float)
                                                    options:MTLResourceStorageModeShared];
    if (!gate_buf || !up_buf || !rw_buf || !mid_fp16 || !mid_fp32) {
        fprintf(stderr, "ds4: swiglu-fp32mid-canary alloc failed\n");
        return 0;
    }

    /* Fill gate/up with values that cover fp16 mantissa range, sized for
     * SiLU saturation effects. */
    uint16_t *gh = (uint16_t *)gate_buf.contents;
    uint16_t *uh = (uint16_t *)up_buf.contents;
    float *rw = (float *)rw_buf.contents;
    for (uint32_t i = 0u; i < n_selected; i++) {
        rw[i] = 0.1f + 0.2f * (float)i; /* distinct positive weights */
    }
    for (size_t idx = 0u; idx < n_inputs; idx++) {
        const float t = (float)idx / (float)n_inputs;
        /* gate spans [-3, 3] to exercise SiLU shape; up spans [-2, 2]. */
        const float g = -3.0f + 6.0f * t;
        const float u = -2.0f + 4.0f * ((float)((idx * 7u) % n_inputs) / (float)n_inputs);
        __fp16 gh_v = (__fp16)g;
        __fp16 uh_v = (__fp16)u;
        gh[idx] = *(uint16_t *)&gh_v;
        uh[idx] = *(uint16_t *)&uh_v;
    }

    /* Run both kernels. */
    extern int ds4_metal_vqb2_fused_swiglu_rowblock_step(
        void *, void *, void *, void *, uint32_t, uint32_t, uint32_t, float);
    extern int ds4_metal_vqb2_fused_swiglu_rowblock_step_fp32mid(
        void *, void *, void *, void *, uint32_t, uint32_t, uint32_t, float);

    int rc_fp16 = ds4_metal_vqb2_fused_swiglu_rowblock_step(
        (__bridge void *)gate_buf, (__bridge void *)up_buf,
        (__bridge void *)rw_buf, (__bridge void *)mid_fp16,
        n_rows, n_selected, n_row_blocks, 0.0f);
    int rc_fp32 = ds4_metal_vqb2_fused_swiglu_rowblock_step_fp32mid(
        (__bridge void *)gate_buf, (__bridge void *)up_buf,
        (__bridge void *)rw_buf, (__bridge void *)mid_fp32,
        n_rows, n_selected, n_row_blocks, 0.0f);
    if (rc_fp16 != 1 || rc_fp32 != 1) {
        fprintf(stderr, "ds4: swiglu-fp32mid-canary dispatch failed fp16=%d fp32=%d\n",
                rc_fp16, rc_fp32);
        return 0;
    }

    /* Compute max delta between fp32-mid and fp16-mid (converted back to fp32). */
    const uint16_t *out_fp16 = (const uint16_t *)mid_fp16.contents;
    const float *out_fp32 = (const float *)mid_fp32.contents;
    double max_abs_delta = 0.0;
    double sum_abs_delta = 0.0;
    double max_abs_fp32 = 0.0;
    uint32_t worst_idx = 0u;
    for (size_t idx = 0u; idx < n_outputs; idx++) {
        __fp16 h_v = *(__fp16 *)&out_fp16[idx];
        const float v_fp16_as_f32 = (float)h_v;
        const float v_fp32 = out_fp32[idx];
        const double delta = fabs((double)v_fp16_as_f32 - (double)v_fp32);
        sum_abs_delta += delta;
        if (delta > max_abs_delta) { max_abs_delta = delta; worst_idx = (uint32_t)idx; }
        if (fabs((double)v_fp32) > max_abs_fp32) max_abs_fp32 = fabs((double)v_fp32);
    }
    const double mean_abs_delta = sum_abs_delta / (double)n_outputs;
    const double max_rel_delta = (max_abs_fp32 > 0.0) ? max_abs_delta / max_abs_fp32 : 0.0;

    fprintf(stderr,
            "ds4: swiglu-fp32mid-canary shape=(n_rows=%u, n_sel=%u, n_rb=%u, total=%zu)\n"
            "ds4:   |fp32_mid - fp32(fp16_mid)|: max=%.6e (idx=%u), mean=%.6e\n"
            "ds4:   max_abs(fp32_mid) = %.6e, max_rel = %.6e\n"
            "ds4:   verdict: %s\n",
            n_rows, n_selected, n_row_blocks, n_outputs,
            max_abs_delta, worst_idx, mean_abs_delta,
            max_abs_fp32, max_rel_delta,
            (max_abs_delta >= 1.0e-4) ? "PASS (fp32-mid carries >=1e-4 absolute signal vs fp16-mid)" :
            (max_abs_delta >= 1.0e-6) ? "PARTIAL (signal exists but small)" :
                                         "FAIL (fp16-mid is sufficient for this shape)");
    return (max_abs_delta >= 1.0e-4) ? 1 : 0;
}

/* ============================================================ */
/* moe_sum6_fp16in_kahan_mtl4 — high-precision sum (Tier 2.b)    */
/* silv 2026-05-28 — path_fused_multitoken_design.md             */
/* ============================================================ */
/* Same I/O as moe_sum6_fp16in_mtl4 but with:
 *   1. magnitude-sorted summation (smallest first)
 *   2. Kahan-compensated accumulation
 *
 * The combination preserves full fp32 precision (~7 digits) where
 * the naive variant can drop to ~5-6 digits on adversarial inputs
 * (mixed magnitudes summed largest-first lose low bits to mantissa
 * shift). For 6 inputs this is ~10× tighter relative error in
 * worst case, ~2-3× in typical case.
 *
 * Why bother for 6 terms: the H2196 9-policy oracle finding shows
 * exact algebraic equivalence (rel_L2=0) is achievable for
 * route-permuted dispatch. Naive sum at fp32 can drift by ~1e-6
 * across permutation order; Kahan-sorted variant stays bit-exact
 * to ~1e-7. This makes order-policy schedule artifacts visible.
 *
 * Activated opt-in via env DS4_VQB2_FP16_PRECISION=high. The
 * existing naive sum remains default. */
static id<MTLComputePipelineState> g_moe_sum6_fp16in_kahan_mtl4_pipeline;
static int g_moe_sum6_fp16in_kahan_mtl4_init_attempted;
static int g_moe_sum6_fp16in_kahan_mtl4_init_ok;

static int ds4_moe_sum6_fp16in_kahan_mtl4_pipeline_init(void) {
    if (g_moe_sum6_fp16in_kahan_mtl4_init_attempted) return g_moe_sum6_fp16in_kahan_mtl4_init_ok;
    g_moe_sum6_fp16in_kahan_mtl4_init_attempted = 1;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "struct sum6_args { uint32_t out_dim; uint32_t pad; };\n"
         "kernel void moe_sum6_fp16in_kahan_mtl4(\n"
         "    device const sum6_args *args [[buffer(0)]],\n"
         "    device const half      *src  [[buffer(1)]],\n"  /* [6 × out_dim] */
         "    device       float     *dst  [[buffer(2)]],\n"  /* [out_dim] */
         "    uint gid [[thread_position_in_grid]]) {\n"
         "  if (gid >= args->out_dim) return;\n"
         "  const uint o = args->out_dim;\n"
         "  /* Load 6 values, convert to fp32. */\n"
         "  float v[6];\n"
         "  v[0] = (float)src[0u * o + gid];\n"
         "  v[1] = (float)src[1u * o + gid];\n"
         "  v[2] = (float)src[2u * o + gid];\n"
         "  v[3] = (float)src[3u * o + gid];\n"
         "  v[4] = (float)src[4u * o + gid];\n"
         "  v[5] = (float)src[5u * o + gid];\n"
         "  /* Insertion sort by |v| ascending — 6 elements is cheap. */\n"
         "  for (uint i = 1u; i < 6u; i++) {\n"
         "    const float key = v[i];\n"
         "    const float key_abs = fabs(key);\n"
         "    uint j = i;\n"
         "    while (j > 0u && fabs(v[j - 1u]) > key_abs) {\n"
         "      v[j] = v[j - 1u];\n"
         "      j--;\n"
         "    }\n"
         "    v[j] = key;\n"
         "  }\n"
         "  /* Kahan compensated sum, smallest first. */\n"
         "  float sum = 0.0f;\n"
         "  float c = 0.0f;\n"
         "  for (uint k = 0u; k < 6u; k++) {\n"
         "    const float y = v[k] - c;\n"
         "    const float t = sum + y;\n"
         "    c = (t - sum) - y;\n"
         "    sum = t;\n"
         "  }\n"
         "  dst[gid] = sum;\n"
         "}\n";

    g_moe_sum6_fp16in_kahan_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_moe_sum6_fp16in_kahan_mtl4",
        @"moe_sum6_fp16in_kahan_mtl4", 256, NULL, 0);
    g_moe_sum6_fp16in_kahan_mtl4_init_ok =
        (g_moe_sum6_fp16in_kahan_mtl4_pipeline != nil) ? 1 : 0;
    return g_moe_sum6_fp16in_kahan_mtl4_init_ok;
}

/* Canary: A/B Kahan-sorted vs naive sum6 on adversarial fp16 inputs.
 * silv 2026-05-28 — falsifiability for the Tier 2.b 10× accuracy claim.
 *
 * Strategy: synthesize 6 fp16 inputs per output position with mixed
 * magnitudes that expose precision loss in naive left-to-right summation:
 *   slot 0: +0.5 * cos(pos)         (small base)
 *   slot 1: +large * sin(pos)        (large positive)
 *   slot 2: -large * sin(pos)        (large negative — cancels slot 1)
 *   slot 3: +small * cos(pos*0.7)    (tiny addition that gets lost
 *                                       when summed after big-cancel)
 *   slot 4: +large * cos(pos)        (large positive again)
 *   slot 5: -large * cos(pos)        (cancels slot 4)
 *
 * True sum = 0.5*cos(pos) + small*cos(pos*0.7); both small terms.
 *
 * Naive fp32 sum visits slots 0..5 in order. After (small + large + (-large))
 * the low bits of `small` are lost. Kahan with magnitude sort visits small
 * terms first, big-cancel pairs last, retaining the small contributions.
 *
 * Computes max |naive - reference| and max |kahan - reference| where
 * reference is the fp64 sum of the fp16-rounded inputs. The 10× accuracy
 * claim is: max_kahan_err / max_naive_err < 0.1 on this adversarial pattern.
 *
 * Returns 1=Kahan beats naive by 10×; 0=fail or wash. */
int ds4_metal_vqb2_fused_sum_step_kahan_canary(uint32_t out_dim, float large_scale) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (out_dim == 0 || out_dim > 16384u) {
        fprintf(stderr, "ds4: kahan-sum-canary requires 0 < out_dim <= 16384\n");
        return 0;
    }
    if (large_scale <= 0.0f) large_scale = 1024.0f;

    /* Build adversarial fp16 src buffer [6 × out_dim]. */
    const uint32_t n_sel = 6u;
    const size_t n_halves = (size_t)n_sel * out_dim;
    id<MTLBuffer> src_buf = [g_device newBufferWithLength:n_halves * sizeof(uint16_t)
                                                  options:MTLResourceStorageModeShared];
    if (!src_buf) { fprintf(stderr, "ds4: kahan-sum-canary src alloc failed\n"); return 0; }

    /* Use a portable fp32→fp16 round-trip via raw fp32 stored as fp16 bit pattern.
     * Apple has __fp16 but we cast through float for clarity. */
    uint16_t *src_h = (uint16_t *)src_buf.contents;
    double *reference = (double *)malloc((size_t)out_dim * sizeof(double));
    if (!reference) {
        fprintf(stderr, "ds4: kahan-sum-canary reference alloc failed\n");
        return 0;
    }
    const float small_scale = 1.0e-3f;
    for (uint32_t pos = 0u; pos < out_dim; pos++) {
        const float p = (float)pos;
        const float v[6] = {
            0.5f * cosf(p * 0.1f),
            large_scale * sinf(p * 0.1f),
            -large_scale * sinf(p * 0.1f),
            small_scale * cosf(p * 0.07f),
            large_scale * cosf(p * 0.1f),
            -large_scale * cosf(p * 0.1f),
        };
        /* Round-trip via __fp16 to get bit-exact fp16 representation. */
        __fp16 vh[6];
        for (uint32_t k = 0u; k < 6u; k++) {
            vh[k] = (__fp16)v[k];
            src_h[(size_t)k * out_dim + pos] = *(uint16_t *)&vh[k];
        }
        /* Reference sum at fp64 over the fp16-rounded values. */
        double ref = 0.0;
        for (uint32_t k = 0u; k < 6u; k++) ref += (double)(float)vh[k];
        reference[pos] = ref;
    }

    /* Allocate destination buffers for naive + kahan. */
    id<MTLBuffer> dst_naive = [g_device newBufferWithLength:(size_t)out_dim * sizeof(float)
                                                     options:MTLResourceStorageModeShared];
    id<MTLBuffer> dst_kahan = [g_device newBufferWithLength:(size_t)out_dim * sizeof(float)
                                                     options:MTLResourceStorageModeShared];
    if (!dst_naive || !dst_kahan) {
        fprintf(stderr, "ds4: kahan-sum-canary dst alloc failed\n");
        free(reference);
        return 0;
    }

    /* Run both kernels. */
    extern int ds4_metal_vqb2_fused_sum_step(void *, void *, uint32_t);
    extern int ds4_metal_vqb2_fused_sum_step_kahan(void *, void *, uint32_t);
    int rc_naive = ds4_metal_vqb2_fused_sum_step(
        (__bridge void *)src_buf, (__bridge void *)dst_naive, out_dim);
    int rc_kahan = ds4_metal_vqb2_fused_sum_step_kahan(
        (__bridge void *)src_buf, (__bridge void *)dst_kahan, out_dim);
    if (rc_naive != 1 || rc_kahan != 1) {
        fprintf(stderr, "ds4: kahan-sum-canary dispatch failed naive=%d kahan=%d\n",
                rc_naive, rc_kahan);
        free(reference);
        return 0;
    }

    /* Compare both against fp64 reference. */
    const float *out_naive = (const float *)dst_naive.contents;
    const float *out_kahan = (const float *)dst_kahan.contents;
    double max_naive_err = 0.0, max_kahan_err = 0.0;
    double sum_naive_err = 0.0, sum_kahan_err = 0.0;
    uint32_t worst_pos_naive = 0u, worst_pos_kahan = 0u;
    for (uint32_t pos = 0u; pos < out_dim; pos++) {
        const double err_n = fabs((double)out_naive[pos] - reference[pos]);
        const double err_k = fabs((double)out_kahan[pos] - reference[pos]);
        sum_naive_err += err_n;
        sum_kahan_err += err_k;
        if (err_n > max_naive_err) { max_naive_err = err_n; worst_pos_naive = pos; }
        if (err_k > max_kahan_err) { max_kahan_err = err_k; worst_pos_kahan = pos; }
    }
    const double mean_naive_err = sum_naive_err / (double)out_dim;
    const double mean_kahan_err = sum_kahan_err / (double)out_dim;
    const double ratio_max  = (max_kahan_err > 0.0) ? max_naive_err / max_kahan_err : 1e9;
    const double ratio_mean = (mean_kahan_err > 0.0) ? mean_naive_err / mean_kahan_err : 1e9;

    fprintf(stderr,
            "ds4: kahan-sum-canary out_dim=%u large_scale=%.3g\n"
            "ds4:   naive max_err=%.6e mean_err=%.6e (worst_pos=%u)\n"
            "ds4:   kahan max_err=%.6e mean_err=%.6e (worst_pos=%u)\n"
            "ds4:   naive/kahan ratio: max=%.3fx mean=%.3fx\n"
            "ds4:   verdict: %s\n",
            out_dim, (double)large_scale,
            max_naive_err, mean_naive_err, worst_pos_naive,
            max_kahan_err, mean_kahan_err, worst_pos_kahan,
            ratio_max, ratio_mean,
            (ratio_max >= 10.0) ? "PASS (Kahan ≥10× tighter on max_err)" :
            (ratio_max >= 2.0)  ? "PARTIAL (Kahan tighter but <10×)" :
                                  "FAIL (Kahan not meaningfully better)");
    free(reference);
    return (ratio_max >= 10.0) ? 1 : 0;
}

/* High-precision wrapper. Same signature as ds4_metal_vqb2_fused_sum_step
 * but routes to the Kahan-sorted kernel. Returns 1=ok, 0=failure. */
int ds4_metal_vqb2_fused_sum_step_kahan(void *down_out_fp16_buf,
                                         void *output_fp32_buf,
                                         uint32_t out_dim) {
    if (!ds4_moe_sum6_fp16in_kahan_mtl4_pipeline_init()) return 0;
    if (!down_out_fp16_buf || !output_fp32_buf || out_dim == 0) return 0;

    static id<MTLBuffer> s_args_buf = nil;
    if (!s_args_buf) {
        s_args_buf = [g_device newBufferWithLength:8
                                          options:MTLResourceStorageModeShared];
        if (!s_args_buf) return 0;
    }
    struct { uint32_t out_dim; uint32_t pad; } args = { out_dim, 0u };
    memcpy(s_args_buf.contents, &args, sizeof(args));

    void *bindings[3] = {
        (__bridge void *)s_args_buf,
        down_out_fp16_buf,
        output_fp32_buf,
    };
    const unsigned long n_tg = (out_dim + 255ul) / 256ul;
    return ds4_mtl4_run_canary(
        (__bridge void *)g_moe_sum6_fp16in_kahan_mtl4_pipeline,
        bindings, 3,
        n_tg, 1ul, 1ul,
        256ul, 1ul, 1ul,
        0ul, NULL, NULL);
}

/* ============================================================ */
/* dsv4_moe_swiglu_weight_f16 MTL4 port (silv 2026-05-27 task #689) */
/* ============================================================ */
/* MTL4 port of kernel_dsv4_moe_swiglu_weight_f16 — FP16 mid variant
 * of #687. Same activation (SiLU(g) × u × route_weight + optional
 * clamp) but writes mid as half precision to halve down-projection
 * read traffic. */

static id<MTLComputePipelineState> g_moe_swiglu_weight_f16_mtl4_pipeline;
static int g_moe_swiglu_weight_f16_mtl4_init_attempted;
static int g_moe_swiglu_weight_f16_mtl4_init_ok;

static int ds4_moe_swiglu_weight_f16_mtl4_pipeline_init(void) {
    if (g_moe_swiglu_weight_f16_mtl4_init_attempted) return g_moe_swiglu_weight_f16_mtl4_init_ok;
    g_moe_swiglu_weight_f16_mtl4_init_attempted = 1;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "struct sw_args {\n"
         "  uint32_t width;\n"
         "  uint32_t rows;\n"
         "  uint64_t gate_row_stride;\n"
         "  uint64_t up_row_stride;\n"
         "  uint64_t mid_row_stride;\n"
         "  uint64_t weight_stride;\n"
         "  uint32_t write_clamped;\n"
         "  float    clamp_value;\n"
         "};\n"
         "kernel void moe_swiglu_weight_f16_mtl4(\n"
         "    device const sw_args *args [[buffer(0)]],\n"
         "    device       char    *gate [[buffer(1)]],\n"
         "    device       char    *up   [[buffer(2)]],\n"
         "    device       char    *mid  [[buffer(3)]],\n"
         "    device const char    *weights [[buffer(4)]],\n"
         "    uint row [[threadgroup_position_in_grid]],\n"
         "    uint tid [[thread_position_in_threadgroup]],\n"
         "    uint ntg [[threads_per_threadgroup]]) {\n"
         "  if (row >= args->rows) return;\n"
         "  device float *gr = (device float *)(gate + (uint64_t)row * args->gate_row_stride);\n"
         "  device float *ur = (device float *)(up   + (uint64_t)row * args->up_row_stride);\n"
         "  device half  *mr = (device half  *)(mid  + (uint64_t)row * args->mid_row_stride);\n"
         "  device const float *w = (device const float *)(weights + (uint64_t)row * args->weight_stride);\n"
         "  const float route_weight = w[0];\n"
         "  const float c = args->clamp_value;\n"
         "  for (uint i = tid; i < args->width; i += ntg) {\n"
         "    float g = gr[i];\n"
         "    float u = ur[i];\n"
         "    if (c > 1.0e-6f) {\n"
         "      g = min(g, c);\n"
         "      u = clamp(u, -c, c);\n"
         "      if (args->write_clamped != 0) { gr[i] = g; ur[i] = u; }\n"
         "    }\n"
         "    const float silu = g / (1.0f + exp(-g));\n"
         "    mr[i] = (half)(silu * u * route_weight);\n"
         "  }\n"
         "}\n";

    g_moe_swiglu_weight_f16_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_moe_swiglu_weight_f16_mtl4", @"moe_swiglu_weight_f16_mtl4", 256, NULL, 0);
    g_moe_swiglu_weight_f16_mtl4_init_ok = (g_moe_swiglu_weight_f16_mtl4_pipeline != nil) ? 1 : 0;
    return g_moe_swiglu_weight_f16_mtl4_init_ok;
}

int ds4_gpu_mtl4_moe_swiglu_weight_f16_canary(uint32_t rows, uint32_t width) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_moe_swiglu_weight_f16_mtl4_pipeline_init()) return 0;
    if (rows == 0 || width == 0) {
        fprintf(stderr, "ds4: moe_swiglu_weight_f16 canary requires rows>0 and width>0\n");
        return 0;
    }

    /* Same canary as #687 but mid stored as half. Expected = SiLU(1.0)*2 = 1.462117,
     * stored as half (closest FP16 value to 1.462117 is 1.4619140625). */
    const uint64_t total = (uint64_t)rows * width;
    float *host_gate = (float *)calloc(total, sizeof(float));
    float *host_up = (float *)calloc(total, sizeof(float));
    uint16_t *host_mid = (uint16_t *)calloc(total, sizeof(uint16_t));  /* half = 16 bits */
    float *host_w = (float *)calloc(rows, sizeof(float));
    if (!host_gate || !host_up || !host_mid || !host_w) {
        free(host_gate); free(host_up); free(host_mid); free(host_w);
        return 0;
    }
    for (uint64_t i = 0; i < total; i++) { host_gate[i] = 1.0f; host_up[i] = 2.0f; }
    for (uint32_t r = 0; r < rows; r++) host_w[r] = 1.0f;
    const float ref = (1.0f / (1.0f + expf(-1.0f))) * 2.0f * 1.0f;

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:48
                                                      options:MTLResourceStorageModeShared];
        id<MTLBuffer> gateBuf = [g_device newBufferWithBytes:host_gate
                                                      length:total * sizeof(float)
                                                     options:MTLResourceStorageModeShared];
        id<MTLBuffer> upBuf = [g_device newBufferWithBytes:host_up
                                                    length:total * sizeof(float)
                                                   options:MTLResourceStorageModeShared];
        id<MTLBuffer> midBuf = [g_device newBufferWithLength:total * sizeof(uint16_t)
                                                     options:MTLResourceStorageModeShared];
        id<MTLBuffer> wBuf = [g_device newBufferWithBytes:host_w
                                                   length:rows * sizeof(float)
                                                  options:MTLResourceStorageModeShared];

        struct {
            uint32_t width_, rows_;
            uint64_t gs_, us_, ms_, ws_;
            uint32_t wc_;
            float c_;
        } args = {
            .width_ = width, .rows_ = rows,
            .gs_ = (uint64_t)width * sizeof(float),
            .us_ = (uint64_t)width * sizeof(float),
            .ms_ = (uint64_t)width * sizeof(uint16_t),  /* half */
            .ws_ = sizeof(float),
            .wc_ = 0,
            .c_ = 0.0f,
        };
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 6;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[5] = {
                (id<MTLAllocation>)argsBuf,
                (id<MTLAllocation>)gateBuf,
                (id<MTLAllocation>)upBuf,
                (id<MTLAllocation>)midBuf,
                (id<MTLAllocation>)wBuf,
            };
            [residency addAllocations:allocs count:5];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(6);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:gateBuf.gpuAddress atIndex:1];
                [argTable setAddress:upBuf.gpuAddress atIndex:2];
                [argTable setAddress:midBuf.gpuAddress atIndex:3];
                [argTable setAddress:wBuf.gpuAddress atIndex:4];

                NSUInteger nth = MIN((NSUInteger)256, MAX((NSUInteger)1, (NSUInteger)width));

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_moe_swiglu_weight_f16_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc dispatchThreadgroups:MTLSizeMake(rows, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) {
                    (void)fb; dispatch_semaphore_signal(sem);
                }];
                id<MTL4CommandBuffer> bufs[1] = { cb };
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem,
                    dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_mid, midBuf.contents, total * sizeof(uint16_t));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 6);
            }
        }
    }
    if (!rc) {
        free(host_gate); free(host_up); free(host_mid); free(host_w);
        return 0;
    }

    /* Convert half → float for verification via _Float16. */
    double max_abs = 0.0;
    float first = 0.0f, last = 0.0f;
    for (uint64_t i = 0; i < total; i++) {
        _Float16 h;
        memcpy(&h, &host_mid[i], sizeof(h));
        const float v = (float)h;
        if (i == 0) first = v;
        if (i == total - 1) last = v;
        double d = fabs((double)(v - ref));
        if (d > max_abs) max_abs = d;
    }
    fprintf(stderr,
        "ds4: moe_swiglu_weight_f16 MTL4 canary rows=%u width=%u "
        "mid[0]=%.6f (ref=%.6f) mid[end]=%.6f max_abs=%.4e\n",
        rows, width, (double)first, (double)ref, (double)last, max_abs);
    free(host_gate); free(host_up); free(host_mid); free(host_w);
    /* FP16 has ~0.5e-3 relative precision near 1.5; accept ≤ 1e-3 absolute. */
    return (max_abs < 1.0e-3) ? 1 : 0;
}

/* ============================================================ */
/* moe_swiglu_weight_f16in_f16out MTL4 — silv 2026-05-28 task #761  */
/* ============================================================ */
/* Phase 2 of PATH_FUSED full-FFN chain. Reads fp16 gate+up (the
 * direct outputs of `ds4_metal_vqb2_fused_dispatch_kind`), writes
 * fp16 mid (the direct input to the next dispatch_kind for DOWN).
 *
 * Per (slot, row): mid[slot, row] = SiLU(gate) × up × route_weight[slot].
 *
 * Why this kernel rather than the existing fp32-in / fp16-out
 * `kernel_dsv4_moe_swiglu_weight_f16`: the existing one reads fp32
 * gate/up, but the fused decode-matmul writes fp16. To use the
 * existing one we'd need a fp16→fp32 round-trip on 24 KB per layer.
 * The new kernel skips that round-trip — keeps everything in fp16
 * accumulators where the codec already lives. Saves ~30 KB DRAM
 * traffic per layer per token.
 *
 * Dispatch shape: (n_rows, n_selected, 1) threadgroups × (32, 1, 1)
 * threads (= one simdgroup per slot, 32 rows-per-iter per simdgroup).
 * Inputs are flat fp16 arrays length n_selected × n_rows; output the
 * same shape. Route weights are fp32 length n_selected.
 *
 * Canary: independently verifiable against the existing fp32 SwiGLU
 * (run both with identical inputs, max_rel < 1e-3 on fp16 round-trip).
 */
static id<MTLComputePipelineState> g_moe_swiglu_weight_f16_io_mtl4_pipeline;
static int g_moe_swiglu_weight_f16_io_mtl4_init_attempted;
static int g_moe_swiglu_weight_f16_io_mtl4_init_ok;

static int ds4_moe_swiglu_weight_f16_io_mtl4_pipeline_init(void) {
    if (g_moe_swiglu_weight_f16_io_mtl4_init_attempted) return g_moe_swiglu_weight_f16_io_mtl4_init_ok;
    g_moe_swiglu_weight_f16_io_mtl4_init_attempted = 1;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "struct sw_args {\n"
         "  uint32_t n_rows;\n"
         "  uint32_t n_selected;\n"
         "  float    clamp_value;\n"
         "  uint32_t pad;\n"
         "};\n"
         "kernel void moe_swiglu_weight_f16_io_mtl4(\n"
         "    device const sw_args *args [[buffer(0)]],\n"
         "    device const half    *gate [[buffer(1)]],\n"  /* [n_sel × n_rows] */
         "    device const half    *up   [[buffer(2)]],\n"  /* [n_sel × n_rows] */
         "    device const float   *route_w [[buffer(3)]],\n" /* [n_sel] */
         "    device       half    *mid  [[buffer(4)]],\n"  /* [n_sel × n_rows] */
         "    uint2 gid [[thread_position_in_grid]]) {\n"
         "  if (gid.x >= args->n_rows || gid.y >= args->n_selected) return;\n"
         "  const uint64_t idx = (uint64_t)gid.y * args->n_rows + gid.x;\n"
         "  float g = (float)gate[idx];\n"
         "  float u = (float)up[idx];\n"
         "  const float c = args->clamp_value;\n"
         "  if (c > 1.0e-6f) { g = min(g, c); u = clamp(u, -c, c); }\n"
         "  const float silu = g / (1.0f + exp(-g));\n"
         "  mid[idx] = (half)(silu * u * route_w[gid.y]);\n"
         "}\n";

    g_moe_swiglu_weight_f16_io_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_moe_swiglu_weight_f16_io_mtl4",
        @"moe_swiglu_weight_f16_io_mtl4", 256, NULL, 0);
    g_moe_swiglu_weight_f16_io_mtl4_init_ok =
        (g_moe_swiglu_weight_f16_io_mtl4_pipeline != nil) ? 1 : 0;
    return g_moe_swiglu_weight_f16_io_mtl4_init_ok;
}

/* Dispatch wrapper for the chain wiring: caller supplies gate/up fp16
 * MTLBuffers (from dispatch_kind outputs), route weights fp32 buffer,
 * and mid fp16 buffer (from out_buffer slot 2). Returns 1 on success.
 *
 * Reuses ds4_mtl4_run_canary helper — see item D pattern.
 *
 * NOTE (codex H2186, 2026-05-28): this 2D variant treats gate/up as flat
 * [n_selected * n_rows] slot-major. The fused PATH_FUSED chain in
 * ds4_metal_vqb2_fp16.m no longer calls this function — it produces
 * gate/up in row-block-major [n_rb][n_selected][n_rows] order, which
 * requires the row-block-aware sibling `ds4_metal_vqb2_fused_swiglu_rowblock_step`
 * below. This function remains for the legacy non-fused path, but any new
 * caller that consumes row-block-major gate/up MUST use the rowblock variant. */
int ds4_metal_vqb2_fused_swiglu_step(void *gate_buf, void *up_buf,
                                      void *route_weights_buf,
                                      void *mid_buf,
                                      uint32_t n_rows, uint32_t n_selected,
                                      float clamp_value) {
    if (!ds4_moe_swiglu_weight_f16_io_mtl4_pipeline_init()) return 0;
    if (!gate_buf || !up_buf || !route_weights_buf || !mid_buf) return 0;
    if (n_rows == 0 || n_selected == 0) return 0;

    /* Args buffer — persistent, refreshed on each call.
     * Caller-supplied buffers stay caller-owned. */
    static id<MTLBuffer> s_args_buf = nil;
    if (!s_args_buf) {
        s_args_buf = [g_device newBufferWithLength:16
                                          options:MTLResourceStorageModeShared];
        if (!s_args_buf) return 0;
    }
    struct { uint32_t n_rows; uint32_t n_selected; float clamp; uint32_t pad; } args = {
        n_rows, n_selected, clamp_value, 0u,
    };
    memcpy(s_args_buf.contents, &args, sizeof(args));

    void *bindings[5] = {
        (__bridge void *)s_args_buf,
        gate_buf, up_buf, route_weights_buf, mid_buf,
    };
    /* Dispatch grid covers (n_rows, n_selected); 32-wide threadgroups. */
    return ds4_mtl4_run_canary(
        (__bridge void *)g_moe_swiglu_weight_f16_io_mtl4_pipeline,
        bindings, 5,
        (unsigned long)n_rows, (unsigned long)n_selected, 1ul,
        32ul, 1ul, 1ul,
        0ul, NULL, NULL);
}

/* ============================================================ */
/* moe_swiglu_weight_f16_rowblock_mtl4 — codex H2186/H2187 fix    */
/* ============================================================ */
/* Row-block-aware SwiGLU for PATH_FUSED chain. Codex H2186 proved
 * that production fused chain silently composed incompatible
 * layouts: fused decode-matmul writes gate/up in row-block-major
 * order [n_rb][n_selected][n_rows] but the legacy 2D SwiGLU above
 * reads them as slot-major [n_selected][n_rows]. The result: 15/16
 * row blocks (93.75% of mid rows) were ignored, DOWN read mid with
 * stride=n_rows (128) instead of the coherent stride=n_rb*n_rows
 * (2048) the dispatch_fused intermediate width requires.
 *
 * Codex H2187 verified the fix direction with a standalone Metal
 * probe: row-block-aware kernel + DOWN stride = n_rb*n_rows produces
 * all 12288 mid halves nonzero vs the production 768. Layouts:
 *   in_idx  = ((row_block * n_selected + slot) * n_rows + row)
 *   out_idx = (slot * (n_row_blocks * n_rows) + row_block * n_rows + row)
 *
 * Dispatch grid: (n_rows, n_selected, n_row_blocks). DOWN reads mid
 * with x_slot_stride_halves = n_row_blocks * n_rows. */
static id<MTLComputePipelineState> g_moe_swiglu_weight_f16_rowblock_mtl4_pipeline;
static int g_moe_swiglu_weight_f16_rowblock_mtl4_init_attempted;
static int g_moe_swiglu_weight_f16_rowblock_mtl4_init_ok;

static int ds4_moe_swiglu_weight_f16_rowblock_mtl4_pipeline_init(void) {
    if (g_moe_swiglu_weight_f16_rowblock_mtl4_init_attempted)
        return g_moe_swiglu_weight_f16_rowblock_mtl4_init_ok;
    g_moe_swiglu_weight_f16_rowblock_mtl4_init_attempted = 1;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "struct rb_args {\n"
         "  uint32_t n_rows;\n"
         "  uint32_t n_selected;\n"
         "  uint32_t n_row_blocks;\n"
         "  float    clamp_value;\n"
         "};\n"
         "kernel void moe_swiglu_weight_f16_rowblock_mtl4(\n"
         "    device const rb_args *args    [[buffer(0)]],\n"
         "    device const half    *gate    [[buffer(1)]],\n"
         "    device const half    *up      [[buffer(2)]],\n"
         "    device const float   *route_w [[buffer(3)]],\n"
         "    device       half    *mid     [[buffer(4)]],\n"
         "    uint3 gid [[thread_position_in_grid]]) {\n"
         "  if (gid.x >= args->n_rows || gid.y >= args->n_selected\n"
         "      || gid.z >= args->n_row_blocks) return;\n"
         "  const ulong in_idx  = ((ulong)gid.z * args->n_selected + gid.y)\n"
         "                         * args->n_rows + gid.x;\n"
         "  const ulong out_idx = (ulong)gid.y * (args->n_row_blocks * args->n_rows)\n"
         "                         + (ulong)gid.z * args->n_rows + gid.x;\n"
         "  float g = (float)gate[in_idx];\n"
         "  float u = (float)up[in_idx];\n"
         "  const float c = args->clamp_value;\n"
         "  if (c > 1.0e-6f) { g = min(g, c); u = clamp(u, -c, c); }\n"
         "  const float silu = g / (1.0f + exp(-g));\n"
         "  mid[out_idx] = (half)(silu * u * route_w[gid.y]);\n"
         "}\n";

    g_moe_swiglu_weight_f16_rowblock_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_moe_swiglu_weight_f16_rowblock_mtl4",
        @"moe_swiglu_weight_f16_rowblock_mtl4", 256, NULL, 0);
    g_moe_swiglu_weight_f16_rowblock_mtl4_init_ok =
        (g_moe_swiglu_weight_f16_rowblock_mtl4_pipeline != nil) ? 1 : 0;
    return g_moe_swiglu_weight_f16_rowblock_mtl4_init_ok;
}

/* Dispatch wrapper. Returns 1 on success.
 * The mid buffer must have at least n_selected * n_row_blocks * n_rows
 * fp16 halves of capacity (i.e., the full slot-major intermediate). */
int ds4_metal_vqb2_fused_swiglu_rowblock_step(void *gate_buf, void *up_buf,
                                               void *route_weights_buf,
                                               void *mid_buf,
                                               uint32_t n_rows,
                                               uint32_t n_selected,
                                               uint32_t n_row_blocks,
                                               float clamp_value) {
    if (!ds4_moe_swiglu_weight_f16_rowblock_mtl4_pipeline_init()) return 0;
    if (!gate_buf || !up_buf || !route_weights_buf || !mid_buf) return 0;
    if (n_rows == 0 || n_selected == 0 || n_row_blocks == 0) return 0;

    static id<MTLBuffer> s_rb_args_buf = nil;
    if (!s_rb_args_buf) {
        s_rb_args_buf = [g_device newBufferWithLength:16
                                              options:MTLResourceStorageModeShared];
        if (!s_rb_args_buf) return 0;
    }
    struct { uint32_t n_rows; uint32_t n_selected;
             uint32_t n_row_blocks; float clamp; } rb_args = {
        n_rows, n_selected, n_row_blocks, clamp_value,
    };
    memcpy(s_rb_args_buf.contents, &rb_args, sizeof(rb_args));

    void *bindings[5] = {
        (__bridge void *)s_rb_args_buf,
        gate_buf, up_buf, route_weights_buf, mid_buf,
    };
    /* Dispatch grid (n_rows, n_selected, n_row_blocks); 32-wide threadgroups. */
    return ds4_mtl4_run_canary(
        (__bridge void *)g_moe_swiglu_weight_f16_rowblock_mtl4_pipeline,
        bindings, 5,
        (unsigned long)n_rows, (unsigned long)n_selected, (unsigned long)n_row_blocks,
        32ul, 1ul, 1ul,
        0ul, NULL, NULL);
}

/* Canary self-test for the row-block-aware SwiGLU. Uses position-dependent
 * gate values to catch layout transpositions: if the kernel reads in_idx
 * via the wrong axis ordering OR writes out_idx with a transposed formula,
 * the silu(gate) value at each output position will mismatch. Uniform
 * inputs would not catch a layout bug — they'd give the same answer
 * regardless of which (rb, slot, row) we read.
 *
 * Input layout: gate/up[rb][slot][row] linearized as
 *   in_idx = (rb * n_selected + slot) * n_rows + row.
 * Output layout: mid[slot][rb * n_rows + row] linearized as
 *   out_idx = slot * (n_row_blocks * n_rows) + rb * n_rows + row.
 *
 * gate[in_idx] = 0.25 + 0.001 * (rb * 7919 + slot * 31 + row) mod 4.0
 * up[in_idx]   = 1.5
 * route_w[slot] = 1.0
 * expected mid[out_idx] = silu(gate[in_idx]) * 1.5
 *
 * Returns 1 if max_abs error < 5e-3 (fp16 with silu compounded).
 * Threshold is looser than the slot-major canary because gate values
 * span a wider range here. */
int ds4_gpu_mtl4_moe_swiglu_weight_f16_rowblock_canary(uint32_t n_rows,
                                                       uint32_t n_selected,
                                                       uint32_t n_row_blocks) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_moe_swiglu_weight_f16_rowblock_mtl4_pipeline_init()) return 0;
    if (n_rows == 0 || n_selected == 0 || n_row_blocks == 0) {
        fprintf(stderr, "ds4: moe_swiglu_weight_f16_rowblock canary requires "
                        "n_rows>0 && n_selected>0 && n_row_blocks>0\n");
        return 0;
    }

    const uint64_t total = (uint64_t)n_row_blocks * n_selected * n_rows;
    int rc = 0;
    @autoreleasepool {
        id<MTLBuffer> gateBuf = [g_device newBufferWithLength:total * sizeof(uint16_t)
                                                       options:MTLResourceStorageModeShared];
        id<MTLBuffer> upBuf   = [g_device newBufferWithLength:total * sizeof(uint16_t)
                                                       options:MTLResourceStorageModeShared];
        id<MTLBuffer> midBuf  = [g_device newBufferWithLength:total * sizeof(uint16_t)
                                                       options:MTLResourceStorageModeShared];
        id<MTLBuffer> wBuf    = [g_device newBufferWithLength:n_selected * sizeof(float)
                                                       options:MTLResourceStorageModeShared];
        if (!gateBuf || !upBuf || !midBuf || !wBuf) return 0;

        _Float16 *gate_h = (_Float16 *)gateBuf.contents;
        _Float16 *up_h   = (_Float16 *)upBuf.contents;
        _Float16 *mid_h  = (_Float16 *)midBuf.contents;
        float    *rw     = (float *)wBuf.contents;
        for (uint32_t s = 0; s < n_selected; s++) rw[s] = 1.0f;
        for (uint32_t rb = 0; rb < n_row_blocks; rb++) {
            for (uint32_t s = 0; s < n_selected; s++) {
                for (uint32_t r = 0; r < n_rows; r++) {
                    const uint64_t in_idx = ((uint64_t)rb * n_selected + s) * n_rows + r;
                    const uint32_t mix = rb * 7919u + s * 31u + r;
                    const float g = 0.25f + 0.001f * (float)(mix & 4095u);
                    gate_h[in_idx] = (_Float16)g;
                    up_h[in_idx]   = (_Float16)1.5f;
                }
            }
        }
        memset(mid_h, 0, total * sizeof(uint16_t));

        const int ok = ds4_metal_vqb2_fused_swiglu_rowblock_step(
            (__bridge void *)gateBuf, (__bridge void *)upBuf,
            (__bridge void *)wBuf,    (__bridge void *)midBuf,
            n_rows, n_selected, n_row_blocks, 0.0f);
        if (!ok) {
            fprintf(stderr, "ds4: moe_swiglu_weight_f16_rowblock canary dispatch failed\n");
            return 0;
        }

        /* Verify: read mid via slot-major out_idx and compare to silu(gate) * 1.5. */
        double max_abs = 0.0;
        uint64_t worst_idx = 0;
        float worst_got = 0.0f, worst_ref = 0.0f;
        for (uint32_t s = 0; s < n_selected; s++) {
            for (uint32_t rb = 0; rb < n_row_blocks; rb++) {
                for (uint32_t r = 0; r < n_rows; r++) {
                    const uint64_t in_idx  = ((uint64_t)rb * n_selected + s) * n_rows + r;
                    const uint64_t out_idx = (uint64_t)s * ((uint64_t)n_row_blocks * n_rows)
                                              + (uint64_t)rb * n_rows + r;
                    const float g = (float)gate_h[in_idx];
                    const float silu = g / (1.0f + expf(-g));
                    const float ref  = silu * 1.5f;
                    const float got  = (float)mid_h[out_idx];
                    const double d = fabs((double)(got - ref));
                    if (d > max_abs) { max_abs = d; worst_idx = out_idx;
                                       worst_got = got; worst_ref = ref; }
                }
            }
        }
        rc = (max_abs < 5.0e-3) ? 1 : 0;
        fprintf(stderr,
            "ds4: moe_swiglu_weight_f16_rowblock MTL4 canary n_rows=%u n_sel=%u "
            "n_rb=%u total=%llu max_abs=%.4e worst[%llu]=%.6f vs %.6f → %s\n",
            n_rows, n_selected, n_row_blocks, (unsigned long long)total,
            max_abs, (unsigned long long)worst_idx, worst_got, worst_ref,
            rc ? "OK" : "FAIL");
    }
    return rc;
}

/* ============================================================ */
/* dsv4_hc_split_sinkhorn MTL4 port (silv 2026-05-27 task #690)  */
/* ============================================================ */
/* MTL4 port of kernel_dsv4_hc_split_sinkhorn (HC=4 specialization).
 * Splits one HC mixer row of 24 floats into:
 *   - positions 0..3: pre  (sigmoid + eps after pre_scale*mix + base)
 *   - positions 4..7: post (twice_sigmoid)
 *   - positions 8..23: 4×4 comb matrix (Sinkhorn-normalized rows+cols)
 *
 * The Sinkhorn portion: row-softmax once + (iters-1) alternating
 * col/row normalize steps to produce a doubly-stochastic 4×4 matrix.
 *
 * Per-row dispatch (one thread per row in 1D grid). HC=4 only. */

static id<MTLComputePipelineState> g_hc_split_sinkhorn_mtl4_pipeline;
static int g_hc_split_sinkhorn_mtl4_init_attempted;
static int g_hc_split_sinkhorn_mtl4_init_ok;

static int ds4_hc_split_sinkhorn_mtl4_pipeline_init(void) {
    if (g_hc_split_sinkhorn_mtl4_init_attempted) return g_hc_split_sinkhorn_mtl4_init_ok;
    g_hc_split_sinkhorn_mtl4_init_attempted = 1;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "static inline float  hc_sigmoid(float  z)        { return 1.0f / (1.0f + exp(-z)); }\n"
         "static inline float4 hc_sigmoid4(float4 z)       { return 1.0f / (1.0f + exp(-z)); }\n"
         "static inline float4 hc_twice_sigmoid4(float4 z) { return 2.0f / (1.0f + exp(-z)); }\n"
         "struct sk_args {\n"
         "  int32_t n_hc;\n"
         "  int32_t sinkhorn_iters;\n"
         "  int64_t n_rows;\n"
         "  int64_t mix_hc;\n"
         "  uint64_t nb01;\n"
         "  uint64_t nb1;\n"
         "  float eps;\n"
         "};\n"
         "kernel void hc_split_sinkhorn_mtl4(\n"
         "    device const sk_args *args [[buffer(0)]],\n"
         "    device const float   *mixes [[buffer(1)]],\n"
         "    device const float   *scale [[buffer(2)]],\n"
         "    device const float   *base  [[buffer(3)]],\n"
         "    device       float   *dst   [[buffer(4)]],\n"
         "    uint tid [[thread_position_in_grid]]) {\n"
         "  if ((int64_t)tid >= args->n_rows || args->n_hc != 4) return;\n"
         "  device const float *mix = mixes + ((int64_t)tid) * args->mix_hc;\n"
         "  device       float *out = dst   + ((int64_t)tid) * args->mix_hc;\n"
         "  const float epsv = args->eps;\n"
         "  const float pre_s = scale[0];\n"
         "  const float post_s = scale[1];\n"
         "  const float comb_s = scale[2];\n"
         "  /* pre + post */\n"
         "  const float4 pre_z  = *((device const float4 *)mix)       * pre_s  + *((device const float4 *)base);\n"
         "  *((device float4 *)out) = hc_sigmoid4(pre_z) + epsv;\n"
         "  const float4 post_z = *((device const float4 *)(mix + 4)) * post_s + *((device const float4 *)(base + 4));\n"
         "  *((device float4 *)(out + 4)) = hc_twice_sigmoid4(post_z);\n"
         "  /* Sinkhorn 4×4 with stable row-softmax */\n"
         "  float4 r0 = *((device const float4 *)(mix +  8)) * comb_s + *((device const float4 *)(base +  8));\n"
         "  float4 r1 = *((device const float4 *)(mix + 12)) * comb_s + *((device const float4 *)(base + 12));\n"
         "  float4 r2 = *((device const float4 *)(mix + 16)) * comb_s + *((device const float4 *)(base + 16));\n"
         "  float4 r3 = *((device const float4 *)(mix + 20)) * comb_s + *((device const float4 *)(base + 20));\n"
         "  const float m0 = max(max(r0.x, r0.y), max(r0.z, r0.w));\n"
         "  const float m1 = max(max(r1.x, r1.y), max(r1.z, r1.w));\n"
         "  const float m2 = max(max(r2.x, r2.y), max(r2.z, r2.w));\n"
         "  const float m3 = max(max(r3.x, r3.y), max(r3.z, r3.w));\n"
         "  r0 = exp(r0 - m0);\n"
         "  r1 = exp(r1 - m1);\n"
         "  r2 = exp(r2 - m2);\n"
         "  r3 = exp(r3 - m3);\n"
         "  r0 = r0 * (1.0f / (r0.x + r0.y + r0.z + r0.w)) + epsv;\n"
         "  r1 = r1 * (1.0f / (r1.x + r1.y + r1.z + r1.w)) + epsv;\n"
         "  r2 = r2 * (1.0f / (r2.x + r2.y + r2.z + r2.w)) + epsv;\n"
         "  r3 = r3 * (1.0f / (r3.x + r3.y + r3.z + r3.w)) + epsv;\n"
         "  float4 col_inv = 1.0f / (r0 + r1 + r2 + r3 + epsv);\n"
         "  r0 *= col_inv; r1 *= col_inv; r2 *= col_inv; r3 *= col_inv;\n"
         "  for (int iter = 1; iter < args->sinkhorn_iters; ++iter) {\n"
         "    r0 *= 1.0f / (r0.x + r0.y + r0.z + r0.w + epsv);\n"
         "    r1 *= 1.0f / (r1.x + r1.y + r1.z + r1.w + epsv);\n"
         "    r2 *= 1.0f / (r2.x + r2.y + r2.z + r2.w + epsv);\n"
         "    r3 *= 1.0f / (r3.x + r3.y + r3.z + r3.w + epsv);\n"
         "    col_inv = 1.0f / (r0 + r1 + r2 + r3 + epsv);\n"
         "    r0 *= col_inv; r1 *= col_inv; r2 *= col_inv; r3 *= col_inv;\n"
         "  }\n"
         "  *((device float4 *)(out +  8)) = r0;\n"
         "  *((device float4 *)(out + 12)) = r1;\n"
         "  *((device float4 *)(out + 16)) = r2;\n"
         "  *((device float4 *)(out + 20)) = r3;\n"
         "}\n";

    g_hc_split_sinkhorn_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_hc_split_sinkhorn_mtl4", @"hc_split_sinkhorn_mtl4", 256, NULL, 0);
    g_hc_split_sinkhorn_mtl4_init_ok = (g_hc_split_sinkhorn_mtl4_pipeline != nil) ? 1 : 0;
    return g_hc_split_sinkhorn_mtl4_init_ok;
}

int ds4_gpu_mtl4_hc_split_sinkhorn_canary(uint32_t n_rows, uint32_t sinkhorn_iters) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_hc_split_sinkhorn_mtl4_pipeline_init()) return 0;
    if (n_rows == 0 || sinkhorn_iters == 0) {
        fprintf(stderr, "ds4: hc_split_sinkhorn canary requires n_rows>0 and sinkhorn_iters>0\n");
        return 0;
    }

    /* Canary: mix = 0, base = 0, scale = {1, 1, 1}, eps = 0.
     * Expected per row:
     *   pre[0..3]   = sigmoid(0) = 0.5
     *   post[4..7]  = 2*sigmoid(0) = 1.0
     *   comb[8..23] = 0.25 each (row+col Sinkhorn of zero matrix = 1/N uniform) */
    const uint32_t mix_hc = 24;  /* 8 + 4*4 */
    const uint64_t total = (uint64_t)n_rows * mix_hc;
    float *host_mix = (float *)calloc(total, sizeof(float));
    float *host_scale = (float *)calloc(3, sizeof(float));
    float *host_base = (float *)calloc(mix_hc, sizeof(float)); /* shared base, indexed without per-row offset */
    float *host_dst = (float *)calloc(total, sizeof(float));
    if (!host_mix || !host_scale || !host_base || !host_dst) {
        free(host_mix); free(host_scale); free(host_base); free(host_dst);
        return 0;
    }
    host_scale[0] = host_scale[1] = host_scale[2] = 1.0f;
    /* mix, base zero already */

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:48
                                                      options:MTLResourceStorageModeShared];
        id<MTLBuffer> mixBuf = [g_device newBufferWithBytes:host_mix
                                                     length:total * sizeof(float)
                                                    options:MTLResourceStorageModeShared];
        id<MTLBuffer> scaleBuf = [g_device newBufferWithBytes:host_scale
                                                       length:3 * sizeof(float)
                                                      options:MTLResourceStorageModeShared];
        id<MTLBuffer> baseBuf = [g_device newBufferWithBytes:host_base
                                                      length:mix_hc * sizeof(float)
                                                     options:MTLResourceStorageModeShared];
        id<MTLBuffer> dstBuf = [g_device newBufferWithLength:total * sizeof(float)
                                                     options:MTLResourceStorageModeShared];

        struct {
            int32_t n_hc_, sinkhorn_iters_;
            int64_t n_rows_, mix_hc_;
            uint64_t nb01_, nb1_;
            float eps_;
            uint32_t pad;
        } args = {
            .n_hc_ = 4, .sinkhorn_iters_ = (int32_t)sinkhorn_iters,
            .n_rows_ = (int64_t)n_rows, .mix_hc_ = mix_hc,
            .nb01_ = (uint64_t)mix_hc * sizeof(float),
            .nb1_  = (uint64_t)mix_hc * sizeof(float),
            .eps_ = 0.0f,
        };
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 6;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[5] = {
                (id<MTLAllocation>)argsBuf,
                (id<MTLAllocation>)mixBuf,
                (id<MTLAllocation>)scaleBuf,
                (id<MTLAllocation>)baseBuf,
                (id<MTLAllocation>)dstBuf,
            };
            [residency addAllocations:allocs count:5];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(6);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:mixBuf.gpuAddress atIndex:1];
                [argTable setAddress:scaleBuf.gpuAddress atIndex:2];
                [argTable setAddress:baseBuf.gpuAddress atIndex:3];
                [argTable setAddress:dstBuf.gpuAddress atIndex:4];

                /* Dispatch 1D: one thread per row, multiple TG's of 64 threads */
                NSUInteger nth = MIN((NSUInteger)64, MAX((NSUInteger)1, (NSUInteger)n_rows));
                NSUInteger n_tg = ((NSUInteger)n_rows + nth - 1u) / nth;

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_hc_split_sinkhorn_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc dispatchThreadgroups:MTLSizeMake(n_tg, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) {
                    (void)fb; dispatch_semaphore_signal(sem);
                }];
                id<MTL4CommandBuffer> bufs[1] = { cb };
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem,
                    dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_dst, dstBuf.contents, total * sizeof(float));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 6);
            }
        }
    }
    if (!rc) {
        free(host_mix); free(host_scale); free(host_base); free(host_dst);
        return 0;
    }

    /* Validate per-row layout: pre=0.5, post=1.0, comb=0.25 */
    double pre_dev = 0.0, post_dev = 0.0, comb_dev = 0.0;
    for (uint32_t r = 0; r < n_rows; r++) {
        const float *o = host_dst + (uint64_t)r * mix_hc;
        for (int i = 0; i < 4; i++) {
            double d = fabs((double)(o[i] - 0.5));
            if (d > pre_dev) pre_dev = d;
        }
        for (int i = 4; i < 8; i++) {
            double d = fabs((double)(o[i] - 1.0));
            if (d > post_dev) post_dev = d;
        }
        for (int i = 8; i < 24; i++) {
            double d = fabs((double)(o[i] - 0.25));
            if (d > comb_dev) comb_dev = d;
        }
    }
    fprintf(stderr,
        "ds4: hc_split_sinkhorn MTL4 canary n_rows=%u iters=%u "
        "pre[0]=%.4f (ref=0.5) post[4]=%.4f (ref=1.0) comb[8]=%.4f (ref=0.25) "
        "pre_dev=%.4e post_dev=%.4e comb_dev=%.4e\n",
        n_rows, sinkhorn_iters,
        (double)host_dst[0], (double)host_dst[4], (double)host_dst[8],
        pre_dev, post_dev, comb_dev);
    free(host_mix); free(host_scale); free(host_base); free(host_dst);
    return (pre_dev < 1.0e-6 && post_dev < 1.0e-6 && comb_dev < 1.0e-6) ? 1 : 0;
}

/* ============================================================ */
/* get_rows_f32 MTL4 port (silv 2026-05-27 task #691)             */
/* ============================================================ */
/* MTL4 port of kernel_get_rows_f<float, float> from metal/get_rows.metal.
 * Gathers embedding/table rows by integer ids. DS4 uses this for
 * token embeddings + router/hash lookup outputs.
 *
 * Dispatch: (n_rows*W, ne11, ne12) threadgroups × (ntg, 1, 1) threads.
 * Per-thread copies one element from src0[id*nb01 ...] to dst[...]
 * after reading the id from src1 (int32). */

static id<MTLComputePipelineState> g_get_rows_f32_mtl4_pipeline;
static int g_get_rows_f32_mtl4_init_attempted;
static int g_get_rows_f32_mtl4_init_ok;

static int ds4_get_rows_f32_mtl4_pipeline_init(void) {
    if (g_get_rows_f32_mtl4_init_attempted) return g_get_rows_f32_mtl4_init_ok;
    g_get_rows_f32_mtl4_init_attempted = 1;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "struct gr_args {\n"
         "  int32_t ne00t;     /* per-thread tile width */\n"
         "  int32_t ne00;      /* row width */\n"
         "  uint64_t nb01;\n"
         "  uint64_t nb02;\n"
         "  uint64_t nb03;\n"
         "  int32_t ne10;      /* ids width */\n"
         "  uint64_t nb10;\n"
         "  uint64_t nb11;\n"
         "  uint64_t nb12;\n"
         "  uint64_t nb1;\n"
         "  uint64_t nb2;\n"
         "  uint64_t nb3;\n"
         "};\n"
         "kernel void get_rows_f32_mtl4(\n"
         "    device const gr_args *args [[buffer(0)]],\n"
         "    device const char    *src0 [[buffer(1)]],   /* table */\n"
         "    device const char    *src1 [[buffer(2)]],   /* int32 ids */\n"
         "    device       char    *dst  [[buffer(3)]],\n"
         "    uint3   tgpig [[threadgroup_position_in_grid]],\n"
         "    ushort  tiitg [[thread_index_in_threadgroup]],\n"
         "    ushort3 ntg   [[threads_per_threadgroup]]) {\n"
         "  const int32_t iw0 = tgpig.x / args->ne10;\n"
         "  const int32_t i10 = tgpig.x % args->ne10;\n"
         "  const int32_t i11 = tgpig.y;\n"
         "  const int32_t i12 = tgpig.z;\n"
         "  const int32_t r = ((const device int32_t *)(src1 + i12*args->nb12 + i11*args->nb11 + i10*args->nb10))[0];\n"
         "  const int32_t i02 = i11;\n"
         "  const int32_t i03 = i12;\n"
         "  device const float *psrc = (device const float *)(src0 + i03*args->nb03 + i02*args->nb02 + r*args->nb01);\n"
         "  device       float *pdst = (device       float *)(dst  + i12*args->nb3  + i11*args->nb2  + i10*args->nb1);\n"
         "  for (int ind = iw0*ntg.x + tiitg; ind < args->ne00t;) {\n"
         "    pdst[ind] = psrc[ind];\n"
         "    break;\n"
         "  }\n"
         "}\n";

    g_get_rows_f32_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_get_rows_f32_mtl4", @"get_rows_f32_mtl4", 256, NULL, 0);
    g_get_rows_f32_mtl4_init_ok = (g_get_rows_f32_mtl4_pipeline != nil) ? 1 : 0;
    return g_get_rows_f32_mtl4_init_ok;
}

int ds4_gpu_mtl4_get_rows_f32_canary(uint32_t n_table_rows, uint32_t row_width, uint32_t n_ids) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_get_rows_f32_mtl4_pipeline_init()) return 0;
    if (n_table_rows == 0 || row_width == 0 || n_ids == 0) {
        fprintf(stderr, "ds4: get_rows_f32 canary needs n_table_rows>0, row_width>0, n_ids>0\n");
        return 0;
    }

    /* Canary: table[row, col] = row * 100 + col.
     * ids = [n_table_rows - 1, n_table_rows - 2, ..., n_table_rows - n_ids].
     * Expected: dst[i, col] = (n_table_rows - 1 - i) * 100 + col. */
    const uint64_t table_n = (uint64_t)n_table_rows * row_width;
    const uint64_t dst_n = (uint64_t)n_ids * row_width;
    float *host_tab = (float *)calloc(table_n, sizeof(float));
    int32_t *host_ids = (int32_t *)calloc(n_ids, sizeof(int32_t));
    float *host_dst = (float *)calloc(dst_n, sizeof(float));
    if (!host_tab || !host_ids || !host_dst) {
        free(host_tab); free(host_ids); free(host_dst); return 0;
    }
    for (uint32_t r = 0; r < n_table_rows; r++) {
        for (uint32_t c = 0; c < row_width; c++) {
            host_tab[(uint64_t)r * row_width + c] = (float)((int)r * 100 + (int)c);
        }
    }
    for (uint32_t i = 0; i < n_ids; i++) {
        host_ids[i] = (int32_t)(n_table_rows - 1 - i);
    }

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:96
                                                      options:MTLResourceStorageModeShared];
        id<MTLBuffer> tabBuf = [g_device newBufferWithBytes:host_tab
                                                     length:table_n * sizeof(float)
                                                    options:MTLResourceStorageModeShared];
        id<MTLBuffer> idsBuf = [g_device newBufferWithBytes:host_ids
                                                     length:n_ids * sizeof(int32_t)
                                                    options:MTLResourceStorageModeShared];
        id<MTLBuffer> dstBuf = [g_device newBufferWithLength:dst_n * sizeof(float)
                                                     options:MTLResourceStorageModeShared];

        struct {
            int32_t ne00t; int32_t ne00;
            uint64_t nb01, nb02, nb03;
            int32_t ne10; uint32_t pad0;
            uint64_t nb10, nb11, nb12;
            uint64_t nb1, nb2, nb3;
        } args = {
            .ne00t = (int32_t)row_width,
            .ne00 = (int32_t)row_width,
            .nb01 = (uint64_t)row_width * sizeof(float),
            .nb02 = (uint64_t)n_table_rows * row_width * sizeof(float),
            .nb03 = (uint64_t)n_table_rows * row_width * sizeof(float),
            .ne10 = (int32_t)n_ids,
            .nb10 = sizeof(int32_t),
            .nb11 = (uint64_t)n_ids * sizeof(int32_t),
            .nb12 = (uint64_t)n_ids * sizeof(int32_t),
            .nb1 = (uint64_t)row_width * sizeof(float),
            .nb2 = (uint64_t)n_ids * row_width * sizeof(float),
            .nb3 = (uint64_t)n_ids * row_width * sizeof(float),
        };
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 6;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[4] = {
                (id<MTLAllocation>)argsBuf,
                (id<MTLAllocation>)tabBuf,
                (id<MTLAllocation>)idsBuf,
                (id<MTLAllocation>)dstBuf,
            };
            [residency addAllocations:allocs count:4];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(4);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:tabBuf.gpuAddress atIndex:1];
                [argTable setAddress:idsBuf.gpuAddress atIndex:2];
                [argTable setAddress:dstBuf.gpuAddress atIndex:3];

                /* Dispatch shape per kernel: (n_ids * W, 1, 1) tg, where W
                 * = ceil(ne00t / ntg.x). For canary, use ntg = min(row_width, 256). */
                NSUInteger nth = MIN((NSUInteger)256, MAX((NSUInteger)1, (NSUInteger)row_width));
                NSUInteger W = ((NSUInteger)row_width + nth - 1u) / nth;
                NSUInteger gx = (NSUInteger)n_ids * W;

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_get_rows_f32_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc dispatchThreadgroups:MTLSizeMake(gx, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) {
                    (void)fb; dispatch_semaphore_signal(sem);
                }];
                id<MTL4CommandBuffer> bufs[1] = { cb };
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem,
                    dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_dst, dstBuf.contents, dst_n * sizeof(float));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 4);
            }
        }
    }
    if (!rc) { free(host_tab); free(host_ids); free(host_dst); return 0; }

    /* Validate */
    double max_abs = 0.0;
    int mismatch_count = 0;
    for (uint32_t i = 0; i < n_ids; i++) {
        const int32_t id_val = (int32_t)(n_table_rows - 1 - i);
        for (uint32_t c = 0; c < row_width; c++) {
            const float v = host_dst[(uint64_t)i * row_width + c];
            const float ref = (float)(id_val * 100 + (int32_t)c);
            const double d = fabs((double)(v - ref));
            if (d > max_abs) max_abs = d;
            if (d > 1.0e-5) mismatch_count++;
        }
    }
    fprintf(stderr,
        "ds4: get_rows_f32 MTL4 canary n_table_rows=%u row_width=%u n_ids=%u "
        "dst[0,0]=%.1f (ref=%.1f) dst[0,end]=%.1f dst[end,0]=%.1f "
        "mismatch=%d max_abs=%.4e\n",
        n_table_rows, row_width, n_ids,
        (double)host_dst[0], (double)((n_table_rows - 1) * 100),
        (double)host_dst[row_width - 1],
        (double)host_dst[(uint64_t)(n_ids - 1) * row_width],
        mismatch_count, max_abs);
    free(host_tab); free(host_ids); free(host_dst);
    return (max_abs < 1.0e-5) ? 1 : 0;
}

/* ============================================================ */
/* argsort_f32_i32_desc MTL4 port (silv 2026-05-27 task #692)    */
/* ============================================================ */
/* MTL4 port of kernel_argsort_f32_i32<DS4_SORT_ORDER_DESC>.
 * Bitonic sort of indices keyed by float values. Returns the top_k
 * largest-value indices (descending) per row.
 *
 * Used by router top-K selection. Pairs with #588 sort_i32_rows_asc
 * (which sorts integer values directly); argsort is the value→index
 * version. ntg.x must be a power of 2.
 *
 * Canary: input row = [N-1, N-2, ..., 1, 0]; descending sort yields
 * indices [0, 1, 2, ..., N-1] (position of the largest = 0). */

static id<MTLComputePipelineState> g_argsort_f32_i32_desc_mtl4_pipeline;
static int g_argsort_f32_i32_desc_mtl4_init_attempted;
static int g_argsort_f32_i32_desc_mtl4_init_ok;

static int ds4_argsort_f32_i32_desc_mtl4_pipeline_init(void) {
    if (g_argsort_f32_i32_desc_mtl4_init_attempted) return g_argsort_f32_i32_desc_mtl4_init_ok;
    g_argsort_f32_i32_desc_mtl4_init_attempted = 1;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "#define SWAP(x, y) { int tmp = (x); (x) = (y); (y) = tmp; }\n"
         "struct as_args {\n"
         "  int32_t ne00; int32_t ne01; int32_t ne02; int32_t ne03;\n"
         "  uint64_t nb00; uint64_t nb01; uint64_t nb02; uint64_t nb03;\n"
         "  int32_t ne0; int32_t ne1; int32_t ne2; int32_t ne3;\n"
         "  int32_t top_k;\n"
         "};\n"
         "kernel void argsort_f32_i32_desc_mtl4(\n"
         "    device const as_args *args [[buffer(0)]],\n"
         "    device const char    *src0 [[buffer(1)]],\n"
         "    device       int32_t *dst  [[buffer(2)]],\n"
         "    threadgroup  int32_t *shmem_i32 [[threadgroup(0)]],\n"
         "    uint3   tgpig [[threadgroup_position_in_grid]],\n"
         "    ushort3 tpitg [[thread_position_in_threadgroup]],\n"
         "    ushort3 ntg   [[threads_per_threadgroup]]) {\n"
         "  const int col = tpitg[0];\n"
         "  const int ib  = tgpig[0] / args->ne01;\n"
         "  const int i00 = ib * ntg.x;\n"
         "  const int i01 = tgpig[0] % args->ne01;\n"
         "  const int i02 = tgpig[1];\n"
         "  const int i03 = tgpig[2];\n"
         "  device const float *src0_row =\n"
         "    (device const float *)(src0 + args->nb01*i01 + args->nb02*i02 + args->nb03*i03);\n"
         "  /* initialize indices */\n"
         "  shmem_i32[col] = i00 + col;\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  /* Bitonic sort, descending order */\n"
         "  for (int k = 2; k <= (int)ntg.x; k *= 2) {\n"
         "    for (int j = k / 2; j > 0; j /= 2) {\n"
         "      int ixj = col ^ j;\n"
         "      if (ixj > col) {\n"
         "        if ((col & k) == 0) {\n"
         "          /* descending: swap if col-element < ixj-element */\n"
         "          if (shmem_i32[col] >= args->ne00 ||\n"
         "             (shmem_i32[ixj] <  args->ne00 &&\n"
         "              src0_row[shmem_i32[col]] < src0_row[shmem_i32[ixj]]))\n"
         "          {\n"
         "            SWAP(shmem_i32[col], shmem_i32[ixj]);\n"
         "          }\n"
         "        } else {\n"
         "          if (shmem_i32[ixj] >= args->ne00 ||\n"
         "             (shmem_i32[col] <  args->ne00 &&\n"
         "              src0_row[shmem_i32[col]] > src0_row[shmem_i32[ixj]]))\n"
         "          {\n"
         "            SWAP(shmem_i32[col], shmem_i32[ixj]);\n"
         "          }\n"
         "        }\n"
         "      }\n"
         "      threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "    }\n"
         "  }\n"
         "  const int64_t i0 = (int64_t)ib * args->top_k;\n"
         "  if (i0 + col < args->ne0 && col < args->top_k) {\n"
         "    dst[i03 * args->ne0 * args->ne1 * args->ne2 +\n"
         "        i02 * args->ne0 * args->ne1 +\n"
         "        i01 * args->ne0 + i0 + col] = shmem_i32[col];\n"
         "  }\n"
         "}\n";

    g_argsort_f32_i32_desc_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_argsort_f32_i32_desc_mtl4", @"argsort_f32_i32_desc_mtl4", 1024, NULL, 0);
    g_argsort_f32_i32_desc_mtl4_init_ok = (g_argsort_f32_i32_desc_mtl4_pipeline != nil) ? 1 : 0;
    return g_argsort_f32_i32_desc_mtl4_init_ok;
}

int ds4_gpu_mtl4_argsort_f32_i32_desc_canary(uint32_t row_n, uint32_t top_k) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_argsort_f32_i32_desc_mtl4_pipeline_init()) return 0;
    if (row_n == 0 || top_k == 0 || top_k > row_n) {
        fprintf(stderr, "ds4: argsort canary needs row_n>0 and 0<top_k<=row_n\n");
        return 0;
    }
    /* row_n must be power of 2 for the bitonic sort */
    if ((row_n & (row_n - 1)) != 0) {
        fprintf(stderr, "ds4: argsort canary row_n must be power of 2\n");
        return 0;
    }

    /* Canary input: row = [row_n - 1, row_n - 2, ..., 1, 0] (descending values).
     * Descending argsort: position of largest (row_n - 1) is at index 0.
     * So output indices = [0, 1, 2, ..., top_k - 1]. */
    float *host_src = (float *)calloc(row_n, sizeof(float));
    int32_t *host_dst = (int32_t *)calloc(top_k, sizeof(int32_t));
    if (!host_src || !host_dst) { free(host_src); free(host_dst); return 0; }
    for (uint32_t i = 0; i < row_n; i++) {
        host_src[i] = (float)(row_n - 1 - i);
    }

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:80
                                                      options:MTLResourceStorageModeShared];
        id<MTLBuffer> srcBuf = [g_device newBufferWithBytes:host_src
                                                     length:row_n * sizeof(float)
                                                    options:MTLResourceStorageModeShared];
        id<MTLBuffer> dstBuf = [g_device newBufferWithLength:top_k * sizeof(int32_t)
                                                     options:MTLResourceStorageModeShared];

        struct {
            int32_t ne00, ne01, ne02, ne03;
            uint64_t nb00, nb01, nb02, nb03;
            int32_t ne0, ne1, ne2, ne3;
            int32_t top_k_;
        } args = {
            .ne00 = (int32_t)row_n, .ne01 = 1, .ne02 = 1, .ne03 = 1,
            .nb00 = sizeof(float),
            .nb01 = (uint64_t)row_n * sizeof(float),
            .nb02 = (uint64_t)row_n * sizeof(float),
            .nb03 = (uint64_t)row_n * sizeof(float),
            .ne0 = (int32_t)top_k, .ne1 = 1, .ne2 = 1, .ne3 = 1,
            .top_k_ = (int32_t)top_k,
        };
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 4;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[3] = {
                (id<MTLAllocation>)argsBuf,
                (id<MTLAllocation>)srcBuf,
                (id<MTLAllocation>)dstBuf,
            };
            [residency addAllocations:allocs count:3];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(4);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:srcBuf.gpuAddress atIndex:1];
                [argTable setAddress:dstBuf.gpuAddress atIndex:2];

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_argsort_f32_i32_desc_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                /* shmem: row_n int32 slots */
                [enc setThreadgroupMemoryLength:row_n * sizeof(int32_t) atIndex:0];
                [enc dispatchThreadgroups:MTLSizeMake(1, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(row_n, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) {
                    (void)fb; dispatch_semaphore_signal(sem);
                }];
                id<MTL4CommandBuffer> bufs[1] = { cb };
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem,
                    dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_dst, dstBuf.contents, top_k * sizeof(int32_t));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 4);
            }
        }
    }
    if (!rc) { free(host_src); free(host_dst); return 0; }

    /* Validate: dst[i] should equal i (position of largest = 0, next = 1, ...) */
    int mismatch = 0;
    for (uint32_t i = 0; i < top_k; i++) {
        if (host_dst[i] != (int32_t)i) mismatch++;
    }
    fprintf(stderr,
        "ds4: argsort_f32_i32_desc MTL4 canary row_n=%u top_k=%u "
        "dst[0]=%d (ref=0) dst[1]=%d (ref=1) dst[end]=%d (ref=%u) mismatch=%d\n",
        row_n, top_k,
        host_dst[0], host_dst[1],
        host_dst[top_k - 1], top_k - 1,
        mismatch);
    free(host_src); free(host_dst);
    return (mismatch == 0) ? 1 : 0;
}

/* ============================================================ */
/* cpy_f32_f32 MTL4 port (silv 2026-05-27 task #693)              */
/* ============================================================ */
/* MTL4 port of kernel_cpy_t_t<float, float> from metal/cpy.metal.
 * Typed copy/conversion between graph tensors. DS4 uses this for
 * layout materialization + F32/F16 conversions at graph boundaries
 * (KV/cache packing, compressor pooling, FlashAttention staging).
 *
 * This port is the f32→f32 specialization; the templated MSL form
 * also supports f32↔f16 conversions which would be ported similarly
 * with the half/float buffer types swapped. */

static id<MTLComputePipelineState> g_cpy_f32_f32_mtl4_pipeline;
static int g_cpy_f32_f32_mtl4_init_attempted;
static int g_cpy_f32_f32_mtl4_init_ok;

static int ds4_cpy_f32_f32_mtl4_pipeline_init(void) {
    if (g_cpy_f32_f32_mtl4_init_attempted) return g_cpy_f32_f32_mtl4_init_ok;
    g_cpy_f32_f32_mtl4_init_attempted = 1;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "struct cpy_args {\n"
         "  int64_t nk0;\n"
         "  int64_t ne00; int64_t ne01; int64_t ne02; int64_t ne03;\n"
         "  uint64_t nb00; uint64_t nb01; uint64_t nb02; uint64_t nb03;\n"
         "  int64_t ne0; int64_t ne1; int64_t ne2; int64_t ne3;\n"
         "  uint64_t nb0; uint64_t nb1; uint64_t nb2; uint64_t nb3;\n"
         "};\n"
         "kernel void cpy_f32_f32_mtl4(\n"
         "    device const cpy_args *args [[buffer(0)]],\n"
         "    device const char     *src0 [[buffer(1)]],\n"
         "    device       char     *dst  [[buffer(2)]],\n"
         "    uint3   tgpig [[threadgroup_position_in_grid]],\n"
         "    ushort  tiitg [[thread_index_in_threadgroup]],\n"
         "    ushort3 ntg   [[threads_per_threadgroup]]) {\n"
         "  const int i03 = tgpig[2];\n"
         "  const int i02 = tgpig[1];\n"
         "  const int i01 = ntg[1] == 1 ? tgpig[0] % args->ne01\n"
         "                              : tgpig[0] * ntg[1] + tiitg / ntg[0];\n"
         "  const int iw0 = ntg[1] == 1 ? tgpig[0] / args->ne01 : 0;\n"
         "  const int64_t n = i03*args->ne02*args->ne01*args->ne00\n"
         "                  + i02*args->ne01*args->ne00\n"
         "                  + i01*args->ne00;\n"
         "  const int64_t i3 = n / (args->ne2*args->ne1*args->ne0);\n"
         "  const int64_t i2 = (n - i3*args->ne2*args->ne1*args->ne0) / (args->ne1*args->ne0);\n"
         "  const int64_t i1 = (n - i3*args->ne2*args->ne1*args->ne0\n"
         "                        - i2*args->ne1*args->ne0) / args->ne0;\n"
         "  const int64_t i0 = (n - i3*args->ne2*args->ne1*args->ne0\n"
         "                        - i2*args->ne1*args->ne0\n"
         "                        - i1*args->ne0);\n"
         "  device float *dst_data = (device float *)\n"
         "    (dst + i3*args->nb3 + i2*args->nb2 + i1*args->nb1 + i0*args->nb0);\n"
         "  for (int64_t i00 = iw0*ntg[0] + tiitg % ntg[0]; i00 < args->ne00; ) {\n"
         "    device const float *src = (device const float *)\n"
         "      (src0 + i03*args->nb03 + i02*args->nb02 + i01*args->nb01 + i00*args->nb00);\n"
         "    dst_data[i00] = (float)src[0];\n"
         "    break;\n"
         "  }\n"
         "}\n";

    g_cpy_f32_f32_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_cpy_f32_f32_mtl4", @"cpy_f32_f32_mtl4", 256, NULL, 0);
    g_cpy_f32_f32_mtl4_init_ok = (g_cpy_f32_f32_mtl4_pipeline != nil) ? 1 : 0;
    return g_cpy_f32_f32_mtl4_init_ok;
}

int ds4_gpu_mtl4_cpy_f32_f32_canary(uint32_t n_rows, uint32_t row_width) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_cpy_f32_f32_mtl4_pipeline_init()) return 0;
    if (n_rows == 0 || row_width == 0) {
        fprintf(stderr, "ds4: cpy_f32_f32 canary requires n_rows>0 and row_width>0\n");
        return 0;
    }

    /* Canary: src[r, c] = r*1000 + c. Expected: dst = src exactly.
     * Simple contiguous 2D tensor — ne00=row_width, ne01=n_rows. */
    const uint64_t total = (uint64_t)n_rows * row_width;
    float *host_src = (float *)calloc(total, sizeof(float));
    float *host_dst = (float *)calloc(total, sizeof(float));
    if (!host_src || !host_dst) { free(host_src); free(host_dst); return 0; }
    for (uint32_t r = 0; r < n_rows; r++) {
        for (uint32_t c = 0; c < row_width; c++) {
            host_src[(uint64_t)r * row_width + c] = (float)((int)r * 1000 + (int)c);
        }
    }

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:144
                                                      options:MTLResourceStorageModeShared];
        id<MTLBuffer> srcBuf = [g_device newBufferWithBytes:host_src
                                                     length:total * sizeof(float)
                                                    options:MTLResourceStorageModeShared];
        id<MTLBuffer> dstBuf = [g_device newBufferWithLength:total * sizeof(float)
                                                     options:MTLResourceStorageModeShared];

        struct {
            int64_t nk0;
            int64_t ne00, ne01, ne02, ne03;
            uint64_t nb00, nb01, nb02, nb03;
            int64_t ne0, ne1, ne2, ne3;
            uint64_t nb0, nb1, nb2, nb3;
        } args = {
            .nk0 = 1,
            .ne00 = row_width, .ne01 = n_rows, .ne02 = 1, .ne03 = 1,
            .nb00 = sizeof(float),
            .nb01 = (uint64_t)row_width * sizeof(float),
            .nb02 = (uint64_t)n_rows * row_width * sizeof(float),
            .nb03 = (uint64_t)n_rows * row_width * sizeof(float),
            .ne0 = row_width, .ne1 = n_rows, .ne2 = 1, .ne3 = 1,
            .nb0 = sizeof(float),
            .nb1 = (uint64_t)row_width * sizeof(float),
            .nb2 = (uint64_t)n_rows * row_width * sizeof(float),
            .nb3 = (uint64_t)n_rows * row_width * sizeof(float),
        };
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 4;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[3] = {
                (id<MTLAllocation>)argsBuf,
                (id<MTLAllocation>)srcBuf,
                (id<MTLAllocation>)dstBuf,
            };
            [residency addAllocations:allocs count:3];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(4);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:srcBuf.gpuAddress atIndex:1];
                [argTable setAddress:dstBuf.gpuAddress atIndex:2];

                /* Dispatch: 1 thread per output element. Use ntg.y=1 path
                 * (the simpler indexing branch). One tg per row × ceil(row_width/ntg.x). */
                NSUInteger nth = MIN((NSUInteger)256, MAX((NSUInteger)1, (NSUInteger)row_width));
                NSUInteger W = ((NSUInteger)row_width + nth - 1u) / nth;
                NSUInteger gx = (NSUInteger)n_rows * W;

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_cpy_f32_f32_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc dispatchThreadgroups:MTLSizeMake(gx, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) {
                    (void)fb; dispatch_semaphore_signal(sem);
                }];
                id<MTL4CommandBuffer> bufs[1] = { cb };
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem,
                    dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_dst, dstBuf.contents, total * sizeof(float));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 4);
            }
        }
    }
    if (!rc) { free(host_src); free(host_dst); return 0; }

    double max_abs = 0.0;
    int mismatch = 0;
    for (uint64_t i = 0; i < total; i++) {
        const double d = fabs((double)(host_dst[i] - host_src[i]));
        if (d > max_abs) max_abs = d;
        if (d > 1.0e-6) mismatch++;
    }
    fprintf(stderr,
        "ds4: cpy_f32_f32 MTL4 canary n_rows=%u row_width=%u "
        "dst[0,0]=%.1f (ref=0.0) dst[end]=%.1f mismatch=%d max_abs=%.4e\n",
        n_rows, row_width,
        (double)host_dst[0],
        (double)host_dst[total - 1],
        mismatch, max_abs);
    free(host_src); free(host_dst);
    return (mismatch == 0) ? 1 : 0;
}

/* ============================================================ */
/* dsv4_hc_split_weighted_sum MTL4 port (silv 2026-05-27 task #694) */
/* ============================================================ */
/* MTL4 port of kernel_dsv4_hc_split_weighted_sum from metal/dsv4_hc.metal.
 * Decode-side fusion of HC=4 split + HC-weighted reduction. One
 * threadgroup handles one token row:
 *   - tid 0 runs the entire #690 hc_split_sinkhorn split path, writes
 *     pre+post+comb into split[], and stashes pre[0..3] in shared mem
 *   - All threads then compute embedding[d] = sum_{h=0..3} x[d,h] × pre[h]
 *
 * Per-token dispatch with width-parallel reduction. */

static id<MTLComputePipelineState> g_hc_split_weighted_sum_mtl4_pipeline;
static int g_hc_split_weighted_sum_mtl4_init_attempted;
static int g_hc_split_weighted_sum_mtl4_init_ok;

static int ds4_hc_split_weighted_sum_mtl4_pipeline_init(void) {
    if (g_hc_split_weighted_sum_mtl4_init_attempted) return g_hc_split_weighted_sum_mtl4_init_ok;
    g_hc_split_weighted_sum_mtl4_init_attempted = 1;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "struct hcsw_args {\n"
         "  int64_t n_embd;\n"
         "  int32_t n_hc;\n"
         "  int32_t sinkhorn_iters;\n"
         "  int64_t n_rows;\n"
         "  int64_t mix_hc;\n"
         "  uint64_t nb_mix1;\n"
         "  uint64_t nb_split1;\n"
         "  uint64_t nb_x0;\n"
         "  uint64_t nb_x1;\n"
         "  uint64_t nb_x2;\n"
         "  uint64_t nb0;\n"
         "  uint64_t nb1;\n"
         "  float eps;\n"
         "};\n"
         "kernel void hc_split_weighted_sum_mtl4(\n"
         "    device const hcsw_args *args [[buffer(0)]],\n"
         "    device const char      *mixes [[buffer(1)]],\n"
         "    device const float     *scale [[buffer(2)]],\n"
         "    device const float     *base  [[buffer(3)]],\n"
         "    device const char      *x     [[buffer(4)]],\n"
         "    device       char      *split [[buffer(5)]],\n"
         "    device       char      *dst   [[buffer(6)]],\n"
         "    threadgroup  float     *pre_shmem [[threadgroup(0)]],\n"
         "    uint row [[threadgroup_position_in_grid]],\n"
         "    uint tid [[thread_position_in_threadgroup]],\n"
         "    uint ntg [[threads_per_threadgroup]]) {\n"
         "  if ((int64_t)row >= args->n_rows || args->n_hc != 4) return;\n"
         "  device const float *mix = (device const float *)(mixes + (uint64_t)row*args->nb_mix1);\n"
         "  device       float *out = (device       float *)(split + (uint64_t)row*args->nb_split1);\n"
         "  if (tid == 0) {\n"
         "    const float epsv = args->eps;\n"
         "    const float pre_s = scale[0];\n"
         "    const float post_s = scale[1];\n"
         "    const float comb_s = scale[2];\n"
         "    const float4 pre_z  = *((device const float4 *)mix)       * pre_s  + *((device const float4 *)base);\n"
         "    const float4 pre = 1.0f / (1.0f + exp(-pre_z)) + epsv;\n"
         "    *((device float4 *)out) = pre;\n"
         "    pre_shmem[0] = pre.x; pre_shmem[1] = pre.y;\n"
         "    pre_shmem[2] = pre.z; pre_shmem[3] = pre.w;\n"
         "    const float4 post_z = *((device const float4 *)(mix + 4)) * post_s + *((device const float4 *)(base + 4));\n"
         "    *((device float4 *)(out + 4)) = 2.0f / (1.0f + exp(-post_z));\n"
         "    /* Sinkhorn 4×4 with stable row-softmax */\n"
         "    float4 r0 = *((device const float4 *)(mix +  8)) * comb_s + *((device const float4 *)(base +  8));\n"
         "    float4 r1 = *((device const float4 *)(mix + 12)) * comb_s + *((device const float4 *)(base + 12));\n"
         "    float4 r2 = *((device const float4 *)(mix + 16)) * comb_s + *((device const float4 *)(base + 16));\n"
         "    float4 r3 = *((device const float4 *)(mix + 20)) * comb_s + *((device const float4 *)(base + 20));\n"
         "    const float m0 = max(max(r0.x, r0.y), max(r0.z, r0.w));\n"
         "    const float m1 = max(max(r1.x, r1.y), max(r1.z, r1.w));\n"
         "    const float m2 = max(max(r2.x, r2.y), max(r2.z, r2.w));\n"
         "    const float m3 = max(max(r3.x, r3.y), max(r3.z, r3.w));\n"
         "    r0 = exp(r0 - m0); r1 = exp(r1 - m1); r2 = exp(r2 - m2); r3 = exp(r3 - m3);\n"
         "    r0 = r0 * (1.0f / (r0.x + r0.y + r0.z + r0.w)) + epsv;\n"
         "    r1 = r1 * (1.0f / (r1.x + r1.y + r1.z + r1.w)) + epsv;\n"
         "    r2 = r2 * (1.0f / (r2.x + r2.y + r2.z + r2.w)) + epsv;\n"
         "    r3 = r3 * (1.0f / (r3.x + r3.y + r3.z + r3.w)) + epsv;\n"
         "    float4 col_inv = 1.0f / (r0 + r1 + r2 + r3 + epsv);\n"
         "    r0 *= col_inv; r1 *= col_inv; r2 *= col_inv; r3 *= col_inv;\n"
         "    for (int iter = 1; iter < args->sinkhorn_iters; ++iter) {\n"
         "      r0 *= 1.0f / (r0.x + r0.y + r0.z + r0.w + epsv);\n"
         "      r1 *= 1.0f / (r1.x + r1.y + r1.z + r1.w + epsv);\n"
         "      r2 *= 1.0f / (r2.x + r2.y + r2.z + r2.w + epsv);\n"
         "      r3 *= 1.0f / (r3.x + r3.y + r3.z + r3.w + epsv);\n"
         "      col_inv = 1.0f / (r0 + r1 + r2 + r3 + epsv);\n"
         "      r0 *= col_inv; r1 *= col_inv; r2 *= col_inv; r3 *= col_inv;\n"
         "    }\n"
         "    *((device float4 *)(out +  8)) = r0;\n"
         "    *((device float4 *)(out + 12)) = r1;\n"
         "    *((device float4 *)(out + 16)) = r2;\n"
         "    *((device float4 *)(out + 20)) = r3;\n"
         "  }\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  /* All threads: per-d HC-weighted sum into dst */\n"
         "  for (int64_t d = tid; d < args->n_embd; d += ntg) {\n"
         "    float acc = 0.0f;\n"
         "    acc += *((device const float *)(x + d*args->nb_x0 + 0*args->nb_x1 + (uint64_t)row*args->nb_x2)) * pre_shmem[0];\n"
         "    acc += *((device const float *)(x + d*args->nb_x0 + 1*args->nb_x1 + (uint64_t)row*args->nb_x2)) * pre_shmem[1];\n"
         "    acc += *((device const float *)(x + d*args->nb_x0 + 2*args->nb_x1 + (uint64_t)row*args->nb_x2)) * pre_shmem[2];\n"
         "    acc += *((device const float *)(x + d*args->nb_x0 + 3*args->nb_x1 + (uint64_t)row*args->nb_x2)) * pre_shmem[3];\n"
         "    *((device float *)(dst + d*args->nb0 + (uint64_t)row*args->nb1)) = acc;\n"
         "  }\n"
         "}\n";

    g_hc_split_weighted_sum_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_hc_split_weighted_sum_mtl4", @"hc_split_weighted_sum_mtl4", 256, NULL, 0);
    g_hc_split_weighted_sum_mtl4_init_ok = (g_hc_split_weighted_sum_mtl4_pipeline != nil) ? 1 : 0;
    return g_hc_split_weighted_sum_mtl4_init_ok;
}

int ds4_gpu_mtl4_hc_split_weighted_sum_canary(uint32_t n_rows, uint32_t n_embd) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_hc_split_weighted_sum_mtl4_pipeline_init()) return 0;
    if (n_rows == 0 || n_embd == 0) {
        fprintf(stderr, "ds4: hc_split_weighted_sum canary requires n_rows>0 and n_embd>0\n");
        return 0;
    }

    /* Canary: mix=0, base=0, scale=[1,1,1], eps=0, x[d,h,r] = 1.0.
     * Expected:
     *   pre[0..3] = sigmoid(0) = 0.5
     *   post[4..7] = 2*sigmoid(0) = 1.0
     *   comb[8..23] = 0.25 (uniform 4×4 doubly-stochastic)
     *   dst[d, r] = sum_{h=0..3} 1.0 × 0.5 = 2.0 */
    const uint32_t mix_hc = 24;
    const uint64_t mix_total = (uint64_t)n_rows * mix_hc;
    const uint64_t split_total = (uint64_t)n_rows * mix_hc;
    const uint64_t x_total = (uint64_t)n_embd * 4 * n_rows;
    const uint64_t dst_total = (uint64_t)n_embd * n_rows;

    float *host_mix = (float *)calloc(mix_total, sizeof(float));
    float *host_scale = (float *)calloc(3, sizeof(float));
    float *host_base = (float *)calloc(mix_hc, sizeof(float));
    float *host_x = (float *)calloc(x_total, sizeof(float));
    float *host_split = (float *)calloc(split_total, sizeof(float));
    float *host_dst = (float *)calloc(dst_total, sizeof(float));
    if (!host_mix || !host_scale || !host_base || !host_x || !host_split || !host_dst) {
        free(host_mix); free(host_scale); free(host_base);
        free(host_x); free(host_split); free(host_dst);
        return 0;
    }
    host_scale[0] = host_scale[1] = host_scale[2] = 1.0f;
    for (uint64_t i = 0; i < x_total; i++) host_x[i] = 1.0f;

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:96
                                                      options:MTLResourceStorageModeShared];
        id<MTLBuffer> mixBuf = [g_device newBufferWithBytes:host_mix
                                                     length:mix_total * sizeof(float)
                                                    options:MTLResourceStorageModeShared];
        id<MTLBuffer> scaleBuf = [g_device newBufferWithBytes:host_scale
                                                       length:3 * sizeof(float)
                                                      options:MTLResourceStorageModeShared];
        id<MTLBuffer> baseBuf = [g_device newBufferWithBytes:host_base
                                                      length:mix_hc * sizeof(float)
                                                     options:MTLResourceStorageModeShared];
        id<MTLBuffer> xBuf = [g_device newBufferWithBytes:host_x
                                                   length:x_total * sizeof(float)
                                                  options:MTLResourceStorageModeShared];
        id<MTLBuffer> splitBuf = [g_device newBufferWithLength:split_total * sizeof(float)
                                                       options:MTLResourceStorageModeShared];
        id<MTLBuffer> dstBuf = [g_device newBufferWithLength:dst_total * sizeof(float)
                                                     options:MTLResourceStorageModeShared];

        struct {
            int64_t n_embd_;
            int32_t n_hc_, sinkhorn_iters_;
            int64_t n_rows_, mix_hc_;
            uint64_t nb_mix1_, nb_split1_;
            uint64_t nb_x0_, nb_x1_, nb_x2_;
            uint64_t nb0_, nb1_;
            float eps_;
            uint32_t pad;
        } args = {
            .n_embd_ = (int64_t)n_embd,
            .n_hc_ = 4, .sinkhorn_iters_ = 1,
            .n_rows_ = (int64_t)n_rows, .mix_hc_ = mix_hc,
            .nb_mix1_ = (uint64_t)mix_hc * sizeof(float),
            .nb_split1_ = (uint64_t)mix_hc * sizeof(float),
            .nb_x0_ = sizeof(float),
            .nb_x1_ = (uint64_t)n_embd * sizeof(float),
            .nb_x2_ = (uint64_t)n_embd * 4 * sizeof(float),
            .nb0_ = sizeof(float),
            .nb1_ = (uint64_t)n_embd * sizeof(float),
            .eps_ = 0.0f,
        };
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 8;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[7] = {
                (id<MTLAllocation>)argsBuf,
                (id<MTLAllocation>)mixBuf,
                (id<MTLAllocation>)scaleBuf,
                (id<MTLAllocation>)baseBuf,
                (id<MTLAllocation>)xBuf,
                (id<MTLAllocation>)splitBuf,
                (id<MTLAllocation>)dstBuf,
            };
            [residency addAllocations:allocs count:7];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(8);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:mixBuf.gpuAddress atIndex:1];
                [argTable setAddress:scaleBuf.gpuAddress atIndex:2];
                [argTable setAddress:baseBuf.gpuAddress atIndex:3];
                [argTable setAddress:xBuf.gpuAddress atIndex:4];
                [argTable setAddress:splitBuf.gpuAddress atIndex:5];
                [argTable setAddress:dstBuf.gpuAddress atIndex:6];

                NSUInteger nth = MIN((NSUInteger)256, MAX((NSUInteger)1, (NSUInteger)n_embd));

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_hc_split_weighted_sum_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                /* shmem: pre_shmem[4] = 16 bytes */
                [enc setThreadgroupMemoryLength:16 atIndex:0];
                [enc dispatchThreadgroups:MTLSizeMake(n_rows, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) {
                    (void)fb; dispatch_semaphore_signal(sem);
                }];
                id<MTL4CommandBuffer> bufs[1] = { cb };
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem,
                    dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_split, splitBuf.contents, split_total * sizeof(float));
                    memcpy(host_dst, dstBuf.contents, dst_total * sizeof(float));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 8);
            }
        }
    }
    if (!rc) {
        free(host_mix); free(host_scale); free(host_base);
        free(host_x); free(host_split); free(host_dst);
        return 0;
    }

    /* Validate */
    double split_dev = 0.0, dst_dev = 0.0;
    for (uint32_t r = 0; r < n_rows; r++) {
        const float *s = host_split + (uint64_t)r * mix_hc;
        for (int i = 0; i < 4; i++) {
            double d = fabs((double)(s[i] - 0.5));
            if (d > split_dev) split_dev = d;
        }
        for (int i = 4; i < 8; i++) {
            double d = fabs((double)(s[i] - 1.0));
            if (d > split_dev) split_dev = d;
        }
        for (int i = 8; i < 24; i++) {
            double d = fabs((double)(s[i] - 0.25));
            if (d > split_dev) split_dev = d;
        }
        for (uint32_t d = 0; d < n_embd; d++) {
            double e = fabs((double)(host_dst[(uint64_t)r * n_embd + d] - 2.0));
            if (e > dst_dev) dst_dev = e;
        }
    }
    fprintf(stderr,
        "ds4: hc_split_weighted_sum MTL4 canary n_rows=%u n_embd=%u "
        "split[0]=%.4f (ref=0.5) split[4]=%.4f (ref=1.0) split[8]=%.4f (ref=0.25) "
        "dst[0,0]=%.4f (ref=2.0) split_dev=%.4e dst_dev=%.4e\n",
        n_rows, n_embd,
        (double)host_split[0], (double)host_split[4], (double)host_split[8],
        (double)host_dst[0],
        split_dev, dst_dev);
    free(host_mix); free(host_scale); free(host_base);
    free(host_x); free(host_split); free(host_dst);
    return (split_dev < 1.0e-6 && dst_dev < 1.0e-6) ? 1 : 0;
}

/* ============================================================ */
/* dsv4_rope_tail_f32 MTL4 port (silv 2026-05-27 task #695)       */
/* ============================================================ */
/* MTL4 port of kernel_dsv4_rope_tail_f32 from metal/dsv4_rope.metal.
 * DeepSeek V4's partial RoPE: the no-position prefix (first n_nope =
 * ne00 - n_dims elements) is copied unchanged, the rotated tail is
 * transformed via YaRN-scaled rotary embedding.
 *
 * NEW patterns:
 *   - YaRN helper functions inlined: ramp, corr_factor, corr_dims, yarn
 *   - Two RoPE variants: interleaved (mode != 2) + NeoX (mode == 2)
 *   - Optional src2 freq_factor table
 *   - Inverse rotation support (sin → -sin)
 *
 * Per-token dispatch: (n_seq, n_tokens, n_batches) tg × (ntg, 1, 1) threads.
 * Canary uses pos=0 (theta=0 → cos=1, sin=0) so rotation is identity. */

static id<MTLComputePipelineState> g_rope_tail_f32_mtl4_pipeline;
static int g_rope_tail_f32_mtl4_init_attempted;
static int g_rope_tail_f32_mtl4_init_ok;

static int ds4_rope_tail_f32_mtl4_pipeline_init(void) {
    if (g_rope_tail_f32_mtl4_init_attempted) return g_rope_tail_f32_mtl4_init_ok;
    g_rope_tail_f32_mtl4_init_attempted = 1;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "static float rope_yarn_ramp(const float low, const float high, const int i0) {\n"
         "  const float y = (i0 / 2 - low) / max(0.001f, high - low);\n"
         "  return 1.0f - min(1.0f, max(0.0f, y));\n"
         "}\n"
         "static void rope_yarn(\n"
         "    float theta_extrap, float freq_scale, float corr_dims[2], int i0,\n"
         "    float ext_factor, float mscale,\n"
         "    thread float *cos_theta, thread float *sin_theta) {\n"
         "  float theta_interp = freq_scale * theta_extrap;\n"
         "  float theta = theta_interp;\n"
         "  if (ext_factor != 0.0f) {\n"
         "    float ramp_mix = rope_yarn_ramp(corr_dims[0], corr_dims[1], i0) * ext_factor;\n"
         "    theta = theta_interp * (1 - ramp_mix) + theta_extrap * ramp_mix;\n"
         "    mscale *= 1.0f + 0.1f * log(1.0f / freq_scale);\n"
         "  }\n"
         "  *cos_theta = cos(theta) * mscale;\n"
         "  *sin_theta = sin(theta) * mscale;\n"
         "}\n"
         "static float rope_yarn_corr_factor(int n_dims, int n_ctx_orig, float n_rot, float base) {\n"
         "  return n_dims * log(n_ctx_orig / (n_rot * 2 * M_PI_F)) / (2 * log(base));\n"
         "}\n"
         "static void rope_yarn_corr_dims(\n"
         "    int n_dims, int n_ctx_orig, float freq_base, float beta_fast, float beta_slow,\n"
         "    thread float *dims) {\n"
         "  dims[0] = max(0.0f, floor(rope_yarn_corr_factor(n_dims, n_ctx_orig, beta_fast, freq_base)));\n"
         "  dims[1] = min(n_dims - 1.0f, ceil(rope_yarn_corr_factor(n_dims, n_ctx_orig, beta_slow, freq_base)));\n"
         "}\n"
         "struct rt_args {\n"
         "  int64_t  ne00; int64_t  ne01; int64_t  ne02; int64_t  ne03;\n"
         "  uint64_t nb00; uint64_t nb01; uint64_t nb02; uint64_t nb03;\n"
         "  uint64_t nb0;  uint64_t nb1;  uint64_t nb2;  uint64_t nb3;\n"
         "  int32_t  n_dims; int32_t mode; int32_t n_ctx_orig; int32_t inverse;\n"
         "  float    freq_base; float freq_scale; float ext_factor; float attn_factor;\n"
         "  float    beta_fast; float beta_slow;\n"
         "  uint32_t src2_flag;  /* 1 if src2 is used for freq_factor table */\n"
         "};\n"
         "kernel void rope_tail_f32_mtl4(\n"
         "    device const rt_args *args [[buffer(0)]],\n"
         "    device const char    *src0 [[buffer(1)]],\n"
         "    device const char    *src1 [[buffer(2)]],   /* int32 positions */\n"
         "    device const char    *src2 [[buffer(3)]],   /* float freq_factors (optional) */\n"
         "    device       char    *dst  [[buffer(4)]],\n"
         "    uint    tid   [[thread_index_in_threadgroup]],\n"
         "    ushort3 ntg   [[threads_per_threadgroup]],\n"
         "    uint3   tgpig [[threadgroup_position_in_grid]]) {\n"
         "  const int i1 = tgpig[0];\n"
         "  const int i2 = tgpig[1];\n"
         "  const int i3 = tgpig[2];\n"
         "  const int n_nope = (int)args->ne00 - args->n_dims;\n"
         "  if (n_nope < 0) return;\n"
         "  device const int32_t *pos = (device const int32_t *)src1;\n"
         "  float corr_dims[2];\n"
         "  rope_yarn_corr_dims(args->n_dims, args->n_ctx_orig, args->freq_base,\n"
         "                       args->beta_fast, args->beta_slow, corr_dims);\n"
         "  const float theta_base = (float)pos[i2];\n"
         "  const float inv_ndims = -1.f / (float)args->n_dims;\n"
         "  const bool is_neox = args->mode == 2;\n"
         "  for (int i0 = (int)tid; i0 < (int)args->ne00; i0 += (int)ntg.x) {\n"
         "    device const char *src_base = src0 + i3*args->nb03 + i2*args->nb02 + i1*args->nb01;\n"
         "    device       char *dst_base = dst  + i3*args->nb3  + i2*args->nb2  + i1*args->nb1;\n"
         "    if (i0 < n_nope) {\n"
         "      *((device float *)(dst_base + i0*args->nb0)) =\n"
         "        *((device const float *)(src_base + i0*args->nb00));\n"
         "      continue;\n"
         "    }\n"
         "    const int r = i0 - n_nope;\n"
         "    if (is_neox) {\n"
         "      const int n_half = args->n_dims / 2;\n"
         "      if (r >= n_half) continue;\n"
         "      const int ic = r;\n"
         "      const int rel_i0 = 2 * ic;\n"
         "      const float theta = theta_base * pow(args->freq_base, inv_ndims * (float)rel_i0);\n"
         "      const float freq_factor = args->src2_flag ? ((device const float *)src2)[ic] : 1.0f;\n"
         "      float cos_theta, sin_theta;\n"
         "      rope_yarn(theta / freq_factor, args->freq_scale, corr_dims, rel_i0,\n"
         "                args->ext_factor, args->attn_factor, &cos_theta, &sin_theta);\n"
         "      if (args->inverse) sin_theta = -sin_theta;\n"
         "      const int j0 = n_nope + ic;\n"
         "      const int j1 = n_nope + ic + n_half;\n"
         "      const float x0 = *((device const float *)(src_base + j0*args->nb00));\n"
         "      const float x1 = *((device const float *)(src_base + j1*args->nb00));\n"
         "      *((device float *)(dst_base + j0*args->nb0)) = x0*cos_theta - x1*sin_theta;\n"
         "      *((device float *)(dst_base + j1*args->nb0)) = x0*sin_theta + x1*cos_theta;\n"
         "    } else {\n"
         "      if ((r & 1) != 0) continue;\n"
         "      const int ic = r / 2;\n"
         "      const float theta = theta_base * pow(args->freq_base, inv_ndims * (float)r);\n"
         "      const float freq_factor = args->src2_flag ? ((device const float *)src2)[ic] : 1.0f;\n"
         "      float cos_theta, sin_theta;\n"
         "      rope_yarn(theta / freq_factor, args->freq_scale, corr_dims, r,\n"
         "                args->ext_factor, args->attn_factor, &cos_theta, &sin_theta);\n"
         "      if (args->inverse) sin_theta = -sin_theta;\n"
         "      const int j0 = n_nope + r;\n"
         "      const int j1 = j0 + 1;\n"
         "      const float x0 = *((device const float *)(src_base + j0*args->nb00));\n"
         "      const float x1 = *((device const float *)(src_base + j1*args->nb00));\n"
         "      *((device float *)(dst_base + j0*args->nb0)) = x0*cos_theta - x1*sin_theta;\n"
         "      *((device float *)(dst_base + j1*args->nb0)) = x0*sin_theta + x1*cos_theta;\n"
         "    }\n"
         "  }\n"
         "}\n";

    g_rope_tail_f32_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_rope_tail_f32_mtl4", @"rope_tail_f32_mtl4", 256, NULL, 0);
    g_rope_tail_f32_mtl4_init_ok = (g_rope_tail_f32_mtl4_pipeline != nil) ? 1 : 0;
    return g_rope_tail_f32_mtl4_init_ok;
}

int ds4_gpu_mtl4_rope_tail_f32_canary(uint32_t head_dim, uint32_t n_rot, uint32_t mode) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_rope_tail_f32_mtl4_pipeline_init()) return 0;
    if (head_dim == 0 || n_rot > head_dim) {
        fprintf(stderr, "ds4: rope_tail canary requires head_dim>0 and n_rot<=head_dim\n");
        return 0;
    }

    /* Canary: pos[0]=0 → theta_base=0 → cos(0)=1, sin(0)=0
     * → x0' = x0*1 - x1*0 = x0
     *   x1' = x0*0 + x1*1 = x1
     * Identity rotation → dst = src exactly across both prefix + tail.
     * src[i] = (float)i for verification. */
    const uint32_t n_nope = head_dim - n_rot;
    float *host_src = (float *)calloc(head_dim, sizeof(float));
    int32_t host_pos[1] = { 0 };
    float *host_dst = (float *)calloc(head_dim, sizeof(float));
    if (!host_src || !host_dst) { free(host_src); free(host_dst); return 0; }
    for (uint32_t i = 0; i < head_dim; i++) host_src[i] = (float)i;
    (void)n_nope;

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:160
                                                      options:MTLResourceStorageModeShared];
        id<MTLBuffer> srcBuf = [g_device newBufferWithBytes:host_src
                                                     length:head_dim * sizeof(float)
                                                    options:MTLResourceStorageModeShared];
        id<MTLBuffer> posBuf = [g_device newBufferWithBytes:host_pos
                                                     length:sizeof(host_pos)
                                                    options:MTLResourceStorageModeShared];
        id<MTLBuffer> dstBuf = [g_device newBufferWithLength:head_dim * sizeof(float)
                                                     options:MTLResourceStorageModeShared];

        struct {
            int64_t ne00, ne01, ne02, ne03;
            uint64_t nb00, nb01, nb02, nb03;
            uint64_t nb0, nb1, nb2, nb3;
            int32_t n_dims, mode_, n_ctx_orig, inverse;
            float freq_base, freq_scale, ext_factor, attn_factor;
            float beta_fast, beta_slow;
            uint32_t src2_flag;
            uint32_t pad;
        } args = {
            .ne00 = head_dim, .ne01 = 1, .ne02 = 1, .ne03 = 1,
            .nb00 = sizeof(float),
            .nb01 = (uint64_t)head_dim * sizeof(float),
            .nb02 = (uint64_t)head_dim * sizeof(float),
            .nb03 = (uint64_t)head_dim * sizeof(float),
            .nb0 = sizeof(float),
            .nb1 = (uint64_t)head_dim * sizeof(float),
            .nb2 = (uint64_t)head_dim * sizeof(float),
            .nb3 = (uint64_t)head_dim * sizeof(float),
            .n_dims = (int32_t)n_rot,
            .mode_ = (int32_t)mode,
            .n_ctx_orig = 4096,
            .inverse = 0,
            .freq_base = 10000.0f,
            .freq_scale = 1.0f,
            .ext_factor = 0.0f,
            .attn_factor = 1.0f,
            .beta_fast = 32.0f, .beta_slow = 1.0f,
            .src2_flag = 0,
        };
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 6;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[5] = {
                (id<MTLAllocation>)argsBuf,
                (id<MTLAllocation>)srcBuf,
                (id<MTLAllocation>)posBuf,
                (id<MTLAllocation>)srcBuf,   /* src2 alias (src2_flag=0 so unused) */
                (id<MTLAllocation>)dstBuf,
            };
            [residency addAllocations:allocs count:5];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(6);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:srcBuf.gpuAddress atIndex:1];
                [argTable setAddress:posBuf.gpuAddress atIndex:2];
                [argTable setAddress:srcBuf.gpuAddress atIndex:3];   /* src2 unused */
                [argTable setAddress:dstBuf.gpuAddress atIndex:4];

                NSUInteger nth = MIN((NSUInteger)256, MAX((NSUInteger)1, (NSUInteger)head_dim));

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_rope_tail_f32_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc dispatchThreadgroups:MTLSizeMake(1, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) {
                    (void)fb; dispatch_semaphore_signal(sem);
                }];
                id<MTL4CommandBuffer> bufs[1] = { cb };
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem,
                    dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_dst, dstBuf.contents, head_dim * sizeof(float));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 6);
            }
        }
    }
    if (!rc) { free(host_src); free(host_dst); return 0; }

    /* pos=0 → identity rotation → dst should equal src exactly */
    double max_abs = 0.0;
    int mismatch = 0;
    for (uint32_t i = 0; i < head_dim; i++) {
        double d = fabs((double)(host_dst[i] - host_src[i]));
        if (d > max_abs) max_abs = d;
        if (d > 1.0e-5) mismatch++;
    }
    fprintf(stderr,
        "ds4: rope_tail_f32 MTL4 canary head_dim=%u n_rot=%u mode=%u "
        "dst[0]=%.1f (ref=0.0) dst[%u]=%.1f (ref=%.1f) "
        "dst[end]=%.1f mismatch=%d max_abs=%.4e\n",
        head_dim, n_rot, mode,
        (double)host_dst[0],
        head_dim - 1, (double)host_dst[head_dim - 1], (double)(head_dim - 1),
        (double)host_dst[head_dim - 1],
        mismatch, max_abs);
    free(host_src); free(host_dst);
    return (mismatch == 0) ? 1 : 0;
}

/* ============================================================ */
/* concat MTL4 port (silv 2026-05-27 task #696)                   */
/* ============================================================ */
/* MTL4 port of kernel_concat from metal/concat.metal. Concatenates
 * two float tensors along a chosen dim. DS4 uses this as a graph
 * utility for assembling attention inputs with the same layout as
 * downstream kernels expect. */

static id<MTLComputePipelineState> g_concat_mtl4_pipeline;
static int g_concat_mtl4_init_attempted;
static int g_concat_mtl4_init_ok;

static int ds4_concat_mtl4_pipeline_init(void) {
    if (g_concat_mtl4_init_attempted) return g_concat_mtl4_init_ok;
    g_concat_mtl4_init_attempted = 1;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "struct cc_args {\n"
         "  int32_t ne00; int32_t ne01; int32_t ne02; int32_t ne03;\n"
         "  uint64_t nb00; uint64_t nb01; uint64_t nb02; uint64_t nb03;\n"
         "  int32_t ne10; int32_t ne11; int32_t ne12; int32_t ne13;\n"
         "  uint64_t nb10; uint64_t nb11; uint64_t nb12; uint64_t nb13;\n"
         "  int32_t ne0; int32_t ne1; int32_t ne2; int32_t ne3;\n"
         "  uint64_t nb0; uint64_t nb1; uint64_t nb2; uint64_t nb3;\n"
         "  int32_t dim;\n"
         "};\n"
         "kernel void concat_mtl4(\n"
         "    device const cc_args *args [[buffer(0)]],\n"
         "    device const char    *src0 [[buffer(1)]],\n"
         "    device const char    *src1 [[buffer(2)]],\n"
         "    device       char    *dst  [[buffer(3)]],\n"
         "    uint3   tgpig [[threadgroup_position_in_grid]],\n"
         "    ushort3 tpitg [[thread_position_in_threadgroup]],\n"
         "    ushort3 ntg   [[threads_per_threadgroup]]) {\n"
         "  const int i3 = tgpig.z;\n"
         "  const int i2 = tgpig.y;\n"
         "  const int i1 = tgpig.x;\n"
         "  int o[4] = {0, 0, 0, 0};\n"
         "  o[args->dim] = args->dim == 0 ? args->ne00 :\n"
         "                  (args->dim == 1 ? args->ne01 :\n"
         "                   (args->dim == 2 ? args->ne02 : args->ne03));\n"
         "  device const float *x;\n"
         "  for (int i0 = tpitg.x; i0 < args->ne0; i0 += ntg.x) {\n"
         "    if (i0 < args->ne00 && i1 < args->ne01 && i2 < args->ne02 && i3 < args->ne03) {\n"
         "      x = (device const float *)(src0 + i3*args->nb03 + i2*args->nb02 + i1*args->nb01 + i0*args->nb00);\n"
         "    } else {\n"
         "      x = (device const float *)(src1 + (i3 - o[3])*args->nb13 + (i2 - o[2])*args->nb12 +\n"
         "                                  (i1 - o[1])*args->nb11 + (i0 - o[0])*args->nb10);\n"
         "    }\n"
         "    device float *y = (device float *)(dst + i3*args->nb3 + i2*args->nb2 + i1*args->nb1 + i0*args->nb0);\n"
         "    *y = *x;\n"
         "  }\n"
         "}\n";

    g_concat_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_concat_mtl4", @"concat_mtl4", 256, NULL, 0);
    g_concat_mtl4_init_ok = (g_concat_mtl4_pipeline != nil) ? 1 : 0;
    return g_concat_mtl4_init_ok;
}

int ds4_gpu_mtl4_concat_canary(uint32_t n0, uint32_t n1, uint32_t n_rows) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_concat_mtl4_pipeline_init()) return 0;
    if (n0 == 0 || n1 == 0 || n_rows == 0) {
        fprintf(stderr, "ds4: concat canary requires all sizes > 0\n");
        return 0;
    }

    /* Canary: concat two tensors along dim 0.
     *   src0[r, c] = (r * 10 + c),         for c in 0..n0
     *   src1[r, c] = (r * 10 + n0 + c),    for c in 0..n1
     *   dst[r, c]  = (r * 10 + c),         for c in 0..(n0+n1)
     * Each src row contributes its part to the dst row. */
    const uint32_t n_out = n0 + n1;
    const uint64_t s0_n = (uint64_t)n0 * n_rows;
    const uint64_t s1_n = (uint64_t)n1 * n_rows;
    const uint64_t dst_n = (uint64_t)n_out * n_rows;
    float *host_s0 = (float *)calloc(s0_n, sizeof(float));
    float *host_s1 = (float *)calloc(s1_n, sizeof(float));
    float *host_dst = (float *)calloc(dst_n, sizeof(float));
    if (!host_s0 || !host_s1 || !host_dst) {
        free(host_s0); free(host_s1); free(host_dst); return 0;
    }
    for (uint32_t r = 0; r < n_rows; r++) {
        for (uint32_t c = 0; c < n0; c++) host_s0[(uint64_t)r * n0 + c] = (float)((int)r * 10 + (int)c);
        for (uint32_t c = 0; c < n1; c++) host_s1[(uint64_t)r * n1 + c] = (float)((int)r * 10 + (int)n0 + (int)c);
    }

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:160
                                                      options:MTLResourceStorageModeShared];
        id<MTLBuffer> s0Buf = [g_device newBufferWithBytes:host_s0
                                                    length:s0_n * sizeof(float)
                                                   options:MTLResourceStorageModeShared];
        id<MTLBuffer> s1Buf = [g_device newBufferWithBytes:host_s1
                                                    length:s1_n * sizeof(float)
                                                   options:MTLResourceStorageModeShared];
        id<MTLBuffer> dstBuf = [g_device newBufferWithLength:dst_n * sizeof(float)
                                                     options:MTLResourceStorageModeShared];

        struct {
            int32_t ne00, ne01, ne02, ne03;
            uint64_t nb00, nb01, nb02, nb03;
            int32_t ne10, ne11, ne12, ne13;
            uint64_t nb10, nb11, nb12, nb13;
            int32_t ne0, ne1, ne2, ne3;
            uint64_t nb0, nb1, nb2, nb3;
            int32_t dim_; uint32_t pad;
        } args = {
            .ne00 = (int32_t)n0, .ne01 = (int32_t)n_rows, .ne02 = 1, .ne03 = 1,
            .nb00 = sizeof(float),
            .nb01 = (uint64_t)n0 * sizeof(float),
            .nb02 = (uint64_t)n0 * n_rows * sizeof(float),
            .nb03 = (uint64_t)n0 * n_rows * sizeof(float),
            .ne10 = (int32_t)n1, .ne11 = (int32_t)n_rows, .ne12 = 1, .ne13 = 1,
            .nb10 = sizeof(float),
            .nb11 = (uint64_t)n1 * sizeof(float),
            .nb12 = (uint64_t)n1 * n_rows * sizeof(float),
            .nb13 = (uint64_t)n1 * n_rows * sizeof(float),
            .ne0 = (int32_t)n_out, .ne1 = (int32_t)n_rows, .ne2 = 1, .ne3 = 1,
            .nb0 = sizeof(float),
            .nb1 = (uint64_t)n_out * sizeof(float),
            .nb2 = (uint64_t)n_out * n_rows * sizeof(float),
            .nb3 = (uint64_t)n_out * n_rows * sizeof(float),
            .dim_ = 0,
        };
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 4;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[4] = {
                (id<MTLAllocation>)argsBuf,
                (id<MTLAllocation>)s0Buf,
                (id<MTLAllocation>)s1Buf,
                (id<MTLAllocation>)dstBuf,
            };
            [residency addAllocations:allocs count:4];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(4);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:s0Buf.gpuAddress atIndex:1];
                [argTable setAddress:s1Buf.gpuAddress atIndex:2];
                [argTable setAddress:dstBuf.gpuAddress atIndex:3];

                NSUInteger nth = MIN((NSUInteger)256, MAX((NSUInteger)1, (NSUInteger)n_out));

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_concat_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc dispatchThreadgroups:MTLSizeMake(n_rows, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) {
                    (void)fb; dispatch_semaphore_signal(sem);
                }];
                id<MTL4CommandBuffer> bufs[1] = { cb };
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem,
                    dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_dst, dstBuf.contents, dst_n * sizeof(float));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 4);
            }
        }
    }
    if (!rc) { free(host_s0); free(host_s1); free(host_dst); return 0; }

    /* Validate: dst[r, c] = r*10 + c for c in [0, n_out) */
    double max_abs = 0.0;
    int mismatch = 0;
    for (uint32_t r = 0; r < n_rows; r++) {
        for (uint32_t c = 0; c < n_out; c++) {
            const float v = host_dst[(uint64_t)r * n_out + c];
            const float ref = (float)((int)r * 10 + (int)c);
            const double d = fabs((double)(v - ref));
            if (d > max_abs) max_abs = d;
            if (d > 1.0e-6) mismatch++;
        }
    }
    fprintf(stderr,
        "ds4: concat MTL4 canary n0=%u n1=%u n_rows=%u "
        "dst[0,0]=%.1f (ref=0.0) dst[0,n0]=%.1f (ref=%.1f) "
        "dst[end]=%.1f mismatch=%d max_abs=%.4e\n",
        n0, n1, n_rows,
        (double)host_dst[0],
        (double)host_dst[n0], (double)n0,
        (double)host_dst[dst_n - 1],
        mismatch, max_abs);
    free(host_s0); free(host_s1); free(host_dst);
    return (mismatch == 0) ? 1 : 0;
}

/* ============================================================ */
/* dsv4_hc_split_weighted_sum_norm4 MTL4 port (silv 2026-05-27 #697) */
/* ============================================================ */
/* MTL4 port of kernel_dsv4_hc_split_weighted_sum_norm4. Three-stage
 * fused kernel:
 *   1. tid 0 runs HC=4 Sinkhorn split path (same as #690 / #694)
 *   2. All threads collapse HC streams into row_shmem[4096] +
 *      accumulate sumf for RMSNorm (cross-simd reduction)
 *   3. Write dst[i] = collapsed_v + norm_dst[i] = (v * rsqrt(rms))*w
 *
 * Hardcoded n_hc=4 and n_embd=4096 (DS4 production shape).
 * Threadgroup memory: row_shmem[4096] + pre_shmem[4] + sum_shmem[32]
 *   = 4132 floats × 4 bytes = 16528 bytes. Under Metal 32K tg limit. */

static id<MTLComputePipelineState> g_hc_split_weighted_sum_norm4_mtl4_pipeline;
static int g_hc_split_weighted_sum_norm4_mtl4_init_attempted;
static int g_hc_split_weighted_sum_norm4_mtl4_init_ok;

static int ds4_hc_split_weighted_sum_norm4_mtl4_pipeline_init(void) {
    if (g_hc_split_weighted_sum_norm4_mtl4_init_attempted) return g_hc_split_weighted_sum_norm4_mtl4_init_ok;
    g_hc_split_weighted_sum_norm4_mtl4_init_attempted = 1;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "struct hcswn_args {\n"
         "  int64_t  n_embd;\n"
         "  int32_t  n_hc;\n"
         "  int32_t  sinkhorn_iters;\n"
         "  int64_t  n_rows;\n"
         "  int64_t  mix_hc;\n"
         "  uint64_t nb_mix1;\n"
         "  uint64_t nb_split1;\n"
         "  uint64_t nb_x0;\n"
         "  uint64_t nb_x1;\n"
         "  uint64_t nb_x2;\n"
         "  uint64_t nb0;\n"
         "  uint64_t nb1;\n"
         "  uint64_t nb_norm1;\n"
         "  float    eps;\n"
         "  float    norm_eps;\n"
         "};\n"
         "kernel void hc_split_weighted_sum_norm4_mtl4(\n"
         "    device const hcswn_args *args [[buffer(0)]],\n"
         "    device const char       *mixes [[buffer(1)]],\n"
         "    device const float      *scale [[buffer(2)]],\n"
         "    device const float      *base  [[buffer(3)]],\n"
         "    device const char       *x     [[buffer(4)]],\n"
         "    device       char       *split [[buffer(5)]],\n"
         "    device       char       *dst   [[buffer(6)]],\n"
         "    device const char       *norm_weight [[buffer(7)]],\n"
         "    device       char       *norm_dst    [[buffer(8)]],\n"
         "    threadgroup  float      *shared [[threadgroup(0)]],\n"
         "    uint   row   [[threadgroup_position_in_grid]],\n"
         "    ushort tid   [[thread_position_in_threadgroup]],\n"
         "    ushort sgitg [[simdgroup_index_in_threadgroup]],\n"
         "    ushort tiisg [[thread_index_in_simdgroup]],\n"
         "    ushort ntg   [[threads_per_threadgroup]]) {\n"
         "  if ((int64_t)row >= args->n_rows || args->n_hc != 4 || args->n_embd != 4096) return;\n"
         "  threadgroup float4 *row_shmem = (threadgroup float4 *)shared;       /* [1024] = 4096 floats */\n"
         "  threadgroup float  *pre_shmem = shared + 4096;                       /* [4]  */\n"
         "  threadgroup float  *sum_shmem = pre_shmem + 4;                       /* [32] */\n"
         "  device const float *mix = (device const float *)(mixes + (uint64_t)row * args->nb_mix1);\n"
         "  device       float *out = (device       float *)(split + (uint64_t)row * args->nb_split1);\n"
         "  if (sgitg == 0) sum_shmem[tiisg] = 0.0f;\n"
         "  if (tid == 0) {\n"
         "    const float epsv = args->eps;\n"
         "    const float pre_s = scale[0];\n"
         "    const float post_s = scale[1];\n"
         "    const float comb_s = scale[2];\n"
         "    const float4 pre_z = *((device const float4 *)mix) * pre_s + *((device const float4 *)base);\n"
         "    const float4 pre = 1.0f / (1.0f + exp(-pre_z)) + epsv;\n"
         "    *((device float4 *)out) = pre;\n"
         "    pre_shmem[0] = pre.x; pre_shmem[1] = pre.y;\n"
         "    pre_shmem[2] = pre.z; pre_shmem[3] = pre.w;\n"
         "    const float4 post_z = *((device const float4 *)(mix + 4)) * post_s + *((device const float4 *)(base + 4));\n"
         "    *((device float4 *)(out + 4)) = 2.0f / (1.0f + exp(-post_z));\n"
         "    float4 r0 = *((device const float4 *)(mix +  8)) * comb_s + *((device const float4 *)(base +  8));\n"
         "    float4 r1 = *((device const float4 *)(mix + 12)) * comb_s + *((device const float4 *)(base + 12));\n"
         "    float4 r2 = *((device const float4 *)(mix + 16)) * comb_s + *((device const float4 *)(base + 16));\n"
         "    float4 r3 = *((device const float4 *)(mix + 20)) * comb_s + *((device const float4 *)(base + 20));\n"
         "    const float m0 = max(max(r0.x, r0.y), max(r0.z, r0.w));\n"
         "    const float m1 = max(max(r1.x, r1.y), max(r1.z, r1.w));\n"
         "    const float m2 = max(max(r2.x, r2.y), max(r2.z, r2.w));\n"
         "    const float m3 = max(max(r3.x, r3.y), max(r3.z, r3.w));\n"
         "    r0 = exp(r0 - m0); r1 = exp(r1 - m1); r2 = exp(r2 - m2); r3 = exp(r3 - m3);\n"
         "    r0 = r0 * (1.0f / (r0.x + r0.y + r0.z + r0.w)) + epsv;\n"
         "    r1 = r1 * (1.0f / (r1.x + r1.y + r1.z + r1.w)) + epsv;\n"
         "    r2 = r2 * (1.0f / (r2.x + r2.y + r2.z + r2.w)) + epsv;\n"
         "    r3 = r3 * (1.0f / (r3.x + r3.y + r3.z + r3.w)) + epsv;\n"
         "    float4 col_inv = 1.0f / (r0 + r1 + r2 + r3 + epsv);\n"
         "    r0 *= col_inv; r1 *= col_inv; r2 *= col_inv; r3 *= col_inv;\n"
         "    for (int iter = 1; iter < args->sinkhorn_iters; ++iter) {\n"
         "      r0 *= 1.0f / (r0.x + r0.y + r0.z + r0.w + epsv);\n"
         "      r1 *= 1.0f / (r1.x + r1.y + r1.z + r1.w + epsv);\n"
         "      r2 *= 1.0f / (r2.x + r2.y + r2.z + r2.w + epsv);\n"
         "      r3 *= 1.0f / (r3.x + r3.y + r3.z + r3.w + epsv);\n"
         "      col_inv = 1.0f / (r0 + r1 + r2 + r3 + epsv);\n"
         "      r0 *= col_inv; r1 *= col_inv; r2 *= col_inv; r3 *= col_inv;\n"
         "    }\n"
         "    *((device float4 *)(out +  8)) = r0;\n"
         "    *((device float4 *)(out + 12)) = r1;\n"
         "    *((device float4 *)(out + 16)) = r2;\n"
         "    *((device float4 *)(out + 20)) = r3;\n"
         "  }\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  /* Stage 2: HC-weighted sum + RMS sumf accumulate */\n"
         "  float sumf = 0.0f;\n"
         "  const uint n4 = 1024u;\n"
         "  for (uint i = tid; i < n4; i += ntg) {\n"
         "    device const float4 *x0 = (device const float4 *)(x + 0*args->nb_x1 + (uint64_t)row*args->nb_x2);\n"
         "    device const float4 *x1 = (device const float4 *)(x + 1*args->nb_x1 + (uint64_t)row*args->nb_x2);\n"
         "    device const float4 *x2 = (device const float4 *)(x + 2*args->nb_x1 + (uint64_t)row*args->nb_x2);\n"
         "    device const float4 *x3 = (device const float4 *)(x + 3*args->nb_x1 + (uint64_t)row*args->nb_x2);\n"
         "    const float4 v = x0[i] * pre_shmem[0] + x1[i] * pre_shmem[1]\n"
         "                   + x2[i] * pre_shmem[2] + x3[i] * pre_shmem[3];\n"
         "    row_shmem[i] = v;\n"
         "    sumf += dot(v, v);\n"
         "  }\n"
         "  sumf = simd_sum(sumf);\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  if (tiisg == 0) sum_shmem[sgitg] = sumf;\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  sumf = sum_shmem[tiisg];\n"
         "  sumf = simd_sum(sumf);\n"
         "  const float norm_scale = rsqrt(sumf / 4096.0f + args->norm_eps);\n"
         "  /* Stage 3: dst + norm_dst writeback */\n"
         "  device float4 *dst4 = (device float4 *)(dst + (uint64_t)row * args->nb1);\n"
         "  device const float4 *w4 = (device const float4 *)norm_weight;\n"
         "  device float4 *norm4 = (device float4 *)(norm_dst + (uint64_t)row * args->nb_norm1);\n"
         "  for (uint i = tid; i < n4; i += ntg) {\n"
         "    const float4 v = row_shmem[i];\n"
         "    dst4[i] = v;\n"
         "    norm4[i] = (v * norm_scale) * w4[i];\n"
         "  }\n"
         "}\n";

    g_hc_split_weighted_sum_norm4_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_hc_split_weighted_sum_norm4_mtl4", @"hc_split_weighted_sum_norm4_mtl4", 1024, NULL, 0);
    g_hc_split_weighted_sum_norm4_mtl4_init_ok = (g_hc_split_weighted_sum_norm4_mtl4_pipeline != nil) ? 1 : 0;
    return g_hc_split_weighted_sum_norm4_mtl4_init_ok;
}

int ds4_gpu_mtl4_hc_split_weighted_sum_norm4_canary(uint32_t n_rows) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_hc_split_weighted_sum_norm4_mtl4_pipeline_init()) return 0;
    if (n_rows == 0) {
        fprintf(stderr, "ds4: hc_split_weighted_sum_norm4 canary requires n_rows > 0\n");
        return 0;
    }

    /* Canary: mix=0, base=0, scale=[1,1,1], eps=0, x[d,h,r]=1.0, w[d]=1.0
     *
     * Stage 1: pre=0.5, post=1.0, comb=0.25 (same as #694)
     * Stage 2: row[d] = 4 × 1.0 × 0.5 = 2.0 across all 4096 d
     *          rms = mean(v^2) = 4.0; norm_scale = rsqrt(4.0) = 0.5
     * Stage 3: dst[d] = 2.0; norm_dst[d] = 2.0 × 0.5 × 1.0 = 1.0 */
    const uint32_t mix_hc = 24;
    const uint32_t n_embd = 4096;
    const uint64_t mix_total = (uint64_t)n_rows * mix_hc;
    const uint64_t split_total = mix_total;
    const uint64_t x_total = (uint64_t)n_embd * 4 * n_rows;
    const uint64_t dst_total = (uint64_t)n_embd * n_rows;
    const uint64_t norm_dst_total = (uint64_t)n_embd * n_rows;

    float *host_mix = (float *)calloc(mix_total, sizeof(float));
    float *host_scale = (float *)calloc(3, sizeof(float));
    float *host_base = (float *)calloc(mix_hc, sizeof(float));
    float *host_x = (float *)calloc(x_total, sizeof(float));
    float *host_w = (float *)calloc(n_embd, sizeof(float));
    float *host_split = (float *)calloc(split_total, sizeof(float));
    float *host_dst = (float *)calloc(dst_total, sizeof(float));
    float *host_norm_dst = (float *)calloc(norm_dst_total, sizeof(float));
    if (!host_mix || !host_scale || !host_base || !host_x || !host_w ||
        !host_split || !host_dst || !host_norm_dst) {
        free(host_mix); free(host_scale); free(host_base);
        free(host_x); free(host_w);
        free(host_split); free(host_dst); free(host_norm_dst);
        return 0;
    }
    host_scale[0] = host_scale[1] = host_scale[2] = 1.0f;
    for (uint64_t i = 0; i < x_total; i++) host_x[i] = 1.0f;
    for (uint32_t i = 0; i < n_embd; i++) host_w[i] = 1.0f;

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:128
                                                      options:MTLResourceStorageModeShared];
        id<MTLBuffer> mixBuf = [g_device newBufferWithBytes:host_mix length:mix_total*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> scaleBuf = [g_device newBufferWithBytes:host_scale length:3*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> baseBuf = [g_device newBufferWithBytes:host_base length:mix_hc*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> xBuf = [g_device newBufferWithBytes:host_x length:x_total*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> splitBuf = [g_device newBufferWithLength:split_total*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> dstBuf = [g_device newBufferWithLength:dst_total*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> wBuf = [g_device newBufferWithBytes:host_w length:n_embd*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> normDstBuf = [g_device newBufferWithLength:norm_dst_total*sizeof(float) options:MTLResourceStorageModeShared];

        struct {
            int64_t n_embd_;
            int32_t n_hc_, sinkhorn_iters_;
            int64_t n_rows_, mix_hc_;
            uint64_t nb_mix1_, nb_split1_;
            uint64_t nb_x0_, nb_x1_, nb_x2_;
            uint64_t nb0_, nb1_;
            uint64_t nb_norm1_;
            float eps_, norm_eps_;
        } args = {
            .n_embd_ = n_embd,
            .n_hc_ = 4, .sinkhorn_iters_ = 1,
            .n_rows_ = n_rows, .mix_hc_ = mix_hc,
            .nb_mix1_ = (uint64_t)mix_hc * sizeof(float),
            .nb_split1_ = (uint64_t)mix_hc * sizeof(float),
            .nb_x0_ = sizeof(float),
            .nb_x1_ = (uint64_t)n_embd * sizeof(float),
            .nb_x2_ = (uint64_t)n_embd * 4 * sizeof(float),
            .nb0_ = sizeof(float),
            .nb1_ = (uint64_t)n_embd * sizeof(float),
            .nb_norm1_ = (uint64_t)n_embd * sizeof(float),
            .eps_ = 0.0f, .norm_eps_ = 0.0f,
        };
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 10;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[9] = {
                (id<MTLAllocation>)argsBuf, (id<MTLAllocation>)mixBuf,
                (id<MTLAllocation>)scaleBuf, (id<MTLAllocation>)baseBuf,
                (id<MTLAllocation>)xBuf, (id<MTLAllocation>)splitBuf,
                (id<MTLAllocation>)dstBuf, (id<MTLAllocation>)wBuf,
                (id<MTLAllocation>)normDstBuf,
            };
            [residency addAllocations:allocs count:9];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(10);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:mixBuf.gpuAddress atIndex:1];
                [argTable setAddress:scaleBuf.gpuAddress atIndex:2];
                [argTable setAddress:baseBuf.gpuAddress atIndex:3];
                [argTable setAddress:xBuf.gpuAddress atIndex:4];
                [argTable setAddress:splitBuf.gpuAddress atIndex:5];
                [argTable setAddress:dstBuf.gpuAddress atIndex:6];
                [argTable setAddress:wBuf.gpuAddress atIndex:7];
                [argTable setAddress:normDstBuf.gpuAddress atIndex:8];

                /* 1024 threads/tg matches the n4=1024 float4 grid */
                NSUInteger nth = 1024;

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_hc_split_weighted_sum_norm4_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                /* tg memory: 4096 + 4 + 32 = 4132 floats */
                [enc setThreadgroupMemoryLength:4132 * sizeof(float) atIndex:0];
                [enc dispatchThreadgroups:MTLSizeMake(n_rows, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) {
                    (void)fb; dispatch_semaphore_signal(sem);
                }];
                id<MTL4CommandBuffer> bufs[1] = { cb };
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem,
                    dispatch_time(DISPATCH_TIME_NOW, 10LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_split, splitBuf.contents, split_total * sizeof(float));
                    memcpy(host_dst, dstBuf.contents, dst_total * sizeof(float));
                    memcpy(host_norm_dst, normDstBuf.contents, norm_dst_total * sizeof(float));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 10);
            }
        }
    }
    if (!rc) {
        free(host_mix); free(host_scale); free(host_base);
        free(host_x); free(host_w);
        free(host_split); free(host_dst); free(host_norm_dst);
        return 0;
    }

    /* Validate */
    double split_dev = 0.0, dst_dev = 0.0, norm_dev = 0.0;
    for (uint32_t r = 0; r < n_rows; r++) {
        const float *s = host_split + (uint64_t)r * mix_hc;
        for (int i = 0; i < 4; i++) {
            double d = fabs((double)(s[i] - 0.5));
            if (d > split_dev) split_dev = d;
        }
        for (int i = 4; i < 8; i++) {
            double d = fabs((double)(s[i] - 1.0));
            if (d > split_dev) split_dev = d;
        }
        for (int i = 8; i < 24; i++) {
            double d = fabs((double)(s[i] - 0.25));
            if (d > split_dev) split_dev = d;
        }
        for (uint32_t d = 0; d < n_embd; d++) {
            double e_dst = fabs((double)(host_dst[(uint64_t)r * n_embd + d] - 2.0));
            double e_nrm = fabs((double)(host_norm_dst[(uint64_t)r * n_embd + d] - 1.0));
            if (e_dst > dst_dev) dst_dev = e_dst;
            if (e_nrm > norm_dev) norm_dev = e_nrm;
        }
    }
    fprintf(stderr,
        "ds4: hc_split_weighted_sum_norm4 MTL4 canary n_rows=%u n_embd=4096 "
        "split[0]=%.4f (ref=0.5) split[8]=%.4f (ref=0.25) "
        "dst[0]=%.4f (ref=2.0) norm_dst[0]=%.4f (ref=1.0) "
        "split_dev=%.4e dst_dev=%.4e norm_dev=%.4e\n",
        n_rows,
        (double)host_split[0], (double)host_split[8],
        (double)host_dst[0], (double)host_norm_dst[0],
        split_dev, dst_dev, norm_dev);
    free(host_mix); free(host_scale); free(host_base);
    free(host_x); free(host_w);
    free(host_split); free(host_dst); free(host_norm_dst);
    return (split_dev < 1.0e-6 && dst_dev < 1.0e-6 && norm_dev < 1.0e-5) ? 1 : 0;
}

/* ============================================================ */
/* dsv4_hc_expand MTL4 port (silv 2026-05-27 task #698)           */
/* ============================================================ */
/* Generic-HC variant of kernel_dsv4_hc_expand. Pairs with #679
 * hc_expand4 (HC=4 specialization). One thread per (d, dst_hc, t)
 * tuple → 1 output. Inner loop runs over n_hc src_hc values.
 *
 * Used for diagnostics and any non-HC=4 deployment. The HC=4 path
 * (#679) is the production hot path; this scalar path is the
 * fallback for arbitrary n_hc. */

static id<MTLComputePipelineState> g_hc_expand_mtl4_pipeline;
static int g_hc_expand_mtl4_init_attempted;
static int g_hc_expand_mtl4_init_ok;

static int ds4_hc_expand_mtl4_pipeline_init(void) {
    if (g_hc_expand_mtl4_init_attempted) return g_hc_expand_mtl4_init_ok;
    g_hc_expand_mtl4_init_attempted = 1;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "struct hce_args {\n"
         "  int32_t n_embd;\n"
         "  int32_t n_hc;\n"
         "  int32_t n_tokens;\n"
         "  int32_t has_add;\n"
         "};\n"
         "kernel void hc_expand_mtl4(\n"
         "    device const hce_args *args [[buffer(0)]],\n"
         "    device const float    *block_out [[buffer(1)]],\n"
         "    device const float    *residual  [[buffer(2)]],\n"
         "    device const float    *post      [[buffer(3)]],\n"
         "    device const float    *comb      [[buffer(4)]],\n"
         "    device const float    *block_add [[buffer(5)]],\n"
         "    device       float    *dst       [[buffer(6)]],\n"
         "    uint gid [[thread_position_in_grid]]) {\n"
         "  const int32_t n_embd = args->n_embd;\n"
         "  const int32_t n_hc = args->n_hc;\n"
         "  const int32_t n_tokens = args->n_tokens;\n"
         "  const int64_t n_elem = (int64_t)n_embd * (int64_t)n_hc * (int64_t)n_tokens;\n"
         "  if ((int64_t)gid >= n_elem) return;\n"
         "  const int64_t d      = (int64_t)gid % n_embd;\n"
         "  const int64_t tmp    = (int64_t)gid / n_embd;\n"
         "  const int64_t dst_hc = tmp % n_hc;\n"
         "  const int64_t t      = tmp / n_hc;\n"
         "  float block_v = block_out[d + t * n_embd];\n"
         "  if (args->has_add) block_v += block_add[d + t * n_embd];\n"
         "  const float post_v = post[dst_hc + t * n_hc];\n"
         "  float acc = block_v * post_v;\n"
         "  for (int64_t src_hc = 0; src_hc < n_hc; ++src_hc) {\n"
         "    const float comb_v = comb[dst_hc + src_hc * n_hc + t * n_hc * n_hc];\n"
         "    const float res_v  = residual[d + src_hc * n_embd + t * n_hc * n_embd];\n"
         "    acc += comb_v * res_v;\n"
         "  }\n"
         "  dst[d + dst_hc * n_embd + t * n_hc * n_embd] = acc;\n"
         "}\n";

    g_hc_expand_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_hc_expand_mtl4", @"hc_expand_mtl4", 256, NULL, 0);
    g_hc_expand_mtl4_init_ok = (g_hc_expand_mtl4_pipeline != nil) ? 1 : 0;
    return g_hc_expand_mtl4_init_ok;
}

int ds4_gpu_mtl4_hc_expand_canary(uint32_t n_embd, uint32_t n_hc, uint32_t n_tokens) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_hc_expand_mtl4_pipeline_init()) return 0;
    if (n_embd == 0 || n_hc == 0 || n_tokens == 0) {
        fprintf(stderr, "ds4: hc_expand canary needs n_embd>0, n_hc>0, n_tokens>0\n");
        return 0;
    }

    /* Canary (same setup as #679 hc_expand4 but with arbitrary n_hc):
     *   block_out[d, t]            = 1.0
     *   residual[d, src_hc, t]     = (src_hc + 1) * 0.5
     *   post[dst_hc, t]            = 1.0
     *   comb[dst_hc, src_hc, t]    = (dst_hc == src_hc) ? 2.0 : 0.0
     *   has_add                    = 0
     *
     * Expected dst[d, dst_hc, t] = 1.0 + 2.0 * (dst_hc + 1) * 0.5 = dst_hc + 2 */
    const uint64_t block_n = (uint64_t)n_embd * n_tokens;
    const uint64_t res_n = (uint64_t)n_embd * n_hc * n_tokens;
    const uint64_t post_n = (uint64_t)n_hc * n_tokens;
    const uint64_t comb_n = (uint64_t)n_hc * n_hc * n_tokens;
    const uint64_t dst_n = (uint64_t)n_embd * n_hc * n_tokens;

    float *host_block = (float *)calloc(block_n, sizeof(float));
    float *host_res = (float *)calloc(res_n, sizeof(float));
    float *host_post = (float *)calloc(post_n, sizeof(float));
    float *host_comb = (float *)calloc(comb_n, sizeof(float));
    float *host_dst = (float *)calloc(dst_n, sizeof(float));
    if (!host_block || !host_res || !host_post || !host_comb || !host_dst) {
        free(host_block); free(host_res); free(host_post); free(host_comb); free(host_dst);
        return 0;
    }
    for (uint64_t i = 0; i < block_n; i++) host_block[i] = 1.0f;
    for (uint32_t t = 0; t < n_tokens; t++) {
        for (uint32_t src_hc = 0; src_hc < n_hc; src_hc++) {
            const float r = (float)(src_hc + 1) * 0.5f;
            for (uint32_t d = 0; d < n_embd; d++) {
                host_res[(uint64_t)d + src_hc * n_embd + (uint64_t)t * n_hc * n_embd] = r;
            }
        }
        for (uint32_t dst_hc = 0; dst_hc < n_hc; dst_hc++) {
            host_post[(uint64_t)dst_hc + (uint64_t)t * n_hc] = 1.0f;
        }
        for (uint32_t src_hc = 0; src_hc < n_hc; src_hc++) {
            for (uint32_t dst_hc = 0; dst_hc < n_hc; dst_hc++) {
                host_comb[(uint64_t)dst_hc + src_hc * n_hc + (uint64_t)t * n_hc * n_hc] =
                    (dst_hc == src_hc) ? 2.0f : 0.0f;
            }
        }
    }

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:16
                                                      options:MTLResourceStorageModeShared];
        id<MTLBuffer> blockBuf = [g_device newBufferWithBytes:host_block length:block_n*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> resBuf = [g_device newBufferWithBytes:host_res length:res_n*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> postBuf = [g_device newBufferWithBytes:host_post length:post_n*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> combBuf = [g_device newBufferWithBytes:host_comb length:comb_n*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> dstBuf = [g_device newBufferWithLength:dst_n*sizeof(float) options:MTLResourceStorageModeShared];

        struct { int32_t n_embd_, n_hc_, n_tokens_, has_add_; } args = {
            .n_embd_ = (int32_t)n_embd, .n_hc_ = (int32_t)n_hc,
            .n_tokens_ = (int32_t)n_tokens, .has_add_ = 0,
        };
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 8;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[7] = {
                (id<MTLAllocation>)argsBuf, (id<MTLAllocation>)blockBuf,
                (id<MTLAllocation>)resBuf, (id<MTLAllocation>)postBuf,
                (id<MTLAllocation>)combBuf, (id<MTLAllocation>)blockBuf,  /* alias */
                (id<MTLAllocation>)dstBuf,
            };
            [residency addAllocations:allocs count:7];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(8);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:blockBuf.gpuAddress atIndex:1];
                [argTable setAddress:resBuf.gpuAddress atIndex:2];
                [argTable setAddress:postBuf.gpuAddress atIndex:3];
                [argTable setAddress:combBuf.gpuAddress atIndex:4];
                [argTable setAddress:blockBuf.gpuAddress atIndex:5];  /* block_add */
                [argTable setAddress:dstBuf.gpuAddress atIndex:6];

                const uint64_t n_elem = (uint64_t)n_embd * n_hc * n_tokens;
                NSUInteger nth = MIN((NSUInteger)256, MAX((NSUInteger)1, (NSUInteger)n_elem));
                NSUInteger n_tg = ((NSUInteger)n_elem + nth - 1u) / nth;

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_hc_expand_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc dispatchThreadgroups:MTLSizeMake(n_tg, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) {
                    (void)fb; dispatch_semaphore_signal(sem);
                }];
                id<MTL4CommandBuffer> bufs[1] = { cb };
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem,
                    dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_dst, dstBuf.contents, dst_n * sizeof(float));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 8);
            }
        }
    }
    if (!rc) {
        free(host_block); free(host_res); free(host_post); free(host_comb); free(host_dst);
        return 0;
    }

    double max_abs = 0.0;
    int mismatch = 0;
    for (uint32_t t = 0; t < n_tokens; t++) {
        for (uint32_t dst_hc = 0; dst_hc < n_hc; dst_hc++) {
            const float ref = (float)(dst_hc + 2);
            for (uint32_t d = 0; d < n_embd; d++) {
                const float v = host_dst[(uint64_t)d + dst_hc * n_embd + (uint64_t)t * n_hc * n_embd];
                const double diff = fabs((double)(v - ref));
                if (diff > max_abs) max_abs = diff;
                if (diff > 1.0e-5) mismatch++;
            }
        }
    }
    fprintf(stderr,
        "ds4: hc_expand MTL4 canary n_embd=%u n_hc=%u n_tokens=%u "
        "dst[0,0,0]=%.2f (ref=2.0) dst[0,%u,0]=%.2f (ref=%.2f) "
        "mismatch=%d max_abs=%.4e\n",
        n_embd, n_hc, n_tokens,
        (double)host_dst[0],
        n_hc - 1,
        (double)host_dst[(uint64_t)(n_hc - 1) * n_embd],
        (double)(n_hc + 1),
        mismatch, max_abs);
    free(host_block); free(host_res); free(host_post); free(host_comb); free(host_dst);
    return (mismatch == 0) ? 1 : 0;
}

/* ============================================================ */
/* hadamard16_fp16_batched_wide MTL4 port (silv 2026-05-27 #699) */
/* ============================================================ */
/* MTL4 port of kernel_hadamard16_fp16_batched_wide. Processes 16
 * Hadamard-16 blocks per threadgroup (256 threads = 16 blocks × 16
 * elements). All blocks' butterfly stages run in lockstep with
 * threadgroup_barrier between stride doublings.
 *
 * Per-block early-out for tail groups via active flag.
 * Output normalized × 1/sqrt(16) = 0.25. */

static id<MTLComputePipelineState> g_hadamard16_wide_mtl4_pipeline;
static int g_hadamard16_wide_mtl4_init_attempted;
static int g_hadamard16_wide_mtl4_init_ok;

static int ds4_hadamard16_wide_mtl4_pipeline_init(void) {
    if (g_hadamard16_wide_mtl4_init_attempted) return g_hadamard16_wide_mtl4_init_ok;
    g_hadamard16_wide_mtl4_init_attempted = 1;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "constant float kHadamard16InvSqrt16 = 0.25f;\n"
         "constant uint  kBlocksPerTg = 16u;\n"
         "struct h16w_args {\n"
         "  uint32_t n_rows;\n"
         "  uint32_t blocks_per_row;\n"
         "  uint64_t row_stride_bytes;\n"
         "};\n"
         "kernel void hadamard16_wide_mtl4(\n"
         "    device const h16w_args *args [[buffer(0)]],\n"
         "    device       half      *x [[buffer(1)]],\n"
         "    threadgroup  half      *scratch [[threadgroup(0)]],\n"
         "    uint2  tgpig [[threadgroup_position_in_grid]],\n"
         "    ushort tid   [[thread_index_in_threadgroup]]) {\n"
         "  const uint row = tgpig.x;\n"
         "  const uint tg_block = tgpig.y;\n"
         "  const ushort block_in_tg = tid / 16;\n"
         "  const ushort elem = tid % 16;\n"
         "  const uint global_block = tg_block * kBlocksPerTg + (uint)block_in_tg;\n"
         "  if (row >= args->n_rows) return;\n"
         "  const bool active = (global_block < args->blocks_per_row);\n"
         "  device half *row_ptr = (device half *)((device char *)x +\n"
         "                                          (uint64_t)row * args->row_stride_bytes);\n"
         "  device half *block_ptr = row_ptr + (uint64_t)global_block * 16u;\n"
         "  threadgroup half *sub = scratch + (uint)block_in_tg * 16u;\n"
         "  if (active) sub[elem] = block_ptr[elem];\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  /* Walsh-Hadamard butterfly, 4 stages (log2(16)=4) */\n"
         "  for (uint stride = 1u; stride < 16u; stride <<= 1u) {\n"
         "    if (active && ((elem & stride) == 0u)) {\n"
         "      const ushort base = (elem & ~(2u * stride - 1u)) + (elem & (stride - 1u));\n"
         "      const float a = (float)sub[base];\n"
         "      const float b = (float)sub[base + stride];\n"
         "      sub[base]          = (half)(a + b);\n"
         "      sub[base + stride] = (half)(a - b);\n"
         "    }\n"
         "    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  }\n"
         "  if (active) block_ptr[elem] = (half)((float)sub[elem] * kHadamard16InvSqrt16);\n"
         "}\n";

    g_hadamard16_wide_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_hadamard16_wide_mtl4", @"hadamard16_wide_mtl4", 256, NULL, 0);
    g_hadamard16_wide_mtl4_init_ok = (g_hadamard16_wide_mtl4_pipeline != nil) ? 1 : 0;
    return g_hadamard16_wide_mtl4_init_ok;
}

int ds4_gpu_mtl4_hadamard16_wide_canary(uint32_t n_rows, uint32_t blocks_per_row) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_hadamard16_wide_mtl4_pipeline_init()) return 0;
    if (n_rows == 0 || blocks_per_row == 0) {
        fprintf(stderr, "ds4: hadamard16_wide canary requires n_rows>0 and blocks_per_row>0\n");
        return 0;
    }

    /* Canary: all rows × all blocks filled with 1.0 (half precision).
     * WHT of (1, 1, ..., 1) = (16, 0, 0, ..., 0) since H[0,:] sums all,
     * other rows have equal +/-1 that cancel.
     * × 1/sqrt(16) normalization = 0.25:
     *   output[0]  = 16 × 0.25 = 4.0
     *   output[1..15] = 0 */
    const uint32_t elems_per_row = blocks_per_row * 16;
    const uint64_t total = (uint64_t)n_rows * elems_per_row;
    uint16_t *host_x = (uint16_t *)calloc(total, sizeof(uint16_t));  /* half */
    if (!host_x) return 0;
    {
        _Float16 one_h = (_Float16)1.0f;
        uint16_t one_bits;
        memcpy(&one_bits, &one_h, sizeof(one_bits));
        for (uint64_t i = 0; i < total; i++) host_x[i] = one_bits;
    }

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:24
                                                      options:MTLResourceStorageModeShared];
        id<MTLBuffer> xBuf = [g_device newBufferWithBytes:host_x
                                                   length:total * sizeof(uint16_t)
                                                  options:MTLResourceStorageModeShared];

        struct { uint32_t n_rows_, blocks_per_row_; uint64_t row_stride_bytes_; } args = {
            .n_rows_ = n_rows,
            .blocks_per_row_ = blocks_per_row,
            .row_stride_bytes_ = (uint64_t)elems_per_row * sizeof(uint16_t),
        };
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 4;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[2] = {
                (id<MTLAllocation>)argsBuf,
                (id<MTLAllocation>)xBuf,
            };
            [residency addAllocations:allocs count:2];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(4);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:xBuf.gpuAddress atIndex:1];

                const uint32_t blocks_per_tg = 16;
                const uint32_t tg_y = (blocks_per_row + blocks_per_tg - 1) / blocks_per_tg;

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_hadamard16_wide_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                /* shmem: 16 blocks × 16 half = 256 half = 512 bytes */
                [enc setThreadgroupMemoryLength:512 atIndex:0];
                [enc dispatchThreadgroups:MTLSizeMake(n_rows, tg_y, 1)
                    threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) {
                    (void)fb; dispatch_semaphore_signal(sem);
                }];
                id<MTL4CommandBuffer> bufs[1] = { cb };
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem,
                    dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_x, xBuf.contents, total * sizeof(uint16_t));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 4);
            }
        }
    }
    if (!rc) { free(host_x); return 0; }

    /* Validate: per 16-block, [0]=4.0, [1..15]=0 */
    double zero_dev = 0.0, first_dev = 0.0;
    int mismatch_first = 0, mismatch_zero = 0;
    for (uint32_t r = 0; r < n_rows; r++) {
        for (uint32_t blk = 0; blk < blocks_per_row; blk++) {
            const uint64_t base = (uint64_t)r * elems_per_row + (uint64_t)blk * 16;
            _Float16 v0_h;
            memcpy(&v0_h, &host_x[base], sizeof(v0_h));
            const float v0 = (float)v0_h;
            const double d0 = fabs((double)(v0 - 4.0));
            if (d0 > first_dev) first_dev = d0;
            if (d0 > 1.0e-3) mismatch_first++;
            for (uint32_t e = 1; e < 16; e++) {
                _Float16 v_h;
                memcpy(&v_h, &host_x[base + e], sizeof(v_h));
                const float v = (float)v_h;
                const double d = fabs((double)v);
                if (d > zero_dev) zero_dev = d;
                if (d > 1.0e-3) mismatch_zero++;
            }
        }
    }
    fprintf(stderr,
        "ds4: hadamard16_wide MTL4 canary n_rows=%u blocks_per_row=%u "
        "block[0][0]=%.4f (ref=4.0) block[0][1]=%.4f (ref=0) "
        "first_dev=%.4e zero_dev=%.4e mismatch_first=%d mismatch_zero=%d\n",
        n_rows, blocks_per_row,
        (double)({ _Float16 h; memcpy(&h, &host_x[0], sizeof(h)); (float)h; }),
        (double)({ _Float16 h; memcpy(&h, &host_x[1], sizeof(h)); (float)h; }),
        first_dev, zero_dev, mismatch_first, mismatch_zero);
    free(host_x);
    return (mismatch_first == 0 && mismatch_zero == 0) ? 1 : 0;
}

/* ============================================================ */
/* argsort_merge_f32_i32_desc MTL4 port (silv 2026-05-27 #700)    */
/* ============================================================ */
/* MTL4 port of kernel_argsort_merge_f32_i32<DS4_SORT_ORDER_DESC>.
 * Merges two pre-sorted index runs produced by #692 argsort_f32_i32.
 * Used to finish top-k over router scores when ne00 exceeds one
 * threadgroup's bitonic-sort capacity — successive merge passes
 * combine adjacent runs of size `len` into runs of size `2*len`.
 *
 * NEW patterns:
 *   - Binary-search partition: find (i, j) such that i+j=k0 splits
 *     the merged stream evenly between two pre-sorted halves
 *   - Per-thread merge-front advance: each thread emits a chunk of
 *     [k0, k1) outputs by stepping (i, j) registers
 *   - Sentinel handling: one half running out short-circuits to a
 *     fast tail copy of the other half
 *
 * Pairs with #692 argsort_f32_i32_desc. */

static id<MTLComputePipelineState> g_argsort_merge_f32_i32_desc_mtl4_pipeline;
static int g_argsort_merge_f32_i32_desc_mtl4_init_attempted;
static int g_argsort_merge_f32_i32_desc_mtl4_init_ok;

static int ds4_argsort_merge_f32_i32_desc_mtl4_pipeline_init(void) {
    if (g_argsort_merge_f32_i32_desc_mtl4_init_attempted) return g_argsort_merge_f32_i32_desc_mtl4_init_ok;
    g_argsort_merge_f32_i32_desc_mtl4_init_attempted = 1;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "struct am_args {\n"
         "  int64_t  ne00; int64_t  ne01; int64_t  ne02; int64_t  ne03;\n"
         "  uint64_t nb00; uint64_t nb01; uint64_t nb02; uint64_t nb03;\n"
         "  int32_t  ne0;  int32_t  ne1;  int32_t  ne2;  int32_t  ne3;\n"
         "  int32_t  top_k; int32_t len;\n"
         "};\n"
         "kernel void argsort_merge_f32_i32_desc_mtl4(\n"
         "    device const am_args  *args [[buffer(0)]],\n"
         "    device const char     *src0 [[buffer(1)]],\n"
         "    device const int32_t  *tmp  [[buffer(2)]],\n"
         "    device       int32_t  *dst  [[buffer(3)]],\n"
         "    uint3   tgpig [[threadgroup_position_in_grid]],\n"
         "    ushort3 tpitg [[thread_position_in_threadgroup]],\n"
         "    ushort3 ntg   [[threads_per_threadgroup]]) {\n"
         "  const int im  = tgpig[0] / (int)args->ne01;\n"
         "  const int i01 = tgpig[0] % (int)args->ne01;\n"
         "  const int i02 = tgpig[1];\n"
         "  const int i03 = tgpig[2];\n"
         "  const int start = im * (2 * args->len);\n"
         "  const int len0 = min((int)args->len, max(0, args->ne0 - start));\n"
         "  const int len1 = min((int)args->len, max(0, args->ne0 - (start + args->len)));\n"
         "  const int total = len0 + len1;\n"
         "  device const int32_t *tmp0 = tmp + start\n"
         "    + i01*args->ne0\n"
         "    + i02*args->ne0*(int)args->ne01\n"
         "    + i03*args->ne0*(int)args->ne01*(int)args->ne02;\n"
         "  device const int32_t *tmp1 = tmp0 + args->len;\n"
         "  dst += start\n"
         "    + i01*args->top_k\n"
         "    + i02*args->top_k*(int)args->ne01\n"
         "    + i03*args->top_k*(int)args->ne01*(int)args->ne02;\n"
         "  device const float *src0_row = (device const float *)(src0\n"
         "    + args->nb01*i01\n"
         "    + args->nb02*i02\n"
         "    + args->nb03*i03);\n"
         "  if (total == 0) return;\n"
         "  const int chunk = (total + ntg.x - 1) / ntg.x;\n"
         "  const int k0 = tpitg.x * chunk;\n"
         "  const int k1 = min(min(k0 + chunk, total), args->top_k);\n"
         "  if (k0 >= args->top_k || k0 >= total) return;\n"
         "  /* Binary-search partition: find i such that merging tmp0[0..i)\n"
         "   * and tmp1[0..k0-i) produces the top-k0 elements. */\n"
         "  int low  = k0 > len1 ? k0 - len1 : 0;\n"
         "  int high = min(k0, len0);\n"
         "  while (low < high) {\n"
         "    const int mid = (low + high) >> 1;\n"
         "    const int32_t idx0 = tmp0[mid];\n"
         "    const int32_t idx1 = tmp1[k0 - mid - 1];\n"
         "    const float val0 = src0_row[idx0];\n"
         "    const float val1 = src0_row[idx1];\n"
         "    /* descending: take_left iff val0 >= val1 */\n"
         "    const bool take_left = (val0 >= val1);\n"
         "    if (take_left) low = mid + 1; else high = mid;\n"
         "  }\n"
         "  int i = low;\n"
         "  int j = k0 - i;\n"
         "  /* Pre-load merge-front registers */\n"
         "  int32_t idx0 = 0;\n"
         "  float   val0 = 0.0f;\n"
         "  if (i < len0) { idx0 = tmp0[i]; val0 = src0_row[idx0]; }\n"
         "  int32_t idx1 = 0;\n"
         "  float   val1 = 0.0f;\n"
         "  if (j < len1) { idx1 = tmp1[j]; val1 = src0_row[idx1]; }\n"
         "  for (int k = k0; k < k1; ++k) {\n"
         "    int32_t out_idx;\n"
         "    if (i >= len0) {\n"
         "      while (k < k1) { dst[k++] = tmp1[j++]; }\n"
         "      break;\n"
         "    } else if (j >= len1) {\n"
         "      while (k < k1) { dst[k++] = tmp0[i++]; }\n"
         "      break;\n"
         "    } else {\n"
         "      const bool take_left = (val0 >= val1);\n"
         "      if (take_left) {\n"
         "        out_idx = idx0; ++i;\n"
         "        if (i < len0) { idx0 = tmp0[i]; val0 = src0_row[idx0]; }\n"
         "      } else {\n"
         "        out_idx = idx1; ++j;\n"
         "        if (j < len1) { idx1 = tmp1[j]; val1 = src0_row[idx1]; }\n"
         "      }\n"
         "    }\n"
         "    dst[k] = out_idx;\n"
         "  }\n"
         "}\n";

    g_argsort_merge_f32_i32_desc_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_argsort_merge_f32_i32_desc_mtl4", @"argsort_merge_f32_i32_desc_mtl4", 256, NULL, 0);
    g_argsort_merge_f32_i32_desc_mtl4_init_ok = (g_argsort_merge_f32_i32_desc_mtl4_pipeline != nil) ? 1 : 0;
    return g_argsort_merge_f32_i32_desc_mtl4_init_ok;
}

int ds4_gpu_mtl4_argsort_merge_f32_i32_desc_canary(uint32_t len, uint32_t top_k) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_argsort_merge_f32_i32_desc_mtl4_pipeline_init()) return 0;
    if (len == 0 || top_k == 0) {
        fprintf(stderr, "ds4: argsort_merge canary requires len>0, top_k>0\n");
        return 0;
    }

    /* Canary: src0_row of length 2*len with values [2L-1, 2L-2, ..., 1, 0]
     * (descending values; index i has value 2L-1-i).
     * Pre-sorted halves (descending):
     *   tmp0 = [0, 1, 2, ..., L-1]            (positions of largest L values)
     *   tmp1 = [L, L+1, ..., 2L-1]            (positions of smaller L values)
     * Merged descending should yield: [0, 1, 2, ..., min(2L, top_k) - 1]. */
    const uint32_t total = 2 * len;
    float *host_src = (float *)calloc(total, sizeof(float));
    int32_t *host_tmp = (int32_t *)calloc(total, sizeof(int32_t));
    int32_t *host_dst = (int32_t *)calloc(top_k, sizeof(int32_t));
    if (!host_src || !host_tmp || !host_dst) {
        free(host_src); free(host_tmp); free(host_dst); return 0;
    }
    for (uint32_t i = 0; i < total; i++) host_src[i] = (float)(total - 1 - i);
    for (uint32_t i = 0; i < len; i++) host_tmp[i] = (int32_t)i;
    for (uint32_t i = 0; i < len; i++) host_tmp[len + i] = (int32_t)(len + i);

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:96
                                                      options:MTLResourceStorageModeShared];
        id<MTLBuffer> srcBuf = [g_device newBufferWithBytes:host_src
                                                     length:total * sizeof(float)
                                                    options:MTLResourceStorageModeShared];
        id<MTLBuffer> tmpBuf = [g_device newBufferWithBytes:host_tmp
                                                     length:total * sizeof(int32_t)
                                                    options:MTLResourceStorageModeShared];
        id<MTLBuffer> dstBuf = [g_device newBufferWithLength:top_k * sizeof(int32_t)
                                                     options:MTLResourceStorageModeShared];

        struct {
            int64_t ne00, ne01, ne02, ne03;
            uint64_t nb00, nb01, nb02, nb03;
            int32_t ne0, ne1, ne2, ne3;
            int32_t top_k_, len_;
        } args = {
            .ne00 = total, .ne01 = 1, .ne02 = 1, .ne03 = 1,
            .nb00 = sizeof(float),
            .nb01 = (uint64_t)total * sizeof(float),
            .nb02 = (uint64_t)total * sizeof(float),
            .nb03 = (uint64_t)total * sizeof(float),
            .ne0 = (int32_t)total, .ne1 = 1, .ne2 = 1, .ne3 = 1,
            .top_k_ = (int32_t)top_k,
            .len_ = (int32_t)len,
        };
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 4;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[4] = {
                (id<MTLAllocation>)argsBuf,
                (id<MTLAllocation>)srcBuf,
                (id<MTLAllocation>)tmpBuf,
                (id<MTLAllocation>)dstBuf,
            };
            [residency addAllocations:allocs count:4];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(4);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:srcBuf.gpuAddress atIndex:1];
                [argTable setAddress:tmpBuf.gpuAddress atIndex:2];
                [argTable setAddress:dstBuf.gpuAddress atIndex:3];

                /* Single merge group: im=0, threadgroup grid (1, 1, 1) */
                NSUInteger nth = MIN((NSUInteger)256, MAX((NSUInteger)1, (NSUInteger)top_k));

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_argsort_merge_f32_i32_desc_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc dispatchThreadgroups:MTLSizeMake(1, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) {
                    (void)fb; dispatch_semaphore_signal(sem);
                }];
                id<MTL4CommandBuffer> bufs[1] = { cb };
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem,
                    dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_dst, dstBuf.contents, top_k * sizeof(int32_t));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 4);
            }
        }
    }
    if (!rc) { free(host_src); free(host_tmp); free(host_dst); return 0; }

    /* Verify: dst[i] = i for i in [0, top_k) (positions of largest values, descending) */
    int mismatch = 0;
    for (uint32_t i = 0; i < top_k; i++) {
        if (host_dst[i] != (int32_t)i) mismatch++;
    }
    fprintf(stderr,
        "ds4: argsort_merge_f32_i32_desc MTL4 canary len=%u top_k=%u "
        "dst[0]=%d (ref=0) dst[1]=%d (ref=1) dst[end]=%d (ref=%u) mismatch=%d\n",
        len, top_k, host_dst[0], host_dst[1],
        host_dst[top_k - 1], top_k - 1, mismatch);
    free(host_src); free(host_tmp); free(host_dst);
    return (mismatch == 0) ? 1 : 0;
}

/* ============================================================ */
/* cpy_f32_f16 + cpy_f16_f32 MTL4 ports (silv 2026-05-27 #702/#703) */
/* ============================================================ */
/* Type-conversion variants of #693 cpy_f32_f32. Same indexing
 * pattern, one of the buffer types is half. Used at graph boundaries
 * for f32↔f16 layout conversion (KV/cache packing, FlashAttention
 * staging input from f32-residual graph nodes).
 *
 * Pure non-MMA ports — no simdgroup matrix API needed. */

static id<MTLComputePipelineState> g_cpy_f32_f16_mtl4_pipeline;
static int g_cpy_f32_f16_mtl4_init_attempted;
static int g_cpy_f32_f16_mtl4_init_ok;

static int ds4_cpy_f32_f16_mtl4_pipeline_init(void) {
    if (g_cpy_f32_f16_mtl4_init_attempted) return g_cpy_f32_f16_mtl4_init_ok;
    g_cpy_f32_f16_mtl4_init_attempted = 1;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "struct cpy_args {\n"
         "  int64_t nk0;\n"
         "  int64_t ne00; int64_t ne01; int64_t ne02; int64_t ne03;\n"
         "  uint64_t nb00; uint64_t nb01; uint64_t nb02; uint64_t nb03;\n"
         "  int64_t ne0; int64_t ne1; int64_t ne2; int64_t ne3;\n"
         "  uint64_t nb0; uint64_t nb1; uint64_t nb2; uint64_t nb3;\n"
         "};\n"
         "kernel void cpy_f32_f16_mtl4(\n"
         "    device const cpy_args *args [[buffer(0)]],\n"
         "    device const char     *src0 [[buffer(1)]],\n"
         "    device       char     *dst  [[buffer(2)]],\n"
         "    uint3   tgpig [[threadgroup_position_in_grid]],\n"
         "    ushort  tiitg [[thread_index_in_threadgroup]],\n"
         "    ushort3 ntg   [[threads_per_threadgroup]]) {\n"
         "  const int i03 = tgpig[2];\n"
         "  const int i02 = tgpig[1];\n"
         "  const int i01 = ntg[1] == 1 ? tgpig[0] % args->ne01\n"
         "                              : tgpig[0] * ntg[1] + tiitg / ntg[0];\n"
         "  const int iw0 = ntg[1] == 1 ? tgpig[0] / args->ne01 : 0;\n"
         "  const int64_t n = i03*args->ne02*args->ne01*args->ne00\n"
         "                  + i02*args->ne01*args->ne00\n"
         "                  + i01*args->ne00;\n"
         "  const int64_t i3 = n / (args->ne2*args->ne1*args->ne0);\n"
         "  const int64_t i2 = (n - i3*args->ne2*args->ne1*args->ne0) / (args->ne1*args->ne0);\n"
         "  const int64_t i1 = (n - i3*args->ne2*args->ne1*args->ne0\n"
         "                        - i2*args->ne1*args->ne0) / args->ne0;\n"
         "  const int64_t i0 = (n - i3*args->ne2*args->ne1*args->ne0\n"
         "                        - i2*args->ne1*args->ne0\n"
         "                        - i1*args->ne0);\n"
         "  device half *dst_data = (device half *)\n"
         "    (dst + i3*args->nb3 + i2*args->nb2 + i1*args->nb1 + i0*args->nb0);\n"
         "  const int64_t i00_base = iw0*ntg[0] + tiitg % ntg[0];\n"
         "  if (i00_base < args->ne00) {\n"
         "    device const float *src = (device const float *)\n"
         "      (src0 + i03*args->nb03 + i02*args->nb02 + i01*args->nb01 + i00_base*args->nb00);\n"
         "    dst_data[i00_base] = (half)src[0];\n"
         "  }\n"
         "}\n";

    g_cpy_f32_f16_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_cpy_f32_f16_mtl4", @"cpy_f32_f16_mtl4", 256, NULL, 0);
    g_cpy_f32_f16_mtl4_init_ok = (g_cpy_f32_f16_mtl4_pipeline != nil) ? 1 : 0;
    return g_cpy_f32_f16_mtl4_init_ok;
}

int ds4_gpu_mtl4_cpy_f32_f16_canary(uint32_t n_rows, uint32_t row_width) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_cpy_f32_f16_mtl4_pipeline_init()) return 0;
    if (n_rows == 0 || row_width == 0) return 0;

    const uint64_t total = (uint64_t)n_rows * row_width;
    float *host_src = (float *)calloc(total, sizeof(float));
    uint16_t *host_dst = (uint16_t *)calloc(total, sizeof(uint16_t));
    if (!host_src || !host_dst) { free(host_src); free(host_dst); return 0; }
    for (uint32_t r = 0; r < n_rows; r++) {
        for (uint32_t c = 0; c < row_width; c++) {
            host_src[(uint64_t)r * row_width + c] = (float)((int)r * 100 + (int)c);
        }
    }

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:144 options:MTLResourceStorageModeShared];
        id<MTLBuffer> srcBuf = [g_device newBufferWithBytes:host_src length:total*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> dstBuf = [g_device newBufferWithLength:total*sizeof(uint16_t) options:MTLResourceStorageModeShared];

        struct {
            int64_t nk0;
            int64_t ne00, ne01, ne02, ne03;
            uint64_t nb00, nb01, nb02, nb03;
            int64_t ne0, ne1, ne2, ne3;
            uint64_t nb0, nb1, nb2, nb3;
        } args = {
            .nk0 = 1,
            .ne00 = row_width, .ne01 = n_rows, .ne02 = 1, .ne03 = 1,
            .nb00 = sizeof(float),
            .nb01 = (uint64_t)row_width * sizeof(float),
            .nb02 = (uint64_t)n_rows * row_width * sizeof(float),
            .nb03 = (uint64_t)n_rows * row_width * sizeof(float),
            .ne0 = row_width, .ne1 = n_rows, .ne2 = 1, .ne3 = 1,
            .nb0 = sizeof(uint16_t),
            .nb1 = (uint64_t)row_width * sizeof(uint16_t),
            .nb2 = (uint64_t)n_rows * row_width * sizeof(uint16_t),
            .nb3 = (uint64_t)n_rows * row_width * sizeof(uint16_t),
        };
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 4;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[3] = {
                (id<MTLAllocation>)argsBuf,
                (id<MTLAllocation>)srcBuf,
                (id<MTLAllocation>)dstBuf,
            };
            [residency addAllocations:allocs count:3];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(4);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:srcBuf.gpuAddress atIndex:1];
                [argTable setAddress:dstBuf.gpuAddress atIndex:2];

                NSUInteger nth = MIN((NSUInteger)256, MAX((NSUInteger)1, (NSUInteger)row_width));
                NSUInteger W = ((NSUInteger)row_width + nth - 1u) / nth;
                NSUInteger gx = (NSUInteger)n_rows * W;

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_cpy_f32_f16_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc dispatchThreadgroups:MTLSizeMake(gx, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) {
                    (void)fb; dispatch_semaphore_signal(sem);
                }];
                id<MTL4CommandBuffer> bufs[1] = { cb };
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem,
                    dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_dst, dstBuf.contents, total * sizeof(uint16_t));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 4);
            }
        }
    }
    if (!rc) { free(host_src); free(host_dst); return 0; }

    /* Validate against expected FP16 round of source (bit-identical equivalence) */
    double max_abs = 0.0;
    int mismatch = 0;
    for (uint64_t i = 0; i < total; i++) {
        _Float16 h_expected = (_Float16)host_src[i];
        uint16_t exp_bits;
        memcpy(&exp_bits, &h_expected, sizeof(exp_bits));
        if (host_dst[i] != exp_bits) mismatch++;
        _Float16 h_got;
        memcpy(&h_got, &host_dst[i], sizeof(h_got));
        const double d = fabs((double)((float)h_got - host_src[i]));
        if (d > max_abs) max_abs = d;
    }
    _Float16 hd0, hde;
    memcpy(&hd0, &host_dst[0], sizeof(hd0));
    memcpy(&hde, &host_dst[total - 1], sizeof(hde));
    fprintf(stderr,
        "ds4: cpy_f32_f16 MTL4 canary n_rows=%u row_width=%u "
        "dst[0]_as_f32=%.1f (ref=0) dst[end]_as_f32=%.1f mismatch=%d max_abs=%.4e\n",
        n_rows, row_width,
        (double)(float)hd0, (double)(float)hde,
        mismatch, max_abs);
    free(host_src); free(host_dst);
    return (mismatch == 0) ? 1 : 0;
}

static id<MTLComputePipelineState> g_cpy_f16_f32_mtl4_pipeline;
static int g_cpy_f16_f32_mtl4_init_attempted;
static int g_cpy_f16_f32_mtl4_init_ok;

static int ds4_cpy_f16_f32_mtl4_pipeline_init(void) {
    if (g_cpy_f16_f32_mtl4_init_attempted) return g_cpy_f16_f32_mtl4_init_ok;
    g_cpy_f16_f32_mtl4_init_attempted = 1;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "struct cpy_args {\n"
         "  int64_t nk0;\n"
         "  int64_t ne00; int64_t ne01; int64_t ne02; int64_t ne03;\n"
         "  uint64_t nb00; uint64_t nb01; uint64_t nb02; uint64_t nb03;\n"
         "  int64_t ne0; int64_t ne1; int64_t ne2; int64_t ne3;\n"
         "  uint64_t nb0; uint64_t nb1; uint64_t nb2; uint64_t nb3;\n"
         "};\n"
         "kernel void cpy_f16_f32_mtl4(\n"
         "    device const cpy_args *args [[buffer(0)]],\n"
         "    device const char     *src0 [[buffer(1)]],\n"
         "    device       char     *dst  [[buffer(2)]],\n"
         "    uint3   tgpig [[threadgroup_position_in_grid]],\n"
         "    ushort  tiitg [[thread_index_in_threadgroup]],\n"
         "    ushort3 ntg   [[threads_per_threadgroup]]) {\n"
         "  const int i03 = tgpig[2];\n"
         "  const int i02 = tgpig[1];\n"
         "  const int i01 = ntg[1] == 1 ? tgpig[0] % args->ne01\n"
         "                              : tgpig[0] * ntg[1] + tiitg / ntg[0];\n"
         "  const int iw0 = ntg[1] == 1 ? tgpig[0] / args->ne01 : 0;\n"
         "  const int64_t n = i03*args->ne02*args->ne01*args->ne00\n"
         "                  + i02*args->ne01*args->ne00\n"
         "                  + i01*args->ne00;\n"
         "  const int64_t i3 = n / (args->ne2*args->ne1*args->ne0);\n"
         "  const int64_t i2 = (n - i3*args->ne2*args->ne1*args->ne0) / (args->ne1*args->ne0);\n"
         "  const int64_t i1 = (n - i3*args->ne2*args->ne1*args->ne0\n"
         "                        - i2*args->ne1*args->ne0) / args->ne0;\n"
         "  const int64_t i0 = (n - i3*args->ne2*args->ne1*args->ne0\n"
         "                        - i2*args->ne1*args->ne0\n"
         "                        - i1*args->ne0);\n"
         "  device float *dst_data = (device float *)\n"
         "    (dst + i3*args->nb3 + i2*args->nb2 + i1*args->nb1 + i0*args->nb0);\n"
         "  const int64_t i00_base = iw0*ntg[0] + tiitg % ntg[0];\n"
         "  if (i00_base < args->ne00) {\n"
         "    device const half *src = (device const half *)\n"
         "      (src0 + i03*args->nb03 + i02*args->nb02 + i01*args->nb01 + i00_base*args->nb00);\n"
         "    dst_data[i00_base] = (float)src[0];\n"
         "  }\n"
         "}\n";

    g_cpy_f16_f32_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_cpy_f16_f32_mtl4", @"cpy_f16_f32_mtl4", 256, NULL, 0);
    g_cpy_f16_f32_mtl4_init_ok = (g_cpy_f16_f32_mtl4_pipeline != nil) ? 1 : 0;
    return g_cpy_f16_f32_mtl4_init_ok;
}

int ds4_gpu_mtl4_cpy_f16_f32_canary(uint32_t n_rows, uint32_t row_width) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_cpy_f16_f32_mtl4_pipeline_init()) return 0;
    if (n_rows == 0 || row_width == 0) return 0;

    const uint64_t total = (uint64_t)n_rows * row_width;
    uint16_t *host_src = (uint16_t *)calloc(total, sizeof(uint16_t));
    float *host_dst = (float *)calloc(total, sizeof(float));
    if (!host_src || !host_dst) { free(host_src); free(host_dst); return 0; }
    for (uint32_t r = 0; r < n_rows; r++) {
        for (uint32_t c = 0; c < row_width; c++) {
            _Float16 h = (_Float16)((int)r * 100 + (int)c);
            memcpy(&host_src[(uint64_t)r * row_width + c], &h, sizeof(h));
        }
    }

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:144 options:MTLResourceStorageModeShared];
        id<MTLBuffer> srcBuf = [g_device newBufferWithBytes:host_src length:total*sizeof(uint16_t) options:MTLResourceStorageModeShared];
        id<MTLBuffer> dstBuf = [g_device newBufferWithLength:total*sizeof(float) options:MTLResourceStorageModeShared];

        struct {
            int64_t nk0;
            int64_t ne00, ne01, ne02, ne03;
            uint64_t nb00, nb01, nb02, nb03;
            int64_t ne0, ne1, ne2, ne3;
            uint64_t nb0, nb1, nb2, nb3;
        } args = {
            .nk0 = 1,
            .ne00 = row_width, .ne01 = n_rows, .ne02 = 1, .ne03 = 1,
            .nb00 = sizeof(uint16_t),
            .nb01 = (uint64_t)row_width * sizeof(uint16_t),
            .nb02 = (uint64_t)n_rows * row_width * sizeof(uint16_t),
            .nb03 = (uint64_t)n_rows * row_width * sizeof(uint16_t),
            .ne0 = row_width, .ne1 = n_rows, .ne2 = 1, .ne3 = 1,
            .nb0 = sizeof(float),
            .nb1 = (uint64_t)row_width * sizeof(float),
            .nb2 = (uint64_t)n_rows * row_width * sizeof(float),
            .nb3 = (uint64_t)n_rows * row_width * sizeof(float),
        };
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 4;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[3] = {
                (id<MTLAllocation>)argsBuf,
                (id<MTLAllocation>)srcBuf,
                (id<MTLAllocation>)dstBuf,
            };
            [residency addAllocations:allocs count:3];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(4);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:srcBuf.gpuAddress atIndex:1];
                [argTable setAddress:dstBuf.gpuAddress atIndex:2];

                NSUInteger nth = MIN((NSUInteger)256, MAX((NSUInteger)1, (NSUInteger)row_width));
                NSUInteger W = ((NSUInteger)row_width + nth - 1u) / nth;
                NSUInteger gx = (NSUInteger)n_rows * W;

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_cpy_f16_f32_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc dispatchThreadgroups:MTLSizeMake(gx, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) {
                    (void)fb; dispatch_semaphore_signal(sem);
                }];
                id<MTL4CommandBuffer> bufs[1] = { cb };
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem,
                    dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_dst, dstBuf.contents, total * sizeof(float));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 4);
            }
        }
    }
    if (!rc) { free(host_src); free(host_dst); return 0; }

    double max_abs = 0.0;
    int mismatch = 0;
    for (uint64_t i = 0; i < total; i++) {
        _Float16 h;
        memcpy(&h, &host_src[i], sizeof(h));
        const float ref = (float)h;
        const double d = fabs((double)(host_dst[i] - ref));
        if (d > max_abs) max_abs = d;
        if (d > 1.0e-6) mismatch++;
    }
    fprintf(stderr,
        "ds4: cpy_f16_f32 MTL4 canary n_rows=%u row_width=%u "
        "dst[0]=%.1f (ref=0) dst[end]=%.1f mismatch=%d max_abs=%.4e\n",
        n_rows, row_width,
        (double)host_dst[0], (double)host_dst[total - 1],
        mismatch, max_abs);
    free(host_src); free(host_dst);
    return (mismatch == 0) ? 1 : 0;
}

/* ============================================================ */
/* sum_rows_f32_f32 MTL4 port (silv 2026-05-27 #704)            */
/* ============================================================ */
/* Per-row sum reduction used at compressor-pooling graph boundary.
 * Non-MMA — uses simd_sum + threadgroup shared memory for
 * inter-simdgroup combine. Hardcoded SUM op (DS4 only exports the
 * sum variant; mean was a sister kernel never emitted via host_name). */

static id<MTLComputePipelineState> g_sum_rows_f32_f32_mtl4_pipeline;
static int g_sum_rows_f32_f32_mtl4_init_attempted;
static int g_sum_rows_f32_f32_mtl4_init_ok;

static int ds4_sum_rows_f32_f32_mtl4_pipeline_init(void) {
    if (g_sum_rows_f32_f32_mtl4_init_attempted) return g_sum_rows_f32_f32_mtl4_init_ok;
    g_sum_rows_f32_f32_mtl4_init_attempted = 1;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "struct sum_args {\n"
         "  int64_t ne00; int64_t ne01; int64_t ne02; int64_t ne03;\n"
         "  uint64_t nb00; uint64_t nb01; uint64_t nb02; uint64_t nb03;\n"
         "  int64_t ne0; int64_t ne1; int64_t ne2; int64_t ne3;\n"
         "  uint64_t nb0; uint64_t nb1; uint64_t nb2; uint64_t nb3;\n"
         "};\n"
         "kernel void sum_rows_f32_f32_mtl4(\n"
         "    device const sum_args *args [[buffer(0)]],\n"
         "    device const char     *src0 [[buffer(1)]],\n"
         "    device       char     *dst  [[buffer(2)]],\n"
         "    threadgroup  float    *shmem [[threadgroup(0)]],\n"
         "    uint3   tgpig [[threadgroup_position_in_grid]],\n"
         "    ushort3 tpitg [[thread_position_in_threadgroup]],\n"
         "    ushort  sgitg [[simdgroup_index_in_threadgroup]],\n"
         "    ushort  tiisg [[thread_index_in_simdgroup]],\n"
         "    ushort3 ntg   [[threads_per_threadgroup]]) {\n"
         "  const int i3 = tgpig.z;\n"
         "  const int i2 = tgpig.y;\n"
         "  const int i1 = tgpig.x;\n"
         "  if (sgitg == 0) shmem[tiisg] = 0.0f;\n"
         "  device const float *src_row = (device const float *)\n"
         "    (src0 + i1*args->nb01 + i2*args->nb02 + i3*args->nb03);\n"
         "  device float *dst_row = (device float *)\n"
         "    (dst + i1*args->nb1 + i2*args->nb2 + i3*args->nb3);\n"
         "  float sumf = 0.0f;\n"
         "  for (int64_t i0 = tpitg.x; i0 < args->ne00; i0 += ntg.x) {\n"
         "    sumf += src_row[i0];\n"
         "  }\n"
         "  sumf = simd_sum(sumf);\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  if (tiisg == 0) shmem[sgitg] = sumf;\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  sumf = shmem[tiisg];\n"
         "  sumf = simd_sum(sumf);\n"
         "  if (tpitg.x == 0) dst_row[0] = sumf;\n"
         "}\n";

    g_sum_rows_f32_f32_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_sum_rows_f32_f32_mtl4", @"sum_rows_f32_f32_mtl4", 1024, NULL, 0);
    g_sum_rows_f32_f32_mtl4_init_ok = (g_sum_rows_f32_f32_mtl4_pipeline != nil) ? 1 : 0;
    return g_sum_rows_f32_f32_mtl4_init_ok;
}

int ds4_gpu_mtl4_sum_rows_f32_f32_canary(uint32_t n_rows, uint32_t row_width) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_sum_rows_f32_f32_mtl4_pipeline_init()) return 0;
    if (n_rows == 0 || row_width == 0) return 0;

    const uint64_t total = (uint64_t)n_rows * row_width;
    float *host_src = (float *)calloc(total, sizeof(float));
    float *host_dst = (float *)calloc(n_rows, sizeof(float));
    float *expected = (float *)calloc(n_rows, sizeof(float));
    if (!host_src || !host_dst || !expected) {
        free(host_src); free(host_dst); free(expected); return 0;
    }
    for (uint32_t r = 0; r < n_rows; r++) {
        double s = 0.0;
        for (uint32_t c = 0; c < row_width; c++) {
            /* values 0.001..row_width*0.001 + 0.5 per row for variety */
            float v = (float)((int)c) * 0.001f + 0.5f * (float)((int)r % 7);
            host_src[(uint64_t)r * row_width + c] = v;
            s += v;
        }
        expected[r] = (float)s;
    }

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:144 options:MTLResourceStorageModeShared];
        id<MTLBuffer> srcBuf = [g_device newBufferWithBytes:host_src length:total*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> dstBuf = [g_device newBufferWithLength:n_rows*sizeof(float) options:MTLResourceStorageModeShared];

        struct {
            int64_t ne00, ne01, ne02, ne03;
            uint64_t nb00, nb01, nb02, nb03;
            int64_t ne0, ne1, ne2, ne3;
            uint64_t nb0, nb1, nb2, nb3;
        } args = {
            .ne00 = row_width, .ne01 = n_rows, .ne02 = 1, .ne03 = 1,
            .nb00 = sizeof(float),
            .nb01 = (uint64_t)row_width * sizeof(float),
            .nb02 = (uint64_t)n_rows * row_width * sizeof(float),
            .nb03 = (uint64_t)n_rows * row_width * sizeof(float),
            .ne0 = 1, .ne1 = n_rows, .ne2 = 1, .ne3 = 1,
            .nb0 = sizeof(float),
            .nb1 = sizeof(float),
            .nb2 = (uint64_t)n_rows * sizeof(float),
            .nb3 = (uint64_t)n_rows * sizeof(float),
        };
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 4;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[3] = {
                (id<MTLAllocation>)argsBuf,
                (id<MTLAllocation>)srcBuf,
                (id<MTLAllocation>)dstBuf,
            };
            [residency addAllocations:allocs count:3];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(4);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:srcBuf.gpuAddress atIndex:1];
                [argTable setAddress:dstBuf.gpuAddress atIndex:2];

                /* 1024 threads = 32 simdgroups × 32 lanes; shmem holds 32 floats */
                NSUInteger nth = MIN((NSUInteger)1024, MAX((NSUInteger)32, (NSUInteger)row_width));
                /* Round up to simdgroup multiple */
                nth = ((nth + 31) / 32) * 32;
                if (nth > 1024) nth = 1024;

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_sum_rows_f32_f32_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc setThreadgroupMemoryLength:32*sizeof(float) atIndex:0];
                [enc dispatchThreadgroups:MTLSizeMake(n_rows, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) {
                    (void)fb; dispatch_semaphore_signal(sem);
                }];
                id<MTL4CommandBuffer> bufs[1] = { cb };
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem,
                    dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_dst, dstBuf.contents, n_rows * sizeof(float));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 4);
            }
        }
    }
    if (!rc) { free(host_src); free(host_dst); free(expected); return 0; }

    double max_rel = 0.0;
    int mismatch = 0;
    for (uint32_t r = 0; r < n_rows; r++) {
        const double diff = fabs((double)(host_dst[r] - expected[r]));
        const double rel = diff / (fabs(expected[r]) + 1e-9);
        if (rel > max_rel) max_rel = rel;
        if (rel > 1e-4) mismatch++;
    }
    fprintf(stderr,
        "ds4: sum_rows_f32_f32 MTL4 canary n_rows=%u row_width=%u "
        "dst[0]=%.6f (ref=%.6f) dst[end]=%.6f (ref=%.6f) mismatch=%d max_rel=%.4e\n",
        n_rows, row_width,
        (double)host_dst[0], (double)expected[0],
        (double)host_dst[n_rows - 1], (double)expected[n_rows - 1],
        mismatch, max_rel);
    free(host_src); free(host_dst); free(expected);
    return (mismatch == 0) ? 1 : 0;
}

/* ============================================================ */
/* set_rows_f32_i32 MTL4 port (silv 2026-05-27 #705)            */
/* ============================================================ */
/* KV-cache scatter: src1[i] is the destination row index; src0[i]
 * is the source row. dst[src1[i]] = src0[i]. Per-token scatter
 * during KV cache writes. Non-MMA, integer-indexed gather/scatter. */

static id<MTLComputePipelineState> g_set_rows_f32_i32_mtl4_pipeline;
static int g_set_rows_f32_i32_mtl4_init_attempted;
static int g_set_rows_f32_i32_mtl4_init_ok;

static int ds4_set_rows_f32_i32_mtl4_pipeline_init(void) {
    if (g_set_rows_f32_i32_mtl4_init_attempted) return g_set_rows_f32_i32_mtl4_init_ok;
    g_set_rows_f32_i32_mtl4_init_attempted = 1;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "struct set_args {\n"
         "  int32_t nk0;\n"
         "  int32_t ne01;\n"
         "  uint64_t nb01; uint64_t nb02; uint64_t nb03;\n"
         "  int32_t ne11; int32_t ne12;\n"
         "  uint64_t nb10; uint64_t nb11; uint64_t nb12;\n"
         "  uint64_t nb1; uint64_t nb2; uint64_t nb3;\n"
         "};\n"
         "kernel void set_rows_f32_i32_mtl4(\n"
         "    device const set_args *args [[buffer(0)]],\n"
         "    device const char     *src0 [[buffer(1)]],\n"
         "    device const char     *src1 [[buffer(2)]],\n"
         "    device       float    *dst  [[buffer(3)]],\n"
         "    uint3 tgpig [[threadgroup_position_in_grid]],\n"
         "    uint  tiitg [[thread_index_in_threadgroup]],\n"
         "    uint3 tptg  [[threads_per_threadgroup]]) {\n"
         "  const int32_t i03 = tgpig.z;\n"
         "  const int32_t i02 = tgpig.y;\n"
         "  const int32_t i12 = i03 % args->ne12;\n"
         "  const int32_t i11 = i02 % args->ne11;\n"
         "  const int32_t i01 = tgpig.x*tptg.y + tiitg/tptg.x;\n"
         "  if (i01 >= args->ne01) return;\n"
         "  const int32_t i10 = i01;\n"
         "  const int32_t i1 = ((device const int32_t *)\n"
         "    (src1 + i10*args->nb10 + i11*args->nb11 + i12*args->nb12))[0];\n"
         "  device float *dst_row = (device float *)\n"
         "    ((device char *)dst + i1*args->nb1 + i02*args->nb2 + i03*args->nb3);\n"
         "  device const float *src_row = (device const float *)\n"
         "    (src0 + i01*args->nb01 + i02*args->nb02 + i03*args->nb03);\n"
         "  for (int ind = tiitg % tptg.x; ind < args->nk0; ind += tptg.x) {\n"
         "    dst_row[ind] = src_row[ind];\n"
         "  }\n"
         "}\n";

    g_set_rows_f32_i32_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_set_rows_f32_i32_mtl4", @"set_rows_f32_i32_mtl4", 256, NULL, 0);
    g_set_rows_f32_i32_mtl4_init_ok = (g_set_rows_f32_i32_mtl4_pipeline != nil) ? 1 : 0;
    return g_set_rows_f32_i32_mtl4_init_ok;
}

int ds4_gpu_mtl4_set_rows_f32_i32_canary(uint32_t n_src_rows, uint32_t row_width) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_set_rows_f32_i32_mtl4_pipeline_init()) return 0;
    if (n_src_rows == 0 || row_width == 0) return 0;

    /* Reverse-permutation: dst row (n_src_rows-1-i) gets src row i */
    const uint64_t src_total = (uint64_t)n_src_rows * row_width;
    const uint64_t dst_total = (uint64_t)n_src_rows * row_width;
    float *host_src = (float *)calloc(src_total, sizeof(float));
    int32_t *host_idx = (int32_t *)calloc(n_src_rows, sizeof(int32_t));
    float *host_dst = (float *)calloc(dst_total, sizeof(float));
    if (!host_src || !host_idx || !host_dst) {
        free(host_src); free(host_idx); free(host_dst); return 0;
    }
    for (uint32_t r = 0; r < n_src_rows; r++) {
        for (uint32_t c = 0; c < row_width; c++) {
            host_src[(uint64_t)r * row_width + c] = (float)((int)r * 1000 + (int)c);
        }
        host_idx[r] = (int32_t)(n_src_rows - 1 - r);
    }

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:128 options:MTLResourceStorageModeShared];
        id<MTLBuffer> srcBuf = [g_device newBufferWithBytes:host_src length:src_total*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> idxBuf = [g_device newBufferWithBytes:host_idx length:n_src_rows*sizeof(int32_t) options:MTLResourceStorageModeShared];
        id<MTLBuffer> dstBuf = [g_device newBufferWithLength:dst_total*sizeof(float) options:MTLResourceStorageModeShared];
        /* Pre-fill dst with sentinel so unwritten rows fail the check */
        float *dst_init = (float *)dstBuf.contents;
        for (uint64_t i = 0; i < dst_total; i++) dst_init[i] = -999.0f;

        struct {
            int32_t nk0;
            int32_t ne01;
            uint64_t nb01, nb02, nb03;
            int32_t ne11, ne12;
            uint64_t nb10, nb11, nb12;
            uint64_t nb1, nb2, nb3;
        } args = {
            .nk0 = row_width, .ne01 = n_src_rows,
            .nb01 = (uint64_t)row_width * sizeof(float),
            .nb02 = (uint64_t)n_src_rows * row_width * sizeof(float),
            .nb03 = (uint64_t)n_src_rows * row_width * sizeof(float),
            .ne11 = 1, .ne12 = 1,
            .nb10 = sizeof(int32_t),
            .nb11 = (uint64_t)n_src_rows * sizeof(int32_t),
            .nb12 = (uint64_t)n_src_rows * sizeof(int32_t),
            .nb1 = (uint64_t)row_width * sizeof(float),
            .nb2 = (uint64_t)n_src_rows * row_width * sizeof(float),
            .nb3 = (uint64_t)n_src_rows * row_width * sizeof(float),
        };
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 6;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[4] = {
                (id<MTLAllocation>)argsBuf,
                (id<MTLAllocation>)srcBuf,
                (id<MTLAllocation>)idxBuf,
                (id<MTLAllocation>)dstBuf,
            };
            [residency addAllocations:allocs count:4];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(8);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:srcBuf.gpuAddress atIndex:1];
                [argTable setAddress:idxBuf.gpuAddress atIndex:2];
                [argTable setAddress:dstBuf.gpuAddress atIndex:3];

                /* tptg.x copies row elements, tptg.y is rows per threadgroup */
                NSUInteger tx = MIN((NSUInteger)64, MAX((NSUInteger)1, (NSUInteger)row_width));
                NSUInteger ty = MIN((NSUInteger)4, MAX((NSUInteger)1, (NSUInteger)n_src_rows));
                NSUInteger gx = ((NSUInteger)n_src_rows + ty - 1) / ty;

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_set_rows_f32_i32_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc dispatchThreadgroups:MTLSizeMake(gx, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(tx, ty, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) {
                    (void)fb; dispatch_semaphore_signal(sem);
                }];
                id<MTL4CommandBuffer> bufs[1] = { cb };
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem,
                    dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_dst, dstBuf.contents, dst_total * sizeof(float));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 8);
            }
        }
    }
    if (!rc) { free(host_src); free(host_idx); free(host_dst); return 0; }

    /* Verify dst[n_src_rows-1-r][c] = src[r][c] (reverse permutation) */
    int mismatch = 0;
    double max_abs = 0.0;
    for (uint32_t r = 0; r < n_src_rows; r++) {
        const uint32_t dst_r = n_src_rows - 1 - r;
        for (uint32_t c = 0; c < row_width; c++) {
            const float got = host_dst[(uint64_t)dst_r * row_width + c];
            const float ref = host_src[(uint64_t)r * row_width + c];
            const double d = fabs((double)(got - ref));
            if (d > max_abs) max_abs = d;
            if (got != ref) mismatch++;
        }
    }
    fprintf(stderr,
        "ds4: set_rows_f32_i32 MTL4 canary n_src_rows=%u row_width=%u "
        "dst[%u][0]=%.1f (ref=%.1f) dst[0][last]=%.1f (ref=%.1f) mismatch=%d max_abs=%.4e\n",
        n_src_rows, row_width,
        n_src_rows - 1, (double)host_dst[(uint64_t)(n_src_rows - 1) * row_width],
        (double)host_src[0],
        (double)host_dst[row_width - 1],
        (double)host_src[(uint64_t)(n_src_rows - 1) * row_width + row_width - 1],
        mismatch, max_abs);
    free(host_src); free(host_idx); free(host_dst);
    return (mismatch == 0) ? 1 : 0;
}

/* ============================================================ */
/* mul_mm_id_map0_ne20_8 MTL4 port (silv 2026-05-27 #706)        */
/* ============================================================ */
/* MoE routing-table builder: inverts the per-token routed-expert
 * list into per-expert (token, slot) pairs. Each thread owns one
 * expert (ide = tpitg). Hardcoded ne20=8 (production DS4: 8 routed
 * experts active per token). Non-MMA — pure index manipulation with
 * threadgroup memory.
 *
 * Inputs:
 *   src2: int32 array of shape [ne21, ne20] — per-token expert IDs
 * Outputs:
 *   hids: int32 array of shape [n_experts, ne21] — per-expert flat indices
 *   htpe: uint32 array of shape [n_experts]      — per-expert count */

static id<MTLComputePipelineState> g_mul_mm_id_map0_ne20_8_mtl4_pipeline;
static int g_mul_mm_id_map0_ne20_8_mtl4_init_attempted;
static int g_mul_mm_id_map0_ne20_8_mtl4_init_ok;

static int ds4_mul_mm_id_map0_ne20_8_mtl4_pipeline_init(void) {
    if (g_mul_mm_id_map0_ne20_8_mtl4_init_attempted) return g_mul_mm_id_map0_ne20_8_mtl4_init_ok;
    g_mul_mm_id_map0_ne20_8_mtl4_init_attempted = 1;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "#define NE20 8\n"
         "struct map0_args {\n"
         "  int32_t  ne21;\n"
         "  uint64_t nb21;\n"
         "};\n"
         "kernel void mul_mm_id_map0_ne20_8_mtl4(\n"
         "    device const map0_args *args [[buffer(0)]],\n"
         "    device const char      *src2 [[buffer(1)]],\n"
         "    device       char      *htpe [[buffer(2)]],\n"
         "    device       char      *hids [[buffer(3)]],\n"
         "    threadgroup  char      *shmem [[threadgroup(0)]],\n"
         "    ushort tpitg [[thread_position_in_threadgroup]],\n"
         "    ushort ntg   [[threads_per_threadgroup]]) {\n"
         "  const short ide = tpitg;\n"
         "  uint32_t n_all = 0;\n"
         "  device int32_t *ids_i32 = (device int32_t *)hids + ide*args->ne21;\n"
         "  for (int i21 = 0; i21 < args->ne21; i21 += ntg) {\n"
         "    if (i21 + tpitg < args->ne21) {\n"
         "      device const int32_t *src2_i32 = (device const int32_t *)\n"
         "        (src2 + (i21 + tpitg)*args->nb21);\n"
         "      threadgroup uint16_t *sids = (threadgroup uint16_t *)shmem + tpitg*NE20;\n"
         "      for (short i20 = 0; i20 < NE20; i20++) sids[i20] = src2_i32[i20];\n"
         "    }\n"
         "    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "    for (short t = 0; t < ntg; t++) {\n"
         "      if (i21 + t >= args->ne21) break;\n"
         "      threadgroup const uint16_t *sids = (threadgroup const uint16_t *)shmem + t*NE20;\n"
         "      short sel = 0;\n"
         "      for (short i20 = 0; i20 < NE20; i20++) sel += (sids[i20] == ide)*(i20 + 1);\n"
         "      ids_i32[n_all] = (i21 + t)*NE20 + sel - 1;\n"
         "      n_all += (sel > 0) ? 1u : 0u;\n"
         "    }\n"
         "    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  }\n"
         "  device uint32_t *tpe_u32 = (device uint32_t *)htpe;\n"
         "  tpe_u32[ide] = n_all;\n"
         "}\n";

    g_mul_mm_id_map0_ne20_8_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_mul_mm_id_map0_ne20_8_mtl4", @"mul_mm_id_map0_ne20_8_mtl4", 1024, NULL, 0);
    g_mul_mm_id_map0_ne20_8_mtl4_init_ok = (g_mul_mm_id_map0_ne20_8_mtl4_pipeline != nil) ? 1 : 0;
    return g_mul_mm_id_map0_ne20_8_mtl4_init_ok;
}

int ds4_gpu_mtl4_mul_mm_id_map0_ne20_8_canary(uint32_t n_experts, uint32_t n_tokens) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_mul_mm_id_map0_ne20_8_mtl4_pipeline_init()) return 0;
    if (n_experts == 0 || n_tokens == 0) return 0;
    if (n_experts > 1024) n_experts = 1024;
    const uint32_t NE20 = 8;

    /* Build deterministic per-token expert lists: token t picks experts
     * ((t + 0) % E, (t + 1) % E, ..., (t + 7) % E) — cyclic. Easy to invert. */
    int32_t *host_src2 = (int32_t *)calloc((uint64_t)n_tokens * NE20, sizeof(int32_t));
    int32_t *host_hids = (int32_t *)calloc((uint64_t)n_experts * n_tokens, sizeof(int32_t));
    uint32_t *host_htpe = (uint32_t *)calloc(n_experts, sizeof(uint32_t));
    if (!host_src2 || !host_hids || !host_htpe) {
        free(host_src2); free(host_hids); free(host_htpe); return 0;
    }
    for (uint32_t t = 0; t < n_tokens; t++) {
        for (uint32_t s = 0; s < NE20; s++) {
            host_src2[(uint64_t)t * NE20 + s] = (int32_t)((t + s) % n_experts);
        }
    }
    /* CPU expected: for each expert e, scan tokens; if any slot s of token t has
     * src2[t][s] == e, record (t*NE20 + s) in hids[e][n_all++] and count. */
    uint32_t *expected_count = (uint32_t *)calloc(n_experts, sizeof(uint32_t));
    int32_t *expected_hids = (int32_t *)calloc((uint64_t)n_experts * n_tokens, sizeof(int32_t));
    for (uint32_t e = 0; e < n_experts; e++) {
        uint32_t n_all = 0;
        for (uint32_t t = 0; t < n_tokens; t++) {
            int16_t sel = 0;
            for (uint32_t s = 0; s < NE20; s++) {
                if (host_src2[(uint64_t)t * NE20 + s] == (int32_t)e) sel += (int16_t)(s + 1);
            }
            if (sel > 0) {
                expected_hids[(uint64_t)e * n_tokens + n_all] = (int32_t)(t * NE20 + sel - 1);
                n_all++;
            }
        }
        expected_count[e] = n_all;
    }

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:32 options:MTLResourceStorageModeShared];
        id<MTLBuffer> src2Buf = [g_device newBufferWithBytes:host_src2 length:(uint64_t)n_tokens*NE20*sizeof(int32_t) options:MTLResourceStorageModeShared];
        id<MTLBuffer> tpeBuf = [g_device newBufferWithLength:n_experts*sizeof(uint32_t) options:MTLResourceStorageModeShared];
        id<MTLBuffer> idsBuf = [g_device newBufferWithLength:(uint64_t)n_experts*n_tokens*sizeof(int32_t) options:MTLResourceStorageModeShared];

        struct {
            int32_t ne21;
            uint64_t nb21;
        } args = {
            .ne21 = n_tokens,
            .nb21 = NE20 * sizeof(int32_t),
        };
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 6;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[4] = {
                (id<MTLAllocation>)argsBuf,
                (id<MTLAllocation>)src2Buf,
                (id<MTLAllocation>)tpeBuf,
                (id<MTLAllocation>)idsBuf,
            };
            [residency addAllocations:allocs count:4];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(8);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:src2Buf.gpuAddress atIndex:1];
                [argTable setAddress:tpeBuf.gpuAddress atIndex:2];
                [argTable setAddress:idsBuf.gpuAddress atIndex:3];

                /* Threads = n_experts (one per expert); shmem holds ntg×NE20 uint16 = 2×ntg×NE20 bytes */
                NSUInteger nth = n_experts;
                NSUInteger shmem_bytes = nth * NE20 * sizeof(uint16_t);

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_mul_mm_id_map0_ne20_8_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc setThreadgroupMemoryLength:shmem_bytes atIndex:0];
                [enc dispatchThreadgroups:MTLSizeMake(1, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) {
                    (void)fb; dispatch_semaphore_signal(sem);
                }];
                id<MTL4CommandBuffer> bufs[1] = { cb };
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem,
                    dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_htpe, tpeBuf.contents, n_experts * sizeof(uint32_t));
                    memcpy(host_hids, idsBuf.contents, (uint64_t)n_experts * n_tokens * sizeof(int32_t));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 8);
            }
        }
    }
    if (!rc) {
        free(host_src2); free(host_hids); free(host_htpe);
        free(expected_count); free(expected_hids); return 0;
    }

    int count_mismatch = 0;
    int hids_mismatch = 0;
    for (uint32_t e = 0; e < n_experts; e++) {
        if (host_htpe[e] != expected_count[e]) count_mismatch++;
        for (uint32_t k = 0; k < expected_count[e]; k++) {
            if (host_hids[(uint64_t)e * n_tokens + k] != expected_hids[(uint64_t)e * n_tokens + k]) hids_mismatch++;
        }
    }
    /* Compute expected aggregate sanity: sum of all htpe = n_tokens * NE20 */
    uint64_t total_routed = 0;
    for (uint32_t e = 0; e < n_experts; e++) total_routed += host_htpe[e];
    fprintf(stderr,
        "ds4: mul_mm_id_map0_ne20_8 MTL4 canary n_experts=%u n_tokens=%u "
        "htpe[0]=%u (ref=%u) total_routed=%llu (ref=%u) count_mismatch=%d hids_mismatch=%d\n",
        n_experts, n_tokens,
        host_htpe[0], expected_count[0],
        (unsigned long long)total_routed, n_tokens * NE20,
        count_mismatch, hids_mismatch);
    free(host_src2); free(host_hids); free(host_htpe);
    free(expected_count); free(expected_hids);
    return (count_mismatch == 0 && hids_mismatch == 0) ? 1 : 0;
}

/* ============================================================ */
/* repeat_f32 MTL4 port (silv 2026-05-27 #707)                  */
/* ============================================================ */
/* Broadcast / repeat source dims into destination dims via modulo
 * addressing. dst[i3,i2,i1,i0] = src[i3%ne03, i2%ne02, i1%ne01, i0%ne00].
 * Used for HC-channel expansion of token embeddings before layer 0. */

static id<MTLComputePipelineState> g_repeat_f32_mtl4_pipeline;
static int g_repeat_f32_mtl4_init_attempted;
static int g_repeat_f32_mtl4_init_ok;

static int ds4_repeat_f32_mtl4_pipeline_init(void) {
    if (g_repeat_f32_mtl4_init_attempted) return g_repeat_f32_mtl4_init_ok;
    g_repeat_f32_mtl4_init_attempted = 1;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "struct rep_args {\n"
         "  int32_t ne00; int32_t ne01; int32_t ne02; int32_t ne03;\n"
         "  uint64_t nb00; uint64_t nb01; uint64_t nb02; uint64_t nb03;\n"
         "  int32_t ne0; int32_t ne1; int32_t ne2; int32_t ne3;\n"
         "  uint64_t nb0; uint64_t nb1; uint64_t nb2; uint64_t nb3;\n"
         "};\n"
         "kernel void repeat_f32_mtl4(\n"
         "    device const rep_args *args [[buffer(0)]],\n"
         "    device const char     *src0 [[buffer(1)]],\n"
         "    device       char     *dst  [[buffer(2)]],\n"
         "    uint3   tgpig [[threadgroup_position_in_grid]],\n"
         "    ushort3 tpitg [[thread_position_in_threadgroup]],\n"
         "    ushort3 ntg   [[threads_per_threadgroup]]) {\n"
         "  const int i3 = tgpig.z;\n"
         "  const int i2 = tgpig.y;\n"
         "  const int i1 = tgpig.x;\n"
         "  const int i03 = i3 % args->ne03;\n"
         "  const int i02 = i2 % args->ne02;\n"
         "  const int i01 = i1 % args->ne01;\n"
         "  device const char *src0_ptr = src0 + i03*args->nb03 + i02*args->nb02 + i01*args->nb01;\n"
         "  device       char *dst_ptr  = dst  + i3*args->nb3   + i2*args->nb2   + i1*args->nb1;\n"
         "  for (int i0 = tpitg.x; i0 < args->ne0; i0 += ntg.x) {\n"
         "    const int i00 = i0 % args->ne00;\n"
         "    *((device float *)(dst_ptr + i0*args->nb0)) =\n"
         "      *((device const float *)(src0_ptr + i00*args->nb00));\n"
         "  }\n"
         "}\n";

    g_repeat_f32_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_repeat_f32_mtl4", @"repeat_f32_mtl4", 256, NULL, 0);
    g_repeat_f32_mtl4_init_ok = (g_repeat_f32_mtl4_pipeline != nil) ? 1 : 0;
    return g_repeat_f32_mtl4_init_ok;
}

int ds4_gpu_mtl4_repeat_f32_canary(uint32_t src_rows, uint32_t src_cols, uint32_t row_factor, uint32_t col_factor) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_repeat_f32_mtl4_pipeline_init()) return 0;
    if (src_rows == 0 || src_cols == 0 || row_factor == 0 || col_factor == 0) return 0;

    const uint32_t dst_rows = src_rows * row_factor;
    const uint32_t dst_cols = src_cols * col_factor;
    const uint64_t src_total = (uint64_t)src_rows * src_cols;
    const uint64_t dst_total = (uint64_t)dst_rows * dst_cols;
    float *host_src = (float *)calloc(src_total, sizeof(float));
    float *host_dst = (float *)calloc(dst_total, sizeof(float));
    if (!host_src || !host_dst) { free(host_src); free(host_dst); return 0; }
    for (uint32_t r = 0; r < src_rows; r++) {
        for (uint32_t c = 0; c < src_cols; c++) {
            host_src[(uint64_t)r * src_cols + c] = (float)((int)r * 100 + (int)c);
        }
    }

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:128 options:MTLResourceStorageModeShared];
        id<MTLBuffer> srcBuf = [g_device newBufferWithBytes:host_src length:src_total*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> dstBuf = [g_device newBufferWithLength:dst_total*sizeof(float) options:MTLResourceStorageModeShared];

        struct {
            int32_t ne00, ne01, ne02, ne03;
            uint64_t nb00, nb01, nb02, nb03;
            int32_t ne0, ne1, ne2, ne3;
            uint64_t nb0, nb1, nb2, nb3;
        } args = {
            .ne00 = src_cols, .ne01 = src_rows, .ne02 = 1, .ne03 = 1,
            .nb00 = sizeof(float),
            .nb01 = (uint64_t)src_cols * sizeof(float),
            .nb02 = (uint64_t)src_rows * src_cols * sizeof(float),
            .nb03 = (uint64_t)src_rows * src_cols * sizeof(float),
            .ne0 = dst_cols, .ne1 = dst_rows, .ne2 = 1, .ne3 = 1,
            .nb0 = sizeof(float),
            .nb1 = (uint64_t)dst_cols * sizeof(float),
            .nb2 = (uint64_t)dst_rows * dst_cols * sizeof(float),
            .nb3 = (uint64_t)dst_rows * dst_cols * sizeof(float),
        };
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 4;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[3] = {
                (id<MTLAllocation>)argsBuf,
                (id<MTLAllocation>)srcBuf,
                (id<MTLAllocation>)dstBuf,
            };
            [residency addAllocations:allocs count:3];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(4);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:srcBuf.gpuAddress atIndex:1];
                [argTable setAddress:dstBuf.gpuAddress atIndex:2];

                NSUInteger tx = MIN((NSUInteger)256, MAX((NSUInteger)1, (NSUInteger)dst_cols));

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_repeat_f32_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc dispatchThreadgroups:MTLSizeMake(dst_rows, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(tx, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) {
                    (void)fb; dispatch_semaphore_signal(sem);
                }];
                id<MTL4CommandBuffer> bufs[1] = { cb };
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem,
                    dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_dst, dstBuf.contents, dst_total * sizeof(float));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 4);
            }
        }
    }
    if (!rc) { free(host_src); free(host_dst); return 0; }

    int mismatch = 0;
    for (uint32_t r = 0; r < dst_rows; r++) {
        for (uint32_t c = 0; c < dst_cols; c++) {
            const float got = host_dst[(uint64_t)r * dst_cols + c];
            const float ref = host_src[(uint64_t)(r % src_rows) * src_cols + (c % src_cols)];
            if (got != ref) mismatch++;
        }
    }
    fprintf(stderr,
        "ds4: repeat_f32 MTL4 canary src=%ux%u dst=%ux%u (factors %ux%u) "
        "dst[0][0]=%.1f (ref=0) dst[end][end]=%.1f (ref=%.1f) mismatch=%d\n",
        src_rows, src_cols, dst_rows, dst_cols, row_factor, col_factor,
        (double)host_dst[0],
        (double)host_dst[dst_total - 1],
        (double)host_src[src_total - 1],
        mismatch);
    free(host_src); free(host_dst);
    return (mismatch == 0) ? 1 : 0;
}

/* ============================================================ */
/* swiglu_f32 MTL4 port (silv 2026-05-27 #708)                  */
/* ============================================================ */
/* SwiGLU activation for the FFN inner state: dst = SiLU(x0) * x1 * alpha
 * with optional clamp via limit > 1e-6f. Non-MMA elementwise kernel.
 * Used at the shared-expert head (the routed-expert SwiGLU is fused
 * elsewhere via moe_swiglu_weight). */

static id<MTLComputePipelineState> g_swiglu_f32_mtl4_pipeline;
static int g_swiglu_f32_mtl4_init_attempted;
static int g_swiglu_f32_mtl4_init_ok;

static int ds4_swiglu_f32_mtl4_pipeline_init(void) {
    if (g_swiglu_f32_mtl4_init_attempted) return g_swiglu_f32_mtl4_init_ok;
    g_swiglu_f32_mtl4_init_attempted = 1;

    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "struct glu_args {\n"
         "  int32_t  ne00;\n"
         "  uint64_t nb01;\n"
         "  int32_t  ne10;\n"
         "  uint64_t nb11;\n"
         "  int32_t  ne0;\n"
         "  uint64_t nb1;\n"
         "  int32_t  i00;\n"
         "  int32_t  i10;\n"
         "  float    alpha;\n"
         "  float    limit;\n"
         "};\n"
         "kernel void swiglu_f32_mtl4(\n"
         "    device const glu_args *args [[buffer(0)]],\n"
         "    device const char     *src0 [[buffer(1)]],\n"
         "    device const char     *src1 [[buffer(2)]],\n"
         "    device       char     *dst  [[buffer(3)]],\n"
         "    uint tgpig [[threadgroup_position_in_grid]],\n"
         "    uint tpitg [[thread_position_in_threadgroup]],\n"
         "    uint ntg   [[threads_per_threadgroup]]) {\n"
         "  device const float *src0_row = (device const float *)\n"
         "    ((device const char *)src0 + tgpig*args->nb01) + args->i00;\n"
         "  device const float *src1_row = (device const float *)\n"
         "    ((device const char *)src1 + tgpig*args->nb11) + args->i10;\n"
         "  device       float *dst_row  = (device float *)\n"
         "    ((device char *)dst + tgpig*args->nb1);\n"
         "  for (int i0 = tpitg; i0 < args->ne0; i0 += ntg) {\n"
         "    float x0 = src0_row[i0];\n"
         "    float x1 = src1_row[i0];\n"
         "    if (args->limit > 1.0e-6f) {\n"
         "      x0 = min(x0, args->limit);\n"
         "      x1 = clamp(x1, -args->limit, args->limit);\n"
         "    }\n"
         "    const float silu = x0 / (1.0f + exp(-x0));\n"
         "    dst_row[i0] = silu * x1 * args->alpha;\n"
         "  }\n"
         "}\n";

    g_swiglu_f32_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_swiglu_f32_mtl4", @"swiglu_f32_mtl4", 256, NULL, 0);
    g_swiglu_f32_mtl4_init_ok = (g_swiglu_f32_mtl4_pipeline != nil) ? 1 : 0;
    return g_swiglu_f32_mtl4_init_ok;
}

int ds4_gpu_mtl4_swiglu_f32_canary(uint32_t n_rows, uint32_t row_width, float alpha, float limit) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_swiglu_f32_mtl4_pipeline_init()) return 0;
    if (n_rows == 0 || row_width == 0) return 0;

    const uint64_t total = (uint64_t)n_rows * row_width;
    float *host_src0 = (float *)calloc(total, sizeof(float));
    float *host_src1 = (float *)calloc(total, sizeof(float));
    float *host_dst = (float *)calloc(total, sizeof(float));
    float *expected = (float *)calloc(total, sizeof(float));
    if (!host_src0 || !host_src1 || !host_dst || !expected) {
        free(host_src0); free(host_src1); free(host_dst); free(expected); return 0;
    }
    /* Test pattern: spans negative (SiLU saturates near 0), zero, and positive,
     * including > limit when limit > 0 to exercise the clamp path. */
    for (uint32_t r = 0; r < n_rows; r++) {
        for (uint32_t c = 0; c < row_width; c++) {
            const float x0 = -4.0f + (float)c * 0.05f + 0.01f * (float)r;
            const float x1 = (float)c * 0.001f - (float)r * 0.002f;
            const uint64_t i = (uint64_t)r * row_width + c;
            host_src0[i] = x0;
            host_src1[i] = x1;
            float x0c = x0, x1c = x1;
            if (limit > 1.0e-6f) {
                x0c = (x0c < limit) ? x0c : limit;
                x1c = (x1c < -limit) ? -limit : ((x1c > limit) ? limit : x1c);
            }
            const float silu = x0c / (1.0f + expf(-x0c));
            expected[i] = silu * x1c * alpha;
        }
    }

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:64 options:MTLResourceStorageModeShared];
        id<MTLBuffer> src0Buf = [g_device newBufferWithBytes:host_src0 length:total*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> src1Buf = [g_device newBufferWithBytes:host_src1 length:total*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> dstBuf = [g_device newBufferWithLength:total*sizeof(float) options:MTLResourceStorageModeShared];

        struct {
            int32_t ne00;
            uint64_t nb01;
            int32_t ne10;
            uint64_t nb11;
            int32_t ne0;
            uint64_t nb1;
            int32_t i00, i10;
            float alpha, limit;
        } args = {
            .ne00 = row_width,
            .nb01 = (uint64_t)row_width * sizeof(float),
            .ne10 = row_width,
            .nb11 = (uint64_t)row_width * sizeof(float),
            .ne0 = row_width,
            .nb1 = (uint64_t)row_width * sizeof(float),
            .i00 = 0, .i10 = 0,
            .alpha = alpha, .limit = limit,
        };
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 6;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[4] = {
                (id<MTLAllocation>)argsBuf,
                (id<MTLAllocation>)src0Buf,
                (id<MTLAllocation>)src1Buf,
                (id<MTLAllocation>)dstBuf,
            };
            [residency addAllocations:allocs count:4];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(8);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:src0Buf.gpuAddress atIndex:1];
                [argTable setAddress:src1Buf.gpuAddress atIndex:2];
                [argTable setAddress:dstBuf.gpuAddress atIndex:3];

                NSUInteger tx = MIN((NSUInteger)256, MAX((NSUInteger)1, (NSUInteger)row_width));

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_swiglu_f32_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc dispatchThreadgroups:MTLSizeMake(n_rows, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(tx, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) {
                    (void)fb; dispatch_semaphore_signal(sem);
                }];
                id<MTL4CommandBuffer> bufs[1] = { cb };
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem,
                    dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_dst, dstBuf.contents, total * sizeof(float));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 8);
            }
        }
    }
    if (!rc) {
        free(host_src0); free(host_src1); free(host_dst); free(expected);
        return 0;
    }

    int mismatch = 0;
    double max_rel = 0.0;
    for (uint64_t i = 0; i < total; i++) {
        const double diff = fabs((double)(host_dst[i] - expected[i]));
        const double rel = diff / (fabs((double)expected[i]) + 1e-7);
        if (rel > max_rel) max_rel = rel;
        if (rel > 1e-5) mismatch++;
    }
    fprintf(stderr,
        "ds4: swiglu_f32 MTL4 canary n_rows=%u row_width=%u alpha=%.2f limit=%.2f "
        "dst[0]=%.4f (ref=%.4f) dst[end]=%.4f (ref=%.4f) mismatch=%d max_rel=%.4e\n",
        n_rows, row_width, (double)alpha, (double)limit,
        (double)host_dst[0], (double)expected[0],
        (double)host_dst[total - 1], (double)expected[total - 1],
        mismatch, max_rel);
    free(host_src0); free(host_src1); free(host_dst); free(expected);
    return (mismatch == 0) ? 1 : 0;
}

/* ============================================================ */
/* rms_norm_mul_f32_4 MTL4 port (silv 2026-05-27 #709)          */
/* ============================================================ */
/* RMSNorm with fused weight multiply. dst = (x / sqrt(mean(x²) + eps)) * w.
 * Production attention/FFN normalization. Non-MMA. Uses simd_sum +
 * threadgroup combine. float4-vectorized.
 *
 * The original kernel_rms_norm_fuse_impl<float4, 2> is dispatched at
 * (n_rows, 1, 1) threadgroups with ntg.x = 256 threads. */

static id<MTLComputePipelineState> g_rms_norm_mul_f32_4_mtl4_pipeline;
static int g_rms_norm_mul_f32_4_mtl4_init_attempted;
static int g_rms_norm_mul_f32_4_mtl4_init_ok;

static int ds4_rms_norm_mul_f32_4_mtl4_pipeline_init(void) {
    if (g_rms_norm_mul_f32_4_mtl4_init_attempted) return g_rms_norm_mul_f32_4_mtl4_init_ok;
    g_rms_norm_mul_f32_4_mtl4_init_attempted = 1;
    if (!ds4_polar_pipeline_init()) return 0;

    /* args layout matches ds4_metal_args_norm: ne00, ne00_t, nb1, nb2, nb3, eps,
     * nef1[3], nef2[3], nef3[3], nbf1[3], nbf2[3], nbf3[3]. src0/src1_0 used
     * (src1_1 ignored for F=2). */
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "struct norm_args {\n"
         "  int32_t  ne00;\n"
         "  int32_t  ne00_t;\n"
         "  uint64_t nb1; uint64_t nb2; uint64_t nb3;\n"
         "  float    eps;\n"
         "  int32_t  nef1[3]; int32_t nef2[3]; int32_t nef3[3];\n"
         "  uint64_t nbf1[3]; uint64_t nbf2[3]; uint64_t nbf3[3];\n"
         "};\n"
         "kernel void rms_norm_mul_f32_4_mtl4(\n"
         "    device const norm_args *args [[buffer(0)]],\n"
         "    device const char      *src0 [[buffer(1)]],\n"
         "    device const char      *src1_0 [[buffer(2)]],\n"
         "    device       char      *dst  [[buffer(3)]],\n"
         "    threadgroup  float     *shmem [[threadgroup(0)]],\n"
         "    uint3   tgpig [[threadgroup_position_in_grid]],\n"
         "    ushort3 tpitg [[thread_position_in_threadgroup]],\n"
         "    ushort  sgitg [[simdgroup_index_in_threadgroup]],\n"
         "    ushort  tiisg [[thread_index_in_simdgroup]],\n"
         "    ushort3 ntg   [[threads_per_threadgroup]]) {\n"
         "  if (sgitg == 0) shmem[tiisg] = 0.0f;\n"
         "  const int i01 = tgpig.x;\n"
         "  const int i02 = tgpig.y;\n"
         "  const int i03 = tgpig.z;\n"
         "  device const float4 *x = (device const float4 *)\n"
         "    (src0 + i03*args->nbf3[0] + i02*args->nbf2[0] + i01*args->nbf1[0]);\n"
         "  device const float4 *f0 = (device const float4 *)\n"
         "    (src1_0 + (i03 % args->nef3[1])*args->nbf3[1]\n"
         "            + (i02 % args->nef2[1])*args->nbf2[1]\n"
         "            + (i01 % args->nef1[1])*args->nbf1[1]);\n"
         "  float sumf = 0.0f;\n"
         "  for (int i00 = tpitg.x; i00 < args->ne00_t; i00 += ntg.x) {\n"
         "    const float4 v = x[i00];\n"
         "    sumf += dot(v, v);\n"
         "  }\n"
         "  sumf = simd_sum(sumf);\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  if (tiisg == 0) shmem[sgitg] = sumf;\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  sumf = shmem[tiisg];\n"
         "  sumf = simd_sum(sumf);\n"
         "  const float mean = sumf / float(args->ne00);\n"
         "  const float scale = 1.0f / sqrt(mean + args->eps);\n"
         "  device float4 *y = (device float4 *)\n"
         "    (dst + i03*args->nb3 + i02*args->nb2 + i01*args->nb1);\n"
         "  for (int i00 = tpitg.x; i00 < args->ne00_t; i00 += ntg.x) {\n"
         "    y[i00] = (x[i00] * scale) * f0[i00];\n"
         "  }\n"
         "}\n";

    g_rms_norm_mul_f32_4_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_rms_norm_mul_f32_4_mtl4", @"rms_norm_mul_f32_4_mtl4", 1024, NULL, 0);
    g_rms_norm_mul_f32_4_mtl4_init_ok = (g_rms_norm_mul_f32_4_mtl4_pipeline != nil) ? 1 : 0;
    return g_rms_norm_mul_f32_4_mtl4_init_ok;
}

int ds4_gpu_mtl4_rms_norm_mul_f32_4_canary(uint32_t n_rows, uint32_t row_width, float eps) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_rms_norm_mul_f32_4_mtl4_pipeline_init()) return 0;
    if (n_rows == 0 || row_width == 0 || (row_width % 4u) != 0u) return 0;

    const uint64_t total = (uint64_t)n_rows * row_width;
    float *host_src = (float *)calloc(total, sizeof(float));
    float *host_w = (float *)calloc(row_width, sizeof(float));
    float *host_dst = (float *)calloc(total, sizeof(float));
    float *expected = (float *)calloc(total, sizeof(float));
    if (!host_src || !host_w || !host_dst || !expected) {
        free(host_src); free(host_w); free(host_dst); free(expected); return 0;
    }
    for (uint32_t r = 0; r < n_rows; r++) {
        for (uint32_t c = 0; c < row_width; c++) {
            host_src[(uint64_t)r * row_width + c] = 0.1f + (float)((int)r * 7 + (int)c % 13) * 0.01f;
        }
    }
    for (uint32_t c = 0; c < row_width; c++) {
        host_w[c] = 0.5f + (float)c * 0.001f;
    }
    /* CPU reference: rms = sqrt(mean(x²) + eps); dst = (x / rms) * w */
    for (uint32_t r = 0; r < n_rows; r++) {
        double sum_sq = 0.0;
        for (uint32_t c = 0; c < row_width; c++) {
            const float v = host_src[(uint64_t)r * row_width + c];
            sum_sq += (double)v * (double)v;
        }
        const float mean = (float)(sum_sq / (double)row_width);
        const float scale = 1.0f / sqrtf(mean + eps);
        for (uint32_t c = 0; c < row_width; c++) {
            expected[(uint64_t)r * row_width + c] =
                host_src[(uint64_t)r * row_width + c] * scale * host_w[c];
        }
    }

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:256 options:MTLResourceStorageModeShared];
        id<MTLBuffer> srcBuf = [g_device newBufferWithBytes:host_src length:total*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> wBuf = [g_device newBufferWithBytes:host_w length:row_width*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> dstBuf = [g_device newBufferWithLength:total*sizeof(float) options:MTLResourceStorageModeShared];

        struct {
            int32_t ne00;
            int32_t ne00_t;
            uint64_t nb1, nb2, nb3;
            float eps;
            int32_t nef1[3], nef2[3], nef3[3];
            uint64_t nbf1[3], nbf2[3], nbf3[3];
        } args;
        memset(&args, 0, sizeof(args));
        args.ne00 = row_width;
        args.ne00_t = row_width / 4;  /* float4 element count */
        args.nb1 = (uint64_t)row_width * sizeof(float);
        args.nb2 = (uint64_t)n_rows * row_width * sizeof(float);
        args.nb3 = (uint64_t)n_rows * row_width * sizeof(float);
        args.eps = eps;
        /* src0 (x) strides */
        args.nef1[0] = 1; args.nef2[0] = 1; args.nef3[0] = 1;
        args.nbf1[0] = (uint64_t)row_width * sizeof(float);
        args.nbf2[0] = (uint64_t)n_rows * row_width * sizeof(float);
        args.nbf3[0] = (uint64_t)n_rows * row_width * sizeof(float);
        /* src1_0 (w) strides: broadcast across rows (nef1[1] = 1; w is single row) */
        args.nef1[1] = 1; args.nef2[1] = 1; args.nef3[1] = 1;
        args.nbf1[1] = 0;  /* w broadcast on row */
        args.nbf2[1] = 0;
        args.nbf3[1] = 0;
        /* src1_1 unused for F=2 */
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 6;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[4] = {
                (id<MTLAllocation>)argsBuf,
                (id<MTLAllocation>)srcBuf,
                (id<MTLAllocation>)wBuf,
                (id<MTLAllocation>)dstBuf,
            };
            [residency addAllocations:allocs count:4];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(8);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:srcBuf.gpuAddress atIndex:1];
                [argTable setAddress:wBuf.gpuAddress atIndex:2];
                [argTable setAddress:dstBuf.gpuAddress atIndex:3];

                /* 256 threads per row (matches classic dispatch); rounded to simdgroup */
                NSUInteger nth = 256;
                if (nth > (NSUInteger)(row_width / 4)) {
                    /* row_width/4 = ne00_t. If smaller than 256 still need ≥1 simdgroup */
                    nth = ((NSUInteger)(row_width / 4) + 31) / 32 * 32;
                    if (nth == 0) nth = 32;
                }

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_rms_norm_mul_f32_4_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc setThreadgroupMemoryLength:32*sizeof(float) atIndex:0];
                [enc dispatchThreadgroups:MTLSizeMake(n_rows, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) {
                    (void)fb; dispatch_semaphore_signal(sem);
                }];
                id<MTL4CommandBuffer> bufs[1] = { cb };
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem,
                    dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_dst, dstBuf.contents, total * sizeof(float));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 8);
            }
        }
    }
    if (!rc) {
        free(host_src); free(host_w); free(host_dst); free(expected);
        return 0;
    }

    int mismatch = 0;
    double max_rel = 0.0;
    for (uint64_t i = 0; i < total; i++) {
        const double diff = fabs((double)(host_dst[i] - expected[i]));
        const double rel = diff / (fabs((double)expected[i]) + 1e-7);
        if (rel > max_rel) max_rel = rel;
        if (rel > 1e-4) mismatch++;
    }
    fprintf(stderr,
        "ds4: rms_norm_mul_f32_4 MTL4 canary n_rows=%u row_width=%u eps=%.2e "
        "dst[0]=%.5f (ref=%.5f) dst[end]=%.5f (ref=%.5f) mismatch=%d max_rel=%.4e\n",
        n_rows, row_width, (double)eps,
        (double)host_dst[0], (double)expected[0],
        (double)host_dst[total - 1], (double)expected[total - 1],
        mismatch, max_rel);
    free(host_src); free(host_w); free(host_dst); free(expected);
    return (mismatch == 0) ? 1 : 0;
}

/* ============================================================ */
/* rms_norm_f32_4 MTL4 port (silv 2026-05-27 #710)              */
/* ============================================================ */
/* F=1 variant: norm only, no weight multiply. dst = x / sqrt(mean(x²) + eps).
 * Diagnostic variant of #709 rms_norm_mul. Non-MMA. */

static id<MTLComputePipelineState> g_rms_norm_f32_4_mtl4_pipeline;
static int g_rms_norm_f32_4_mtl4_init_attempted;
static int g_rms_norm_f32_4_mtl4_init_ok;

static int ds4_rms_norm_f32_4_mtl4_pipeline_init(void) {
    if (g_rms_norm_f32_4_mtl4_init_attempted) return g_rms_norm_f32_4_mtl4_init_ok;
    g_rms_norm_f32_4_mtl4_init_attempted = 1;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "struct norm_args {\n"
         "  int32_t  ne00; int32_t ne00_t;\n"
         "  uint64_t nb1; uint64_t nb2; uint64_t nb3;\n"
         "  float    eps;\n"
         "  int32_t  nef1[3]; int32_t nef2[3]; int32_t nef3[3];\n"
         "  uint64_t nbf1[3]; uint64_t nbf2[3]; uint64_t nbf3[3];\n"
         "};\n"
         "kernel void rms_norm_f32_4_mtl4(\n"
         "    device const norm_args *args [[buffer(0)]],\n"
         "    device const char      *src0 [[buffer(1)]],\n"
         "    device       char      *dst  [[buffer(2)]],\n"
         "    threadgroup  float     *shmem [[threadgroup(0)]],\n"
         "    uint3   tgpig [[threadgroup_position_in_grid]],\n"
         "    ushort3 tpitg [[thread_position_in_threadgroup]],\n"
         "    ushort  sgitg [[simdgroup_index_in_threadgroup]],\n"
         "    ushort  tiisg [[thread_index_in_simdgroup]],\n"
         "    ushort3 ntg   [[threads_per_threadgroup]]) {\n"
         "  if (sgitg == 0) shmem[tiisg] = 0.0f;\n"
         "  const int i01 = tgpig.x;\n"
         "  const int i02 = tgpig.y;\n"
         "  const int i03 = tgpig.z;\n"
         "  device const float4 *x = (device const float4 *)\n"
         "    (src0 + i03*args->nbf3[0] + i02*args->nbf2[0] + i01*args->nbf1[0]);\n"
         "  float sumf = 0.0f;\n"
         "  for (int i00 = tpitg.x; i00 < args->ne00_t; i00 += ntg.x) {\n"
         "    const float4 v = x[i00];\n"
         "    sumf += dot(v, v);\n"
         "  }\n"
         "  sumf = simd_sum(sumf);\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  if (tiisg == 0) shmem[sgitg] = sumf;\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  sumf = shmem[tiisg];\n"
         "  sumf = simd_sum(sumf);\n"
         "  const float mean = sumf / float(args->ne00);\n"
         "  const float scale = 1.0f / sqrt(mean + args->eps);\n"
         "  device float4 *y = (device float4 *)\n"
         "    (dst + i03*args->nb3 + i02*args->nb2 + i01*args->nb1);\n"
         "  for (int i00 = tpitg.x; i00 < args->ne00_t; i00 += ntg.x) {\n"
         "    y[i00] = x[i00] * scale;\n"
         "  }\n"
         "}\n";

    g_rms_norm_f32_4_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_rms_norm_f32_4_mtl4", @"rms_norm_f32_4_mtl4", 1024, NULL, 0);
    g_rms_norm_f32_4_mtl4_init_ok = (g_rms_norm_f32_4_mtl4_pipeline != nil) ? 1 : 0;
    return g_rms_norm_f32_4_mtl4_init_ok;
}

int ds4_gpu_mtl4_rms_norm_f32_4_canary(uint32_t n_rows, uint32_t row_width, float eps) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_rms_norm_f32_4_mtl4_pipeline_init()) return 0;
    if (n_rows == 0 || row_width == 0 || (row_width % 4u) != 0u) return 0;

    const uint64_t total = (uint64_t)n_rows * row_width;
    float *host_src = (float *)calloc(total, sizeof(float));
    float *host_dst = (float *)calloc(total, sizeof(float));
    float *expected = (float *)calloc(total, sizeof(float));
    if (!host_src || !host_dst || !expected) {
        free(host_src); free(host_dst); free(expected); return 0;
    }
    for (uint32_t r = 0; r < n_rows; r++) {
        for (uint32_t c = 0; c < row_width; c++) {
            host_src[(uint64_t)r * row_width + c] = 0.1f + (float)((int)r * 7 + (int)c % 13) * 0.01f;
        }
    }
    for (uint32_t r = 0; r < n_rows; r++) {
        double sum_sq = 0.0;
        for (uint32_t c = 0; c < row_width; c++) {
            const float v = host_src[(uint64_t)r * row_width + c];
            sum_sq += (double)v * (double)v;
        }
        const float mean = (float)(sum_sq / (double)row_width);
        const float scale = 1.0f / sqrtf(mean + eps);
        for (uint32_t c = 0; c < row_width; c++) {
            expected[(uint64_t)r * row_width + c] = host_src[(uint64_t)r * row_width + c] * scale;
        }
    }

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:256 options:MTLResourceStorageModeShared];
        id<MTLBuffer> srcBuf = [g_device newBufferWithBytes:host_src length:total*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> dstBuf = [g_device newBufferWithLength:total*sizeof(float) options:MTLResourceStorageModeShared];

        struct {
            int32_t ne00, ne00_t;
            uint64_t nb1, nb2, nb3;
            float eps;
            int32_t nef1[3], nef2[3], nef3[3];
            uint64_t nbf1[3], nbf2[3], nbf3[3];
        } args;
        memset(&args, 0, sizeof(args));
        args.ne00 = row_width;
        args.ne00_t = row_width / 4;
        args.nb1 = (uint64_t)row_width * sizeof(float);
        args.nb2 = (uint64_t)n_rows * row_width * sizeof(float);
        args.nb3 = (uint64_t)n_rows * row_width * sizeof(float);
        args.eps = eps;
        args.nef1[0] = 1; args.nef2[0] = 1; args.nef3[0] = 1;
        args.nbf1[0] = (uint64_t)row_width * sizeof(float);
        args.nbf2[0] = (uint64_t)n_rows * row_width * sizeof(float);
        args.nbf3[0] = (uint64_t)n_rows * row_width * sizeof(float);
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 4;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[3] = {
                (id<MTLAllocation>)argsBuf,
                (id<MTLAllocation>)srcBuf,
                (id<MTLAllocation>)dstBuf,
            };
            [residency addAllocations:allocs count:3];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(4);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:srcBuf.gpuAddress atIndex:1];
                [argTable setAddress:dstBuf.gpuAddress atIndex:2];

                NSUInteger nth = 256;
                if (nth > (NSUInteger)(row_width / 4)) {
                    nth = ((NSUInteger)(row_width / 4) + 31) / 32 * 32;
                    if (nth == 0) nth = 32;
                }

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_rms_norm_f32_4_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc setThreadgroupMemoryLength:32*sizeof(float) atIndex:0];
                [enc dispatchThreadgroups:MTLSizeMake(n_rows, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) {
                    (void)fb; dispatch_semaphore_signal(sem);
                }];
                id<MTL4CommandBuffer> bufs[1] = { cb };
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem,
                    dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_dst, dstBuf.contents, total * sizeof(float));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 4);
            }
        }
    }
    if (!rc) { free(host_src); free(host_dst); free(expected); return 0; }

    int mismatch = 0;
    double max_rel = 0.0;
    for (uint64_t i = 0; i < total; i++) {
        const double diff = fabs((double)(host_dst[i] - expected[i]));
        const double rel = diff / (fabs((double)expected[i]) + 1e-7);
        if (rel > max_rel) max_rel = rel;
        if (rel > 1e-4) mismatch++;
    }
    fprintf(stderr,
        "ds4: rms_norm_f32_4 MTL4 canary n_rows=%u row_width=%u eps=%.2e "
        "dst[0]=%.5f (ref=%.5f) dst[end]=%.5f (ref=%.5f) mismatch=%d max_rel=%.4e\n",
        n_rows, row_width, (double)eps,
        (double)host_dst[0], (double)expected[0],
        (double)host_dst[total - 1], (double)expected[total - 1],
        mismatch, max_rel);
    free(host_src); free(host_dst); free(expected);
    return (mismatch == 0) ? 1 : 0;
}

/* ============================================================ */
/* get_rows_f16 + get_rows_i32 MTL4 ports (silv 2026-05-27 #711/#712) */
/* ============================================================ */
/* Type-variant clones of #691 get_rows_f32. f16 source loads half then
 * widens to float on store. i32 source preserves int32 end-to-end (used
 * for embedding-table lookups via integer hash IDs). */

static id<MTLComputePipelineState> g_get_rows_f16_mtl4_pipeline;
static int g_get_rows_f16_mtl4_init_attempted;
static int g_get_rows_f16_mtl4_init_ok;

static int ds4_get_rows_f16_mtl4_pipeline_init(void) {
    if (g_get_rows_f16_mtl4_init_attempted) return g_get_rows_f16_mtl4_init_ok;
    g_get_rows_f16_mtl4_init_attempted = 1;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "struct gr_args {\n"
         "  int32_t ne00t; int32_t ne00;\n"
         "  uint64_t nb01; uint64_t nb02; uint64_t nb03;\n"
         "  int32_t ne10; uint64_t nb10; uint64_t nb11; uint64_t nb12;\n"
         "  uint64_t nb1; uint64_t nb2; uint64_t nb3;\n"
         "};\n"
         "kernel void get_rows_f16_mtl4(\n"
         "    device const gr_args *args [[buffer(0)]],\n"
         "    device const char    *src0 [[buffer(1)]],\n"
         "    device const char    *src1 [[buffer(2)]],\n"
         "    device       char    *dst  [[buffer(3)]],\n"
         "    uint3   tgpig [[threadgroup_position_in_grid]],\n"
         "    ushort  tiitg [[thread_index_in_threadgroup]],\n"
         "    ushort3 ntg   [[threads_per_threadgroup]]) {\n"
         "  const int32_t iw0 = tgpig.x / args->ne10;\n"
         "  const int32_t i10 = tgpig.x % args->ne10;\n"
         "  const int32_t i11 = tgpig.y;\n"
         "  const int32_t i12 = tgpig.z;\n"
         "  const int32_t r = ((const device int32_t *)\n"
         "    (src1 + i12*args->nb12 + i11*args->nb11 + i10*args->nb10))[0];\n"
         "  const int32_t i02 = i11;\n"
         "  const int32_t i03 = i12;\n"
         "  device const half  *psrc = (device const half *)\n"
         "    (src0 + i03*args->nb03 + i02*args->nb02 + r*args->nb01);\n"
         "  device       float *pdst = (device float *)\n"
         "    (dst + i12*args->nb3 + i11*args->nb2 + i10*args->nb1);\n"
         "  const int ind = iw0*ntg.x + tiitg;\n"
         "  if (ind < args->ne00t) pdst[ind] = (float)psrc[ind];\n"
         "}\n";

    g_get_rows_f16_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_get_rows_f16_mtl4", @"get_rows_f16_mtl4", 256, NULL, 0);
    g_get_rows_f16_mtl4_init_ok = (g_get_rows_f16_mtl4_pipeline != nil) ? 1 : 0;
    return g_get_rows_f16_mtl4_init_ok;
}

int ds4_gpu_mtl4_get_rows_f16_canary(uint32_t n_table_rows, uint32_t row_width, uint32_t n_ids) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_get_rows_f16_mtl4_pipeline_init()) return 0;
    if (n_table_rows == 0 || row_width == 0 || n_ids == 0) return 0;

    const uint64_t table_n = (uint64_t)n_table_rows * row_width;
    const uint64_t dst_n = (uint64_t)n_ids * row_width;
    uint16_t *host_tab = (uint16_t *)calloc(table_n, sizeof(uint16_t));
    int32_t *host_ids = (int32_t *)calloc(n_ids, sizeof(int32_t));
    float *host_dst = (float *)calloc(dst_n, sizeof(float));
    if (!host_tab || !host_ids || !host_dst) {
        free(host_tab); free(host_ids); free(host_dst); return 0;
    }
    for (uint32_t r = 0; r < n_table_rows; r++) {
        for (uint32_t c = 0; c < row_width; c++) {
            _Float16 h = (_Float16)((int)r * 100 + (int)c);
            memcpy(&host_tab[(uint64_t)r * row_width + c], &h, sizeof(h));
        }
    }
    for (uint32_t i = 0; i < n_ids; i++) host_ids[i] = (int32_t)(n_table_rows - 1 - i);

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:96 options:MTLResourceStorageModeShared];
        id<MTLBuffer> tabBuf = [g_device newBufferWithBytes:host_tab length:table_n*sizeof(uint16_t) options:MTLResourceStorageModeShared];
        id<MTLBuffer> idsBuf = [g_device newBufferWithBytes:host_ids length:n_ids*sizeof(int32_t) options:MTLResourceStorageModeShared];
        id<MTLBuffer> dstBuf = [g_device newBufferWithLength:dst_n*sizeof(float) options:MTLResourceStorageModeShared];

        struct {
            int32_t ne00t, ne00;
            uint64_t nb01, nb02, nb03;
            int32_t ne10;
            uint64_t nb10, nb11, nb12;
            uint64_t nb1, nb2, nb3;
        } args = {
            .ne00t = row_width, .ne00 = row_width,
            .nb01 = (uint64_t)row_width * sizeof(uint16_t),
            .nb02 = (uint64_t)n_table_rows * row_width * sizeof(uint16_t),
            .nb03 = (uint64_t)n_table_rows * row_width * sizeof(uint16_t),
            .ne10 = n_ids,
            .nb10 = sizeof(int32_t),
            .nb11 = (uint64_t)n_ids * sizeof(int32_t),
            .nb12 = (uint64_t)n_ids * sizeof(int32_t),
            .nb1 = (uint64_t)row_width * sizeof(float),
            .nb2 = (uint64_t)n_ids * row_width * sizeof(float),
            .nb3 = (uint64_t)n_ids * row_width * sizeof(float),
        };
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 6;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[4] = {(id)argsBuf, (id)tabBuf, (id)idsBuf, (id)dstBuf};
            [residency addAllocations:allocs count:4];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(8);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:tabBuf.gpuAddress atIndex:1];
                [argTable setAddress:idsBuf.gpuAddress atIndex:2];
                [argTable setAddress:dstBuf.gpuAddress atIndex:3];

                NSUInteger nth = MIN((NSUInteger)256, MAX((NSUInteger)1, (NSUInteger)row_width));
                NSUInteger W = ((NSUInteger)row_width + nth - 1) / nth;

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_get_rows_f16_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc dispatchThreadgroups:MTLSizeMake(W * n_ids, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) { (void)fb; dispatch_semaphore_signal(sem); }];
                id<MTL4CommandBuffer> bufs[1] = {cb};
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_dst, dstBuf.contents, dst_n * sizeof(float));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 8);
            }
        }
    }
    if (!rc) { free(host_tab); free(host_ids); free(host_dst); return 0; }

    int mismatch = 0;
    for (uint32_t i = 0; i < n_ids; i++) {
        const uint32_t expected_r = (uint32_t)host_ids[i];
        for (uint32_t c = 0; c < row_width; c++) {
            _Float16 h;
            memcpy(&h, &host_tab[(uint64_t)expected_r * row_width + c], sizeof(h));
            const float ref = (float)h;
            if (host_dst[(uint64_t)i * row_width + c] != ref) mismatch++;
        }
    }
    fprintf(stderr,
        "ds4: get_rows_f16 MTL4 canary n_table=%u row_width=%u n_ids=%u "
        "dst[0][0]=%.1f dst[end][end]=%.1f mismatch=%d\n",
        n_table_rows, row_width, n_ids,
        (double)host_dst[0], (double)host_dst[dst_n - 1], mismatch);
    free(host_tab); free(host_ids); free(host_dst);
    return (mismatch == 0) ? 1 : 0;
}

static id<MTLComputePipelineState> g_get_rows_i32_mtl4_pipeline;
static int g_get_rows_i32_mtl4_init_attempted;
static int g_get_rows_i32_mtl4_init_ok;

static int ds4_get_rows_i32_mtl4_pipeline_init(void) {
    if (g_get_rows_i32_mtl4_init_attempted) return g_get_rows_i32_mtl4_init_ok;
    g_get_rows_i32_mtl4_init_attempted = 1;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "struct gr_args {\n"
         "  int32_t ne00t; int32_t ne00;\n"
         "  uint64_t nb01; uint64_t nb02; uint64_t nb03;\n"
         "  int32_t ne10; uint64_t nb10; uint64_t nb11; uint64_t nb12;\n"
         "  uint64_t nb1; uint64_t nb2; uint64_t nb3;\n"
         "};\n"
         "kernel void get_rows_i32_mtl4(\n"
         "    device const gr_args *args [[buffer(0)]],\n"
         "    device const char    *src0 [[buffer(1)]],\n"
         "    device const char    *src1 [[buffer(2)]],\n"
         "    device       char    *dst  [[buffer(3)]],\n"
         "    uint3   tgpig [[threadgroup_position_in_grid]],\n"
         "    ushort  tiitg [[thread_index_in_threadgroup]],\n"
         "    ushort3 ntg   [[threads_per_threadgroup]]) {\n"
         "  const int32_t iw0 = tgpig.x / args->ne10;\n"
         "  const int32_t i10 = tgpig.x % args->ne10;\n"
         "  const int32_t i11 = tgpig.y;\n"
         "  const int32_t i12 = tgpig.z;\n"
         "  const int32_t r = ((const device int32_t *)\n"
         "    (src1 + i12*args->nb12 + i11*args->nb11 + i10*args->nb10))[0];\n"
         "  const int32_t i02 = i11;\n"
         "  const int32_t i03 = i12;\n"
         "  device const int32_t *psrc = (device const int32_t *)\n"
         "    (src0 + i03*args->nb03 + i02*args->nb02 + r*args->nb01);\n"
         "  device       int32_t *pdst = (device int32_t *)\n"
         "    (dst + i12*args->nb3 + i11*args->nb2 + i10*args->nb1);\n"
         "  const int ind = iw0*ntg.x + tiitg;\n"
         "  if (ind < args->ne00t) pdst[ind] = psrc[ind];\n"
         "}\n";

    g_get_rows_i32_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_get_rows_i32_mtl4", @"get_rows_i32_mtl4", 256, NULL, 0);
    g_get_rows_i32_mtl4_init_ok = (g_get_rows_i32_mtl4_pipeline != nil) ? 1 : 0;
    return g_get_rows_i32_mtl4_init_ok;
}

int ds4_gpu_mtl4_get_rows_i32_canary(uint32_t n_table_rows, uint32_t row_width, uint32_t n_ids) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_get_rows_i32_mtl4_pipeline_init()) return 0;
    if (n_table_rows == 0 || row_width == 0 || n_ids == 0) return 0;

    const uint64_t table_n = (uint64_t)n_table_rows * row_width;
    const uint64_t dst_n = (uint64_t)n_ids * row_width;
    int32_t *host_tab = (int32_t *)calloc(table_n, sizeof(int32_t));
    int32_t *host_ids = (int32_t *)calloc(n_ids, sizeof(int32_t));
    int32_t *host_dst = (int32_t *)calloc(dst_n, sizeof(int32_t));
    if (!host_tab || !host_ids || !host_dst) {
        free(host_tab); free(host_ids); free(host_dst); return 0;
    }
    for (uint32_t r = 0; r < n_table_rows; r++) {
        for (uint32_t c = 0; c < row_width; c++) {
            host_tab[(uint64_t)r * row_width + c] = (int32_t)((int)r * 10000 + (int)c);
        }
    }
    for (uint32_t i = 0; i < n_ids; i++) host_ids[i] = (int32_t)(n_table_rows - 1 - i);

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:96 options:MTLResourceStorageModeShared];
        id<MTLBuffer> tabBuf = [g_device newBufferWithBytes:host_tab length:table_n*sizeof(int32_t) options:MTLResourceStorageModeShared];
        id<MTLBuffer> idsBuf = [g_device newBufferWithBytes:host_ids length:n_ids*sizeof(int32_t) options:MTLResourceStorageModeShared];
        id<MTLBuffer> dstBuf = [g_device newBufferWithLength:dst_n*sizeof(int32_t) options:MTLResourceStorageModeShared];

        struct {
            int32_t ne00t, ne00;
            uint64_t nb01, nb02, nb03;
            int32_t ne10;
            uint64_t nb10, nb11, nb12;
            uint64_t nb1, nb2, nb3;
        } args = {
            .ne00t = row_width, .ne00 = row_width,
            .nb01 = (uint64_t)row_width * sizeof(int32_t),
            .nb02 = (uint64_t)n_table_rows * row_width * sizeof(int32_t),
            .nb03 = (uint64_t)n_table_rows * row_width * sizeof(int32_t),
            .ne10 = n_ids,
            .nb10 = sizeof(int32_t),
            .nb11 = (uint64_t)n_ids * sizeof(int32_t),
            .nb12 = (uint64_t)n_ids * sizeof(int32_t),
            .nb1 = (uint64_t)row_width * sizeof(int32_t),
            .nb2 = (uint64_t)n_ids * row_width * sizeof(int32_t),
            .nb3 = (uint64_t)n_ids * row_width * sizeof(int32_t),
        };
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 6;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[4] = {(id)argsBuf, (id)tabBuf, (id)idsBuf, (id)dstBuf};
            [residency addAllocations:allocs count:4];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(8);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:tabBuf.gpuAddress atIndex:1];
                [argTable setAddress:idsBuf.gpuAddress atIndex:2];
                [argTable setAddress:dstBuf.gpuAddress atIndex:3];

                NSUInteger nth = MIN((NSUInteger)256, MAX((NSUInteger)1, (NSUInteger)row_width));
                NSUInteger W = ((NSUInteger)row_width + nth - 1) / nth;

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_get_rows_i32_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc dispatchThreadgroups:MTLSizeMake(W * n_ids, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) { (void)fb; dispatch_semaphore_signal(sem); }];
                id<MTL4CommandBuffer> bufs[1] = {cb};
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_dst, dstBuf.contents, dst_n * sizeof(int32_t));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 8);
            }
        }
    }
    if (!rc) { free(host_tab); free(host_ids); free(host_dst); return 0; }

    int mismatch = 0;
    for (uint32_t i = 0; i < n_ids; i++) {
        const uint32_t expected_r = (uint32_t)host_ids[i];
        for (uint32_t c = 0; c < row_width; c++) {
            const int32_t ref = host_tab[(uint64_t)expected_r * row_width + c];
            if (host_dst[(uint64_t)i * row_width + c] != ref) mismatch++;
        }
    }
    fprintf(stderr,
        "ds4: get_rows_i32 MTL4 canary n_table=%u row_width=%u n_ids=%u "
        "dst[0][0]=%d dst[end][end]=%d mismatch=%d\n",
        n_table_rows, row_width, n_ids,
        host_dst[0], host_dst[dst_n - 1], mismatch);
    free(host_tab); free(host_ids); free(host_dst);
    return (mismatch == 0) ? 1 : 0;
}

/* ============================================================ */
/* bin_fuse_add_f32 MTL4 port (silv 2026-05-27 #713)            */
/* ============================================================ */
/* Function-constant-specialized variant of kernel_bin_fuse_impl with
 * FC_OP=0 (add), FC_F=1 (single src1), FC_RB=0 (no row-broadcast),
 * FC_CB=0 (no col-broadcast). The residual-add path used at every
 * layer's attn-out + x and ffn-out + x connections.
 *
 * Non-MMA elementwise. The classic kernel template-parameterizes via
 * function constants; this MTL4 port hardcodes the production residual
 * path. Additional bin_fuse specializations (mul, scalar-mul, div) can
 * follow the same pattern at separate pipelines. */

static id<MTLComputePipelineState> g_bin_fuse_add_f32_mtl4_pipeline;
static int g_bin_fuse_add_f32_mtl4_init_attempted;
static int g_bin_fuse_add_f32_mtl4_init_ok;

static int ds4_bin_fuse_add_f32_mtl4_pipeline_init(void) {
    if (g_bin_fuse_add_f32_mtl4_init_attempted) return g_bin_fuse_add_f32_mtl4_init_ok;
    g_bin_fuse_add_f32_mtl4_init_attempted = 1;
    if (!ds4_polar_pipeline_init()) return 0;

    /* Args layout mirrors ds4_metal_args_bin (FC_F=1 only needs o1[0]) but we
     * size for all 8 to match the host-side struct. */
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "struct bin_args {\n"
         "  int32_t  ne00; int32_t ne01; int32_t ne02; int32_t ne03;\n"
         "  uint64_t nb00; uint64_t nb01; uint64_t nb02; uint64_t nb03;\n"
         "  int32_t  ne10; int32_t ne11; int32_t ne12; int32_t ne13;\n"
         "  uint64_t nb10; uint64_t nb11; uint64_t nb12; uint64_t nb13;\n"
         "  int32_t  ne0;  int32_t ne1;  int32_t ne2;  int32_t ne3;\n"
         "  uint64_t nb0;  uint64_t nb1; uint64_t nb2; uint64_t nb3;\n"
         "  uint64_t offs;\n"
         "  uint64_t o1[8];\n"
         "};\n"
         "kernel void bin_fuse_add_f32_mtl4(\n"
         "    device const bin_args *args [[buffer(0)]],\n"
         "    device const char     *src0 [[buffer(1)]],\n"
         "    device const char     *src1 [[buffer(2)]],\n"
         "    device       char     *dst  [[buffer(3)]],\n"
         "    uint3   tgpig [[threadgroup_position_in_grid]],\n"
         "    ushort3 tpitg [[thread_position_in_threadgroup]],\n"
         "    ushort3 ntg   [[threads_per_threadgroup]]) {\n"
         "  const int i03 = tgpig.z;\n"
         "  const int i02 = tgpig.y;\n"
         "  const int i01 = tgpig.x;\n"
         "  if (i01 >= args->ne01) return;\n"
         "  const int i13 = i03 % args->ne13;\n"
         "  const int i12 = i02 % args->ne12;\n"
         "  const int i11 = i01 % args->ne11;\n"
         "  device const float *src0_ptr = (device const float *)\n"
         "    (src0 + i03*args->nb03 + i02*args->nb02 + i01*args->nb01 + args->offs);\n"
         "  device       float *dst_ptr  = (device float *)\n"
         "    (dst + i03*args->nb3 + i02*args->nb2 + i01*args->nb1 + args->offs);\n"
         "  device const float *src1_ptr = (device const float *)\n"
         "    (src1 + args->o1[0] + i13*args->nb13 + i12*args->nb12 + i11*args->nb11);\n"
         "  for (int i0 = tpitg.x; i0 < args->ne0; i0 += ntg.x) {\n"
         "    dst_ptr[i0] = src0_ptr[i0] + src1_ptr[i0];\n"
         "  }\n"
         "}\n";

    g_bin_fuse_add_f32_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_bin_fuse_add_f32_mtl4", @"bin_fuse_add_f32_mtl4", 256, NULL, 0);
    g_bin_fuse_add_f32_mtl4_init_ok = (g_bin_fuse_add_f32_mtl4_pipeline != nil) ? 1 : 0;
    return g_bin_fuse_add_f32_mtl4_init_ok;
}

int ds4_gpu_mtl4_bin_fuse_add_f32_canary(uint32_t n_rows, uint32_t row_width) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_bin_fuse_add_f32_mtl4_pipeline_init()) return 0;
    if (n_rows == 0 || row_width == 0) return 0;

    const uint64_t total = (uint64_t)n_rows * row_width;
    float *host_src0 = (float *)calloc(total, sizeof(float));
    float *host_src1 = (float *)calloc(total, sizeof(float));
    float *host_dst = (float *)calloc(total, sizeof(float));
    if (!host_src0 || !host_src1 || !host_dst) {
        free(host_src0); free(host_src1); free(host_dst); return 0;
    }
    for (uint32_t r = 0; r < n_rows; r++) {
        for (uint32_t c = 0; c < row_width; c++) {
            host_src0[(uint64_t)r * row_width + c] = 0.1f + 0.01f * (float)((int)r * 13 + (int)c);
            host_src1[(uint64_t)r * row_width + c] = -0.05f + 0.001f * (float)((int)r - (int)c);
        }
    }

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:256 options:MTLResourceStorageModeShared];
        id<MTLBuffer> src0Buf = [g_device newBufferWithBytes:host_src0 length:total*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> src1Buf = [g_device newBufferWithBytes:host_src1 length:total*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> dstBuf = [g_device newBufferWithLength:total*sizeof(float) options:MTLResourceStorageModeShared];

        struct {
            int32_t ne00, ne01, ne02, ne03;
            uint64_t nb00, nb01, nb02, nb03;
            int32_t ne10, ne11, ne12, ne13;
            uint64_t nb10, nb11, nb12, nb13;
            int32_t ne0, ne1, ne2, ne3;
            uint64_t nb0, nb1, nb2, nb3;
            uint64_t offs;
            uint64_t o1[8];
        } args;
        memset(&args, 0, sizeof(args));
        args.ne00 = row_width; args.ne01 = n_rows; args.ne02 = 1; args.ne03 = 1;
        args.nb00 = sizeof(float);
        args.nb01 = (uint64_t)row_width * sizeof(float);
        args.nb02 = (uint64_t)n_rows * row_width * sizeof(float);
        args.nb03 = (uint64_t)n_rows * row_width * sizeof(float);
        args.ne10 = row_width; args.ne11 = n_rows; args.ne12 = 1; args.ne13 = 1;
        args.nb10 = sizeof(float);
        args.nb11 = (uint64_t)row_width * sizeof(float);
        args.nb12 = (uint64_t)n_rows * row_width * sizeof(float);
        args.nb13 = (uint64_t)n_rows * row_width * sizeof(float);
        args.ne0 = row_width; args.ne1 = n_rows; args.ne2 = 1; args.ne3 = 1;
        args.nb0 = sizeof(float);
        args.nb1 = (uint64_t)row_width * sizeof(float);
        args.nb2 = (uint64_t)n_rows * row_width * sizeof(float);
        args.nb3 = (uint64_t)n_rows * row_width * sizeof(float);
        args.offs = 0;
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 6;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[4] = {(id)argsBuf, (id)src0Buf, (id)src1Buf, (id)dstBuf};
            [residency addAllocations:allocs count:4];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(8);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:src0Buf.gpuAddress atIndex:1];
                [argTable setAddress:src1Buf.gpuAddress atIndex:2];
                [argTable setAddress:dstBuf.gpuAddress atIndex:3];

                NSUInteger tx = MIN((NSUInteger)256, MAX((NSUInteger)1, (NSUInteger)row_width));

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_bin_fuse_add_f32_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc dispatchThreadgroups:MTLSizeMake(n_rows, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(tx, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) { (void)fb; dispatch_semaphore_signal(sem); }];
                id<MTL4CommandBuffer> bufs[1] = {cb};
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_dst, dstBuf.contents, total * sizeof(float));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 8);
            }
        }
    }
    if (!rc) { free(host_src0); free(host_src1); free(host_dst); return 0; }

    int mismatch = 0;
    double max_abs = 0.0;
    for (uint64_t i = 0; i < total; i++) {
        const float ref = host_src0[i] + host_src1[i];
        const double d = fabs((double)(host_dst[i] - ref));
        if (d > max_abs) max_abs = d;
        if (d > 1.0e-5) mismatch++;
    }
    fprintf(stderr,
        "ds4: bin_fuse_add_f32 MTL4 canary n_rows=%u row_width=%u "
        "dst[0]=%.5f (ref=%.5f) dst[end]=%.5f (ref=%.5f) mismatch=%d max_abs=%.4e\n",
        n_rows, row_width,
        (double)host_dst[0], (double)(host_src0[0] + host_src1[0]),
        (double)host_dst[total - 1], (double)(host_src0[total - 1] + host_src1[total - 1]),
        mismatch, max_abs);
    free(host_src0); free(host_src1); free(host_dst);
    return (mismatch == 0) ? 1 : 0;
}

/* ============================================================ */
/* bin_fuse_mul/sub/div_f32 MTL4 ports (silv 2026-05-27 #714/#715/#716) */
/* ============================================================ */
/* Companion ops to #713 bin_fuse_add. Same skeleton, FC_OP varies:
 * sub (1), mul (2), div (3). All FC_F=1, FC_RB=0, FC_CB=0. Used for
 * residual subtraction (rare), elementwise multiply (gate*up), and
 * row-wise division (norm-style ops). */

/* Generic helper to instantiate any of the 4 bin op variants at the same
 * kernel structure. The OP_INFIX string is embedded into the MSL source.
 * cb_mode=0 → no broadcast; cb_mode=1 → column-broadcast (src1 is a single
 * row broadcast across all rows, FC_CB=1 in classic kernel). */
static id<MTLComputePipelineState> ds4_bin_fuse_build_pipeline_cb(
        const char *op_infix, int cb_mode, const char *kernel_name, const char *lib_name);

static id<MTLComputePipelineState> ds4_bin_fuse_build_pipeline(
        const char *op_infix, const char *kernel_name, const char *lib_name) {
    return ds4_bin_fuse_build_pipeline_cb(op_infix, 0, kernel_name, lib_name);
}

static id<MTLComputePipelineState> ds4_bin_fuse_build_pipeline_cb(
        const char *op_infix, int cb_mode, const char *kernel_name, const char *lib_name) {
    if (!ds4_polar_pipeline_init()) return nil;
    NSError *err = nil;
    NSString *source = [NSString stringWithFormat:
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "struct bin_args {\n"
         "  int32_t  ne00; int32_t ne01; int32_t ne02; int32_t ne03;\n"
         "  uint64_t nb00; uint64_t nb01; uint64_t nb02; uint64_t nb03;\n"
         "  int32_t  ne10; int32_t ne11; int32_t ne12; int32_t ne13;\n"
         "  uint64_t nb10; uint64_t nb11; uint64_t nb12; uint64_t nb13;\n"
         "  int32_t  ne0;  int32_t ne1;  int32_t ne2;  int32_t ne3;\n"
         "  uint64_t nb0;  uint64_t nb1; uint64_t nb2; uint64_t nb3;\n"
         "  uint64_t offs;\n"
         "  uint64_t o1[8];\n"
         "};\n"
         "kernel void %s(\n"
         "    device const bin_args *args [[buffer(0)]],\n"
         "    device const char     *src0 [[buffer(1)]],\n"
         "    device const char     *src1 [[buffer(2)]],\n"
         "    device       char     *dst  [[buffer(3)]],\n"
         "    uint3   tgpig [[threadgroup_position_in_grid]],\n"
         "    ushort3 tpitg [[thread_position_in_threadgroup]],\n"
         "    ushort3 ntg   [[threads_per_threadgroup]]) {\n"
         "  const int i03 = tgpig.z;\n"
         "  const int i02 = tgpig.y;\n"
         "  const int i01 = tgpig.x;\n"
         "  if (i01 >= args->ne01) return;\n"
         "  const int i13 = i03 %% args->ne13;\n"
         "  const int i12 = i02 %% args->ne12;\n"
         "  const int i11 = i01 %% args->ne11;\n"
         "  device const float *src0_ptr = (device const float *)\n"
         "    (src0 + i03*args->nb03 + i02*args->nb02 + i01*args->nb01 + args->offs);\n"
         "  device       float *dst_ptr  = (device float *)\n"
         "    (dst + i03*args->nb3 + i02*args->nb2 + i01*args->nb1 + args->offs);\n"
         "  device const float *src1_ptr = (device const float *)\n"
         "    (src1 + args->o1[0] + i13*args->nb13 + i12*args->nb12 + i11*args->nb11);\n"
         "  for (int i0 = tpitg.x; i0 < args->ne0; i0 += ntg.x) {\n"
         "    const int i10 = %s;\n"
         "    dst_ptr[i0] = src0_ptr[i0] %s src1_ptr[i10];\n"
         "  }\n"
         "}\n",
        kernel_name,
        cb_mode ? "i0 % args->ne10" : "i0",
        op_infix];

    MTL4LibraryDescriptor *libDesc = [MTL4LibraryDescriptor new];
    libDesc.source = source;
    libDesc.name = [NSString stringWithUTF8String:lib_name];
    id<MTLLibrary> lib = [g_polar_compiler newLibraryWithDescriptor:libDesc error:&err];
    if (!lib) {
        fprintf(stderr, "ds4: %s MTL4 library compile failed: %s\n",
                lib_name, err ? err.localizedDescription.UTF8String : "(no error)");
        return nil;
    }
    MTL4LibraryFunctionDescriptor *fnDesc = [MTL4LibraryFunctionDescriptor new];
    fnDesc.library = lib;
    fnDesc.name = [NSString stringWithUTF8String:kernel_name];
    MTL4ComputePipelineDescriptor *pipeDesc = [MTL4ComputePipelineDescriptor new];
    pipeDesc.computeFunctionDescriptor = fnDesc;
    pipeDesc.threadGroupSizeIsMultipleOfThreadExecutionWidth = YES;
    pipeDesc.maxTotalThreadsPerThreadgroup = 256;
    id<MTLComputePipelineState> pipeline =
        [g_polar_compiler newComputePipelineStateWithDescriptor:pipeDesc
                                           compilerTaskOptions:nil error:&err];
    if (!pipeline) {
        fprintf(stderr, "ds4: %s MTL4 pipeline failed: %s\n",
                lib_name, err ? err.localizedDescription.UTF8String : "(no error)");
        return nil;
    }
    fprintf(stderr, "ds4: %s MTL4 pipeline initialized\n", lib_name);
    return pipeline;
}

