/* ============================================================ */
/* mul_mv_f32_f32 MTL4 port (silv 2026-05-27 #722)              */
/* ============================================================ */
/* Dense F32 matrix-vector multiply. First MTL4 port to USE function
 * constants (FC_mul_mv_nsg). Pattern:
 *   1. Compile MSL source with function_constant declarations
 *   2. Build MTL4LibraryFunctionDescriptor (base)
 *   3. Wrap in MTL4SpecializedFunctionDescriptor + constantValues
 *   4. Pass specialized descriptor to MTL4ComputePipelineDescriptor
 *
 * NR0=4 hardcoded (most common dispatch case). NSG picked at pipeline-
 * init time (default 4). Future variants can spawn additional NSG-value
 * pipelines. The classic factory ds4_gpu_get_mul_mv_pipeline(name, nsg)
 * already does this pattern for the legacy MTL path.
 *
 * Args struct: ds4_metal_args_mul_mv (ne00, ne01, ne02, nb00, nb01,
 * nb02, nb03, ne10, ne11, ne12, nb10, nb11, nb12, nb13, ne0, ne1, nr0,
 * r2, r3). */

static id<MTLComputePipelineState> ds4_mul_mv_f32_f32_build_pipeline(short nsg_value) {
    /* MSL source: full mul_mv_t_t<float, float, NR0=4> impl + helper.
     * NR0 is hardcoded to 4 (template); NSG comes from FC.
     * NR0 = compile-time tile rows per threadgroup. */
    NSString *source = [NSString stringWithFormat:
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "#define FC_MUL_MV 600\n"
         "#define N_SIMDWIDTH 32\n"
         "constant short FC_mul_mv_nsg [[function_constant(FC_MUL_MV + 0)]];\n"
         "struct mv_args {\n"
         "  int ne00; int ne01; int ne02;\n"
         "  ulong nb00; ulong nb01; ulong nb02; ulong nb03;\n"
         "  int ne10; int ne11; int ne12;\n"
         "  ulong nb10; ulong nb11; ulong nb12; ulong nb13;\n"
         "  int ne0; int ne1; int nr0;\n"
         "  short r2; short r3;\n"
         "};\n"
         "static inline void reduce_write(\n"
         "    device float *dst_f32,\n"
         "    thread float *sumf,\n"
         "    const int r0,\n"
         "    const int ne01,\n"
         "    ushort tiisg,\n"
         "    ushort sgitg,\n"
         "    threadgroup char *shmem) {\n"
         "  constexpr short NW = N_SIMDWIDTH;\n"
         "  constexpr short NR0 = 4;\n"
         "  threadgroup float *shmem_f32[NR0];\n"
         "  for (short row = 0; row < NR0; ++row) {\n"
         "    shmem_f32[row] = (threadgroup float *)shmem + NW*row;\n"
         "    if (sgitg == 0) shmem_f32[row][tiisg] = 0.0f;\n"
         "    sumf[row] = simd_sum(sumf[row]);\n"
         "  }\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  for (short row = 0; row < NR0; ++row) {\n"
         "    if (tiisg == 0) shmem_f32[row][sgitg] = sumf[row];\n"
         "  }\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  for (short row = 0; row < NR0 && r0 + row < ne01; ++row) {\n"
         "    float tot = simd_sum(shmem_f32[row][tiisg]);\n"
         "    if (tiisg == 0 && sgitg == 0) dst_f32[r0 + row] = tot;\n"
         "  }\n"
         "}\n"
         "kernel void mul_mv_f32_f32_mtl4(\n"
         "    device const mv_args *args [[buffer(0)]],\n"
         "    device const char    *src0 [[buffer(1)]],\n"
         "    device const char    *src1 [[buffer(2)]],\n"
         "    device       char    *dst  [[buffer(3)]],\n"
         "    threadgroup  char    *shmem [[threadgroup(0)]],\n"
         "    uint3   tgpig [[threadgroup_position_in_grid]],\n"
         "    ushort  tiisg [[thread_index_in_simdgroup]],\n"
         "    ushort  sgitg [[simdgroup_index_in_threadgroup]]) {\n"
         "  constexpr short NR0 = 4;\n"
         "  const short NSG = FC_mul_mv_nsg;\n"
         "  constexpr short NW = N_SIMDWIDTH;\n"
         "  constexpr short NB = 32;\n"
         "  constexpr short NF = 8;\n"
         "  const int nb = args->ne00 / NB;\n"
         "  const int r0 = tgpig.x * NR0;\n"
         "  const int r1 = tgpig.y;\n"
         "  const int im = tgpig.z;\n"
         "  const uint i12 = im %% args->ne12;\n"
         "  const uint i13 = im / args->ne12;\n"
         "  const ulong offset1 = r1*args->nb11 + i12*args->nb12 + i13*args->nb13;\n"
         "  device const float *y = (device const float *)(src1 + offset1);\n"
         "  device const float *ax[NR0];\n"
         "  for (short row = 0; row < NR0; ++row) {\n"
         "    const ulong offset0 = (r0 + row)*args->nb01\n"
         "                       + (i12/args->r2)*args->nb02\n"
         "                       + (i13/args->r3)*args->nb03;\n"
         "    ax[row] = (device const float *)((device const char *)src0 + offset0);\n"
         "  }\n"
         "  float sumf[NR0] = {0.0f};\n"
         "  const short ix = tiisg / (NW / NF);\n"
         "  const short il = tiisg %% (NW / NF);\n"
         "  const int ib0 = sgitg * NF + ix;\n"
         "  float yl[NF];\n"
         "  device const float *yb = y + ib0*NB + il*NF;\n"
         "  for (int ib = ib0; ib < nb; ib += NSG*NF) {\n"
         "    for (short i = 0; i < NF; ++i) yl[i] = yb[i];\n"
         "    for (short row = 0; row < NR0; ++row) {\n"
         "      device const float *xb = ax[row] + ib*NB + il*NF;\n"
         "      float sumq = 0.0f;\n"
         "      for (short i = 0; i < NF; ++i) sumq += xb[i] * yl[i];\n"
         "      sumf[row] += sumq;\n"
         "    }\n"
         "    yb += NSG*NF*NW;\n"
         "  }\n"
         "  for (int i = nb*NB + sgitg*NW + tiisg; i < args->ne00; i += NW*NSG) {\n"
         "    for (short row = 0; row < NR0; ++row) sumf[row] += ax[row][i] * y[i];\n"
         "  }\n"
         "  device float *dst_f32 = (device float *)dst\n"
         "    + (ulong)im*args->ne0*args->ne1 + (ulong)r1*args->ne0;\n"
         "  reduce_write(dst_f32, sumf, r0, args->ne01, tiisg, sgitg, shmem);\n"
         "}\n"];

    /* silv 2026-05-27 refactor: use shared ds4_mtl4_build_kernel_pipeline */
    const ds4_mtl4_fc_short fcs[] = {{nsg_value, 600}};
    return ds4_mtl4_build_kernel_pipeline(
        source,
        @"ds4_mul_mv_f32_f32_mtl4",
        @"mul_mv_f32_f32_mtl4",
        1024,
        fcs, 1);
}

static id<MTLComputePipelineState> g_mul_mv_f32_f32_nsg4_mtl4_pipeline;
static int g_mul_mv_f32_f32_nsg4_mtl4_init_attempted;
static int g_mul_mv_f32_f32_nsg4_mtl4_init_ok;

static int ds4_mul_mv_f32_f32_nsg4_mtl4_pipeline_init(void) {
    if (g_mul_mv_f32_f32_nsg4_mtl4_init_attempted) return g_mul_mv_f32_f32_nsg4_mtl4_init_ok;
    g_mul_mv_f32_f32_nsg4_mtl4_init_attempted = 1;
    g_mul_mv_f32_f32_nsg4_mtl4_pipeline = ds4_mul_mv_f32_f32_build_pipeline(4);
    g_mul_mv_f32_f32_nsg4_mtl4_init_ok = (g_mul_mv_f32_f32_nsg4_mtl4_pipeline != nil) ? 1 : 0;
    return g_mul_mv_f32_f32_nsg4_mtl4_init_ok;
}

/* Canary: M-row matrix × N-elt vector → M-elt output.
 * Uses NSG=4, NR0=4 — so M must be multiple of 4 (the threadgroup r0 stride).
 * Threadgroups: (M/4, 1, 1); threads per tg: (NSG * 32, 1, 1) = 128. */
int ds4_gpu_mtl4_mul_mv_f32_f32_canary(uint32_t M, uint32_t N) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_mul_mv_f32_f32_nsg4_mtl4_pipeline_init()) return 0;
    if (M == 0 || N == 0 || (M % 4) != 0 || (N % 32) != 0) {
        fprintf(stderr, "ds4: mul_mv canary needs M%%4==0 and N%%32==0 (got M=%u N=%u)\n", M, N);
        return 0;
    }

    const uint64_t matrix_n = (uint64_t)M * N;
    float *host_mat = (float *)calloc(matrix_n, sizeof(float));
    float *host_vec = (float *)calloc(N, sizeof(float));
    float *host_dst = (float *)calloc(M, sizeof(float));
    float *expected = (float *)calloc(M, sizeof(float));
    if (!host_mat || !host_vec || !host_dst || !expected) {
        free(host_mat); free(host_vec); free(host_dst); free(expected); return 0;
    }
    /* Test pattern: row r col c = (r % 7) * 0.01 + (c % 5) * 0.001
     * vec[c] = (c % 3) * 0.1 + 0.5. Range stays small for FP32 stability. */
    for (uint32_t r = 0; r < M; r++) {
        for (uint32_t c = 0; c < N; c++) {
            host_mat[(uint64_t)r * N + c] = (float)((int)r % 7) * 0.01f + (float)((int)c % 5) * 0.001f;
        }
    }
    for (uint32_t c = 0; c < N; c++) host_vec[c] = (float)((int)c % 3) * 0.1f + 0.5f;
    for (uint32_t r = 0; r < M; r++) {
        double acc = 0.0;
        for (uint32_t c = 0; c < N; c++) {
            acc += (double)host_mat[(uint64_t)r * N + c] * (double)host_vec[c];
        }
        expected[r] = (float)acc;
    }

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:128 options:MTLResourceStorageModeShared];
        id<MTLBuffer> matBuf = [g_device newBufferWithBytes:host_mat length:matrix_n*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> vecBuf = [g_device newBufferWithBytes:host_vec length:N*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> dstBuf = [g_device newBufferWithLength:M*sizeof(float) options:MTLResourceStorageModeShared];

        struct {
            int ne00, ne01, ne02;
            uint64_t nb00, nb01, nb02, nb03;
            int ne10, ne11, ne12;
            uint64_t nb10, nb11, nb12, nb13;
            int ne0, ne1, nr0;
            int16_t r2, r3;
        } args;
        memset(&args, 0, sizeof(args));
        args.ne00 = N; args.ne01 = M; args.ne02 = 1;
        args.nb00 = sizeof(float);
        args.nb01 = (uint64_t)N * sizeof(float);
        args.nb02 = (uint64_t)M * N * sizeof(float);
        args.nb03 = (uint64_t)M * N * sizeof(float);
        args.ne10 = N; args.ne11 = 1; args.ne12 = 1;
        args.nb10 = sizeof(float);
        args.nb11 = (uint64_t)N * sizeof(float);
        args.nb12 = (uint64_t)N * sizeof(float);
        args.nb13 = (uint64_t)N * sizeof(float);
        args.ne0 = M; args.ne1 = 1; args.nr0 = 4;
        args.r2 = 1; args.r3 = 1;
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 6;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[4] = {(id)argsBuf, (id)matBuf, (id)vecBuf, (id)dstBuf};
            [residency addAllocations:allocs count:4];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(8);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:matBuf.gpuAddress atIndex:1];
                [argTable setAddress:vecBuf.gpuAddress atIndex:2];
                [argTable setAddress:dstBuf.gpuAddress atIndex:3];

                /* NSG=4 simdgroups × 32 lanes = 128 threads/tg */
                NSUInteger nth = 4u * 32u;
                NSUInteger shmem_bytes = 4u * 32u * sizeof(float);  /* NR0 × NW */

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_mul_mv_f32_f32_nsg4_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc setThreadgroupMemoryLength:shmem_bytes atIndex:0];
                /* Dispatch: (M/4, 1, 1) */
                [enc dispatchThreadgroups:MTLSizeMake(M / 4, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) { (void)fb; dispatch_semaphore_signal(sem); }];
                id<MTL4CommandBuffer> bufs[1] = {cb};
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_dst, dstBuf.contents, M * sizeof(float));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 8);
            }
        }
    }
    if (!rc) { free(host_mat); free(host_vec); free(host_dst); free(expected); return 0; }

    int mismatch = 0;
    double max_rel = 0.0;
    for (uint32_t r = 0; r < M; r++) {
        const double diff = fabs((double)(host_dst[r] - expected[r]));
        const double rel = diff / (fabs((double)expected[r]) + 1e-7);
        if (rel > max_rel) max_rel = rel;
        if (rel > 1e-4) mismatch++;
    }
    fprintf(stderr,
        "ds4: mul_mv_f32_f32 MTL4 canary M=%u N=%u "
        "dst[0]=%.5f (ref=%.5f) dst[end]=%.5f (ref=%.5f) mismatch=%d max_rel=%.4e\n",
        M, N,
        (double)host_dst[0], (double)expected[0],
        (double)host_dst[M - 1], (double)expected[M - 1],
        mismatch, max_rel);
    free(host_mat); free(host_vec); free(host_dst); free(expected);
    return (mismatch == 0) ? 1 : 0;
}

/* ============================================================ */
/* mul_mv_q8_0_f32 MTL4 port (silv 2026-05-27 #723)             */
/* ============================================================ */
/* Q8_0 matrix × FP32 vector → FP32 output. Production Q-quantized
 * matvec for shared experts and small dense projections. Uses
 * FC_mul_mv_nsg (FC pattern from #722). NR0=N_R0_Q8_0=2.
 *
 * Q8_0 block layout: { half d; int8_t qs[32]; } = 34 bytes/block.
 * Dequant: val[i] = (float)d * (float)qs[i]
 *
 * Per-thread inner loop reads QK8_0=32 quantized bytes + 32 vec floats,
 * accumulates partial dot, then multiplies by the block scale once
 * (saves QK8_0 muls per block — Q8_0 amortized dequant). */

static id<MTLComputePipelineState> ds4_mul_mv_q8_0_f32_build_pipeline(short nsg_value) {
    NSString *source = [NSString stringWithFormat:
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "#define FC_MUL_MV 600\n"
         "#define N_SIMDWIDTH 32\n"
         "#define QK8_0 32\n"
         "constant short FC_mul_mv_nsg [[function_constant(FC_MUL_MV + 0)]];\n"
         "struct block_q8_0 { half d; int8_t qs[QK8_0]; };\n"
         "struct mv_args {\n"
         "  int ne00; int ne01; int ne02;\n"
         "  ulong nb00; ulong nb01; ulong nb02; ulong nb03;\n"
         "  int ne10; int ne11; int ne12;\n"
         "  ulong nb10; ulong nb11; ulong nb12; ulong nb13;\n"
         "  int ne0; int ne1; int nr0;\n"
         "  short r2; short r3;\n"
         "};\n"
         "static inline void reduce_write_nr2(\n"
         "    device float *dst_f32,\n"
         "    thread float *sumf,\n"
         "    const int r0,\n"
         "    const int ne01,\n"
         "    ushort tiisg,\n"
         "    ushort sgitg,\n"
         "    threadgroup char *shmem) {\n"
         "  constexpr short NW = N_SIMDWIDTH;\n"
         "  constexpr short NR0 = 2;\n"
         "  threadgroup float *shmem_f32[NR0];\n"
         "  for (short row = 0; row < NR0; ++row) {\n"
         "    shmem_f32[row] = (threadgroup float *)shmem + NW*row;\n"
         "    if (sgitg == 0) shmem_f32[row][tiisg] = 0.0f;\n"
         "    sumf[row] = simd_sum(sumf[row]);\n"
         "  }\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  for (short row = 0; row < NR0; ++row) {\n"
         "    if (tiisg == 0) shmem_f32[row][sgitg] = sumf[row];\n"
         "  }\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  for (short row = 0; row < NR0 && r0 + row < ne01; ++row) {\n"
         "    float tot = simd_sum(shmem_f32[row][tiisg]);\n"
         "    if (tiisg == 0 && sgitg == 0) dst_f32[r0 + row] = tot;\n"
         "  }\n"
         "}\n"
         "kernel void mul_mv_q8_0_f32_mtl4(\n"
         "    device const mv_args *args [[buffer(0)]],\n"
         "    device const char    *src0 [[buffer(1)]],\n"
         "    device const char    *src1 [[buffer(2)]],\n"
         "    device       char    *dst  [[buffer(3)]],\n"
         "    threadgroup  char    *shmem [[threadgroup(0)]],\n"
         "    uint3   tgpig [[threadgroup_position_in_grid]],\n"
         "    ushort  tiisg [[thread_index_in_simdgroup]],\n"
         "    ushort  sgitg [[simdgroup_index_in_threadgroup]]) {\n"
         "  constexpr short NR0 = 2;\n"
         "  const short NSG = FC_mul_mv_nsg;\n"
         "  constexpr short NW = N_SIMDWIDTH;\n"
         "  constexpr short NQ = 8;\n"
         "  const int nb = args->ne00 / QK8_0;\n"
         "  const int r0 = tgpig.x * NR0;\n"
         "  const int r1 = tgpig.y;\n"
         "  const int im = tgpig.z;\n"
         "  const uint i12 = im %% args->ne12;\n"
         "  const uint i13 = im / args->ne12;\n"
         "  const ulong offset1 = r1*args->nb11 + i12*args->nb12 + i13*args->nb13;\n"
         "  device const float *y = (device const float *)(src1 + offset1);\n"
         "  device const block_q8_0 *ax[NR0];\n"
         "  for (short row = 0; row < NR0; ++row) {\n"
         "    const ulong offset0 = (r0 + row)*args->nb01\n"
         "                       + (i12/args->r2)*args->nb02\n"
         "                       + (i13/args->r3)*args->nb03;\n"
         "    ax[row] = (device const block_q8_0 *)((device const char *)src0 + offset0);\n"
         "  }\n"
         "  float sumf[NR0] = {0.0f};\n"
         "  const short ix = tiisg / (NW / NQ);\n"
         "  const short il = tiisg %% (NW / NQ);\n"
         "  const int ib0 = sgitg * NQ + ix;\n"
         "  float yl[NQ];\n"
         "  device const float *yb = y + ib0*QK8_0 + il*NQ;\n"
         "  for (int ib = ib0; ib < nb; ib += NSG*NQ) {\n"
         "    for (short i = 0; i < NQ; ++i) yl[i] = yb[i];\n"
         "    for (short row = 0; row < NR0; ++row) {\n"
         "      device const int8_t *qs = ax[row][ib].qs + il*NQ;\n"
         "      float sumq = 0.0f;\n"
         "      for (short i = 0; i < NQ; ++i) sumq += (float)qs[i] * yl[i];\n"
         "      sumf[row] += sumq * (float)ax[row][ib].d;\n"
         "    }\n"
         "    yb += NSG*NQ*QK8_0;\n"
         "  }\n"
         "  device float *dst_f32 = (device float *)dst\n"
         "    + (ulong)im*args->ne0*args->ne1 + (ulong)r1*args->ne0;\n"
         "  reduce_write_nr2(dst_f32, sumf, r0, args->ne01, tiisg, sgitg, shmem);\n"
         "}\n"];

    const ds4_mtl4_fc_short fcs[] = {{nsg_value, 600}};
    return ds4_mtl4_build_kernel_pipeline(
        source,
        @"ds4_mul_mv_q8_0_f32_mtl4",
        @"mul_mv_q8_0_f32_mtl4",
        1024,
        fcs, 1);
}

static id<MTLComputePipelineState> g_mul_mv_q8_0_f32_nsg4_mtl4_pipeline;
static int g_mul_mv_q8_0_f32_nsg4_mtl4_init_attempted;
static int g_mul_mv_q8_0_f32_nsg4_mtl4_init_ok;

static int ds4_mul_mv_q8_0_f32_nsg4_mtl4_pipeline_init(void) {
    if (g_mul_mv_q8_0_f32_nsg4_mtl4_init_attempted) return g_mul_mv_q8_0_f32_nsg4_mtl4_init_ok;
    g_mul_mv_q8_0_f32_nsg4_mtl4_init_attempted = 1;
    g_mul_mv_q8_0_f32_nsg4_mtl4_pipeline = ds4_mul_mv_q8_0_f32_build_pipeline(4);
    g_mul_mv_q8_0_f32_nsg4_mtl4_init_ok = (g_mul_mv_q8_0_f32_nsg4_mtl4_pipeline != nil) ? 1 : 0;
    return g_mul_mv_q8_0_f32_nsg4_mtl4_init_ok;
}

/* Host-side Q8_0 quantization helper for canary: encode FP32 row into
 * Q8_0 blocks (one block per QK8_0=32 elements). */
static void ds4_quantize_q8_0_row(const float *row, uint32_t n, uint8_t *blocks_out) {
    /* layout: each block = [u16 d_half | s8 qs[32]] = 34 bytes
     * Caller ensures blocks_out has at least (n/32) * 34 bytes */
    const uint32_t n_blocks = n / 32u;
    for (uint32_t b = 0; b < n_blocks; b++) {
        const float *src = row + (uint64_t)b * 32u;
        float amax = 0.0f;
        for (uint32_t i = 0; i < 32; i++) {
            const float v = fabsf(src[i]);
            if (v > amax) amax = v;
        }
        const float d = (amax > 0.0f) ? (amax / 127.0f) : 1.0f;
        const float inv_d = (amax > 0.0f) ? (127.0f / amax) : 1.0f;
        uint8_t *blk = blocks_out + (uint64_t)b * 34u;
        _Float16 d_half = (_Float16)d;
        memcpy(blk, &d_half, 2);
        int8_t *qs = (int8_t *)(blk + 2);
        for (uint32_t i = 0; i < 32; i++) {
            float q = src[i] * inv_d;
            if (q > 127.0f) q = 127.0f;
            if (q < -128.0f) q = -128.0f;
            qs[i] = (int8_t)(q < 0.0f ? (q - 0.5f) : (q + 0.5f));
        }
    }
}

/* Canary: M-row Q8_0 matrix × N-elt FP32 vector → M-elt FP32 output.
 * Uses NSG=4, NR0=2; M must be multiple of 2, N must be multiple of 256
 * (NSG × NQ × QK8_0 = 4 × 8 × 32 = 1024 — but the inner loop handles
 * remainder via NSG×NQ-block stride; for the canary keep N a multiple
 * of QK8_0=32 to avoid block padding). */
int ds4_gpu_mtl4_mul_mv_q8_0_f32_canary(uint32_t M, uint32_t N) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_mul_mv_q8_0_f32_nsg4_mtl4_pipeline_init()) return 0;
    if (M == 0 || N == 0 || (M % 2) != 0 || (N % 32) != 0) {
        fprintf(stderr, "ds4: mul_mv_q8_0 canary needs M%%2==0 and N%%32==0 (got M=%u N=%u)\n", M, N);
        return 0;
    }

    /* Allocate host buffers + Q8_0-quantized matrix */
    float *host_mat = (float *)calloc((uint64_t)M * N, sizeof(float));
    float *host_vec = (float *)calloc(N, sizeof(float));
    float *host_dst = (float *)calloc(M, sizeof(float));
    float *expected = (float *)calloc(M, sizeof(float));
    const uint32_t n_blocks_per_row = N / 32u;
    const uint64_t q8_row_bytes = (uint64_t)n_blocks_per_row * 34u;
    uint8_t *host_q8 = (uint8_t *)calloc((uint64_t)M * q8_row_bytes, 1);
    if (!host_mat || !host_vec || !host_dst || !expected || !host_q8) {
        free(host_mat); free(host_vec); free(host_dst); free(expected); free(host_q8);
        return 0;
    }
    /* Integer-valued pattern in [-125, 124] — values fit comfortably under
     * the Q8_0 range of [-127, 127]. The quantization scale d will be
     * amax/127 per block, introducing a small per-block quantization step.
     * To make the canary check the KERNEL (not the encoder noise), we
     * dequantize the Q8_0 blocks back into host_mat and use those for the
     * CPU reference. The dequantized values are exactly what the GPU sees. */
    for (uint32_t r = 0; r < M; r++) {
        for (uint32_t c = 0; c < N; c++) {
            host_mat[(uint64_t)r * N + c] = (float)((int)((r * 13 + c * 7) % 250) - 125);
        }
        ds4_quantize_q8_0_row(host_mat + (uint64_t)r * N, N, host_q8 + (uint64_t)r * q8_row_bytes);
        /* Dequantize back into host_mat so expected matches GPU semantics */
        for (uint32_t b = 0; b < n_blocks_per_row; b++) {
            const uint8_t *blk = host_q8 + (uint64_t)r * q8_row_bytes + (uint64_t)b * 34u;
            _Float16 d_half;
            memcpy(&d_half, blk, sizeof(d_half));
            const float d = (float)d_half;
            const int8_t *qs = (const int8_t *)(blk + 2);
            for (uint32_t i = 0; i < 32; i++) {
                host_mat[(uint64_t)r * N + (uint64_t)b * 32u + i] = (float)qs[i] * d;
            }
        }
    }
    for (uint32_t c = 0; c < N; c++) host_vec[c] = ((float)((int)(c % 7)) - 3.0f) * 0.5f;
    for (uint32_t r = 0; r < M; r++) {
        double acc = 0.0;
        for (uint32_t c = 0; c < N; c++) {
            acc += (double)host_mat[(uint64_t)r * N + c] * (double)host_vec[c];
        }
        expected[r] = (float)acc;
    }

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:128 options:MTLResourceStorageModeShared];
        id<MTLBuffer> q8Buf = [g_device newBufferWithBytes:host_q8 length:(uint64_t)M*q8_row_bytes options:MTLResourceStorageModeShared];
        id<MTLBuffer> vecBuf = [g_device newBufferWithBytes:host_vec length:N*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> dstBuf = [g_device newBufferWithLength:M*sizeof(float) options:MTLResourceStorageModeShared];

        struct {
            int ne00, ne01, ne02;
            uint64_t nb00, nb01, nb02, nb03;
            int ne10, ne11, ne12;
            uint64_t nb10, nb11, nb12, nb13;
            int ne0, ne1, nr0;
            int16_t r2, r3;
        } args;
        memset(&args, 0, sizeof(args));
        args.ne00 = N; args.ne01 = M; args.ne02 = 1;
        args.nb00 = 1;  /* Q8_0 is byte-addressed inside block; nb00 unused by impl */
        args.nb01 = q8_row_bytes;
        args.nb02 = (uint64_t)M * q8_row_bytes;
        args.nb03 = (uint64_t)M * q8_row_bytes;
        args.ne10 = N; args.ne11 = 1; args.ne12 = 1;
        args.nb10 = sizeof(float);
        args.nb11 = (uint64_t)N * sizeof(float);
        args.nb12 = (uint64_t)N * sizeof(float);
        args.nb13 = (uint64_t)N * sizeof(float);
        args.ne0 = M; args.ne1 = 1; args.nr0 = 2;
        args.r2 = 1; args.r3 = 1;
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 6;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[4] = {(id)argsBuf, (id)q8Buf, (id)vecBuf, (id)dstBuf};
            [residency addAllocations:allocs count:4];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(8);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:q8Buf.gpuAddress atIndex:1];
                [argTable setAddress:vecBuf.gpuAddress atIndex:2];
                [argTable setAddress:dstBuf.gpuAddress atIndex:3];

                NSUInteger nth = 4u * 32u;  /* NSG=4 × 32 lanes = 128 threads */
                NSUInteger shmem_bytes = 2u * 32u * sizeof(float);  /* NR0=2 × NW=32 */

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_mul_mv_q8_0_f32_nsg4_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc setThreadgroupMemoryLength:shmem_bytes atIndex:0];
                [enc dispatchThreadgroups:MTLSizeMake(M / 2, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) { (void)fb; dispatch_semaphore_signal(sem); }];
                id<MTL4CommandBuffer> bufs[1] = {cb};
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_dst, dstBuf.contents, M * sizeof(float));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 8);
            }
        }
    }
    if (!rc) {
        free(host_mat); free(host_vec); free(host_dst); free(expected); free(host_q8);
        return 0;
    }

    int mismatch = 0;
    double max_rel = 0.0;
    for (uint32_t r = 0; r < M; r++) {
        const double diff = fabs((double)(host_dst[r] - expected[r]));
        const double rel = diff / (fabs((double)expected[r]) + 1e-3);
        if (rel > max_rel) max_rel = rel;
        /* Q8_0 dequant tolerance: scale × 127 magnitude → ~1 ULP per element ×
         * N elements per row. For our pattern this is well within 1% relative. */
        if (rel > 5.0e-3) mismatch++;
    }
    fprintf(stderr,
        "ds4: mul_mv_q8_0_f32 MTL4 canary M=%u N=%u "
        "dst[0]=%.2f (ref=%.2f) dst[end]=%.2f (ref=%.2f) mismatch=%d max_rel=%.4e\n",
        M, N,
        (double)host_dst[0], (double)expected[0],
        (double)host_dst[M - 1], (double)expected[M - 1],
        mismatch, max_rel);
    free(host_mat); free(host_vec); free(host_dst); free(expected); free(host_q8);
    return (mismatch == 0) ? 1 : 0;
}

/* ============================================================ */
/* dsv4_shared_gate_up_swiglu_q8_0 MTL4 port (silv 2026-05-27 #724) */
/* ============================================================ */
/* Shared-expert fused gate+up Q8_0 matvecs followed by SwiGLU activation.
 * Replaces three separate dispatches (gate matvec, up matvec, SwiGLU) with
 * one Q8_0 read of the activation vector. The activation vector y is read
 * ONCE per ib iteration and broadcast to both gate and up dequant lanes.
 *
 * Inputs: args, src0_gate (Q8_0), src0_up (Q8_0), src1 (FP32 vec), clamp (float)
 * Outputs: dst_gate (FP32), dst_up (FP32), dst_mid (FP32 = SiLU(g) * u)
 * FC: FC_mul_mv_nsg (function constant from #722 pattern)
 * NR0=2, NSG=4. */

static id<MTLComputePipelineState> ds4_dsv4_shared_gate_up_swiglu_q8_0_build_pipeline(short nsg_value) {
    NSString *source = [NSString stringWithFormat:
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "#define FC_MUL_MV 600\n"
         "#define N_SIMDWIDTH 32\n"
         "#define QK8_0 32\n"
         "constant short FC_mul_mv_nsg [[function_constant(FC_MUL_MV + 0)]];\n"
         "struct block_q8_0 { half d; int8_t qs[QK8_0]; };\n"
         "struct mv_args {\n"
         "  int ne00; int ne01; int ne02;\n"
         "  ulong nb00; ulong nb01; ulong nb02; ulong nb03;\n"
         "  int ne10; int ne11; int ne12;\n"
         "  ulong nb10; ulong nb11; ulong nb12; ulong nb13;\n"
         "  int ne0; int ne1; int nr0;\n"
         "  short r2; short r3;\n"
         "};\n"
         "kernel void dsv4_shared_gate_up_swiglu_q8_0_mtl4(\n"
         "    device const mv_args *args      [[buffer(0)]],\n"
         "    device const char    *src0_gate [[buffer(1)]],\n"
         "    device const char    *src0_up   [[buffer(2)]],\n"
         "    device const char    *src1      [[buffer(3)]],\n"
         "    device       char    *dst_gate  [[buffer(4)]],\n"
         "    device       char    *dst_up    [[buffer(5)]],\n"
         "    device       char    *dst_mid   [[buffer(6)]],\n"
         "    device const float   *clamp_val [[buffer(7)]],\n"
         "    threadgroup  char    *shmem     [[threadgroup(0)]],\n"
         "    uint3   tgpig [[threadgroup_position_in_grid]],\n"
         "    ushort  tiisg [[thread_index_in_simdgroup]],\n"
         "    ushort  sgitg [[simdgroup_index_in_threadgroup]]) {\n"
         "  constexpr short NR0 = 2;\n"
         "  const short NSG = FC_mul_mv_nsg;\n"
         "  constexpr short NW = N_SIMDWIDTH;\n"
         "  constexpr short NQ = 8;\n"
         "  const int nb = args->ne00 / QK8_0;\n"
         "  const int r0 = tgpig.x * NR0;\n"
         "  const int r1 = tgpig.y;\n"
         "  const int im = tgpig.z;\n"
         "  const uint i12 = im %% args->ne12;\n"
         "  const uint i13 = im / args->ne12;\n"
         "  const ulong offset1 = r1*args->nb11 + i12*args->nb12 + i13*args->nb13;\n"
         "  device const float *y = (device const float *)(src1 + offset1);\n"
         "  device const block_q8_0 *ag[NR0];\n"
         "  device const block_q8_0 *au[NR0];\n"
         "  for (short row = 0; row < NR0; ++row) {\n"
         "    const ulong offset0 = (r0 + row)*args->nb01\n"
         "                       + (i12/args->r2)*args->nb02\n"
         "                       + (i13/args->r3)*args->nb03;\n"
         "    ag[row] = (device const block_q8_0 *)((device const char *)src0_gate + offset0);\n"
         "    au[row] = (device const block_q8_0 *)((device const char *)src0_up   + offset0);\n"
         "  }\n"
         "  float sumg[NR0] = {0.0f};\n"
         "  float sumu[NR0] = {0.0f};\n"
         "  const short ix = tiisg / (NW / NQ);\n"
         "  const short il = tiisg %% (NW / NQ);\n"
         "  const int ib0 = sgitg * NQ + ix;\n"
         "  float yl[NQ];\n"
         "  device const float *yb = y + ib0*QK8_0 + il*NQ;\n"
         "  for (int ib = ib0; ib < nb; ib += NSG*NQ) {\n"
         "    for (short i = 0; i < NQ; ++i) yl[i] = yb[i];\n"
         "    for (short row = 0; row < NR0; ++row) {\n"
         "      device const int8_t *qg = ag[row][ib].qs + il*NQ;\n"
         "      device const int8_t *qu = au[row][ib].qs + il*NQ;\n"
         "      float sg = 0.0f, su = 0.0f;\n"
         "      for (short i = 0; i < NQ; ++i) {\n"
         "        sg += (float)qg[i] * yl[i];\n"
         "        su += (float)qu[i] * yl[i];\n"
         "      }\n"
         "      sumg[row] += sg * (float)ag[row][ib].d;\n"
         "      sumu[row] += su * (float)au[row][ib].d;\n"
         "    }\n"
         "    yb += NSG*NQ*QK8_0;\n"
         "  }\n"
         "  threadgroup float *shmem_f32 = (threadgroup float *)shmem;\n"
         "  threadgroup float *sh_gate[NR0];\n"
         "  threadgroup float *sh_up[NR0];\n"
         "  for (short row = 0; row < NR0; ++row) {\n"
         "    sh_gate[row] = shmem_f32 + NW * row;\n"
         "    sh_up[row]   = shmem_f32 + NW * (NR0 + row);\n"
         "    if (sgitg == 0) { sh_gate[row][tiisg] = 0.0f; sh_up[row][tiisg] = 0.0f; }\n"
         "    sumg[row] = simd_sum(sumg[row]);\n"
         "    sumu[row] = simd_sum(sumu[row]);\n"
         "  }\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  for (short row = 0; row < NR0; ++row) {\n"
         "    if (tiisg == 0) { sh_gate[row][sgitg] = sumg[row]; sh_up[row][sgitg] = sumu[row]; }\n"
         "  }\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  device float *gate_f32 = (device float *)dst_gate\n"
         "    + (ulong)im*args->ne0*args->ne1 + (ulong)r1*args->ne0;\n"
         "  device float *up_f32 = (device float *)dst_up\n"
         "    + (ulong)im*args->ne0*args->ne1 + (ulong)r1*args->ne0;\n"
         "  device float *mid_f32 = (device float *)dst_mid\n"
         "    + (ulong)im*args->ne0*args->ne1 + (ulong)r1*args->ne0;\n"
         "  for (short row = 0; row < NR0 && r0 + row < args->ne01; ++row) {\n"
         "    const float gate = simd_sum(sh_gate[row][tiisg]);\n"
         "    const float up   = simd_sum(sh_up[row][tiisg]);\n"
         "    if (tiisg == 0 && sgitg == 0) {\n"
         "      const int out_row = r0 + row;\n"
         "      gate_f32[out_row] = gate;\n"
         "      up_f32[out_row] = up;\n"
         "      float g = gate, u = up;\n"
         "      const float cv = *clamp_val;\n"
         "      if (cv > 1.0e-6f) { g = min(g, cv); u = clamp(u, -cv, cv); }\n"
         "      const float silu = g / (1.0f + exp(-g));\n"
         "      mid_f32[out_row] = silu * u;\n"
         "    }\n"
         "  }\n"
         "}\n"];

    const ds4_mtl4_fc_short fcs[] = {{nsg_value, 600}};
    return ds4_mtl4_build_kernel_pipeline(
        source,
        @"ds4_dsv4_shared_gate_up_swiglu_q8_0_mtl4",
        @"dsv4_shared_gate_up_swiglu_q8_0_mtl4",
        1024,
        fcs, 1);
}

static id<MTLComputePipelineState> g_dsv4_shared_gate_up_swiglu_q8_0_nsg4_mtl4_pipeline;
static int g_dsv4_shared_gate_up_swiglu_q8_0_nsg4_mtl4_init_attempted;
static int g_dsv4_shared_gate_up_swiglu_q8_0_nsg4_mtl4_init_ok;

static int ds4_dsv4_shared_gate_up_swiglu_q8_0_nsg4_mtl4_pipeline_init(void) {
    if (g_dsv4_shared_gate_up_swiglu_q8_0_nsg4_mtl4_init_attempted) return g_dsv4_shared_gate_up_swiglu_q8_0_nsg4_mtl4_init_ok;
    g_dsv4_shared_gate_up_swiglu_q8_0_nsg4_mtl4_init_attempted = 1;
    g_dsv4_shared_gate_up_swiglu_q8_0_nsg4_mtl4_pipeline = ds4_dsv4_shared_gate_up_swiglu_q8_0_build_pipeline(4);
    g_dsv4_shared_gate_up_swiglu_q8_0_nsg4_mtl4_init_ok = (g_dsv4_shared_gate_up_swiglu_q8_0_nsg4_mtl4_pipeline != nil) ? 1 : 0;
    return g_dsv4_shared_gate_up_swiglu_q8_0_nsg4_mtl4_init_ok;
}

int ds4_gpu_mtl4_dsv4_shared_gate_up_swiglu_q8_0_canary(uint32_t M, uint32_t N, float clamp_value) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_dsv4_shared_gate_up_swiglu_q8_0_nsg4_mtl4_pipeline_init()) return 0;
    if (M == 0 || N == 0 || (M % 2) != 0 || (N % 32) != 0) {
        fprintf(stderr, "ds4: shared_gate_up_swiglu canary needs M%%2==0 and N%%32==0 (got M=%u N=%u)\n", M, N);
        return 0;
    }

    /* Two Q8_0 matrices: gate weights, up weights. One FP32 vector. Three FP32 outputs. */
    float *host_gate_w = (float *)calloc((uint64_t)M * N, sizeof(float));
    float *host_up_w = (float *)calloc((uint64_t)M * N, sizeof(float));
    float *host_vec = (float *)calloc(N, sizeof(float));
    float *host_dst_gate = (float *)calloc(M, sizeof(float));
    float *host_dst_up = (float *)calloc(M, sizeof(float));
    float *host_dst_mid = (float *)calloc(M, sizeof(float));
    float *expected_gate = (float *)calloc(M, sizeof(float));
    float *expected_up = (float *)calloc(M, sizeof(float));
    float *expected_mid = (float *)calloc(M, sizeof(float));
    const uint32_t n_blocks_per_row = N / 32u;
    const uint64_t q8_row_bytes = (uint64_t)n_blocks_per_row * 34u;
    uint8_t *host_gate_q8 = (uint8_t *)calloc((uint64_t)M * q8_row_bytes, 1);
    uint8_t *host_up_q8 = (uint8_t *)calloc((uint64_t)M * q8_row_bytes, 1);
    if (!host_gate_w || !host_up_w || !host_vec || !host_dst_gate || !host_dst_up || !host_dst_mid ||
        !expected_gate || !expected_up || !expected_mid || !host_gate_q8 || !host_up_q8) {
        free(host_gate_w); free(host_up_w); free(host_vec);
        free(host_dst_gate); free(host_dst_up); free(host_dst_mid);
        free(expected_gate); free(expected_up); free(expected_mid);
        free(host_gate_q8); free(host_up_q8);
        return 0;
    }
    for (uint32_t r = 0; r < M; r++) {
        for (uint32_t c = 0; c < N; c++) {
            host_gate_w[(uint64_t)r * N + c] = (float)((int)((r * 13 + c * 7) % 250) - 125);
            host_up_w[(uint64_t)r * N + c]   = (float)((int)((r * 17 + c * 11) % 250) - 125);
        }
        ds4_quantize_q8_0_row(host_gate_w + (uint64_t)r * N, N, host_gate_q8 + (uint64_t)r * q8_row_bytes);
        ds4_quantize_q8_0_row(host_up_w   + (uint64_t)r * N, N, host_up_q8   + (uint64_t)r * q8_row_bytes);
        /* Dequantize back for reference */
        for (uint32_t b = 0; b < n_blocks_per_row; b++) {
            for (int which = 0; which < 2; which++) {
                uint8_t *blocks = (which == 0) ? host_gate_q8 : host_up_q8;
                float *out = (which == 0) ? host_gate_w : host_up_w;
                const uint8_t *blk = blocks + (uint64_t)r * q8_row_bytes + (uint64_t)b * 34u;
                _Float16 d_half;
                memcpy(&d_half, blk, sizeof(d_half));
                const float d = (float)d_half;
                const int8_t *qs = (const int8_t *)(blk + 2);
                for (uint32_t i = 0; i < 32; i++) {
                    out[(uint64_t)r * N + (uint64_t)b * 32u + i] = (float)qs[i] * d;
                }
            }
        }
    }
    for (uint32_t c = 0; c < N; c++) host_vec[c] = ((float)((int)(c % 7)) - 3.0f) * 0.5f;
    /* CPU reference: gate, up, then SwiGLU mid */
    for (uint32_t r = 0; r < M; r++) {
        double accg = 0.0, accu = 0.0;
        for (uint32_t c = 0; c < N; c++) {
            accg += (double)host_gate_w[(uint64_t)r * N + c] * (double)host_vec[c];
            accu += (double)host_up_w[(uint64_t)r * N + c]   * (double)host_vec[c];
        }
        expected_gate[r] = (float)accg;
        expected_up[r]   = (float)accu;
        float g = expected_gate[r], u = expected_up[r];
        if (clamp_value > 1.0e-6f) {
            g = (g < clamp_value) ? g : clamp_value;
            u = (u < -clamp_value) ? -clamp_value : ((u > clamp_value) ? clamp_value : u);
        }
        const float silu = g / (1.0f + expf(-g));
        expected_mid[r] = silu * u;
    }

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:128 options:MTLResourceStorageModeShared];
        id<MTLBuffer> gateQBuf = [g_device newBufferWithBytes:host_gate_q8 length:(uint64_t)M*q8_row_bytes options:MTLResourceStorageModeShared];
        id<MTLBuffer> upQBuf = [g_device newBufferWithBytes:host_up_q8 length:(uint64_t)M*q8_row_bytes options:MTLResourceStorageModeShared];
        id<MTLBuffer> vecBuf = [g_device newBufferWithBytes:host_vec length:N*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> dstGateBuf = [g_device newBufferWithLength:M*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> dstUpBuf = [g_device newBufferWithLength:M*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> dstMidBuf = [g_device newBufferWithLength:M*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> clampBuf = [g_device newBufferWithBytes:&clamp_value length:sizeof(float) options:MTLResourceStorageModeShared];

        struct {
            int ne00, ne01, ne02;
            uint64_t nb00, nb01, nb02, nb03;
            int ne10, ne11, ne12;
            uint64_t nb10, nb11, nb12, nb13;
            int ne0, ne1, nr0;
            int16_t r2, r3;
        } args;
        memset(&args, 0, sizeof(args));
        args.ne00 = N; args.ne01 = M; args.ne02 = 1;
        args.nb00 = 1;
        args.nb01 = q8_row_bytes;
        args.nb02 = (uint64_t)M * q8_row_bytes;
        args.nb03 = (uint64_t)M * q8_row_bytes;
        args.ne10 = N; args.ne11 = 1; args.ne12 = 1;
        args.nb10 = sizeof(float);
        args.nb11 = (uint64_t)N * sizeof(float);
        args.nb12 = (uint64_t)N * sizeof(float);
        args.nb13 = (uint64_t)N * sizeof(float);
        args.ne0 = M; args.ne1 = 1; args.nr0 = 2;
        args.r2 = 1; args.r3 = 1;
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 12;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[8] = {
                (id)argsBuf, (id)gateQBuf, (id)upQBuf, (id)vecBuf,
                (id)dstGateBuf, (id)dstUpBuf, (id)dstMidBuf, (id)clampBuf
            };
            [residency addAllocations:allocs count:8];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(8);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:gateQBuf.gpuAddress atIndex:1];
                [argTable setAddress:upQBuf.gpuAddress atIndex:2];
                [argTable setAddress:vecBuf.gpuAddress atIndex:3];
                [argTable setAddress:dstGateBuf.gpuAddress atIndex:4];
                [argTable setAddress:dstUpBuf.gpuAddress atIndex:5];
                [argTable setAddress:dstMidBuf.gpuAddress atIndex:6];
                [argTable setAddress:clampBuf.gpuAddress atIndex:7];

                NSUInteger nth = 4u * 32u;
                /* shmem: NR0 × 2 (gate + up) × NW floats = 4 × 32 = 128 floats */
                NSUInteger shmem_bytes = 2u * 2u * 32u * sizeof(float);

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_dsv4_shared_gate_up_swiglu_q8_0_nsg4_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc setThreadgroupMemoryLength:shmem_bytes atIndex:0];
                [enc dispatchThreadgroups:MTLSizeMake(M / 2, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) { (void)fb; dispatch_semaphore_signal(sem); }];
                id<MTL4CommandBuffer> bufs[1] = {cb};
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_dst_gate, dstGateBuf.contents, M * sizeof(float));
                    memcpy(host_dst_up, dstUpBuf.contents, M * sizeof(float));
                    memcpy(host_dst_mid, dstMidBuf.contents, M * sizeof(float));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 8);
            }
        }
    }
    if (!rc) goto cleanup;

    int gate_mismatch = 0, up_mismatch = 0, mid_mismatch = 0;
    double max_rel_gate = 0.0, max_rel_up = 0.0, max_rel_mid = 0.0;
    for (uint32_t r = 0; r < M; r++) {
        double d, rel;
        d = fabs((double)(host_dst_gate[r] - expected_gate[r]));
        rel = d / (fabs((double)expected_gate[r]) + 1e-3);
        if (rel > max_rel_gate) max_rel_gate = rel;
        if (rel > 5.0e-3) gate_mismatch++;
        d = fabs((double)(host_dst_up[r] - expected_up[r]));
        rel = d / (fabs((double)expected_up[r]) + 1e-3);
        if (rel > max_rel_up) max_rel_up = rel;
        if (rel > 5.0e-3) up_mismatch++;
        d = fabs((double)(host_dst_mid[r] - expected_mid[r]));
        rel = d / (fabs((double)expected_mid[r]) + 1e-3);
        if (rel > max_rel_mid) max_rel_mid = rel;
        if (rel > 5.0e-3) mid_mismatch++;
    }
    fprintf(stderr,
        "ds4: dsv4_shared_gate_up_swiglu_q8_0 MTL4 canary M=%u N=%u clamp=%.2f "
        "gate_mismatch=%d (max_rel=%.4e) up_mismatch=%d (max_rel=%.4e) mid_mismatch=%d (max_rel=%.4e)\n",
        M, N, (double)clamp_value,
        gate_mismatch, max_rel_gate, up_mismatch, max_rel_up, mid_mismatch, max_rel_mid);

cleanup:
    free(host_gate_w); free(host_up_w); free(host_vec);
    free(host_dst_gate); free(host_dst_up); free(host_dst_mid);
    free(expected_gate); free(expected_up); free(expected_mid);
    free(host_gate_q8); free(host_up_q8);
    return rc && (gate_mismatch == 0 && up_mismatch == 0 && mid_mismatch == 0) ? 1 : 0;
}

/* ============================================================ */
/* dsv4_q8_hc_expand4_q8_0 MTL4 port (silv 2026-05-27 #725)     */
/* ============================================================ */
/* Q8_0 matvec fused with 4-channel HC expansion. Hardcoded n_hc=4
 * and n_tokens=1 (decode-time path). Per output row d:
 *   1. Compute block_v = <Q8_0 weight row d, input vec>
 *   2. Read 4 residual values r0..r3 from residual[d, *]
 *   3. For each hc-channel c in [0,4): dst[d, c] =
 *        block_v * post[c] + sum_k comb[c, k] * rk
 *
 * 9 buffers: args_mv, args_hc, weight (Q8_0), input (FP32),
 * block_out (FP32), residual (FP32), post (FP32 × 4),
 * comb (FP32 × 16), dst (FP32 × M × 4).
 *
 * Uses FC_mul_mv_nsg via the established pattern. NR0=2, NSG=4. */

static id<MTLComputePipelineState> ds4_dsv4_q8_hc_expand4_q8_0_build_pipeline(short nsg_value) {
    NSString *source = [NSString stringWithFormat:
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "#define FC_MUL_MV 600\n"
         "#define N_SIMDWIDTH 32\n"
         "#define QK8_0 32\n"
         "constant short FC_mul_mv_nsg [[function_constant(FC_MUL_MV + 0)]];\n"
         "struct block_q8_0 { half d; int8_t qs[QK8_0]; };\n"
         "struct mv_args {\n"
         "  int ne00; int ne01; int ne02;\n"
         "  ulong nb00; ulong nb01; ulong nb02; ulong nb03;\n"
         "  int ne10; int ne11; int ne12;\n"
         "  ulong nb10; ulong nb11; ulong nb12; ulong nb13;\n"
         "  int ne0; int ne1; int nr0;\n"
         "  short r2; short r3;\n"
         "};\n"
         "struct hc_args {\n"
         "  long n_embd; long n_hc; long n_tokens;\n"
         "  ulong nb_block0; ulong nb_block1;\n"
         "  ulong nb_add0; ulong nb_add1;\n"
         "  ulong nb_res0; ulong nb_res1; ulong nb_res2;\n"
         "  ulong nb_post0; ulong nb_post1;\n"
         "  ulong nb_comb0; ulong nb_comb1; ulong nb_comb2;\n"
         "  ulong nb0; ulong nb1;\n"
         "};\n"
         "kernel void dsv4_q8_hc_expand4_q8_0_mtl4(\n"
         "    device const mv_args *mv        [[buffer(0)]],\n"
         "    device const hc_args *hc        [[buffer(1)]],\n"
         "    device const char    *weight    [[buffer(2)]],\n"
         "    device const char    *input     [[buffer(3)]],\n"
         "    device       char    *block_out [[buffer(4)]],\n"
         "    device const char    *residual  [[buffer(5)]],\n"
         "    device const char    *post      [[buffer(6)]],\n"
         "    device const char    *comb      [[buffer(7)]],\n"
         "    device       char    *dst       [[buffer(8)]],\n"
         "    threadgroup  char    *shmem     [[threadgroup(0)]],\n"
         "    uint3   tgpig [[threadgroup_position_in_grid]],\n"
         "    ushort  tiisg [[thread_index_in_simdgroup]],\n"
         "    ushort  sgitg [[simdgroup_index_in_threadgroup]]) {\n"
         "  if (hc->n_hc != 4 || hc->n_tokens != 1) return;\n"
         "  constexpr short NR0 = 2;\n"
         "  const short NSG = FC_mul_mv_nsg;\n"
         "  constexpr short NW = N_SIMDWIDTH;\n"
         "  constexpr short NQ = 8;\n"
         "  const int nb = mv->ne00 / QK8_0;\n"
         "  const int row0 = tgpig.x * NR0;\n"
         "  const short ix = tiisg / (NW / NQ);\n"
         "  const short il = tiisg %% (NW / NQ);\n"
         "  const int ib0 = sgitg * NQ + ix;\n"
         "  device const float *y = (device const float *)(input);\n"
         "  device const float *yb = y + ib0*QK8_0 + il*NQ;\n"
         "  device const block_q8_0 *ax[NR0];\n"
         "  for (short row = 0; row < NR0; ++row) {\n"
         "    const ulong off0 = (ulong)(row0 + row) * mv->nb01;\n"
         "    ax[row] = (device const block_q8_0 *)(weight + off0);\n"
         "  }\n"
         "  float sumf[NR0] = {0.0f};\n"
         "  float yl[NQ];\n"
         "  for (int ib = ib0; ib < nb; ib += NSG*NQ) {\n"
         "    for (short i = 0; i < NQ; ++i) yl[i] = yb[i];\n"
         "    for (short row = 0; row < NR0; ++row) {\n"
         "      device const int8_t *qs = ax[row][ib].qs + il*NQ;\n"
         "      float sumq = 0.0f;\n"
         "      for (short i = 0; i < NQ; ++i) sumq += (float)qs[i] * yl[i];\n"
         "      sumf[row] += sumq * (float)ax[row][ib].d;\n"
         "    }\n"
         "    yb += NSG*NQ*QK8_0;\n"
         "  }\n"
         "  threadgroup float *shmem_f32[NR0];\n"
         "  for (short row = 0; row < NR0; ++row) {\n"
         "    shmem_f32[row] = (threadgroup float *)shmem + NW * row;\n"
         "    if (sgitg == 0) shmem_f32[row][tiisg] = 0.0f;\n"
         "    sumf[row] = simd_sum(sumf[row]);\n"
         "  }\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  for (short row = 0; row < NR0; ++row) {\n"
         "    if (tiisg == 0) shmem_f32[row][sgitg] = sumf[row];\n"
         "  }\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  for (short row = 0; row < NR0; ++row) {\n"
         "    const int d = row0 + row;\n"
         "    if (d >= mv->ne01) continue;\n"
         "    const float block_v = simd_sum(shmem_f32[row][tiisg]);\n"
         "    if (tiisg == 0 && sgitg == 0) {\n"
         "      *((device float *)(block_out + (ulong)d * sizeof(float))) = block_v;\n"
         "      const float r0v = *((device const float *)(residual + (ulong)d * hc->nb_res0 + 0 * hc->nb_res1));\n"
         "      const float r1v = *((device const float *)(residual + (ulong)d * hc->nb_res0 + 1 * hc->nb_res1));\n"
         "      const float r2v = *((device const float *)(residual + (ulong)d * hc->nb_res0 + 2 * hc->nb_res1));\n"
         "      const float r3v = *((device const float *)(residual + (ulong)d * hc->nb_res0 + 3 * hc->nb_res1));\n"
         "      for (long dst_hc = 0; dst_hc < 4; ++dst_hc) {\n"
         "        float acc = block_v * *((device const float *)(post + dst_hc * hc->nb_post0));\n"
         "        acc += *((device const float *)(comb + dst_hc * hc->nb_comb0 + 0 * hc->nb_comb1)) * r0v;\n"
         "        acc += *((device const float *)(comb + dst_hc * hc->nb_comb0 + 1 * hc->nb_comb1)) * r1v;\n"
         "        acc += *((device const float *)(comb + dst_hc * hc->nb_comb0 + 2 * hc->nb_comb1)) * r2v;\n"
         "        acc += *((device const float *)(comb + dst_hc * hc->nb_comb0 + 3 * hc->nb_comb1)) * r3v;\n"
         "        *((device float *)(dst + (ulong)d * hc->nb0 + dst_hc * hc->nb1)) = acc;\n"
         "      }\n"
         "    }\n"
         "  }\n"
         "}\n"];

    const ds4_mtl4_fc_short fcs[] = {{nsg_value, 600}};
    return ds4_mtl4_build_kernel_pipeline(
        source,
        @"ds4_dsv4_q8_hc_expand4_q8_0_mtl4",
        @"dsv4_q8_hc_expand4_q8_0_mtl4",
        1024,
        fcs, 1);
}

static id<MTLComputePipelineState> g_dsv4_q8_hc_expand4_q8_0_nsg4_mtl4_pipeline;
static int g_dsv4_q8_hc_expand4_q8_0_nsg4_mtl4_init_attempted;
static int g_dsv4_q8_hc_expand4_q8_0_nsg4_mtl4_init_ok;

static int ds4_dsv4_q8_hc_expand4_q8_0_nsg4_mtl4_pipeline_init(void) {
    if (g_dsv4_q8_hc_expand4_q8_0_nsg4_mtl4_init_attempted) return g_dsv4_q8_hc_expand4_q8_0_nsg4_mtl4_init_ok;
    g_dsv4_q8_hc_expand4_q8_0_nsg4_mtl4_init_attempted = 1;
    g_dsv4_q8_hc_expand4_q8_0_nsg4_mtl4_pipeline = ds4_dsv4_q8_hc_expand4_q8_0_build_pipeline(4);
    g_dsv4_q8_hc_expand4_q8_0_nsg4_mtl4_init_ok = (g_dsv4_q8_hc_expand4_q8_0_nsg4_mtl4_pipeline != nil) ? 1 : 0;
    return g_dsv4_q8_hc_expand4_q8_0_nsg4_mtl4_init_ok;
}

int ds4_gpu_mtl4_dsv4_q8_hc_expand4_q8_0_canary(uint32_t M, uint32_t N) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_dsv4_q8_hc_expand4_q8_0_nsg4_mtl4_pipeline_init()) return 0;
    if (M == 0 || N == 0 || (M % 2) != 0 || (N % 32) != 0) {
        fprintf(stderr, "ds4: q8_hc_expand4 canary needs M%%2==0 and N%%32==0 (got M=%u N=%u)\n", M, N);
        return 0;
    }

    float *host_w = (float *)calloc((uint64_t)M * N, sizeof(float));
    float *host_input = (float *)calloc(N, sizeof(float));
    float *host_block_out = (float *)calloc(M, sizeof(float));
    float *host_residual = (float *)calloc((uint64_t)M * 4, sizeof(float));
    float host_post[4] = {0.5f, 0.25f, 0.125f, 0.0625f};
    float host_comb[16];
    for (int i = 0; i < 16; i++) host_comb[i] = 0.1f * (float)(i % 5);
    float *host_dst = (float *)calloc((uint64_t)M * 4, sizeof(float));
    float *expected_block = (float *)calloc(M, sizeof(float));
    float *expected_dst = (float *)calloc((uint64_t)M * 4, sizeof(float));
    const uint32_t n_blocks_per_row = N / 32u;
    const uint64_t q8_row_bytes = (uint64_t)n_blocks_per_row * 34u;
    uint8_t *host_q8 = (uint8_t *)calloc((uint64_t)M * q8_row_bytes, 1);
    if (!host_w || !host_input || !host_block_out || !host_residual || !host_dst ||
        !expected_block || !expected_dst || !host_q8) {
        free(host_w); free(host_input); free(host_block_out); free(host_residual);
        free(host_dst); free(expected_block); free(expected_dst); free(host_q8);
        return 0;
    }
    for (uint32_t r = 0; r < M; r++) {
        for (uint32_t c = 0; c < N; c++) {
            host_w[(uint64_t)r * N + c] = (float)((int)((r * 13 + c * 7) % 250) - 125);
        }
        ds4_quantize_q8_0_row(host_w + (uint64_t)r * N, N, host_q8 + (uint64_t)r * q8_row_bytes);
        for (uint32_t b = 0; b < n_blocks_per_row; b++) {
            const uint8_t *blk = host_q8 + (uint64_t)r * q8_row_bytes + (uint64_t)b * 34u;
            _Float16 d_half;
            memcpy(&d_half, blk, sizeof(d_half));
            const float d = (float)d_half;
            const int8_t *qs = (const int8_t *)(blk + 2);
            for (uint32_t i = 0; i < 32; i++) {
                host_w[(uint64_t)r * N + (uint64_t)b * 32u + i] = (float)qs[i] * d;
            }
        }
        for (int c = 0; c < 4; c++) {
            host_residual[(uint64_t)r * 4 + c] = 0.1f * (float)((int)r + c);
        }
    }
    for (uint32_t c = 0; c < N; c++) host_input[c] = ((float)((int)(c % 7)) - 3.0f) * 0.5f;
    for (uint32_t r = 0; r < M; r++) {
        double acc = 0.0;
        for (uint32_t c = 0; c < N; c++) acc += (double)host_w[(uint64_t)r * N + c] * (double)host_input[c];
        const float block_v = (float)acc;
        expected_block[r] = block_v;
        for (int dst_hc = 0; dst_hc < 4; dst_hc++) {
            float v = block_v * host_post[dst_hc];
            for (int k = 0; k < 4; k++) v += host_comb[dst_hc * 4 + k] * host_residual[(uint64_t)r * 4 + k];
            expected_dst[(uint64_t)r * 4 + dst_hc] = v;
        }
    }

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> mvBuf = [g_device newBufferWithLength:128 options:MTLResourceStorageModeShared];
        id<MTLBuffer> hcBuf = [g_device newBufferWithLength:128 options:MTLResourceStorageModeShared];
        id<MTLBuffer> wBuf = [g_device newBufferWithBytes:host_q8 length:(uint64_t)M*q8_row_bytes options:MTLResourceStorageModeShared];
        id<MTLBuffer> inBuf = [g_device newBufferWithBytes:host_input length:N*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> blockOutBuf = [g_device newBufferWithLength:M*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> resBuf = [g_device newBufferWithBytes:host_residual length:(uint64_t)M*4*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> postBuf = [g_device newBufferWithBytes:host_post length:4*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> combBuf = [g_device newBufferWithBytes:host_comb length:16*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> dstBuf = [g_device newBufferWithLength:(uint64_t)M*4*sizeof(float) options:MTLResourceStorageModeShared];

        struct {
            int ne00, ne01, ne02;
            uint64_t nb00, nb01, nb02, nb03;
            int ne10, ne11, ne12;
            uint64_t nb10, nb11, nb12, nb13;
            int ne0, ne1, nr0;
            int16_t r2, r3;
        } mv;
        memset(&mv, 0, sizeof(mv));
        mv.ne00 = N; mv.ne01 = M; mv.ne02 = 1;
        mv.nb00 = 1; mv.nb01 = q8_row_bytes;
        mv.nb02 = (uint64_t)M * q8_row_bytes; mv.nb03 = mv.nb02;
        mv.ne10 = N; mv.ne11 = 1; mv.ne12 = 1;
        mv.nb10 = sizeof(float); mv.nb11 = (uint64_t)N * sizeof(float);
        mv.nb12 = mv.nb11; mv.nb13 = mv.nb11;
        mv.ne0 = M; mv.ne1 = 1; mv.nr0 = 2; mv.r2 = 1; mv.r3 = 1;
        memcpy(mvBuf.contents, &mv, sizeof(mv));

        struct {
            int64_t n_embd, n_hc, n_tokens;
            uint64_t nb_block0, nb_block1;
            uint64_t nb_add0, nb_add1;
            uint64_t nb_res0, nb_res1, nb_res2;
            uint64_t nb_post0, nb_post1;
            uint64_t nb_comb0, nb_comb1, nb_comb2;
            uint64_t nb0, nb1;
        } hc;
        memset(&hc, 0, sizeof(hc));
        hc.n_embd = M; hc.n_hc = 4; hc.n_tokens = 1;
        hc.nb_block0 = sizeof(float); hc.nb_block1 = (uint64_t)M * sizeof(float);
        /* residual layout: [M, 4] row-major — nb_res0 = 4*sizeof(float), nb_res1 = sizeof(float) */
        hc.nb_res0 = 4 * sizeof(float); hc.nb_res1 = sizeof(float); hc.nb_res2 = 0;
        /* post layout: [4] — stride sizeof(float) */
        hc.nb_post0 = sizeof(float); hc.nb_post1 = 0;
        /* comb layout: [4, 4] row-major — nb_comb0 = 4*sizeof(float), nb_comb1 = sizeof(float) */
        hc.nb_comb0 = 4 * sizeof(float); hc.nb_comb1 = sizeof(float); hc.nb_comb2 = 0;
        /* dst layout: [M, 4] row-major — nb0 = 4*sizeof(float), nb1 = sizeof(float) */
        hc.nb0 = 4 * sizeof(float); hc.nb1 = sizeof(float);
        memcpy(hcBuf.contents, &hc, sizeof(hc));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 16;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[9] = {
                (id)mvBuf, (id)hcBuf, (id)wBuf, (id)inBuf,
                (id)blockOutBuf, (id)resBuf, (id)postBuf, (id)combBuf, (id)dstBuf
            };
            [residency addAllocations:allocs count:9];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(16);
            if (argTable) {
                [argTable setAddress:mvBuf.gpuAddress atIndex:0];
                [argTable setAddress:hcBuf.gpuAddress atIndex:1];
                [argTable setAddress:wBuf.gpuAddress atIndex:2];
                [argTable setAddress:inBuf.gpuAddress atIndex:3];
                [argTable setAddress:blockOutBuf.gpuAddress atIndex:4];
                [argTable setAddress:resBuf.gpuAddress atIndex:5];
                [argTable setAddress:postBuf.gpuAddress atIndex:6];
                [argTable setAddress:combBuf.gpuAddress atIndex:7];
                [argTable setAddress:dstBuf.gpuAddress atIndex:8];

                NSUInteger nth = 4u * 32u;
                NSUInteger shmem_bytes = 2u * 32u * sizeof(float);

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_dsv4_q8_hc_expand4_q8_0_nsg4_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc setThreadgroupMemoryLength:shmem_bytes atIndex:0];
                [enc dispatchThreadgroups:MTLSizeMake(M / 2, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) { (void)fb; dispatch_semaphore_signal(sem); }];
                id<MTL4CommandBuffer> bufs[1] = {cb};
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_block_out, blockOutBuf.contents, M * sizeof(float));
                    memcpy(host_dst, dstBuf.contents, (uint64_t)M * 4 * sizeof(float));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 16);
            }
        }
    }
    if (!rc) goto cleanup;

    int block_mismatch = 0, dst_mismatch = 0;
    double max_rel_block = 0.0, max_rel_dst = 0.0;
    for (uint32_t r = 0; r < M; r++) {
        double d = fabs((double)(host_block_out[r] - expected_block[r]));
        double rel = d / (fabs((double)expected_block[r]) + 1e-3);
        if (rel > max_rel_block) max_rel_block = rel;
        if (rel > 5.0e-3) block_mismatch++;
        for (int c = 0; c < 4; c++) {
            d = fabs((double)(host_dst[(uint64_t)r * 4 + c] - expected_dst[(uint64_t)r * 4 + c]));
            rel = d / (fabs((double)expected_dst[(uint64_t)r * 4 + c]) + 1e-3);
            if (rel > max_rel_dst) max_rel_dst = rel;
            if (rel > 5.0e-3) dst_mismatch++;
        }
    }
    fprintf(stderr,
        "ds4: dsv4_q8_hc_expand4_q8_0 MTL4 canary M=%u N=%u "
        "block_mismatch=%d (max_rel=%.4e) dst_mismatch=%d (max_rel=%.4e)\n",
        M, N,
        block_mismatch, max_rel_block, dst_mismatch, max_rel_dst);

cleanup:
    free(host_w); free(host_input); free(host_block_out); free(host_residual);
    free(host_dst); free(expected_block); free(expected_dst); free(host_q8);
    return rc && (block_mismatch == 0 && dst_mismatch == 0) ? 1 : 0;
}

/* ============================================================ */
/* mul_mv_f16_f32 MTL4 port (silv 2026-05-28 #727)              */
/* ============================================================ */
/* Half-precision matrix × FP32 vector → FP32 output. Twin of #722
 * mul_mv_f32_f32; only src0 element type changes (half instead of
 * float). Used for FP16-stored attention/projection weights.
 * NR0=4 hardcoded; NSG=4 via FC. Uses the refactored
 * ds4_mtl4_build_kernel_pipeline helper. */

static id<MTLComputePipelineState> ds4_mul_mv_f16_f32_build_pipeline(short nsg_value) {
    NSString *source = [NSString stringWithFormat:
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "#define FC_MUL_MV 600\n"
         "#define N_SIMDWIDTH 32\n"
         "constant short FC_mul_mv_nsg [[function_constant(FC_MUL_MV + 0)]];\n"
         "struct mv_args {\n"
         "  int ne00; int ne01; int ne02;\n"
         "  ulong nb00; ulong nb01; ulong nb02; ulong nb03;\n"
         "  int ne10; int ne11; int ne12;\n"
         "  ulong nb10; ulong nb11; ulong nb12; ulong nb13;\n"
         "  int ne0; int ne1; int nr0;\n"
         "  short r2; short r3;\n"
         "};\n"
         "static inline void reduce_write(\n"
         "    device float *dst_f32,\n"
         "    thread float *sumf,\n"
         "    const int r0,\n"
         "    const int ne01,\n"
         "    ushort tiisg,\n"
         "    ushort sgitg,\n"
         "    threadgroup char *shmem) {\n"
         "  constexpr short NW = N_SIMDWIDTH;\n"
         "  constexpr short NR0 = 4;\n"
         "  threadgroup float *shmem_f32[NR0];\n"
         "  for (short row = 0; row < NR0; ++row) {\n"
         "    shmem_f32[row] = (threadgroup float *)shmem + NW*row;\n"
         "    if (sgitg == 0) shmem_f32[row][tiisg] = 0.0f;\n"
         "    sumf[row] = simd_sum(sumf[row]);\n"
         "  }\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  for (short row = 0; row < NR0; ++row) {\n"
         "    if (tiisg == 0) shmem_f32[row][sgitg] = sumf[row];\n"
         "  }\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  for (short row = 0; row < NR0 && r0 + row < ne01; ++row) {\n"
         "    float tot = simd_sum(shmem_f32[row][tiisg]);\n"
         "    if (tiisg == 0 && sgitg == 0) dst_f32[r0 + row] = tot;\n"
         "  }\n"
         "}\n"
         "kernel void mul_mv_f16_f32_mtl4(\n"
         "    device const mv_args *args [[buffer(0)]],\n"
         "    device const char    *src0 [[buffer(1)]],\n"
         "    device const char    *src1 [[buffer(2)]],\n"
         "    device       char    *dst  [[buffer(3)]],\n"
         "    threadgroup  char    *shmem [[threadgroup(0)]],\n"
         "    uint3   tgpig [[threadgroup_position_in_grid]],\n"
         "    ushort  tiisg [[thread_index_in_simdgroup]],\n"
         "    ushort  sgitg [[simdgroup_index_in_threadgroup]]) {\n"
         "  constexpr short NR0 = 4;\n"
         "  const short NSG = FC_mul_mv_nsg;\n"
         "  constexpr short NW = N_SIMDWIDTH;\n"
         "  constexpr short NB = 32;\n"
         "  constexpr short NF = 8;\n"
         "  const int nb = args->ne00 / NB;\n"
         "  const int r0 = tgpig.x * NR0;\n"
         "  const int r1 = tgpig.y;\n"
         "  const int im = tgpig.z;\n"
         "  const uint i12 = im %% args->ne12;\n"
         "  const uint i13 = im / args->ne12;\n"
         "  const ulong offset1 = r1*args->nb11 + i12*args->nb12 + i13*args->nb13;\n"
         "  device const float *y = (device const float *)(src1 + offset1);\n"
         "  device const half *ax[NR0];\n"
         "  for (short row = 0; row < NR0; ++row) {\n"
         "    const ulong offset0 = (r0 + row)*args->nb01\n"
         "                       + (i12/args->r2)*args->nb02\n"
         "                       + (i13/args->r3)*args->nb03;\n"
         "    ax[row] = (device const half *)((device const char *)src0 + offset0);\n"
         "  }\n"
         "  float sumf[NR0] = {0.0f};\n"
         "  const short ix = tiisg / (NW / NF);\n"
         "  const short il = tiisg %% (NW / NF);\n"
         "  const int ib0 = sgitg * NF + ix;\n"
         "  float yl[NF];\n"
         "  device const float *yb = y + ib0*NB + il*NF;\n"
         "  for (int ib = ib0; ib < nb; ib += NSG*NF) {\n"
         "    for (short i = 0; i < NF; ++i) yl[i] = yb[i];\n"
         "    for (short row = 0; row < NR0; ++row) {\n"
         "      device const half *xb = ax[row] + ib*NB + il*NF;\n"
         "      float sumq = 0.0f;\n"
         "      for (short i = 0; i < NF; ++i) sumq += (float)xb[i] * yl[i];\n"
         "      sumf[row] += sumq;\n"
         "    }\n"
         "    yb += NSG*NF*NW;\n"
         "  }\n"
         "  for (int i = nb*NB + sgitg*NW + tiisg; i < args->ne00; i += NW*NSG) {\n"
         "    for (short row = 0; row < NR0; ++row) sumf[row] += (float)ax[row][i] * y[i];\n"
         "  }\n"
         "  device float *dst_f32 = (device float *)dst\n"
         "    + (ulong)im*args->ne0*args->ne1 + (ulong)r1*args->ne0;\n"
         "  reduce_write(dst_f32, sumf, r0, args->ne01, tiisg, sgitg, shmem);\n"
         "}\n"];

    const ds4_mtl4_fc_short fcs[] = {{nsg_value, 600}};
    return ds4_mtl4_build_kernel_pipeline(
        source,
        @"ds4_mul_mv_f16_f32_mtl4",
        @"mul_mv_f16_f32_mtl4",
        1024,
        fcs, 1);
}

/* ============================================================ */
/* BF16 matrix × FP32 vector → FP32 output. silv 2026-05-28 #796
 * Increment 1: clone of mul_mv_f16_f32_mtl4 with BF16 read path.
 *
 * BF16 is the upper 16 bits of an fp32 representation. The read is
 * `ushort bits` followed by `(uint)bits << 16u` reinterpreted as float —
 * exact, no precision loss in the conversion (BF16 → F32 is a widen, not
 * a quantize). Inner-loop cost: 1 shift + 1 reinterpret per weight,
 * negligible vs the multiply.
 *
 * Engineer-roster notes:
 *   Carmack: minimal diff vs the f16 kernel. Same algorithm, different read.
 *   DJB: no new dispatch infrastructure — same FC slot, same arg table shape.
 *   Knuth: NR0=4, NSG via FC — copied verbatim from the f16 variant.
 *   Pearl: bf16→f32 widen is information-preserving; the kernel is
 *          numerically equivalent to "load f32, multiply" but with 2× memory
 *          bandwidth savings (half-width weight read).
 *
 * Use: non-routed attention Q/K/V/O matvec, embed lookup paths where the
 * weight tensor is BF16 source-exact from the nonrouted pack. Selected by
 * tensor_effective_type() == DS4_TENSOR_BF16 at the dispatch site (#796
 * Increment 2+ wires the actual call sites). */
static id<MTLComputePipelineState> ds4_mul_mv_bf16_f32_build_pipeline(short nsg_value) {
    NSString *source = [NSString stringWithFormat:
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "#define FC_MUL_MV 600\n"
         "#define N_SIMDWIDTH 32\n"
         "constant short FC_mul_mv_nsg [[function_constant(FC_MUL_MV + 0)]];\n"
         "struct mv_args {\n"
         "  int ne00; int ne01; int ne02;\n"
         "  ulong nb00; ulong nb01; ulong nb02; ulong nb03;\n"
         "  int ne10; int ne11; int ne12;\n"
         "  ulong nb10; ulong nb11; ulong nb12; ulong nb13;\n"
         "  int ne0; int ne1; int nr0;\n"
         "  short r2; short r3;\n"
         "};\n"
         "static inline float bf16_to_f32(ushort bits) {\n"
         "  uint f32_bits = (uint)bits << 16u;\n"
         "  return as_type<float>(f32_bits);\n"
         "}\n"
         "static inline void reduce_write(\n"
         "    device float *dst_f32,\n"
         "    thread float *sumf,\n"
         "    const int r0,\n"
         "    const int ne01,\n"
         "    ushort tiisg,\n"
         "    ushort sgitg,\n"
         "    threadgroup char *shmem) {\n"
         "  constexpr short NR0 = 4;\n"
         "  threadgroup float (*shmem_f32)[N_SIMDWIDTH] = (threadgroup float (*)[N_SIMDWIDTH])shmem;\n"
         "  for (short row = 0; row < NR0; ++row) {\n"
         "    if (sgitg == 0) shmem_f32[row][tiisg] = 0.0f;\n"
         "    sumf[row] = simd_sum(sumf[row]);\n"
         "  }\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  for (short row = 0; row < NR0; ++row) {\n"
         "    if (tiisg == 0) shmem_f32[row][sgitg] = sumf[row];\n"
         "  }\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  for (short row = 0; row < NR0 && r0 + row < ne01; ++row) {\n"
         "    float tot = simd_sum(shmem_f32[row][tiisg]);\n"
         "    if (tiisg == 0 && sgitg == 0) dst_f32[r0 + row] = tot;\n"
         "  }\n"
         "}\n"
         "kernel void mul_mv_bf16_f32_mtl4(\n"
         "    device const mv_args *args [[buffer(0)]],\n"
         "    device const char    *src0 [[buffer(1)]],\n"
         "    device const char    *src1 [[buffer(2)]],\n"
         "    device       char    *dst  [[buffer(3)]],\n"
         "    threadgroup  char    *shmem [[threadgroup(0)]],\n"
         "    uint3   tgpig [[threadgroup_position_in_grid]],\n"
         "    ushort  tiisg [[thread_index_in_simdgroup]],\n"
         "    ushort  sgitg [[simdgroup_index_in_threadgroup]]) {\n"
         "  constexpr short NR0 = 4;\n"
         "  const short NSG = FC_mul_mv_nsg;\n"
         "  constexpr short NW = N_SIMDWIDTH;\n"
         "  constexpr short NB = 32;\n"
         "  constexpr short NF = 8;\n"
         "  const int nb = args->ne00 / NB;\n"
         "  const int r0 = tgpig.x * NR0;\n"
         "  const int r1 = tgpig.y;\n"
         "  const int im = tgpig.z;\n"
         "  const uint i12 = im %% args->ne12;\n"
         "  const uint i13 = im / args->ne12;\n"
         "  const ulong offset1 = r1*args->nb11 + i12*args->nb12 + i13*args->nb13;\n"
         "  device const float *y = (device const float *)(src1 + offset1);\n"
         "  device const ushort *ax[NR0];\n"
         "  for (short row = 0; row < NR0; ++row) {\n"
         "    const ulong offset0 = (r0 + row)*args->nb01\n"
         "                       + (i12/args->r2)*args->nb02\n"
         "                       + (i13/args->r3)*args->nb03;\n"
         "    ax[row] = (device const ushort *)((device const char *)src0 + offset0);\n"
         "  }\n"
         "  float sumf[NR0] = {0.0f};\n"
         "  const short ix = tiisg / (NW / NF);\n"
         "  const short il = tiisg %% (NW / NF);\n"
         "  const int ib0 = sgitg * NF + ix;\n"
         "  float yl[NF];\n"
         "  device const float *yb = y + ib0*NB + il*NF;\n"
         "  for (int ib = ib0; ib < nb; ib += NSG*NF) {\n"
         "    for (short i = 0; i < NF; ++i) yl[i] = yb[i];\n"
         "    for (short row = 0; row < NR0; ++row) {\n"
         "      device const ushort *xb = ax[row] + ib*NB + il*NF;\n"
         "      float sumq = 0.0f;\n"
         "      for (short i = 0; i < NF; ++i) sumq += bf16_to_f32(xb[i]) * yl[i];\n"
         "      sumf[row] += sumq;\n"
         "    }\n"
         "    yb += NSG*NF*NW;\n"
         "  }\n"
         "  for (int i = nb*NB + sgitg*NW + tiisg; i < args->ne00; i += NW*NSG) {\n"
         "    for (short row = 0; row < NR0; ++row) sumf[row] += bf16_to_f32(ax[row][i]) * y[i];\n"
         "  }\n"
         "  device float *dst_f32 = (device float *)dst\n"
         "    + (ulong)im*args->ne0*args->ne1 + (ulong)r1*args->ne0;\n"
         "  reduce_write(dst_f32, sumf, r0, args->ne01, tiisg, sgitg, shmem);\n"
         "}\n"];

    const ds4_mtl4_fc_short fcs[] = {{nsg_value, 600}};
    return ds4_mtl4_build_kernel_pipeline(
        source,
        @"ds4_mul_mv_bf16_f32_mtl4",
        @"mul_mv_bf16_f32_mtl4",
        1024,
        fcs, 1);
}

static id<MTLComputePipelineState> g_mul_mv_bf16_f32_nsg4_mtl4_pipeline;
static int g_mul_mv_bf16_f32_nsg4_mtl4_init_attempted;
static int g_mul_mv_bf16_f32_nsg4_mtl4_init_ok;

static int ds4_mul_mv_bf16_f32_nsg4_mtl4_pipeline_init(void) {
    if (g_mul_mv_bf16_f32_nsg4_mtl4_init_attempted) return g_mul_mv_bf16_f32_nsg4_mtl4_init_ok;
    g_mul_mv_bf16_f32_nsg4_mtl4_init_attempted = 1;
    g_mul_mv_bf16_f32_nsg4_mtl4_pipeline = ds4_mul_mv_bf16_f32_build_pipeline(4);
    g_mul_mv_bf16_f32_nsg4_mtl4_init_ok = (g_mul_mv_bf16_f32_nsg4_mtl4_pipeline != nil) ? 1 : 0;
    return g_mul_mv_bf16_f32_nsg4_mtl4_init_ok;
}

static id<MTLComputePipelineState> g_mul_mv_f16_f32_nsg4_mtl4_pipeline;
static int g_mul_mv_f16_f32_nsg4_mtl4_init_attempted;
static int g_mul_mv_f16_f32_nsg4_mtl4_init_ok;

static int ds4_mul_mv_f16_f32_nsg4_mtl4_pipeline_init(void) {
    if (g_mul_mv_f16_f32_nsg4_mtl4_init_attempted) return g_mul_mv_f16_f32_nsg4_mtl4_init_ok;
    g_mul_mv_f16_f32_nsg4_mtl4_init_attempted = 1;
    g_mul_mv_f16_f32_nsg4_mtl4_pipeline = ds4_mul_mv_f16_f32_build_pipeline(4);
    g_mul_mv_f16_f32_nsg4_mtl4_init_ok = (g_mul_mv_f16_f32_nsg4_mtl4_pipeline != nil) ? 1 : 0;
    return g_mul_mv_f16_f32_nsg4_mtl4_init_ok;
}

int ds4_gpu_mtl4_mul_mv_f16_f32_canary(uint32_t M, uint32_t N) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_mul_mv_f16_f32_nsg4_mtl4_pipeline_init()) return 0;
    if (M == 0 || N == 0 || (M % 4) != 0 || (N % 32) != 0) {
        fprintf(stderr, "ds4: mul_mv_f16_f32 canary needs M%%4==0 and N%%32==0 (got M=%u N=%u)\n", M, N);
        return 0;
    }

    const uint64_t matrix_n = (uint64_t)M * N;
    uint16_t *host_mat = (uint16_t *)calloc(matrix_n, sizeof(uint16_t));
    float *host_vec = (float *)calloc(N, sizeof(float));
    float *host_dst = (float *)calloc(M, sizeof(float));
    float *expected = (float *)calloc(M, sizeof(float));
    if (!host_mat || !host_vec || !host_dst || !expected) {
        free(host_mat); free(host_vec); free(host_dst); free(expected); return 0;
    }
    for (uint32_t r = 0; r < M; r++) {
        for (uint32_t c = 0; c < N; c++) {
            float v = (float)((int)r % 7) * 0.01f + (float)((int)c % 5) * 0.001f;
            _Float16 h = (_Float16)v;
            memcpy(&host_mat[(uint64_t)r * N + c], &h, sizeof(h));
        }
    }
    for (uint32_t c = 0; c < N; c++) host_vec[c] = (float)((int)c % 3) * 0.1f + 0.5f;
    for (uint32_t r = 0; r < M; r++) {
        double acc = 0.0;
        for (uint32_t c = 0; c < N; c++) {
            _Float16 h;
            memcpy(&h, &host_mat[(uint64_t)r * N + c], sizeof(h));
            acc += (double)(float)h * (double)host_vec[c];
        }
        expected[r] = (float)acc;
    }

    int rc = 0;
    double gpu_ms = -1.0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:128 options:MTLResourceStorageModeShared];
        id<MTLBuffer> matBuf = [g_device newBufferWithBytes:host_mat length:matrix_n*sizeof(uint16_t) options:MTLResourceStorageModeShared];
        id<MTLBuffer> vecBuf = [g_device newBufferWithBytes:host_vec length:N*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> dstBuf = [g_device newBufferWithLength:M*sizeof(float) options:MTLResourceStorageModeShared];

        struct {
            int ne00, ne01, ne02;
            uint64_t nb00, nb01, nb02, nb03;
            int ne10, ne11, ne12;
            uint64_t nb10, nb11, nb12, nb13;
            int ne0, ne1, nr0;
            int16_t r2, r3;
        } args;
        memset(&args, 0, sizeof(args));
        args.ne00 = N; args.ne01 = M; args.ne02 = 1;
        args.nb00 = sizeof(uint16_t);
        args.nb01 = (uint64_t)N * sizeof(uint16_t);
        args.nb02 = (uint64_t)M * N * sizeof(uint16_t);
        args.nb03 = (uint64_t)M * N * sizeof(uint16_t);
        args.ne10 = N; args.ne11 = 1; args.ne12 = 1;
        args.nb10 = sizeof(float);
        args.nb11 = (uint64_t)N * sizeof(float);
        args.nb12 = args.nb11; args.nb13 = args.nb11;
        args.ne0 = M; args.ne1 = 1; args.nr0 = 4;
        args.r2 = 1; args.r3 = 1;
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 6;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[4] = {(id)argsBuf, (id)matBuf, (id)vecBuf, (id)dstBuf};
            [residency addAllocations:allocs count:4];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(8);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:matBuf.gpuAddress atIndex:1];
                [argTable setAddress:vecBuf.gpuAddress atIndex:2];
                [argTable setAddress:dstBuf.gpuAddress atIndex:3];

                NSUInteger nth = 4u * 32u;
                NSUInteger shmem_bytes = 4u * 32u * sizeof(float);

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_mul_mv_f16_f32_nsg4_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc setThreadgroupMemoryLength:shmem_bytes atIndex:0];
                [enc dispatchThreadgroups:MTLSizeMake(M / 4, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) { (void)fb; dispatch_semaphore_signal(sem); }];
                id<MTL4CommandBuffer> bufs[1] = {cb};
                const double gpu_t0 = ds4_gpu_now_ms();
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                gpu_ms = ds4_gpu_now_ms() - gpu_t0;
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_dst, dstBuf.contents, M * sizeof(float));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 8);
            }
        }
    }
    if (!rc) { free(host_mat); free(host_vec); free(host_dst); free(expected); return 0; }

    int mismatch = 0;
    double max_rel = 0.0;
    for (uint32_t r = 0; r < M; r++) {
        const double diff = fabs((double)(host_dst[r] - expected[r]));
        const double rel = diff / (fabs((double)expected[r]) + 1e-7);
        if (rel > max_rel) max_rel = rel;
        if (rel > 1e-4) mismatch++;
    }
    fprintf(stderr,
        "ds4: mul_mv_f16_f32 MTL4 canary M=%u N=%u gpu_ms=%.3f "
        "dst[0]=%.5f (ref=%.5f) dst[end]=%.5f (ref=%.5f) mismatch=%d max_rel=%.4e\n",
        M, N, gpu_ms,
        (double)host_dst[0], (double)expected[0],
        (double)host_dst[M - 1], (double)expected[M - 1],
        mismatch, max_rel);
    free(host_mat); free(host_vec); free(host_dst); free(expected);
    return (mismatch == 0) ? 1 : 0;
}

/* silv 2026-05-28 #796 Increment 1 — BF16 matvec canary.
 *
 * Twin of the F16 canary above. Weights are encoded as BF16 (upper 16 bits
 * of fp32). The expected output uses the same widen-to-f32 path the kernel
 * uses internally, so any deviation indicates kernel bug (NOT precision
 * loss in the BF16 representation itself — that's already baked into both
 * the input and the reference). Tolerance: same 1e-4 as the F16 canary.
 *
 * Self-tests:
 *   M=64, N=128  — small, fast (smoke)
 *   M=256, N=4096 — closer to real attention weight shape
 *
 * Engineer-roster: canary that proves the BF16 read path is numerically
 * correct, before any production call site wires tensor_effective_type. */

/* silv 2026-05-28 #796 Increment 4 — heap-storage-aware BF16 matvec.
 *
 * Parallel to matmul_f16_storage / matmul_q8_0_storage but for BF16
 * weights. Uses the existing g_mul_mv_bf16_f32_nsg4_mtl4_pipeline
 * (MTLComputePipelineState is dispatch-mechanism-agnostic) via the
 * standard MTL3-style command buffer, so no new pipeline build required
 * and no MTL4-overhead per call (vs the canary which uses a fresh
 * residency set + semaphore).
 *
 * BF16 only supports n_tok=1 (matvec) — the existing MSL kernel is
 * matvec-only. Multi-token would require a new mul_mm_bf16_f32 kernel.
 *
 * Currently no production call site wires this — Increment 5 (lifting
 * the Cycle 5 ground rule + override-fill populating BF16 storage) is
 * the gate. This function ships the foundation so Increment 5 has a
 * dispatch target ready.
 *
 * Returns 1 on success, 0 on failure. */
int ds4_gpu_matmul_bf16_storage(
    ds4_gpu_tensor *out,
    void *weight_buf,
    uint64_t in_dim,
    uint64_t out_dim,
    const ds4_gpu_tensor *x,
    uint64_t n_tok) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_mul_mv_bf16_f32_nsg4_mtl4_pipeline_init()) return 0;
    if (!weight_buf || !out || !x) return 0;
    if (n_tok != 1) return 0;
    if (in_dim > UINT32_MAX || out_dim > UINT32_MAX) return 0;
    if ((out_dim % 4u) != 0 || (in_dim % 32u) != 0) return 0;

    @autoreleasepool {
        id<MTLBuffer> wbuf = (__bridge id<MTLBuffer>)weight_buf;
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        if (!xbuf || !outbuf) return 0;

        const uint64_t weight_bytes = in_dim * out_dim * sizeof(uint16_t);
        if ((uint64_t)wbuf.length < weight_bytes) {
            fprintf(stderr,
                    "ds4: matmul_bf16_storage weight buffer too small (%llu < %llu)\n",
                    (unsigned long long)wbuf.length,
                    (unsigned long long)weight_bytes);
            return 0;
        }
        const uint64_t x_bytes = in_dim * sizeof(float);
        const uint64_t out_bytes = out_dim * sizeof(float);
        if (ds4_gpu_tensor_bytes(x) < x_bytes ||
            ds4_gpu_tensor_bytes(out) < out_bytes) {
            fprintf(stderr, "ds4: matmul_bf16_storage received undersized activation buffers\n");
            return 0;
        }

        /* Args struct matches the BF16 MSL kernel's mv_args layout. */
        struct {
            int ne00, ne01, ne02;
            uint64_t nb00, nb01, nb02, nb03;
            int ne10, ne11, ne12;
            uint64_t nb10, nb11, nb12, nb13;
            int ne0, ne1, nr0;
            int16_t r2, r3;
        } args;
        memset(&args, 0, sizeof(args));
        args.ne00 = (int)in_dim;  args.ne01 = (int)out_dim;  args.ne02 = 1;
        args.nb00 = sizeof(uint16_t);
        args.nb01 = in_dim * sizeof(uint16_t);
        args.nb02 = in_dim * out_dim * sizeof(uint16_t);
        args.nb03 = args.nb02;
        args.ne10 = (int)in_dim;  args.ne11 = 1;  args.ne12 = 1;
        args.nb10 = sizeof(float);
        args.nb11 = in_dim * sizeof(float);
        args.nb12 = args.nb11;  args.nb13 = args.nb11;
        args.ne0 = (int)out_dim;  args.ne1 = 1;  args.nr0 = 4;
        args.r2 = 1;  args.r3 = 1;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:g_mul_mv_bf16_f32_nsg4_mtl4_pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:wbuf offset:0 atIndex:1];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
        const NSUInteger shmem_bytes = 4u * 32u * sizeof(float);
        [enc setThreadgroupMemoryLength:shmem_bytes atIndex:0];
        const NSUInteger nth = 4u * 32u;
        [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)out_dim / 4, 1, 1)
            threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "BF16 storage matvec")) return 0;
    }
    return 1;
}

int ds4_gpu_mtl4_mul_mv_bf16_f32_canary(uint32_t M, uint32_t N) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_mul_mv_bf16_f32_nsg4_mtl4_pipeline_init()) return 0;
    if (M == 0 || N == 0 || (M % 4) != 0 || (N % 32) != 0) {
        fprintf(stderr, "ds4: mul_mv_bf16_f32 canary needs M%%4==0 and N%%32==0 (got M=%u N=%u)\n", M, N);
        return 0;
    }

    const uint64_t matrix_n = (uint64_t)M * N;
    uint16_t *host_mat = (uint16_t *)calloc(matrix_n, sizeof(uint16_t));
    float *host_vec = (float *)calloc(N, sizeof(float));
    float *host_dst = (float *)calloc(M, sizeof(float));
    float *expected = (float *)calloc(M, sizeof(float));
    if (!host_mat || !host_vec || !host_dst || !expected) {
        free(host_mat); free(host_vec); free(host_dst); free(expected); return 0;
    }
    /* Fill matrix with deterministic values, encoded as BF16 (upper 16 bits
     * of fp32). Note: BF16 simply TRUNCATES the lower 16 bits of fp32 — no
     * round-to-nearest. */
    for (uint32_t r = 0; r < M; r++) {
        for (uint32_t c = 0; c < N; c++) {
            float v = (float)((int)r % 7) * 0.01f + (float)((int)c % 5) * 0.001f;
            uint32_t bits;
            memcpy(&bits, &v, sizeof(bits));
            uint16_t bf16 = (uint16_t)(bits >> 16);  /* upper 16 bits */
            host_mat[(uint64_t)r * N + c] = bf16;
        }
    }
    for (uint32_t c = 0; c < N; c++) host_vec[c] = (float)((int)c % 3) * 0.1f + 0.5f;
    /* Reference accumulates using the same BF16 → F32 widen the kernel does. */
    for (uint32_t r = 0; r < M; r++) {
        double acc = 0.0;
        for (uint32_t c = 0; c < N; c++) {
            uint16_t bf16 = host_mat[(uint64_t)r * N + c];
            uint32_t f32_bits = (uint32_t)bf16 << 16;
            float w;
            memcpy(&w, &f32_bits, sizeof(w));
            acc += (double)w * (double)host_vec[c];
        }
        expected[r] = (float)acc;
    }

    int rc = 0;
    double gpu_ms = -1.0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:128 options:MTLResourceStorageModeShared];
        id<MTLBuffer> matBuf = [g_device newBufferWithBytes:host_mat length:matrix_n*sizeof(uint16_t) options:MTLResourceStorageModeShared];
        id<MTLBuffer> vecBuf = [g_device newBufferWithBytes:host_vec length:N*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> dstBuf = [g_device newBufferWithLength:M*sizeof(float) options:MTLResourceStorageModeShared];

        struct {
            int ne00, ne01, ne02;
            uint64_t nb00, nb01, nb02, nb03;
            int ne10, ne11, ne12;
            uint64_t nb10, nb11, nb12, nb13;
            int ne0, ne1, nr0;
            int16_t r2, r3;
        } args;
        memset(&args, 0, sizeof(args));
        args.ne00 = N; args.ne01 = M; args.ne02 = 1;
        args.nb00 = sizeof(uint16_t);
        args.nb01 = (uint64_t)N * sizeof(uint16_t);
        args.nb02 = (uint64_t)M * N * sizeof(uint16_t);
        args.nb03 = (uint64_t)M * N * sizeof(uint16_t);
        args.ne10 = N; args.ne11 = 1; args.ne12 = 1;
        args.nb10 = sizeof(float);
        args.nb11 = (uint64_t)N * sizeof(float);
        args.nb12 = args.nb11; args.nb13 = args.nb11;
        args.ne0 = M; args.ne1 = 1; args.nr0 = 4;
        args.r2 = 1; args.r3 = 1;
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 6;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[4] = {(id)argsBuf, (id)matBuf, (id)vecBuf, (id)dstBuf};
            [residency addAllocations:allocs count:4];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(8);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:matBuf.gpuAddress atIndex:1];
                [argTable setAddress:vecBuf.gpuAddress atIndex:2];
                [argTable setAddress:dstBuf.gpuAddress atIndex:3];

                NSUInteger nth = 4u * 32u;
                NSUInteger shmem_bytes = 4u * 32u * sizeof(float);

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_mul_mv_bf16_f32_nsg4_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc setThreadgroupMemoryLength:shmem_bytes atIndex:0];
                [enc dispatchThreadgroups:MTLSizeMake(M / 4, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) { (void)fb; dispatch_semaphore_signal(sem); }];
                id<MTL4CommandBuffer> bufs[1] = {cb};
                const double gpu_t0 = ds4_gpu_now_ms();
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                gpu_ms = ds4_gpu_now_ms() - gpu_t0;
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_dst, dstBuf.contents, M * sizeof(float));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 8);
            }
        }
    }
    if (!rc) { free(host_mat); free(host_vec); free(host_dst); free(expected); return 0; }

    int mismatch = 0;
    double max_rel = 0.0;
    for (uint32_t r = 0; r < M; r++) {
        const double diff = fabs((double)(host_dst[r] - expected[r]));
        const double rel = diff / (fabs((double)expected[r]) + 1e-7);
        if (rel > max_rel) max_rel = rel;
        if (rel > 1e-4) mismatch++;
    }
    fprintf(stderr,
        "ds4: mul_mv_bf16_f32 MTL4 canary M=%u N=%u gpu_ms=%.3f "
        "dst[0]=%.5f (ref=%.5f) dst[end]=%.5f (ref=%.5f) mismatch=%d max_rel=%.4e\n",
        M, N, gpu_ms,
        (double)host_dst[0], (double)expected[0],
        (double)host_dst[M - 1], (double)expected[M - 1],
        mismatch, max_rel);
    free(host_mat); free(host_vec); free(host_dst); free(expected);
    return (mismatch == 0) ? 1 : 0;
}

/* ============================================================ */
/* dsv4_shared_down_hc_expand4_q8_0 MTL4 port (silv 2026-05-28 #728) */
/* ============================================================ */
/* Q8_0 shared-down matvec fused with routed-out add + 4-channel HC
 * expansion. Sister of #725 q8_hc_expand4 with an extra routed_out
 * input — block_v = shared_v + routed_out[d]. Used after routed-expert
 * down + shared-expert SwiGLU intermediate to combine both streams and
 * emit the 4 HC channels at decode-time. 10 buffers. Hardcoded
 * n_hc=4, n_tokens=1. NR0=2, NSG=4 via FC. */

static id<MTLComputePipelineState> ds4_dsv4_shared_down_hc_expand4_q8_0_build_pipeline(short nsg_value) {
    NSString *source = [NSString stringWithFormat:
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "#define FC_MUL_MV 600\n"
         "#define N_SIMDWIDTH 32\n"
         "#define QK8_0 32\n"
         "constant short FC_mul_mv_nsg [[function_constant(FC_MUL_MV + 0)]];\n"
         "struct block_q8_0 { half d; int8_t qs[QK8_0]; };\n"
         "struct mv_args {\n"
         "  int ne00; int ne01; int ne02;\n"
         "  ulong nb00; ulong nb01; ulong nb02; ulong nb03;\n"
         "  int ne10; int ne11; int ne12;\n"
         "  ulong nb10; ulong nb11; ulong nb12; ulong nb13;\n"
         "  int ne0; int ne1; int nr0;\n"
         "  short r2; short r3;\n"
         "};\n"
         "struct hc_args {\n"
         "  long n_embd; long n_hc; long n_tokens;\n"
         "  ulong nb_block0; ulong nb_block1;\n"
         "  ulong nb_add0; ulong nb_add1;\n"
         "  ulong nb_res0; ulong nb_res1; ulong nb_res2;\n"
         "  ulong nb_post0; ulong nb_post1;\n"
         "  ulong nb_comb0; ulong nb_comb1; ulong nb_comb2;\n"
         "  ulong nb0; ulong nb1;\n"
         "};\n"
         "kernel void dsv4_shared_down_hc_expand4_q8_0_mtl4(\n"
         "    device const mv_args *mv         [[buffer(0)]],\n"
         "    device const hc_args *hc         [[buffer(1)]],\n"
         "    device const char    *weight     [[buffer(2)]],\n"
         "    device const char    *shared_mid [[buffer(3)]],\n"
         "    device       char    *shared_out [[buffer(4)]],\n"
         "    device const char    *routed_out [[buffer(5)]],\n"
         "    device const char    *residual   [[buffer(6)]],\n"
         "    device const char    *post       [[buffer(7)]],\n"
         "    device const char    *comb       [[buffer(8)]],\n"
         "    device       char    *dst        [[buffer(9)]],\n"
         "    threadgroup  char    *shmem      [[threadgroup(0)]],\n"
         "    uint3   tgpig [[threadgroup_position_in_grid]],\n"
         "    ushort  tiisg [[thread_index_in_simdgroup]],\n"
         "    ushort  sgitg [[simdgroup_index_in_threadgroup]]) {\n"
         "  if (hc->n_hc != 4 || hc->n_tokens != 1) return;\n"
         "  constexpr short NR0 = 2;\n"
         "  const short NSG = FC_mul_mv_nsg;\n"
         "  constexpr short NW = N_SIMDWIDTH;\n"
         "  constexpr short NQ = 8;\n"
         "  const int nb = mv->ne00 / QK8_0;\n"
         "  const int row0 = tgpig.x * NR0;\n"
         "  const short ix = tiisg / (NW / NQ);\n"
         "  const short il = tiisg %% (NW / NQ);\n"
         "  const int ib0 = sgitg * NQ + ix;\n"
         "  device const float *y = (device const float *)(shared_mid);\n"
         "  device const float *yb = y + ib0*QK8_0 + il*NQ;\n"
         "  device const block_q8_0 *ax[NR0];\n"
         "  for (short row = 0; row < NR0; ++row) {\n"
         "    const ulong off0 = (ulong)(row0 + row) * mv->nb01;\n"
         "    ax[row] = (device const block_q8_0 *)(weight + off0);\n"
         "  }\n"
         "  float sumf[NR0] = {0.0f};\n"
         "  float yl[NQ];\n"
         "  for (int ib = ib0; ib < nb; ib += NSG*NQ) {\n"
         "    for (short i = 0; i < NQ; ++i) yl[i] = yb[i];\n"
         "    for (short row = 0; row < NR0; ++row) {\n"
         "      device const int8_t *qs = ax[row][ib].qs + il*NQ;\n"
         "      float sumq = 0.0f;\n"
         "      for (short i = 0; i < NQ; ++i) sumq += (float)qs[i] * yl[i];\n"
         "      sumf[row] += sumq * (float)ax[row][ib].d;\n"
         "    }\n"
         "    yb += NSG*NQ*QK8_0;\n"
         "  }\n"
         "  threadgroup float *shmem_f32[NR0];\n"
         "  for (short row = 0; row < NR0; ++row) {\n"
         "    shmem_f32[row] = (threadgroup float *)shmem + NW * row;\n"
         "    if (sgitg == 0) shmem_f32[row][tiisg] = 0.0f;\n"
         "    sumf[row] = simd_sum(sumf[row]);\n"
         "  }\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  for (short row = 0; row < NR0; ++row) {\n"
         "    if (tiisg == 0) shmem_f32[row][sgitg] = sumf[row];\n"
         "  }\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  for (short row = 0; row < NR0; ++row) {\n"
         "    const int d = row0 + row;\n"
         "    if (d >= mv->ne01) continue;\n"
         "    const float shared_v = simd_sum(shmem_f32[row][tiisg]);\n"
         "    if (tiisg == 0 && sgitg == 0) {\n"
         "      *((device float *)(shared_out + (ulong)d * sizeof(float))) = shared_v;\n"
         "      float block_v = *((device const float *)(routed_out + (ulong)d * hc->nb_block0));\n"
         "      block_v += shared_v;\n"
         "      const float r0v = *((device const float *)(residual + (ulong)d * hc->nb_res0 + 0 * hc->nb_res1));\n"
         "      const float r1v = *((device const float *)(residual + (ulong)d * hc->nb_res0 + 1 * hc->nb_res1));\n"
         "      const float r2v = *((device const float *)(residual + (ulong)d * hc->nb_res0 + 2 * hc->nb_res1));\n"
         "      const float r3v = *((device const float *)(residual + (ulong)d * hc->nb_res0 + 3 * hc->nb_res1));\n"
         "      for (long dst_hc = 0; dst_hc < 4; ++dst_hc) {\n"
         "        float acc = block_v * *((device const float *)(post + dst_hc * hc->nb_post0));\n"
         "        acc += *((device const float *)(comb + dst_hc * hc->nb_comb0 + 0 * hc->nb_comb1)) * r0v;\n"
         "        acc += *((device const float *)(comb + dst_hc * hc->nb_comb0 + 1 * hc->nb_comb1)) * r1v;\n"
         "        acc += *((device const float *)(comb + dst_hc * hc->nb_comb0 + 2 * hc->nb_comb1)) * r2v;\n"
         "        acc += *((device const float *)(comb + dst_hc * hc->nb_comb0 + 3 * hc->nb_comb1)) * r3v;\n"
         "        *((device float *)(dst + (ulong)d * hc->nb0 + dst_hc * hc->nb1)) = acc;\n"
         "      }\n"
         "    }\n"
         "  }\n"
         "}\n"];

    const ds4_mtl4_fc_short fcs[] = {{nsg_value, 600}};
    return ds4_mtl4_build_kernel_pipeline(
        source,
        @"ds4_dsv4_shared_down_hc_expand4_q8_0_mtl4",
        @"dsv4_shared_down_hc_expand4_q8_0_mtl4",
        1024,
        fcs, 1);
}

static id<MTLComputePipelineState> g_dsv4_shared_down_hc_expand4_q8_0_nsg4_mtl4_pipeline;
static int g_dsv4_shared_down_hc_expand4_q8_0_nsg4_mtl4_init_attempted;
static int g_dsv4_shared_down_hc_expand4_q8_0_nsg4_mtl4_init_ok;

static int ds4_dsv4_shared_down_hc_expand4_q8_0_nsg4_mtl4_pipeline_init(void) {
    if (g_dsv4_shared_down_hc_expand4_q8_0_nsg4_mtl4_init_attempted) return g_dsv4_shared_down_hc_expand4_q8_0_nsg4_mtl4_init_ok;
    g_dsv4_shared_down_hc_expand4_q8_0_nsg4_mtl4_init_attempted = 1;
    g_dsv4_shared_down_hc_expand4_q8_0_nsg4_mtl4_pipeline = ds4_dsv4_shared_down_hc_expand4_q8_0_build_pipeline(4);
    g_dsv4_shared_down_hc_expand4_q8_0_nsg4_mtl4_init_ok = (g_dsv4_shared_down_hc_expand4_q8_0_nsg4_mtl4_pipeline != nil) ? 1 : 0;
    return g_dsv4_shared_down_hc_expand4_q8_0_nsg4_mtl4_init_ok;
}

int ds4_gpu_mtl4_dsv4_shared_down_hc_expand4_q8_0_canary(uint32_t M, uint32_t N) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_dsv4_shared_down_hc_expand4_q8_0_nsg4_mtl4_pipeline_init()) return 0;
    if (M == 0 || N == 0 || (M % 2) != 0 || (N % 32) != 0) {
        fprintf(stderr, "ds4: shared_down_hc canary needs M%%2==0 N%%32==0 (got M=%u N=%u)\n", M, N);
        return 0;
    }

    float *host_w = (float *)calloc((uint64_t)M * N, sizeof(float));
    float *host_shared_mid = (float *)calloc(N, sizeof(float));
    float *host_routed_out = (float *)calloc(M, sizeof(float));
    float *host_shared_out = (float *)calloc(M, sizeof(float));
    float *host_residual = (float *)calloc((uint64_t)M * 4, sizeof(float));
    float host_post[4] = {0.5f, 0.25f, 0.125f, 0.0625f};
    float host_comb[16];
    for (int i = 0; i < 16; i++) host_comb[i] = 0.1f * (float)(i % 5);
    float *host_dst = (float *)calloc((uint64_t)M * 4, sizeof(float));
    float *expected_shared = (float *)calloc(M, sizeof(float));
    float *expected_dst = (float *)calloc((uint64_t)M * 4, sizeof(float));
    const uint32_t n_blocks_per_row = N / 32u;
    const uint64_t q8_row_bytes = (uint64_t)n_blocks_per_row * 34u;
    uint8_t *host_q8 = (uint8_t *)calloc((uint64_t)M * q8_row_bytes, 1);
    if (!host_w || !host_shared_mid || !host_routed_out || !host_shared_out ||
        !host_residual || !host_dst || !expected_shared || !expected_dst || !host_q8) {
        free(host_w); free(host_shared_mid); free(host_routed_out); free(host_shared_out);
        free(host_residual); free(host_dst); free(expected_shared); free(expected_dst); free(host_q8);
        return 0;
    }
    for (uint32_t r = 0; r < M; r++) {
        for (uint32_t c = 0; c < N; c++) {
            host_w[(uint64_t)r * N + c] = (float)((int)((r * 13 + c * 7) % 250) - 125);
        }
        ds4_quantize_q8_0_row(host_w + (uint64_t)r * N, N, host_q8 + (uint64_t)r * q8_row_bytes);
        for (uint32_t b = 0; b < n_blocks_per_row; b++) {
            const uint8_t *blk = host_q8 + (uint64_t)r * q8_row_bytes + (uint64_t)b * 34u;
            _Float16 d_half;
            memcpy(&d_half, blk, sizeof(d_half));
            const float d = (float)d_half;
            const int8_t *qs = (const int8_t *)(blk + 2);
            for (uint32_t i = 0; i < 32; i++) {
                host_w[(uint64_t)r * N + (uint64_t)b * 32u + i] = (float)qs[i] * d;
            }
        }
        host_routed_out[r] = 0.05f * (float)((int)r - 32);
        for (int c = 0; c < 4; c++) host_residual[(uint64_t)r * 4 + c] = 0.1f * (float)((int)r + c);
    }
    for (uint32_t c = 0; c < N; c++) host_shared_mid[c] = ((float)((int)(c % 7)) - 3.0f) * 0.5f;
    for (uint32_t r = 0; r < M; r++) {
        double acc = 0.0;
        for (uint32_t c = 0; c < N; c++) acc += (double)host_w[(uint64_t)r * N + c] * (double)host_shared_mid[c];
        const float shared_v = (float)acc;
        expected_shared[r] = shared_v;
        const float block_v = host_routed_out[r] + shared_v;
        for (int dst_hc = 0; dst_hc < 4; dst_hc++) {
            float v = block_v * host_post[dst_hc];
            for (int k = 0; k < 4; k++) v += host_comb[dst_hc * 4 + k] * host_residual[(uint64_t)r * 4 + k];
            expected_dst[(uint64_t)r * 4 + dst_hc] = v;
        }
    }

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> mvBuf = [g_device newBufferWithLength:128 options:MTLResourceStorageModeShared];
        id<MTLBuffer> hcBuf = [g_device newBufferWithLength:128 options:MTLResourceStorageModeShared];
        id<MTLBuffer> wBuf = [g_device newBufferWithBytes:host_q8 length:(uint64_t)M*q8_row_bytes options:MTLResourceStorageModeShared];
        id<MTLBuffer> midBuf = [g_device newBufferWithBytes:host_shared_mid length:N*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> sharedOutBuf = [g_device newBufferWithLength:M*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> routedOutBuf = [g_device newBufferWithBytes:host_routed_out length:M*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> resBuf = [g_device newBufferWithBytes:host_residual length:(uint64_t)M*4*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> postBuf = [g_device newBufferWithBytes:host_post length:4*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> combBuf = [g_device newBufferWithBytes:host_comb length:16*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> dstBuf = [g_device newBufferWithLength:(uint64_t)M*4*sizeof(float) options:MTLResourceStorageModeShared];

        struct {
            int ne00, ne01, ne02;
            uint64_t nb00, nb01, nb02, nb03;
            int ne10, ne11, ne12;
            uint64_t nb10, nb11, nb12, nb13;
            int ne0, ne1, nr0;
            int16_t r2, r3;
        } mv;
        memset(&mv, 0, sizeof(mv));
        mv.ne00 = N; mv.ne01 = M; mv.ne02 = 1;
        mv.nb00 = 1; mv.nb01 = q8_row_bytes;
        mv.nb02 = (uint64_t)M * q8_row_bytes; mv.nb03 = mv.nb02;
        mv.ne10 = N; mv.ne11 = 1; mv.ne12 = 1;
        mv.nb10 = sizeof(float); mv.nb11 = (uint64_t)N * sizeof(float);
        mv.nb12 = mv.nb11; mv.nb13 = mv.nb11;
        mv.ne0 = M; mv.ne1 = 1; mv.nr0 = 2; mv.r2 = 1; mv.r3 = 1;
        memcpy(mvBuf.contents, &mv, sizeof(mv));

        struct {
            int64_t n_embd, n_hc, n_tokens;
            uint64_t nb_block0, nb_block1;
            uint64_t nb_add0, nb_add1;
            uint64_t nb_res0, nb_res1, nb_res2;
            uint64_t nb_post0, nb_post1;
            uint64_t nb_comb0, nb_comb1, nb_comb2;
            uint64_t nb0, nb1;
        } hc;
        memset(&hc, 0, sizeof(hc));
        hc.n_embd = M; hc.n_hc = 4; hc.n_tokens = 1;
        hc.nb_block0 = sizeof(float); hc.nb_block1 = (uint64_t)M * sizeof(float);
        hc.nb_res0 = 4 * sizeof(float); hc.nb_res1 = sizeof(float); hc.nb_res2 = 0;
        hc.nb_post0 = sizeof(float); hc.nb_post1 = 0;
        hc.nb_comb0 = 4 * sizeof(float); hc.nb_comb1 = sizeof(float); hc.nb_comb2 = 0;
        hc.nb0 = 4 * sizeof(float); hc.nb1 = sizeof(float);
        memcpy(hcBuf.contents, &hc, sizeof(hc));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 16;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[10] = {
                (id)mvBuf, (id)hcBuf, (id)wBuf, (id)midBuf,
                (id)sharedOutBuf, (id)routedOutBuf, (id)resBuf,
                (id)postBuf, (id)combBuf, (id)dstBuf
            };
            [residency addAllocations:allocs count:10];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(16);
            if (argTable) {
                [argTable setAddress:mvBuf.gpuAddress atIndex:0];
                [argTable setAddress:hcBuf.gpuAddress atIndex:1];
                [argTable setAddress:wBuf.gpuAddress atIndex:2];
                [argTable setAddress:midBuf.gpuAddress atIndex:3];
                [argTable setAddress:sharedOutBuf.gpuAddress atIndex:4];
                [argTable setAddress:routedOutBuf.gpuAddress atIndex:5];
                [argTable setAddress:resBuf.gpuAddress atIndex:6];
                [argTable setAddress:postBuf.gpuAddress atIndex:7];
                [argTable setAddress:combBuf.gpuAddress atIndex:8];
                [argTable setAddress:dstBuf.gpuAddress atIndex:9];

                NSUInteger nth = 4u * 32u;
                NSUInteger shmem_bytes = 2u * 32u * sizeof(float);

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_dsv4_shared_down_hc_expand4_q8_0_nsg4_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc setThreadgroupMemoryLength:shmem_bytes atIndex:0];
                [enc dispatchThreadgroups:MTLSizeMake(M / 2, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) { (void)fb; dispatch_semaphore_signal(sem); }];
                id<MTL4CommandBuffer> bufs[1] = {cb};
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_shared_out, sharedOutBuf.contents, M * sizeof(float));
                    memcpy(host_dst, dstBuf.contents, (uint64_t)M * 4 * sizeof(float));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 16);
            }
        }
    }
    if (!rc) goto cleanup;

    int shared_mismatch = 0, dst_mismatch = 0;
    double max_rel_shared = 0.0, max_rel_dst = 0.0;
    for (uint32_t r = 0; r < M; r++) {
        double d = fabs((double)(host_shared_out[r] - expected_shared[r]));
        double rel = d / (fabs((double)expected_shared[r]) + 1e-3);
        if (rel > max_rel_shared) max_rel_shared = rel;
        if (rel > 5.0e-3) shared_mismatch++;
        for (int c = 0; c < 4; c++) {
            d = fabs((double)(host_dst[(uint64_t)r * 4 + c] - expected_dst[(uint64_t)r * 4 + c]));
            rel = d / (fabs((double)expected_dst[(uint64_t)r * 4 + c]) + 1e-3);
            if (rel > max_rel_dst) max_rel_dst = rel;
            if (rel > 5.0e-3) dst_mismatch++;
        }
    }
    fprintf(stderr,
        "ds4: dsv4_shared_down_hc_expand4_q8_0 MTL4 canary M=%u N=%u "
        "shared_mismatch=%d (max_rel=%.4e) dst_mismatch=%d (max_rel=%.4e)\n",
        M, N,
        shared_mismatch, max_rel_shared, dst_mismatch, max_rel_dst);

cleanup:
    free(host_w); free(host_shared_mid); free(host_routed_out); free(host_shared_out);
    free(host_residual); free(host_dst); free(expected_shared); free(expected_dst); free(host_q8);
    return rc && (shared_mismatch == 0 && dst_mismatch == 0) ? 1 : 0;
}

/* ============================================================ */
/* MTL4 lane-execution diagnostic (silv 2026-05-28 — crack #701)  */
/* ============================================================ */
/* The simdgroup MMA failure isn't about MMA. The prior diagnostic
 * showed that even DIRECT per-thread writes only landed for lanes
 * whose row0 = lane >> 3 = 0 (lanes 0-7). Lanes 8-31 of every
 * simdgroup silently skipped writes.
 *
 * Test 1: dispatch (128, 1, 1) threads, each writes its tpitg value
 * to dst[tpitg]. If we see all 128 values, lane execution works.
 * If we see fewer, MTL4 is clamping. */

static id<MTLComputePipelineState> g_lane_diag_mtl4_pipeline;
static int g_lane_diag_mtl4_init_attempted;
static int g_lane_diag_mtl4_init_ok;

static int ds4_lane_diag_mtl4_pipeline_init(void) {
    if (g_lane_diag_mtl4_init_attempted) return g_lane_diag_mtl4_init_ok;
    g_lane_diag_mtl4_init_attempted = 1;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "kernel void lane_diag_mtl4(\n"
         "    device       int *dst   [[buffer(0)]],\n"
         "    device const int *meta  [[buffer(1)]],\n"
         "    uint  tpitg [[thread_position_in_threadgroup]],\n"
         "    ushort tiisg [[thread_index_in_simdgroup]],\n"
         "    ushort sgitg [[simdgroup_index_in_threadgroup]],\n"
         "    uint  ntg   [[threads_per_threadgroup]]) {\n"
         "  /* Encode: tpitg | (ntg << 12) | (tiisg << 20) | (sgitg << 25) */\n"
         "  uint v = (uint)tpitg | ((uint)ntg << 12) | ((uint)tiisg << 20) | ((uint)sgitg << 25);\n"
         "  dst[tpitg] = (int)v;\n"
         "  /* Also sanity: meta[0] is the expected ntg value; record mismatch */\n"
         "  if (tpitg == 0) dst[1024] = (int)meta[0] - (int)ntg;\n"
         "}\n";
    g_lane_diag_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_lane_diag_mtl4", @"lane_diag_mtl4", 1024, NULL, 0);
    g_lane_diag_mtl4_init_ok = (g_lane_diag_mtl4_pipeline != nil) ? 1 : 0;
    return g_lane_diag_mtl4_init_ok;
}

int ds4_gpu_mtl4_lane_diag_canary(uint32_t nthreads) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_lane_diag_mtl4_pipeline_init()) return 0;
    if (nthreads == 0 || nthreads > 1024) return 0;

    int *host_dst = (int *)calloc(2048, sizeof(int));
    int meta[1] = {(int)nthreads};
    if (!host_dst) return 0;

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> dstBuf = [g_device newBufferWithLength:2048*sizeof(int) options:MTLResourceStorageModeShared];
        id<MTLBuffer> metaBuf = [g_device newBufferWithBytes:meta length:sizeof(meta) options:MTLResourceStorageModeShared];
        memset(dstBuf.contents, 0, 2048*sizeof(int));
        /* Sentinel: pre-fill with -1 so we can detect lanes that didn't write */
        int *pre = (int *)dstBuf.contents;
        for (int i = 0; i < 1024; i++) pre[i] = -1;

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 4;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[2] = {(id)dstBuf, (id)metaBuf};
            [residency addAllocations:allocs count:2];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(4);
            if (argTable) {
                [argTable setAddress:dstBuf.gpuAddress atIndex:0];
                [argTable setAddress:metaBuf.gpuAddress atIndex:1];

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_lane_diag_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc dispatchThreadgroups:MTLSizeMake(1, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(nthreads, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) { (void)fb; dispatch_semaphore_signal(sem); }];
                id<MTL4CommandBuffer> bufs[1] = {cb};
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_dst, dstBuf.contents, 2048*sizeof(int));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 4);
            }
        }
    }
    if (!rc) { free(host_dst); return 0; }

    /* Analyze: count how many lanes wrote (non -1), record per-bucket */
    int n_wrote = 0;
    int per_8lane[16] = {0};  /* lanes 0-7, 8-15, ... 120-127 */
    int ntg_seen = 0;
    int tiisg_max = -1, sgitg_max = -1;
    for (uint32_t i = 0; i < 1024; i++) {
        if (host_dst[i] == -1) continue;
        n_wrote++;
        if (i < 128) per_8lane[i / 8]++;
        uint32_t v = (uint32_t)host_dst[i];
        uint32_t tpitg_seen = v & 0xFFF;
        uint32_t ntg_s = (v >> 12) & 0xFF;
        uint32_t tiisg = (v >> 20) & 0x1F;
        uint32_t sgitg = (v >> 25) & 0x7F;
        if ((int)tpitg_seen != (int)i) {
            /* Encoded tpitg should match index, since dst[tpitg] = v */
            fprintf(stderr, "ds4: lane_diag mismatch at i=%u: tpitg_encoded=%u\n", i, tpitg_seen);
        }
        if (ntg_seen == 0) ntg_seen = ntg_s;
        if ((int)tiisg > tiisg_max) tiisg_max = tiisg;
        if ((int)sgitg > sgitg_max) sgitg_max = sgitg;
    }
    fprintf(stderr,
        "ds4: lane_diag dispatched_nth=%u, n_wrote=%d, ntg_seen=%d, "
        "tiisg_max=%d, sgitg_max=%d, ntg_meta_delta=%d\n",
        nthreads, n_wrote, ntg_seen, tiisg_max, sgitg_max, host_dst[1024]);
    fprintf(stderr, "  per-8-lane buckets (lanes 0-7, 8-15, ..., 120-127): ");
    for (int b = 0; b < 16; b++) fprintf(stderr, "%d ", per_8lane[b]);
    fprintf(stderr, "\n");
    free(host_dst);
    return (n_wrote == (int)nthreads) ? 1 : 0;
}

/* ============================================================ */
/* MTL4 simdgroup_MMA isolation test (silv 2026-05-28 — #701)    */
/* ============================================================ */
/* Smallest possible MMA kernel: 1 simdgroup, fill 8×8 matrices A=B=1,
 * multiply, store. Expected result: 8 (since each output cell is the
 * dot of 8 ones × 8 ones = 8). If this fails, MTL4 cannot run
 * simdgroup MMA on M1. If it works, the indexer_scores_tiled kernel's
 * MMA usage was the bug (likely threadgroup memory pointer space). */

static id<MTLComputePipelineState> g_mma_iso_mtl4_pipeline;
static int g_mma_iso_mtl4_init_attempted;
static int g_mma_iso_mtl4_init_ok;

static int ds4_mma_iso_mtl4_pipeline_init(void) {
    if (g_mma_iso_mtl4_init_attempted) return g_mma_iso_mtl4_init_ok;
    g_mma_iso_mtl4_init_attempted = 1;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "#include <metal_simdgroup_matrix>\n"
         "using namespace metal;\n"
         "kernel void mma_iso_mtl4(\n"
         "    device       float *dst   [[buffer(0)]],\n"
         "    threadgroup  float *shmem [[threadgroup(0)]],\n"
         "    ushort tiisg [[thread_index_in_simdgroup]],\n"
         "    ushort sgitg [[simdgroup_index_in_threadgroup]],\n"
         "    uint   tpitg [[thread_position_in_threadgroup]]) {\n"
         "  /* Each simdgroup fills a separate 8x8 block in threadgroup memory:\n"
         "   *   sg 0: shmem[0..63] = A0, shmem[64..127] = B0\n"
         "   *   sg 1: shmem[128..191] = A1, shmem[192..255] = B1\n"
         "   * Each lane in the simdgroup writes 2 floats to A and 2 to B (=1.0f).\n"
         "   * Then simdgroup_load + multiply + store; verify all 64 cells = 8. */\n"
         "  const uint sg_off = (uint)sgitg * 128;  /* 64 A + 64 B */\n"
         "  /* Init: 64 lanes per matrix × 2 simdgroups = 128 cells but we only\n"
         "   * have 32 lanes; each lane writes 2 cells (a0 and a32, b0 and b32) */\n"
         "  shmem[sg_off + tiisg] = 1.0f;\n"
         "  shmem[sg_off + 32 + tiisg] = 1.0f;\n"
         "  shmem[sg_off + 64 + tiisg] = 1.0f;\n"
         "  shmem[sg_off + 64 + 32 + tiisg] = 1.0f;\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "\n"
         "  simdgroup_float8x8 mA, mB;\n"
         "  simdgroup_float8x8 mC = make_filled_simdgroup_matrix<float, 8>(0.0f);\n"
         "  /* Origin (0,0); stride 8 (8 floats per row of the 8x8 tile). */\n"
         "  simdgroup_load(mA, shmem + sg_off, 8, ulong2(0, 0), false);\n"
         "  simdgroup_load(mB, shmem + sg_off + 64, 8, ulong2(0, 0), false);\n"
         "  simdgroup_multiply_accumulate(mC, mA, mB, mC);\n"
         "  /* Store mC into shmem at the same A slot (overwrites the all-1 A) */\n"
         "  simdgroup_store(mC, shmem + sg_off, 8, ulong2(0, 0), false);\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "\n"
         "  /* Each lane writes 2 of the 64 C cells to device dst[sgitg*64 + i] */\n"
         "  dst[sgitg * 64 + tiisg] = shmem[sg_off + tiisg];\n"
         "  dst[sgitg * 64 + 32 + tiisg] = shmem[sg_off + 32 + tiisg];\n"
         "}\n";
    g_mma_iso_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_mma_iso_mtl4", @"mma_iso_mtl4", 1024, NULL, 0);
    g_mma_iso_mtl4_init_ok = (g_mma_iso_mtl4_pipeline != nil) ? 1 : 0;
    return g_mma_iso_mtl4_init_ok;
}

int ds4_gpu_mtl4_mma_iso_canary(uint32_t n_sg) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_mma_iso_mtl4_pipeline_init()) return 0;
    if (n_sg == 0 || n_sg > 32) return 0;

    const uint32_t n_threads = n_sg * 32;
    const uint32_t n_cells = n_sg * 64;
    float *host_dst = (float *)calloc(n_cells, sizeof(float));
    if (!host_dst) return 0;

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> dstBuf = [g_device newBufferWithLength:n_cells*sizeof(float) options:MTLResourceStorageModeShared];
        /* Sentinel fill */
        float *pre = (float *)dstBuf.contents;
        for (uint32_t i = 0; i < n_cells; i++) pre[i] = -999.0f;

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 2;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[1] = {(id)dstBuf};
            [residency addAllocations:allocs count:1];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(2);
            if (argTable) {
                [argTable setAddress:dstBuf.gpuAddress atIndex:0];

                /* shmem: n_sg simdgroups × 128 floats = 512 bytes per simdgroup */
                NSUInteger shmem_bytes = (NSUInteger)n_sg * 128u * sizeof(float);

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_mma_iso_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc setThreadgroupMemoryLength:shmem_bytes atIndex:0];
                [enc dispatchThreadgroups:MTLSizeMake(1, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(n_threads, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) { (void)fb; dispatch_semaphore_signal(sem); }];
                id<MTL4CommandBuffer> bufs[1] = {cb};
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 5LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_dst, dstBuf.contents, n_cells * sizeof(float));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 2);
            }
        }
    }
    if (!rc) { free(host_dst); return 0; }

    /* Expected: every cell = 8.0 (dot of 8 ones × 8 ones). Sentinel was -999. */
    int n_eight = 0, n_sentinel = 0, n_other = 0;
    int first_8 = -1, first_sentinel = -1;
    for (uint32_t i = 0; i < n_cells; i++) {
        if (host_dst[i] == 8.0f) { n_eight++; if (first_8 < 0) first_8 = (int)i; }
        else if (host_dst[i] == -999.0f) { n_sentinel++; if (first_sentinel < 0) first_sentinel = (int)i; }
        else n_other++;
    }
    fprintf(stderr,
        "ds4: mma_iso canary n_sg=%u n_threads=%u n_cells=%u: "
        "n_eight=%d n_sentinel=%d n_other=%d first_8=%d first_sentinel=%d\n",
        n_sg, n_threads, n_cells, n_eight, n_sentinel, n_other, first_8, first_sentinel);
    /* First 16 cells for inspection */
    fprintf(stderr, "  dst[0..15] = ");
    for (int i = 0; i < 16 && i < (int)n_cells; i++) fprintf(stderr, "%.1f ", (double)host_dst[i]);
    fprintf(stderr, "\n");
    free(host_dst);
    return (n_eight == (int)n_cells) ? 1 : 0;
}

/* ============================================================ */
/* dsv4_indexer_scores_tiled_f32 MTL4 port (silv 2026-05-28 #730) */
/* ============================================================ */
/* THE SIMDGROUP MMA UNBLOCKER. Prior #701 deferral was based on a
 * wrong diagnosis (thought lanes 8-31 didn't fire — they do). MMA
 * itself works in MTL4 (verified by --mma-iso). Re-attempting the
 * port now with the established FC/helper pattern.
 *
 * Computes indexer scores: for each (token, comp) tile, accumulate
 * over all heads:
 *   s = max(<Q[t, head, :], K[c, :]>, 0) * weights[t, head] * scale
 *   scores[t, c] = sum_head s  (with causal mask via pos0/ratio).
 *
 * Dispatch: (ceil(n_comp/32), ceil(n_tokens/8), 1) × 128 threads.
 * Threadgroup memory: 8×D + 32×D + 8×32 floats = ~21 KB at D=128.
 * Uses 4 simdgroups: each sg handles 8 components out of TN=32. */

static id<MTLComputePipelineState> g_indexer_scores_tiled_f32_mtl4_pipeline;
static int g_indexer_scores_tiled_f32_mtl4_init_attempted;
static int g_indexer_scores_tiled_f32_mtl4_init_ok;

static int ds4_indexer_scores_tiled_f32_mtl4_pipeline_init(void) {
    if (g_indexer_scores_tiled_f32_mtl4_init_attempted) return g_indexer_scores_tiled_f32_mtl4_init_ok;
    g_indexer_scores_tiled_f32_mtl4_init_attempted = 1;

    NSString *source =
        @"#include <metal_stdlib>\n"
         "#include <metal_simdgroup_matrix>\n"
         "using namespace metal;\n"
         "struct sf_args {\n"
         "  uint n_comp; uint n_tokens; uint n_head; uint head_dim;\n"
         "  uint pos0; uint ratio;\n"
         "  ulong q_token_stride; ulong q_head_stride;\n"
         "  ulong weights_token_stride;\n"
         "  ulong index_row_stride;\n"
         "  ulong score_token_stride;\n"
         "  float scale;\n"
         "};\n"
         "kernel void indexer_scores_tiled_f32_mtl4(\n"
         "    device const sf_args *args      [[buffer(0)]],\n"
         "    device const char    *q         [[buffer(1)]],\n"
         "    device const char    *weights   [[buffer(2)]],\n"
         "    device const char    *index_comp[[buffer(3)]],\n"
         "    device       char    *scores    [[buffer(4)]],\n"
         "    threadgroup  float   *shared    [[threadgroup(0)]],\n"
         "    uint2  tgpig [[threadgroup_position_in_grid]],\n"
         "    ushort tid   [[thread_index_in_threadgroup]],\n"
         "    ushort lane  [[thread_index_in_simdgroup]],\n"
         "    ushort sg    [[simdgroup_index_in_threadgroup]]) {\n"
         "  constexpr uint TM = 8;\n"
         "  constexpr uint TN = 32;\n"
         "  constexpr uint TS = 8;\n"
         "  constexpr uint D = 128;\n"
         "  const uint c0 = tgpig.x * TN;\n"
         "  const uint t0 = tgpig.y * TM;\n"
         "  threadgroup float *qtg = shared;\n"
         "  threadgroup float *ktg = qtg + TM*D;\n"
         "  threadgroup float *dot = ktg + TN*D;\n"
         "  const uint last_token = min(t0 + TM, args->n_tokens);\n"
         "  const uint max_visible = last_token > t0 ?\n"
         "    min((args->pos0 + last_token) / args->ratio, args->n_comp) : 0u;\n"
         "  if (c0 >= max_visible) {\n"
         "    for (uint i = tid; i < TM*TN; i += 128) {\n"
         "      const uint r = i / TN;\n"
         "      const uint cc = i - r*TN;\n"
         "      const uint token = t0 + r;\n"
         "      const uint comp = c0 + cc;\n"
         "      if (token < args->n_tokens && comp < args->n_comp) {\n"
         "        device float *dst = (device float *)(scores +\n"
         "          (ulong)token * args->score_token_stride) + comp;\n"
         "        *dst = -INFINITY;\n"
         "      }\n"
         "    }\n"
         "    return;\n"
         "  }\n"
         "  for (uint i = tid; i < TN*D; i += 128) {\n"
         "    const uint cc = i / D;\n"
         "    const uint d = i - cc*D;\n"
         "    const uint comp = c0 + cc;\n"
         "    float v = 0.0f;\n"
         "    if (comp < args->n_comp) {\n"
         "      device const float *row = (device const float *)(index_comp +\n"
         "        (ulong)comp * args->index_row_stride);\n"
         "      v = row[d];\n"
         "    }\n"
         "    ktg[i] = v;\n"
         "  }\n"
         "  const uint cell0 = lane;\n"
         "  const uint cell1 = lane + 32u;\n"
         "  const uint row0 = cell0 >> 3;\n"
         "  const uint row1 = cell1 >> 3;\n"
         "  const uint sub0 = cell0 & 7u;\n"
         "  const uint sub1 = cell1 & 7u;\n"
         "  const uint col0 = (uint)sg * TS + sub0;\n"
         "  const uint col1 = (uint)sg * TS + sub1;\n"
         "  const uint token0 = t0 + row0;\n"
         "  const uint token1 = t0 + row1;\n"
         "  const uint comp0 = c0 + col0;\n"
         "  const uint comp1 = c0 + col1;\n"
         "  float acc0 = 0.0f;\n"
         "  float acc1 = 0.0f;\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  for (uint head = 0; head < args->n_head; head++) {\n"
         "    for (uint i = tid; i < TM*D; i += 128) {\n"
         "      const uint r = i / D;\n"
         "      const uint d = i - r*D;\n"
         "      const uint token = t0 + r;\n"
         "      float v = 0.0f;\n"
         "      if (token < args->n_tokens) {\n"
         "        device const float *qrow = (device const float *)(q +\n"
         "          (ulong)token * args->q_token_stride +\n"
         "          (ulong)head * args->q_head_stride);\n"
         "        v = qrow[d];\n"
         "      }\n"
         "      qtg[i] = v;\n"
         "    }\n"
         "    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "    simdgroup_float8x8 mdot = make_filled_simdgroup_matrix<float, 8>(0.0f);\n"
         "    for (uint db = 0; db < D/TS; db++) {\n"
         "      simdgroup_float8x8 mq;\n"
         "      simdgroup_float8x8 mk;\n"
         "      simdgroup_load(mq, qtg + db*TS, D, ulong2(0, 0), false);\n"
         "      simdgroup_load(mk, ktg + ((uint)sg * TS) * D + db*TS, D, ulong2(0, 0), true);\n"
         "      simdgroup_multiply_accumulate(mdot, mq, mk, mdot);\n"
         "    }\n"
         "    simdgroup_store(mdot, dot + (uint)sg * TS, TN, ulong2(0, 0), false);\n"
         "    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "    if (token0 < args->n_tokens && comp0 < args->n_comp) {\n"
         "      device const float *w = (device const float *)(weights +\n"
         "        (ulong)token0 * args->weights_token_stride);\n"
         "      const float s = dot[row0*TN + col0];\n"
         "      acc0 += max(s, 0.0f) * (w[head] * args->scale);\n"
         "    }\n"
         "    if (token1 < args->n_tokens && comp1 < args->n_comp) {\n"
         "      device const float *w = (device const float *)(weights +\n"
         "        (ulong)token1 * args->weights_token_stride);\n"
         "      const float s = dot[row1*TN + col1];\n"
         "      acc1 += max(s, 0.0f) * (w[head] * args->scale);\n"
         "    }\n"
         "    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  }\n"
         "  if (token0 < args->n_tokens && comp0 < args->n_comp) {\n"
         "    const uint visible = min((args->pos0 + token0 + 1u) / args->ratio, args->n_comp);\n"
         "    device float *dst = (device float *)(scores +\n"
         "      (ulong)token0 * args->score_token_stride) + comp0;\n"
         "    *dst = comp0 < visible ? acc0 : -INFINITY;\n"
         "  }\n"
         "  if (token1 < args->n_tokens && comp1 < args->n_comp) {\n"
         "    const uint visible = min((args->pos0 + token1 + 1u) / args->ratio, args->n_comp);\n"
         "    device float *dst = (device float *)(scores +\n"
         "      (ulong)token1 * args->score_token_stride) + comp1;\n"
         "    *dst = comp1 < visible ? acc1 : -INFINITY;\n"
         "  }\n"
         "}\n";
    g_indexer_scores_tiled_f32_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_indexer_scores_tiled_f32_mtl4", @"indexer_scores_tiled_f32_mtl4", 1024, NULL, 0);
    g_indexer_scores_tiled_f32_mtl4_init_ok = (g_indexer_scores_tiled_f32_mtl4_pipeline != nil) ? 1 : 0;
    return g_indexer_scores_tiled_f32_mtl4_init_ok;
}

int ds4_gpu_mtl4_indexer_scores_tiled_f32_canary(uint32_t n_tokens, uint32_t n_comp, uint32_t n_head) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_indexer_scores_tiled_f32_mtl4_pipeline_init()) return 0;
    if (n_tokens == 0 || n_comp == 0 || n_head == 0) return 0;
    if ((n_tokens % 8) != 0 || (n_comp % 32) != 0) {
        fprintf(stderr, "ds4: indexer_scores canary needs n_tokens%%8==0, n_comp%%32==0 (got %u, %u)\n", n_tokens, n_comp);
        return 0;
    }
    const uint32_t D = 128;
    const uint64_t q_total = (uint64_t)n_tokens * n_head * D;
    const uint64_t k_total = (uint64_t)n_comp * D;
    const uint64_t w_total = (uint64_t)n_tokens * n_head;
    const uint64_t s_total = (uint64_t)n_tokens * n_comp;

    float *host_q = (float *)calloc(q_total, sizeof(float));
    float *host_k = (float *)calloc(k_total, sizeof(float));
    float *host_w = (float *)calloc(w_total, sizeof(float));
    float *host_s = (float *)calloc(s_total, sizeof(float));
    if (!host_q || !host_k || !host_w || !host_s) {
        free(host_q); free(host_k); free(host_w); free(host_s); return 0;
    }
    /* All-ones pattern: each cell s = D = 128; per-head contribution = 128 * 1.0 * 1.0 = 128.
     * Sum over n_head heads: 128 * n_head. */
    for (uint64_t i = 0; i < q_total; i++) host_q[i] = 1.0f;
    for (uint64_t i = 0; i < k_total; i++) host_k[i] = 1.0f;
    for (uint64_t i = 0; i < w_total; i++) host_w[i] = 1.0f;

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:128 options:MTLResourceStorageModeShared];
        id<MTLBuffer> qBuf = [g_device newBufferWithBytes:host_q length:q_total*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> kBuf = [g_device newBufferWithBytes:host_k length:k_total*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> wBuf = [g_device newBufferWithBytes:host_w length:w_total*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> sBuf = [g_device newBufferWithLength:s_total*sizeof(float) options:MTLResourceStorageModeShared];

        struct {
            uint32_t n_comp, n_tokens, n_head, head_dim;
            uint32_t pos0, ratio;
            uint64_t q_token_stride, q_head_stride;
            uint64_t weights_token_stride;
            uint64_t index_row_stride;
            uint64_t score_token_stride;
            float scale;
        } args;
        memset(&args, 0, sizeof(args));
        args.n_comp = n_comp; args.n_tokens = n_tokens; args.n_head = n_head; args.head_dim = D;
        /* Bypass causal mask: pos0 huge, ratio=1 → max_visible = min(pos0 + token + 1, n_comp)
         * = n_comp for every token. Every cell is computed (no -INFINITY). */
        args.pos0 = 1u << 30;
        args.ratio = 1;
        args.q_token_stride = (uint64_t)n_head * D * sizeof(float);
        args.q_head_stride = (uint64_t)D * sizeof(float);
        args.weights_token_stride = (uint64_t)n_head * sizeof(float);
        args.index_row_stride = (uint64_t)D * sizeof(float);
        args.score_token_stride = (uint64_t)n_comp * sizeof(float);
        args.scale = 1.0f;
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 6;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[5] = {(id)argsBuf, (id)qBuf, (id)kBuf, (id)wBuf, (id)sBuf};
            [residency addAllocations:allocs count:5];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(8);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:qBuf.gpuAddress atIndex:1];
                [argTable setAddress:wBuf.gpuAddress atIndex:2];
                [argTable setAddress:kBuf.gpuAddress atIndex:3];
                [argTable setAddress:sBuf.gpuAddress atIndex:4];

                /* shmem: TM*D + TN*D + TM*TN = (8+32)*128 + 8*32 = 5120 + 256 = 5376 floats
                 * = 21504 bytes. M1 has 32KB threadgroup memory, so fits. */
                NSUInteger shmem_bytes = (40 * 128 + 8 * 32) * sizeof(float);

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_indexer_scores_tiled_f32_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc setThreadgroupMemoryLength:shmem_bytes atIndex:0];
                [enc dispatchThreadgroups:MTLSizeMake(n_comp / 32, n_tokens / 8, 1)
                    threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) { (void)fb; dispatch_semaphore_signal(sem); }];
                id<MTL4CommandBuffer> bufs[1] = {cb};
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 10LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_s, sBuf.contents, s_total * sizeof(float));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 8);
            }
        }
    }
    if (!rc) { free(host_q); free(host_k); free(host_w); free(host_s); return 0; }

    const float expected = (float)D * (float)n_head;
    int n_match = 0, n_zero = 0, n_neg_inf = 0, n_other = 0;
    int first_other = -1;
    float first_other_v = 0.0f;
    for (uint64_t i = 0; i < s_total; i++) {
        const float v = host_s[i];
        if (v == expected) n_match++;
        else if (v == 0.0f) n_zero++;
        else if (v == -INFINITY) n_neg_inf++;
        else {
            n_other++;
            if (first_other < 0) { first_other = (int)i; first_other_v = v; }
        }
    }
    fprintf(stderr,
        "ds4: indexer_scores_tiled_f32 MTL4 canary n_tokens=%u n_comp=%u n_head=%u "
        "expected=%.1f match=%d zero=%d -inf=%d other=%d first_other_v=%.4f\n",
        n_tokens, n_comp, n_head,
        (double)expected, n_match, n_zero, n_neg_inf, n_other, (double)first_other_v);
    fprintf(stderr, "  s[0..3] = %.1f %.1f %.1f %.1f s[last]=%.1f\n",
        (double)host_s[0], (double)host_s[1], (double)host_s[2], (double)host_s[3],
        (double)host_s[s_total - 1]);
    free(host_q); free(host_k); free(host_w); free(host_s);
    return (n_match == (int)s_total) ? 1 : 0;
}

/* ============================================================ */
/* dsv4_indexer_scores_tiled MTL4 port (silv 2026-05-28 #731)   */
/* ============================================================ */
/* Half-precision Q/K staging variant of #730. The Q and K tiles
 * downcast to half before MMA; dot accumulator and final score
 * stay float. Long-context profiling identified the indexer score
 * matrix as prefill-slope dominant, so this trades ~1e-3 relative
 * error in the ranking for a ~2× MMA throughput improvement. */

static id<MTLComputePipelineState> g_indexer_scores_tiled_mtl4_pipeline;
static int g_indexer_scores_tiled_mtl4_init_attempted;
static int g_indexer_scores_tiled_mtl4_init_ok;

static int ds4_indexer_scores_tiled_mtl4_pipeline_init(void) {
    if (g_indexer_scores_tiled_mtl4_init_attempted) return g_indexer_scores_tiled_mtl4_init_ok;
    g_indexer_scores_tiled_mtl4_init_attempted = 1;

    NSString *source =
        @"#include <metal_stdlib>\n"
         "#include <metal_simdgroup_matrix>\n"
         "using namespace metal;\n"
         "struct sf_args {\n"
         "  uint n_comp; uint n_tokens; uint n_head; uint head_dim;\n"
         "  uint pos0; uint ratio;\n"
         "  ulong q_token_stride; ulong q_head_stride;\n"
         "  ulong weights_token_stride;\n"
         "  ulong index_row_stride;\n"
         "  ulong score_token_stride;\n"
         "  float scale;\n"
         "};\n"
         "kernel void indexer_scores_tiled_mtl4(\n"
         "    device const sf_args *args      [[buffer(0)]],\n"
         "    device const char    *q         [[buffer(1)]],\n"
         "    device const char    *weights   [[buffer(2)]],\n"
         "    device const char    *index_comp[[buffer(3)]],\n"
         "    device       char    *scores    [[buffer(4)]],\n"
         "    threadgroup  float   *shared    [[threadgroup(0)]],\n"
         "    uint2  tgpig [[threadgroup_position_in_grid]],\n"
         "    ushort tid   [[thread_index_in_threadgroup]],\n"
         "    ushort lane  [[thread_index_in_simdgroup]],\n"
         "    ushort sg    [[simdgroup_index_in_threadgroup]]) {\n"
         "  constexpr uint TM = 8;\n"
         "  constexpr uint TN = 32;\n"
         "  constexpr uint TS = 8;\n"
         "  constexpr uint D = 128;\n"
         "  const uint c0 = tgpig.x * TN;\n"
         "  const uint t0 = tgpig.y * TM;\n"
         "  threadgroup half *qtg = (threadgroup half *)shared;\n"
         "  threadgroup half *ktg = qtg + TM*D;\n"
         "  threadgroup float *dot = (threadgroup float *)(ktg + TN*D);\n"
         "  const uint last_token = min(t0 + TM, args->n_tokens);\n"
         "  const uint max_visible = last_token > t0 ?\n"
         "    min((args->pos0 + last_token) / args->ratio, args->n_comp) : 0u;\n"
         "  if (c0 >= max_visible) {\n"
         "    for (uint i = tid; i < TM*TN; i += 128) {\n"
         "      const uint r = i / TN;\n"
         "      const uint cc = i - r*TN;\n"
         "      const uint token = t0 + r;\n"
         "      const uint comp = c0 + cc;\n"
         "      if (token < args->n_tokens && comp < args->n_comp) {\n"
         "        device float *dst = (device float *)(scores +\n"
         "          (ulong)token * args->score_token_stride) + comp;\n"
         "        *dst = -INFINITY;\n"
         "      }\n"
         "    }\n"
         "    return;\n"
         "  }\n"
         "  for (uint i = tid; i < TN*D; i += 128) {\n"
         "    const uint cc = i / D;\n"
         "    const uint d = i - cc*D;\n"
         "    const uint comp = c0 + cc;\n"
         "    half v = half(0.0f);\n"
         "    if (comp < args->n_comp) {\n"
         "      device const float *row = (device const float *)(index_comp +\n"
         "        (ulong)comp * args->index_row_stride);\n"
         "      v = half(row[d]);\n"
         "    }\n"
         "    ktg[i] = v;\n"
         "  }\n"
         "  const uint cell0 = lane;\n"
         "  const uint cell1 = lane + 32u;\n"
         "  const uint row0 = cell0 >> 3;\n"
         "  const uint row1 = cell1 >> 3;\n"
         "  const uint sub0 = cell0 & 7u;\n"
         "  const uint sub1 = cell1 & 7u;\n"
         "  const uint col0 = (uint)sg * TS + sub0;\n"
         "  const uint col1 = (uint)sg * TS + sub1;\n"
         "  const uint token0 = t0 + row0;\n"
         "  const uint token1 = t0 + row1;\n"
         "  const uint comp0 = c0 + col0;\n"
         "  const uint comp1 = c0 + col1;\n"
         "  float acc0 = 0.0f;\n"
         "  float acc1 = 0.0f;\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  for (uint head = 0; head < args->n_head; head++) {\n"
         "    for (uint i = tid; i < TM*D; i += 128) {\n"
         "      const uint r = i / D;\n"
         "      const uint d = i - r*D;\n"
         "      const uint token = t0 + r;\n"
         "      half v = half(0.0f);\n"
         "      if (token < args->n_tokens) {\n"
         "        device const float *qrow = (device const float *)(q +\n"
         "          (ulong)token * args->q_token_stride +\n"
         "          (ulong)head * args->q_head_stride);\n"
         "        v = half(qrow[d]);\n"
         "      }\n"
         "      qtg[i] = v;\n"
         "    }\n"
         "    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "    simdgroup_float8x8 mdot = make_filled_simdgroup_matrix<float, 8>(0.0f);\n"
         "    for (uint db = 0; db < D/TS; db++) {\n"
         "      simdgroup_half8x8 mq;\n"
         "      simdgroup_half8x8 mk;\n"
         "      simdgroup_load(mq, qtg + db*TS, D, ulong2(0, 0), false);\n"
         "      simdgroup_load(mk, ktg + ((uint)sg * TS) * D + db*TS, D, ulong2(0, 0), true);\n"
         "      simdgroup_multiply_accumulate(mdot, mq, mk, mdot);\n"
         "    }\n"
         "    simdgroup_store(mdot, dot + (uint)sg * TS, TN, ulong2(0, 0), false);\n"
         "    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "    if (token0 < args->n_tokens && comp0 < args->n_comp) {\n"
         "      device const float *w = (device const float *)(weights +\n"
         "        (ulong)token0 * args->weights_token_stride);\n"
         "      const float s = dot[row0*TN + col0];\n"
         "      acc0 += max(s, 0.0f) * (w[head] * args->scale);\n"
         "    }\n"
         "    if (token1 < args->n_tokens && comp1 < args->n_comp) {\n"
         "      device const float *w = (device const float *)(weights +\n"
         "        (ulong)token1 * args->weights_token_stride);\n"
         "      const float s = dot[row1*TN + col1];\n"
         "      acc1 += max(s, 0.0f) * (w[head] * args->scale);\n"
         "    }\n"
         "    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  }\n"
         "  if (token0 < args->n_tokens && comp0 < args->n_comp) {\n"
         "    const uint visible = min((args->pos0 + token0 + 1u) / args->ratio, args->n_comp);\n"
         "    device float *dst = (device float *)(scores +\n"
         "      (ulong)token0 * args->score_token_stride) + comp0;\n"
         "    *dst = comp0 < visible ? acc0 : -INFINITY;\n"
         "  }\n"
         "  if (token1 < args->n_tokens && comp1 < args->n_comp) {\n"
         "    const uint visible = min((args->pos0 + token1 + 1u) / args->ratio, args->n_comp);\n"
         "    device float *dst = (device float *)(scores +\n"
         "      (ulong)token1 * args->score_token_stride) + comp1;\n"
         "    *dst = comp1 < visible ? acc1 : -INFINITY;\n"
         "  }\n"
         "}\n";
    g_indexer_scores_tiled_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_indexer_scores_tiled_mtl4", @"indexer_scores_tiled_mtl4", 1024, NULL, 0);
    g_indexer_scores_tiled_mtl4_init_ok = (g_indexer_scores_tiled_mtl4_pipeline != nil) ? 1 : 0;
    return g_indexer_scores_tiled_mtl4_init_ok;
}

int ds4_gpu_mtl4_indexer_scores_tiled_canary(uint32_t n_tokens, uint32_t n_comp, uint32_t n_head) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_indexer_scores_tiled_mtl4_pipeline_init()) return 0;
    if ((n_tokens % 8) != 0 || (n_comp % 32) != 0) return 0;
    const uint32_t D = 128;
    const uint64_t q_total = (uint64_t)n_tokens * n_head * D;
    const uint64_t k_total = (uint64_t)n_comp * D;
    const uint64_t w_total = (uint64_t)n_tokens * n_head;
    const uint64_t s_total = (uint64_t)n_tokens * n_comp;

    float *host_q = (float *)calloc(q_total, sizeof(float));
    float *host_k = (float *)calloc(k_total, sizeof(float));
    float *host_w = (float *)calloc(w_total, sizeof(float));
    float *host_s = (float *)calloc(s_total, sizeof(float));
    if (!host_q || !host_k || !host_w || !host_s) {
        free(host_q); free(host_k); free(host_w); free(host_s); return 0;
    }
    for (uint64_t i = 0; i < q_total; i++) host_q[i] = 1.0f;
    for (uint64_t i = 0; i < k_total; i++) host_k[i] = 1.0f;
    for (uint64_t i = 0; i < w_total; i++) host_w[i] = 1.0f;

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:128 options:MTLResourceStorageModeShared];
        id<MTLBuffer> qBuf = [g_device newBufferWithBytes:host_q length:q_total*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> kBuf = [g_device newBufferWithBytes:host_k length:k_total*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> wBuf = [g_device newBufferWithBytes:host_w length:w_total*sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> sBuf = [g_device newBufferWithLength:s_total*sizeof(float) options:MTLResourceStorageModeShared];

        struct {
            uint32_t n_comp, n_tokens, n_head, head_dim;
            uint32_t pos0, ratio;
            uint64_t q_token_stride, q_head_stride;
            uint64_t weights_token_stride;
            uint64_t index_row_stride;
            uint64_t score_token_stride;
            float scale;
        } args;
        memset(&args, 0, sizeof(args));
        args.n_comp = n_comp; args.n_tokens = n_tokens; args.n_head = n_head; args.head_dim = D;
        args.pos0 = 1u << 30; args.ratio = 1;  /* bypass causal mask */
        args.q_token_stride = (uint64_t)n_head * D * sizeof(float);
        args.q_head_stride = (uint64_t)D * sizeof(float);
        args.weights_token_stride = (uint64_t)n_head * sizeof(float);
        args.index_row_stride = (uint64_t)D * sizeof(float);
        args.score_token_stride = (uint64_t)n_comp * sizeof(float);
        args.scale = 1.0f;
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 6;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[5] = {(id)argsBuf, (id)qBuf, (id)kBuf, (id)wBuf, (id)sBuf};
            [residency addAllocations:allocs count:5];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(8);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:qBuf.gpuAddress atIndex:1];
                [argTable setAddress:wBuf.gpuAddress atIndex:2];
                [argTable setAddress:kBuf.gpuAddress atIndex:3];
                [argTable setAddress:sBuf.gpuAddress atIndex:4];

                /* shmem: half tiles + float dot. (8 + 32) × 128 halves + 8 × 32 floats
                 * = 40 × 128 × 2 + 256 × 4 = 10240 + 1024 = 11264 bytes. */
                NSUInteger shmem_bytes = 40u * 128u * sizeof(uint16_t) + 8u * 32u * sizeof(float);

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_indexer_scores_tiled_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc setThreadgroupMemoryLength:shmem_bytes atIndex:0];
                [enc dispatchThreadgroups:MTLSizeMake(n_comp / 32, n_tokens / 8, 1)
                    threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) { (void)fb; dispatch_semaphore_signal(sem); }];
                id<MTL4CommandBuffer> bufs[1] = {cb};
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 10LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_s, sBuf.contents, s_total * sizeof(float));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 8);
            }
        }
    }
    if (!rc) { free(host_q); free(host_k); free(host_w); free(host_s); return 0; }

    /* FP16-tile MMA expected result: D × n_head exactly (1.0 × 1.0 = 1.0 in half is exact).
     * For non-trivial inputs there's ~3e-4 relative noise. For all-ones, expect exact. */
    const float expected = (float)D * (float)n_head;
    int n_match = 0, n_other = 0;
    double max_rel = 0.0;
    for (uint64_t i = 0; i < s_total; i++) {
        const double d = fabs((double)(host_s[i] - expected));
        const double rel = d / (fabs((double)expected) + 1e-7);
        if (rel > max_rel) max_rel = rel;
        if (rel < 1e-3) n_match++;
        else n_other++;
    }
    fprintf(stderr,
        "ds4: indexer_scores_tiled MTL4 canary n_tokens=%u n_comp=%u n_head=%u "
        "expected=%.1f match=%d other=%d max_rel=%.4e s[0]=%.2f\n",
        n_tokens, n_comp, n_head, (double)expected, n_match, n_other, max_rel, (double)host_s[0]);
    free(host_q); free(host_k); free(host_w); free(host_s);
    return (n_match == (int)s_total) ? 1 : 0;
}

/* ============================================================ */
/* mul_mm_f16_f32 MTL4 port (silv 2026-05-28 #732 — production matmul) */
/* ============================================================ */
/* Dense f16-weight × f16-input → float-output GEMM at 64×32×32 tile.
 * Uses simdgroup_half8x8 MMA in 8-tile spilled output (NR0=64, NR1=32,
 * NK=32 per loop). 4 simdgroups × 32 lanes = 128 threads/tg. Threadgroup
 * memory: 4 KB for B-side tile (sa) + 2 KB for A-side tile (sb) = 6 KB
 * minimum (helper uses 4096-byte stride). Specialized for FP16 with
 * is_same<T0_4x4, block_q> compile-time true → no dequant needed at all.
 * FCs hardcoded: FC_mul_mm_bc_inp=true, FC_mul_mm_bc_out=true (full
 * bounds-checked path) so dimensions that aren't multiples of NR0/NR1
 * also work. */

static id<MTLComputePipelineState> g_mul_mm_f16_f32_mtl4_pipeline;
static int g_mul_mm_f16_f32_mtl4_init_attempted;
static int g_mul_mm_f16_f32_mtl4_init_ok;

static int ds4_mul_mm_f16_f32_mtl4_pipeline_init(void) {
    if (g_mul_mm_f16_f32_mtl4_init_attempted) return g_mul_mm_f16_f32_mtl4_init_ok;
    g_mul_mm_f16_f32_mtl4_init_attempted = 1;

    /* The template uses simdgroup_half8x8 for both A and B sides at FP16
     * and simdgroup_float8x8 for accumulators. FC values 700/701 are set
     * via the FC pattern. Inline the dequantize_f16 as the identity
     * since for FP16 the block_q == T0_4x4 = half4x4. */
    NSString *source = [NSString stringWithFormat:
        @"#include <metal_stdlib>\n"
         "#include <metal_simdgroup_matrix>\n"
         "using namespace metal;\n"
         "#define FC_MUL_MM 700\n"
         "constant short FC_mul_mm_bc_inp [[function_constant(FC_MUL_MM + 0)]];\n"
         "constant short FC_mul_mm_bc_out [[function_constant(FC_MUL_MM + 1)]];\n"
         "struct mm_args {\n"
         "  int ne00; int ne02;\n"
         "  ulong nb01; ulong nb02; ulong nb03;\n"
         "  int ne12;\n"
         "  ulong nb10; ulong nb11; ulong nb12; ulong nb13;\n"
         "  int ne0; int ne1;\n"
         "  short r2; short r3;\n"
         "};\n"
         "kernel void mul_mm_f16_f32_mtl4(\n"
         "    device const mm_args *args [[buffer(0)]],\n"
         "    device const char    *src0 [[buffer(1)]],\n"
         "    device const char    *src1 [[buffer(2)]],\n"
         "    device       char    *dst  [[buffer(3)]],\n"
         "    threadgroup  char    *shmem [[threadgroup(0)]],\n"
         "    uint3   tgpig [[threadgroup_position_in_grid]],\n"
         "    ushort  tiitg [[thread_index_in_threadgroup]],\n"
         "    ushort  sgitg [[simdgroup_index_in_threadgroup]]) {\n"
         "  threadgroup half *sa = (threadgroup half *)(shmem);\n"
         "  threadgroup half *sb = (threadgroup half *)(shmem + 4096);\n"
         "  constexpr int NR0 = 64;\n"
         "  constexpr int NR1 = 32;\n"
         "  constexpr int NK  = 32;\n"
         "  constexpr int NL0 = NK/16;\n"
         "  constexpr int NL1 = NK/8;\n"
         "  const int im = tgpig.z;\n"
         "  const int r0 = tgpig.y*NR0;\n"
         "  const int r1 = tgpig.x*NR1;\n"
         "  const short nr0 = (args->ne0 - r0 < NR0) ? (args->ne0 - r0) : NR0;\n"
         "  const short nr1 = (args->ne1 - r1 < NR1) ? (args->ne1 - r1) : NR1;\n"
         "  const short lr0 = ((short)tiitg/NL0) < nr0 ? ((short)tiitg/NL0) : nr0 - 1;\n"
         "  const short lr1 = ((short)tiitg/NL1) < nr1 ? ((short)tiitg/NL1) : nr1 - 1;\n"
         "  const short il0 = (tiitg %% NL0);\n"
         "  short il = il0;\n"
         "  const int i12 = im %% args->ne12;\n"
         "  const int i13 = im / args->ne12;\n"
         "  const ulong offset0 = (i12/args->r2)*args->nb02 + (i13/args->r3)*args->nb03;\n"
         "  const short offset1 = il0/1;\n"
         "  device const half4x4 *x = (device const half4x4 *)\n"
         "    (src0 + args->nb01*(r0 + lr0) + offset0) + offset1;\n"
         "  const short iy = 8*(tiitg %% NL1);\n"
         "  device const half *y = (device const half *)(src1\n"
         "    + args->nb13*i13 + args->nb12*i12 + args->nb11*(r1 + lr1) + args->nb10*iy);\n"
         "  simdgroup_half8x8 ma[4];\n"
         "  simdgroup_half8x8 mb[2];\n"
         "  simdgroup_float8x8 mc[8];\n"
         "  for (short i = 0; i < 8; i++) mc[i] = make_filled_simdgroup_matrix<float, 8>(0.0f);\n"
         "  for (int loop_k = 0; loop_k < args->ne00; loop_k += NK) {\n"
         "    /* FP16: is_same<half4x4, block_q> == true compile-time. Use direct half4x4 read. */\n"
         "    if (FC_mul_mm_bc_inp) {\n"
         "      threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "      for (short i = 0; i < 16; i++) {\n"
         "        const short sx = 2*il0 + i/8;\n"
         "        const short sy = (tiitg/NL0)/8;\n"
         "        const short lx = (tiitg/NL0)%%8;\n"
         "        const short ly = i%%8;\n"
         "        const short ib = 8*sx + sy;\n"
         "        *(sa + 64*ib + 8*ly + lx) = loop_k + 16*il + i < args->ne00 ? *((device half *)x + i) : half(0);\n"
         "      }\n"
         "    } else {\n"
         "      half4x4 temp_a = *x;\n"
         "      threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "      for (short i = 0; i < 16; i++) {\n"
         "        const short sx = 2*il0 + i/8;\n"
         "        const short sy = (tiitg/NL0)/8;\n"
         "        const short lx = (tiitg/NL0)%%8;\n"
         "        const short ly = i%%8;\n"
         "        const short ib = 8*sx + sy;\n"
         "        *(sa + 64*ib + 8*ly + lx) = temp_a[i/4][i%%4];\n"
         "      }\n"
         "    }\n"
         "    if (FC_mul_mm_bc_inp) {\n"
         "      for (short i = 0; i < 8; ++i) {\n"
         "        const short sx = (tiitg%%NL1);\n"
         "        const short sy = (tiitg/NL1)/8;\n"
         "        const short lx = i;\n"
         "        const short ly = (tiitg/NL1)%%8;\n"
         "        const short ib = 4*sx + sy;\n"
         "        *(sb + 64*ib + 8*ly + lx) = loop_k + iy + i < args->ne00 ? *((device half *)y + i) : half(0);\n"
         "      }\n"
         "    } else {\n"
         "      const short sx = (tiitg%%NL1);\n"
         "      const short sy = (tiitg/NL1)/8;\n"
         "      const short ly = (tiitg/NL1)%%8;\n"
         "      const short ib = 4*sx + sy;\n"
         "      *(threadgroup half2x4 *)(sb + 64*ib + 8*ly) = *((device half2x4 *)y);\n"
         "    }\n"
         "    il = (il + 2 < 1) ? il + 2 : il %% 2;\n"
         "    x = (il < 2) ? x + 2 : x;\n"
         "    y += NK;\n"
         "    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "    threadgroup const half *lsma = (sa + 4*64*(sgitg%%2));\n"
         "    threadgroup const half *lsmb = (sb + 2*64*(sgitg/2));\n"
         "    for (short ik = 0; ik < NK/8; ik++) {\n"
         "      simdgroup_barrier(mem_flags::mem_none);\n"
         "      for (short i = 0; i < 4; i++) simdgroup_load(ma[i], lsma + 64*i, 8, ulong2(0, 0), false);\n"
         "      simdgroup_barrier(mem_flags::mem_none);\n"
         "      for (short i = 0; i < 2; i++) simdgroup_load(mb[i], lsmb + 64*i, 8, ulong2(0, 0), false);\n"
         "      simdgroup_barrier(mem_flags::mem_none);\n"
         "      for (short i = 0; i < 8; i++) simdgroup_multiply_accumulate(mc[i], mb[i/4], ma[i%%4], mc[i]);\n"
         "      lsma += 8*64;\n"
         "      lsmb += 4*64;\n"
         "    }\n"
         "  }\n"
         "  if (!FC_mul_mm_bc_out || (r0 + NR0 <= args->ne0 && r1 + NR1 <= args->ne1)) {\n"
         "    device float *C = (device float *)dst +\n"
         "      (r0 + 32*(sgitg & 1)) +\n"
         "      (r1 + 16*(sgitg >> 1)) * args->ne0 + im*args->ne1*args->ne0;\n"
         "    for (short i = 0; i < 8; i++) {\n"
         "      simdgroup_store(mc[i], C + 8*(i%%4) + 8*args->ne0*(i/4), args->ne0, ulong2(0, 0), false);\n"
         "    }\n"
         "  } else {\n"
         "    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "    threadgroup float *temp_str = ((threadgroup float *)shmem)\n"
         "      + 32*(sgitg&1) + (16*(sgitg >> 1))*NR0;\n"
         "    for (short i = 0; i < 8; i++) {\n"
         "      simdgroup_store(mc[i], temp_str + 8*(i%%4) + 8*NR0*(i/4), NR0, ulong2(0, 0), false);\n"
         "    }\n"
         "    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "    if (sgitg == 0) {\n"
         "      for (int j = tiitg; j < nr1; j += NR1) {\n"
         "        device float *D = (device float *)dst + r0 + (r1 + j)*args->ne0 + im*args->ne1*args->ne0;\n"
         "        threadgroup float *C = temp_str + (j*NR0);\n"
         "        for (int i = 0; i < nr0; i++) D[i] = C[i];\n"
         "      }\n"
         "    }\n"
         "  }\n"
         "}\n"];

    /* Set both FCs to false: bounds-check disabled. Canary uses clean dims. */
    const ds4_mtl4_fc_short fcs[] = {{0, 700}, {0, 701}};
    g_mul_mm_f16_f32_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_mul_mm_f16_f32_mtl4", @"mul_mm_f16_f32_mtl4", 1024, fcs, 2);
    g_mul_mm_f16_f32_mtl4_init_ok = (g_mul_mm_f16_f32_mtl4_pipeline != nil) ? 1 : 0;
    return g_mul_mm_f16_f32_mtl4_init_ok;
}

int ds4_gpu_mtl4_mul_mm_f16_f32_canary(uint32_t M, uint32_t N, uint32_t K) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_mul_mm_f16_f32_mtl4_pipeline_init()) return 0;
    if (M == 0 || N == 0 || K == 0 || (M % 64) != 0 || (N % 32) != 0 || (K % 32) != 0) {
        fprintf(stderr, "ds4: mul_mm canary needs M%%64==0, N%%32==0, K%%32==0 (got %u, %u, %u)\n", M, N, K);
        return 0;
    }
    const uint64_t b_total = (uint64_t)M * K;
    const uint64_t a_total = (uint64_t)N * K;
    const uint64_t c_total = (uint64_t)M * N;
    uint16_t *host_b = (uint16_t *)calloc(b_total, sizeof(uint16_t));  /* M × K half */
    uint16_t *host_a = (uint16_t *)calloc(a_total, sizeof(uint16_t));  /* N × K half */
    float *host_c = (float *)calloc(c_total, sizeof(float));
    if (!host_b || !host_a || !host_c) {
        free(host_b); free(host_a); free(host_c); return 0;
    }
    /* All-ones pattern: each C[m, n] = K. */
    _Float16 one = (_Float16)1.0f;
    for (uint64_t i = 0; i < b_total; i++) memcpy(&host_b[i], &one, sizeof(one));
    for (uint64_t i = 0; i < a_total; i++) memcpy(&host_a[i], &one, sizeof(one));

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:128 options:MTLResourceStorageModeShared];
        id<MTLBuffer> bBuf = [g_device newBufferWithBytes:host_b length:b_total*sizeof(uint16_t) options:MTLResourceStorageModeShared];
        id<MTLBuffer> aBuf = [g_device newBufferWithBytes:host_a length:a_total*sizeof(uint16_t) options:MTLResourceStorageModeShared];
        id<MTLBuffer> cBuf = [g_device newBufferWithLength:c_total*sizeof(float) options:MTLResourceStorageModeShared];

        struct {
            int ne00, ne02;
            uint64_t nb01, nb02, nb03;
            int ne12;
            uint64_t nb10, nb11, nb12, nb13;
            int ne0, ne1;
            int16_t r2, r3;
        } args;
        memset(&args, 0, sizeof(args));
        args.ne00 = K;
        args.ne02 = 1;
        args.nb01 = (uint64_t)K * sizeof(uint16_t);  /* B row stride */
        args.nb02 = (uint64_t)M * K * sizeof(uint16_t);
        args.nb03 = args.nb02;
        args.ne12 = 1;
        args.nb10 = sizeof(uint16_t);
        args.nb11 = (uint64_t)K * sizeof(uint16_t);  /* A row stride */
        args.nb12 = (uint64_t)N * K * sizeof(uint16_t);
        args.nb13 = args.nb12;
        args.ne0 = M; args.ne1 = N;
        args.r2 = 1; args.r3 = 1;
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 6;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[4] = {(id)argsBuf, (id)bBuf, (id)aBuf, (id)cBuf};
            [residency addAllocations:allocs count:4];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(8);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:bBuf.gpuAddress atIndex:1];
                [argTable setAddress:aBuf.gpuAddress atIndex:2];
                [argTable setAddress:cBuf.gpuAddress atIndex:3];

                /* Threadgroup memory: sa offset = 0, sb offset = 4096 bytes.
                 * sa size = NR0×NK×sizeof(half) = 64×32×2 = 4096
                 * sb size = NR1×NK×sizeof(half) = 32×32×2 = 2048
                 * total: 6144 bytes minimum. Helper adds spillover so be safe. */
                NSUInteger shmem_bytes = 8192;  /* NR0 × NK × float for the bc_out spill */

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_mul_mm_f16_f32_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc setThreadgroupMemoryLength:shmem_bytes atIndex:0];
                [enc dispatchThreadgroups:MTLSizeMake(N / 32, M / 64, 1)
                    threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) { (void)fb; dispatch_semaphore_signal(sem); }];
                id<MTL4CommandBuffer> bufs[1] = {cb};
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 10LL * NSEC_PER_SEC));
                if (getenv("DS4_LENS_TIME")) {  /* agent1 2026-06-03: env-gated GPU-dispatch timing; reuses argTable/residency, no default-path change */
                    const int _R = 12;
                    struct timespec _t0, _t1; clock_gettime(CLOCK_MONOTONIC, &_t0);
                    for (int _r = 0; _r < _R; _r++) {
                        id<MTL4CommandBuffer> _cb = [g_device newCommandBuffer];
                        [_cb beginCommandBufferWithAllocator:g_polar_allocator];
                        [_cb useResidencySet:residency];
                        id<MTL4ComputeCommandEncoder> _enc = [_cb computeCommandEncoder];
                        [_enc setComputePipelineState:g_mul_mm_f16_f32_mtl4_pipeline];
                        [_enc setArgumentTable:argTable];
                        [_enc setThreadgroupMemoryLength:shmem_bytes atIndex:0];
                        [_enc dispatchThreadgroups:MTLSizeMake(N / 32, M / 64, 1)
                            threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
                        [_enc endEncoding];
                        [_cb endCommandBuffer];
                        dispatch_semaphore_t _sem = dispatch_semaphore_create(0);
                        MTL4CommitOptions *_opts = [MTL4CommitOptions new];
                        [_opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) { (void)fb; dispatch_semaphore_signal(_sem); }];
                        id<MTL4CommandBuffer> _bufs[1] = {_cb};
                        [g_polar_queue commit:_bufs count:1 options:_opts];
                        dispatch_semaphore_wait(_sem, dispatch_time(DISPATCH_TIME_NOW, 30LL * NSEC_PER_SEC));
                    }
                    clock_gettime(CLOCK_MONOTONIC, &_t1);
                    double _ms = ((_t1.tv_sec - _t0.tv_sec) * 1e3 + (_t1.tv_nsec - _t0.tv_nsec) / 1e6) / _R;
                    double _tf = 2.0 * (double)M * (double)N * (double)K / (_ms / 1e3) / 1e12;
                    fprintf(stderr, "ds4: LENS_TIME M=%u N=%u K=%u %.3f ms/dispatch %.2f TFLOP/s\n", M, N, K, _ms, _tf);
                }
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_c, cBuf.contents, c_total * sizeof(float));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 8);
            }
        }
    }
    if (!rc) { free(host_b); free(host_a); free(host_c); return 0; }

    /* All-ones: every cell = K */
    const float expected = (float)K;
    int n_match = 0, n_other = 0;
    double max_rel = 0.0;
    int first_other = -1;
    float first_other_v = 0.0f;
    for (uint64_t i = 0; i < c_total; i++) {
        const double d = fabs((double)(host_c[i] - expected));
        const double rel = d / (fabs((double)expected) + 1e-7);
        if (rel > max_rel) max_rel = rel;
        if (rel < 1e-3) n_match++;
        else { n_other++; if (first_other < 0) { first_other = (int)i; first_other_v = host_c[i]; } }
    }
    fprintf(stderr,
        "ds4: mul_mm_f16_f32 MTL4 canary M=%u N=%u K=%u expected=%.1f "
        "match=%d other=%d max_rel=%.4e first_other=%d first_other_v=%.4f c[0]=%.2f c[end]=%.2f\n",
        M, N, K, (double)expected, n_match, n_other, max_rel,
        first_other, (double)first_other_v, (double)host_c[0], (double)host_c[c_total - 1]);
    free(host_b); free(host_a); free(host_c);
    return (n_match == (int)c_total) ? 1 : 0;
}

/* ============================================================ */
/* mul_mm_q8_0_f32 MTL4 port (silv 2026-05-28 #733)              */
/* ============================================================ */
/* Q8_0-weight × FP16-input → FP32-output GEMM at 64×32×32 tile.
 * Sister of #732 mul_mm_f16_f32 with src0 dequant from block_q8_0
 * blocks. nl=2 (2 sub-blocks per QK8_0=32-element block; each
 * thread dequants 16 elements per iteration). Block layout:
 * { half d; int8_t qs[32]; } = 34 bytes.
 *
 * The mul_mm template's branch `is_same<T0_4x4, block_q>::value` is
 * FALSE here (T0_4x4=half4x4, block_q=block_q8_0), so the dequant
 * path always runs. */

static id<MTLComputePipelineState> g_mul_mm_q8_0_f32_mtl4_pipeline;
static int g_mul_mm_q8_0_f32_mtl4_init_attempted;
static int g_mul_mm_q8_0_f32_mtl4_init_ok;

static int ds4_mul_mm_q8_0_f32_mtl4_pipeline_init(void) {
    if (g_mul_mm_q8_0_f32_mtl4_init_attempted) return g_mul_mm_q8_0_f32_mtl4_init_ok;
    g_mul_mm_q8_0_f32_mtl4_init_attempted = 1;

    NSString *source = [NSString stringWithFormat:
        @"#include <metal_stdlib>\n"
         "#include <metal_simdgroup_matrix>\n"
         "using namespace metal;\n"
         "#define FC_MUL_MM 700\n"
         "#define QK8_0 32\n"
         "constant short FC_mul_mm_bc_inp [[function_constant(FC_MUL_MM + 0)]];\n"
         "constant short FC_mul_mm_bc_out [[function_constant(FC_MUL_MM + 1)]];\n"
         "struct block_q8_0 { half d; int8_t qs[QK8_0]; };\n"
         "static inline void dequantize_q8_0_4x4(device const block_q8_0 *xb, short il, thread half4x4 &reg) {\n"
         "  device const int8_t *qs = xb->qs + 16*il;\n"
         "  const half d = xb->d;\n"
         "  for (short i = 0; i < 16; i++) reg[i/4][i%%4] = (half)((float)qs[i] * (float)d);\n"
         "}\n"
         "struct mm_args {\n"
         "  int ne00; int ne02;\n"
         "  ulong nb01; ulong nb02; ulong nb03;\n"
         "  int ne12;\n"
         "  ulong nb10; ulong nb11; ulong nb12; ulong nb13;\n"
         "  int ne0; int ne1;\n"
         "  short r2; short r3;\n"
         "};\n"
         "kernel void mul_mm_q8_0_f32_mtl4(\n"
         "    device const mm_args *args [[buffer(0)]],\n"
         "    device const char    *src0 [[buffer(1)]],\n"
         "    device const char    *src1 [[buffer(2)]],\n"
         "    device       char    *dst  [[buffer(3)]],\n"
         "    threadgroup  char    *shmem [[threadgroup(0)]],\n"
         "    uint3   tgpig [[threadgroup_position_in_grid]],\n"
         "    ushort  tiitg [[thread_index_in_threadgroup]],\n"
         "    ushort  sgitg [[simdgroup_index_in_threadgroup]]) {\n"
         "  threadgroup half *sa = (threadgroup half *)(shmem);\n"
         "  threadgroup half *sb = (threadgroup half *)(shmem + 4096);\n"
         "  constexpr int NR0 = 64;\n"
         "  constexpr int NR1 = 32;\n"
         "  constexpr int NK  = 32;\n"
         "  constexpr int NL0 = NK/16;\n"
         "  constexpr int NL1 = NK/8;\n"
         "  constexpr int nl  = 2;\n"
         "  const int im = tgpig.z;\n"
         "  const int r0 = tgpig.y*NR0;\n"
         "  const int r1 = tgpig.x*NR1;\n"
         "  const short nr0 = (args->ne0 - r0 < NR0) ? (args->ne0 - r0) : NR0;\n"
         "  const short nr1 = (args->ne1 - r1 < NR1) ? (args->ne1 - r1) : NR1;\n"
         "  const short lr0 = ((short)tiitg/NL0) < nr0 ? ((short)tiitg/NL0) : nr0 - 1;\n"
         "  const short lr1 = ((short)tiitg/NL1) < nr1 ? ((short)tiitg/NL1) : nr1 - 1;\n"
         "  const short il0 = (tiitg %% NL0);\n"
         "  short il = il0;\n"
         "  const int i12 = im %% args->ne12;\n"
         "  const int i13 = im / args->ne12;\n"
         "  const ulong offset0 = (i12/args->r2)*args->nb02 + (i13/args->r3)*args->nb03;\n"
         "  const short offset1 = il0/nl;\n"
         "  device const block_q8_0 *x = (device const block_q8_0 *)\n"
         "    (src0 + args->nb01*(r0 + lr0) + offset0) + offset1;\n"
         "  const short iy = 8*(tiitg %% NL1);\n"
         "  device const half *y = (device const half *)(src1\n"
         "    + args->nb13*i13 + args->nb12*i12 + args->nb11*(r1 + lr1) + args->nb10*iy);\n"
         "  simdgroup_half8x8 ma[4];\n"
         "  simdgroup_half8x8 mb[2];\n"
         "  simdgroup_float8x8 mc[8];\n"
         "  for (short i = 0; i < 8; i++) mc[i] = make_filled_simdgroup_matrix<float, 8>(0.0f);\n"
         "  for (int loop_k = 0; loop_k < args->ne00; loop_k += NK) {\n"
         "    half4x4 temp_a;\n"
         "    dequantize_q8_0_4x4(x, il, temp_a);\n"
         "    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "    for (short i = 0; i < 16; i++) {\n"
         "      const short sx = 2*il0 + i/8;\n"
         "      const short sy = (tiitg/NL0)/8;\n"
         "      const short lx = (tiitg/NL0)%%8;\n"
         "      const short ly = i%%8;\n"
         "      const short ib = 8*sx + sy;\n"
         "      *(sa + 64*ib + 8*ly + lx) = temp_a[i/4][i%%4];\n"
         "    }\n"
         "    if (FC_mul_mm_bc_inp) {\n"
         "      for (short i = 0; i < 8; ++i) {\n"
         "        const short sx = (tiitg%%NL1);\n"
         "        const short sy = (tiitg/NL1)/8;\n"
         "        const short lx = i;\n"
         "        const short ly = (tiitg/NL1)%%8;\n"
         "        const short ib = 4*sx + sy;\n"
         "        *(sb + 64*ib + 8*ly + lx) = loop_k + iy + i < args->ne00 ? *((device half *)y + i) : half(0);\n"
         "      }\n"
         "    } else {\n"
         "      const short sx = (tiitg%%NL1);\n"
         "      const short sy = (tiitg/NL1)/8;\n"
         "      const short ly = (tiitg/NL1)%%8;\n"
         "      const short ib = 4*sx + sy;\n"
         "      *(threadgroup half2x4 *)(sb + 64*ib + 8*ly) = *((device half2x4 *)y);\n"
         "    }\n"
         "    il = (il + 2 < nl) ? il + 2 : il %% nl;\n"
         "    x = (il < 2) ? x + (2 + nl - 1)/nl : x;\n"
         "    y += NK;\n"
         "    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "    threadgroup const half *lsma = (sa + 4*64*(sgitg%%2));\n"
         "    threadgroup const half *lsmb = (sb + 2*64*(sgitg/2));\n"
         "    for (short ik = 0; ik < NK/8; ik++) {\n"
         "      simdgroup_barrier(mem_flags::mem_none);\n"
         "      for (short i = 0; i < 4; i++) simdgroup_load(ma[i], lsma + 64*i, 8, ulong2(0, 0), false);\n"
         "      simdgroup_barrier(mem_flags::mem_none);\n"
         "      for (short i = 0; i < 2; i++) simdgroup_load(mb[i], lsmb + 64*i, 8, ulong2(0, 0), false);\n"
         "      simdgroup_barrier(mem_flags::mem_none);\n"
         "      for (short i = 0; i < 8; i++) simdgroup_multiply_accumulate(mc[i], mb[i/4], ma[i%%4], mc[i]);\n"
         "      lsma += 8*64;\n"
         "      lsmb += 4*64;\n"
         "    }\n"
         "  }\n"
         "  if (!FC_mul_mm_bc_out || (r0 + NR0 <= args->ne0 && r1 + NR1 <= args->ne1)) {\n"
         "    device float *C = (device float *)dst +\n"
         "      (r0 + 32*(sgitg & 1)) +\n"
         "      (r1 + 16*(sgitg >> 1)) * args->ne0 + im*args->ne1*args->ne0;\n"
         "    for (short i = 0; i < 8; i++) {\n"
         "      simdgroup_store(mc[i], C + 8*(i%%4) + 8*args->ne0*(i/4), args->ne0, ulong2(0, 0), false);\n"
         "    }\n"
         "  } else {\n"
         "    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "    threadgroup float *temp_str = ((threadgroup float *)shmem)\n"
         "      + 32*(sgitg&1) + (16*(sgitg >> 1))*NR0;\n"
         "    for (short i = 0; i < 8; i++) {\n"
         "      simdgroup_store(mc[i], temp_str + 8*(i%%4) + 8*NR0*(i/4), NR0, ulong2(0, 0), false);\n"
         "    }\n"
         "    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "    if (sgitg == 0) {\n"
         "      for (int j = tiitg; j < nr1; j += NR1) {\n"
         "        device float *D = (device float *)dst + r0 + (r1 + j)*args->ne0 + im*args->ne1*args->ne0;\n"
         "        threadgroup float *C = temp_str + (j*NR0);\n"
         "        for (int i = 0; i < nr0; i++) D[i] = C[i];\n"
         "      }\n"
         "    }\n"
         "  }\n"
         "}\n"];

    const ds4_mtl4_fc_short fcs[] = {{0, 700}, {0, 701}};
    g_mul_mm_q8_0_f32_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_mul_mm_q8_0_f32_mtl4", @"mul_mm_q8_0_f32_mtl4", 1024, fcs, 2);
    g_mul_mm_q8_0_f32_mtl4_init_ok = (g_mul_mm_q8_0_f32_mtl4_pipeline != nil) ? 1 : 0;
    return g_mul_mm_q8_0_f32_mtl4_init_ok;
}

int ds4_gpu_mtl4_mul_mm_q8_0_f32_canary(uint32_t M, uint32_t N, uint32_t K) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_mul_mm_q8_0_f32_mtl4_pipeline_init()) return 0;
    if ((M % 64) != 0 || (N % 32) != 0 || (K % 32) != 0) {
        fprintf(stderr, "ds4: mul_mm_q8_0 canary needs M%%64==0, N%%32==0, K%%32==0 (got %u,%u,%u)\n", M, N, K);
        return 0;
    }
    const uint64_t b_total = (uint64_t)M * K;  /* B = weights, M rows × K cols */
    const uint64_t a_total = (uint64_t)N * K;
    const uint64_t c_total = (uint64_t)M * N;
    const uint32_t n_blocks_per_row = K / 32u;
    const uint64_t q8_row_bytes = (uint64_t)n_blocks_per_row * 34u;
    float *host_b = (float *)calloc(b_total, sizeof(float));
    uint8_t *host_b_q8 = (uint8_t *)calloc((uint64_t)M * q8_row_bytes, 1);
    uint16_t *host_a = (uint16_t *)calloc(a_total, sizeof(uint16_t));
    float *host_c = (float *)calloc(c_total, sizeof(float));
    if (!host_b || !host_b_q8 || !host_a || !host_c) {
        free(host_b); free(host_b_q8); free(host_a); free(host_c); return 0;
    }
    /* Pattern: B[m, k] = integer in [-125, 125] (clean Q8_0 round); A[n, k] = 1.0 (FP16).
     * Expected C[m, n] = sum_k B[m, k] * 1 = sum_k B[m, k]. With B = ((m*13 + k*7) % 250) - 125,
     * the row sum depends on m. Compute it after dequantizing the Q8_0 blocks. */
    for (uint32_t m = 0; m < M; m++) {
        for (uint32_t k = 0; k < K; k++) {
            host_b[(uint64_t)m * K + k] = (float)((int)((m * 13 + k * 7) % 250) - 125);
        }
        ds4_quantize_q8_0_row(host_b + (uint64_t)m * K, K, host_b_q8 + (uint64_t)m * q8_row_bytes);
        /* Dequant back into host_b for reference */
        for (uint32_t b = 0; b < n_blocks_per_row; b++) {
            const uint8_t *blk = host_b_q8 + (uint64_t)m * q8_row_bytes + (uint64_t)b * 34u;
            _Float16 d_half; memcpy(&d_half, blk, sizeof(d_half));
            const float d = (float)d_half;
            const int8_t *qs = (const int8_t *)(blk + 2);
            for (uint32_t i = 0; i < 32; i++) {
                host_b[(uint64_t)m * K + (uint64_t)b * 32u + i] = (float)qs[i] * d;
            }
        }
    }
    _Float16 one = (_Float16)1.0f;
    for (uint64_t i = 0; i < a_total; i++) memcpy(&host_a[i], &one, sizeof(one));

    /* Expected: C[m, n] = sum_k B[m, k] * 1.0 = sum of row m */
    float *expected_row_sums = (float *)calloc(M, sizeof(float));
    for (uint32_t m = 0; m < M; m++) {
        double s = 0.0;
        for (uint32_t k = 0; k < K; k++) s += (double)host_b[(uint64_t)m * K + k];
        expected_row_sums[m] = (float)s;
    }

    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:128 options:MTLResourceStorageModeShared];
        id<MTLBuffer> bBuf = [g_device newBufferWithBytes:host_b_q8 length:(uint64_t)M*q8_row_bytes options:MTLResourceStorageModeShared];
        id<MTLBuffer> aBuf = [g_device newBufferWithBytes:host_a length:a_total*sizeof(uint16_t) options:MTLResourceStorageModeShared];
        id<MTLBuffer> cBuf = [g_device newBufferWithLength:c_total*sizeof(float) options:MTLResourceStorageModeShared];

        struct {
            int ne00, ne02;
            uint64_t nb01, nb02, nb03;
            int ne12;
            uint64_t nb10, nb11, nb12, nb13;
            int ne0, ne1;
            int16_t r2, r3;
        } args;
        memset(&args, 0, sizeof(args));
        args.ne00 = K;
        args.ne02 = 1;
        args.nb01 = q8_row_bytes;
        args.nb02 = (uint64_t)M * q8_row_bytes;
        args.nb03 = args.nb02;
        args.ne12 = 1;
        args.nb10 = sizeof(uint16_t);
        args.nb11 = (uint64_t)K * sizeof(uint16_t);
        args.nb12 = (uint64_t)N * K * sizeof(uint16_t);
        args.nb13 = args.nb12;
        args.ne0 = M; args.ne1 = N;
        args.r2 = 1; args.r3 = 1;
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 6;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[4] = {(id)argsBuf, (id)bBuf, (id)aBuf, (id)cBuf};
            [residency addAllocations:allocs count:4];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);

            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(8);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:bBuf.gpuAddress atIndex:1];
                [argTable setAddress:aBuf.gpuAddress atIndex:2];
                [argTable setAddress:cBuf.gpuAddress atIndex:3];
                NSUInteger shmem_bytes = 8192;

                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_mul_mm_q8_0_f32_mtl4_pipeline];
                [enc setArgumentTable:argTable];
                [enc setThreadgroupMemoryLength:shmem_bytes atIndex:0];
                [enc dispatchThreadgroups:MTLSizeMake(N / 32, M / 64, 1)
                    threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];

                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) { (void)fb; dispatch_semaphore_signal(sem); }];
                id<MTL4CommandBuffer> bufs[1] = {cb};
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 10LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_c, cBuf.contents, c_total * sizeof(float));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 8);
            }
        }
    }
    if (!rc) { free(host_b); free(host_b_q8); free(host_a); free(host_c); free(expected_row_sums); return 0; }

    /* FP16-staged Q8_0 matmul precision: accumulator is float but mb tile is half,
     * so values like (int8 ± 127) × d_half drift by ~1 part in 1024 per K step.
     * 5% tolerance bounded by K=256 cumulative drift on integer inputs. */
    int mismatch = 0;
    double max_rel = 0.0;
    for (uint32_t m = 0; m < M; m++) {
        const float expected = expected_row_sums[m];
        for (uint32_t n = 0; n < N; n++) {
            const float got = host_c[(uint64_t)n * M + m];
            const double d = fabs((double)(got - expected));
            const double rel = d / (fabs((double)expected) + 1e-3);
            if (rel > max_rel) max_rel = rel;
            if (rel > 5e-2) mismatch++;
        }
    }
    fprintf(stderr,
        "ds4: mul_mm_q8_0_f32 MTL4 canary M=%u N=%u K=%u mismatch=%d max_rel=%.4e "
        "c[0,0]=%.2f (ref_row0=%.2f) c[0,N-1]=%.2f c[M-1,0]=%.2f\n",
        M, N, K, mismatch, max_rel,
        (double)host_c[0], (double)expected_row_sums[0],
        (double)host_c[(uint64_t)(N - 1) * M], (double)host_c[M - 1]);
    free(host_b); free(host_b_q8); free(host_a); free(host_c); free(expected_row_sums);
    return (mismatch == 0) ? 1 : 0;
}

/* Q8_0 MSL source builder — single template for n32/n64/n128 widths.
 * silv 2026-05-28 R1 consolidation: nl=2 (vs nl=16 for K-quants) since
 * Q8_0 blocks are 32 elements each; otherwise identical NR1/k pattern. */
static NSString *ds4_mm_id_q8_0_msl(int nr1, const char *suffix) {
    return [NSString stringWithFormat:
        @"#include <metal_stdlib>\n"
         "#include <metal_simdgroup_matrix>\n"
         "using namespace metal;\n"
         "#define FC_MUL_MM 700\n"
         "#define QK8_0 32\n"
         "constant short FC_mul_mm_bc_inp [[function_constant(FC_MUL_MM + 0)]];\n"
         "constant short FC_mul_mm_bc_out [[function_constant(FC_MUL_MM + 1)]];\n"
         "struct block_q8_0 { half d; int8_t qs[QK8_0]; };\n"
         "static inline void dequantize_q8_0_4x4(device const block_q8_0 *xb, short il, thread half4x4 &reg) {\n"
         "  device const int8_t *qs = xb->qs + 16*il;\n"
         "  const half d = xb->d;\n"
         "  for (short i = 0; i < 16; i++) reg[i/4][i%%4] = (half)((float)qs[i] * (float)d);\n"
         "}\n"
         "struct mm_id_args {\n"
         "  int ne00; int ne02;\n"
         "  ulong nb01; ulong nb02; ulong nb03;\n"
         "  int ne11;\n"
         "  ulong nb10; ulong nb11; ulong nb12; ulong nb13;\n"
         "  int ne20; int ne21;\n"
         "  int ne0; int ne1;\n"
         "  short r2; short r3;\n"
         "};\n"
         "kernel void mul_mm_id_q8_0_f32%s_mtl4(\n"
         "    device const mm_id_args *args [[buffer(0)]],\n"
         "    device const char       *src0 [[buffer(1)]],\n"
         "    device const char       *src1 [[buffer(2)]],\n"
         "    device const char       *htpe [[buffer(3)]],\n"
         "    device const char       *hids [[buffer(4)]],\n"
         "    device       char       *dst  [[buffer(5)]],\n"
         "    threadgroup  char       *shmem [[threadgroup(0)]],\n"
         "    uint3   tgpig [[threadgroup_position_in_grid]],\n"
         "    ushort  tiitg [[thread_index_in_threadgroup]],\n"
         "    ushort  tiisg [[thread_index_in_simdgroup]],\n"
         "    ushort  sgitg [[simdgroup_index_in_threadgroup]]) {\n"
         "  threadgroup half *sa = (threadgroup half *)(shmem);\n"
         "  threadgroup half *sb = (threadgroup half *)(shmem + 4096);\n"
         "  constexpr int NR0 = 64;\n"
         "  constexpr int NR1 = %d;\n"
         "  constexpr int NK  = 32;\n"
         "  constexpr int NL0 = NK/16;\n"
         "  constexpr int NL1 = NK/8;\n"
         "  constexpr int nl  = 2;\n"
         "  constexpr int N_BANDS = NR1 / 32;\n"
         "  const int im = tgpig.z;\n"
         "  const int r0 = tgpig.y*NR0;\n"
         "  const int r1 = tgpig.x*NR1;\n"
         "  device const uint  *tpe_u32 = (device const uint *)htpe;\n"
         "  device const int   *ids_i32 = (device const int  *)hids;\n"
         "  const int neh1 = (int)tpe_u32[im];\n"
         "  if (r1 >= neh1) return;\n"
         "  const short nr0 = (args->ne0 - r0 < NR0) ? (args->ne0 - r0) : NR0;\n"
         "  const short nr1 = (neh1 - r1 < NR1) ? (neh1 - r1) : NR1;\n"
         "  const short lr0 = ((short)tiitg/NL0) < nr0 ? ((short)tiitg/NL0) : nr0 - 1;\n"
         "  const short il0 = (tiitg %% NL0);\n"
         "  short il = il0;\n"
         "  const short i13 = 0;\n"
         "  const ulong offset0 = im*args->nb02 + i13*args->nb03;\n"
         "  const short offset1 = il0/nl;\n"
         "  device const block_q8_0 *x = (device const block_q8_0 *)\n"
         "    (src0 + args->nb01*(r0 + lr0) + offset0) + offset1;\n"
         "  const short iy = 8*(tiitg %% NL1);\n"
         "  simdgroup_half8x8 ma[4];\n"
         "  simdgroup_half8x8 mb[NR1/16];\n"
         "  simdgroup_float8x8 mc[NR1/4];\n"
         "  for (short i = 0; i < NR1/4; i++) mc[i] = make_filled_simdgroup_matrix<float, 8>(0.0f);\n"
         "  for (int loop_k = 0; loop_k < args->ne00; loop_k += NK) {\n"
         "    half4x4 temp_a;\n"
         "    dequantize_q8_0_4x4(x, il, temp_a);\n"
         "    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "    for (short i = 0; i < 16; i++) {\n"
         "      const short sx = 2*il0 + i/8;\n"
         "      const short sy = (tiitg/NL0)/8;\n"
         "      const short lx = (tiitg/NL0)%%8;\n"
         "      const short ly = i%%8;\n"
         "      const short ib = 8*sx + sy;\n"
         "      *(sa + 64*ib + 8*ly + lx) = temp_a[i/4][i%%4];\n"
         "    }\n"
         "    for (short band = 0; band < N_BANDS; band++) {\n"
         "      const short lr1_b_raw = (short)tiitg/NL1 + band * 32;\n"
         "      const short lr1_b = lr1_b_raw < nr1 ? lr1_b_raw : nr1 - 1;\n"
         "      const int id_b = ids_i32[im*args->ne21 + r1 + lr1_b];\n"
         "      const short i11_b = (id_b %% args->ne20) %% args->ne11;\n"
         "      const short i12_b = (id_b / args->ne20);\n"
         "      device const half *y_b = (device const half *)(src1\n"
         "        + args->nb13*i13 + args->nb12*i12_b + args->nb11*i11_b + args->nb10*iy);\n"
         "      y_b += loop_k;\n"
         "      const short sy_b = (tiitg/NL1)/8 + band * 4;\n"
         "      if (FC_mul_mm_bc_inp) {\n"
         "        for (short i = 0; i < 8; ++i) {\n"
         "          const short sx = (tiitg%%NL1);\n"
         "          const short ly = (tiitg/NL1)%%8;\n"
         "          const short ib = (NR1/8)*sx + sy_b;\n"
         "          *(sb + 64*ib + 8*ly + i) = loop_k + iy + i < args->ne00 ? *((device half *)y_b + i) : half(0);\n"
         "        }\n"
         "      } else {\n"
         "        const short sx = (tiitg%%NL1);\n"
         "        const short ly = (tiitg/NL1)%%8;\n"
         "        const short ib = (NR1/8)*sx + sy_b;\n"
         "        *(threadgroup half2x4 *)(sb + 64*ib + 8*ly) = *((device half2x4 *)y_b);\n"
         "      }\n"
         "    }\n"
         "    il = (il + 2 < nl) ? il + 2 : il %% nl;\n"
         "    x = (il < 2) ? x + (2 + nl - 1)/nl : x;\n"
         "    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "    threadgroup const half *lsma = (sa + 4*64*(sgitg%%2));\n"
         "    threadgroup const half *lsmb = (sb + (NR1/16)*64*(sgitg/2));\n"
         "    for (short ik = 0; ik < NK/8; ik++) {\n"
         "      simdgroup_barrier(mem_flags::mem_none);\n"
         "      for (short i = 0; i < 4; i++) simdgroup_load(ma[i], lsma + 64*i, 8, ulong2(0, 0), false);\n"
         "      simdgroup_barrier(mem_flags::mem_none);\n"
         "      for (short i = 0; i < NR1/16; i++) simdgroup_load(mb[i], lsmb + 64*i, 8, ulong2(0, 0), false);\n"
         "      simdgroup_barrier(mem_flags::mem_none);\n"
         "      for (short i = 0; i < NR1/4; i++) simdgroup_multiply_accumulate(mc[i], mb[i/4], ma[i%%4], mc[i]);\n"
         "      lsma += 8*64;\n"
         "      lsmb += (NR1/8)*64;\n"
         "    }\n"
         "  }\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  threadgroup float *temp_str = ((threadgroup float *)shmem)\n"
         "    + 32*(sgitg&1) + ((NR1/2)*(sgitg >> 1))*NR0;\n"
         "  for (short i = 0; i < NR1/4; i++) {\n"
         "    simdgroup_store(mc[i], temp_str + 8*(i%%4) + 8*NR0*(i/4), NR0, ulong2(0, 0), false);\n"
         "  }\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  for (short j = sgitg; j < nr1; j += 4) {\n"
         "    const int idj = ids_i32[im*args->ne21 + r1 + j];\n"
         "    const short ide = idj %% args->ne20;\n"
         "    const short idt = idj / args->ne20;\n"
         "    device float *D = (device float *)dst + r0 + ide*args->ne0 + idt*args->ne1*args->ne0;\n"
         "    threadgroup float *C = (threadgroup float *)shmem + j*NR0;\n"
         "    int i = tiisg;\n"
         "    for (; i < nr0; i += 32) D[i] = C[i];\n"
         "  }\n"
         "}\n", suffix, nr1];
}

/* ============================================================ */
/* mul_mm_id_q8_0_f32 MTL4 port (silv 2026-05-28 #734)            */
/* ============================================================ */
/* Routed MoE Q8_0 prefill matmul. Same kernel shape as #733 dense
 * mul_mm_q8_0 but with two extra buffers:
 *   - htpe : uint32_t[ne02]  — number of routed rows per expert
 *   - hids : int32_t[ne02*ne21] — encoded (slot, token) ids
 * The kernel reads im = tgpig.z (expert idx), bails if r1 >= tpe[im],
 * then decodes id = hids[im*ne21 + r1 + lr1] as (ide=id%ne20,
 * idt=id/ne20) and uses (idt, ide%ne11) as (i12, i11) for src1 read.
 *
 * Output write fans into a second loop that re-decodes id per output
 * row and writes dst + r0 + ide*ne0 + idt*ne1*ne0.
 *
 * This is the DS4 shared-expert prefill path for Q8_0 weights; sister
 * dense kernel (#733) drives non-routed shared experts. Adds 1 to the
 * 5 mul_mm_id_map0 variants (#706-#729) already in the MTL4 set.
 */

static id<MTLComputePipelineState> g_mul_mm_id_q8_0_f32_mtl4_pipeline;
static int g_mul_mm_id_q8_0_f32_mtl4_init_attempted;
static int g_mul_mm_id_q8_0_f32_mtl4_init_ok;

static int ds4_mul_mm_id_q8_0_f32_mtl4_pipeline_init(void) {
    if (g_mul_mm_id_q8_0_f32_mtl4_init_attempted) return g_mul_mm_id_q8_0_f32_mtl4_init_ok;
    g_mul_mm_id_q8_0_f32_mtl4_init_attempted = 1;
    NSString *source = ds4_mm_id_q8_0_msl(32, "");
    const ds4_mtl4_fc_short fcs[] = {{0, 700}, {0, 701}};
    g_mul_mm_id_q8_0_f32_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_mul_mm_id_q8_0_f32_mtl4", @"mul_mm_id_q8_0_f32_mtl4", 1024, fcs, 2);
    g_mul_mm_id_q8_0_f32_mtl4_init_ok = (g_mul_mm_id_q8_0_f32_mtl4_pipeline != nil) ? 1 : 0;
    return g_mul_mm_id_q8_0_f32_mtl4_init_ok;
}

/* Round 2: unified canary dispatch helper for mul_mm_id family (12 canaries).
 * Sets up MTL buffers + args struct + dispatches via MTL4 + reads back to host_c_out.
 * Per-canary code fills host_b/host_tpe/host_ids/expected + cfg fields, then calls this. */
typedef struct {
    uint64_t b_total;
    uint64_t a_total_elems;
    uint64_t c_total_elems;
    uint32_t M;
    uint32_t K;
    uint32_t n_experts;
    uint64_t row_bytes;
    NSUInteger shmem_bytes;
} ds4_mtl4_canary_cfg_t;

static int ds4_mtl4_mm_id_canary_dispatch(
    id<MTLComputePipelineState> pipeline,
    const ds4_mtl4_canary_cfg_t *cfg,
    const uint8_t  *host_b,
    const uint16_t *host_a,
    const uint32_t *host_tpe,
    const int32_t  *host_ids,
    float          *host_c_out)
{
    int rc = 0;
    @autoreleasepool {
        NSError *err = nil;
        id<MTLBuffer> argsBuf = [g_device newBufferWithLength:128 options:MTLResourceStorageModeShared];
        id<MTLBuffer> bBuf = [g_device newBufferWithBytes:host_b length:cfg->b_total options:MTLResourceStorageModeShared];
        id<MTLBuffer> aBuf = [g_device newBufferWithBytes:host_a length:cfg->a_total_elems*sizeof(uint16_t) options:MTLResourceStorageModeShared];
        id<MTLBuffer> tpeBuf = [g_device newBufferWithBytes:host_tpe length:cfg->n_experts*sizeof(uint32_t) options:MTLResourceStorageModeShared];
        id<MTLBuffer> idsBuf = [g_device newBufferWithBytes:host_ids length:cfg->n_experts*sizeof(int32_t) options:MTLResourceStorageModeShared];
        id<MTLBuffer> cBuf = [g_device newBufferWithLength:cfg->c_total_elems*sizeof(float) options:MTLResourceStorageModeShared];

        struct {
            int ne00, ne02;
            uint64_t nb01, nb02, nb03;
            int ne11;
            uint64_t nb10, nb11, nb12, nb13;
            int ne20, ne21;
            int ne0, ne1;
            int16_t r2, r3;
        } args;
        memset(&args, 0, sizeof(args));
        args.ne00 = cfg->K;
        args.ne02 = cfg->n_experts;
        args.nb01 = cfg->row_bytes;
        args.nb02 = (uint64_t)cfg->M * cfg->row_bytes;
        args.nb03 = args.nb02 * cfg->n_experts;
        args.ne11 = 1;
        args.nb10 = sizeof(uint16_t);
        args.nb11 = (uint64_t)cfg->K * sizeof(uint16_t);
        args.nb12 = args.nb11;
        args.nb13 = args.nb12 * cfg->n_experts;
        args.ne20 = 1; args.ne21 = 1;
        args.ne0 = cfg->M; args.ne1 = 1;
        args.r2 = 1; args.r3 = 1;
        memcpy(argsBuf.contents, &args, sizeof(args));

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 8;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (residency) {
            id<MTLAllocation> allocs[6] = {(id)argsBuf, (id)bBuf, (id)aBuf, (id)tpeBuf, (id)idsBuf, (id)cBuf};
            [residency addAllocations:allocs count:6];
            [residency commit];
            ds4_residency_request_checked(residency, __func__);
            id<MTL4ArgumentTable> argTable = ds4_mtl4_pool_acquire(8);
            if (argTable) {
                [argTable setAddress:argsBuf.gpuAddress atIndex:0];
                [argTable setAddress:bBuf.gpuAddress atIndex:1];
                [argTable setAddress:aBuf.gpuAddress atIndex:2];
                [argTable setAddress:tpeBuf.gpuAddress atIndex:3];
                [argTable setAddress:idsBuf.gpuAddress atIndex:4];
                [argTable setAddress:cBuf.gpuAddress atIndex:5];
                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:residency];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:pipeline];
                [enc setArgumentTable:argTable];
                [enc setThreadgroupMemoryLength:cfg->shmem_bytes atIndex:0];
                [enc dispatchThreadgroups:MTLSizeMake(1, cfg->M / 64, cfg->n_experts)
                    threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];
                [g_polar_queue addResidencySet:residency];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) { (void)fb; dispatch_semaphore_signal(sem); }];
                id<MTL4CommandBuffer> bufs[1] = {cb};
                [g_polar_queue commit:bufs count:1 options:opts];
                long waitRes = dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 10LL * NSEC_PER_SEC));
                [residency endResidency];
                if (waitRes == 0) {
                    memcpy(host_c_out, cBuf.contents, cfg->c_total_elems * sizeof(float));
                    rc = 1;
                }
                ds4_mtl4_pool_release(argTable, 8);
            }
        }
    }
    return rc;
}

int ds4_gpu_mtl4_mul_mm_id_q8_0_f32_canary(uint32_t M, uint32_t N, uint32_t K, uint32_t n_experts) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_mul_mm_id_q8_0_f32_mtl4_pipeline_init()) return 0;
    if ((M % 64) != 0 || (N % 32) != 0 || (K % 32) != 0 || n_experts == 0) {
        fprintf(stderr, "ds4: mul_mm_id_q8_0 canary needs M%%64==0, N%%32==0, K%%32==0, n_experts>0 "
                "(got %u,%u,%u,%u)\n", M, N, K, n_experts);
        return 0;
    }
    /* Per-expert weight: M rows × K cols (Q8_0 quantized). Each expert routes 1 row of input.
     * Each expert e is assigned its OWN token e: hids[e*ne21 + 0] = e (so idt=e, ide=0).
     * Input is n_experts tokens; output is n_experts × M (one row of output per token). */
    const uint32_t n_blocks_per_row = K / 32u;
    const uint64_t q8_row_bytes = (uint64_t)n_blocks_per_row * 34u;
    const uint64_t b_total = (uint64_t)n_experts * M * K;
    const uint64_t b_q8_total = (uint64_t)n_experts * M * q8_row_bytes;
    /* Input: n_experts tokens × 1 slot × K cols FP16. ne11=1, ne12=n_experts. */
    const uint64_t a_total = (uint64_t)n_experts * K;
    /* Output: M × ne1 × n_tokens. With ne20=1 and ne1=1, idt stride is M floats. */
    const uint64_t c_per_token = (uint64_t)M;
    const uint64_t c_total = (uint64_t)n_experts * c_per_token;

    float *host_b = (float *)calloc(b_total, sizeof(float));
    uint8_t *host_b_q8 = (uint8_t *)calloc(b_q8_total, 1);
    uint16_t *host_a = (uint16_t *)calloc(a_total, sizeof(uint16_t));
    float *host_c = (float *)calloc(c_total, sizeof(float));
    uint32_t *host_tpe = (uint32_t *)calloc(n_experts, sizeof(uint32_t));
    int32_t *host_ids = (int32_t *)calloc(n_experts, sizeof(int32_t));
    if (!host_b || !host_b_q8 || !host_a || !host_c || !host_tpe || !host_ids) {
        free(host_b); free(host_b_q8); free(host_a); free(host_c); free(host_tpe); free(host_ids);
        return 0;
    }
    /* Each expert gets weights B[e, m, k] = ((m*13 + k*7 + e*53) % 250) - 125.
     * Each expert routes 1 row: htpe[e] = 1, hids[e*1 + 0] = e (idt=e, ide=0).
     * Output dst[e*M + r] should be sum_k B[e, r, k] * 1.0. */
    for (uint32_t e = 0; e < n_experts; e++) {
        for (uint32_t m = 0; m < M; m++) {
            for (uint32_t k = 0; k < K; k++) {
                host_b[((uint64_t)e * M + m) * K + k] =
                    (float)((int)((m * 13 + k * 7 + e * 53) % 250) - 125);
            }
            uint8_t *dst_row = host_b_q8 + ((uint64_t)e * M + m) * q8_row_bytes;
            ds4_quantize_q8_0_row(host_b + ((uint64_t)e * M + m) * K, K, dst_row);
            /* Dequant back for reference */
            for (uint32_t b = 0; b < n_blocks_per_row; b++) {
                const uint8_t *blk = dst_row + (uint64_t)b * 34u;
                _Float16 d_half; memcpy(&d_half, blk, sizeof(d_half));
                const float d = (float)d_half;
                const int8_t *qs = (const int8_t *)(blk + 2);
                for (uint32_t i = 0; i < 32; i++) {
                    host_b[((uint64_t)e * M + m) * K + (uint64_t)b * 32u + i] =
                        (float)qs[i] * d;
                }
            }
        }
        host_tpe[e] = 1u;
        host_ids[e] = (int32_t)e;  /* token e, slot 0 */
    }
    _Float16 one = (_Float16)1.0f;
    for (uint64_t i = 0; i < a_total; i++) memcpy(&host_a[i], &one, sizeof(one));

    /* Expected: c[e*M + m] = sum_k B[e, m, k] (input is all-ones, every token routes to its own expert) */
    float *expected = (float *)calloc(c_total, sizeof(float));
    for (uint32_t e = 0; e < n_experts; e++) {
        for (uint32_t m = 0; m < M; m++) {
            double s = 0.0;
            for (uint32_t k = 0; k < K; k++) s += (double)host_b[((uint64_t)e * M + m) * K + k];
            expected[(uint64_t)e * c_per_token + m] = (float)s;
        }
    }

    ds4_mtl4_canary_cfg_t cfg;
    memset(&cfg, 0, sizeof(cfg));
    cfg.b_total       = b_q8_total;
    cfg.a_total_elems = a_total;
    cfg.c_total_elems = c_total;
    cfg.M = M; cfg.K = K; cfg.n_experts = n_experts;
    cfg.row_bytes     = q8_row_bytes;
    cfg.shmem_bytes   = 8192u;
    int rc = ds4_mtl4_mm_id_canary_dispatch(
        g_mul_mm_id_q8_0_f32_mtl4_pipeline, &cfg, (const uint8_t *)host_b_q8, host_a, host_tpe, host_ids, host_c);
    if (!rc) {
        free(host_b); free(host_b_q8); free(host_a); free(host_c);
        free(host_tpe); free(host_ids); free(expected);
        return 0;
    }

    /* Same FP16-staged Q8_0 drift bound as #733: 5% relative. */
    int mismatch = 0;
    double max_rel = 0.0;
    for (uint64_t i = 0; i < c_total; i++) {
        const double d = fabs((double)(host_c[i] - expected[i]));
        const double rel = d / (fabs((double)expected[i]) + 1e-3);
        if (rel > max_rel) max_rel = rel;
        if (rel > 5e-2) mismatch++;
    }
    fprintf(stderr,
        "ds4: mul_mm_id_q8_0_f32 MTL4 canary M=%u N=%u K=%u E=%u mismatch=%d max_rel=%.4e "
        "c[e0,0]=%.2f (ref=%.2f) c[e0,M-1]=%.2f c[eN-1,0]=%.2f\n",
        M, N, K, n_experts, mismatch, max_rel,
        (double)host_c[0], (double)expected[0],
        (double)host_c[M - 1], (double)host_c[(uint64_t)(n_experts - 1) * c_per_token]);
    free(host_b); free(host_b_q8); free(host_a); free(host_c);
    free(host_tpe); free(host_ids); free(expected);
    return (mismatch == 0) ? 1 : 0;
}

/* IQ2_XXS MSL source builder — single template for n32/n64/n128 widths.
 * silv 2026-05-28 R1 consolidation: includes 2KB iq2xxs_grid + 128B
 * ksigns_iq2xs + 8B kmask_iq2xs tables embedded inline. Same NR1/k
 * pattern as q4_K/q2_K/q8_0 builders. */
static NSString *ds4_mm_id_iq2_xxs_msl(int nr1, const char *suffix) {
    return [NSString stringWithFormat:
        @"#include <metal_stdlib>\n"
