         "  int ne00; int ne02;\n"
         "  ulong nb01; ulong nb02; ulong nb03;\n"
         "  int ne11;\n"
         "  ulong nb10; ulong nb11; ulong nb12; ulong nb13;\n"
         "  int ne20; int ne21;\n"
         "  int ne0; int ne1;\n"
         "  short r2; short r3;\n"
