         "    device const mm_id_args *args [[buffer(0)]],\n"
         "    device const char       *src0 [[buffer(1)]],\n"
         "    device const char       *src1 [[buffer(2)]],\n"
         "    device const char       *htpe [[buffer(3)]],\n"
         "    device const char       *hids [[buffer(4)]],\n"
