/* mul_mm_id_q8_0_f32_n128 MTL4 port (silv 2026-05-28 #743)            */
/* ============================================================ */
/* Routed MoE Q8_0 prefill matmul. Same kernel shape as #733 dense
 * mul_mm_q8_0 but with two extra buffers:
 *   - htpe : uint32_t[ne02]  — number of routed rows per expert
 *   - hids : int32_t[ne02*ne21] — encoded (slot, token) ids
 * The kernel reads im = tgpig.z (expert idx), bails if r1 >= tpe[im],
 * then decodes id = hids[im*ne21 + r1 + lr1] as (ide=id%ne20,
 * idt=id/ne20) and uses (idt, ide%ne11) as (i12, i11) for src1 read.
 *
 * Output write fans into a second loop that re-decodes id per output
 * row and writes dst + r0 + ide*ne0 + idt*ne1*ne0.
 *
 * This is the DS4 shared-expert prefill path for Q8_0 weights; sister
 * dense kernel (#733) drives non-routed shared experts. Adds 1 to the
 * 5 mul_mm_id_map0 variants (#706-#729) already in the MTL4 set.
 */

static id<MTLComputePipelineState> g_mul_mm_id_q8_0_f32_n128_mtl4_pipeline;
static int g_mul_mm_id_q8_0_f32_n128_mtl4_init_attempted;
