/* silv 2026-05-28 I-1 wiring probe: call ds4_gpu_routed_mm_pipeline_for_tile
 * for each (type, tile_n) and print which pipeline got selected. Pair with
 * DS4_METAL_LOG_ROUTED_MM=1 env to see the per-pick log lines. This is the
 * smoke test for the MTL4-redirect — confirms n64/n128 picks the fixed
 * kernels not antirez. */
int ds4_gpu_mtl4_routed_mm_dispatch_probe(void) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    const uint32_t types[3] = { DS4_METAL_TENSOR_IQ2_XXS, DS4_METAL_TENSOR_Q4_K, DS4_METAL_TENSOR_Q2_K };
    const char *type_names[3] = { "IQ2_XXS", "Q4_K", "Q2_K" };
    const uint32_t tiles[3] = { 32, 64, 128 };
    int total_ok = 0, total = 0;
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            id<MTLComputePipelineState> p = ds4_gpu_routed_mm_pipeline_for_tile(types[i], tiles[j]);
            const int ok = (p != nil) ? 1 : 0;
            fprintf(stderr, "ds4: routed_mm probe type=%s tile_n=%u → pipeline=%s\n",
                    type_names[i], tiles[j], ok ? "OK" : "NIL");
            total += 1;
            total_ok += ok;
        }
    }
    fprintf(stderr, "ds4: routed_mm probe %d/%d pipelines selected non-nil\n", total_ok, total);
    return (total_ok == total) ? 1 : 0;
}

/* ============================================================ */
/* VQB2 GPU decoder kernel (silv 2026-05-28)                    */
/* ============================================================ */
/* The runtime substrate codex H2116-H2125 calls for: read VQB2 packets
 * directly from the pack mmap on the GPU, decode (re, im) pairs into
 * fp16 output without CPU-side dequant. This is the elementary primitive
 * — one thread per pair — that unblocks pack-direct dispatch.
 *
 * Inputs:
 *   - codebook: K × 2 floats (the packet's centroids)
 *   - codes:    packed bit stream (2/4/6/8-bit codes, little-bit-endian)
 *   - args:     bit_width, code_mask, n_codes_to_decode, start_linear
 *   - out_fp16: 2 halves per pair (re, im)
 *
 * Decoder mirrors ds4_vqb2_reader.c vqb2_extract_code exactly. Verified
 * by canary against ds4_vqb2_decode_pair.
 *
 * 1D thread grid: one thread per code. Threadgroup size 64. */

static id<MTLComputePipelineState> g_vqb2_decode_fp16_mtl4_pipeline;
static int g_vqb2_decode_fp16_mtl4_init_attempted;
static int g_vqb2_decode_fp16_mtl4_init_ok;

/* silv 2026-05-28 lazy-module-import fix: the base VQB2 decoder MSL is
 * shared by the MTL4-path pipeline init (this function) AND the classic-MTL
 * pipeline init (used for ICB Phase 8). Previously each function held its
 * own copy of the 35-line MSL source — a real drift risk if the decoder
 * formula changes. Single source, both paths import it. The kernel name
 * is shared (`vqb2_decode_fp16`); the MTL4-suffixed init produces a
 * separately-compiled MTL4 pipeline while the classic init produces a
 * classic-MTL pipeline with supportIndirectCommandBuffers=YES.
 *
 * NOT THREAD-SAFE: assumes single-threaded engine init. All sibling
 * `_init_attempted = 1` patterns share this assumption; concurrent init
 * would race on the first-call compile path. */
/* silv 2026-05-28 OOM-speedup batched variant: one dispatch, 3D grid covers
 * (codes_per_expert × n_selected × n_packets). All packets share codebook +
 * selection list; codes_base + out_base are big buffers indexed by packet via
 * stride args. Eliminates per-packet dispatch overhead which the stacked
 * bench revealed dominates at typical layer-event granularity (~1.4 ms per
 * dispatch vs ~12 μs of actual memory-bandwidth work). Layer event = one
 * commit instead of 64 dispatches. */
static NSString * const k_vqb2_decode_fp16_batched_msl =
    @"#include <metal_stdlib>\n"
     "using namespace metal;\n"
     "struct args_t {\n"
     "  uint bit_width;\n"
     "  uint code_mask;\n"
     "  uint n_rows;\n"
     "  uint n_pairs;\n"
     "  uint n_selected;\n"
     "  uint n_packets;\n"
     "  uint codes_stride;\n"
     "  uint out_stride;\n"
     "};\n"
     "kernel void vqb2_decode_fp16_batched(\n"
     "    device const args_t *args         [[buffer(0)]],\n"
     "    device const float  *codebook     [[buffer(1)]],\n"
     "    device const uchar  *codes_base   [[buffer(2)]],\n"
     "    device const uint   *selected     [[buffer(3)]],\n"
     "    device       half2  *out_base     [[buffer(4)]],\n"
     "    uint3 gid [[thread_position_in_grid]]) {\n"
     "  const uint codes_per_expert = args->n_rows * args->n_pairs;\n"
     "  if (gid.x >= codes_per_expert) return;\n"
     "  if (gid.y >= args->n_selected) return;\n"
     "  if (gid.z >= args->n_packets) return;\n"
     "  const device uchar *codes = codes_base + gid.z * args->codes_stride;\n"
     "  device       half2 *out   = out_base   + gid.z * args->out_stride;\n"
     "  const uint expert = selected[gid.y];\n"
     "  const uint linear = expert * codes_per_expert + gid.x;\n"
     "  const uint bit_off = linear * args->bit_width;\n"
     "  const uint byte_off = bit_off >> 3;\n"
     "  const uint shift = bit_off & 7u;\n"
     "  const uint lo = (uint)codes[byte_off];\n"
     "  const uint hi = (args->bit_width + shift > 8u) ? (uint)codes[byte_off + 1u] : 0u;\n"
     "  const uint window = lo | (hi << 8);\n"
     "  const uint code = (window >> shift) & args->code_mask;\n"
     "  const float re = codebook[code * 2u + 0u];\n"
     "  const float im = codebook[code * 2u + 1u];\n"
     "  out[gid.y * codes_per_expert + gid.x] = half2((half)re, (half)im);\n"
     "}\n";

static id<MTLComputePipelineState> g_vqb2_decode_fp16_batched_mtl4_pipeline;
static int g_vqb2_decode_fp16_batched_mtl4_init_attempted;
static int g_vqb2_decode_fp16_batched_mtl4_init_ok;

static int ds4_vqb2_decode_fp16_batched_mtl4_pipeline_init(void) {
    if (g_vqb2_decode_fp16_batched_mtl4_init_attempted) return g_vqb2_decode_fp16_batched_mtl4_init_ok;
    g_vqb2_decode_fp16_batched_mtl4_init_attempted = 1;
    g_vqb2_decode_fp16_batched_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        k_vqb2_decode_fp16_batched_msl, @"ds4_vqb2_decode_fp16_batched_mtl4",
        @"vqb2_decode_fp16_batched", 64, NULL, 0);
    g_vqb2_decode_fp16_batched_mtl4_init_ok =
        (g_vqb2_decode_fp16_batched_mtl4_pipeline != nil) ? 1 : 0;
    return g_vqb2_decode_fp16_batched_mtl4_init_ok;
}

/* ============================================================ */
/* VECTORIZED VQB2 DECODER — silv 2026-05-28 OOM-speedup target  */
/* ============================================================ */
/* Earlier stacked bench (tmp/20260528_cache_audit/SPEEDUP_ANALYSIS.md)
 * found per-code kernel is instruction-bound at ~4 G outputs/sec
 * (~8 inst/code: cond-load, shift, mask, LUT, cast, store). This
 * vectorizes the bit-extraction by processing 8 codes per thread for
 * K=16 (4-bit codes) and 4 codes per thread for K=256 (8-bit codes).
 *
 * Per-K specialization eliminates the `(bw+shift>8) ? codes[byte+1] : 0`
 * branch (alignment is known at compile time). One uint32 load fetches
 * 8 nibbles (K=16) or 4 bytes (K=256); the body is 1 load + N shifts +
 * N lookups + N stores. Instruction count drops from ~8/code to ~3/code.
 *
 * Cache key requirements (for byte-alignment safety):
 *   - K=16: codes_per_expert MUST be divisible by 8 (8 codes per uint32)
 *   - K=256: codes_per_expert MUST be divisible by 4
 *   For DS4 V4 Flash (n_rows=128, n_pairs=256/1024): codes_per_expert ∈
 *   {32768, 131072} — both divisible by 8 ✓.
 *
 * Output: same packed-by-selection-order layout as the base kernel; both
 * are byte-exact for valid inputs. */

static NSString * const k_vqb2_decode_fp16_k16_x8_msl =
    @"#include <metal_stdlib>\n"
     "using namespace metal;\n"
     "struct args_t {\n"
     "  uint n_rows;\n"
     "  uint n_pairs;\n"
     "  uint n_selected;\n"
     "  uint n_packets;\n"
     "  uint codes_stride;\n"
     "  uint out_stride;\n"
     "  uint pad0; uint pad1;\n"
     "};\n"
     "kernel void vqb2_decode_fp16_k16_x8(\n"
     "    device const args_t *args         [[buffer(0)]],\n"
     "    device const float  *codebook     [[buffer(1)]],\n"
     "    device const uchar  *codes_base   [[buffer(2)]],\n"
     "    device const uint   *selected     [[buffer(3)]],\n"
     "    device       half2  *out_base     [[buffer(4)]],\n"
     "    uint3 gid [[thread_position_in_grid]]) {\n"
     "  const uint codes_per_expert = args->n_rows * args->n_pairs;\n"
     "  const uint x_base = gid.x * 8u;\n"
     "  if (x_base >= codes_per_expert) return;\n"
     "  if (gid.y >= args->n_selected) return;\n"
     "  if (gid.z >= args->n_packets) return;\n"
     "  const device uchar *codes = codes_base + gid.z * args->codes_stride;\n"
     "  device       half2 *out   = out_base   + gid.z * args->out_stride;\n"
     "  const uint expert = selected[gid.y];\n"
     "  const uint linear_base = expert * codes_per_expert + x_base;\n"
     "  /* K=16 → bit_width=4 → 8 codes = 32 bits = 1 uint32. Bytes-aligned. */\n"
     "  const uint byte_off = linear_base >> 1;\n"
     "  const device uint *codes_u32 = (device const uint *)(codes + byte_off);\n"
     "  const uint packed = *codes_u32;\n"
     "  const uint out_idx = gid.y * codes_per_expert + x_base;\n"
     "  /* Extract 8 nibbles and emit 8 half2 (re, im) pairs */\n"
     "  for (uint i = 0; i < 8u; i++) {\n"
     "    const uint code = (packed >> (i * 4u)) & 0xFu;\n"
     "    const float re = codebook[code * 2u + 0u];\n"
     "    const float im = codebook[code * 2u + 1u];\n"
     "    out[out_idx + i] = half2((half)re, (half)im);\n"
     "  }\n"
     "}\n";

static id<MTLComputePipelineState> g_vqb2_decode_fp16_k16_x8_mtl4_pipeline;
static int g_vqb2_decode_fp16_k16_x8_mtl4_init_attempted;
static int g_vqb2_decode_fp16_k16_x8_mtl4_init_ok;

static int ds4_vqb2_decode_fp16_k16_x8_mtl4_pipeline_init(void) {
    if (g_vqb2_decode_fp16_k16_x8_mtl4_init_attempted) return g_vqb2_decode_fp16_k16_x8_mtl4_init_ok;
    g_vqb2_decode_fp16_k16_x8_mtl4_init_attempted = 1;
    g_vqb2_decode_fp16_k16_x8_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        k_vqb2_decode_fp16_k16_x8_msl, @"ds4_vqb2_decode_fp16_k16_x8_mtl4",
        @"vqb2_decode_fp16_k16_x8", 64, NULL, 0);
    g_vqb2_decode_fp16_k16_x8_mtl4_init_ok =
        (g_vqb2_decode_fp16_k16_x8_mtl4_pipeline != nil) ? 1 : 0;
    return g_vqb2_decode_fp16_k16_x8_mtl4_init_ok;
}

/* Vectorized K=4 (2-bit codes): 16 codes per thread = 32 bits = 1 uint32.
 * Byte-aligned for codes_per_expert divisible by 16; n_rows×n_pairs ≥ 1024×128
 * in DS4 → divisible by 16 ✓. */
static NSString * const k_vqb2_decode_fp16_k4_x16_msl =
    @"#include <metal_stdlib>\n"
     "using namespace metal;\n"
     "struct args_t {\n"
     "  uint n_rows;\n"
     "  uint n_pairs;\n"
     "  uint n_selected;\n"
     "  uint n_packets;\n"
     "  uint codes_stride;\n"
     "  uint out_stride;\n"
     "  uint pad0; uint pad1;\n"
     "};\n"
     "kernel void vqb2_decode_fp16_k4_x16(\n"
     "    device const args_t *args         [[buffer(0)]],\n"
     "    device const float  *codebook     [[buffer(1)]],\n"
     "    device const uchar  *codes_base   [[buffer(2)]],\n"
     "    device const uint   *selected     [[buffer(3)]],\n"
     "    device       half2  *out_base     [[buffer(4)]],\n"
     "    uint3 gid [[thread_position_in_grid]]) {\n"
     "  const uint codes_per_expert = args->n_rows * args->n_pairs;\n"
     "  const uint x_base = gid.x * 16u;\n"
     "  if (x_base >= codes_per_expert) return;\n"
     "  if (gid.y >= args->n_selected) return;\n"
     "  if (gid.z >= args->n_packets) return;\n"
     "  const device uchar *codes = codes_base + gid.z * args->codes_stride;\n"
     "  device       half2 *out   = out_base   + gid.z * args->out_stride;\n"
     "  const uint expert = selected[gid.y];\n"
     "  const uint linear_base = expert * codes_per_expert + x_base;\n"
     "  /* K=4 → bit_width=2 → 16 codes = 32 bits */\n"
     "  const uint byte_off = linear_base >> 2;\n"
     "  const device uint *codes_u32 = (device const uint *)(codes + byte_off);\n"
     "  const uint packed = *codes_u32;\n"
     "  const uint out_idx = gid.y * codes_per_expert + x_base;\n"
     "  for (uint i = 0; i < 16u; i++) {\n"
     "    const uint code = (packed >> (i * 2u)) & 0x3u;\n"
     "    const float re = codebook[code * 2u + 0u];\n"
     "    const float im = codebook[code * 2u + 1u];\n"
     "    out[out_idx + i] = half2((half)re, (half)im);\n"
     "  }\n"
     "}\n";

static id<MTLComputePipelineState> g_vqb2_decode_fp16_k4_x16_mtl4_pipeline;
static int g_vqb2_decode_fp16_k4_x16_mtl4_init_attempted;
static int g_vqb2_decode_fp16_k4_x16_mtl4_init_ok;

static int ds4_vqb2_decode_fp16_k4_x16_mtl4_pipeline_init(void) {
    if (g_vqb2_decode_fp16_k4_x16_mtl4_init_attempted) return g_vqb2_decode_fp16_k4_x16_mtl4_init_ok;
    g_vqb2_decode_fp16_k4_x16_mtl4_init_attempted = 1;
    g_vqb2_decode_fp16_k4_x16_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        k_vqb2_decode_fp16_k4_x16_msl, @"ds4_vqb2_decode_fp16_k4_x16_mtl4",
        @"vqb2_decode_fp16_k4_x16", 64, NULL, 0);
    g_vqb2_decode_fp16_k4_x16_mtl4_init_ok =
        (g_vqb2_decode_fp16_k4_x16_mtl4_pipeline != nil) ? 1 : 0;
    return g_vqb2_decode_fp16_k4_x16_mtl4_init_ok;
}

/* Vectorized K=256 (8-bit codes): 4 codes per thread = 32 bits = 1 uint32. */
static NSString * const k_vqb2_decode_fp16_k256_x4_msl =
    @"#include <metal_stdlib>\n"
     "using namespace metal;\n"
     "struct args_t {\n"
     "  uint n_rows;\n"
     "  uint n_pairs;\n"
     "  uint n_selected;\n"
     "  uint n_packets;\n"
     "  uint codes_stride;\n"
     "  uint out_stride;\n"
     "  uint pad0; uint pad1;\n"
     "};\n"
     "kernel void vqb2_decode_fp16_k256_x4(\n"
     "    device const args_t *args         [[buffer(0)]],\n"
     "    device const float  *codebook     [[buffer(1)]],\n"
     "    device const uchar  *codes_base   [[buffer(2)]],\n"
     "    device const uint   *selected     [[buffer(3)]],\n"
     "    device       half2  *out_base     [[buffer(4)]],\n"
     "    uint3 gid [[thread_position_in_grid]]) {\n"
     "  const uint codes_per_expert = args->n_rows * args->n_pairs;\n"
     "  const uint x_base = gid.x * 4u;\n"
     "  if (x_base >= codes_per_expert) return;\n"
     "  if (gid.y >= args->n_selected) return;\n"
     "  if (gid.z >= args->n_packets) return;\n"
     "  const device uchar *codes = codes_base + gid.z * args->codes_stride;\n"
     "  device       half2 *out   = out_base   + gid.z * args->out_stride;\n"
     "  const uint expert = selected[gid.y];\n"
     "  const uint linear_base = expert * codes_per_expert + x_base;\n"
     "  /* K=256 → bit_width=8 → 4 codes = 32 bits */\n"
     "  const device uint *codes_u32 = (device const uint *)(codes + linear_base);\n"
     "  const uint packed = *codes_u32;\n"
     "  const uint out_idx = gid.y * codes_per_expert + x_base;\n"
     "  for (uint i = 0; i < 4u; i++) {\n"
     "    const uint code = (packed >> (i * 8u)) & 0xFFu;\n"
     "    const float re = codebook[code * 2u + 0u];\n"
     "    const float im = codebook[code * 2u + 1u];\n"
     "    out[out_idx + i] = half2((half)re, (half)im);\n"
     "  }\n"
     "}\n";

static id<MTLComputePipelineState> g_vqb2_decode_fp16_k256_x4_mtl4_pipeline;
static int g_vqb2_decode_fp16_k256_x4_mtl4_init_attempted;
static int g_vqb2_decode_fp16_k256_x4_mtl4_init_ok;

static int ds4_vqb2_decode_fp16_k256_x4_mtl4_pipeline_init(void) {
    if (g_vqb2_decode_fp16_k256_x4_mtl4_init_attempted) return g_vqb2_decode_fp16_k256_x4_mtl4_init_ok;
    g_vqb2_decode_fp16_k256_x4_mtl4_init_attempted = 1;
    g_vqb2_decode_fp16_k256_x4_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        k_vqb2_decode_fp16_k256_x4_msl, @"ds4_vqb2_decode_fp16_k256_x4_mtl4",
        @"vqb2_decode_fp16_k256_x4", 64, NULL, 0);
    g_vqb2_decode_fp16_k256_x4_mtl4_init_ok =
        (g_vqb2_decode_fp16_k256_x4_mtl4_pipeline != nil) ? 1 : 0;
    return g_vqb2_decode_fp16_k256_x4_mtl4_init_ok;
}

/* Diagnostic baseline kernels — silv 2026-05-28.
 *
 * Localize the 2.2 GB/s wall the vectorization couldn't break. Two variants
 * stripped down to isolate each candidate bottleneck:
 *
 *   NOOP_WRITE: writes a CONSTANT half2 — no codes load, no codebook lookup.
 *               If this also hits 2.2 GB/s, the wall is in pure GPU write
 *               throughput at this dispatch shape (cache-line scatter,
 *               threadgroup launch overhead, or similar).
 *
 *   NOOP_FULL: empty kernel body, just early-exit on first thread.
 *              Measures launch + sync overhead only. If this is ~87 ms
 *              for the same dispatch shape, the launch is the wall.
 *
 * Same args struct + dispatch grid as the decoder kernels for apples-to-apples. */
static NSString * const k_vqb2_noop_write_msl =
    @"#include <metal_stdlib>\n"
     "using namespace metal;\n"
     "struct args_t {\n"
     "  uint n_rows;\n"
     "  uint n_pairs;\n"
     "  uint n_selected;\n"
     "  uint n_packets;\n"
     "  uint codes_stride;\n"
     "  uint out_stride;\n"
     "  uint pad0; uint pad1;\n"
     "};\n"
     "kernel void vqb2_noop_write(\n"
     "    device const args_t *args         [[buffer(0)]],\n"
     "    device const float  *codebook     [[buffer(1)]],\n"
     "    device const uchar  *codes_base   [[buffer(2)]],\n"
     "    device const uint   *selected     [[buffer(3)]],\n"
     "    device       half2  *out_base     [[buffer(4)]],\n"
     "    uint3 gid [[thread_position_in_grid]]) {\n"
     "  const uint codes_per_expert = args->n_rows * args->n_pairs;\n"
     "  const uint ept = args->pad0 > 0u ? args->pad0 : 1u;\n"  /* elems-per-thread: coarsen test */
     "  const uint base_x = gid.x * ept;\n"
     "  if (base_x >= codes_per_expert) return;\n"
     "  if (gid.y >= args->n_selected) return;\n"
     "  if (gid.z >= args->n_packets) return;\n"
     "  device half2 *out = out_base + gid.z * args->out_stride;\n"
     "  const uint row0 = gid.y * codes_per_expert;\n"
     "  const uint lim = min(base_x + ept, codes_per_expert);\n"
     "  for (uint x = base_x; x < lim; x++) {\n"
     "    out[row0 + x] = half2(half(1.0), half(-1.0));\n"
     "  }\n"
     "}\n";

static id<MTLComputePipelineState> g_vqb2_noop_write_mtl4_pipeline;
static int g_vqb2_noop_write_mtl4_init_attempted;
static int g_vqb2_noop_write_mtl4_init_ok;

static int ds4_vqb2_noop_write_mtl4_pipeline_init(void) {
    if (g_vqb2_noop_write_mtl4_init_attempted) return g_vqb2_noop_write_mtl4_init_ok;
    g_vqb2_noop_write_mtl4_init_attempted = 1;
    g_vqb2_noop_write_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        k_vqb2_noop_write_msl, @"ds4_vqb2_noop_write_mtl4",
        @"vqb2_noop_write", 64, NULL, 0);
    g_vqb2_noop_write_mtl4_init_ok =
        (g_vqb2_noop_write_mtl4_pipeline != nil) ? 1 : 0;
    return g_vqb2_noop_write_mtl4_init_ok;
}

int ds4_gpu_mtl4_vqb2_noop_write_bench(uint32_t n_packets, uint32_t n_selected,
                                       uint32_t n_rows, uint32_t n_pairs,
                                       uint32_t rounds) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_vqb2_noop_write_mtl4_pipeline_init()) return 0;
    if (n_packets == 0 || n_selected == 0 || n_rows == 0 || n_pairs == 0 || rounds == 0) return 0;

    const uint32_t codes_per_expert = n_rows * n_pairs;
    const size_t sel_out_per_packet = (size_t)n_selected * codes_per_expert * 2u * sizeof(_Float16);
    const char *ept_env = getenv("DS4_NOOP_EPT");   /* elems-per-thread coarsen test (task #823) */
    uint32_t ept = ept_env ? (uint32_t)atoi(ept_env) : 1u;
    if (ept == 0u) ept = 1u;
    double t_ms = 0;
    int rc = 0;

    @autoreleasepool {
        const MTLResourceOptions out_mode = getenv("DS4_NOOP_PRIVATE")
            ? MTLResourceStorageModePrivate : MTLResourceStorageModeShared;  /* storage-mode test #823 */
        id<MTLBuffer> outBuf = [g_device newBufferWithLength:(NSUInteger)n_packets * sel_out_per_packet
                                                    options:out_mode];
        struct args_t {
            uint32_t n_rows, n_pairs, n_selected, n_packets,
                     codes_stride, out_stride, pad0, pad1;
        } args = {
            n_rows, n_pairs, n_selected, n_packets,
            0,
            (uint32_t)(sel_out_per_packet / sizeof(_Float16) / 2u),
            ept, 0,   /* pad0 carries elems-per-thread */
        };
        id<MTLBuffer> argsBuf = [g_device newBufferWithBytes:&args length:sizeof(args)
                                                     options:MTLResourceStorageModeShared];
        if (!outBuf || !argsBuf) return 0;

        mach_timebase_info_data_t tb; mach_timebase_info(&tb);
        const uint64_t t0 = mach_absolute_time();
        for (uint32_t r = 0; r < rounds; r++) {
            id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
            [cb beginCommandBufferWithAllocator:g_polar_allocator];
            id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
            id<MTL4ArgumentTable> at = ds4_mtl4_pool_acquire(8);
            if (!at) return 0;
            [at setAddress:argsBuf.gpuAddress atIndex:0];
            [at setAddress:0 atIndex:1];  /* codebook unused */
            [at setAddress:0 atIndex:2];  /* codes_base unused */
            [at setAddress:0 atIndex:3];  /* selected unused */
            [at setAddress:outBuf.gpuAddress atIndex:4];
            [enc setComputePipelineState:g_vqb2_noop_write_mtl4_pipeline];
            [enc setArgumentTable:at];
            [enc dispatchThreadgroups:MTLSizeMake((((codes_per_expert + ept - 1u) / ept) + 63u) / 64u, n_selected, n_packets)
                threadsPerThreadgroup:MTLSizeMake(64, 1, 1)];
            [enc endEncoding];
            [cb endCommandBuffer];
            dispatch_semaphore_t sem = dispatch_semaphore_create(0);
            MTL4CommitOptions *opts = [MTL4CommitOptions new];
            [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) { (void)fb; dispatch_semaphore_signal(sem); }];
            id<MTL4CommandBuffer> bufs[1] = {cb};
            [g_polar_queue commit:bufs count:1 options:opts];
            dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 10LL * NSEC_PER_SEC));
            ds4_mtl4_pool_release(at, 8);
        }
        const uint64_t t1 = mach_absolute_time();
        t_ms = (double)(t1 - t0) * (double)tb.numer / (double)tb.denom / 1e6;
        rc = 1;
    }
    const uint64_t bytes_per_round =
        (uint64_t)n_packets * n_selected * codes_per_expert * 2u * sizeof(_Float16);
    const double gbs = ((double)bytes_per_round * rounds / 1e9) / (t_ms / 1000.0);
    fprintf(stderr,
        "ds4: vqb2_noop_write_bench n_packets=%u n_sel=%u rows=%u pairs=%u rounds=%u\n"
        "  noop write only: %.3f ms (%.3f ms/round)  %.1f GB/s output  (vs decoder ~2.2 GB/s)\n"
        "  rc=%d\n",
        n_packets, n_selected, n_rows, n_pairs, rounds,
        t_ms, t_ms / (double)rounds, gbs, rc);
    return rc;
}

/* ============================================================ */
/* FUSED DECODE-MATMUL KERNEL — silv 2026-05-28                  */
/* ============================================================ */
/* The architectural move: instead of decode-then-store (which writes
 * 192 MB/round at 2.7 GB/s peak — the noop-write diagnostic showed
 * this is the wall), decode-on-demand inside the matmul inner loop.
 * Weights only exist transiently in registers; the intermediate fp16
 * write is eliminated entirely (192 MB → 96 KB output = 2000× reduction).
 *
 * Per output row r of expert e of packet p:
 *   acc = 0
 *   for pair_idx in [0, n_pairs):
 *     code = decode(codes[p], e, r, pair_idx)
 *     (re, im) = codebook[p][code]
 *     acc += X[pair_idx*2 + 0] * re + X[pair_idx*2 + 1] * im
 *   out[p][e_slot][r] = (half)acc
 *
 * Output shape: [n_packets][n_selected][n_rows]. Output bytes per layer
 * event = 64 packets × 6 selected × 128 rows × 2 = 96 KB (vs 192 MB
 * decode-then-store). Dispatch grid (n_rows, n_selected, n_packets) =
 * 128 × 6 × 64 = 49K threads vs prior 50M decode threads (1000× fewer
 * thread launches).
 *
 * V1: generic over bit_width (no K-specialization). One float accumulator
 * per thread, no threadgroup memory yet. X loaded redundantly per thread
 * — V2 optimization queued. */
static NSString * const k_vqb2_decode_matmul_fp16_msl =
    @"#include <metal_stdlib>\n"
     "using namespace metal;\n"
     "struct args_t {\n"
     "  uint bit_width;\n"
     "  uint code_mask;\n"
     "  uint n_rows;\n"
     "  uint n_pairs;\n"
     "  uint n_experts_in_packet;\n"
     "  uint n_selected;\n"
     "  uint codes_stride;\n"
     "  uint out_stride;\n"
     "  /* silv 2026-05-28 task #761 Phase 3 — per-slot X stride (in halves).\n"
     "   * 0 = shared X across all selected slots (existing gate/up behavior).\n"
     "   * >0 = each selected slot reads X[gid.y * x_slot_stride + i] — required\n"
     "   * for DOWN where each expert has its own mid input. Trailing field;\n"
     "   * existing callers' positional initializers leave it zero. */\n"
     "  uint x_slot_stride;\n"
     "};\n"
     "kernel void vqb2_decode_matmul_fp16(\n"
     "    device const args_t *args        [[buffer(0)]],\n"
     "    device const float  *codebook    [[buffer(1)]],\n"
     "    device const uchar  *codes_base  [[buffer(2)]],\n"
     "    device const uint   *selected    [[buffer(3)]],\n"
     "    device const half   *X           [[buffer(4)]],\n"
     "    device       half   *out_base    [[buffer(5)]],\n"
     "    threadgroup float *tg            [[threadgroup(0)]],\n"
     "    uint3 gid                        [[thread_position_in_grid]],\n"
     "    uint  tid                        [[thread_index_in_threadgroup]],\n"
     "    uint3 tg_dim                     [[threads_per_threadgroup]]) {\n"
     "  const uint tg_threads = tg_dim.x * tg_dim.y * tg_dim.z;\n"
     "  /* Threadgroup memory layout: codebook (K*2 floats) | X (np*2 floats).\n"
     "   * Each TG holds tg_threads rows of one (selected, packet) pair, so X is\n"
     "   * loaded once and reused across all rows — turns 32× redundant device\n"
     "   * reads of X into one cooperative load. */\n"
     "  const uint K = args->code_mask + 1u;\n"
     "  const uint cb_floats = K * 2u;\n"
     "  threadgroup float *cb_tg = tg;\n"
     "  threadgroup float *X_tg  = tg + cb_floats;\n"
     "  const uint np  = args->n_pairs;\n"
     "  const uint np2 = np * 2u;\n"
     "  /* Cooperative load (any tg_size works; codebook is ~32-512 floats, X is np*2). */\n"
     "  for (uint i = tid; i < cb_floats; i += tg_threads) cb_tg[i] = codebook[i];\n"
     "  /* Phase 3 (#761): per-slot X. Each threadgroup runs for one (selected_slot,\n"
     "   * row_block) — gid.y is the slot. When x_slot_stride > 0, slot s reads from\n"
     "   * X[s * x_slot_stride + i]; when 0, all slots share X (gate/up case). */\n"
     "  const uint x_off = (args->x_slot_stride > 0u) ? (gid.y * args->x_slot_stride) : 0u;\n"
     "  for (uint i = tid; i < np2; i += tg_threads) X_tg[i] = (float)X[x_off + i];\n"
     "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
     "  if (gid.x >= args->n_rows)     return;\n"
     "  if (gid.y >= args->n_selected) return;\n"
     "  const device uchar *codes = codes_base + gid.z * args->codes_stride;\n"
     "  const uint expert = selected[gid.y];\n"
     "  const uint codes_per_expert = args->n_rows * np;\n"
     "  const uint linear_base = expert * codes_per_expert + gid.x * np;\n"
     "  const uint bw = args->bit_width;\n"
     "  const uint mask = args->code_mask;\n"
     "  float acc = 0.0f;\n"
     "  /* Fast path: bw==4 (K=16). 8 pairs per iter via uint32 byte-load (32 bits = 8 nibbles).\n"
     "   * Codes start at byte_base = linear_base/2. Aligned when linear_base mul of 8\n"
     "   * (which holds when n_pairs % 8 == 0 since n_pairs*r is the row stride). */\n"
     "  if (bw == 4u && (np & 7u) == 0u && (linear_base & 7u) == 0u) {\n"
     "    const uint byte_base = linear_base >> 1;\n"
     "    for (uint p = 0; p < np; p += 8u) {\n"
     "      const uint w = *((const device uint *)(codes + byte_base + (p >> 1)));\n"
     "      const uint c0 = (w >>  0) & 0xFu;\n"
     "      const uint c1 = (w >>  4) & 0xFu;\n"
     "      const uint c2 = (w >>  8) & 0xFu;\n"
     "      const uint c3 = (w >> 12) & 0xFu;\n"
     "      const uint c4 = (w >> 16) & 0xFu;\n"
     "      const uint c5 = (w >> 20) & 0xFu;\n"
     "      const uint c6 = (w >> 24) & 0xFu;\n"
     "      const uint c7 = (w >> 28) & 0xFu;\n"
     "      const uint xb = p * 2u;\n"
     "      acc += X_tg[xb+ 0]*cb_tg[c0*2u  ] + X_tg[xb+ 1]*cb_tg[c0*2u+1];\n"
     "      acc += X_tg[xb+ 2]*cb_tg[c1*2u  ] + X_tg[xb+ 3]*cb_tg[c1*2u+1];\n"
     "      acc += X_tg[xb+ 4]*cb_tg[c2*2u  ] + X_tg[xb+ 5]*cb_tg[c2*2u+1];\n"
     "      acc += X_tg[xb+ 6]*cb_tg[c3*2u  ] + X_tg[xb+ 7]*cb_tg[c3*2u+1];\n"
     "      acc += X_tg[xb+ 8]*cb_tg[c4*2u  ] + X_tg[xb+ 9]*cb_tg[c4*2u+1];\n"
     "      acc += X_tg[xb+10]*cb_tg[c5*2u  ] + X_tg[xb+11]*cb_tg[c5*2u+1];\n"
     "      acc += X_tg[xb+12]*cb_tg[c6*2u  ] + X_tg[xb+13]*cb_tg[c6*2u+1];\n"
     "      acc += X_tg[xb+14]*cb_tg[c7*2u  ] + X_tg[xb+15]*cb_tg[c7*2u+1];\n"
     "    }\n"
     "  } else if (bw == 4u && (np & 1u) == 0u) {\n"
     "    /* Slow K=16 path: byte-aligned but uint32 alignment doesn't hold. */\n"
     "    const uint byte_base = linear_base >> 1;\n"
     "    for (uint p = 0; p < np; p += 2u) {\n"
     "      const uint b = (uint)codes[byte_base + (p >> 1)];\n"
     "      const uint code0 = b & 0xFu;\n"
     "      const uint code1 = b >> 4;\n"
     "      acc += X_tg[p*2u  ]*cb_tg[code0*2u  ] + X_tg[p*2u+1]*cb_tg[code0*2u+1];\n"
     "      acc += X_tg[(p+1u)*2u]*cb_tg[code1*2u] + X_tg[(p+1u)*2u+1]*cb_tg[code1*2u+1];\n"
     "    }\n"
     "  } else if (bw == 2u && (np & 15u) == 0u && (linear_base & 15u) == 0u) {\n"
     "    /* Fast K=4: 16 pairs per iter via uint32 byte-load (32 bits = 16 2-bit codes). */\n"
     "    const uint byte_base = linear_base >> 2;\n"
     "    for (uint p = 0; p < np; p += 16u) {\n"
     "      const uint w = *((const device uint *)(codes + byte_base + (p >> 2)));\n"
     "      const uint xb = p * 2u;\n"
     "      for (uint i = 0; i < 16; i++) {\n"
     "        const uint c = (w >> (i * 2u)) & 3u;\n"
     "        acc += X_tg[xb + 2u*i]*cb_tg[c*2u] + X_tg[xb + 2u*i + 1u]*cb_tg[c*2u+1];\n"
     "      }\n"
     "    }\n"
     "  } else if (bw == 2u && (np & 3u) == 0u) {\n"
     "    /* Slow K=4: byte-aligned but uint32-misaligned. */\n"
     "    const uint byte_base = linear_base >> 2;\n"
     "    for (uint p = 0; p < np; p += 4u) {\n"
     "      const uint b = (uint)codes[byte_base + (p >> 2)];\n"
     "      const uint c0 = b & 3u;\n"
     "      const uint c1 = (b >> 2) & 3u;\n"
     "      const uint c2 = (b >> 4) & 3u;\n"
     "      const uint c3 = (b >> 6) & 3u;\n"
     "      acc += X_tg[(p+0u)*2u+0u]*cb_tg[c0*2u+0u] + X_tg[(p+0u)*2u+1u]*cb_tg[c0*2u+1u];\n"
     "      acc += X_tg[(p+1u)*2u+0u]*cb_tg[c1*2u+0u] + X_tg[(p+1u)*2u+1u]*cb_tg[c1*2u+1u];\n"
     "      acc += X_tg[(p+2u)*2u+0u]*cb_tg[c2*2u+0u] + X_tg[(p+2u)*2u+1u]*cb_tg[c2*2u+1u];\n"
     "      acc += X_tg[(p+3u)*2u+0u]*cb_tg[c3*2u+0u] + X_tg[(p+3u)*2u+1u]*cb_tg[c3*2u+1u];\n"
     "    }\n"
     "  } else if (bw == 8u && (np & 3u) == 0u && (linear_base & 3u) == 0u) {\n"
     "    /* Fast K=256: 4 pairs per iter via uint32 byte-load (4 bytes = 4 codes). */\n"
     "    const uint byte_base = linear_base;\n"
     "    for (uint p = 0; p < np; p += 4u) {\n"
     "      const uint w = *((const device uint *)(codes + byte_base + p));\n"
     "      const uint c0 = (w >>  0) & 0xFFu;\n"
     "      const uint c1 = (w >>  8) & 0xFFu;\n"
     "      const uint c2 = (w >> 16) & 0xFFu;\n"
     "      const uint c3 = (w >> 24) & 0xFFu;\n"
     "      const uint xb = p * 2u;\n"
     "      acc += X_tg[xb  ]*cb_tg[c0*2u  ] + X_tg[xb+1]*cb_tg[c0*2u+1];\n"
     "      acc += X_tg[xb+2]*cb_tg[c1*2u  ] + X_tg[xb+3]*cb_tg[c1*2u+1];\n"
     "      acc += X_tg[xb+4]*cb_tg[c2*2u  ] + X_tg[xb+5]*cb_tg[c2*2u+1];\n"
     "      acc += X_tg[xb+6]*cb_tg[c3*2u  ] + X_tg[xb+7]*cb_tg[c3*2u+1];\n"
     "    }\n"
     "  } else if (bw == 8u) {\n"
     "    /* Fast path: bw==8 (K=256), each pair == 1 byte. */\n"
     "    const uint byte_base = linear_base;\n"
     "    for (uint p = 0; p < np; p++) {\n"
     "      const uint code = (uint)codes[byte_base + p];\n"
     "      acc += X_tg[p*2u+0u]*cb_tg[code*2u+0u] + X_tg[p*2u+1u]*cb_tg[code*2u+1u];\n"
     "    }\n"
     "  } else {\n"
     "    /* Generic bit-aligned path for bw=6 (K=64) and unaligned configurations. */\n"
     "    for (uint p = 0; p < np; p++) {\n"
     "      const uint linear = linear_base + p;\n"
     "      const uint bit_off = linear * bw;\n"
     "      const uint byte_off = bit_off >> 3;\n"
     "      const uint shift = bit_off & 7u;\n"
     "      const uint lo = (uint)codes[byte_off];\n"
     "      const uint hi = (bw + shift > 8u) ? (uint)codes[byte_off + 1u] : 0u;\n"
     "      const uint window = lo | (hi << 8);\n"
     "      const uint code = (window >> shift) & mask;\n"
     "      acc += X_tg[p*2u+0u]*cb_tg[code*2u+0u] + X_tg[p*2u+1u]*cb_tg[code*2u+1u];\n"
     "    }\n"
     "  }\n"
     "  device half *out = out_base + gid.z * args->out_stride;\n"
     "  out[gid.y * args->n_rows + gid.x] = (half)acc;\n"
     "}\n";

