static int ds4_vqb2_decode_matmul_parallel_enabled(void) {
    static int checked = 0;
    static int enabled = 0;
    static int notice = 0;
    if (!checked) {
        const char *e = getenv("DS4_VQB2_PARALLEL_DECODE");
        enabled = (e && *e && e[0] != '0') ? 1 : 0;
        checked = 1;
    }
    if (enabled && !notice) {
        fprintf(stderr,
            "ds4: DS4_VQB2_PARALLEL_DECODE=1 — VQB2 decode matmul uses threadgroup-per-output reduction\n");
        notice = 1;
    }
    return enabled;
}

/* silv 2026-05-28 task #768 — vqb2_decode_matmul_fp16 x4row variant.
 *
 * 4 outputs per thread instead of 1. The X load + codebook indirection feed
 * 4 FMAs (4 row outputs) per inner step. Memory traffic per inner step is
 * unchanged for X (broadcast) and grows 4× for codes (4 row codes), but the
 * threadgroup-memory codebook lookup is shared via cb_tg[c*2+...] reads.
 *
 * Theoretical: 4× arithmetic intensity per X load. Expected speedup: 2-3×
 * on the H2125 shape if compute-bound (current 107 GFLOP/s; M1 Max peak
 * ~10.4 TFLOPS fp32, so we have 100× of headroom on compute).
 *
 * Correctness: float accumulator preserved per row; output is fp16 per row
 * unchanged. Cross-check vs the scalar kernel must be bit-exact in float
 * accumulation order (X is loaded once per pair, applied to 4 codes — same
 * order as 4 separate scalar invocations).
 *
 * Dispatch: gid = (n_rows/4, n_selected, n_packets), TG = 32 threads.
 * Each TG covers row_block = 32×4 = 128 rows. n_rows must be a multiple of 4. */
static NSString * const k_vqb2_decode_matmul_fp16_x4row_msl =
    @"#include <metal_stdlib>\n"
     "using namespace metal;\n"
     "struct args_t {\n"
     "  uint bit_width;\n"
     "  uint code_mask;\n"
     "  uint n_rows;\n"
     "  uint n_pairs;\n"
     "  uint n_experts_in_packet;\n"
     "  uint n_selected;\n"
     "  uint codes_stride;\n"
     "  uint out_stride;\n"
     "  uint x_slot_stride;\n"
     "};\n"
     "/* silv 2026-05-28 x4row args_t MUST match the bench struct order\n"
     " * {bit_width, code_mask, n_rows, n_pairs, n_experts_in_packet, n_selected,\n"
     " *  codes_stride, out_stride, x_slot_stride} — earlier swapped order caused\n"
     " * 100%% mismatch (read bit_width=4 as n_rows, all rows>0 returned early). */\n"
     "kernel void vqb2_decode_matmul_fp16_x4row(\n"
     "    device const args_t *args        [[buffer(0)]],\n"
     "    device const float  *codebook    [[buffer(1)]],\n"
     "    device const uchar  *codes_base  [[buffer(2)]],\n"
     "    device const uint   *selected    [[buffer(3)]],\n"
     "    device const half   *X           [[buffer(4)]],\n"
     "    device       half   *out_base    [[buffer(5)]],\n"
     "    threadgroup float *tg            [[threadgroup(0)]],\n"
     "    uint3 gid                        [[thread_position_in_grid]],\n"
     "    uint  tid                        [[thread_index_in_threadgroup]],\n"
     "    uint3 tg_dim                     [[threads_per_threadgroup]]) {\n"
     "  const uint tg_threads = tg_dim.x * tg_dim.y * tg_dim.z;\n"
     "  const uint K = args->code_mask + 1u;\n"
     "  const uint cb_floats = K * 2u;\n"
     "  threadgroup float *cb_tg = tg;\n"
     "  threadgroup float *X_tg  = tg + cb_floats;\n"
     "  const uint np  = args->n_pairs;\n"
     "  const uint np2 = np * 2u;\n"
     "  for (uint i = tid; i < cb_floats; i += tg_threads) cb_tg[i] = codebook[i];\n"
     "  const uint x_off = (args->x_slot_stride > 0u) ? (gid.y * args->x_slot_stride) : 0u;\n"
     "  for (uint i = tid; i < np2; i += tg_threads) X_tg[i] = (float)X[x_off + i];\n"
     "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
     "  const uint row_base = gid.x * 4u;\n"
     "  if (row_base >= args->n_rows)  return;\n"
     "  if (gid.y >= args->n_selected) return;\n"
     "  const device uchar *codes = codes_base + gid.z * args->codes_stride;\n"
     "  const uint expert = selected[gid.y];\n"
     "  const uint codes_per_expert = args->n_rows * np;\n"
     "  const uint linear_base0 = expert * codes_per_expert + (row_base + 0u) * np;\n"
     "  const uint linear_base1 = expert * codes_per_expert + (row_base + 1u) * np;\n"
     "  const uint linear_base2 = expert * codes_per_expert + (row_base + 2u) * np;\n"
     "  const uint linear_base3 = expert * codes_per_expert + (row_base + 3u) * np;\n"
     "  const uint bw = args->bit_width;\n"
     "  const uint mask = args->code_mask;\n"
     "  float acc0 = 0.0f, acc1 = 0.0f, acc2 = 0.0f, acc3 = 0.0f;\n"
     "  /* K=16 fast path: 8 pairs per iter via uint32 byte-load. */\n"
     "  if (bw == 4u && (np & 7u) == 0u && (linear_base0 & 7u) == 0u) {\n"
     "    const uint byte_base0 = linear_base0 >> 1;\n"
     "    const uint byte_base1 = linear_base1 >> 1;\n"
     "    const uint byte_base2 = linear_base2 >> 1;\n"
     "    const uint byte_base3 = linear_base3 >> 1;\n"
     "    for (uint p = 0; p < np; p += 8u) {\n"
     "      const uint w0 = *((const device uint *)(codes + byte_base0 + (p >> 1)));\n"
     "      const uint w1 = *((const device uint *)(codes + byte_base1 + (p >> 1)));\n"
     "      const uint w2 = *((const device uint *)(codes + byte_base2 + (p >> 1)));\n"
     "      const uint w3 = *((const device uint *)(codes + byte_base3 + (p >> 1)));\n"
     "      const uint xb = p * 2u;\n"
     "      for (uint i = 0; i < 8u; i++) {\n"
     "        const uint shift = i * 4u;\n"
     "        const uint c0 = (w0 >> shift) & 0xFu;\n"
     "        const uint c1 = (w1 >> shift) & 0xFu;\n"
     "        const uint c2 = (w2 >> shift) & 0xFu;\n"
     "        const uint c3 = (w3 >> shift) & 0xFu;\n"
     "        const float x_re = X_tg[xb + 2u*i];\n"
     "        const float x_im = X_tg[xb + 2u*i + 1u];\n"
     "        acc0 += x_re*cb_tg[c0*2u] + x_im*cb_tg[c0*2u+1u];\n"
     "        acc1 += x_re*cb_tg[c1*2u] + x_im*cb_tg[c1*2u+1u];\n"
     "        acc2 += x_re*cb_tg[c2*2u] + x_im*cb_tg[c2*2u+1u];\n"
     "        acc3 += x_re*cb_tg[c3*2u] + x_im*cb_tg[c3*2u+1u];\n"
     "      }\n"
     "    }\n"
     "  } else if (bw == 2u && (np & 15u) == 0u && (linear_base0 & 15u) == 0u) {\n"
     "    /* K=4 fast path: 16 pairs per iter via uint32 byte-load (4 rows). */\n"
     "    const uint byte_base0 = linear_base0 >> 2;\n"
     "    const uint byte_base1 = linear_base1 >> 2;\n"
     "    const uint byte_base2 = linear_base2 >> 2;\n"
     "    const uint byte_base3 = linear_base3 >> 2;\n"
     "    for (uint p = 0; p < np; p += 16u) {\n"
     "      const uint w0 = *((const device uint *)(codes + byte_base0 + (p >> 2)));\n"
     "      const uint w1 = *((const device uint *)(codes + byte_base1 + (p >> 2)));\n"
     "      const uint w2 = *((const device uint *)(codes + byte_base2 + (p >> 2)));\n"
     "      const uint w3 = *((const device uint *)(codes + byte_base3 + (p >> 2)));\n"
     "      const uint xb = p * 2u;\n"
     "      for (uint i = 0; i < 16u; i++) {\n"
     "        const uint shift = i * 2u;\n"
     "        const uint c0 = (w0 >> shift) & 3u;\n"
     "        const uint c1 = (w1 >> shift) & 3u;\n"
     "        const uint c2 = (w2 >> shift) & 3u;\n"
     "        const uint c3 = (w3 >> shift) & 3u;\n"
     "        const float x_re = X_tg[xb + 2u*i];\n"
     "        const float x_im = X_tg[xb + 2u*i + 1u];\n"
     "        acc0 += x_re*cb_tg[c0*2u] + x_im*cb_tg[c0*2u+1u];\n"
     "        acc1 += x_re*cb_tg[c1*2u] + x_im*cb_tg[c1*2u+1u];\n"
     "        acc2 += x_re*cb_tg[c2*2u] + x_im*cb_tg[c2*2u+1u];\n"
     "        acc3 += x_re*cb_tg[c3*2u] + x_im*cb_tg[c3*2u+1u];\n"
     "      }\n"
     "    }\n"
     "  } else if (bw == 8u && (np & 3u) == 0u && (linear_base0 & 3u) == 0u) {\n"
     "    /* K=256 fast path: 4 pairs per iter (4 codes = 32 bits per row). */\n"
     "    const uint byte_base0 = linear_base0;\n"
     "    const uint byte_base1 = linear_base1;\n"
     "    const uint byte_base2 = linear_base2;\n"
     "    const uint byte_base3 = linear_base3;\n"
     "    for (uint p = 0; p < np; p += 4u) {\n"
     "      const uint w0 = *((const device uint *)(codes + byte_base0 + p));\n"
     "      const uint w1 = *((const device uint *)(codes + byte_base1 + p));\n"
     "      const uint w2 = *((const device uint *)(codes + byte_base2 + p));\n"
     "      const uint w3 = *((const device uint *)(codes + byte_base3 + p));\n"
     "      const uint xb = p * 2u;\n"
     "      for (uint i = 0; i < 4u; i++) {\n"
     "        const uint shift = i * 8u;\n"
     "        const uint c0 = (w0 >> shift) & 0xFFu;\n"
     "        const uint c1 = (w1 >> shift) & 0xFFu;\n"
     "        const uint c2 = (w2 >> shift) & 0xFFu;\n"
     "        const uint c3 = (w3 >> shift) & 0xFFu;\n"
     "        const float x_re = X_tg[xb + 2u*i];\n"
     "        const float x_im = X_tg[xb + 2u*i + 1u];\n"
     "        acc0 += x_re*cb_tg[c0*2u] + x_im*cb_tg[c0*2u+1u];\n"
     "        acc1 += x_re*cb_tg[c1*2u] + x_im*cb_tg[c1*2u+1u];\n"
     "        acc2 += x_re*cb_tg[c2*2u] + x_im*cb_tg[c2*2u+1u];\n"
     "        acc3 += x_re*cb_tg[c3*2u] + x_im*cb_tg[c3*2u+1u];\n"
     "      }\n"
     "    }\n"
     "  } else {\n"
     "    /* Generic bit-aligned: bw=6 (K=64) and unaligned. 4 row codes per pair. */\n"
     "    for (uint p = 0; p < np; p++) {\n"
     "      const uint bit_off0 = (linear_base0 + p) * bw;\n"
     "      const uint bit_off1 = (linear_base1 + p) * bw;\n"
     "      const uint bit_off2 = (linear_base2 + p) * bw;\n"
     "      const uint bit_off3 = (linear_base3 + p) * bw;\n"
     "      const uint c0 = ((((uint)codes[bit_off0 >> 3] | ((bw + (bit_off0 & 7u) > 8u) ? ((uint)codes[(bit_off0 >> 3) + 1u] << 8) : 0u)) >> (bit_off0 & 7u)) & mask);\n"
     "      const uint c1 = ((((uint)codes[bit_off1 >> 3] | ((bw + (bit_off1 & 7u) > 8u) ? ((uint)codes[(bit_off1 >> 3) + 1u] << 8) : 0u)) >> (bit_off1 & 7u)) & mask);\n"
     "      const uint c2 = ((((uint)codes[bit_off2 >> 3] | ((bw + (bit_off2 & 7u) > 8u) ? ((uint)codes[(bit_off2 >> 3) + 1u] << 8) : 0u)) >> (bit_off2 & 7u)) & mask);\n"
     "      const uint c3 = ((((uint)codes[bit_off3 >> 3] | ((bw + (bit_off3 & 7u) > 8u) ? ((uint)codes[(bit_off3 >> 3) + 1u] << 8) : 0u)) >> (bit_off3 & 7u)) & mask);\n"
     "      const float x_re = X_tg[p*2u];\n"
     "      const float x_im = X_tg[p*2u + 1u];\n"
     "      acc0 += x_re*cb_tg[c0*2u] + x_im*cb_tg[c0*2u+1u];\n"
     "      acc1 += x_re*cb_tg[c1*2u] + x_im*cb_tg[c1*2u+1u];\n"
     "      acc2 += x_re*cb_tg[c2*2u] + x_im*cb_tg[c2*2u+1u];\n"
     "      acc3 += x_re*cb_tg[c3*2u] + x_im*cb_tg[c3*2u+1u];\n"
     "    }\n"
     "  }\n"
     "  device half *out = out_base + gid.z * args->out_stride;\n"
     "  const uint out_row_base = gid.y * args->n_rows + row_base;\n"
     "  out[out_row_base + 0u] = (half)acc0;\n"
     "  out[out_row_base + 1u] = (half)acc1;\n"
     "  out[out_row_base + 2u] = (half)acc2;\n"
     "  out[out_row_base + 3u] = (half)acc3;\n"
     "}\n";

static id<MTLComputePipelineState> g_vqb2_decode_matmul_fp16_x4row_mtl4_pipeline;
static int g_vqb2_decode_matmul_fp16_x4row_mtl4_init_attempted;
static int g_vqb2_decode_matmul_fp16_x4row_mtl4_init_ok;

static int ds4_vqb2_decode_matmul_fp16_x4row_mtl4_pipeline_init(void) {
    if (g_vqb2_decode_matmul_fp16_x4row_mtl4_init_attempted)
        return g_vqb2_decode_matmul_fp16_x4row_mtl4_init_ok;
    g_vqb2_decode_matmul_fp16_x4row_mtl4_init_attempted = 1;
    g_vqb2_decode_matmul_fp16_x4row_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        k_vqb2_decode_matmul_fp16_x4row_msl, @"ds4_vqb2_decode_matmul_fp16_x4row_mtl4",
        @"vqb2_decode_matmul_fp16_x4row", 256, NULL, 0);
    g_vqb2_decode_matmul_fp16_x4row_mtl4_init_ok =
        (g_vqb2_decode_matmul_fp16_x4row_mtl4_pipeline != nil) ? 1 : 0;
    return g_vqb2_decode_matmul_fp16_x4row_mtl4_init_ok;
}

/* Canary + bench: builds synthetic packet (codes, codebook, X activation),
 * runs the fused kernel, cross-checks each output against a scalar CPU
 * reference (decode each code via the same bit-extract logic + accumulate
 * dot product). Then measures throughput vs the prior decode-then-store
 * shape from the noop-write diagnostic.
 *
 * Tolerance: fp16 accumulator drift bound is ~5e-3 relative at n_pairs=1024.
 * Float accumulator (used in kernel) gives tighter precision; cross-check
 * uses float accumulator on CPU too. */
int ds4_gpu_mtl4_vqb2_decode_matmul_fp16_canary(uint32_t n_packets,
                                                 uint32_t n_selected,
                                                 uint32_t n_experts_total,
                                                 uint32_t n_rows,
                                                 uint32_t n_pairs,
                                                 uint32_t k_val,
                                                 uint32_t rounds) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    /* silv 2026-05-28 task #768: env DS4_VQB2_MATMUL_X4ROW=1 picks the
     * 4-rows-per-thread variant. n_rows must be multiple of 4 for the
     * fast paths to engage; otherwise variant falls back to the generic
     * bit-aligned path which still works but loses the vector speedup. */
    const int use_x4row = getenv("DS4_VQB2_MATMUL_X4ROW") &&
                          getenv("DS4_VQB2_MATMUL_X4ROW")[0] == '1';
    if (use_x4row) {
        if (!ds4_vqb2_decode_matmul_fp16_x4row_mtl4_pipeline_init()) return 0;
    } else {
        if (!ds4_vqb2_decode_matmul_fp16_mtl4_pipeline_init()) return 0;
    }
    if (n_packets == 0 || n_selected == 0 || n_selected > n_experts_total) return 0;
    if (n_rows == 0 || n_pairs == 0 || rounds == 0) return 0;
    if (use_x4row && (n_rows & 3u) != 0u) {
        fprintf(stderr, "ds4: x4row variant needs n_rows %% 4 == 0 (got %u)\n", n_rows);
        return 0;
    }
    uint32_t bit_width;
    switch (k_val) {
        case 4:   bit_width = 2; break;
        case 16:  bit_width = 4; break;
        case 64:  bit_width = 6; break;
        case 256: bit_width = 8; break;
        default:  return 0;
    }
    const uint32_t codes_per_expert = n_rows * n_pairs;
    const uint64_t total_codes_per_packet = (uint64_t)n_experts_total * codes_per_expert;
    const size_t codes_bytes_per_packet = (size_t)(total_codes_per_packet * bit_width + 7u) >> 3;
    const size_t out_per_packet_halves = (size_t)n_selected * n_rows;

    int rc = 0;
    int mismatch = 0;
    double max_rel = 0.0;
    double t_ms = 0;

    @autoreleasepool {
        const float step = 1.0f / (float)k_val;
        id<MTLBuffer> cbBuf = [g_device newBufferWithLength:(NSUInteger)k_val * 2u * sizeof(float)
                                                   options:MTLResourceStorageModeShared];
        id<MTLBuffer> codesBuf = [g_device newBufferWithLength:(NSUInteger)n_packets * codes_bytes_per_packet
                                                       options:MTLResourceStorageModeShared];
        id<MTLBuffer> selBuf = [g_device newBufferWithLength:(NSUInteger)n_selected * sizeof(uint32_t)
                                                     options:MTLResourceStorageModeShared];
        id<MTLBuffer> xBuf = [g_device newBufferWithLength:(NSUInteger)n_pairs * 2u * sizeof(_Float16)
                                                   options:MTLResourceStorageModeShared];
        size_t out_buf_bytes = (size_t)n_packets * out_per_packet_halves * sizeof(_Float16);
        if (out_buf_bytes < 16384) out_buf_bytes = 16384;
        id<MTLBuffer> outBuf = [g_device newBufferWithLength:(NSUInteger)out_buf_bytes
                                                    options:MTLResourceStorageModeShared];
        if (!cbBuf || !codesBuf || !selBuf || !xBuf || !outBuf) return 0;

        float *cb_data = (float *)cbBuf.contents;
        for (uint32_t i = 0; i < k_val; i++) {
            cb_data[i * 2u + 0u] =  (float)i * step;
            cb_data[i * 2u + 1u] = -(float)i * step;
        }
        /* Codes: code[expert][i] = (e+i) % k */
        uint8_t *codes_host = (uint8_t *)codesBuf.contents;
        memset(codes_host, 0, (size_t)n_packets * codes_bytes_per_packet);
        for (uint32_t p = 0; p < n_packets; p++) {
            uint8_t *base = codes_host + (size_t)p * codes_bytes_per_packet;
            for (uint32_t e = 0; e < n_experts_total; e++) {
                for (uint32_t i = 0; i < codes_per_expert; i++) {
                    const uint32_t code = (e + i + p) % k_val;
                    const uint64_t linear = (uint64_t)e * codes_per_expert + i;
                    const uint64_t bit_off = linear * bit_width;
                    const size_t byte_off = (size_t)(bit_off >> 3);
                    const uint32_t shift = (uint32_t)(bit_off & 7ull);
                    base[byte_off] |= (uint8_t)((code << shift) & 0xFFu);
                    if (bit_width + shift > 8u) {
                        base[byte_off + 1u] |= (uint8_t)((code >> (8u - shift)) & 0xFFu);
                    }
                }
            }
        }
        uint32_t *sel = (uint32_t *)selBuf.contents;
        for (uint32_t i = 0; i < n_selected; i++) sel[i] = i * (n_experts_total / n_selected);
        /* X: simple sinusoid-ish pattern for non-zero accumulator + per-row variation */
        _Float16 *x_host = (_Float16 *)xBuf.contents;
        for (uint32_t i = 0; i < n_pairs * 2u; i++) {
            x_host[i] = (_Float16)(0.5f + 0.001f * (float)i);
        }

        struct args_t {
            uint32_t bit_width, code_mask, n_rows, n_pairs,
                     n_experts_in_packet, n_selected, codes_stride, out_stride;
        } args = {
            bit_width, (1u << bit_width) - 1u, n_rows, n_pairs,
            n_experts_total, n_selected,
            (uint32_t)codes_bytes_per_packet,
            (uint32_t)out_per_packet_halves,
        };
        id<MTLBuffer> argsBuf = [g_device newBufferWithBytes:&args length:sizeof(args)
                                                     options:MTLResourceStorageModeShared];

        /* Residency set: REQUIRED on Apple MTL4. Without this, the GPU sees zeros
         * for any buffer not auto-resident — kernel reads args->n_rows as 0, hits
         * the early-return guard, and writes nothing. (silv 2026-05-28 catch)  */
        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 8;
        NSError *rs_err = nil;
        id<MTLResidencySet> rs = [g_device newResidencySetWithDescriptor:rsDesc error:&rs_err];
        if (!rs) { fprintf(stderr, "ds4: residency set creation failed: %s\n", rs_err.localizedDescription.UTF8String); return 0; }
        id<MTLAllocation> allocs[6] = { argsBuf, cbBuf, codesBuf, selBuf, xBuf, outBuf };
        [rs addAllocations:allocs count:6];
        [rs commit];
        ds4_residency_request_checked(rs, __func__);
        [g_polar_queue addResidencySet:rs];

        mach_timebase_info_data_t tb; mach_timebase_info(&tb);
        const uint64_t t0 = mach_absolute_time();
        for (uint32_t r = 0; r < rounds; r++) {
            id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
            [cb beginCommandBufferWithAllocator:g_polar_allocator];
            [cb useResidencySet:rs];
            id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
            id<MTL4ArgumentTable> at = ds4_mtl4_pool_acquire(8);
            if (!at) return 0;
            [at setAddress:argsBuf.gpuAddress atIndex:0];
            [at setAddress:cbBuf.gpuAddress atIndex:1];
            [at setAddress:codesBuf.gpuAddress atIndex:2];
            [at setAddress:selBuf.gpuAddress atIndex:3];
            [at setAddress:xBuf.gpuAddress atIndex:4];
            [at setAddress:outBuf.gpuAddress atIndex:5];
            /* silv 2026-05-28 task #768: x4row variant under debug — see kernel
             * source for the bug investigation. Default back to baseline path. */
            [enc setComputePipelineState:
                use_x4row ? g_vqb2_decode_matmul_fp16_x4row_mtl4_pipeline
                          : g_vqb2_decode_matmul_fp16_mtl4_pipeline];
            [enc setArgumentTable:at];
            /* Threadgroup memory: codebook (K*2 floats) + X (np*2 floats). */
            const NSUInteger tg_mem_bytes =
                ((NSUInteger)k_val * 2u + (NSUInteger)n_pairs * 2u) * sizeof(float);
            [enc setThreadgroupMemoryLength:tg_mem_bytes atIndex:0];
            /* tg_size=32 = 1 simdgroup wide. x4row: 4 outputs/thread so grid x = n_rows/4. */
            const NSUInteger eff_rows = use_x4row ? (NSUInteger)n_rows / 4u : (NSUInteger)n_rows;
            const NSUInteger tg_x = (eff_rows + 31u) / 32u;
            [enc dispatchThreadgroups:MTLSizeMake(tg_x, n_selected, n_packets)
                threadsPerThreadgroup:MTLSizeMake(32, 1, 1)];
            [enc endEncoding];
            [cb endCommandBuffer];
            dispatch_semaphore_t sem = dispatch_semaphore_create(0);
            MTL4CommitOptions *opts = [MTL4CommitOptions new];
            [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) { (void)fb; dispatch_semaphore_signal(sem); }];
            id<MTL4CommandBuffer> bufs[1] = {cb};
            [g_polar_queue commit:bufs count:1 options:opts];
            dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 30LL * NSEC_PER_SEC));
            ds4_mtl4_pool_release(at, 8);
        }
        const uint64_t t1 = mach_absolute_time();
        t_ms = (double)(t1 - t0) * (double)tb.numer / (double)tb.denom / 1e6;
        [rs endResidency];
        [g_polar_queue removeResidencySet:rs];

        /* CPU reference: compute the same dot products in float, cross-check. */
        const _Float16 *gpu_out = (const _Float16 *)outBuf.contents;
        if (getenv("DS4_PROBE_ARGS")) {
            fprintf(stderr, "  PROBE: out[0..7] = %.2f %.2f %.2f %.2f %.2f %.2f %.2f %.2f\n",
                    (double)gpu_out[0], (double)gpu_out[1], (double)gpu_out[2], (double)gpu_out[3],
                    (double)gpu_out[4], (double)gpu_out[5], (double)gpu_out[6], (double)gpu_out[7]);
        }
        int dumped = 0;
        for (uint32_t p = 0; p < n_packets; p++) {
            const uint8_t *base = codes_host + (size_t)p * codes_bytes_per_packet;
            for (uint32_t es = 0; es < n_selected; es++) {
                const uint32_t expert = sel[es];
                for (uint32_t r = 0; r < n_rows; r++) {
                    float acc = 0.0f;
                    const uint64_t linear_base =
                        (uint64_t)expert * codes_per_expert + (uint64_t)r * n_pairs;
                    for (uint32_t pp = 0; pp < n_pairs; pp++) {
                        const uint64_t linear = linear_base + pp;
                        const uint64_t bit_off = linear * bit_width;
                        const size_t byte_off = (size_t)(bit_off >> 3);
                        const uint32_t shift = (uint32_t)(bit_off & 7ull);
                        const uint32_t lo = base[byte_off];
                        const uint32_t hi = (bit_width + shift > 8u) ? base[byte_off + 1] : 0u;
                        const uint32_t window = lo | (hi << 8);
                        const uint32_t code = (window >> shift) & ((1u << bit_width) - 1u);
                        const float re = cb_data[code * 2u + 0u];
                        const float im = cb_data[code * 2u + 1u];
                        const float x_re = (float)x_host[pp * 2u + 0u];
                        const float x_im = (float)x_host[pp * 2u + 1u];
                        acc += x_re * re + x_im * im;
                    }
                    const float expected = acc;
                    const float got = (float)gpu_out[p * out_per_packet_halves + es * n_rows + r];
                    const float denom = (fabsf(expected) > 1e-3f) ? fabsf(expected) : 1e-3f;
                    const double rel = fabs((double)(got - expected)) / (double)denom;
                    if (rel > max_rel) max_rel = rel;
                    if (rel > 5e-2) mismatch++;
                    if (getenv("DS4_DUMP_MATMUL") && dumped < 8) {
                        fprintf(stderr, "    [p=%u es=%u expert=%u r=%u] got=%.5f expected=%.5f\n",
                                p, es, expert, r, (double)got, (double)expected);
                        dumped++;
                    }
                }
            }
        }
        rc = 1;
    }

    const uint64_t macs_per_round = (uint64_t)n_packets * n_selected * n_rows * n_pairs;
    const double gflops = ((double)macs_per_round * 2.0 * rounds / 1e9) / (t_ms / 1000.0);
    const double per_layer_us = t_ms * 1000.0 / (double)rounds;

    fprintf(stderr,
        "ds4: vqb2_decode_matmul_fp16 canary n_packets=%u n_sel=%u/%u rows=%u pairs=%u K=%u rounds=%u\n"
        "  fused decode+matmul: %.3f ms total (%.1f us/round)  %.2f GFLOP/s\n"
        "  cross-check mismatch=%d max_rel=%.4e (must be <5%% per cell)  rc=%d\n",
        n_packets, n_selected, n_experts_total, n_rows, n_pairs, k_val, rounds,
        t_ms, per_layer_us, gflops,
        mismatch, max_rel, rc);
    return (rc && mismatch == 0) ? 1 : 0;
}

/* ============================================================================
 * Runtime fused decode-matmul dispatch (silv 2026-05-28).
 * Production-callable primitive that takes pre-bound MTLBuffers and runs the
 * fused kernel for one (layer, kind) batch. Caller manages residency + sync.
 * Header: ds4_gpu.h ds4_gpu_mtl4_vqb2_decode_matmul_fp16_dispatch.
 * ============================================================================
 */
/* Cached residency sets (shared between _dispatch and _dispatch_layer).
 * The old single-slot cache bounced gate→up→down and re-requested residency
 * for every organ/layer. The pack is fixed for a session; keep a small set of
 * stable buffer-tuples resident and mutate one shared args buffer between
 * synchronous dispatches. */
#define DS4_PACK_DISPATCH_RS_SLOTS 64
#define DS4_PACK_DISPATCH_ARGS_BYTES 128u
typedef struct {
    void *pack, *cb, *sel, *x, *out;
    id<MTLResidencySet> rs;
    int valid;
} ds4_pack_dispatch_rs_cache_entry;

static ds4_pack_dispatch_rs_cache_entry g_pack_dispatch_rs_cache[DS4_PACK_DISPATCH_RS_SLOTS];
static uint32_t g_pack_dispatch_rs_clock;
static id<MTLBuffer> g_pack_dispatch_args_buf;

static id<MTLBuffer> pack_dispatch_args_buffer(const void *args, size_t args_len) {
    if (!args || args_len == 0 || args_len > DS4_PACK_DISPATCH_ARGS_BYTES) return nil;
    if (!g_pack_dispatch_args_buf) {
        g_pack_dispatch_args_buf =
            [g_device newBufferWithLength:DS4_PACK_DISPATCH_ARGS_BYTES
                                  options:MTLResourceStorageModeShared];
    }
    if (!g_pack_dispatch_args_buf) return nil;
    memcpy(g_pack_dispatch_args_buf.contents, args, args_len);
    return g_pack_dispatch_args_buf;
}

static void pack_dispatch_rs_cache_clear(ds4_pack_dispatch_rs_cache_entry *e) {
    if (!e || !e->valid) return;
    [g_polar_queue removeResidencySet:e->rs];
    [e->rs endResidency];
    e->rs = nil;
    e->valid = 0;
}

static id<MTLResidencySet> pack_dispatch_get_rs(id<MTLBuffer> argsBuf,
                                                id<MTLBuffer> packBuf,
                                                id<MTLBuffer> cbBuf,
                                                id<MTLBuffer> selBuf,
                                                id<MTLBuffer> xBuf,
                                                id<MTLBuffer> outBuf) {
    void *pack_key = (__bridge void *)packBuf;
    void *cb_key   = (__bridge void *)cbBuf;
    void *sel_key  = (__bridge void *)selBuf;
    void *x_key    = (__bridge void *)xBuf;
    void *out_key  = (__bridge void *)outBuf;
    for (uint32_t i = 0; i < DS4_PACK_DISPATCH_RS_SLOTS; i++) {
        ds4_pack_dispatch_rs_cache_entry *e = &g_pack_dispatch_rs_cache[i];
        if (e->valid &&
            e->pack == pack_key &&
            e->cb   == cb_key &&
            e->sel  == sel_key &&
            e->x    == x_key &&
            e->out  == out_key) {
            return e->rs;
        }
    }
    ds4_pack_dispatch_rs_cache_entry *slot = NULL;
    for (uint32_t i = 0; i < DS4_PACK_DISPATCH_RS_SLOTS; i++) {
        if (!g_pack_dispatch_rs_cache[i].valid) {
            slot = &g_pack_dispatch_rs_cache[i];
            break;
        }
    }
    if (!slot) {
        slot = &g_pack_dispatch_rs_cache[g_pack_dispatch_rs_clock++ % DS4_PACK_DISPATCH_RS_SLOTS];
        pack_dispatch_rs_cache_clear(slot);
    }
    MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
    rsDesc.initialCapacity = 8;
    NSError *rs_err = nil;
    id<MTLResidencySet> rs = [g_device newResidencySetWithDescriptor:rsDesc error:&rs_err];
    if (!rs) return nil;
    id<MTLAllocation> allocs[6];
    NSUInteger n_allocs = 0;
    allocs[n_allocs++] = argsBuf;
    allocs[n_allocs++] = packBuf;
    if (cbBuf != packBuf) allocs[n_allocs++] = cbBuf;
    allocs[n_allocs++] = selBuf;
    allocs[n_allocs++] = xBuf;
    allocs[n_allocs++] = outBuf;
    [rs addAllocations:allocs count:n_allocs];
    [rs commit];
    ds4_residency_request_checked(rs, __func__);
    [g_polar_queue addResidencySet:rs];
    slot->pack = pack_key;
    slot->cb   = cb_key;
    slot->sel  = sel_key;
    slot->x    = x_key;
    slot->out  = out_key;
    slot->rs = rs;
    slot->valid = 1;
    return rs;
}

int ds4_gpu_mtl4_vqb2_decode_matmul_fp16_dispatch(void *codebook_mtlbuf,
                                                  void *codes_mtlbuf,
                                                  void *selected_mtlbuf,
                                                  void *x_mtlbuf,
                                                  void *out_mtlbuf,
                                                  uint32_t n_packets,
                                                  uint32_t n_selected,
                                                  uint32_t n_experts_in_packet,
                                                  uint32_t n_rows,
                                                  uint32_t n_pairs,
                                                  uint32_t k_val,
                                                  uint32_t codes_stride_bytes,
                                                  uint32_t out_stride_halves) {
    if (!g_initialized && !ds4_gpu_init()) return -1;
    const int use_parallel = ds4_vqb2_decode_matmul_parallel_enabled();
    if (use_parallel) {
        if (!ds4_vqb2_decode_matmul_fp16_parallel_mtl4_pipeline_init()) return -1;
    } else {
        if (!ds4_vqb2_decode_matmul_fp16_mtl4_pipeline_init()) return -1;
    }
    if (!codebook_mtlbuf || !codes_mtlbuf || !selected_mtlbuf ||
        !x_mtlbuf || !out_mtlbuf) return -1;
    if (n_packets == 0 || n_selected == 0 || n_selected > n_experts_in_packet) return -1;
    if (n_rows == 0 || n_pairs == 0) return -1;
    uint32_t bit_width;
    switch (k_val) {
        case 4:   bit_width = 2; break;
        case 16:  bit_width = 4; break;
        case 64:  bit_width = 6; break;
        case 256: bit_width = 8; break;
        default:  return -1;
    }
    id<MTLBuffer> cbBuf    = (__bridge id<MTLBuffer>)codebook_mtlbuf;
    id<MTLBuffer> codesBuf = (__bridge id<MTLBuffer>)codes_mtlbuf;
    id<MTLBuffer> selBuf   = (__bridge id<MTLBuffer>)selected_mtlbuf;
    id<MTLBuffer> xBuf     = (__bridge id<MTLBuffer>)x_mtlbuf;
    id<MTLBuffer> outBuf   = (__bridge id<MTLBuffer>)out_mtlbuf;

    struct args_t {
        uint32_t bit_width, code_mask, n_rows, n_pairs,
                 n_experts_in_packet, n_selected, codes_stride, out_stride,
                 x_slot_stride;
    } args = {
        bit_width, (1u << bit_width) - 1u, n_rows, n_pairs,
        n_experts_in_packet, n_selected, codes_stride_bytes, out_stride_halves,
        0u,
    };
    int rc = -2;
    @autoreleasepool {
        id<MTLBuffer> argsBuf = pack_dispatch_args_buffer(&args, sizeof(args));
        if (!argsBuf) return -2;
        id<MTLResidencySet> rs = pack_dispatch_get_rs(argsBuf, codesBuf, cbBuf, selBuf, xBuf, outBuf);
        if (!rs) return -2;

        id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
        [cb beginCommandBufferWithAllocator:g_polar_allocator];
        [cb useResidencySet:rs];
        id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
        id<MTL4ArgumentTable> at = ds4_mtl4_pool_acquire(8);
        if (!at) return -2;
        [at setAddress:argsBuf.gpuAddress  atIndex:0];
        [at setAddress:cbBuf.gpuAddress    atIndex:1];
        [at setAddress:codesBuf.gpuAddress atIndex:2];
        [at setAddress:selBuf.gpuAddress   atIndex:3];
        [at setAddress:xBuf.gpuAddress     atIndex:4];
        [at setAddress:outBuf.gpuAddress   atIndex:5];
        [enc setComputePipelineState:
            use_parallel ? g_vqb2_decode_matmul_fp16_parallel_mtl4_pipeline
                         : g_vqb2_decode_matmul_fp16_mtl4_pipeline];
        [enc setArgumentTable:at];
        const NSUInteger tg_mem_bytes =
            (use_parallel
                ? ((NSUInteger)k_val * 2u + 32u)
                : ((NSUInteger)k_val * 2u + (NSUInteger)n_pairs * 2u)) * sizeof(float);
        [enc setThreadgroupMemoryLength:tg_mem_bytes atIndex:0];
        const NSUInteger grid_x = use_parallel ? (NSUInteger)n_rows
                                                : (NSUInteger)((n_rows + 31u) / 32u);
        [enc dispatchThreadgroups:MTLSizeMake(grid_x, n_selected, n_packets)
            threadsPerThreadgroup:(use_parallel ? MTLSizeMake(256, 1, 1) : MTLSizeMake(32, 1, 1))];
        [enc endEncoding];
        [cb endCommandBuffer];
        dispatch_semaphore_t sem = dispatch_semaphore_create(0);
        MTL4CommitOptions *opts = [MTL4CommitOptions new];
        [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) { (void)fb; dispatch_semaphore_signal(sem); }];
        id<MTL4CommandBuffer> bufs[1] = { cb };
        [g_polar_queue commit:bufs count:1 options:opts];
        dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 30LL * NSEC_PER_SEC));
        ds4_mtl4_pool_release(at, 8);
        /* rs is cache-owned; do NOT tear down here. */
        rc = 0;
    }
    return rc;
}

/* ============================================================================
 * task #759 ICB Phase 8 for fused decode-matmul.
 *
 * The fused kernel exists as an MTL4 pipeline (g_vqb2_decode_matmul_fp16_mtl4_pipeline);
 * classic-MTL ICB requires a separate classic-MTL pipeline compiled from the
 * SAME MSL source. We record the per-layer dispatch sequence into an MTL ICB
 * once at first call; subsequent calls replay via executeCommandsInBuffer.
 *
 * Opt-in via DS4_ICB_VQB2_DECODE_MATMUL=1.
 * ============================================================================
 */
#define DS4_VQB2_DECODE_MATMUL_ICB_SLOTS 320  /* full unified ICB slot budget */
static id<MTLComputePipelineState> g_vqb2_decode_matmul_fp16_classic_pipeline;
static int g_vqb2_decode_matmul_fp16_classic_init_attempted;
static int g_vqb2_decode_matmul_fp16_classic_init_ok;
static id<MTLComputePipelineState> g_vqb2_decode_matmul_fp16_parallel_classic_pipeline;
static int g_vqb2_decode_matmul_fp16_parallel_classic_init_attempted;
static int g_vqb2_decode_matmul_fp16_parallel_classic_init_ok;
static id<MTLBuffer> g_vqb2_decode_matmul_icb_args_buffer; /* shared args, written each replay */
/* Cycle 9f: unified ds4_icb_slot replaces g_vqb2_decode_matmul_fp16_icb +
 * 96-element bespoke slot array. 96 commands at 6 bindings each. */
static ds4_icb_slot_t g_vqb2_decode_matmul_slot;

/* Classic-MTL pipeline init. Same MSL source as the MTL4 path; we just compile
 * via newLibraryWithSource (classic) and set supportIndirectCommandBuffers=YES. */
static int ds4_vqb2_decode_matmul_fp16_classic_pipeline_init(void) {
    if (g_vqb2_decode_matmul_fp16_classic_init_attempted)
        return g_vqb2_decode_matmul_fp16_classic_init_ok;
    g_vqb2_decode_matmul_fp16_classic_init_attempted = 1;
    NSError *err = nil;
    id<MTLLibrary> lib = [g_device newLibraryWithSource:k_vqb2_decode_matmul_fp16_msl
                                                options:nil error:&err];
    if (!lib) {
        fprintf(stderr, "ds4: vqb2_decode_matmul_fp16 classic lib compile failed: %s\n",
                err ? err.localizedDescription.UTF8String : "(no error)");
        return 0;
    }
    id<MTLFunction> fn = [lib newFunctionWithName:@"vqb2_decode_matmul_fp16"];
    if (!fn) { fprintf(stderr, "ds4: vqb2_decode_matmul_fp16 classic function not found\n"); return 0; }
    MTLComputePipelineDescriptor *pdesc = [MTLComputePipelineDescriptor new];
    pdesc.computeFunction = fn;
    pdesc.supportIndirectCommandBuffers = YES;
    g_vqb2_decode_matmul_fp16_classic_pipeline =
        [g_device newComputePipelineStateWithDescriptor:pdesc
                                                options:MTLPipelineOptionNone
                                             reflection:nil
                                                  error:&err];
    if (!g_vqb2_decode_matmul_fp16_classic_pipeline) {
        fprintf(stderr, "ds4: vqb2_decode_matmul_fp16 classic pipeline failed: %s\n",
                err ? err.localizedDescription.UTF8String : "(no error)");
        return 0;
    }
    g_vqb2_decode_matmul_fp16_classic_init_ok = 1;
    fprintf(stderr, "ds4: vqb2_decode_matmul_fp16 classic pipeline initialized (ICB-compatible)\n");
    return 1;
}

static int ds4_vqb2_decode_matmul_fp16_parallel_classic_pipeline_init(void) {
    if (g_vqb2_decode_matmul_fp16_parallel_classic_init_attempted)
        return g_vqb2_decode_matmul_fp16_parallel_classic_init_ok;
    g_vqb2_decode_matmul_fp16_parallel_classic_init_attempted = 1;
    NSError *err = nil;
    id<MTLLibrary> lib = [g_device newLibraryWithSource:k_vqb2_decode_matmul_fp16_parallel_msl
                                                options:nil error:&err];
    if (!lib) {
        fprintf(stderr, "ds4: vqb2_decode_matmul_fp16_parallel classic lib compile failed: %s\n",
                err ? err.localizedDescription.UTF8String : "(no error)");
        return 0;
    }
    id<MTLFunction> fn = [lib newFunctionWithName:@"vqb2_decode_matmul_fp16_parallel"];
    if (!fn) {
        fprintf(stderr, "ds4: vqb2_decode_matmul_fp16_parallel classic function not found\n");
        return 0;
    }
    MTLComputePipelineDescriptor *pdesc = [MTLComputePipelineDescriptor new];
    pdesc.computeFunction = fn;
    pdesc.supportIndirectCommandBuffers = YES;
    g_vqb2_decode_matmul_fp16_parallel_classic_pipeline =
        [g_device newComputePipelineStateWithDescriptor:pdesc
                                                options:MTLPipelineOptionNone
                                             reflection:nil
                                                  error:&err];
    if (!g_vqb2_decode_matmul_fp16_parallel_classic_pipeline) {
        fprintf(stderr, "ds4: vqb2_decode_matmul_fp16_parallel classic pipeline failed: %s\n",
                err ? err.localizedDescription.UTF8String : "(no error)");
        return 0;
    }
    g_vqb2_decode_matmul_fp16_parallel_classic_init_ok = 1;
    fprintf(stderr, "ds4: vqb2_decode_matmul_fp16_parallel classic pipeline initialized (ICB-compatible)\n");
    return 1;
}

/* Dispatch a single fused decode-matmul via classic-MTL ICB.
 * Slot is keyed by all the args; signature mismatch triggers re-record.
 * Replays cost ~5 µs vs ~60 µs for MTL4 dispatch overhead per call. */
static int ds4_gpu_vqb2_decode_matmul_fp16_icb_dispatch(
        id<MTLCommandBuffer> cb,
        uint32_t slot_idx,
        id<MTLBuffer> args_buf, NSUInteger args_off,
        id<MTLBuffer> codebook, NSUInteger codebook_off,
        id<MTLBuffer> codes,    NSUInteger codes_off,
        id<MTLBuffer> selected, NSUInteger sel_off,
        id<MTLBuffer> xbuf,     NSUInteger x_off,
        id<MTLBuffer> outbuf,   NSUInteger out_off,
        uint32_t n_rows, uint32_t n_pairs,
        uint32_t n_selected, uint32_t n_packets, uint32_t k_val) {
    if (slot_idx >= DS4_VQB2_DECODE_MATMUL_ICB_SLOTS) return 0;
    if (!cb || !args_buf || !codebook || !codes || !selected || !xbuf || !outbuf) return 0;
    const int use_parallel = ds4_vqb2_decode_matmul_parallel_enabled();
    if (use_parallel) {
        if (!ds4_vqb2_decode_matmul_fp16_parallel_classic_pipeline_init()) return 0;
    } else {
        if (!ds4_vqb2_decode_matmul_fp16_classic_pipeline_init()) return 0;
    }

    /* Cycle 9f (silv 2026-05-28 task #673/#795) — migrated to unified
     * ds4_icb_slot API. 96 commands at 6 bindings each. Per-slot
     * signature scalars (n_rows, n_pairs, n_selected, k_val, tg_x) go
     * into extras. */
    if (!g_vqb2_decode_matmul_slot.icb) {
        if (!ds4_icb_slot_acquire(&g_vqb2_decode_matmul_slot,
                                  /*max_commands=*/(NSUInteger)DS4_VQB2_DECODE_MATMUL_ICB_SLOTS,
                                  /*max_bindings=*/6)) {
            fprintf(stderr, "ds4: vqb2_decode_matmul_fp16 ICB slot acquire failed\n");
            return 0;
        }
    }

    const uint32_t grid_x = use_parallel ? n_rows : ((n_rows + 31u) / 32u);
    const NSUInteger tg_mem_bytes =
        (use_parallel
            ? ((NSUInteger)k_val * 2u + 32u)
            : ((NSUInteger)k_val * 2u + (NSUInteger)n_pairs * 2u)) * sizeof(float);
    id<MTLComputePipelineState> pso =
        use_parallel ? g_vqb2_decode_matmul_fp16_parallel_classic_pipeline
                     : g_vqb2_decode_matmul_fp16_classic_pipeline;
    const MTLSize grid = MTLSizeMake(grid_x, n_selected, n_packets);
    const MTLSize threads = use_parallel ? MTLSizeMake(256, 1, 1)
                                         : MTLSizeMake(32, 1, 1);
    __unsafe_unretained id<MTLBuffer> bufs[6] = {
        args_buf, codebook, codes, selected, xbuf, outbuf };
    NSUInteger offs[6] = {
        args_off, codebook_off, codes_off, sel_off, x_off, out_off };
    uint64_t extras[6] = { n_rows, n_pairs, n_selected, k_val, grid_x, (uint64_t)use_parallel };
    if (!ds4_icb_slot_record_command(&g_vqb2_decode_matmul_slot, /*cmd_idx=*/slot_idx,
                                     pso,
                                     bufs, offs, 6,
                                     grid,
                                     threads,
                                     (uint32_t)tg_mem_bytes,
                                     extras, 6)) {
        return 0;
    }

    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc useResource:args_buf usage:MTLResourceUsageRead];
    [enc useResource:codebook usage:MTLResourceUsageRead];
    [enc useResource:codes    usage:MTLResourceUsageRead];
    [enc useResource:selected usage:MTLResourceUsageRead];
    [enc useResource:xbuf     usage:MTLResourceUsageRead];
    [enc useResource:outbuf   usage:MTLResourceUsageRead | MTLResourceUsageWrite];
    ds4_icb_slot_execute(&g_vqb2_decode_matmul_slot, enc, slot_idx, 1);
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

/* Batched variant for PATH_FUSED.  One call records/replays a contiguous run
 * of row-block commands into a single ICB range, avoiding the old one-encoder
 * per-row-block replay path.  The caller owns command-buffer commit/wait so the
 * shared args buffer cannot be overwritten before execution completes. */
static int ds4_gpu_vqb2_decode_matmul_fp16_icb_dispatch_batch(
        id<MTLCommandBuffer> cb,
        uint32_t slot_base,
        id<MTLBuffer> args_buf, NSUInteger args_off,
        id<MTLBuffer> codebook, NSUInteger codebook_off,
        id<MTLBuffer> codes, const uint64_t *codes_offsets,
        uint32_t n_dispatches,
        id<MTLBuffer> selected, NSUInteger sel_off,
        id<MTLBuffer> xbuf, NSUInteger x_off,
        id<MTLBuffer> outbuf, uint64_t out_base_off, uint64_t out_stride_bytes,
        uint32_t n_rows, uint32_t n_pairs,
        uint32_t n_selected, uint32_t n_packets, uint32_t k_val) {
    if (n_dispatches == 0) return 1;
    if (n_dispatches > DS4_VQB2_DECODE_MATMUL_ICB_SLOTS) return 0;
    if (!cb || !args_buf || !codebook || !codes || !codes_offsets ||
        !selected || !xbuf || !outbuf) return 0;
    const int use_parallel = ds4_vqb2_decode_matmul_parallel_enabled();
    if (use_parallel) {
        if (!ds4_vqb2_decode_matmul_fp16_parallel_classic_pipeline_init()) return 0;
    } else {
        if (!ds4_vqb2_decode_matmul_fp16_classic_pipeline_init()) return 0;
    }
    if (!g_vqb2_decode_matmul_slot.icb) {
        if (!ds4_icb_slot_acquire(&g_vqb2_decode_matmul_slot,
                                  /*max_commands=*/(NSUInteger)DS4_VQB2_DECODE_MATMUL_ICB_SLOTS,
                                  /*max_bindings=*/6)) {
            fprintf(stderr, "ds4: vqb2_decode_matmul_fp16 batched ICB slot acquire failed\n");
            return 0;
        }
    }

    const uint32_t max_start = DS4_VQB2_DECODE_MATMUL_ICB_SLOTS - n_dispatches;
    const uint32_t slot_start = (max_start > 0) ? (slot_base % (max_start + 1u)) : 0u;
    const uint32_t grid_x = use_parallel ? n_rows : ((n_rows + 31u) / 32u);
    const NSUInteger tg_mem_bytes =
        (use_parallel
            ? ((NSUInteger)k_val * 2u + 32u)
            : ((NSUInteger)k_val * 2u + (NSUInteger)n_pairs * 2u)) * sizeof(float);
    id<MTLComputePipelineState> pso =
        use_parallel ? g_vqb2_decode_matmul_fp16_parallel_classic_pipeline
                     : g_vqb2_decode_matmul_fp16_classic_pipeline;
    const MTLSize grid = MTLSizeMake(grid_x, n_selected, n_packets);
    const MTLSize threads = use_parallel ? MTLSizeMake(256, 1, 1)
                                         : MTLSizeMake(32, 1, 1);
    uint64_t extras[7] = { n_rows, n_pairs, n_selected, n_packets, k_val, grid_x, (uint64_t)use_parallel };

    for (uint32_t d = 0; d < n_dispatches; d++) {
        __unsafe_unretained id<MTLBuffer> bufs[6] = {
            args_buf, codebook, codes, selected, xbuf, outbuf };
        NSUInteger offs[6] = {
            args_off,
            codebook_off,
            (NSUInteger)codes_offsets[d],
            sel_off,
            x_off,
            (NSUInteger)(out_base_off + (uint64_t)d * out_stride_bytes),
        };
        if (!ds4_icb_slot_record_command(&g_vqb2_decode_matmul_slot,
                                         /*cmd_idx=*/slot_start + d,
                                         pso,
                                         bufs, offs, 6,
                                         grid,
                                         threads,
                                         (uint32_t)tg_mem_bytes,
                                         extras, 7)) {
            return 0;
        }
    }

    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc useResource:args_buf usage:MTLResourceUsageRead];
    [enc useResource:codebook usage:MTLResourceUsageRead];
    [enc useResource:codes    usage:MTLResourceUsageRead];
    [enc useResource:selected usage:MTLResourceUsageRead];
    [enc useResource:xbuf     usage:MTLResourceUsageRead];
    [enc useResource:outbuf   usage:MTLResourceUsageRead | MTLResourceUsageWrite];
    const int ok = ds4_icb_slot_execute(&g_vqb2_decode_matmul_slot, enc, slot_start, n_dispatches);
    ds4_gpu_end_compute_encoder(cb, enc);
    return ok;
}

/* ============================================================================
 * task #758 Architecture B: pack-as-MTLBuffer + per-layer batched dispatch.
 * silv 2026-05-28.
 * ============================================================================
 */

void *ds4_gpu_mtl4_vqb2_pack_wrap_mtlbuffer(void *pack_map, size_t pack_size) {
    if (!g_initialized && !ds4_gpu_init()) return NULL;
    if (!pack_map || pack_size == 0) return NULL;
    /* Zero-copy: caller owns the mmap region; we just hand Metal a view.
     * deallocator left NULL — Metal doesn't own the memory. */
    id<MTLBuffer> buf = [g_device newBufferWithBytesNoCopy:pack_map
                                                   length:(NSUInteger)pack_size
                                                  options:MTLResourceStorageModeShared
                                              deallocator:nil];
    if (!buf) return NULL;
    return (__bridge_retained void *)buf;
}

void ds4_gpu_mtl4_vqb2_pack_release_mtlbuffer(void *pack_mtlbuf) {
    if (!pack_mtlbuf) return;
    id<MTLBuffer> buf = (__bridge_transfer id<MTLBuffer>)pack_mtlbuf;
    (void)buf;  /* ARC releases on scope exit */
}

/* silv 2026-05-28 #796 Increment 2 — wrap arbitrary heap bytes as an
 * MTLBuffer (shared storage, zero-copy). Used by the Phase 2b override-
 * fill loop to make heap-allocated tensor data GPU-addressable without
 * a second allocation.
 *
 * Constraint: `bytes` must be page-aligned (vm_page_size — 16 KB on M1)
 * AND `length` must be a multiple of page size. The caller arranges
 * this by using `posix_memalign` + rounding length up. If the input
 * isn't aligned, `newBufferWithBytesNoCopy` returns nil and we return
 * NULL — the dispatch path falls back to mmap.
 *
 * Lifetime: caller owns `bytes`. The MTLBuffer holds a pointer; do
 * NOT free `bytes` until the MTLBuffer is released via
 * ds4_gpu_release_heap_buffer. */
void *ds4_gpu_wrap_heap_bytes(void *bytes, uint64_t length) {
    if (!g_initialized && !ds4_gpu_init()) return NULL;
    if (!bytes || length == 0) return NULL;
    /* Best-effort alignment check (Apple may return nil regardless if
     * page-alignment isn't satisfied — we surface that case as NULL). */
    const uintptr_t page = (uintptr_t)getpagesize();
    if (((uintptr_t)bytes & (page - 1)) != 0) {
        /* Not page-aligned — Metal will reject newBufferWithBytesNoCopy.
         * Caller's allocator wasn't aligned; return NULL silently. The
         * tensor's storage.metal_buffer stays NULL; dispatch falls back. */
        return NULL;
    }
    id<MTLBuffer> buf = [g_device newBufferWithBytesNoCopy:bytes
                                                   length:(NSUInteger)length
                                                  options:MTLResourceStorageModeShared
                                              deallocator:nil];
    if (!buf) return NULL;
    return (__bridge_retained void *)buf;
}

void ds4_gpu_release_heap_buffer(void *opaque) {
    if (!opaque) return;
    id<MTLBuffer> buf = (__bridge_transfer id<MTLBuffer>)opaque;
    (void)buf;  /* ARC releases on scope exit */
}

uint64_t ds4_gpu_heap_buffer_gpu_address(void *opaque) {
    if (!opaque) return 0;
    id<MTLBuffer> buf = (__bridge id<MTLBuffer>)opaque;
    return (uint64_t)buf.gpuAddress;
}

/* Encode N fused dispatches in one command buffer with one shared residency
 * set. Each dispatch reads codes from pack_mtlbuf + codes_offsets[i] and
 * writes to out_mtlbuf + (out_dispatch_base+i)*out_stride_halves halves.
 * `out_dispatch_base` lets callers split a logical layer dispatch into
 * same-codebook runs without overwriting earlier row-block outputs. */
/* silv 2026-05-28 Phase 3 — strided variant. Existing public function below
 * (zero stride) wraps this with x_slot_stride_halves=0 for backwards compat.
 * DOWN dispatch in the PATH_FUSED chain passes the per-expert mid stride. */
static int ds4_gpu_mtl4_vqb2_pack_dispatch_layer_strided_at(void *pack_mtlbuf,
                                                            void *codebook_mtlbuf,
                                                            void *selected_mtlbuf,
                                                            void *x_mtlbuf,
                                                            void *out_mtlbuf,
                                                            const uint64_t *codes_offsets,
                                                            uint32_t n_dispatches,
                                                            uint32_t n_selected,
                                                            uint32_t n_experts_in_packet,
                                                            uint32_t n_rows,
                                                            uint32_t n_pairs,
                                                            uint32_t k_val,
                                                            uint32_t out_stride_halves,
                                                            uint32_t x_slot_stride_halves,
                                                            uint32_t out_dispatch_base,
                                                            uint32_t icb_slot_base) {
    if (!g_initialized && !ds4_gpu_init()) return -1;
    if (!pack_mtlbuf || !codebook_mtlbuf || !selected_mtlbuf ||
        !x_mtlbuf || !out_mtlbuf || !codes_offsets) return -1;
    if (n_dispatches == 0) return 0;
    if (n_selected == 0 || n_selected > n_experts_in_packet) return -1;
    if (n_rows == 0 || n_pairs == 0) return -1;

    uint32_t bit_width;
    switch (k_val) {
        case 4:   bit_width = 2; break;
        case 16:  bit_width = 4; break;
        case 64:  bit_width = 6; break;
        case 256: bit_width = 8; break;
        default:  return -1;
    }

    id<MTLBuffer> packBuf = (__bridge id<MTLBuffer>)pack_mtlbuf;
    id<MTLBuffer> cbBuf   = (__bridge id<MTLBuffer>)codebook_mtlbuf;
    id<MTLBuffer> selBuf  = (__bridge id<MTLBuffer>)selected_mtlbuf;
    id<MTLBuffer> xBuf    = (__bridge id<MTLBuffer>)x_mtlbuf;
    id<MTLBuffer> outBuf  = (__bridge id<MTLBuffer>)out_mtlbuf;

    /* Args is identical for every dispatch in this layer call.
     * out_stride passed as 0 — we set the out_address per-dispatch instead.
     * x_slot_stride (Phase 3): 0=shared X (gate/up), >0=per-slot X (DOWN). */
    struct args_t {
        uint32_t bit_width, code_mask, n_rows, n_pairs,
                 n_experts_in_packet, n_selected, codes_stride, out_stride,
                 x_slot_stride;
    } args = {
        bit_width, (1u << bit_width) - 1u, n_rows, n_pairs,
        n_experts_in_packet, n_selected,
        0u,  /* codes_stride: we set codes_address per-dispatch, n_packets=1 */
        out_stride_halves,
        x_slot_stride_halves,
    };

    static int s_icb_checked = 0;
    static int s_icb_enabled = 0;
    static int s_icb_notice = 0;
    static int s_icb_fallback_notice = 0;
    if (!s_icb_checked) {
        s_icb_enabled = getenv("DS4_ICB_VQB2_DECODE_MATMUL") != NULL;
        s_icb_checked = 1;
    }
    if (s_icb_enabled) {
        @autoreleasepool {
            id<MTLBuffer> argsBuf = pack_dispatch_args_buffer(&args, sizeof(args));
            if (argsBuf) {
                const uint64_t out_stride_bytes = (uint64_t)out_stride_halves * sizeof(_Float16);
                const uint64_t codebook_bytes = (uint64_t)k_val * 2ull * sizeof(float);
                if (!(cbBuf == packBuf && codes_offsets[0] < codebook_bytes)) {
                    const NSUInteger codebook_off = (NSUInteger)
                        ((cbBuf == packBuf) ? (codes_offsets[0] - codebook_bytes) : 0ull);
                    id<MTLCommandBuffer> cb = ds4_gpu_create_cb_counted();
                    if (cb) {
                        if (!s_icb_notice) {
                            fprintf(stderr,
                                "ds4: DS4_ICB_VQB2_DECODE_MATMUL=1 — batched PATH_FUSED ICB replay enabled\n");
                            s_icb_notice = 1;
                        }
                        const int icb_ok = ds4_gpu_vqb2_decode_matmul_fp16_icb_dispatch_batch(
                            cb, icb_slot_base,
                            argsBuf, 0,
                            cbBuf, codebook_off,
                            packBuf, codes_offsets, n_dispatches,
                            selBuf, 0,
                            xBuf, 0,
                            outBuf, (uint64_t)out_dispatch_base * out_stride_bytes, out_stride_bytes,
                            n_rows, n_pairs, n_selected, 1u, k_val);
                        if (icb_ok &&
                            ds4_gpu_finish_command_buffer(cb, 1, "vqb2 decode-matmul ICB batch")) {
                            return 0;
                        }
                    }
                }
            }
        }
        if (!s_icb_fallback_notice) {
            fprintf(stderr,
                "ds4: batched PATH_FUSED ICB replay unavailable; falling back to direct MTL4 dispatch\n");
            s_icb_fallback_notice = 1;
        }
    }

    const int use_parallel_direct = ds4_vqb2_decode_matmul_parallel_enabled();
    if (use_parallel_direct) {
        if (!ds4_vqb2_decode_matmul_fp16_parallel_mtl4_pipeline_init()) return -1;
    } else {
        if (!ds4_vqb2_decode_matmul_fp16_mtl4_pipeline_init()) return -1;
    }
    int rc = -2;
    @autoreleasepool {
        id<MTLBuffer> argsBuf = pack_dispatch_args_buffer(&args, sizeof(args));
        if (!argsBuf) return -2;

        id<MTLResidencySet> rs = pack_dispatch_get_rs(argsBuf, packBuf, cbBuf, selBuf, xBuf, outBuf);
        if (!rs) return -2;

        id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
        [cb beginCommandBufferWithAllocator:g_polar_allocator];
        [cb useResidencySet:rs];
        id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
        id<MTL4ArgumentTable> at = ds4_mtl4_pool_acquire(8);
        if (!at) return -2;

        [enc setComputePipelineState:
            use_parallel_direct ? g_vqb2_decode_matmul_fp16_parallel_mtl4_pipeline
                                : g_vqb2_decode_matmul_fp16_mtl4_pipeline];
        [enc setArgumentTable:at];
        const NSUInteger tg_mem_bytes =
            (use_parallel_direct
                ? ((NSUInteger)k_val * 2u + 32u)
                : ((NSUInteger)k_val * 2u + (NSUInteger)n_pairs * 2u)) * sizeof(float);
        [enc setThreadgroupMemoryLength:tg_mem_bytes atIndex:0];
        const NSUInteger grid_x = use_parallel_direct ? (NSUInteger)n_rows
                                                       : (NSUInteger)((n_rows + 31u) / 32u);
        const MTLSize threads = use_parallel_direct ? MTLSizeMake(256, 1, 1)
                                                    : MTLSizeMake(32, 1, 1);

        /* Stable bindings: args/codebook/selected/X are shared across all
         * dispatches in this layer call. Only codes and out addresses change. */
        const uint64_t pack_base = packBuf.gpuAddress;
        const uint64_t out_base  = outBuf.gpuAddress;
        const uint64_t out_stride_bytes = (uint64_t)out_stride_halves * sizeof(_Float16);
        const uint64_t codebook_bytes = (uint64_t)k_val * 2ull * sizeof(float);
        if (cbBuf == packBuf && codes_offsets[0] < codebook_bytes) return -2;
        const uint64_t codebook_addr = cbBuf.gpuAddress +
            ((cbBuf == packBuf) ? (codes_offsets[0] - codebook_bytes) : 0ull);
        [at setAddress:argsBuf.gpuAddress atIndex:0];
        [at setAddress:codebook_addr      atIndex:1];
        [at setAddress:selBuf.gpuAddress  atIndex:3];
        [at setAddress:xBuf.gpuAddress    atIndex:4];

        for (uint32_t d = 0; d < n_dispatches; d++) {
            [at setAddress:(pack_base + codes_offsets[d]) atIndex:2];
            [at setAddress:(out_base + (uint64_t)(out_dispatch_base + d) * out_stride_bytes) atIndex:5];
            [enc dispatchThreadgroups:MTLSizeMake(grid_x, n_selected, 1)
                threadsPerThreadgroup:threads];
        }
        [enc endEncoding];
        [cb endCommandBuffer];

        dispatch_semaphore_t sem = dispatch_semaphore_create(0);
        MTL4CommitOptions *opts = [MTL4CommitOptions new];
        [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) { (void)fb; dispatch_semaphore_signal(sem); }];
        id<MTL4CommandBuffer> bufs[1] = { cb };
        [g_polar_queue commit:bufs count:1 options:opts];
        dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 30LL * NSEC_PER_SEC));
        ds4_mtl4_pool_release(at, 8);
        /* rs is cache-owned; do NOT tear down here. */
        rc = 0;
    }
    return rc;
}

int ds4_gpu_mtl4_vqb2_pack_dispatch_layer_strided(void *pack_mtlbuf,
                                                  void *codebook_mtlbuf,
                                                  void *selected_mtlbuf,
                                                  void *x_mtlbuf,
                                                  void *out_mtlbuf,
                                                  const uint64_t *codes_offsets,
                                                  uint32_t n_dispatches,
                                                  uint32_t n_selected,
                                                  uint32_t n_experts_in_packet,
                                                  uint32_t n_rows,
                                                  uint32_t n_pairs,
                                                  uint32_t k_val,
                                                  uint32_t out_stride_halves,
                                                  uint32_t x_slot_stride_halves) {
    return ds4_gpu_mtl4_vqb2_pack_dispatch_layer_strided_at(
        pack_mtlbuf, codebook_mtlbuf, selected_mtlbuf, x_mtlbuf, out_mtlbuf,
        codes_offsets, n_dispatches, n_selected, n_experts_in_packet,
        n_rows, n_pairs, k_val, out_stride_halves, x_slot_stride_halves,
        0u, 0u);
}

/* Back-compat wrapper: original signature, shared-X (gate/up) semantic.
 * All existing callers continue to work; DOWN dispatch uses _strided form. */
int ds4_gpu_mtl4_vqb2_pack_dispatch_layer(void *pack_mtlbuf,
                                          void *codebook_mtlbuf,
                                          void *selected_mtlbuf,
                                          void *x_mtlbuf,
                                          void *out_mtlbuf,
                                          const uint64_t *codes_offsets,
                                          uint32_t n_dispatches,
                                          uint32_t n_selected,
                                          uint32_t n_experts_in_packet,
                                          uint32_t n_rows,
                                          uint32_t n_pairs,
                                          uint32_t k_val,
                                          uint32_t out_stride_halves) {
    return ds4_gpu_mtl4_vqb2_pack_dispatch_layer_strided(
        pack_mtlbuf, codebook_mtlbuf, selected_mtlbuf, x_mtlbuf, out_mtlbuf,
        codes_offsets, n_dispatches, n_selected, n_experts_in_packet,
        n_rows, n_pairs, k_val, out_stride_halves,
        0u  /* x_slot_stride: shared X */);
}

/* ============================================================================
 * Bind-pack: production wiring point (silv 2026-05-28 task #759).
 * Opens a real VQB2 pack, wraps it as MTLBuffer (zero-copy on unified memory),
 * builds per-entry codebook MTLBuffers + a (layer, kind, row_block) → entry
 * lookup, and stores everything in a session-scoped binding.
 *
 * After bind, `ds4_metal_vqb2_fused_dispatch_kind(layer, kind, sel[6], X, out)`
 * performs the fused decode-matmul for one (layer, kind) using all entries
 * of that kind, indexed by row_block.
 * ============================================================================
 */
#include "ds4_vqb2_pack.h"

#define DS4_FUSED_BIND_MAX_LAYERS 64
#define DS4_FUSED_BIND_MAX_KINDS  3
#define DS4_FUSED_BIND_MAX_RB     32

static struct {
    ds4_vqb2_pack pack;
    int           pack_open;
    void         *pack_mtlbuf;    /* opaque retained id<MTLBuffer> */
    uint64_t      codebook_hash[DS4_FUSED_BIND_MAX_LAYERS][DS4_FUSED_BIND_MAX_KINDS][DS4_FUSED_BIND_MAX_RB];
    uint64_t      codes_offset[DS4_FUSED_BIND_MAX_LAYERS][DS4_FUSED_BIND_MAX_KINDS][DS4_FUSED_BIND_MAX_RB];
    int32_t       entry_idx[DS4_FUSED_BIND_MAX_LAYERS][DS4_FUSED_BIND_MAX_KINDS][DS4_FUSED_BIND_MAX_RB];
    uint64_t      rowblock_mask[DS4_FUSED_BIND_MAX_LAYERS][DS4_FUSED_BIND_MAX_KINDS];
    /* silv 2026-05-28 task #761 item A — bit-packed per-(kind) layer presence
     * masks. Computed ONCE at bind time. Per-layer coverage lookup becomes O(1):
     *   gate_present = (cov_bits_gate >> L) & 1
     *   bitmask      = gate_present | (up_present<<1) | (down_present<<2)
     *
     * Storage drops from 43 bytes (layer-coverage byte cache in vqb2_fp16.m)
     * to 3 × uint64 = 24 bytes, AND first-touch probing of MAX_RB×MAX_KINDS
     * (96 ops/layer × 43 layers = 4128 ops worst case) collapses to a single
     * shift+AND. Caller in ds4_metal_vqb2_fp16.m drops its own static cache. */
    uint64_t      cov_bits_kind[DS4_FUSED_BIND_MAX_KINDS];
    uint64_t      cov_bits_full;  /* bit L set iff all three kinds present at layer L */
} g_fused_bind;

static uint64_t ds4_fused_fnv1a64(const void *data, size_t n) {
    const uint8_t *p = (const uint8_t *)data;
    uint64_t h = 1469598103934665603ull;
    for (size_t i = 0; i < n; i++) {
        h ^= (uint64_t)p[i];
        h *= 1099511628211ull;
    }
    return h ? h : 1ull;
}

int ds4_metal_vqb2_fused_bind(const char *pack_path, const char *index_csv_path) {
    if (!g_initialized && !ds4_gpu_init()) return -1;
    if (g_fused_bind.pack_open) {
        fprintf(stderr, "ds4_metal_vqb2_fused_bind: already bound; close existing first\n");
        return -1;
    }
    if (!ds4_vqb2_pack_open(pack_path, index_csv_path, &g_fused_bind.pack)) {
        fprintf(stderr, "ds4_metal_vqb2_fused_bind: pack_open failed (%s, %s)\n",
                pack_path, index_csv_path);
        return -1;
    }
    g_fused_bind.pack_open = 1;

    /* Wrap pack mmap as MTLBuffer (zero-copy on Apple Silicon shared mem). */
    g_fused_bind.pack_mtlbuf = ds4_gpu_mtl4_vqb2_pack_wrap_mtlbuffer(
        g_fused_bind.pack.map, g_fused_bind.pack.map_size);
    if (!g_fused_bind.pack_mtlbuf) {
        fprintf(stderr, "ds4_metal_vqb2_fused_bind: pack wrap failed\n");
        ds4_vqb2_pack_close(&g_fused_bind.pack);
        g_fused_bind.pack_open = 0;
        return -1;
    }

    /* DS4_FUSED_PRETOUCH=1 → touch every page to pin in OS page cache.
     * DS4_FUSED_MLOCK=1     → mlock() to also wire down (requires unlimited
     *                          memlock; will fail on small ulimits). */
    if (getenv("DS4_FUSED_PRETOUCH")) {
        const uint8_t *p = (const uint8_t *)g_fused_bind.pack.map;
        const size_t page = (size_t)getpagesize();
        uint64_t accum = 0;
        const uint64_t t0 = mach_absolute_time();
        for (size_t i = 0; i < g_fused_bind.pack.map_size; i += page) {
            accum += p[i];  /* force fault-in */
        }
        const uint64_t t1 = mach_absolute_time();
        mach_timebase_info_data_t tb; mach_timebase_info(&tb);
        const double ms = (double)(t1 - t0) * (double)tb.numer / (double)tb.denom / 1e6;
        fprintf(stderr, "ds4_metal_vqb2_fused_bind: pre-touch %zu pages took %.2f s (accum=%llu)\n",
                g_fused_bind.pack.map_size / page, ms / 1000.0, (unsigned long long)accum);
    }
    if (getenv("DS4_FUSED_MLOCK")) {
        const uint64_t t0 = mach_absolute_time();
        if (mlock(g_fused_bind.pack.map, g_fused_bind.pack.map_size) != 0) {
            fprintf(stderr, "ds4_metal_vqb2_fused_bind: mlock failed (%s) — try `ulimit -l unlimited`\n",
                    strerror(errno));
        } else {
            const uint64_t t1 = mach_absolute_time();
            mach_timebase_info_data_t tb; mach_timebase_info(&tb);
            const double ms = (double)(t1 - t0) * (double)tb.numer / (double)tb.denom / 1e6;
            fprintf(stderr, "ds4_metal_vqb2_fused_bind: mlock %.2f GiB took %.2f s\n",
                    g_fused_bind.pack.map_size / 1e9, ms / 1000.0);
        }
    }

    /* Initialize entry index table to -1 (absent). */
    memset(g_fused_bind.entry_idx, 0xff, sizeof(g_fused_bind.entry_idx));
    memset(g_fused_bind.codes_offset, 0, sizeof(g_fused_bind.codes_offset));
    memset(g_fused_bind.codebook_hash, 0, sizeof(g_fused_bind.codebook_hash));
    memset(g_fused_bind.rowblock_mask, 0, sizeof(g_fused_bind.rowblock_mask));
    memset(g_fused_bind.cov_bits_kind, 0, sizeof(g_fused_bind.cov_bits_kind));
    g_fused_bind.cov_bits_full = 0;

    /* Walk pack entries: cache codebook hash + code offset per (layer, kind, row_block).
     * Codebooks stay in the pack MTLBuffer; dispatch binds pack+codebook_offset
     * directly instead of minting thousands of tiny MTLBuffers. */
    int n_indexed = 0;
    @autoreleasepool {
        for (uint32_t i = 0; i < g_fused_bind.pack.n_entries; i++) {
            const ds4_vqb2_pack_entry *e = &g_fused_bind.pack.entries[i];
            if (e->layer >= DS4_FUSED_BIND_MAX_LAYERS) continue;
            if (e->kind_id >= DS4_FUSED_BIND_MAX_KINDS) continue;
            if ((e->row_start & 127u) != 0) continue;
            const uint32_t rb = e->row_start >> 7;
            if (rb >= DS4_FUSED_BIND_MAX_RB) continue;

            /* Codebook for this entry sits at pack_offset + DS4_VQB2_HEADER_BYTES. */
            const uint8_t *cb_src =
                (const uint8_t *)g_fused_bind.pack.map + e->pack_offset + DS4_VQB2_HEADER_BYTES;
            const size_t cb_bytes = (size_t)e->k * 2u * sizeof(float);
            g_fused_bind.codebook_hash[e->layer][e->kind_id][rb] =
                ds4_fused_fnv1a64(cb_src, cb_bytes);

            /* codes_offset in pack = pack_offset + header + codebook bytes */
            g_fused_bind.codes_offset[e->layer][e->kind_id][rb] =
                e->pack_offset + DS4_VQB2_HEADER_BYTES + cb_bytes;
            g_fused_bind.entry_idx[e->layer][e->kind_id][rb] = (int32_t)i;
            g_fused_bind.rowblock_mask[e->layer][e->kind_id] |= (1ull << rb);
            /* Bit-packed coverage: layer e->layer has kind_id present. */
            if (e->layer < 64u && e->kind_id < DS4_FUSED_BIND_MAX_KINDS) {
                g_fused_bind.cov_bits_kind[e->kind_id] |= (1ull << e->layer);
            }
            n_indexed++;
        }
    }

    /* Pre-compute true full-row-block coverage.  A layer is safe for the
     * PATH_FUSED full FFN only when gate/up have all 16 row blocks and down
     * has all 32.  The older kind-presence intersection was too weak: a pack
     * with one packet for each organ looked "full" and could route partial
     * decoded tensors into the live FFN chain. */
    const uint64_t gate_up_full_mask = (1ull << 16u) - 1ull;
    const uint64_t down_full_mask = 0xffffffffull;
    for (uint32_t L = 0; L < DS4_FUSED_BIND_MAX_LAYERS && L < 64u; L++) {
        const uint64_t gate_mask = g_fused_bind.rowblock_mask[L][0];
        const uint64_t up_mask   = g_fused_bind.rowblock_mask[L][1];
        const uint64_t down_mask = g_fused_bind.rowblock_mask[L][2];
        if ((gate_mask & gate_up_full_mask) == gate_up_full_mask &&
            (up_mask   & gate_up_full_mask) == gate_up_full_mask &&
            (down_mask & down_full_mask)    == down_full_mask) {
            g_fused_bind.cov_bits_full |= (1ull << L);
        }
    }

    fprintf(stderr,
        "ds4_metal_vqb2_fused_bind: pack=%s\n"
        "  size=%.2f GiB  entries=%u  indexed=%d\n"
        "  coverage: gate=0x%llx up=0x%llx down=0x%llx full=0x%llx\n"
        "  pack MTLBuffer wrapped + in-pack codebook addressing enabled\n",
        pack_path, g_fused_bind.pack.pack_size / 1e9,
        g_fused_bind.pack.n_entries, n_indexed,
        (unsigned long long)g_fused_bind.cov_bits_kind[0],
        (unsigned long long)g_fused_bind.cov_bits_kind[1],
        (unsigned long long)g_fused_bind.cov_bits_kind[2],
        (unsigned long long)g_fused_bind.cov_bits_full);
    return 0;
}

void ds4_metal_vqb2_fused_unbind(void) {
    if (!g_fused_bind.pack_open) return;
    if (g_fused_bind.pack_mtlbuf) {
        ds4_gpu_mtl4_vqb2_pack_release_mtlbuffer(g_fused_bind.pack_mtlbuf);
        g_fused_bind.pack_mtlbuf = NULL;
    }
    ds4_vqb2_pack_close(&g_fused_bind.pack);
    g_fused_bind.pack_open = 0;
}

/* silv 2026-05-28 task #761 — per-layer coverage probe.
 *
 * Returns bitmask of bound kinds for `layer`:
 *   bit 0 = GATE  (kind_id 0)
 *   bit 1 = UP    (kind_id 1)
 *   bit 2 = DOWN  (kind_id 2)
 *   0 = layer not bound at all; 7 = all three kinds present.
 *
 * Foundation for PATH_FUSED's full-FFN chain: caller checks coverage before
 * attempting fused dispatch; falls back to MTL4 when bitmask != 7.
 *
 * Item A (bit-packed cache): O(1) — read 3 bits from the per-kind layer masks
 * pre-computed once at bind time. Was O(MAX_RB × MAX_KINDS) = 96 ops/layer.
 * Safe to call before bind (returns 0 because pack_open guard).
 */
uint32_t ds4_metal_vqb2_fused_layer_coverage(uint32_t layer) {
    if (!g_fused_bind.pack_open) return 0;
    if (layer >= 64u) return 0;
    const uint64_t bit = 1ull << layer;
    uint32_t mask = 0;
    if (g_fused_bind.cov_bits_kind[0] & bit) mask |= 1u;
    if (g_fused_bind.cov_bits_kind[1] & bit) mask |= 2u;
    if (g_fused_bind.cov_bits_kind[2] & bit) mask |= 4u;
    return mask;
}

/* Bit-packed full-coverage shortcut. Returns nonzero iff all three kinds
 * (gate, up, down) are present at `layer`. Cheaper than calling
 * ds4_metal_vqb2_fused_layer_coverage(layer) == 7 because it's a single
 * shift+AND instead of three. */
int ds4_metal_vqb2_fused_layer_fully_covered(uint32_t layer) {
    if (!g_fused_bind.pack_open || layer >= 64u) return 0;
    return (int)((g_fused_bind.cov_bits_full >> layer) & 1ull);
}

/* silv 2026-05-28 task #761 — shape adapter: fp32 activation → fp16 X buffer.
 *
 * Kernel `vqb2_decode_matmul_fp16` reads X as device half[n_pairs * 2] (line
 * 34939 of ds4_metal.m). Production code holds the activation as fp32 of
 * length expert_in_dim. For DS4 V4:
 *   gate/up: in_dim = 4096 → n_pairs = 2048
 *   down   : in_dim = 2048 → n_pairs = 1024
 *
 * Mapping is LINEAR — element i of the fp32 vector becomes element i of the
 * fp16 buffer. NO transpose, NO repack: the kernel just consumes
 * `expert_in_dim` halves in order. The "pair" structure is internal to the
 * kernel's accumulator (each pair contributes two MAC ops with codebook[c*2+0]
 * and codebook[c*2+1]) but the input layout is flat.
 *
 * Persistent staging buffer + shared MTLBuffer wrap: caller reuses across
 * calls; the buffer grows on demand and shrinks never. Returns an opaque
 * id<MTLBuffer> pointer suitable for passing to
 * `ds4_metal_vqb2_fused_dispatch_kind` as `x_mtlbuf`.
 *
 * Args:
 *   in_fp32  — pointer to fp32 activation vector
 *   n_elems  — element count (e.g. 4096 for gate/up, 2048 for down)
 * Returns the MTLBuffer pointer; NULL on failure.
 *
 * Cost on M1 (unified mem): one cacheline-walk through `n_elems` floats with a
 * static_cast to _Float16. For 4096 elems ≈ 1 µs. CPU-side is faster than
 * kernel-side for this size because launch overhead alone is >5 µs. */
void *ds4_metal_vqb2_fused_x_adapter_fp32_to_fp16(const float *in_fp32, uint32_t n_elems) {
    if (!g_initialized && !ds4_gpu_init()) return NULL;
    if (!in_fp32 || n_elems == 0) return NULL;

    static id<MTLBuffer> s_x_fp16_buf = nil;
    static uint32_t      s_x_fp16_cap = 0;
    const uint32_t need_bytes = n_elems * (uint32_t)sizeof(_Float16);
    if (s_x_fp16_cap < need_bytes) {
        s_x_fp16_buf = [g_device newBufferWithLength:(NSUInteger)need_bytes
                                            options:MTLResourceStorageModeShared];
        if (!s_x_fp16_buf) return NULL;
        s_x_fp16_cap = need_bytes;
    }
    _Float16 *dst = (_Float16 *)s_x_fp16_buf.contents;
    for (uint32_t i = 0; i < n_elems; i++) dst[i] = (_Float16)in_fp32[i];
    return (__bridge void *)s_x_fp16_buf;
}

/* Companion: persistent fp16 output buffer pool for dispatch_kind outputs.
 *
 * One slot per (layer, kind) — gate/up/down dispatches write here, downstream
 * consumers (SwiGLU+route_weight fuse, moe_sum6, fp16→fp32 reducer) read.
 * Buffer size = n_rb × n_selected × n_rows × sizeof(_Float16). For DS4 V4
 * gate/up: 1 × 6 × 2048 × 2 = 24 KB per (layer, kind); for down: 1 × 6 ×
 * 4096 × 2 = 48 KB. Grows on demand; lives for the session lifetime.
 *
 * `slot_id` is caller-managed (use a deterministic enum: GATE_OUT=0, UP_OUT=1,
 * MID_FP16=2, DOWN_OUT=3). Returns NULL on failure. */
#define DS4_FUSED_OUT_SLOTS 4
void *ds4_metal_vqb2_fused_out_buffer(uint32_t slot_id, uint32_t need_bytes) {
    if (!g_initialized && !ds4_gpu_init()) return NULL;
    if (slot_id >= DS4_FUSED_OUT_SLOTS || need_bytes == 0) return NULL;
    static id<MTLBuffer> s_out_buf[DS4_FUSED_OUT_SLOTS] = { nil };
    static uint32_t      s_out_cap[DS4_FUSED_OUT_SLOTS] = { 0 };
    if (s_out_cap[slot_id] < need_bytes) {
        s_out_buf[slot_id] = [g_device newBufferWithLength:(NSUInteger)need_bytes
                                                  options:MTLResourceStorageModeShared];
        if (!s_out_buf[slot_id]) return NULL;
        s_out_cap[slot_id] = need_bytes;
    }
    return (__bridge void *)s_out_buf[slot_id];
}

/* Dispatch the fused decode-matmul for one (layer, kind) using the bound pack.
 * Output layout: out[row_block * n_selected * n_rows + sel_slot * n_rows + row].
 *
 * Returns 0 on success, -1 if bind missing or (layer, kind) absent. */
int ds4_metal_vqb2_fused_dispatch_kind(uint32_t layer, uint32_t kind_id,
                                        const uint32_t *selected, uint32_t n_selected,
                                        void *x_mtlbuf, void *out_mtlbuf,
                                        uint32_t *out_n_dispatches,
                                        uint32_t *out_n_rows,
                                        uint32_t *out_n_pairs) {
    if (!g_fused_bind.pack_open) {
        fprintf(stderr, "ds4_metal_vqb2_fused_dispatch_kind: bind missing\n");
        return -1;
    }
    if (layer >= DS4_FUSED_BIND_MAX_LAYERS || kind_id >= DS4_FUSED_BIND_MAX_KINDS) return -1;

    /* Gather contiguous row_blocks for this (layer, kind). */
    uint64_t offsets[DS4_FUSED_BIND_MAX_RB];
    uint64_t cb_hashes[DS4_FUSED_BIND_MAX_RB];
    uint32_t n_rb = 0;
    uint32_t n_rows = 0, n_pairs = 0, n_experts_in_packet = 0, k_val = 0;
    for (uint32_t rb = 0; rb < DS4_FUSED_BIND_MAX_RB; rb++) {
        const int32_t idx = g_fused_bind.entry_idx[layer][kind_id][rb];
        if (idx < 0) continue;
        const ds4_vqb2_pack_entry *e = &g_fused_bind.pack.entries[idx];
        if (n_rb == 0) {
            n_rows = e->n_rows;
            n_pairs = e->n_pairs;
            n_experts_in_packet = e->n_experts;
            k_val = e->k;
        } else if (e->n_rows != n_rows || e->n_pairs != n_pairs ||
                   e->k != k_val || e->n_experts != n_experts_in_packet) {
            fprintf(stderr,
                "ds4_metal_vqb2_fused_dispatch_kind: heterogeneous row_blocks at L%u kind=%u rb=%u — bail\n",
                layer, kind_id, rb);
            return -1;
        }
        cb_hashes[n_rb] = g_fused_bind.codebook_hash[layer][kind_id][rb];
        offsets[n_rb++] = g_fused_bind.codes_offset[layer][kind_id][rb];
    }
    if (n_rb == 0) return -1;

    /* Persistent selected buffer (reused across calls — content updated via memcpy).
     * Stable identity ⇒ residency-set cache hits → 30ms × N_dispatches saved per call. */
    static id<MTLBuffer> s_persistent_sel_buf = nil;
    static uint32_t      s_persistent_sel_cap = 0;
    const uint32_t need = n_selected;
    if (s_persistent_sel_cap < need) {
        s_persistent_sel_buf = [g_device newBufferWithLength:(NSUInteger)need * sizeof(uint32_t)
                                                    options:MTLResourceStorageModeShared];
        if (!s_persistent_sel_buf) return -1;
        s_persistent_sel_cap = need;
    }
    memcpy(s_persistent_sel_buf.contents, selected, n_selected * sizeof(uint32_t));
    id<MTLBuffer> selBuf = s_persistent_sel_buf;

    const uint32_t out_stride_halves = n_selected * n_rows;
    int rc = 0;
    for (uint32_t run_start = 0; run_start < n_rb; ) {
        uint32_t run_end = run_start + 1u;
        while (run_end < n_rb && cb_hashes[run_end] == cb_hashes[run_start]) run_end++;
        const uint32_t icb_slot_base =
            ((layer * DS4_FUSED_BIND_MAX_KINDS + kind_id) * DS4_FUSED_BIND_MAX_RB + run_start);
        rc = ds4_gpu_mtl4_vqb2_pack_dispatch_layer_strided_at(
            g_fused_bind.pack_mtlbuf,
            g_fused_bind.pack_mtlbuf,
            (__bridge void *)selBuf,
            x_mtlbuf, out_mtlbuf,
            offsets + run_start, run_end - run_start, n_selected, n_experts_in_packet,
            n_rows, n_pairs, k_val, out_stride_halves, 0u, run_start, icb_slot_base);
        if (rc != 0) return rc;
        run_start = run_end;
    }

    if (out_n_dispatches) *out_n_dispatches = n_rb;
    if (out_n_rows) *out_n_rows = n_rows;
    if (out_n_pairs) *out_n_pairs = n_pairs;
    return rc;
}

/* Phase 3 strided variant: same as ds4_metal_vqb2_fused_dispatch_kind but
 * accepts per-slot X stride (in halves). DOWN dispatches with stride>0 so
 * each selected expert reads its own SwiGLU mid buffer. GATE/UP can keep
 * using the non-strided wrapper above (shared X = ffn_norm output). */
int ds4_metal_vqb2_fused_dispatch_kind_strided(uint32_t layer, uint32_t kind_id,
                                                const uint32_t *selected, uint32_t n_selected,
                                                void *x_mtlbuf, void *out_mtlbuf,
                                                uint32_t x_slot_stride_halves,
                                                uint32_t *out_n_dispatches,
                                                uint32_t *out_n_rows,
                                                uint32_t *out_n_pairs) {
    if (!g_fused_bind.pack_open) {
        fprintf(stderr, "ds4_metal_vqb2_fused_dispatch_kind_strided: bind missing\n");
        return -1;
    }
    if (layer >= DS4_FUSED_BIND_MAX_LAYERS || kind_id >= DS4_FUSED_BIND_MAX_KINDS) return -1;

    uint64_t offsets[DS4_FUSED_BIND_MAX_RB];
    uint64_t cb_hashes[DS4_FUSED_BIND_MAX_RB];
    uint32_t n_rb = 0;
    uint32_t n_rows = 0, n_pairs = 0, n_experts_in_packet = 0, k_val = 0;
    for (uint32_t rb = 0; rb < DS4_FUSED_BIND_MAX_RB; rb++) {
        const int32_t idx = g_fused_bind.entry_idx[layer][kind_id][rb];
        if (idx < 0) continue;
        const ds4_vqb2_pack_entry *e = &g_fused_bind.pack.entries[idx];
        if (n_rb == 0) {
            n_rows = e->n_rows;
            n_pairs = e->n_pairs;
            n_experts_in_packet = e->n_experts;
            k_val = e->k;
        } else if (e->n_rows != n_rows || e->n_pairs != n_pairs ||
                   e->k != k_val || e->n_experts != n_experts_in_packet) {
            fprintf(stderr,
                "ds4_metal_vqb2_fused_dispatch_kind_strided: heterogeneous row_blocks at L%u kind=%u rb=%u — bail\n",
                layer, kind_id, rb);
            return -1;
        }
        cb_hashes[n_rb] = g_fused_bind.codebook_hash[layer][kind_id][rb];
        offsets[n_rb++] = g_fused_bind.codes_offset[layer][kind_id][rb];
    }
    if (n_rb == 0) return -1;

    /* Reuse the same persistent selected buffer that the non-strided variant
     * uses — they never run concurrently within one PATH_FUSED iteration. */
    static id<MTLBuffer> s_persistent_sel_buf_strided = nil;
    static uint32_t      s_persistent_sel_cap_strided = 0;
    const uint32_t need = n_selected;
    if (s_persistent_sel_cap_strided < need) {
        s_persistent_sel_buf_strided = [g_device newBufferWithLength:(NSUInteger)need * sizeof(uint32_t)
                                                             options:MTLResourceStorageModeShared];
        if (!s_persistent_sel_buf_strided) return -1;
        s_persistent_sel_cap_strided = need;
    }
    memcpy(s_persistent_sel_buf_strided.contents, selected, n_selected * sizeof(uint32_t));
    id<MTLBuffer> selBuf = s_persistent_sel_buf_strided;

    const uint32_t out_stride_halves = n_selected * n_rows;
    int rc = 0;
    for (uint32_t run_start = 0; run_start < n_rb; ) {
        uint32_t run_end = run_start + 1u;
        while (run_end < n_rb && cb_hashes[run_end] == cb_hashes[run_start]) run_end++;
        const uint32_t icb_slot_base =
            ((layer * DS4_FUSED_BIND_MAX_KINDS + kind_id) * DS4_FUSED_BIND_MAX_RB + run_start);
        rc = ds4_gpu_mtl4_vqb2_pack_dispatch_layer_strided_at(
            g_fused_bind.pack_mtlbuf,
            g_fused_bind.pack_mtlbuf,
            (__bridge void *)selBuf,
            x_mtlbuf, out_mtlbuf,
            offsets + run_start, run_end - run_start, n_selected, n_experts_in_packet,
            n_rows, n_pairs, k_val, out_stride_halves, x_slot_stride_halves, run_start, icb_slot_base);
        if (rc != 0) return rc;
        run_start = run_end;
    }

    if (out_n_dispatches) *out_n_dispatches = n_rb;
    if (out_n_rows) *out_n_rows = n_rows;
    if (out_n_pairs) *out_n_pairs = n_pairs;
    return rc;
}

/* Microbench: bind pack, time N warm dispatch_kind calls, project per-token t/s.
 * Reports per-(layer, kind) latency and a 43-layer × 3-kind extrapolation. */
int ds4_metal_vqb2_fused_microbench(const char *pack_path, const char *index_csv_path,
                                     uint32_t layer, uint32_t kind_id, uint32_t rounds) {
    if (ds4_metal_vqb2_fused_bind(pack_path, index_csv_path) != 0) return 0;
    uint32_t n_rows = 0, n_pairs = 0, k_val = 0;
    for (uint32_t rb = 0; rb < DS4_FUSED_BIND_MAX_RB; rb++) {
        const int32_t idx = g_fused_bind.entry_idx[layer][kind_id][rb];
        if (idx < 0) continue;
        const ds4_vqb2_pack_entry *e = &g_fused_bind.pack.entries[idx];
        n_rows = e->n_rows; n_pairs = e->n_pairs; k_val = e->k;
        break;
    }
    if (n_rows == 0) {
        fprintf(stderr, "ds4_metal_vqb2_fused_microbench: no entries for L%u kind=%u\n", layer, kind_id);
        ds4_metal_vqb2_fused_unbind();
        return 0;
    }

    const uint32_t n_selected = 6;
    uint32_t sel[6] = { 0, 50, 100, 150, 200, 250 };
    double t_warm_ms = 0.0;

    @autoreleasepool {
        id<MTLBuffer> xBuf = [g_device newBufferWithLength:(NSUInteger)n_pairs * 2u * sizeof(_Float16)
                                                   options:MTLResourceStorageModeShared];
        _Float16 *x_host = (_Float16 *)xBuf.contents;
        for (uint32_t i = 0; i < n_pairs * 2u; i++) x_host[i] = (_Float16)(0.5f + 0.001f * (float)i);
        const size_t out_halves = (size_t)DS4_FUSED_BIND_MAX_RB * n_selected * n_rows;
        id<MTLBuffer> outBuf = [g_device newBufferWithLength:out_halves * sizeof(_Float16)
                                                    options:MTLResourceStorageModeShared];

        /* Warmup: 1 call to page-in + cache warm */
        ds4_metal_vqb2_fused_dispatch_kind(layer, kind_id, sel, n_selected,
                                            (__bridge void *)xBuf, (__bridge void *)outBuf,
                                            NULL, NULL, NULL);

        /* Timed */
        mach_timebase_info_data_t tb; mach_timebase_info(&tb);
        const uint64_t t0 = mach_absolute_time();
        for (uint32_t r = 0; r < rounds; r++) {
            ds4_metal_vqb2_fused_dispatch_kind(layer, kind_id, sel, n_selected,
                                                (__bridge void *)xBuf, (__bridge void *)outBuf,
                                                NULL, NULL, NULL);
        }
        const uint64_t t1 = mach_absolute_time();
        t_warm_ms = (double)(t1 - t0) * (double)tb.numer / (double)tb.denom / 1e6;
    }

    const double per_kind_ms = t_warm_ms / (double)rounds;
    /* Per-token projection: 43 layers × 3 kinds (gate, up, down) */
    const double per_token_ms = per_kind_ms * 43.0 * 3.0;
    const double proj_tps = 1000.0 / per_token_ms;

    fprintf(stderr,
        "ds4_metal_vqb2_fused_microbench: L%u kind=%u  n_rows=%u n_pairs=%u K=%u\n"
        "  %u warm rounds: %.3f ms total  →  %.3f ms per (layer, kind)\n"
        "  projection: 43 layers × 3 kinds × %.3f ms = %.1f ms/token = %.2f t/s ceiling\n",
        layer, kind_id, n_rows, n_pairs, k_val, rounds,
        t_warm_ms, per_kind_ms, per_kind_ms, per_token_ms, proj_tps);

    ds4_metal_vqb2_fused_unbind();
    return 1;
}

/* Smoke test: bind a pack and dispatch one (layer, kind) call. */
int ds4_metal_vqb2_fused_bind_smoke(const char *pack_path, const char *index_csv_path,
                                    uint32_t layer, uint32_t kind_id) {
    if (ds4_metal_vqb2_fused_bind(pack_path, index_csv_path) != 0) return 0;

    /* Build a placeholder X and out buffer matching the bound entry's shape.
     * Read shape from the first entry of the requested (layer, kind). */
    uint32_t n_rows = 0, n_pairs = 0, k_val = 0;
    for (uint32_t rb = 0; rb < DS4_FUSED_BIND_MAX_RB; rb++) {
        const int32_t idx = g_fused_bind.entry_idx[layer][kind_id][rb];
        if (idx < 0) continue;
        const ds4_vqb2_pack_entry *e = &g_fused_bind.pack.entries[idx];
        n_rows = e->n_rows; n_pairs = e->n_pairs; k_val = e->k;
        break;
    }
    if (n_rows == 0) {
        fprintf(stderr, "ds4_metal_vqb2_fused_bind_smoke: no entries for L%u kind=%u\n", layer, kind_id);
        ds4_metal_vqb2_fused_unbind();
        return 0;
    }

    const uint32_t n_selected = 6;
    uint32_t sel[6] = { 0, 50, 100, 150, 200, 250 };

    int rc;
    @autoreleasepool {
        id<MTLBuffer> xBuf = [g_device newBufferWithLength:(NSUInteger)n_pairs * 2u * sizeof(_Float16)
                                                   options:MTLResourceStorageModeShared];
        _Float16 *x_host = (_Float16 *)xBuf.contents;
        for (uint32_t i = 0; i < n_pairs * 2u; i++) x_host[i] = (_Float16)(0.5f + 0.001f * (float)i);

        /* Out: DS4_FUSED_BIND_MAX_RB * n_selected * n_rows halves max */
        const size_t out_halves = (size_t)DS4_FUSED_BIND_MAX_RB * n_selected * n_rows;
        id<MTLBuffer> outBuf = [g_device newBufferWithLength:out_halves * sizeof(_Float16)
                                                    options:MTLResourceStorageModeShared];
        memset(outBuf.contents, 0, out_halves * sizeof(_Float16));

        uint32_t n_rb = 0;
        const uint64_t t0 = mach_absolute_time();
        rc = ds4_metal_vqb2_fused_dispatch_kind(layer, kind_id, sel, n_selected,
                                                 (__bridge void *)xBuf,
                                                 (__bridge void *)outBuf,
                                                 &n_rb, NULL, NULL);
        const uint64_t t1 = mach_absolute_time();
        mach_timebase_info_data_t tb; mach_timebase_info(&tb);
        const double ms = (double)(t1 - t0) * (double)tb.numer / (double)tb.denom / 1e6;

        /* Print some output values + first nonzero locations */
        const _Float16 *out_h = (const _Float16 *)outBuf.contents;
        int nonzero = 0;
        for (size_t i = 0; i < out_halves; i++) if (out_h[i] != (_Float16)0.0) nonzero++;
        fprintf(stderr,
            "ds4_metal_vqb2_fused_bind_smoke: L%u kind=%u  n_rb=%u  n_rows=%u n_pairs=%u K=%u\n"
            "  dispatch: %.3f ms (%d halves total, %d nonzero)\n"
            "  out[0..7] = %.3f %.3f %.3f %.3f %.3f %.3f %.3f %.3f\n"
            "  rc=%d\n",
            layer, kind_id, n_rb, n_rows, n_pairs, k_val,
            ms, (int)out_halves, nonzero,
            (double)out_h[0], (double)out_h[1], (double)out_h[2], (double)out_h[3],
            (double)out_h[4], (double)out_h[5], (double)out_h[6], (double)out_h[7],
            rc);
    }
    ds4_metal_vqb2_fused_unbind();
    return rc == 0 ? 1 : 0;
}

/* Synthetic canary: validates the pack-driven layer dispatch primitive.
 * Allocates n_entries codes blobs back-to-back in a single buffer (simulating
 * mmap'd pack), wraps as MTLBuffer, dispatches, cross-checks. */
int ds4_gpu_mtl4_vqb2_pack_fused_canary(uint32_t n_entries,
                                        uint32_t n_selected,
                                        uint32_t n_experts_in_packet,
                                        uint32_t n_rows,
                                        uint32_t n_pairs,
                                        uint32_t k_val,
                                        uint32_t rounds) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (n_entries == 0 || rounds == 0) return 0;
    if (n_selected == 0 || n_selected > n_experts_in_packet) return 0;
    if (n_rows == 0 || n_pairs == 0) return 0;
    uint32_t bit_width;
    switch (k_val) {
        case 4:   bit_width = 2; break;
        case 16:  bit_width = 4; break;
        case 64:  bit_width = 6; break;
        case 256: bit_width = 8; break;
        default:  return 0;
    }

    const uint32_t codes_per_expert = n_rows * n_pairs;
    const uint64_t codes_per_entry = (uint64_t)n_experts_in_packet * codes_per_expert;
    const size_t entry_bytes = (size_t)((codes_per_entry * bit_width + 7u) >> 3);
    /* Pack layout: n_entries codes blobs back-to-back. */
    const size_t pack_size = entry_bytes * n_entries;
    const size_t out_per_dispatch_halves = (size_t)n_selected * n_rows;

    /* Use mmap to get page-aligned region — newBufferWithBytesNoCopy requires
     * vm_page_size alignment on Apple Silicon shared mode. calloc doesn't
     * guarantee this; mmap with anonymous + private does. */
    const size_t page_size = (size_t)getpagesize();
    const size_t pack_size_aligned = ((pack_size + page_size - 1) / page_size) * page_size;
    uint8_t *pack_map = (uint8_t *)mmap(NULL, pack_size_aligned,
                                         PROT_READ | PROT_WRITE,
                                         MAP_PRIVATE | MAP_ANON, -1, 0);
    if (pack_map == MAP_FAILED) {
        fprintf(stderr, "ds4: pack_fused canary mmap %.2f MB failed\n", pack_size_aligned / 1e6);
        return 0;
    }
    memset(pack_map, 0, pack_size);

    /* Synthesize codes per entry — distinct seed per entry. */
    for (uint32_t e_idx = 0; e_idx < n_entries; e_idx++) {
        uint8_t *base = pack_map + (size_t)e_idx * entry_bytes;
        for (uint32_t e = 0; e < n_experts_in_packet; e++) {
            for (uint32_t i = 0; i < codes_per_expert; i++) {
                const uint32_t code = (e + i + e_idx) % k_val;
                const uint64_t linear = (uint64_t)e * codes_per_expert + i;
                const uint64_t bit_off = linear * bit_width;
                const size_t byte_off = (size_t)(bit_off >> 3);
                const uint32_t shift = (uint32_t)(bit_off & 7ull);
                base[byte_off] |= (uint8_t)((code << shift) & 0xFFu);
                if (bit_width + shift > 8u) {
                    base[byte_off + 1u] |= (uint8_t)((code >> (8u - shift)) & 0xFFu);
                }
            }
        }
    }

    int rc = 0;
    int mismatch = 0;
    double max_rel = 0.0;
    double t_ms = 0;

    @autoreleasepool {
        /* Wrap pack as MTLBuffer. */
        void *pack_buf = ds4_gpu_mtl4_vqb2_pack_wrap_mtlbuffer(pack_map, pack_size);
        if (!pack_buf) { free(pack_map); return 0; }

        /* Build other GPU buffers. */
        id<MTLBuffer> cbBuf = [g_device newBufferWithLength:(NSUInteger)k_val * 2u * sizeof(float)
                                                   options:MTLResourceStorageModeShared];
        id<MTLBuffer> selBuf = [g_device newBufferWithLength:(NSUInteger)n_selected * sizeof(uint32_t)
                                                     options:MTLResourceStorageModeShared];
        id<MTLBuffer> xBuf = [g_device newBufferWithLength:(NSUInteger)n_pairs * 2u * sizeof(_Float16)
                                                   options:MTLResourceStorageModeShared];
        id<MTLBuffer> outBuf = [g_device newBufferWithLength:
                                  (NSUInteger)n_entries * out_per_dispatch_halves * sizeof(_Float16)
                                                    options:MTLResourceStorageModeShared];
        if (!cbBuf || !selBuf || !xBuf || !outBuf) {
            ds4_gpu_mtl4_vqb2_pack_release_mtlbuffer(pack_buf);
            free(pack_map);
            return 0;
        }
        float *cb_data = (float *)cbBuf.contents;
        const float step = 1.0f / (float)k_val;
        for (uint32_t i = 0; i < k_val; i++) {
            cb_data[i * 2u + 0u] =  (float)i * step;
            cb_data[i * 2u + 1u] = -(float)i * step;
        }
        uint32_t *sel = (uint32_t *)selBuf.contents;
        for (uint32_t i = 0; i < n_selected; i++)
            sel[i] = i * (n_experts_in_packet / n_selected);
        _Float16 *x_host = (_Float16 *)xBuf.contents;
        for (uint32_t i = 0; i < n_pairs * 2u; i++)
            x_host[i] = (_Float16)(0.5f + 0.001f * (float)i);

        /* Codes offsets: contiguous by default.  Set
         * DS4_VQB2_PACK_NONUNIFORM_OFFSETS=1 to reverse the row-block order
         * and force the production _strided_at dispatcher instead of the
         * uniform n_packets fast path; this is the canary for PATH_FUSED ICB. */
        uint64_t *offsets = (uint64_t *)malloc((size_t)n_entries * sizeof(uint64_t));
        if (!offsets) {
            ds4_gpu_mtl4_vqb2_pack_release_mtlbuffer(pack_buf);
            free(pack_map);
            return 0;
        }
        const int nonuniform_offsets = getenv("DS4_VQB2_PACK_NONUNIFORM_OFFSETS") != NULL;
        for (uint32_t i = 0; i < n_entries; i++) {
            const uint32_t src = nonuniform_offsets ? (n_entries - 1u - i) : i;
            offsets[i] = (uint64_t)src * (uint64_t)entry_bytes;
        }

        /* Detect uniform-stride: if all offsets are i * entry_bytes, we can
         * collapse 64 dispatches into 1 kernel call via n_packets grid.z.
         * The H2125 promise is that real packs have layer-major locality,
         * so this fast path should be the production case. */
        int uniform_stride = 1;
        for (uint32_t i = 0; i < n_entries; i++) {
            if (offsets[i] != (uint64_t)i * (uint64_t)entry_bytes) {
                uniform_stride = 0; break;
            }
        }
        /* Untimed warm dispatch: first use compiles/records pipelines and ICB
         * commands.  The reported timing should measure steady replay, not
         * startup, especially for the forced-nonuniform PATH_FUSED ICB canary. */
        int warm_rc;
        if (uniform_stride) {
            warm_rc = ds4_gpu_mtl4_vqb2_decode_matmul_fp16_dispatch(
                (__bridge void *)cbBuf, pack_buf, (__bridge void *)selBuf,
                (__bridge void *)xBuf, (__bridge void *)outBuf,
                n_entries, n_selected, n_experts_in_packet,
                n_rows, n_pairs, k_val,
                (uint32_t)entry_bytes, (uint32_t)out_per_dispatch_halves);
        } else {
            warm_rc = ds4_gpu_mtl4_vqb2_pack_dispatch_layer(
                pack_buf, (__bridge void *)cbBuf, (__bridge void *)selBuf,
                (__bridge void *)xBuf, (__bridge void *)outBuf,
                offsets, n_entries, n_selected, n_experts_in_packet,
                n_rows, n_pairs, k_val, (uint32_t)out_per_dispatch_halves);
        }
        if (warm_rc != 0) { free(offsets); rc = 0; goto canary_done; }

        mach_timebase_info_data_t tb; mach_timebase_info(&tb);
        const uint64_t t0 = mach_absolute_time();
        for (uint32_t r = 0; r < rounds; r++) {
            int d_rc;
            if (uniform_stride) {
                /* All-in-one batched dispatch: pack_buf IS the codes buffer,
                 * codes_stride is uniform entry_bytes, kernel handles all
                 * entries via gid.z dimension. */
                d_rc = ds4_gpu_mtl4_vqb2_decode_matmul_fp16_dispatch(
                    (__bridge void *)cbBuf, pack_buf, (__bridge void *)selBuf,
                    (__bridge void *)xBuf, (__bridge void *)outBuf,
                    n_entries, n_selected, n_experts_in_packet,
                    n_rows, n_pairs, k_val,
                    (uint32_t)entry_bytes, (uint32_t)out_per_dispatch_halves);
            } else {
                d_rc = ds4_gpu_mtl4_vqb2_pack_dispatch_layer(
                    pack_buf, (__bridge void *)cbBuf, (__bridge void *)selBuf,
                    (__bridge void *)xBuf, (__bridge void *)outBuf,
                    offsets, n_entries, n_selected, n_experts_in_packet,
                    n_rows, n_pairs, k_val, (uint32_t)out_per_dispatch_halves);
            }
            if (d_rc != 0) { free(offsets); rc = 0; goto canary_done; }
        }
        const uint64_t t1 = mach_absolute_time();
        t_ms = (double)(t1 - t0) * (double)tb.numer / (double)tb.denom / 1e6;
        fprintf(stderr, "  uniform_stride path: %s%s\n",
                uniform_stride ? "YES" : "NO",
                nonuniform_offsets ? " (forced nonuniform offset canary)" : "");

        /* CPU reference. */
        const _Float16 *gpu_out = (const _Float16 *)outBuf.contents;
        for (uint32_t e_idx = 0; e_idx < n_entries; e_idx++) {
            const uint8_t *base = pack_map + (size_t)offsets[e_idx];
            for (uint32_t es = 0; es < n_selected; es++) {
                const uint32_t expert = sel[es];
                for (uint32_t r = 0; r < n_rows; r++) {
                    float acc = 0.0f;
                    const uint64_t linear_base =
                        (uint64_t)expert * codes_per_expert + (uint64_t)r * n_pairs;
                    for (uint32_t pp = 0; pp < n_pairs; pp++) {
                        const uint64_t linear = linear_base + pp;
                        const uint64_t bit_off = linear * bit_width;
                        const size_t byte_off = (size_t)(bit_off >> 3);
                        const uint32_t shift = (uint32_t)(bit_off & 7ull);
                        const uint32_t lo = base[byte_off];
                        const uint32_t hi = (bit_width + shift > 8u) ? base[byte_off + 1] : 0u;
                        const uint32_t window = lo | (hi << 8);
                        const uint32_t code = (window >> shift) & ((1u << bit_width) - 1u);
                        const float re = cb_data[code * 2u + 0u];
                        const float im = cb_data[code * 2u + 1u];
                        const float x_re = (float)x_host[pp * 2u + 0u];
                        const float x_im = (float)x_host[pp * 2u + 1u];
                        acc += x_re * re + x_im * im;
                    }
                    const float expected = acc;
                    const float got = (float)gpu_out[e_idx * out_per_dispatch_halves
                                                     + es * n_rows + r];
                    const float denom = (fabsf(expected) > 1e-3f) ? fabsf(expected) : 1e-3f;
                    const double rel = fabs((double)(got - expected)) / (double)denom;
                    if (rel > max_rel) max_rel = rel;
                    if (rel > 5e-2) mismatch++;
                }
            }
        }
        rc = 1;
        free(offsets);

canary_done:
        ds4_gpu_mtl4_vqb2_pack_release_mtlbuffer(pack_buf);
    }
    munmap(pack_map, pack_size_aligned);

    const uint64_t macs_per_round = (uint64_t)n_entries * n_selected * n_rows * n_pairs;
    const double gflops = ((double)macs_per_round * 2.0 * rounds / 1e9) / (t_ms / 1000.0);
    const double per_dispatch_us = t_ms * 1000.0 / (double)(rounds * n_entries);

    fprintf(stderr,
        "ds4: pack_fused canary entries=%u sel=%u/%u rows=%u pairs=%u K=%u rounds=%u\n"
        "  pack-batched fused: %.3f ms total (%.1f us/dispatch)  %.2f GFLOP/s\n"
        "  cross-check mismatch=%d max_rel=%.4e  rc=%d\n",
        n_entries, n_selected, n_experts_in_packet, n_rows, n_pairs, k_val, rounds,
        t_ms, per_dispatch_us, gflops, mismatch, max_rel, rc);
    return (rc && mismatch == 0) ? 1 : 0;
}

/* ICB head-to-head bench: cached-MTL4 vs classic-ICB.
 * Same shape as pack_fused canary. Runs both paths back to back; reports
 * GFLOP/s for each; cross-checks bit-exactness of ICB vs CPU reference. */
int ds4_gpu_mtl4_vqb2_pack_icb_bench(uint32_t n_entries,
                                     uint32_t n_selected,
                                     uint32_t n_experts_in_packet,
                                     uint32_t n_rows,
                                     uint32_t n_pairs,
                                     uint32_t k_val,
                                     uint32_t rounds) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_vqb2_decode_matmul_fp16_classic_pipeline_init()) return 0;
    if (n_entries == 0 || rounds == 0) return 0;
    if (n_selected == 0 || n_selected > n_experts_in_packet) return 0;
    uint32_t bit_width;
    switch (k_val) {
        case 4:   bit_width = 2; break;
        case 16:  bit_width = 4; break;
        case 64:  bit_width = 6; break;
        case 256: bit_width = 8; break;
        default:  return 0;
    }

    const uint32_t codes_per_expert = n_rows * n_pairs;
    const uint64_t codes_per_entry = (uint64_t)n_experts_in_packet * codes_per_expert;
    const size_t entry_bytes = (size_t)((codes_per_entry * bit_width + 7u) >> 3);
    const size_t pack_size = entry_bytes * n_entries;
    const size_t out_per_dispatch_halves = (size_t)n_selected * n_rows;

    /* mmap page-aligned pack region. */
    const size_t page_size = (size_t)getpagesize();
    const size_t pack_size_aligned = ((pack_size + page_size - 1) / page_size) * page_size;
    uint8_t *pack_map = (uint8_t *)mmap(NULL, pack_size_aligned,
                                         PROT_READ | PROT_WRITE,
                                         MAP_PRIVATE | MAP_ANON, -1, 0);
    if (pack_map == MAP_FAILED) return 0;
    memset(pack_map, 0, pack_size);
    /* Synthesize codes (same pattern as pack_fused canary). */
    for (uint32_t e_idx = 0; e_idx < n_entries; e_idx++) {
        uint8_t *base = pack_map + (size_t)e_idx * entry_bytes;
        for (uint32_t e = 0; e < n_experts_in_packet; e++) {
            for (uint32_t i = 0; i < codes_per_expert; i++) {
                const uint32_t code = (e + i + e_idx) % k_val;
                const uint64_t linear = (uint64_t)e * codes_per_expert + i;
                const uint64_t bit_off = linear * bit_width;
                const size_t byte_off = (size_t)(bit_off >> 3);
                const uint32_t shift = (uint32_t)(bit_off & 7ull);
                base[byte_off] |= (uint8_t)((code << shift) & 0xFFu);
                if (bit_width + shift > 8u)
                    base[byte_off + 1u] |= (uint8_t)((code >> (8u - shift)) & 0xFFu);
            }
        }
    }

    double t_mtl4_ms = 0.0, t_icb_ms = 0.0;
    int mtl4_mismatch = 0, icb_mismatch = 0;

    @autoreleasepool {
        void *pack_buf = ds4_gpu_mtl4_vqb2_pack_wrap_mtlbuffer(pack_map, pack_size_aligned);
        if (!pack_buf) { munmap(pack_map, pack_size_aligned); return 0; }
        id<MTLBuffer> packBufObj = (__bridge id<MTLBuffer>)pack_buf;

        id<MTLBuffer> cbBuf = [g_device newBufferWithLength:(NSUInteger)k_val * 2u * sizeof(float)
                                                   options:MTLResourceStorageModeShared];
        id<MTLBuffer> selBuf = [g_device newBufferWithLength:(NSUInteger)n_selected * sizeof(uint32_t)
                                                     options:MTLResourceStorageModeShared];
        id<MTLBuffer> xBuf = [g_device newBufferWithLength:(NSUInteger)n_pairs * 2u * sizeof(_Float16)
                                                   options:MTLResourceStorageModeShared];
        id<MTLBuffer> outMtl4 = [g_device newBufferWithLength:
                                  (NSUInteger)n_entries * out_per_dispatch_halves * sizeof(_Float16)
                                                    options:MTLResourceStorageModeShared];
        id<MTLBuffer> outIcb = [g_device newBufferWithLength:
                                  (NSUInteger)n_entries * out_per_dispatch_halves * sizeof(_Float16)
                                                    options:MTLResourceStorageModeShared];

        float *cb_data = (float *)cbBuf.contents;
        const float step = 1.0f / (float)k_val;
        for (uint32_t i = 0; i < k_val; i++) {
            cb_data[i * 2u + 0u] =  (float)i * step;
            cb_data[i * 2u + 1u] = -(float)i * step;
        }
        uint32_t *sel = (uint32_t *)selBuf.contents;
        for (uint32_t i = 0; i < n_selected; i++) sel[i] = i * (n_experts_in_packet / n_selected);
        _Float16 *x_host = (_Float16 *)xBuf.contents;
        for (uint32_t i = 0; i < n_pairs * 2u; i++) x_host[i] = (_Float16)(0.5f + 0.001f * (float)i);

        /* args buffer for ICB path (classic ICB requires explicit args buf bind). */
        struct args_t {
            uint32_t bit_width, code_mask, n_rows, n_pairs,
                     n_experts_in_packet, n_selected, codes_stride, out_stride;
        } args = {
            bit_width, (1u << bit_width) - 1u, n_rows, n_pairs,
            n_experts_in_packet, n_selected,
            (uint32_t)entry_bytes, (uint32_t)out_per_dispatch_halves,
        };
        id<MTLBuffer> argsBuf = [g_device newBufferWithBytes:&args length:sizeof(args)
                                                     options:MTLResourceStorageModeShared];

        mach_timebase_info_data_t tb; mach_timebase_info(&tb);

        /* ============ PATH A: cached MTL4 (uniform-stride all-in-one) ============ */
        const uint64_t t0a = mach_absolute_time();
        for (uint32_t r = 0; r < rounds; r++) {
            int d_rc = ds4_gpu_mtl4_vqb2_decode_matmul_fp16_dispatch(
                (__bridge void *)cbBuf, pack_buf, (__bridge void *)selBuf,
                (__bridge void *)xBuf, (__bridge void *)outMtl4,
                n_entries, n_selected, n_experts_in_packet,
                n_rows, n_pairs, k_val,
                (uint32_t)entry_bytes, (uint32_t)out_per_dispatch_halves);
            if (d_rc != 0) {
                ds4_gpu_mtl4_vqb2_pack_release_mtlbuffer(pack_buf);
                munmap(pack_map, pack_size_aligned);
                return 0;
            }
        }
        const uint64_t t1a = mach_absolute_time();
        t_mtl4_ms = (double)(t1a - t0a) * (double)tb.numer / (double)tb.denom / 1e6;

        /* ============ PATH B: classic-MTL ICB (one slot, n_packets-batched) ============ */
        /* First call records the slot, subsequent replays reuse. */
        const uint64_t t0b = mach_absolute_time();
        for (uint32_t r = 0; r < rounds; r++) {
            id<MTLCommandBuffer> cb = [g_queue commandBuffer];
            ds4_gpu_vqb2_decode_matmul_fp16_icb_dispatch(
                cb, /*slot_idx=*/0,
                argsBuf, /*args_off=*/0,
                cbBuf,   /*codebook_off=*/0,
                packBufObj, /*codes_off=*/0,
                selBuf,  /*sel_off=*/0,
                xBuf,    /*x_off=*/0,
                outIcb,  /*out_off=*/0,
                n_rows, n_pairs, n_selected, n_entries, k_val);
            [cb commit];
            [cb waitUntilCompleted];
        }
        const uint64_t t1b = mach_absolute_time();
        t_icb_ms = (double)(t1b - t0b) * (double)tb.numer / (double)tb.denom / 1e6;

        /* Bit-exact cross-check: ICB out == MTL4 out (both reference the same kernel). */
        const _Float16 *mtl4_out = (const _Float16 *)outMtl4.contents;
        const _Float16 *icb_out  = (const _Float16 *)outIcb.contents;
        const size_t total_halves = (size_t)n_entries * out_per_dispatch_halves;
        for (size_t i = 0; i < total_halves; i++) {
            const float a = (float)mtl4_out[i];
            const float b = (float)icb_out[i];
            if (fabsf(a - b) > 1e-3f * (fabsf(a) > 1.0f ? fabsf(a) : 1.0f)) icb_mismatch++;
        }
        (void)mtl4_mismatch;

        ds4_gpu_mtl4_vqb2_pack_release_mtlbuffer(pack_buf);
    }
    munmap(pack_map, pack_size_aligned);

    const uint64_t macs_per_round = (uint64_t)n_entries * n_selected * n_rows * n_pairs;
    const double mtl4_gflops = ((double)macs_per_round * 2.0 * rounds / 1e9) / (t_mtl4_ms / 1000.0);
    const double icb_gflops  = ((double)macs_per_round * 2.0 * rounds / 1e9) / (t_icb_ms / 1000.0);
    const double speedup = t_mtl4_ms / t_icb_ms;

    fprintf(stderr,
        "ds4: pack_icb_bench entries=%u sel=%u/%u rows=%u pairs=%u K=%u rounds=%u\n"
        "  PATH A (cached MTL4): %.3f ms total (%.1f us/round)  %.2f GFLOP/s\n"
        "  PATH B (classic ICB): %.3f ms total (%.1f us/round)  %.2f GFLOP/s\n"
        "  speedup: %.2fx (ICB vs MTL4)\n"
        "  ICB vs MTL4 output mismatch: %d / %zu halves\n",
        n_entries, n_selected, n_experts_in_packet, n_rows, n_pairs, k_val, rounds,
        t_mtl4_ms, t_mtl4_ms * 1000.0 / rounds, mtl4_gflops,
        t_icb_ms,  t_icb_ms  * 1000.0 / rounds, icb_gflops,
        speedup,
        icb_mismatch, (size_t)n_entries * out_per_dispatch_halves);
    return icb_mismatch == 0 ? 1 : 0;
}

/* Vectorized decoder bench: K=4 / K=16 / K=256 specialized kernels;
 * cross-checks vectorized output against the scalar baseline. */
int ds4_gpu_mtl4_vqb2_decode_vectorized_bench(uint32_t n_packets,
                                               uint32_t n_selected,
                                               uint32_t n_experts_total,
                                               uint32_t n_rows,
                                               uint32_t n_pairs,
                                               uint32_t k_val,
                                               uint32_t rounds) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_vqb2_decode_fp16_batched_mtl4_pipeline_init()) return 0;
    id<MTLComputePipelineState> vec_pipeline = nil;
    uint32_t codes_per_thread = 0;
    uint32_t bit_width = 0;
    switch (k_val) {
        case 4:
            if (!ds4_vqb2_decode_fp16_k4_x16_mtl4_pipeline_init()) return 0;
            vec_pipeline = g_vqb2_decode_fp16_k4_x16_mtl4_pipeline;
            codes_per_thread = 16; bit_width = 2; break;
        case 16:
            if (!ds4_vqb2_decode_fp16_k16_x8_mtl4_pipeline_init()) return 0;
            vec_pipeline = g_vqb2_decode_fp16_k16_x8_mtl4_pipeline;
            codes_per_thread = 8; bit_width = 4; break;
        case 256:
            if (!ds4_vqb2_decode_fp16_k256_x4_mtl4_pipeline_init()) return 0;
            vec_pipeline = g_vqb2_decode_fp16_k256_x4_mtl4_pipeline;
            codes_per_thread = 4; bit_width = 8; break;
        default:
            fprintf(stderr, "ds4: vqb2_decode_vectorized_bench requires K∈{4,16,256} (got %u)\n", k_val);
            return 0;
    }
    if (n_packets == 0 || n_selected == 0 || n_selected > n_experts_total) return 0;
    if (n_rows == 0 || n_pairs == 0 || rounds == 0) return 0;
    const uint32_t codes_per_expert = n_rows * n_pairs;
    if (codes_per_expert % codes_per_thread != 0) {
        fprintf(stderr, "ds4: codes_per_expert=%u not divisible by codes_per_thread=%u\n",
                codes_per_expert, codes_per_thread);
        return 0;
    }
    const uint64_t total_codes_per_packet = (uint64_t)n_experts_total * codes_per_expert;
    const size_t codes_bytes_per_packet = (size_t)(total_codes_per_packet * bit_width + 7u) >> 3;
    const size_t sel_out_per_packet  = (size_t)n_selected * codes_per_expert * 2u * sizeof(_Float16);

    int rc = 0;
    int mismatch = 0;
    double t_scalar_ms = 0, t_vec_ms = 0;

    @autoreleasepool {
        const float step = 1.0f / (float)k_val;
        id<MTLBuffer> cbBuf = [g_device newBufferWithLength:(NSUInteger)k_val * 2u * sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> codesBuf = [g_device newBufferWithLength:(NSUInteger)n_packets * codes_bytes_per_packet options:MTLResourceStorageModeShared];
        id<MTLBuffer> selBuf = [g_device newBufferWithLength:(NSUInteger)n_selected * sizeof(uint32_t) options:MTLResourceStorageModeShared];
        id<MTLBuffer> outScalarBuf = [g_device newBufferWithLength:(NSUInteger)n_packets * sel_out_per_packet options:MTLResourceStorageModeShared];
        id<MTLBuffer> outVecBuf    = [g_device newBufferWithLength:(NSUInteger)n_packets * sel_out_per_packet options:MTLResourceStorageModeShared];
        if (!cbBuf || !codesBuf || !selBuf || !outScalarBuf || !outVecBuf) return 0;

        float *cb_data = (float *)cbBuf.contents;
        for (uint32_t i = 0; i < k_val; i++) {
            cb_data[i * 2u + 0u] =  (float)i * step;
            cb_data[i * 2u + 1u] = -(float)i * step;
        }
        /* Pack distinct codes per (expert, position) so any divergence is detectable. */
        uint8_t *codes_host = (uint8_t *)codesBuf.contents;
        memset(codes_host, 0, (size_t)n_packets * codes_bytes_per_packet);
        for (uint32_t p = 0; p < n_packets; p++) {
            uint8_t *base = codes_host + (size_t)p * codes_bytes_per_packet;
            for (uint32_t e = 0; e < n_experts_total; e++) {
                for (uint32_t i = 0; i < codes_per_expert; i++) {
                    const uint32_t code = (e + i + p) % k_val;
                    const uint64_t linear = (uint64_t)e * codes_per_expert + i;
                    const uint64_t bit_off = linear * bit_width;
                    const size_t byte_off = (size_t)(bit_off >> 3);
                    const uint32_t shift = (uint32_t)(bit_off & 7ull);
                    base[byte_off] |= (uint8_t)((code << shift) & 0xFFu);
                    if (bit_width + shift > 8u) {
                        base[byte_off + 1u] |= (uint8_t)((code >> (8u - shift)) & 0xFFu);
                    }
                }
            }
        }
        uint32_t *sel = (uint32_t *)selBuf.contents;
        for (uint32_t i = 0; i < n_selected; i++) sel[i] = i * (n_experts_total / n_selected);

        /* Args structs */
        struct scalar_args_t {
            uint32_t bit_width, code_mask, n_rows, n_pairs,
                     n_selected, n_packets, codes_stride, out_stride;
        } scalar_args = {
            bit_width, (1u << bit_width) - 1u, n_rows, n_pairs,
            n_selected, n_packets,
            (uint32_t)codes_bytes_per_packet,
            (uint32_t)(sel_out_per_packet / sizeof(_Float16) / 2u),
        };
        id<MTLBuffer> scalarArgsBuf = [g_device newBufferWithBytes:&scalar_args length:sizeof(scalar_args) options:MTLResourceStorageModeShared];

        struct vec_args_t {
            uint32_t n_rows, n_pairs, n_selected, n_packets,
                     codes_stride, out_stride, pad0, pad1;
        } vec_args = {
            n_rows, n_pairs, n_selected, n_packets,
            (uint32_t)codes_bytes_per_packet,
            (uint32_t)(sel_out_per_packet / sizeof(_Float16) / 2u),
            0, 0,
        };
        id<MTLBuffer> vecArgsBuf = [g_device newBufferWithBytes:&vec_args length:sizeof(vec_args) options:MTLResourceStorageModeShared];

        mach_timebase_info_data_t tb; mach_timebase_info(&tb);

        /* === SCALAR baseline (the batched kernel from earlier session) === */
        const uint64_t tS0 = mach_absolute_time();
        for (uint32_t r = 0; r < rounds; r++) {
            id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
            [cb beginCommandBufferWithAllocator:g_polar_allocator];
            id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
            id<MTL4ArgumentTable> at = ds4_mtl4_pool_acquire(8);
            if (!at) return 0;
            [at setAddress:scalarArgsBuf.gpuAddress atIndex:0];
            [at setAddress:cbBuf.gpuAddress atIndex:1];
            [at setAddress:codesBuf.gpuAddress atIndex:2];
            [at setAddress:selBuf.gpuAddress atIndex:3];
            [at setAddress:outScalarBuf.gpuAddress atIndex:4];
            [enc setComputePipelineState:g_vqb2_decode_fp16_batched_mtl4_pipeline];
            [enc setArgumentTable:at];
            [enc dispatchThreadgroups:MTLSizeMake((codes_per_expert + 63u) / 64u, n_selected, n_packets)
                threadsPerThreadgroup:MTLSizeMake(64, 1, 1)];
            [enc endEncoding];
            [cb endCommandBuffer];
            dispatch_semaphore_t sem = dispatch_semaphore_create(0);
            MTL4CommitOptions *opts = [MTL4CommitOptions new];
            [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) { (void)fb; dispatch_semaphore_signal(sem); }];
            id<MTL4CommandBuffer> bufs[1] = {cb};
            [g_polar_queue commit:bufs count:1 options:opts];
            dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 10LL * NSEC_PER_SEC));
            ds4_mtl4_pool_release(at, 8);
        }
        const uint64_t tS1 = mach_absolute_time();
        t_scalar_ms = (double)(tS1 - tS0) * (double)tb.numer / (double)tb.denom / 1e6;

        /* === VECTORIZED === */
        const uint32_t tg_x = (codes_per_expert / codes_per_thread + 63u) / 64u;
        const uint64_t tV0 = mach_absolute_time();
        for (uint32_t r = 0; r < rounds; r++) {
            id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
            [cb beginCommandBufferWithAllocator:g_polar_allocator];
            id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
            id<MTL4ArgumentTable> at = ds4_mtl4_pool_acquire(8);
            if (!at) return 0;
            [at setAddress:vecArgsBuf.gpuAddress atIndex:0];
            [at setAddress:cbBuf.gpuAddress atIndex:1];
            [at setAddress:codesBuf.gpuAddress atIndex:2];
            [at setAddress:selBuf.gpuAddress atIndex:3];
            [at setAddress:outVecBuf.gpuAddress atIndex:4];
            [enc setComputePipelineState:vec_pipeline];
            [enc setArgumentTable:at];
            [enc dispatchThreadgroups:MTLSizeMake(tg_x, n_selected, n_packets)
                threadsPerThreadgroup:MTLSizeMake(64, 1, 1)];
            [enc endEncoding];
            [cb endCommandBuffer];
            dispatch_semaphore_t sem = dispatch_semaphore_create(0);
            MTL4CommitOptions *opts = [MTL4CommitOptions new];
            [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) { (void)fb; dispatch_semaphore_signal(sem); }];
            id<MTL4CommandBuffer> bufs[1] = {cb};
            [g_polar_queue commit:bufs count:1 options:opts];
            dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 10LL * NSEC_PER_SEC));
            ds4_mtl4_pool_release(at, 8);
        }
        const uint64_t tV1 = mach_absolute_time();
        t_vec_ms = (double)(tV1 - tV0) * (double)tb.numer / (double)tb.denom / 1e6;

        /* Cross-check bit-exactness against scalar output */
        const _Float16 *scalar_out = (const _Float16 *)outScalarBuf.contents;
        const _Float16 *vec_out    = (const _Float16 *)outVecBuf.contents;
        const size_t n_halves = (size_t)n_packets * sel_out_per_packet / sizeof(_Float16);
        for (size_t i = 0; i < n_halves; i++) {
            if ((float)scalar_out[i] != (float)vec_out[i]) mismatch++;
        }
        rc = 1;
    }

    const uint64_t bytes_per_round =
        (uint64_t)n_packets * n_selected * codes_per_expert * 2u * sizeof(_Float16);
    const double gbs_scalar = ((double)bytes_per_round * rounds / 1e9) / (t_scalar_ms / 1000.0);
    const double gbs_vec    = ((double)bytes_per_round * rounds / 1e9) / (t_vec_ms / 1000.0);

    fprintf(stderr,
        "ds4: vqb2_decode_vectorized_bench n_packets=%u n_sel=%u/%u rows=%u pairs=%u K=%u "
        "codes_per_thread=%u rounds=%u\n"
        "  scalar (1 code/thread):  %.3f ms (%.3f ms/round)  %.1f GB/s\n"
        "  vector (%u codes/thread): %.3f ms (%.3f ms/round)  %.1f GB/s   speedup=%.2fx\n"
        "  cross-check mismatch=%d (bit-exact must be 0)  rc=%d\n",
        n_packets, n_selected, n_experts_total, n_rows, n_pairs, k_val,
        codes_per_thread, rounds,
        t_scalar_ms, t_scalar_ms / (double)rounds, gbs_scalar,
        codes_per_thread, t_vec_ms, t_vec_ms / (double)rounds, gbs_vec,
        t_scalar_ms / t_vec_ms,
        mismatch, rc);
    return (rc && mismatch == 0) ? 1 : 0;
}

static NSString * const k_vqb2_decode_fp16_msl =
    @"#include <metal_stdlib>\n"
     "using namespace metal;\n"
     "struct args_t {\n"
     "  uint bit_width;\n"
     "  uint code_mask;\n"
     "  uint n_codes;\n"
     "  uint start_linear;\n"
     "};\n"
     "kernel void vqb2_decode_fp16(\n"
     "    device const args_t *args [[buffer(0)]],\n"
     "    device const float  *codebook [[buffer(1)]],\n"
     "    device const uchar  *codes [[buffer(2)]],\n"
     "    device       half2  *out_fp16 [[buffer(3)]],\n"
     "    uint gid [[thread_position_in_grid]]) {\n"
     "  if (gid >= args->n_codes) return;\n"
     "  const uint linear = args->start_linear + gid;\n"
     "  const uint bit_off = linear * args->bit_width;\n"
     "  const uint byte_off = bit_off >> 3;\n"
     "  const uint shift = bit_off & 7u;\n"
     "  const uint lo = (uint)codes[byte_off];\n"
     "  const uint hi = (args->bit_width + shift > 8u) ? (uint)codes[byte_off + 1u] : 0u;\n"
     "  const uint window = lo | (hi << 8);\n"
     "  const uint code = (window >> shift) & args->code_mask;\n"
     "  const float re = codebook[code * 2u + 0u];\n"
     "  const float im = codebook[code * 2u + 1u];\n"
     "  out_fp16[gid] = half2((half)re, (half)im);\n"
     "}\n";

static int ds4_vqb2_decode_fp16_mtl4_pipeline_init(void) {
    if (g_vqb2_decode_fp16_mtl4_init_attempted) return g_vqb2_decode_fp16_mtl4_init_ok;
    g_vqb2_decode_fp16_mtl4_init_attempted = 1;
    g_vqb2_decode_fp16_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        k_vqb2_decode_fp16_msl, @"ds4_vqb2_decode_fp16_mtl4",
        @"vqb2_decode_fp16", 64, NULL, 0);
    g_vqb2_decode_fp16_mtl4_init_ok =
        (g_vqb2_decode_fp16_mtl4_pipeline != nil) ? 1 : 0;
    return g_vqb2_decode_fp16_mtl4_init_ok;
}

/* silv 2026-05-28 ICB Phase 8: classic-MTL VQB2 decoder pipeline. Imports
 * the shared k_vqb2_decode_fp16_msl module-source (see above) — same MSL
 * compiled via newLibraryWithSource (classic path) instead of MTL4Compiler.
 * supportIndirectCommandBuffers=YES is set on the pipeline descriptor so
 * classic ICB recording works (the MTL4 path is not ICB-encodable in
 * classic mode). */
static int ds4_vqb2_decode_fp16_classic_pipeline_init(void) {
    if (g_vqb2_decode_fp16_classic_init_attempted) return g_vqb2_decode_fp16_classic_init_ok;
    g_vqb2_decode_fp16_classic_init_attempted = 1;
    NSError *err = nil;
    id<MTLLibrary> lib = [g_device newLibraryWithSource:k_vqb2_decode_fp16_msl
                                                options:nil error:&err];
    if (!lib) {
        fprintf(stderr, "ds4: vqb2_decode_fp16_classic library compile failed: %s\n",
                err ? err.localizedDescription.UTF8String : "(no error)");
        return 0;
    }
    id<MTLFunction> fn = [lib newFunctionWithName:@"vqb2_decode_fp16"];
    if (!fn) {
        fprintf(stderr, "ds4: vqb2_decode_fp16 function not found in classic library\n");
        return 0;
    }
    MTLComputePipelineDescriptor *pdesc = [MTLComputePipelineDescriptor new];
    pdesc.computeFunction = fn;
    pdesc.supportIndirectCommandBuffers = YES;
    g_vqb2_decode_fp16_classic_pipeline =
        [g_device newComputePipelineStateWithDescriptor:pdesc
                                                options:MTLPipelineOptionNone
                                             reflection:nil
                                                  error:&err];
    if (!g_vqb2_decode_fp16_classic_pipeline) {
        fprintf(stderr, "ds4: vqb2_decode_fp16_classic pipeline failed: %s\n",
                err ? err.localizedDescription.UTF8String : "(no error)");
        return 0;
    }
    g_vqb2_decode_fp16_classic_init_ok = 1;
    fprintf(stderr, "ds4: vqb2_decode_fp16_classic pipeline initialized (ICB-compatible)\n");
    return 1;
}

/* Record/replay one VQB2 decode dispatch via classic-MTL ICB. Per-slot
 * signature: (codebook_ptr, codes_ptr, out_ptr, n_codes, bit_width,
 * start_linear). Re-records on signature change. Args buffer is per-slot
 * (vary independently per packet — n_codes/bit_width/start_linear).
 *
 * Returns 1 if dispatched via ICB (recording on first signature, replay
 * otherwise); 0 on hard error or if slot_idx out of range. Caller is
 * responsible for ensuring buffers have correct contents at execute time
 * (ICB binds buffer+offset, not bytes). Opt-in via DS4_ICB_VQB2_DECODE=1. */
static int ds4_gpu_vqb2_decode_fp16_icb_dispatch(
        id<MTLCommandBuffer> cb,
        uint32_t slot_idx,
        id<MTLBuffer> codebook, NSUInteger codebook_off,
        id<MTLBuffer> codes,    NSUInteger codes_off,
        id<MTLBuffer> out_buf,  NSUInteger out_off,
        uint32_t n_codes, uint32_t bit_width, uint32_t start_linear) {
    static int s_env_checked = 0;
    static int s_env_active = 0;
    if (!s_env_checked) {
        s_env_active = getenv("DS4_ICB_VQB2_DECODE") != NULL ? 1 : 0;
        s_env_checked = 1;
        if (s_env_active) {
            fprintf(stderr, "ds4: DS4_ICB_VQB2_DECODE=1 — VQB2 decoder ICB engaged "
                            "(64 slots, layer-window record/replay)\n");
        }
    }
    if (!s_env_active) return 0;
    if (slot_idx >= DS4_VQB2_DECODE_ICB_SLOTS) return 0;
    if (!cb || !codebook || !codes || !out_buf) return 0;
    if (!ds4_vqb2_decode_fp16_classic_pipeline_init()) return 0;

    /* Cycle 9g (silv 2026-05-28 task #673/#795) — migrated to unified
     * ds4_icb_slot API. The Phase 8a slot's recorded scalars
     * (n_codes, bit_width, start_linear) go into signature extras. */
    if (!g_vqb2_decode_slot.icb) {
        if (!ds4_icb_slot_acquire(&g_vqb2_decode_slot,
                                  /*max_commands=*/(NSUInteger)DS4_VQB2_DECODE_ICB_SLOTS,
                                  /*max_bindings=*/4)) {
            fprintf(stderr, "ds4: VQB2 decoder ICB slot acquire failed\n");
            return 0;
        }
    }
    /* Lazy-allocate per-slot args buffer */
    if (!g_vqb2_decode_icb_args_buffers[slot_idx]) {
        g_vqb2_decode_icb_args_buffers[slot_idx] =
            [g_device newBufferWithLength:16 options:MTLResourceStorageModeShared];
        if (!g_vqb2_decode_icb_args_buffers[slot_idx]) return 0;
    }
    /* Args buffer is rewritten each call (cheap memcpy of 16 bytes).
     * Signature extras capture the scalar values so signature mismatch
     * triggers re-record when scalars change (in addition to buffer changes). */
    {
        uint32_t *args = (uint32_t *)g_vqb2_decode_icb_args_buffers[slot_idx].contents;
        args[0] = bit_width;
        args[1] = (1u << bit_width) - 1u;
        args[2] = n_codes;
        args[3] = start_linear;
    }

    __unsafe_unretained id<MTLBuffer> bufs[4] = {
        g_vqb2_decode_icb_args_buffers[slot_idx], codebook, codes, out_buf };
    NSUInteger offs[4] = { 0, codebook_off, codes_off, out_off };
    const NSUInteger tg = (n_codes + 63u) / 64u;
    uint64_t extras[3] = { n_codes, bit_width, start_linear };
    if (!ds4_icb_slot_record_command(&g_vqb2_decode_slot, /*cmd_idx=*/slot_idx,
                                     g_vqb2_decode_fp16_classic_pipeline,
                                     bufs, offs, 4,
                                     MTLSizeMake(tg, 1, 1),
                                     MTLSizeMake(64, 1, 1), 0,
                                     extras, 3)) {
        return 0;
    }

    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc useResource:g_vqb2_decode_icb_args_buffers[slot_idx] usage:MTLResourceUsageRead];
    [enc useResource:codebook usage:MTLResourceUsageRead];
    [enc useResource:codes    usage:MTLResourceUsageRead];
    [enc useResource:out_buf  usage:MTLResourceUsageRead | MTLResourceUsageWrite];
    ds4_icb_slot_execute(&g_vqb2_decode_slot, enc, slot_idx, 1);
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

/* ICB Phase 8 bench/canary: build N synthetic packets, dispatch via direct
 * compute encoder vs ICB record-and-replay, measure both wall times.
 *
 * The bench runs ROUNDS iterations of (record + N executes) for ICB and N
 * direct dispatches per round for the baseline; reports per-iter mean.
 * Verifies ICB output bit-exact against direct decode for round 1.
 *
 * Returns 1 on success; 0 on failure. */
int ds4_gpu_mtl4_vqb2_decode_icb_bench(uint32_t n_packets, uint32_t n_codes_per_packet,
                                       uint32_t k_val, uint32_t rounds) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_vqb2_decode_fp16_classic_pipeline_init()) return 0;
    if (n_packets == 0 || n_packets > DS4_VQB2_DECODE_ICB_SLOTS) {
        fprintf(stderr, "ds4: vqb2_decode_icb_bench needs 1 ≤ n_packets ≤ %u (got %u)\n",
                DS4_VQB2_DECODE_ICB_SLOTS, n_packets);
        return 0;
    }
    if (n_codes_per_packet == 0 || rounds == 0) return 0;
    uint32_t bit_width;
    switch (k_val) {
        case 4:   bit_width = 2; break;
        case 16:  bit_width = 4; break;
        case 64:  bit_width = 6; break;
        case 256: bit_width = 8; break;
        default:
            fprintf(stderr, "ds4: vqb2_decode_icb_bench K must be 4|16|64|256 (got %u)\n", k_val);
            return 0;
    }
    /* Force env active for the bench so we can observe ICB even when caller
     * didn't pre-set DS4_ICB_VQB2_DECODE. */
    setenv("DS4_ICB_VQB2_DECODE", "1", 1);

    /* Synthetic packets: each has the same codebook + a synthetic codes stream.
     * codebook[i] = (i*step, -i*step), step = 1/k.
     * codes[i] = i % k → out_fp16[i] = (re, im) for centroid (i%k).
     * All packets share a single codebook buffer to minimize bench noise; codes
     * and out are per-packet to allow ICB slot-keyed binding. */
    const float step = 1.0f / (float)k_val;
    const size_t codes_bytes_per_packet = (size_t)((uint64_t)n_codes_per_packet * (uint64_t)bit_width + 7u) >> 3;
    const size_t out_bytes_per_packet = (size_t)n_codes_per_packet * 2u * sizeof(_Float16);

    int rc = 0;
    double t_direct_ms = 0.0, t_icb_ms = 0.0;
    int mismatch_total = 0;

    @autoreleasepool {
        /* Codebook */
        id<MTLBuffer> cbBuf = [g_device newBufferWithLength:(NSUInteger)k_val * 2u * sizeof(float)
                                                   options:MTLResourceStorageModeShared];
        if (!cbBuf) goto cleanup;
        float *cb_data = (float *)cbBuf.contents;
        for (uint32_t i = 0; i < k_val; i++) {
            cb_data[i * 2u + 0u] =  (float)i * step;
            cb_data[i * 2u + 1u] = -(float)i * step;
        }

        /* Per-packet codes + out buffers, packed into a single underlying
         * buffer with per-packet offsets — closer to the pack-mmap shape. */
        const NSUInteger codes_total = (NSUInteger)n_packets * (NSUInteger)codes_bytes_per_packet;
        const NSUInteger out_total   = (NSUInteger)n_packets * (NSUInteger)out_bytes_per_packet;
        id<MTLBuffer> codesBuf = [g_device newBufferWithLength:codes_total
                                                       options:MTLResourceStorageModeShared];
        id<MTLBuffer> outBuf   = [g_device newBufferWithLength:out_total
                                                       options:MTLResourceStorageModeShared];
        if (!codesBuf || !outBuf) goto cleanup;

        /* Fill codes: per packet, code[i] = i % k */
        for (uint32_t p = 0; p < n_packets; p++) {
            uint8_t *base = (uint8_t *)codesBuf.contents + (size_t)p * codes_bytes_per_packet;
            memset(base, 0, codes_bytes_per_packet);
            for (uint32_t i = 0; i < n_codes_per_packet; i++) {
                const uint32_t code = i % k_val;
                const uint32_t bit_off = i * bit_width;
                const uint32_t byte_off = bit_off >> 3;
                const uint32_t shift = bit_off & 7u;
                base[byte_off] |= (uint8_t)((code << shift) & 0xFFu);
                if (bit_width + shift > 8u) {
                    base[byte_off + 1u] |= (uint8_t)((code >> (8u - shift)) & 0xFFu);
                }
            }
        }
        /* Args buffer for direct path (shared, same args across packets). */
        uint32_t args_direct[4] = { bit_width, (1u << bit_width) - 1u, n_codes_per_packet, 0 };
        id<MTLBuffer> argsBufDirect = [g_device newBufferWithBytes:args_direct length:16
                                                           options:MTLResourceStorageModeShared];

        /* === BASELINE: N direct dispatches per round === */
        const uint64_t t0_direct = mach_absolute_time();
        for (uint32_t r = 0; r < rounds; r++) {
            id<MTLCommandBuffer> cb = [g_queue commandBuffer];
            id<MTLComputeCommandEncoder> enc = [cb computeCommandEncoder];
            for (uint32_t p = 0; p < n_packets; p++) {
                [enc setComputePipelineState:g_vqb2_decode_fp16_classic_pipeline];
                [enc setBuffer:argsBufDirect offset:0 atIndex:0];
                [enc setBuffer:cbBuf offset:0 atIndex:1];
                [enc setBuffer:codesBuf offset:(NSUInteger)p * codes_bytes_per_packet atIndex:2];
                [enc setBuffer:outBuf offset:(NSUInteger)p * out_bytes_per_packet atIndex:3];
                const NSUInteger tg = (n_codes_per_packet + 63u) / 64u;
                [enc dispatchThreadgroups:MTLSizeMake(tg, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(64, 1, 1)];
            }
            [enc endEncoding];
            [cb commit];
            [cb waitUntilCompleted];
        }
        const uint64_t t1_direct = mach_absolute_time();
        mach_timebase_info_data_t tb;
        mach_timebase_info(&tb);
        t_direct_ms = (double)(t1_direct - t0_direct) * (double)tb.numer / (double)tb.denom / 1e6;

        /* Capture direct output for cross-check */
        _Float16 *direct_out = (_Float16 *)malloc(out_total);
        if (direct_out) memcpy(direct_out, outBuf.contents, out_total);
        memset(outBuf.contents, 0, out_total);

        /* === ICB: record N slots ONCE; per round do ONE encoder + ONE
         * executeCommandsInBuffer(range=N). This is the actual amortization
         * shape: setComputePipelineState + 4 setBuffer × N = 0 (replaced by
         * pre-recorded ICB commands); single encoder open/close per round. */
        /* Reset ICB slot state for clean bench (Cycle 9g: unified slot). */
        for (uint32_t p = 0; p < DS4_VQB2_DECODE_ICB_SLOTS; p++) {
            g_vqb2_decode_slot.recorded[p] = 0;
        }
        /* Pre-record all N slots in one priming command buffer (not timed —
         * one-time cost amortized across all future calls). */
        {
            id<MTLCommandBuffer> prime_cb = [g_queue commandBuffer];
            for (uint32_t p = 0; p < n_packets; p++) {
                ds4_gpu_vqb2_decode_fp16_icb_dispatch(prime_cb, p,
                    cbBuf, 0,
                    codesBuf, (NSUInteger)p * codes_bytes_per_packet,
                    outBuf,   (NSUInteger)p * out_bytes_per_packet,
                    n_codes_per_packet, bit_width, 0);
            }
            [prime_cb commit];
            [prime_cb waitUntilCompleted];
        }
        /* Now time pure replay: per round, single encoder + single execute. */
        const uint64_t t0_icb = mach_absolute_time();
        for (uint32_t r = 0; r < rounds; r++) {
            id<MTLCommandBuffer> cb = [g_queue commandBuffer];
            id<MTLComputeCommandEncoder> enc = [cb computeCommandEncoder];
            /* Mark all buffers needed by the recorded commands as resident. */
            [enc useResource:cbBuf usage:MTLResourceUsageRead];
            [enc useResource:codesBuf usage:MTLResourceUsageRead];
            [enc useResource:outBuf usage:MTLResourceUsageRead | MTLResourceUsageWrite];
            for (uint32_t p = 0; p < n_packets; p++) {
                [enc useResource:g_vqb2_decode_icb_args_buffers[p] usage:MTLResourceUsageRead];
            }
            /* Cycle 9g: bench-site replay uses the unified slot's icb. */
            [enc executeCommandsInBuffer:g_vqb2_decode_slot.icb
                               withRange:NSMakeRange(0, n_packets)];
            [enc endEncoding];
            [cb commit];
            [cb waitUntilCompleted];
        }
        const uint64_t t1_icb = mach_absolute_time();
        t_icb_ms = (double)(t1_icb - t0_icb) * (double)tb.numer / (double)tb.denom / 1e6;

        /* Cross-check ICB output against direct */
        if (direct_out) {
            const _Float16 *icb_out = (const _Float16 *)outBuf.contents;
            const size_t n_halves = out_total / sizeof(_Float16);
            for (size_t i = 0; i < n_halves; i++) {
                if ((float)icb_out[i] != (float)direct_out[i]) mismatch_total++;
            }
            free(direct_out);
        }

        rc = 1;
    }

cleanup:
    fprintf(stderr,
        "ds4: vqb2_decode_icb_bench n_packets=%u n_codes=%u K=%u bw=%u rounds=%u "
        "direct=%.3f ms (%.3f ms/round) icb=%.3f ms (%.3f ms/round) speedup=%.2fx "
        "mismatch=%d rc=%d\n",
        n_packets, n_codes_per_packet, k_val, bit_width, rounds,
        t_direct_ms, t_direct_ms / (double)rounds,
        t_icb_ms,    t_icb_ms    / (double)rounds,
        t_direct_ms > 0.0 ? t_direct_ms / t_icb_ms : 0.0,
        mismatch_total, rc);
    return (rc && mismatch_total == 0) ? 1 : 0;
}

/* ============================================================ */
/* Selected-expert VQB2 decoder — H2125 routed-MoE primitive    */
/* ============================================================ */
/* The base vqb2_decode_fp16_mtl4 kernel decodes a contiguous code range.
 * For routed MoE dispatch (H2125 layer-window pattern), each packet
 * carries 256 experts but only 6 are selected per token. This kernel
 * decodes ONLY the selected subset directly from the packet's codes
 * stream, producing a dense (n_selected × n_rows × n_pairs) fp16 output.
 *
 * Layout inside the packet: expert e starts at linear_index = e × n_rows ×
 * n_pairs. Codes are little-bit-endian packed (bit_width ∈ {2,4,6,8}).
 *
 * Output is packed by selection order (not expert ID), so caller's downstream
 * matmul indexes [k=0..n_selected-1] directly. */

static id<MTLComputePipelineState> g_vqb2_decode_fp16_selected_mtl4_pipeline;
static int g_vqb2_decode_fp16_selected_mtl4_init_attempted;
static int g_vqb2_decode_fp16_selected_mtl4_init_ok;

static int ds4_vqb2_decode_fp16_selected_mtl4_pipeline_init(void) {
    if (g_vqb2_decode_fp16_selected_mtl4_init_attempted) return g_vqb2_decode_fp16_selected_mtl4_init_ok;
    g_vqb2_decode_fp16_selected_mtl4_init_attempted = 1;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "struct args_t {\n"
         "  uint bit_width;\n"
         "  uint code_mask;\n"
         "  uint n_rows;\n"
         "  uint n_pairs;\n"
         "  uint n_selected;\n"
         "  uint pad;\n"
         "};\n"
         "kernel void vqb2_decode_fp16_selected_mtl4(\n"
         "    device const args_t *args         [[buffer(0)]],\n"
         "    device const float  *codebook     [[buffer(1)]],\n"
         "    device const uchar  *codes        [[buffer(2)]],\n"
         "    device const uint   *selected     [[buffer(3)]],\n"
         "    device       half2  *out_fp16     [[buffer(4)]],\n"
         "    uint2 gid [[thread_position_in_grid]]) {\n"
         "  /* gid.x = code index within one expert (0..n_rows*n_pairs-1)\n"
         "   * gid.y = selection slot (0..n_selected-1) */\n"
         "  const uint codes_per_expert = args->n_rows * args->n_pairs;\n"
         "  if (gid.x >= codes_per_expert) return;\n"
         "  if (gid.y >= args->n_selected) return;\n"
         "  const uint expert = selected[gid.y];\n"
         "  const uint linear = expert * codes_per_expert + gid.x;\n"
         "  const uint bit_off = linear * args->bit_width;\n"
         "  const uint byte_off = bit_off >> 3;\n"
         "  const uint shift = bit_off & 7u;\n"
         "  const uint lo = (uint)codes[byte_off];\n"
         "  const uint hi = (args->bit_width + shift > 8u) ? (uint)codes[byte_off + 1u] : 0u;\n"
         "  const uint window = lo | (hi << 8);\n"
         "  const uint code = (window >> shift) & args->code_mask;\n"
         "  const float re = codebook[code * 2u + 0u];\n"
         "  const float im = codebook[code * 2u + 1u];\n"
         "  const uint out_idx = gid.y * codes_per_expert + gid.x;\n"
         "  out_fp16[out_idx] = half2((half)re, (half)im);\n"
         "}\n";
    g_vqb2_decode_fp16_selected_mtl4_pipeline = ds4_mtl4_build_kernel_pipeline(
        source, @"ds4_vqb2_decode_fp16_selected_mtl4",
        @"vqb2_decode_fp16_selected_mtl4", 64, NULL, 0);
    g_vqb2_decode_fp16_selected_mtl4_init_ok =
        (g_vqb2_decode_fp16_selected_mtl4_pipeline != nil) ? 1 : 0;
    return g_vqb2_decode_fp16_selected_mtl4_init_ok;
}

/* Canary: synthetic packet with 256 experts, select arbitrary k experts,
 * decode them, cross-check against the equivalent base-kernel decode of the
 * same expert IDs. K∈{4,16,64,256}. */
int ds4_gpu_mtl4_vqb2_decode_fp16_selected_canary(uint32_t n_selected,
                                                  uint32_t n_experts_total,
                                                  uint32_t n_rows,
                                                  uint32_t n_pairs,
                                                  uint32_t k_val) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_vqb2_decode_fp16_selected_mtl4_pipeline_init()) return 0;
    if (n_selected == 0 || n_selected > n_experts_total) {
        fprintf(stderr, "ds4: vqb2_decode_fp16_selected canary needs 1 ≤ n_selected ≤ n_experts_total\n");
        return 0;
    }
    if (n_rows == 0 || n_pairs == 0) return 0;
    uint32_t bit_width;
    switch (k_val) {
        case 4:   bit_width = 2; break;
        case 16:  bit_width = 4; break;
        case 64:  bit_width = 6; break;
        case 256: bit_width = 8; break;
        default:  return 0;
    }
    const uint32_t codes_per_expert = n_rows * n_pairs;
    const uint64_t total_codes = (uint64_t)n_experts_total * codes_per_expert;
    const size_t codes_bytes = (size_t)(total_codes * bit_width + 7u) >> 3;

    /* Build codebook in [-1, +1]. */
    float *host_cb = (float *)calloc((size_t)k_val * 2u, sizeof(float));
    if (!host_cb) return 0;
    const float step = 1.0f / (float)k_val;
    for (uint32_t i = 0; i < k_val; i++) {
        host_cb[i * 2u + 0u] =  (float)i * step;
        host_cb[i * 2u + 1u] = -(float)i * step;
    }
    /* Pack codes: per (expert, code_idx), code = (expert + code_idx) % k.
     * Distinct per expert → cross-check rules out cross-expert smearing. */
    uint8_t *host_codes = (uint8_t *)calloc(codes_bytes + 8u, 1);
    if (!host_codes) { free(host_cb); return 0; }
    for (uint32_t e = 0; e < n_experts_total; e++) {
        for (uint32_t i = 0; i < codes_per_expert; i++) {
            const uint32_t code = (e + i) % k_val;
            const uint64_t linear = (uint64_t)e * codes_per_expert + i;
            const uint64_t bit_off = linear * bit_width;
            const size_t byte_off = (size_t)(bit_off >> 3);
            const uint32_t shift = (uint32_t)(bit_off & 7ull);
            host_codes[byte_off]      |= (uint8_t)((code << shift) & 0xFFu);
            if (bit_width + shift > 8u) {
                host_codes[byte_off + 1u] |= (uint8_t)((code >> (8u - shift)) & 0xFFu);
            }
        }
    }
    /* Build selected list: every Nth expert (spread evenly across range). */
    uint32_t *host_sel = (uint32_t *)calloc(n_selected, sizeof(uint32_t));
    if (!host_sel) { free(host_cb); free(host_codes); return 0; }
    const uint32_t stride_sel = (n_experts_total > n_selected) ? n_experts_total / n_selected : 1;
    for (uint32_t s = 0; s < n_selected; s++) {
        host_sel[s] = (s * stride_sel) % n_experts_total;
    }

    _Float16 *host_out = (_Float16 *)calloc((size_t)n_selected * codes_per_expert * 2u, sizeof(_Float16));
    if (!host_out) { free(host_cb); free(host_codes); free(host_sel); return 0; }

    int rc = 0;
    @autoreleasepool {
        struct { uint32_t bit_width, code_mask, n_rows, n_pairs, n_selected, pad; }
            args = { bit_width, (1u << bit_width) - 1u, n_rows, n_pairs, n_selected, 0 };
        id<MTLBuffer> argsBuf = [g_device newBufferWithBytes:&args length:sizeof(args) options:MTLResourceStorageModeShared];
        id<MTLBuffer> cbBuf   = [g_device newBufferWithBytes:host_cb length:(NSUInteger)k_val * 2u * sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> codesBuf= [g_device newBufferWithBytes:host_codes length:codes_bytes + 8u options:MTLResourceStorageModeShared];
        id<MTLBuffer> selBuf  = [g_device newBufferWithBytes:host_sel length:(NSUInteger)n_selected * sizeof(uint32_t) options:MTLResourceStorageModeShared];
        id<MTLBuffer> outBuf  = [g_device newBufferWithLength:(NSUInteger)n_selected * codes_per_expert * 2u * sizeof(_Float16) options:MTLResourceStorageModeShared];

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 8;
        NSError *err = nil;
        id<MTLResidencySet> rs = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (rs) {
            id<MTLAllocation> allocs[5] = {(id)argsBuf, (id)cbBuf, (id)codesBuf, (id)selBuf, (id)outBuf};
            [rs addAllocations:allocs count:5];
            [rs commit];
            ds4_residency_request_checked(rs, __func__);
            id<MTL4ArgumentTable> at = ds4_mtl4_pool_acquire(8);
            if (at) {
                [at setAddress:argsBuf.gpuAddress atIndex:0];
                [at setAddress:cbBuf.gpuAddress atIndex:1];
                [at setAddress:codesBuf.gpuAddress atIndex:2];
                [at setAddress:selBuf.gpuAddress atIndex:3];
                [at setAddress:outBuf.gpuAddress atIndex:4];
                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:rs];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_vqb2_decode_fp16_selected_mtl4_pipeline];
                [enc setArgumentTable:at];
                /* 2D grid: (codes_per_expert, n_selected). Threadgroup 64×1. */
                const NSUInteger tg_x = (codes_per_expert + 63u) / 64u;
                [enc dispatchThreadgroups:MTLSizeMake(tg_x, n_selected, 1)
                    threadsPerThreadgroup:MTLSizeMake(64, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];
                [g_polar_queue addResidencySet:rs];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) { (void)fb; dispatch_semaphore_signal(sem); }];
                id<MTL4CommandBuffer> bufs[1] = {cb};
                [g_polar_queue commit:bufs count:1 options:opts];
                long w = dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 10LL * NSEC_PER_SEC));
                [rs endResidency];
                if (w == 0) {
                    memcpy(host_out, outBuf.contents, (size_t)n_selected * codes_per_expert * 2u * sizeof(_Float16));
                    rc = 1;
                }
                ds4_mtl4_pool_release(at, 8);
            }
        }
    }
    /* Cross-check: for each selected expert, compute expected (re, im) per
     * code index and compare to host_out. */
    int mismatch = 0;
    double max_err = 0.0;
    if (rc) {
        for (uint32_t s = 0; s < n_selected; s++) {
            const uint32_t e = host_sel[s];
            for (uint32_t i = 0; i < codes_per_expert; i++) {
                const uint32_t code = (e + i) % k_val;
                const float exp_re = (float)code * step;
                const float exp_im = -(float)code * step;
                const uint32_t out_idx = (s * codes_per_expert + i) * 2u;
                const float got_re = (float)host_out[out_idx + 0u];
                const float got_im = (float)host_out[out_idx + 1u];
                const double e_re = fabs((double)(got_re - exp_re));
                const double e_im = fabs((double)(got_im - exp_im));
                if (e_re > max_err) max_err = e_re;
                if (e_im > max_err) max_err = e_im;
                if (e_re > 1e-3 || e_im > 1e-3) mismatch++;
            }
        }
    }
    fprintf(stderr,
        "ds4: vqb2_decode_fp16_selected MTL4 canary n_sel=%u n_total=%u rows=%u pairs=%u K=%u bw=%u "
        "mismatch=%d max_err=%.4e rc=%d sel[0]=%u sel[%u]=%u out[s0,0]=(%+.4f,%+.4f)\n",
        n_selected, n_experts_total, n_rows, n_pairs, k_val, bit_width,
        mismatch, max_err, rc,
        host_sel[0], n_selected - 1, host_sel[n_selected - 1],
        (double)host_out[0], (double)host_out[1]);
    free(host_cb); free(host_codes); free(host_sel); free(host_out);
    return (rc && mismatch == 0) ? 1 : 0;
}

/* silv 2026-05-28 — stacked-speedup bench. Quantifies the combined win of
 * the H2125 routed-MoE primitive: selected-expert decoder × ICB-style
 * single-encoder batched dispatch, compared to the baseline full-decode +
 * encoder-per-call path.
 *
 * The bench runs `rounds` iterations of: one routed-MoE layer event = 64
 * packets, each with 6 selected experts of 256, K=16 (gate/up shape) or
 * K=256 (L22 island).
 *
 * Configurations compared:
 *   A. FULL decode + per-packet encoder (baseline cost: 256 experts × 64
 *      packets × encoder open/close per call)
 *   B. SELECTED decode (6/256) + per-packet encoder (compute -42×, but
 *      encoder overhead still 64 calls)
 *   C. SELECTED decode + single-encoder batched (encoder overhead 1, the
 *      pack-direct production target shape)
 *
 * The "10× accuracy" of this bench: ICB / direct shape differences are
 * usually conflated; this bench isolates the compute-reduction win
 * (FULL → SELECTED) from the encoder-amortization win (per-packet →
 * batched) so each can be priced separately. Without isolation, codex
 * H2126 caught a fused-batched regression that was actually irregular
 * indexing; isolating axes prevents that confusion. */
int ds4_gpu_mtl4_vqb2_decode_stacked_speedup_bench(uint32_t n_packets,
                                                   uint32_t n_selected,
                                                   uint32_t n_experts_total,
                                                   uint32_t n_rows,
                                                   uint32_t n_pairs,
                                                   uint32_t k_val,
                                                   uint32_t rounds) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_vqb2_decode_fp16_mtl4_pipeline_init()) return 0;
    if (!ds4_vqb2_decode_fp16_selected_mtl4_pipeline_init()) return 0;
    if (!ds4_vqb2_decode_fp16_batched_mtl4_pipeline_init()) return 0;
    if (n_packets == 0 || n_selected == 0 || n_selected > n_experts_total) return 0;
    if (n_rows == 0 || n_pairs == 0 || rounds == 0) return 0;
    uint32_t bit_width;
    switch (k_val) {
        case 4:   bit_width = 2; break;
        case 16:  bit_width = 4; break;
        case 64:  bit_width = 6; break;
        case 256: bit_width = 8; break;
        default:  return 0;
    }
    const uint32_t codes_per_expert = n_rows * n_pairs;
    const uint64_t total_codes_per_packet = (uint64_t)n_experts_total * codes_per_expert;
    const size_t codes_bytes_per_packet = (size_t)(total_codes_per_packet * bit_width + 7u) >> 3;
    const size_t full_out_per_packet = (size_t)n_experts_total * codes_per_expert * 2u * sizeof(_Float16);
    const size_t sel_out_per_packet  = (size_t)n_selected * codes_per_expert * 2u * sizeof(_Float16);

    double t_A_ms = 0, t_B_ms = 0, t_C_ms = 0;

    @autoreleasepool {
        const float step = 1.0f / (float)k_val;
        /* Codebook + packed codes (n_packets × 256 experts × codes) + selection list. */
        id<MTLBuffer> cbBuf = [g_device newBufferWithLength:(NSUInteger)k_val * 2u * sizeof(float)
                                                   options:MTLResourceStorageModeShared];
        id<MTLBuffer> codesBuf = [g_device newBufferWithLength:(NSUInteger)n_packets * codes_bytes_per_packet
                                                       options:MTLResourceStorageModeShared];
        id<MTLBuffer> selBuf = [g_device newBufferWithLength:(NSUInteger)n_selected * sizeof(uint32_t)
                                                     options:MTLResourceStorageModeShared];
        id<MTLBuffer> fullOutBuf = [g_device newBufferWithLength:(NSUInteger)n_packets * full_out_per_packet
                                                         options:MTLResourceStorageModeShared];
        id<MTLBuffer> selOutBuf  = [g_device newBufferWithLength:(NSUInteger)n_packets * sel_out_per_packet
                                                         options:MTLResourceStorageModeShared];
        if (!cbBuf || !codesBuf || !selBuf || !fullOutBuf || !selOutBuf) return 0;

        float *cb_data = (float *)cbBuf.contents;
        for (uint32_t i = 0; i < k_val; i++) {
            cb_data[i * 2u + 0u] =  (float)i * step;
            cb_data[i * 2u + 1u] = -(float)i * step;
        }
        /* Codes filled deterministically (don't measure init time) */
        memset(codesBuf.contents, 0xCD, (NSUInteger)n_packets * codes_bytes_per_packet);
        uint32_t *sel = (uint32_t *)selBuf.contents;
        for (uint32_t i = 0; i < n_selected; i++) sel[i] = i * (n_experts_total / n_selected);

        struct full_args_t { uint32_t bit_width, code_mask, n_codes, start_linear; }
            full_args = { bit_width, (1u << bit_width) - 1u, (uint32_t)total_codes_per_packet, 0 };
        id<MTLBuffer> fullArgsBuf = [g_device newBufferWithBytes:&full_args length:sizeof(full_args)
                                                         options:MTLResourceStorageModeShared];
        struct sel_args_t { uint32_t bit_width, code_mask, n_rows, n_pairs, n_selected, pad; }
            sel_args = { bit_width, (1u << bit_width) - 1u, n_rows, n_pairs, n_selected, 0 };
        id<MTLBuffer> selArgsBuf = [g_device newBufferWithBytes:&sel_args length:sizeof(sel_args)
                                                        options:MTLResourceStorageModeShared];

        mach_timebase_info_data_t tb;
        mach_timebase_info(&tb);

        /* === A. FULL decode + per-packet encoder === */
        const uint64_t tA0 = mach_absolute_time();
        for (uint32_t r = 0; r < rounds; r++) {
            for (uint32_t p = 0; p < n_packets; p++) {
                id<MTLCommandBuffer> cb = [g_queue commandBuffer];
                id<MTLComputeCommandEncoder> enc = [cb computeCommandEncoder];
                /* Use the classic pipeline for fair comparison vs ICB path */
                if (!ds4_vqb2_decode_fp16_classic_pipeline_init()) return 0;
                [enc setComputePipelineState:g_vqb2_decode_fp16_classic_pipeline];
                [enc setBuffer:fullArgsBuf offset:0 atIndex:0];
                [enc setBuffer:cbBuf offset:0 atIndex:1];
                [enc setBuffer:codesBuf offset:(NSUInteger)p * codes_bytes_per_packet atIndex:2];
                [enc setBuffer:fullOutBuf offset:(NSUInteger)p * full_out_per_packet atIndex:3];
                const NSUInteger tg = (total_codes_per_packet + 63u) / 64u;
                [enc dispatchThreadgroups:MTLSizeMake(tg, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(64, 1, 1)];
                [enc endEncoding];
                [cb commit];
                [cb waitUntilCompleted];
            }
        }
        const uint64_t tA1 = mach_absolute_time();
        t_A_ms = (double)(tA1 - tA0) * (double)tb.numer / (double)tb.denom / 1e6;

        /* === B. SELECTED decode + per-packet encoder ===
         * (uses MTL4 path since classic path doesn't have a selected variant
         * pipeline. Both paths produce bit-identical output per #751.) */
        const uint64_t tB0 = mach_absolute_time();
        for (uint32_t r = 0; r < rounds; r++) {
            for (uint32_t p = 0; p < n_packets; p++) {
                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                id<MTL4ArgumentTable> at = ds4_mtl4_pool_acquire(8);
                if (!at) return 0;
                [at setAddress:selArgsBuf.gpuAddress atIndex:0];
                [at setAddress:cbBuf.gpuAddress atIndex:1];
                [at setAddress:codesBuf.gpuAddress + (uint64_t)p * codes_bytes_per_packet atIndex:2];
                [at setAddress:selBuf.gpuAddress atIndex:3];
                [at setAddress:selOutBuf.gpuAddress + (uint64_t)p * sel_out_per_packet atIndex:4];
                [enc setComputePipelineState:g_vqb2_decode_fp16_selected_mtl4_pipeline];
                [enc setArgumentTable:at];
                const NSUInteger tg_x = (codes_per_expert + 63u) / 64u;
                [enc dispatchThreadgroups:MTLSizeMake(tg_x, n_selected, 1)
                    threadsPerThreadgroup:MTLSizeMake(64, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) { (void)fb; dispatch_semaphore_signal(sem); }];
                id<MTL4CommandBuffer> bufs[1] = {cb};
                [g_polar_queue commit:bufs count:1 options:opts];
                dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 10LL * NSEC_PER_SEC));
                ds4_mtl4_pool_release(at, 8);
            }
        }
        const uint64_t tB1 = mach_absolute_time();
        t_B_ms = (double)(tB1 - tB0) * (double)tb.numer / (double)tb.denom / 1e6;

        /* === C. SELECTED decode + single-encoder batched (all packets in one encoder) === */
        const uint64_t tC0 = mach_absolute_time();
        for (uint32_t r = 0; r < rounds; r++) {
            id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
            [cb beginCommandBufferWithAllocator:g_polar_allocator];
            id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
            id<MTL4ArgumentTable> at = ds4_mtl4_pool_acquire(8);
            if (!at) return 0;
            [enc setComputePipelineState:g_vqb2_decode_fp16_selected_mtl4_pipeline];
            for (uint32_t p = 0; p < n_packets; p++) {
                [at setAddress:selArgsBuf.gpuAddress atIndex:0];
                [at setAddress:cbBuf.gpuAddress atIndex:1];
                [at setAddress:codesBuf.gpuAddress + (uint64_t)p * codes_bytes_per_packet atIndex:2];
                [at setAddress:selBuf.gpuAddress atIndex:3];
                [at setAddress:selOutBuf.gpuAddress + (uint64_t)p * sel_out_per_packet atIndex:4];
                [enc setArgumentTable:at];
                const NSUInteger tg_x = (codes_per_expert + 63u) / 64u;
                [enc dispatchThreadgroups:MTLSizeMake(tg_x, n_selected, 1)
                    threadsPerThreadgroup:MTLSizeMake(64, 1, 1)];
            }
            [enc endEncoding];
            [cb endCommandBuffer];
            dispatch_semaphore_t sem = dispatch_semaphore_create(0);
            MTL4CommitOptions *opts = [MTL4CommitOptions new];
            [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) { (void)fb; dispatch_semaphore_signal(sem); }];
            id<MTL4CommandBuffer> bufs[1] = {cb};
            [g_polar_queue commit:bufs count:1 options:opts];
            dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 10LL * NSEC_PER_SEC));
            ds4_mtl4_pool_release(at, 8);
        }
        const uint64_t tC1 = mach_absolute_time();
        t_C_ms = (double)(tC1 - tC0) * (double)tb.numer / (double)tb.denom / 1e6;

        /* === D. SELECTED decode + SINGLE 3D-grid dispatch (OOM-speedup target) ===
         * One kernel invocation covers all n_packets via gid.z. Eliminates the
         * per-packet dispatch overhead the bench revealed dominates. */
        struct batched_args_t {
            uint32_t bit_width, code_mask, n_rows, n_pairs,
                     n_selected, n_packets, codes_stride, out_stride;
        } batched_args = {
            bit_width, (1u << bit_width) - 1u, n_rows, n_pairs,
            n_selected, n_packets,
            (uint32_t)codes_bytes_per_packet,
            (uint32_t)(sel_out_per_packet / sizeof(_Float16) / 2u),
        };
        id<MTLBuffer> batchedArgsBuf = [g_device newBufferWithBytes:&batched_args
                                                             length:sizeof(batched_args)
                                                            options:MTLResourceStorageModeShared];

        const uint64_t tD0 = mach_absolute_time();
        for (uint32_t r = 0; r < rounds; r++) {
            id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
            [cb beginCommandBufferWithAllocator:g_polar_allocator];
            id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
            id<MTL4ArgumentTable> at = ds4_mtl4_pool_acquire(8);
            if (!at) return 0;
            [at setAddress:batchedArgsBuf.gpuAddress atIndex:0];
            [at setAddress:cbBuf.gpuAddress atIndex:1];
            [at setAddress:codesBuf.gpuAddress atIndex:2];
            [at setAddress:selBuf.gpuAddress atIndex:3];
            [at setAddress:selOutBuf.gpuAddress atIndex:4];
            [enc setComputePipelineState:g_vqb2_decode_fp16_batched_mtl4_pipeline];
            [enc setArgumentTable:at];
            const NSUInteger tg_x = (codes_per_expert + 63u) / 64u;
            [enc dispatchThreadgroups:MTLSizeMake(tg_x, n_selected, n_packets)
                threadsPerThreadgroup:MTLSizeMake(64, 1, 1)];
            [enc endEncoding];
            [cb endCommandBuffer];
            dispatch_semaphore_t sem = dispatch_semaphore_create(0);
            MTL4CommitOptions *opts = [MTL4CommitOptions new];
            [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) { (void)fb; dispatch_semaphore_signal(sem); }];
            id<MTL4CommandBuffer> bufs[1] = {cb};
            [g_polar_queue commit:bufs count:1 options:opts];
            dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 10LL * NSEC_PER_SEC));
            ds4_mtl4_pool_release(at, 8);
        }
        const uint64_t tD1 = mach_absolute_time();
        double t_D_ms = (double)(tD1 - tD0) * (double)tb.numer / (double)tb.denom / 1e6;

        /* === E. SINGLE command buffer with ALL rounds packed inside (production-shape)
         * — many decodes share one commit + one wait. This is the regime real
         * inference operates in: tokens batch many kernels per command buffer.
         * Measures kernel throughput minus sync overhead. */
        const uint64_t tE0 = mach_absolute_time();
        {
            id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
            [cb beginCommandBufferWithAllocator:g_polar_allocator];
            id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
            id<MTL4ArgumentTable> at = ds4_mtl4_pool_acquire(8);
            if (at) {
                [at setAddress:batchedArgsBuf.gpuAddress atIndex:0];
                [at setAddress:cbBuf.gpuAddress atIndex:1];
                [at setAddress:codesBuf.gpuAddress atIndex:2];
                [at setAddress:selBuf.gpuAddress atIndex:3];
                [at setAddress:selOutBuf.gpuAddress atIndex:4];
                [enc setComputePipelineState:g_vqb2_decode_fp16_batched_mtl4_pipeline];
                [enc setArgumentTable:at];
                const NSUInteger tg_x = (codes_per_expert + 63u) / 64u;
                for (uint32_t r = 0; r < rounds; r++) {
                    [enc dispatchThreadgroups:MTLSizeMake(tg_x, n_selected, n_packets)
                        threadsPerThreadgroup:MTLSizeMake(64, 1, 1)];
                }
                [enc endEncoding];
                [cb endCommandBuffer];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) { (void)fb; dispatch_semaphore_signal(sem); }];
                id<MTL4CommandBuffer> bufs[1] = {cb};
                [g_polar_queue commit:bufs count:1 options:opts];
                dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 30LL * NSEC_PER_SEC));
                ds4_mtl4_pool_release(at, 8);
            }
        }
        const uint64_t tE1 = mach_absolute_time();
        double t_E_ms = (double)(tE1 - tE0) * (double)tb.numer / (double)tb.denom / 1e6;

        const uint64_t bytes_per_round =
            (uint64_t)n_packets * n_selected * n_rows * n_pairs * 2u * sizeof(_Float16);
        const double gbs_E = ((double)bytes_per_round * rounds / 1e9) / (t_E_ms / 1000.0);

        fprintf(stderr,
            "ds4: stacked_speedup_bench n_packets=%u n_sel=%u/%u rows=%u pairs=%u K=%u rounds=%u\n"
            "  A. full   + per-pkt encoder: %.3f ms (%.3f ms/round)\n"
            "  B. select + per-pkt encoder: %.3f ms (%.3f ms/round)  vs A = %.2fx (compute axis)\n"
            "  C. select + batched encoder: %.3f ms (%.3f ms/round)  vs B = %.2fx (encoder axis)\n"
            "  D. select + fused 3D grid:   %.3f ms (%.3f ms/round)  vs C = %.2fx (dispatch axis)\n"
            "  E. all rounds in 1 cmdbuf:   %.3f ms (%.3f ms/round)  vs D = %.2fx (sync axis)\n"
            "  combined E vs A = %.2fx   E throughput = %.1f GB/s output\n",
            n_packets, n_selected, n_experts_total, n_rows, n_pairs, k_val, rounds,
            t_A_ms, t_A_ms / (double)rounds,
            t_B_ms, t_B_ms / (double)rounds, t_A_ms / t_B_ms,
            t_C_ms, t_C_ms / (double)rounds, t_B_ms / t_C_ms,
            t_D_ms, t_D_ms / (double)rounds, t_C_ms / t_D_ms,
            t_E_ms, t_E_ms / (double)rounds, t_D_ms / t_E_ms,
            t_A_ms / t_E_ms, gbs_E);
        return 1;
    }
    return 0;
}

/* Standalone canary: provide a synthetic packet (codebook + codes), dispatch
 * decode, compare against ground-truth pair values. Returns 1 on success.
 *
 * Test setup:
 *   - K=16 codebook with code i → (i*0.1, -i*0.1) for clear visual signature
 *   - 256 codes pre-encoded with code = i % 16 (cycles 0..15)
 *   - bit_width = 4
 *   - Decode all 256 codes; verify out_fp16[i] == ((i%16)*0.1, -(i%16)*0.1) within fp16 epsilon. */
int ds4_gpu_mtl4_vqb2_decode_fp16_canary(uint32_t n_codes, uint32_t k_val) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_vqb2_decode_fp16_mtl4_pipeline_init()) return 0;
    if (n_codes == 0 || (k_val != 4 && k_val != 16 && k_val != 64 && k_val != 256)) {
        fprintf(stderr, "ds4: vqb2_decode_fp16 canary needs n_codes>0, k∈{4,16,64,256} (got %u, %u)\n",
                n_codes, k_val);
        return 0;
    }
    uint32_t bit_width;
    switch (k_val) {
        case 4:   bit_width = 2; break;
        case 16:  bit_width = 4; break;
        case 64:  bit_width = 6; break;
        case 256: bit_width = 8; break;
        default:  return 0;
    }
    /* Build codebook in [-1, +1] — matches real VQB2 centroid range, keeps
     * fp16 precision uniform across K∈{4,16,64,256}. */
    float *host_cb = (float *)calloc((size_t)k_val * 2u, sizeof(float));
    if (!host_cb) return 0;
    const float step = 1.0f / (float)k_val;
    for (uint32_t i = 0; i < k_val; i++) {
        host_cb[i * 2u + 0u] = (float)i * step;
        host_cb[i * 2u + 1u] = -(float)i * step;
    }
    /* Pack codes: code[i] = i % k */
    const size_t codes_bytes = (size_t)((uint64_t)n_codes * (uint64_t)bit_width + 7u) >> 3;
    uint8_t *host_codes = (uint8_t *)calloc(codes_bytes + 8u, 1);  /* +8 for safe LE 16-bit read */
    if (!host_codes) { free(host_cb); return 0; }
    for (uint32_t i = 0; i < n_codes; i++) {
        const uint32_t code = i % k_val;
        const uint32_t bit_off = i * bit_width;
        const uint32_t byte_off = bit_off >> 3;
        const uint32_t shift = bit_off & 7u;
        host_codes[byte_off]      |= (uint8_t)((code << shift) & 0xFFu);
        if (bit_width + shift > 8u) {
            host_codes[byte_off + 1u] |= (uint8_t)((code >> (8u - shift)) & 0xFFu);
        }
    }
    /* Run kernel */
    _Float16 *host_out = (_Float16 *)calloc((size_t)n_codes * 2u, sizeof(_Float16));
    if (!host_out) { free(host_cb); free(host_codes); return 0; }
    int rc = 0;
    @autoreleasepool {
        struct { uint32_t bit_width; uint32_t code_mask; uint32_t n_codes; uint32_t start_linear; }
            args = { bit_width, (1u << bit_width) - 1u, n_codes, 0 };
        id<MTLBuffer> argsBuf = [g_device newBufferWithBytes:&args length:sizeof(args) options:MTLResourceStorageModeShared];
        id<MTLBuffer> cbBuf   = [g_device newBufferWithBytes:host_cb length:(NSUInteger)k_val * 2u * sizeof(float) options:MTLResourceStorageModeShared];
        id<MTLBuffer> codesBuf= [g_device newBufferWithBytes:host_codes length:codes_bytes + 8u options:MTLResourceStorageModeShared];
        id<MTLBuffer> outBuf  = [g_device newBufferWithLength:(NSUInteger)n_codes * 2u * sizeof(_Float16) options:MTLResourceStorageModeShared];
        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 4;
        NSError *err = nil;
        id<MTLResidencySet> rs = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (rs) {
            id<MTLAllocation> allocs[4] = {(id)argsBuf, (id)cbBuf, (id)codesBuf, (id)outBuf};
            [rs addAllocations:allocs count:4];
            [rs commit];
            ds4_residency_request_checked(rs, __func__);
            id<MTL4ArgumentTable> at = ds4_mtl4_pool_acquire(8);
            if (at) {
                [at setAddress:argsBuf.gpuAddress atIndex:0];
                [at setAddress:cbBuf.gpuAddress atIndex:1];
                [at setAddress:codesBuf.gpuAddress atIndex:2];
                [at setAddress:outBuf.gpuAddress atIndex:3];
                id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
                [cb beginCommandBufferWithAllocator:g_polar_allocator];
                [cb useResidencySet:rs];
                id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
                [enc setComputePipelineState:g_vqb2_decode_fp16_mtl4_pipeline];
                [enc setArgumentTable:at];
                const NSUInteger tg = (n_codes + 63u) / 64u;
                [enc dispatchThreadgroups:MTLSizeMake(tg, 1, 1)
                    threadsPerThreadgroup:MTLSizeMake(64, 1, 1)];
                [enc endEncoding];
                [cb endCommandBuffer];
                [g_polar_queue addResidencySet:rs];
                dispatch_semaphore_t sem = dispatch_semaphore_create(0);
                MTL4CommitOptions *opts = [MTL4CommitOptions new];
                [opts addFeedbackHandler:^(id<MTL4CommitFeedback> fb) { (void)fb; dispatch_semaphore_signal(sem); }];
                id<MTL4CommandBuffer> bufs[1] = {cb};
                [g_polar_queue commit:bufs count:1 options:opts];
                long w = dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 10LL * NSEC_PER_SEC));
                [rs endResidency];
                if (w == 0) {
                    memcpy(host_out, outBuf.contents, (size_t)n_codes * 2u * sizeof(_Float16));
                    rc = 1;
                }
                ds4_mtl4_pool_release(at, 8);
            }
        }
    }
    /* Compare — tolerance scaled to fp16 precision (max value × ~5e-4). */
    int mismatch = 0;
    double max_err = 0.0;
    if (rc) {
        for (uint32_t i = 0; i < n_codes; i++) {
            const float exp_re = (float)(i % k_val) * step;
            const float exp_im = -(float)(i % k_val) * step;
            const float got_re = (float)host_out[i * 2u + 0u];
            const float got_im = (float)host_out[i * 2u + 1u];
            const double e = fmax(fabs((double)(got_re - exp_re)),
                                  fabs((double)(got_im - exp_im)));
            if (e > max_err) max_err = e;
            if (e > 1e-3) mismatch++;
        }
    }
    fprintf(stderr,
        "ds4: vqb2_decode_fp16 MTL4 canary n_codes=%u k=%u bw=%u mismatch=%d max_err=%.4e rc=%d "
        "out[0]=(%+.4f, %+.4f) out[%u]=(%+.4f, %+.4f)\n",
        n_codes, k_val, bit_width, mismatch, max_err, rc,
        (double)host_out[0], (double)host_out[1],
        n_codes - 1, (double)host_out[(n_codes - 1) * 2u + 0u],
        (double)host_out[(n_codes - 1) * 2u + 1u]);
    free(host_cb); free(host_codes); free(host_out);
    return (rc && mismatch == 0) ? 1 : 0;
}

/* ============================================================ */
/* H1729 tile×row×batch polar dot kernel                        */
/* ============================================================ */
/* Per codex H1729: real MoE execution unit = "resident expert-code tile +
 * streaming hidden states". Same MSL kernel shape as H1725 but the
 * dispatch is 3D (tile, row, batch) and the hidden vector is indexed by
 * (batch, tile) — SAME hidden vector reused across all rows of a tile.
 * That's the layout amortization: per-token hidden state fans out to all
 * the weight rows of one expert sub-block in a single dispatch.
 *
 * Measured (codex H1729 on M1 Max): b8 = 46.70 ns/output (1.45× over
 * per-packet H1725), b32 = 31.81× layout reduction. Best per-output at
 * b8; best layout amortization at b32.
 *
 * Self-test: ds4_gpu_mtl4_polar_tile_canary(tiles, rows, batches, pairs).
 * Synthetic deterministic input: mag=0, phase=4 (angle 0), level[0]=1,
 * hidden=1. Expected per output = pairs × 1.0.
 *
 * Codex artifact source:
 *   research/llm_fallacy_deconstruction/framework_deconstruction/
 *     h1729_mtl4_polar_tile32_batched_kernel_20260525.m
 */

static id<MTLComputePipelineState> g_polar_tile_pipeline;
static int g_polar_tile_init_attempted;
static int g_polar_tile_init_ok;

static int ds4_polar_tile_pipeline_init(void) {
    if (g_polar_tile_init_attempted) return g_polar_tile_init_ok;
    g_polar_tile_init_attempted = 1;

    if (!ds4_polar_pipeline_init()) return 0; /* reuse the compiler + queue + allocator */

    NSError *err = nil;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "kernel void polar_dot_tile(device const uchar* mag [[buffer(0)]],\n"
         "                            device const uchar* phase [[buffer(1)]],\n"
         "                            device const float* levels [[buffer(2)]],\n"
         "                            device const float* hidden [[buffer(3)]],\n"
         "                            device const float* cos_lut [[buffer(4)]],\n"
         "                            device const float* sin_lut [[buffer(5)]],\n"
         "                            device float* out [[buffer(6)]],\n"
         "                            device const uint* params [[buffer(7)]],\n"
         "                            uint3 tg [[threadgroup_position_in_grid]],\n"
         "                            uint tid [[thread_index_in_threadgroup]]) {\n"
         "  constexpr uint THREADS = 256;\n"
         "  threadgroup float partial[THREADS];\n"
         "  uint tile = tg.x;\n"
         "  uint row  = tg.y;\n"
         "  uint batch = tg.z;\n"
         "  uint pairs = params[0];\n"
         "  uint rows  = params[1];\n"
         "  uint tiles = params[2];\n"
         "  uint row_packet = tile * rows + row;\n"
         "  uint row_packets = tiles * rows;\n"
         "  uint code_base = row_packet * pairs;\n"
         "  uint hbase = (batch * tiles + tile) * pairs * 2;\n"
         "  float acc = 0.0f;\n"
         "  for (uint j = tid; j < pairs; j += THREADS) {\n"
         "    uint idx = code_base + j;\n"
         "    uchar mcode = mag[idx];\n"
         "    float qmag = levels[row_packet * 4 + uint(mcode)];\n"
         "    uint lut = uint(phase[idx]);\n"
         "    float x0 = qmag * cos_lut[lut];\n"
         "    float x1 = qmag * sin_lut[lut];\n"
         "    acc += x0 * hidden[hbase + 2*j] + x1 * hidden[hbase + 2*j + 1];\n"
         "  }\n"
         "  partial[tid] = acc;\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  for (uint stride = THREADS >> 1; stride > 0; stride >>= 1) {\n"
         "    if (tid < stride) partial[tid] += partial[tid + stride];\n"
         "    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  }\n"
         "  if (tid == 0) out[batch * row_packets + row_packet] = partial[0];\n"
         "}\n";

    MTL4LibraryDescriptor *libDesc = [MTL4LibraryDescriptor new];
    libDesc.source = source;
    libDesc.name = @"ds4_polar_dot_tile";
    id<MTLLibrary> lib = [g_polar_compiler newLibraryWithDescriptor:libDesc error:&err];
    if (!lib) {
        fprintf(stderr, "ds4: polar tile MTL4 library failed: %s\n",
                err ? err.localizedDescription.UTF8String : "(no error)");
        return 0;
    }
    MTL4LibraryFunctionDescriptor *fnDesc = [MTL4LibraryFunctionDescriptor new];
    fnDesc.library = lib;
    fnDesc.name = @"polar_dot_tile";
    MTL4ComputePipelineDescriptor *pipeDesc = [MTL4ComputePipelineDescriptor new];
    pipeDesc.computeFunctionDescriptor = fnDesc;
    pipeDesc.threadGroupSizeIsMultipleOfThreadExecutionWidth = YES;
    pipeDesc.maxTotalThreadsPerThreadgroup = 256;
    g_polar_tile_pipeline = [g_polar_compiler newComputePipelineStateWithDescriptor:pipeDesc
                                                                compilerTaskOptions:nil
                                                                              error:&err];
    if (!g_polar_tile_pipeline) {
        fprintf(stderr, "ds4: polar tile pipeline failed: %s\n",
                err ? err.localizedDescription.UTF8String : "(no error)");
        return 0;
    }
    g_polar_tile_init_ok = 1;
    return 1;
}

/* Same kernel as ds4_gpu_mtl4_polar_tile_canary, but loads buffers from
 * pre-encoded binary files produced by analyzers/polar_encode_safetensors.py.
 * Validates end-to-end against the Python reference in <prefix>.expected_polar.bin.
 *
 * Files read (sizes are tiles*rows*pairs for mag/phase, tiles*rows*4 for levels,
 * tiles*pairs*2 for hidden when batches=1):
 *   <prefix>.mag.bin        uint8
 *   <prefix>.phase.bin      uint8
 *   <prefix>.levels.bin     float32
 *   <prefix>.cos_lut.bin    9 float32
 *   <prefix>.sin_lut.bin    9 float32
 *   <prefix>.hidden.bin     float32 (size = batches * tiles * pairs * 2;
 *                                   encoder emits batches=n_tiles by default)
 *   <prefix>.expected_polar.bin  rows*tiles float32 (Python-computed reference)
 *
 * Returns 1 on success, 0 on failure. Reports max|GPU-Python_ref| difference. */
static long ds4_polar_read_file(const char *path, void *dst, size_t expected_bytes) {
    FILE *fp = fopen(path, "rb");
    if (!fp) { fprintf(stderr, "ds4: polar_tile_real: open %s failed\n", path); return -1; }
    long got = (long)fread(dst, 1, expected_bytes, fp);
    fclose(fp);
    if (got != (long)expected_bytes) {
        fprintf(stderr, "ds4: polar_tile_real: short read %s (%ld / %zu bytes)\n",
                path, got, expected_bytes);
        return -1;
    }
    return got;
}

int ds4_gpu_mtl4_polar_tile_real(const char *prefix,
                                  uint32_t tiles, uint32_t rows,
                                  uint32_t batches, uint32_t pairs) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_polar_tile_pipeline_init()) return 0;
    if (!prefix || tiles == 0 || rows == 0 || batches == 0 || pairs == 0) return 0;

    @autoreleasepool {
        NSError *err = nil;
        const NSUInteger row_packets = (NSUInteger)tiles * rows;
        const NSUInteger pair_count = row_packets * pairs;
        const NSUInteger hidden_count = (NSUInteger)batches * tiles * pairs * 2;
        const NSUInteger out_count = (NSUInteger)batches * row_packets;

        id<MTLBuffer> mag      = [g_device newBufferWithLength:pair_count                        options:MTLResourceStorageModeShared];
        id<MTLBuffer> phase    = [g_device newBufferWithLength:pair_count                        options:MTLResourceStorageModeShared];
        id<MTLBuffer> levels   = [g_device newBufferWithLength:row_packets * 4 * sizeof(float)   options:MTLResourceStorageModeShared];
        id<MTLBuffer> hidden   = [g_device newBufferWithLength:hidden_count * sizeof(float)      options:MTLResourceStorageModeShared];
        id<MTLBuffer> cosLut   = [g_device newBufferWithLength:9 * sizeof(float)                 options:MTLResourceStorageModeShared];
        id<MTLBuffer> sinLut   = [g_device newBufferWithLength:9 * sizeof(float)                 options:MTLResourceStorageModeShared];
        id<MTLBuffer> outBuf   = [g_device newBufferWithLength:out_count * sizeof(float)         options:MTLResourceStorageModeShared];
        id<MTLBuffer> paramsBuf= [g_device newBufferWithLength:3 * sizeof(uint32_t)              options:MTLResourceStorageModeShared];
        if (!mag || !phase || !levels || !hidden || !cosLut || !sinLut || !outBuf || !paramsBuf) return 0;

        char path[1024];
        snprintf(path, sizeof(path), "%s.mag.bin",   prefix); if (ds4_polar_read_file(path, mag.contents,    pair_count) < 0) return 0;
        snprintf(path, sizeof(path), "%s.phase.bin", prefix); if (ds4_polar_read_file(path, phase.contents,  pair_count) < 0) return 0;
        snprintf(path, sizeof(path), "%s.levels.bin",prefix); if (ds4_polar_read_file(path, levels.contents, row_packets * 4 * sizeof(float)) < 0) return 0;
        snprintf(path, sizeof(path), "%s.hidden.bin",prefix); if (ds4_polar_read_file(path, hidden.contents, hidden_count * sizeof(float)) < 0) return 0;
        snprintf(path, sizeof(path), "%s.cos_lut.bin", prefix); if (ds4_polar_read_file(path, cosLut.contents, 9 * sizeof(float)) < 0) return 0;
        snprintf(path, sizeof(path), "%s.sin_lut.bin", prefix); if (ds4_polar_read_file(path, sinLut.contents, 9 * sizeof(float)) < 0) return 0;

        uint32_t *params = (uint32_t *)paramsBuf.contents;
        params[0] = pairs; params[1] = rows; params[2] = tiles;

        /* Standard MTL4 dispatch — copied from the synthetic canary. */
        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 8;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (!residency) return 0;
        id<MTLAllocation> allocs[8] = {
            (id<MTLAllocation>)mag, (id<MTLAllocation>)phase,
            (id<MTLAllocation>)levels, (id<MTLAllocation>)hidden,
            (id<MTLAllocation>)cosLut, (id<MTLAllocation>)sinLut,
            (id<MTLAllocation>)outBuf, (id<MTLAllocation>)paramsBuf,
        };
        [residency addAllocations:allocs count:8];
        [residency commit];
        ds4_residency_request_checked(residency, __func__);

        MTL4ArgumentTableDescriptor *atDesc = [MTL4ArgumentTableDescriptor new];
        atDesc.maxBufferBindCount = 8;
        atDesc.initializeBindings = YES;
        id<MTL4ArgumentTable> argTable = [g_device newArgumentTableWithDescriptor:atDesc error:&err];
        if (!argTable) return 0;
        [argTable setAddress:mag.gpuAddress       atIndex:0];
        [argTable setAddress:phase.gpuAddress     atIndex:1];
        [argTable setAddress:levels.gpuAddress    atIndex:2];
        [argTable setAddress:hidden.gpuAddress    atIndex:3];
        [argTable setAddress:cosLut.gpuAddress    atIndex:4];
        [argTable setAddress:sinLut.gpuAddress    atIndex:5];
        [argTable setAddress:outBuf.gpuAddress    atIndex:6];
        [argTable setAddress:paramsBuf.gpuAddress atIndex:7];

        id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
        [cb beginCommandBufferWithAllocator:g_polar_allocator];
        [cb useResidencySet:residency];
        id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
        if (!enc) return 0;
        [enc setComputePipelineState:g_polar_tile_pipeline];
        [enc setArgumentTable:argTable];
        [enc dispatchThreadgroups:MTLSizeMake(tiles, rows, batches)
            threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        [enc endEncoding];
        [cb endCommandBuffer];

        [g_polar_queue addResidencySet:residency];
        dispatch_semaphore_t sem = dispatch_semaphore_create(0);
        __block CFTimeInterval gpuStart = 0.0, gpuEnd = 0.0;
        __block NSError *fbErr = nil;
        MTL4CommitOptions *opts = [MTL4CommitOptions new];
        [opts addFeedbackHandler:^(id<MTL4CommitFeedback> feedback) {
            fbErr = feedback.error;
            gpuStart = feedback.GPUStartTime; gpuEnd = feedback.GPUEndTime;
            dispatch_semaphore_signal(sem);
        }];
        id<MTL4CommandBuffer> bufs[1] = { cb };
        [g_polar_queue commit:bufs count:1 options:opts];
        long waitRes = dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 30LL * NSEC_PER_SEC));
        [residency endResidency];
        if (waitRes != 0) { fprintf(stderr, "ds4: polar_tile_real timeout\n"); return 0; }
        if (fbErr) { fprintf(stderr, "ds4: polar_tile_real feedback err: %s\n", fbErr.localizedDescription.UTF8String); return 0; }

        /* Compare GPU output to Python reference. */
        float *expected_polar = malloc(out_count * sizeof(float));
        snprintf(path, sizeof(path), "%s.expected_polar.bin", prefix);
        if (ds4_polar_read_file(path, expected_polar, out_count * sizeof(float)) < 0) {
            free(expected_polar);
            return 0;
        }

        float *outPtr = (float *)outBuf.contents;
        float maxAbsErr = 0.0f;
        double sumAbsErr = 0.0;
        for (NSUInteger i = 0; i < out_count; i++) {
            float diff = fabsf(outPtr[i] - expected_polar[i]);
            sumAbsErr += diff;
            if (diff > maxAbsErr) maxAbsErr = diff;
        }
        const double gpuMs = (gpuEnd - gpuStart) * 1000.0;
        fprintf(stderr,
                "ds4: polar TILE REAL prefix=%s tiles=%u rows=%u batches=%u pairs=%u\n"
                "  GPU out[0]=%.4f  Python ref[0]=%.4f  max|diff|=%.3e  mean|diff|=%.3e\n"
                "  gpu_elapsed=%.6f ms  (%.0f ns/output, resident=%.1f MB)\n",
                prefix, tiles, rows, batches, pairs,
                (double)outPtr[0], (double)expected_polar[0],
                (double)maxAbsErr, sumAbsErr / out_count,
                gpuMs, gpuMs * 1e6 / (double)out_count,
                (double)(pair_count * 2 + row_packets * 4 * 4 + hidden_count * 4 + out_count * 4) / 1e6);
        free(expected_polar);
        return maxAbsErr < 1e-2f ? 1 : 0; /* fp32-vs-Python tolerance — codex H1729 hit 7e-9 */
    }
}

/* ============================================================ */
/* H1733 fused gate*silu*up*route_weight kernel                 */
/* ============================================================ */
/* Per codex H1733: the real DS4 MLP organ is the fused
 *   silu(gate(hidden)) * up(hidden) * route_weight
 * computed in ONE dispatch over the routed expert subset.
 *
 * b32 measured by codex: 21.28 ns/equiv row-dot (2.20× over single
 * row-dots at b32, 1.77× lower allocation), max_abs vs CPU = 7.55e-9.
 *
 * Architectural pieces:
 *   - mag/phase: ALL unique code tiles concatenated (H1731 dedup)
 *   - levels:    per-row 4-level quantile table
 *   - gate_code[route_pair]: which code tile is the gate for this route pair
 *   - up_code[route_pair]:   same, for up
 *   - route_weight[route_pair]: per-route scalar from top-k selection
 *   - hidden[batch, route_pair]: per-(batch, route_pair) input vector
 *
 * Dispatch: (route_pairs, rows, batches) × 256 threads. Each threadgroup
 * computes both gate_dot AND up_dot for one (route_pair, row, batch),
 * sharing hidden reads. The final write applies silu+mul+route_weight.
 *
 * Self-test: ds4_gpu_mtl4_polar_fused_canary(...) — synthetic input where
 * mag=0/phase=4(angle 0)/level[0]=1/hidden=1 → gate_dot = up_dot = pairs.
 * silu(pairs) ≈ pairs (for pairs > 5), so output ≈ pairs * pairs * route_weight.
 *
 * Codex source:
 *   research/llm_fallacy_deconstruction/framework_deconstruction/
 *     h1733_mtl4_gate_up_fused_packet_kernel_20260525.m
 */

static id<MTLComputePipelineState> g_polar_fused_pipeline;
static int g_polar_fused_init_attempted;
static int g_polar_fused_init_ok;

static int ds4_polar_fused_pipeline_init(void) {
    if (g_polar_fused_init_attempted) return g_polar_fused_init_ok;
    g_polar_fused_init_attempted = 1;

    if (!ds4_polar_pipeline_init()) return 0; /* shared compiler + alloc + queue */

    NSError *err = nil;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "kernel void gate_up_packet(device const uchar* mag [[buffer(0)]],\n"
         "                            device const uchar* phase [[buffer(1)]],\n"
         "                            device const float* levels [[buffer(2)]],\n"
         "                            device const uint* gate_code [[buffer(3)]],\n"
         "                            device const uint* up_code [[buffer(4)]],\n"
         "                            device const float* route_weight [[buffer(5)]],\n"
         "                            device const float* hidden [[buffer(6)]],\n"
         "                            device const float* cos_lut [[buffer(7)]],\n"
         "                            device const float* sin_lut [[buffer(8)]],\n"
         "                            device float* out [[buffer(9)]],\n"
         "                            device const uint* params [[buffer(10)]],\n"
         "                            uint3 tg [[threadgroup_position_in_grid]],\n"
         "                            uint tid [[thread_index_in_threadgroup]]) {\n"
         "  constexpr uint THREADS = 256;\n"
         "  threadgroup float gate_partial[THREADS];\n"
         "  threadgroup float up_partial[THREADS];\n"
         "  uint route_pair = tg.x;\n"
         "  uint row = tg.y;\n"
         "  uint batch = tg.z;\n"
         "  uint pairs = params[0];\n"
         "  uint rows = params[1];\n"
         "  uint route_pairs = params[2];\n"
         "  uint gate_row = gate_code[route_pair] * rows + row;\n"
         "  uint up_row = up_code[route_pair] * rows + row;\n"
         "  uint gate_base = gate_row * pairs;\n"
         "  uint up_base = up_row * pairs;\n"
         "  uint hbase = (batch * route_pairs + route_pair) * pairs * 2;\n"
         "  float gate_acc = 0.0f;\n"
         "  float up_acc = 0.0f;\n"
         "  for (uint j = tid; j < pairs; j += THREADS) {\n"
         "    float h0 = hidden[hbase + 2*j];\n"
         "    float h1 = hidden[hbase + 2*j + 1];\n"
         "    uchar gate_m = mag[gate_base + j];\n"
         "    uint gate_l = uint(phase[gate_base + j]);\n"
         "    float gate_q = levels[gate_row * 4 + uint(gate_m)];\n"
         "    gate_acc += gate_q * cos_lut[gate_l] * h0 + gate_q * sin_lut[gate_l] * h1;\n"
         "    uchar up_m = mag[up_base + j];\n"
         "    uint up_l = uint(phase[up_base + j]);\n"
         "    float up_q = levels[up_row * 4 + uint(up_m)];\n"
         "    up_acc += up_q * cos_lut[up_l] * h0 + up_q * sin_lut[up_l] * h1;\n"
         "  }\n"
         "  gate_partial[tid] = gate_acc;\n"
         "  up_partial[tid] = up_acc;\n"
         "  threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  for (uint stride = THREADS >> 1; stride > 0; stride >>= 1) {\n"
         "    if (tid < stride) {\n"
         "      gate_partial[tid] += gate_partial[tid + stride];\n"
         "      up_partial[tid] += up_partial[tid + stride];\n"
         "    }\n"
         "    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  }\n"
         "  if (tid == 0) {\n"
         "    float g = gate_partial[0];\n"
         "    float u = up_partial[0];\n"
         "    float silu = g / (1.0f + exp(-g));\n"
         "    out[(batch * route_pairs + route_pair) * rows + row] = silu * u * route_weight[route_pair];\n"
         "  }\n"
         "}\n";

    MTL4LibraryDescriptor *libDesc = [MTL4LibraryDescriptor new];
    libDesc.source = source;
    libDesc.name = @"ds4_polar_gate_up_fused";
    id<MTLLibrary> lib = [g_polar_compiler newLibraryWithDescriptor:libDesc error:&err];
    if (!lib) {
        fprintf(stderr, "ds4: polar fused library failed: %s\n",
                err ? err.localizedDescription.UTF8String : "(no error)");
        return 0;
    }
    MTL4LibraryFunctionDescriptor *fnDesc = [MTL4LibraryFunctionDescriptor new];
    fnDesc.library = lib;
    fnDesc.name = @"gate_up_packet";
    MTL4ComputePipelineDescriptor *pipeDesc = [MTL4ComputePipelineDescriptor new];
    pipeDesc.computeFunctionDescriptor = fnDesc;
    pipeDesc.threadGroupSizeIsMultipleOfThreadExecutionWidth = YES;
    pipeDesc.maxTotalThreadsPerThreadgroup = 256;
    g_polar_fused_pipeline = [g_polar_compiler newComputePipelineStateWithDescriptor:pipeDesc
                                                                 compilerTaskOptions:nil
                                                                               error:&err];
    if (!g_polar_fused_pipeline) {
        fprintf(stderr, "ds4: polar fused pipeline failed: %s\n",
                err ? err.localizedDescription.UTF8String : "(no error)");
        return 0;
    }
    g_polar_fused_init_ok = 1;
    return 1;
}

/* Synthetic canary for the H1733 fused gate*silu*up*route_weight kernel.
 *
 * Layout: n_codes code tiles available, route_pairs pairs use them, each
 * pair picks one gate_code and one up_code, rows output rows per tile,
 * batches batches.
 *
 * Inputs are deterministic: mag=0 (code 0), phase=4 (angle 0 LUT entry),
 * level[0]=1.0, hidden=1.0, route_weight=1.0. With those:
 *   gate_dot = up_dot = pairs (since cos(0)=1, sum of pairs ones)
 *   silu(pairs) = pairs / (1 + exp(-pairs)) ≈ pairs (for pairs > 10)
 *   out = silu(pairs) * pairs * 1.0 ≈ pairs^2 - pairs*exp(-pairs)/(1+exp(-pairs))
 *
 * For pairs=2048, expected = 2048 * 2048 = 4194304 (exp(-2048) is sub-denormal).
 */
int ds4_gpu_mtl4_polar_fused_canary(uint32_t n_codes, uint32_t route_pairs,
                                     uint32_t rows, uint32_t batches, uint32_t pairs) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_polar_fused_pipeline_init()) return 0;
    if (n_codes == 0 || route_pairs == 0 || rows == 0 || batches == 0 || pairs == 0) return 0;

    @autoreleasepool {
        NSError *err = nil;
        const NSUInteger code_rows = (NSUInteger)n_codes * rows;
        const NSUInteger pair_count = code_rows * pairs;
        const NSUInteger hidden_count = (NSUInteger)batches * route_pairs * pairs * 2;
        const NSUInteger out_count = (NSUInteger)batches * route_pairs * rows;

        id<MTLBuffer> mag       = [g_device newBufferWithLength:pair_count                       options:MTLResourceStorageModeShared];
        id<MTLBuffer> phase     = [g_device newBufferWithLength:pair_count                       options:MTLResourceStorageModeShared];
        id<MTLBuffer> levels    = [g_device newBufferWithLength:code_rows * 4 * sizeof(float)    options:MTLResourceStorageModeShared];
        id<MTLBuffer> gateCode  = [g_device newBufferWithLength:route_pairs * sizeof(uint32_t)   options:MTLResourceStorageModeShared];
        id<MTLBuffer> upCode    = [g_device newBufferWithLength:route_pairs * sizeof(uint32_t)   options:MTLResourceStorageModeShared];
        id<MTLBuffer> routeW    = [g_device newBufferWithLength:route_pairs * sizeof(float)      options:MTLResourceStorageModeShared];
        id<MTLBuffer> hidden    = [g_device newBufferWithLength:hidden_count * sizeof(float)     options:MTLResourceStorageModeShared];
        id<MTLBuffer> cosLut    = [g_device newBufferWithLength:9 * sizeof(float)                options:MTLResourceStorageModeShared];
        id<MTLBuffer> sinLut    = [g_device newBufferWithLength:9 * sizeof(float)                options:MTLResourceStorageModeShared];
        id<MTLBuffer> outBuf    = [g_device newBufferWithLength:out_count * sizeof(float)        options:MTLResourceStorageModeShared];
        id<MTLBuffer> paramsBuf = [g_device newBufferWithLength:3 * sizeof(uint32_t)             options:MTLResourceStorageModeShared];
        if (!mag || !phase || !levels || !gateCode || !upCode || !routeW || !hidden || !cosLut || !sinLut || !outBuf || !paramsBuf) return 0;

        memset(mag.contents, 0, pair_count);
        memset(phase.contents, 4, pair_count);
        float *lvl = (float *)levels.contents;
        for (NSUInteger r = 0; r < code_rows; r++) {
            lvl[r * 4 + 0] = 1.0f; lvl[r * 4 + 1] = 0.5f;
            lvl[r * 4 + 2] = 0.25f; lvl[r * 4 + 3] = 0.125f;
        }
        uint32_t *gc = (uint32_t *)gateCode.contents;
        uint32_t *uc = (uint32_t *)upCode.contents;
        float *rw = (float *)routeW.contents;
        for (uint32_t r = 0; r < route_pairs; r++) {
            gc[r] = r % n_codes;
            uc[r] = (r + 1) % n_codes;
            rw[r] = 1.0f;
        }
        float *hid = (float *)hidden.contents;
        for (NSUInteger i = 0; i < hidden_count; i++) hid[i] = 1.0f;
        float *cosP = (float *)cosLut.contents;
        float *sinP = (float *)sinLut.contents;
        for (int code = -4; code <= 4; code++) {
            float angle = (float)code * 0.78539816339744830962f;
            cosP[code + 4] = cosf(angle);
            sinP[code + 4] = sinf(angle);
        }
        uint32_t *params = (uint32_t *)paramsBuf.contents;
        params[0] = pairs; params[1] = rows; params[2] = route_pairs;

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 11;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (!residency) return 0;
        id<MTLAllocation> allocs[11] = {
            (id<MTLAllocation>)mag, (id<MTLAllocation>)phase, (id<MTLAllocation>)levels,
            (id<MTLAllocation>)gateCode, (id<MTLAllocation>)upCode, (id<MTLAllocation>)routeW,
            (id<MTLAllocation>)hidden, (id<MTLAllocation>)cosLut, (id<MTLAllocation>)sinLut,
            (id<MTLAllocation>)outBuf, (id<MTLAllocation>)paramsBuf,
        };
        [residency addAllocations:allocs count:11];
        [residency commit];
        ds4_residency_request_checked(residency, __func__);

        MTL4ArgumentTableDescriptor *atDesc = [MTL4ArgumentTableDescriptor new];
        atDesc.maxBufferBindCount = 11;
        atDesc.initializeBindings = YES;
        id<MTL4ArgumentTable> argTable = [g_device newArgumentTableWithDescriptor:atDesc error:&err];
        if (!argTable) return 0;
        [argTable setAddress:mag.gpuAddress       atIndex:0];
        [argTable setAddress:phase.gpuAddress     atIndex:1];
        [argTable setAddress:levels.gpuAddress    atIndex:2];
        [argTable setAddress:gateCode.gpuAddress  atIndex:3];
        [argTable setAddress:upCode.gpuAddress    atIndex:4];
        [argTable setAddress:routeW.gpuAddress    atIndex:5];
        [argTable setAddress:hidden.gpuAddress    atIndex:6];
        [argTable setAddress:cosLut.gpuAddress    atIndex:7];
        [argTable setAddress:sinLut.gpuAddress    atIndex:8];
        [argTable setAddress:outBuf.gpuAddress    atIndex:9];
        [argTable setAddress:paramsBuf.gpuAddress atIndex:10];

        id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
        [cb beginCommandBufferWithAllocator:g_polar_allocator];
        [cb useResidencySet:residency];
        id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
        if (!enc) return 0;
        [enc setComputePipelineState:g_polar_fused_pipeline];
        [enc setArgumentTable:argTable];
        [enc dispatchThreadgroups:MTLSizeMake(route_pairs, rows, batches)
            threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        [enc endEncoding];
        [cb endCommandBuffer];

        [g_polar_queue addResidencySet:residency];
        dispatch_semaphore_t sem = dispatch_semaphore_create(0);
        __block CFTimeInterval gpuStart = 0.0, gpuEnd = 0.0;
        __block NSError *fbErr = nil;
        MTL4CommitOptions *opts = [MTL4CommitOptions new];
        [opts addFeedbackHandler:^(id<MTL4CommitFeedback> feedback) {
            fbErr = feedback.error;
            gpuStart = feedback.GPUStartTime; gpuEnd = feedback.GPUEndTime;
            dispatch_semaphore_signal(sem);
        }];
        id<MTL4CommandBuffer> bufs[1] = { cb };
        [g_polar_queue commit:bufs count:1 options:opts];
        long waitRes = dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 30LL * NSEC_PER_SEC));
        [residency endResidency];
        if (waitRes != 0) { fprintf(stderr, "ds4: polar fused canary timeout\n"); return 0; }
        if (fbErr) { fprintf(stderr, "ds4: polar fused feedback err: %s\n", fbErr.localizedDescription.UTF8String); return 0; }

        /* Expected: gate=up=pairs, silu(pairs)≈pairs, out ≈ pairs*pairs.
         * For pairs=2048: 2048*2048 = 4194304. */
        float *outPtr = (float *)outBuf.contents;
        float expected = (float)pairs * (float)pairs; /* silu(pairs) ≈ pairs */
        /* tighter expected: silu(p) = p / (1 + exp(-p)); for p=2048 exp(-p) underflows */
        float gate = (float)pairs, silu = gate / (1.0f + expf(-gate));
        expected = silu * (float)pairs * 1.0f;
        float maxAbsErr = 0.0f;
        double sumAbsErr = 0.0;
        for (NSUInteger i = 0; i < out_count; i++) {
            float diff = fabsf(outPtr[i] - expected);
            sumAbsErr += diff;
            if (diff > maxAbsErr) maxAbsErr = diff;
        }
        const double gpuMs = (gpuEnd - gpuStart) * 1000.0;
        fprintf(stderr,
                "ds4: polar FUSED canary n_codes=%u route_pairs=%u rows=%u batches=%u pairs=%u\n"
                "  expected=%.3f out[0]=%.3f max_abs_err=%.3e mean_abs_err=%.3e\n"
                "  gpu_elapsed=%.6f ms (%.0f ns/output, %.0f ns/row-dot-equiv, resident=%.1f MB)\n",
                n_codes, route_pairs, rows, batches, pairs,
                (double)expected, (double)outPtr[0],
                (double)maxAbsErr, sumAbsErr / out_count,
                gpuMs,
                gpuMs * 1e6 / (double)out_count,
                gpuMs * 1e6 / (double)(out_count * 2), /* 2 dots per output */
                (double)(pair_count * 2 + code_rows * 4 * 4 + route_pairs * 4 * 2 + route_pairs * 4 + hidden_count * 4 + out_count * 4) / 1e6);
        /* Relative tolerance — output magnitudes can be huge (pairs^2) */
        float relErr = maxAbsErr / fabsf(expected);
        return relErr < 1e-3f ? 1 : 0;
    }
}

/* ============================================================ */
/* H1735 fused gate*silu*up*route_weight + down projection      */
/* ============================================================ */
/* Per codex H1735: adds down-projection on top of H1733's fused
 * gate/up packet. One threadgroup per (route_pair, batch) computes:
 *   1. For each act_row r ∈ [0, act_rows):
 *        gate_dot = polar_dot(gate_code[route_pair], r, hidden[batch,rp])
 *        up_dot   = polar_dot(up_code[route_pair],   r, hidden[batch,rp])
 *        act[r]   = silu(gate_dot) * up_dot * route_weight[route_pair]
 *   2. For tid < down_rows:
 *        out[batch, route_pair, tid] = sum_k act[k] * down[route_pair, tid, k]
 *
 * Codex measured at b8 16×8 (act_rows=16, down_rows=8): 22.31 ns/equiv
 * row-dot per H1736 tile sweep. b32 32×64 hits 21.03 ns. H1737 refuted
 * two-stage materialization; KEEP monolithic tiled fusion.
 *
 * Tile policy (from H1738 per-token measured table):
 *   b8  latency/memory  -> 8×8
 *   b8  gate-up throughput -> 16×8 (22.31 ns)
 *   b8  down/balanced -> 8×64
 *   b32 latency/memory -> 16×8
 *   b32 gate-up/down/balanced -> 32×64 (21.03 ns)
 *
 * Synthetic canary (this entry point): mag=0, phase=4, level[0]=1,
 * hidden=1, gate_code=r%n, up_code=(r+1)%n, route_weight=1,
 * down=1/act_rows. Then:
 *   gate_dot = up_dot = pairs   (cos(0)*1*pairs)
 *   silu(pairs) ≈ pairs         (pairs >> 1)
 *   act[r] = pairs² for all r
 *   out[i] = sum_r act[r] * (1/act_rows) = pairs² * act_rows/act_rows = pairs²
 *
 * So expected output is identical to the fused canary: pairs². Same
 * 1e-3 relative tolerance.
 *
 * Codex source:
 *   research/llm_fallacy_deconstruction/framework_deconstruction/
 *     h1735_mtl4_gate_up_down_partial_kernel_20260525.m  (kernel + dispatch)
 *     h1735_ds4_mtl4_gate_up_down_partial_harness_20260525.py (real data harness)
 */

static id<MTLComputePipelineState> g_polar_gud_pipeline;
static int g_polar_gud_init_attempted;
static int g_polar_gud_init_ok;

static int ds4_polar_gud_pipeline_init(void) {
    if (g_polar_gud_init_attempted) return g_polar_gud_init_ok;
    g_polar_gud_init_attempted = 1;
    if (!ds4_polar_pipeline_init()) return 0; /* shared compiler + allocator + queue */

    NSError *err = nil;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "kernel void gate_up_down_partial(device const uchar* mag [[buffer(0)]],\n"
         "                                  device const uchar* phase [[buffer(1)]],\n"
         "                                  device const float* levels [[buffer(2)]],\n"
         "                                  device const uint* gate_code [[buffer(3)]],\n"
         "                                  device const uint* up_code [[buffer(4)]],\n"
         "                                  device const float* route_weight [[buffer(5)]],\n"
         "                                  device const float* hidden [[buffer(6)]],\n"
         "                                  device const float* down [[buffer(7)]],\n"
         "                                  device const float* cos_lut [[buffer(8)]],\n"
         "                                  device const float* sin_lut [[buffer(9)]],\n"
         "                                  device float* out [[buffer(10)]],\n"
         "                                  device const uint* params [[buffer(11)]],\n"
         "                                  uint2 tg [[threadgroup_position_in_grid]],\n"
         "                                  uint tid [[thread_index_in_threadgroup]]) {\n"
         "  constexpr uint THREADS = 256;\n"
         "  constexpr uint MAX_ACT = 64;\n"
         "  threadgroup float gate_partial[THREADS];\n"
         "  threadgroup float up_partial[THREADS];\n"
         "  threadgroup float act[MAX_ACT];\n"
         "  uint route_pair = tg.x;\n"
         "  uint batch = tg.y;\n"
         "  uint pairs = params[0];\n"
         "  uint rows = params[1];\n"
         "  uint route_pairs = params[2];\n"
         "  uint down_rows = params[3];\n"
         "  uint act_rows = params[4];\n"
         "  uint mag_levels = params[5];\n"  /* H1735+m8: parameterized magnitude codebook size */
         "  uint hbase = (batch * route_pairs + route_pair) * pairs * 2;\n"
         "  for (uint row = 0; row < act_rows; row++) {\n"
         "    uint gate_row = gate_code[route_pair] * rows + row;\n"
         "    uint up_row = up_code[route_pair] * rows + row;\n"
         "    uint gate_base = gate_row * pairs;\n"
         "    uint up_base = up_row * pairs;\n"
         "    float gate_acc = 0.0f;\n"
         "    float up_acc = 0.0f;\n"
         "    for (uint j = tid; j < pairs; j += THREADS) {\n"
         "      float h0 = hidden[hbase + 2*j];\n"
         "      float h1 = hidden[hbase + 2*j + 1];\n"
         "      uchar gate_m = mag[gate_base + j];\n"
         "      uint gate_l = uint(phase[gate_base + j]);\n"
         "      float gate_q = levels[gate_row * mag_levels + uint(gate_m)];\n"
         "      gate_acc += gate_q * cos_lut[gate_l] * h0 + gate_q * sin_lut[gate_l] * h1;\n"
         "      uchar up_m = mag[up_base + j];\n"
         "      uint up_l = uint(phase[up_base + j]);\n"
         "      float up_q = levels[up_row * mag_levels + uint(up_m)];\n"
         "      up_acc += up_q * cos_lut[up_l] * h0 + up_q * sin_lut[up_l] * h1;\n"
         "    }\n"
         "    gate_partial[tid] = gate_acc;\n"
         "    up_partial[tid] = up_acc;\n"
         "    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "    for (uint stride = THREADS >> 1; stride > 0; stride >>= 1) {\n"
         "      if (tid < stride) {\n"
         "        gate_partial[tid] += gate_partial[tid + stride];\n"
         "        up_partial[tid] += up_partial[tid + stride];\n"
         "      }\n"
         "      threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "    }\n"
         "    if (tid == 0) {\n"
         "      float g = gate_partial[0];\n"
         "      float u = up_partial[0];\n"
         "      act[row] = (g / (1.0f + exp(-g))) * u * route_weight[route_pair];\n"
         "    }\n"
         "    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  }\n"
         "  if (tid < down_rows) {\n"
         "    float acc = 0.0f;\n"
         "    uint down_base = (route_pair * down_rows + tid) * act_rows;\n"
         "    for (uint k = 0; k < act_rows; k++) acc += act[k] * down[down_base + k];\n"
         "    out[(batch * route_pairs + route_pair) * down_rows + tid] = acc;\n"
         "  }\n"
         "}\n";

    MTL4LibraryDescriptor *libDesc = [MTL4LibraryDescriptor new];
    libDesc.source = source;
    libDesc.name = @"ds4_polar_gate_up_down";
    id<MTLLibrary> lib = [g_polar_compiler newLibraryWithDescriptor:libDesc error:&err];
    if (!lib) {
        fprintf(stderr, "ds4: polar gud library failed: %s\n",
                err ? err.localizedDescription.UTF8String : "(no error)");
        return 0;
    }
    MTL4LibraryFunctionDescriptor *fnDesc = [MTL4LibraryFunctionDescriptor new];
    fnDesc.library = lib;
    fnDesc.name = @"gate_up_down_partial";
    MTL4ComputePipelineDescriptor *pipeDesc = [MTL4ComputePipelineDescriptor new];
    pipeDesc.computeFunctionDescriptor = fnDesc;
    pipeDesc.threadGroupSizeIsMultipleOfThreadExecutionWidth = YES;
    pipeDesc.maxTotalThreadsPerThreadgroup = 256;
    g_polar_gud_pipeline = [g_polar_compiler newComputePipelineStateWithDescriptor:pipeDesc
                                                                compilerTaskOptions:nil
                                                                              error:&err];
    if (!g_polar_gud_pipeline) {
        fprintf(stderr, "ds4: polar gud pipeline failed: %s\n",
                err ? err.localizedDescription.UTF8String : "(no error)");
        return 0;
    }
    g_polar_gud_init_ok = 1;
    return 1;
}

int ds4_gpu_mtl4_polar_gate_up_down_canary(uint32_t n_codes, uint32_t route_pairs,
                                            uint32_t rows, uint32_t batches, uint32_t pairs,
                                            uint32_t down_rows, uint32_t act_rows) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_polar_gud_pipeline_init()) return 0;
    if (n_codes == 0 || route_pairs == 0 || rows == 0 || batches == 0 ||
        pairs == 0 || down_rows == 0 || act_rows == 0) return 0;
    if (act_rows > 64) {
        fprintf(stderr, "ds4: polar gud canary act_rows=%u exceeds MAX_ACT=64\n", act_rows);
        return 0;
    }
    if (act_rows > rows) {
        fprintf(stderr, "ds4: polar gud canary act_rows=%u > rows=%u (must fit per-tile)\n", act_rows, rows);
        return 0;
    }
    if (down_rows > 256) {
        fprintf(stderr, "ds4: polar gud canary down_rows=%u exceeds THREADS=256\n", down_rows);
        return 0;
    }

    @autoreleasepool {
        NSError *err = nil;
        const NSUInteger code_rows = (NSUInteger)n_codes * rows;
        const NSUInteger pair_count = code_rows * pairs;
        const NSUInteger hidden_count = (NSUInteger)batches * route_pairs * pairs * 2;
        const NSUInteger down_count = (NSUInteger)route_pairs * down_rows * act_rows;
        const NSUInteger out_count = (NSUInteger)batches * route_pairs * down_rows;

        id<MTLBuffer> mag       = [g_device newBufferWithLength:pair_count                       options:MTLResourceStorageModeShared];
        id<MTLBuffer> phase     = [g_device newBufferWithLength:pair_count                       options:MTLResourceStorageModeShared];
        id<MTLBuffer> levels    = [g_device newBufferWithLength:code_rows * 4 * sizeof(float)    options:MTLResourceStorageModeShared];
        id<MTLBuffer> gateCode  = [g_device newBufferWithLength:route_pairs * sizeof(uint32_t)   options:MTLResourceStorageModeShared];
        id<MTLBuffer> upCode    = [g_device newBufferWithLength:route_pairs * sizeof(uint32_t)   options:MTLResourceStorageModeShared];
        id<MTLBuffer> routeW    = [g_device newBufferWithLength:route_pairs * sizeof(float)      options:MTLResourceStorageModeShared];
        id<MTLBuffer> hidden    = [g_device newBufferWithLength:hidden_count * sizeof(float)     options:MTLResourceStorageModeShared];
        id<MTLBuffer> downBuf   = [g_device newBufferWithLength:down_count * sizeof(float)       options:MTLResourceStorageModeShared];
        id<MTLBuffer> cosLut    = [g_device newBufferWithLength:9 * sizeof(float)                options:MTLResourceStorageModeShared];
        id<MTLBuffer> sinLut    = [g_device newBufferWithLength:9 * sizeof(float)                options:MTLResourceStorageModeShared];
        id<MTLBuffer> outBuf    = [g_device newBufferWithLength:out_count * sizeof(float)        options:MTLResourceStorageModeShared];
        id<MTLBuffer> paramsBuf = [g_device newBufferWithLength:6 * sizeof(uint32_t)             options:MTLResourceStorageModeShared];
        if (!mag || !phase || !levels || !gateCode || !upCode || !routeW || !hidden ||
            !downBuf || !cosLut || !sinLut || !outBuf || !paramsBuf) return 0;

        memset(mag.contents, 0, pair_count);
        memset(phase.contents, 4, pair_count);
        float *lvl = (float *)levels.contents;
        for (NSUInteger r = 0; r < code_rows; r++) {
            lvl[r * 4 + 0] = 1.0f; lvl[r * 4 + 1] = 0.5f;
            lvl[r * 4 + 2] = 0.25f; lvl[r * 4 + 3] = 0.125f;
        }
        uint32_t *gc = (uint32_t *)gateCode.contents;
        uint32_t *uc = (uint32_t *)upCode.contents;
        float *rw = (float *)routeW.contents;
        for (uint32_t r = 0; r < route_pairs; r++) {
            gc[r] = r % n_codes;
            uc[r] = (r + 1) % n_codes;
            rw[r] = 1.0f;
        }
        float *hid = (float *)hidden.contents;
        for (NSUInteger i = 0; i < hidden_count; i++) hid[i] = 1.0f;
        /* down = 1.0 / act_rows uniformly. Sum of act_rows terms × pairs² × (1/act_rows) = pairs². */
        float *dwn = (float *)downBuf.contents;
        const float down_val = 1.0f / (float)act_rows;
        for (NSUInteger i = 0; i < down_count; i++) dwn[i] = down_val;
        float *cosP = (float *)cosLut.contents;
        float *sinP = (float *)sinLut.contents;
        for (int code = -4; code <= 4; code++) {
            float angle = (float)code * 0.78539816339744830962f;
            cosP[code + 4] = cosf(angle);
            sinP[code + 4] = sinf(angle);
        }
        uint32_t *params = (uint32_t *)paramsBuf.contents;
        params[0] = pairs; params[1] = rows; params[2] = route_pairs;
        params[3] = down_rows; params[4] = act_rows;
        params[5] = 4;  /* synthetic canary uses m4 codebook */

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 12;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (!residency) return 0;
        id<MTLAllocation> allocs[12] = {
            (id<MTLAllocation>)mag, (id<MTLAllocation>)phase, (id<MTLAllocation>)levels,
            (id<MTLAllocation>)gateCode, (id<MTLAllocation>)upCode, (id<MTLAllocation>)routeW,
            (id<MTLAllocation>)hidden, (id<MTLAllocation>)downBuf,
            (id<MTLAllocation>)cosLut, (id<MTLAllocation>)sinLut,
            (id<MTLAllocation>)outBuf, (id<MTLAllocation>)paramsBuf,
        };
        [residency addAllocations:allocs count:12];
        [residency commit];
        ds4_residency_request_checked(residency, __func__);

        MTL4ArgumentTableDescriptor *atDesc = [MTL4ArgumentTableDescriptor new];
        atDesc.maxBufferBindCount = 12;
        atDesc.initializeBindings = YES;
        id<MTL4ArgumentTable> argTable = [g_device newArgumentTableWithDescriptor:atDesc error:&err];
        if (!argTable) return 0;
        [argTable setAddress:mag.gpuAddress       atIndex:0];
        [argTable setAddress:phase.gpuAddress     atIndex:1];
        [argTable setAddress:levels.gpuAddress    atIndex:2];
        [argTable setAddress:gateCode.gpuAddress  atIndex:3];
        [argTable setAddress:upCode.gpuAddress    atIndex:4];
        [argTable setAddress:routeW.gpuAddress    atIndex:5];
        [argTable setAddress:hidden.gpuAddress    atIndex:6];
        [argTable setAddress:downBuf.gpuAddress   atIndex:7];
        [argTable setAddress:cosLut.gpuAddress    atIndex:8];
        [argTable setAddress:sinLut.gpuAddress    atIndex:9];
        [argTable setAddress:outBuf.gpuAddress    atIndex:10];
        [argTable setAddress:paramsBuf.gpuAddress atIndex:11];

        id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
        [cb beginCommandBufferWithAllocator:g_polar_allocator];
        [cb useResidencySet:residency];
        id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
        if (!enc) return 0;
        [enc setComputePipelineState:g_polar_gud_pipeline];
        [enc setArgumentTable:argTable];
        /* H1735 grid: 2D (route_pairs, batches) — NOT 3D like H1733. */
        [enc dispatchThreadgroups:MTLSizeMake(route_pairs, batches, 1)
            threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        [enc endEncoding];
        [cb endCommandBuffer];

        [g_polar_queue addResidencySet:residency];
        dispatch_semaphore_t sem = dispatch_semaphore_create(0);
        __block CFTimeInterval gpuStart = 0.0, gpuEnd = 0.0;
        __block NSError *fbErr = nil;
        MTL4CommitOptions *opts = [MTL4CommitOptions new];
        [opts addFeedbackHandler:^(id<MTL4CommitFeedback> feedback) {
            fbErr = feedback.error;
            gpuStart = feedback.GPUStartTime; gpuEnd = feedback.GPUEndTime;
            dispatch_semaphore_signal(sem);
        }];
        id<MTL4CommandBuffer> bufs[1] = { cb };
        [g_polar_queue commit:bufs count:1 options:opts];
        long waitRes = dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 30LL * NSEC_PER_SEC));
        [residency endResidency];
        if (waitRes != 0) { fprintf(stderr, "ds4: polar gud canary timeout\n"); return 0; }
        if (fbErr) { fprintf(stderr, "ds4: polar gud feedback err: %s\n", fbErr.localizedDescription.UTF8String); return 0; }

        /* Expected: gate=up=pairs, silu(pairs)≈pairs, act=pairs², down=1/act_rows uniform,
         * out = sum_k act × down = act_rows × pairs² × (1/act_rows) = pairs². */
        float *outPtr = (float *)outBuf.contents;
        const float gate = (float)pairs;
        const float silu = gate / (1.0f + expf(-gate));
        const float act = silu * (float)pairs * 1.0f;
        const float expected = act; /* sum_k act × (1/act_rows) × act_rows = act = pairs² */
        float maxAbsErr = 0.0f;
        double sumAbsErr = 0.0;
        for (NSUInteger i = 0; i < out_count; i++) {
            float diff = fabsf(outPtr[i] - expected);
            sumAbsErr += diff;
            if (diff > maxAbsErr) maxAbsErr = diff;
        }
        const double gpuMs = (gpuEnd - gpuStart) * 1000.0;
        /* gate-up equivalent row-dot count: 2 × act_rows per (batch, route_pair).
         * down equivalent: act_rows MACs per output, down_rows outputs per (batch, route_pair). */
        const NSUInteger gate_up_dots = (NSUInteger)batches * route_pairs * act_rows * 2;
        const double bytes = (double)(pair_count * 2 + code_rows * 4 * 4 +
                                       route_pairs * (4 * 2 + 4) +
                                       hidden_count * 4 + down_count * 4 +
                                       out_count * 4);
        fprintf(stderr,
                "ds4: polar GUD canary n_codes=%u route_pairs=%u rows=%u batches=%u pairs=%u down_rows=%u act_rows=%u\n"
                "  expected=%.3f out[0]=%.3f max_abs_err=%.3e mean_abs_err=%.3e\n"
                "  gpu_elapsed=%.6f ms (%.1f ns/output, %.1f ns/equiv-gate-up-row-dot, resident=%.1f MB)\n",
                n_codes, route_pairs, rows, batches, pairs, down_rows, act_rows,
                (double)expected, (double)outPtr[0],
                (double)maxAbsErr, sumAbsErr / out_count,
                gpuMs,
                gpuMs * 1e6 / (double)out_count,
                gpuMs * 1e6 / (double)gate_up_dots,
                bytes / 1e6);
        float relErr = maxAbsErr / fabsf(expected);
        return relErr < 1e-3f ? 1 : 0;
    }
}

/* ============================================================ */
/* #563 Phase B-2.2 real-data H1735 canary                       */
/* ============================================================ */
/* Bridges the PLR2 polar file format to the H1735 GPU kernel. Loads real
 * DS4 V4 expert weights from a directory of L{LL}_{kind}.polar files,
 * copies expert <expert>'s rows into MTL buffers, dispatches the kernel
 * with synthetic hidden=1, route_weight=1, down=1/act_rows, and compares
 * the GPU output to a CPU reference derived from ds4_polar_decode_pair_re/im.
 *
 * Verifies that the PLR2 byte format matches what the kernel reads. If byte
 * alignment, stride arithmetic, or LUT indexing diverged between encoder
 * (polar_encode_mlx.py) and decoder (H1735 MSL kernel), this canary catches
 * it BEFORE we touch the inference hot path in Phase B-2.3.
 *
 * Output cross-check: with hidden=h0=h1=1 the kernel's per-pair accumulator
 * is `qmag*cos*1 + qmag*sin*1 = re_decoded + im_decoded`. Summing over all
 * pairs of one row gives the dot product the kernel computes. We do this on
 * CPU for the FIRST `act_rows` of the FIRST expert in the pool's code slot,
 * apply silu, multiply, sum × (1/act_rows). Expected = act = silu(dot)*dot. */
int ds4_gpu_mtl4_polar_real_canary(const char *polar_dir,
                                    uint32_t layer, uint32_t expert,
                                    uint32_t down_rows, uint32_t act_rows) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_polar_gud_pipeline_init()) return 0;
    if (!polar_dir || !polar_dir[0]) return 0;
    if (down_rows == 0 || act_rows == 0 || down_rows > 256 || act_rows > 64) return 0;

    ds4_polar_pool pool;
    ds4_polar_pool_init(&pool);
    uint32_t opened = ds4_polar_pool_load_dir(&pool, polar_dir);
    if (opened == 0) {
        fprintf(stderr, "ds4: polar real canary — no PLR2 files in %s\n", polar_dir);
        ds4_polar_pool_close(&pool);
        return 0;
    }

    const ds4_polar_file *gate_file = ds4_polar_pool_get(&pool, layer, DS4_POLAR_KIND_GATE);
    const ds4_polar_file *up_file   = ds4_polar_pool_get(&pool, layer, DS4_POLAR_KIND_UP);
    if (!gate_file || !up_file) {
        fprintf(stderr, "ds4: polar real canary — layer %u missing gate/up in pool\n", layer);
        ds4_polar_pool_close(&pool);
        return 0;
    }
    if (expert >= gate_file->n_experts || expert >= up_file->n_experts) {
        fprintf(stderr, "ds4: polar real canary — expert %u OOR (gate/up have %u experts)\n",
                expert, gate_file->n_experts);
        ds4_polar_pool_close(&pool);
        return 0;
    }
    if (act_rows > gate_file->n_rows || act_rows > up_file->n_rows) {
        fprintf(stderr, "ds4: polar real canary — act_rows %u > available rows %u\n",
                act_rows, gate_file->n_rows);
        ds4_polar_pool_close(&pool);
        return 0;
    }

    /* Phase B-2.3a (D1 path): optionally validate polar-DOWN → fp32 → H1735
     * end-to-end on real DS4 V4 weights. Gated by env var DS4_POLAR_REAL_DOWN=1
     * so the original synthetic-uniform-down test path is preserved by default.
     *
     * Polar-down storage: row d ∈ [0, n_rows) carries n_pairs complex pairs
     * encoding (re_0, im_0, re_1, im_1, …, re_{n_pairs-1}, im_{n_pairs-1}) →
     * 2 × n_pairs real values per row. We need down_rows × act_rows reals
     * here, so require down_rows ≤ down_file->n_rows AND act_rows ≤ 2 × n_pairs. */
    const char *env_polar_real_down = getenv("DS4_POLAR_REAL_DOWN");
    const int use_polar_down = (env_polar_real_down && env_polar_real_down[0] == '1') ? 1 : 0;
    const ds4_polar_file *down_file = NULL;
    if (use_polar_down) {
        down_file = ds4_polar_pool_get(&pool, layer, DS4_POLAR_KIND_DOWN);
        if (!down_file) {
            fprintf(stderr, "ds4: polar real canary — DS4_POLAR_REAL_DOWN=1 but no down PLR2 for layer %u; falling back to synthetic\n",
                    layer);
        } else if (expert >= down_file->n_experts) {
            fprintf(stderr, "ds4: polar real canary — down expert %u OOR (down has %u experts); falling back to synthetic\n",
                    expert, down_file->n_experts);
            down_file = NULL;
        } else if (down_rows > down_file->n_rows) {
            fprintf(stderr, "ds4: polar real canary — down_rows %u > down n_rows %u; falling back to synthetic\n",
                    down_rows, down_file->n_rows);
            down_file = NULL;
        } else if (act_rows > down_file->n_pairs * 2u) {
            fprintf(stderr, "ds4: polar real canary — act_rows %u > down 2×n_pairs %u; falling back to synthetic\n",
                    act_rows, down_file->n_pairs * 2u);
            down_file = NULL;
        }
    }

    const uint32_t rows   = gate_file->n_rows;
    const uint32_t pairs  = gate_file->n_pairs;
    const uint32_t n_codes = 1;        /* single tile pool: just this expert */
    const uint32_t route_pairs = 1;    /* single route */
    const uint32_t batches = 1;

    @autoreleasepool {
        NSError *err = nil;
        const NSUInteger code_rows = (NSUInteger)n_codes * rows;
        const NSUInteger pair_count = code_rows * pairs;
        const NSUInteger hidden_count = (NSUInteger)batches * route_pairs * pairs * 2;
        const NSUInteger down_count = (NSUInteger)route_pairs * down_rows * act_rows;
        const NSUInteger out_count = (NSUInteger)batches * route_pairs * down_rows;

        /* LUT sizes depend on file's phase_levels (legacy=8 → 9 entries; new
         * p16 → 17 entries; ... up to p+1). H1735 kernel reads
         * cos_lut[phase_code] where phase_code ∈ [0, phase_levels], so
         * buffer must be at least (phase_levels + 1) floats. */
        const uint32_t phase_levels = gate_file->phase_levels;
        const uint32_t mag_levels   = gate_file->mag_levels;
        const NSUInteger lut_entries = (NSUInteger)phase_levels + 1u;
        const NSUInteger levels_bytes_per_expert = (NSUInteger)rows * mag_levels * sizeof(float);

        id<MTLBuffer> mag       = [g_device newBufferWithLength:pair_count                                       options:MTLResourceStorageModeShared];
        id<MTLBuffer> phase     = [g_device newBufferWithLength:pair_count                                       options:MTLResourceStorageModeShared];
        id<MTLBuffer> levels    = [g_device newBufferWithLength:code_rows * mag_levels * sizeof(float)           options:MTLResourceStorageModeShared];
        id<MTLBuffer> gateCode  = [g_device newBufferWithLength:route_pairs * sizeof(uint32_t)                   options:MTLResourceStorageModeShared];
        id<MTLBuffer> upCode    = [g_device newBufferWithLength:route_pairs * sizeof(uint32_t)                   options:MTLResourceStorageModeShared];
        id<MTLBuffer> routeW    = [g_device newBufferWithLength:route_pairs * sizeof(float)                      options:MTLResourceStorageModeShared];
        id<MTLBuffer> hidden    = [g_device newBufferWithLength:hidden_count * sizeof(float)                     options:MTLResourceStorageModeShared];
        id<MTLBuffer> downBuf   = [g_device newBufferWithLength:down_count * sizeof(float)                       options:MTLResourceStorageModeShared];
        id<MTLBuffer> cosLut    = [g_device newBufferWithLength:lut_entries * sizeof(float)                      options:MTLResourceStorageModeShared];
        id<MTLBuffer> sinLut    = [g_device newBufferWithLength:lut_entries * sizeof(float)                      options:MTLResourceStorageModeShared];
        id<MTLBuffer> outBuf    = [g_device newBufferWithLength:out_count * sizeof(float)                        options:MTLResourceStorageModeShared];
        id<MTLBuffer> paramsBuf = [g_device newBufferWithLength:6 * sizeof(uint32_t)                             options:MTLResourceStorageModeShared];
        if (!mag || !phase || !levels || !gateCode || !upCode || !routeW || !hidden ||
            !downBuf || !cosLut || !sinLut || !outBuf || !paramsBuf) {
            ds4_polar_pool_close(&pool); return 0;
        }

        /* H1735+m8: levels buffer now sized from mag_levels (was hardcoded 4).
         * Any mag_levels ∈ {1..32} works; m4 = legacy, m8 = OOM-accuracy
         * candidate per codec_pareto_frontier.md. */

        /* Copy expert's real polar data from PLR2 (mmap-resident in pool).
         * For this canary, we use the SAME expert for gate AND up to keep
         * the CPU reference computation trivial. */
        const uint8_t *gate_mag_src = NULL;
        const uint8_t *gate_phase_src = NULL;
        const float   *gate_levels_src = NULL;
        ds4_polar_expert_view(gate_file, expert, &gate_mag_src, &gate_phase_src, &gate_levels_src);
        memcpy(mag.contents,    gate_mag_src,    (NSUInteger)rows * pairs);
        memcpy(phase.contents,  gate_phase_src,  (NSUInteger)rows * pairs);
        memcpy(levels.contents, gate_levels_src, levels_bytes_per_expert);

        /* Route metadata: single route_pair points at code tile 0 (our copied expert). */
        ((uint32_t *)gateCode.contents)[0] = 0;
        ((uint32_t *)upCode.contents)[0]   = 0;
        ((float    *)routeW.contents)[0]   = 1.0f;
        float *hid = (float *)hidden.contents;
        for (NSUInteger i = 0; i < hidden_count; i++) hid[i] = 1.0f;
        float *dwn = (float *)downBuf.contents;
        if (down_file) {
            /* Polar-down: decode first (down_rows × act_rows) reals into the
             * down buffer. Layout matches the H1735 kernel expectation
             * `down[route_pair, d, a]` flattened as
             * `dwn[((route_pair * down_rows) + d) * act_rows + a]`.
             * route_pairs == 1 here, so offset = d * act_rows + a.
             *
             * Polar storage: each pair at index k gives (re, im) → reals at
             * a = 2*k AND a = 2*k+1. For odd act_rows the last real comes
             * from re of pair k=act_rows/2. */
            for (uint32_t d = 0; d < down_rows; d++) {
                for (uint32_t a = 0; a < act_rows; a += 2) {
                    const uint32_t k = a >> 1;
                    const float re = ds4_polar_decode_pair_re(down_file, expert, d, k);
                    dwn[(NSUInteger)d * act_rows + a] = re;
                    if ((a + 1) < act_rows) {
                        const float im = ds4_polar_decode_pair_im(down_file, expert, d, k);
                        dwn[(NSUInteger)d * act_rows + a + 1] = im;
                    }
                }
            }
        } else {
            const float down_val = 1.0f / (float)act_rows;
            for (NSUInteger i = 0; i < down_count; i++) dwn[i] = down_val;
        }
        float *cosP = (float *)cosLut.contents;
        float *sinP = (float *)sinLut.contents;
        /* Populate LUT for phase_codes ∈ [0, phase_levels]:
         * decoded angle for code c is (c - phase_levels/2) × 2π/phase_levels. */
        const double phase_step_d = (2.0 * M_PI) / (double)phase_levels;
        const int half_P = (int)(phase_levels / 2u);
        for (NSUInteger c = 0; c < lut_entries; c++) {
            double angle = ((double)c - (double)half_P) * phase_step_d;
            cosP[c] = (float)cos(angle);
            sinP[c] = (float)sin(angle);
        }
        (void)0;  /* satisfy old loop tail; replaced by parameterized loop above */
        if (0) for (int code = -4; code <= 4; code++) {
            float angle = (float)code * 0.78539816339744830962f;
            cosP[code + 4] = cosf(angle);
            sinP[code + 4] = sinf(angle);
        }
        uint32_t *params = (uint32_t *)paramsBuf.contents;
        params[0] = pairs; params[1] = rows; params[2] = route_pairs;
        params[3] = down_rows; params[4] = act_rows;
        params[5] = mag_levels;  /* H1735+m8: dynamic magnitude codebook size */

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 12;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (!residency) { ds4_polar_pool_close(&pool); return 0; }
        id<MTLAllocation> allocs[12] = {
            (id<MTLAllocation>)mag, (id<MTLAllocation>)phase, (id<MTLAllocation>)levels,
            (id<MTLAllocation>)gateCode, (id<MTLAllocation>)upCode, (id<MTLAllocation>)routeW,
            (id<MTLAllocation>)hidden, (id<MTLAllocation>)downBuf,
            (id<MTLAllocation>)cosLut, (id<MTLAllocation>)sinLut,
            (id<MTLAllocation>)outBuf, (id<MTLAllocation>)paramsBuf,
        };
        [residency addAllocations:allocs count:12];
        [residency commit];
        ds4_residency_request_checked(residency, __func__);

        MTL4ArgumentTableDescriptor *atDesc = [MTL4ArgumentTableDescriptor new];
        atDesc.maxBufferBindCount = 12;
        atDesc.initializeBindings = YES;
        id<MTL4ArgumentTable> argTable = [g_device newArgumentTableWithDescriptor:atDesc error:&err];
        if (!argTable) { ds4_polar_pool_close(&pool); return 0; }
        [argTable setAddress:mag.gpuAddress       atIndex:0];
        [argTable setAddress:phase.gpuAddress     atIndex:1];
        [argTable setAddress:levels.gpuAddress    atIndex:2];
        [argTable setAddress:gateCode.gpuAddress  atIndex:3];
        [argTable setAddress:upCode.gpuAddress    atIndex:4];
        [argTable setAddress:routeW.gpuAddress    atIndex:5];
        [argTable setAddress:hidden.gpuAddress    atIndex:6];
        [argTable setAddress:downBuf.gpuAddress   atIndex:7];
        [argTable setAddress:cosLut.gpuAddress    atIndex:8];
        [argTable setAddress:sinLut.gpuAddress    atIndex:9];
        [argTable setAddress:outBuf.gpuAddress    atIndex:10];
        [argTable setAddress:paramsBuf.gpuAddress atIndex:11];

        id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
        [cb beginCommandBufferWithAllocator:g_polar_allocator];
        [cb useResidencySet:residency];
        id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
        if (!enc) { ds4_polar_pool_close(&pool); return 0; }
        [enc setComputePipelineState:g_polar_gud_pipeline];
        [enc setArgumentTable:argTable];
        [enc dispatchThreadgroups:MTLSizeMake(route_pairs, batches, 1)
            threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        [enc endEncoding];
        [cb endCommandBuffer];

        [g_polar_queue addResidencySet:residency];
        dispatch_semaphore_t sem = dispatch_semaphore_create(0);
        __block CFTimeInterval gpuStart = 0.0, gpuEnd = 0.0;
        __block NSError *fbErr = nil;
        MTL4CommitOptions *opts = [MTL4CommitOptions new];
        [opts addFeedbackHandler:^(id<MTL4CommitFeedback> feedback) {
            fbErr = feedback.error;
            gpuStart = feedback.GPUStartTime; gpuEnd = feedback.GPUEndTime;
            dispatch_semaphore_signal(sem);
        }];
        id<MTL4CommandBuffer> bufs[1] = { cb };
        [g_polar_queue commit:bufs count:1 options:opts];
        long waitRes = dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 30LL * NSEC_PER_SEC));
        [residency endResidency];
        if (waitRes != 0) { fprintf(stderr, "ds4: polar real canary timeout\n"); ds4_polar_pool_close(&pool); return 0; }
        if (fbErr) { fprintf(stderr, "ds4: polar real canary feedback err: %s\n", fbErr.localizedDescription.UTF8String); ds4_polar_pool_close(&pool); return 0; }

        /* CPU reference computation. For each row r ∈ [0, act_rows):
         *   gate_dot[r] = sum over p ∈ [0, pairs): re_decoded(r,p) + im_decoded(r,p)
         * (same as up_dot since we copied gate into up's slot for this canary).
         * act[r] = silu(gate_dot) * up_dot * 1.0
         *
         * If down is synthetic-uniform (down_file==NULL):
         *   out[d] = sum_r act[r] * (1/act_rows)  → identical across d
         * If down is polar (down_file!=NULL):
         *   out[d] = sum_r act[r] * dwn[d * act_rows + r]  → per-d differentiated */
        float gate_dot_sum_rows[64] = {0};  /* MAX_ACT = 64 */
        for (uint32_t r = 0; r < act_rows; r++) {
            double sum_re_im = 0.0;
            for (uint32_t p = 0; p < pairs; p++) {
                sum_re_im += (double)ds4_polar_decode_pair_re(gate_file, expert, r, p);
                sum_re_im += (double)ds4_polar_decode_pair_im(gate_file, expert, r, p);
            }
            gate_dot_sum_rows[r] = (float)sum_re_im;
        }
        float act_per_row[64] = {0};  /* MAX_ACT = 64 */
        double act_sum = 0.0;
        for (uint32_t r = 0; r < act_rows; r++) {
            const float g = gate_dot_sum_rows[r];
            const float silu = g / (1.0f + expf(-g));
            const float a = silu * g * 1.0f;
            act_per_row[r] = a;
            act_sum += (double)a;
        }

        float *outPtr = (float *)outBuf.contents;
        float maxAbsErr = 0.0f;
        float refMagMax = 0.0f;  /* max |expected[d]| for rel-err denominator */
        float expected0 = 0.0f;
        if (down_file) {
            /* polar-down: per-d expected via real dwn values */
            for (uint32_t d = 0; d < down_rows; d++) {
                double od = 0.0;
                for (uint32_t r = 0; r < act_rows; r++) {
                    od += (double)act_per_row[r] * (double)dwn[(NSUInteger)d * act_rows + r];
                }
                const float exp_d = (float)od;
                if (d == 0) expected0 = exp_d;
                if (fabsf(exp_d) > refMagMax) refMagMax = fabsf(exp_d);
                const float diff = fabsf(outPtr[d] - exp_d);
                if (diff > maxAbsErr) maxAbsErr = diff;
            }
        } else {
            /* synthetic-uniform down: per-d expected is the same value act_sum/act_rows */
            expected0 = (float)(act_sum / (double)act_rows);
            refMagMax = fabsf(expected0);
            for (NSUInteger i = 0; i < out_count; i++) {
                float diff = fabsf(outPtr[i] - expected0);
                if (diff > maxAbsErr) maxAbsErr = diff;
            }
        }
        const double gpuMs = (gpuEnd - gpuStart) * 1000.0;
        const float relErr = refMagMax > 1e-6f ? maxAbsErr / refMagMax : maxAbsErr;
        fprintf(stderr,
                "ds4: polar REAL canary layer=%u expert=%u rows=%u pairs=%u down_rows=%u act_rows=%u\n"
                "  down_src=%s CPU expected[0]=%.4f GPU out[0]=%.4f max_abs_err=%.4e rel_err=%.4e\n"
                "  gpu_elapsed=%.4f ms  resident=%.1f MB\n",
                layer, expert, rows, pairs, down_rows, act_rows,
                down_file ? "polar" : "uniform",
                (double)expected0, (double)outPtr[0],
                (double)maxAbsErr, (double)relErr,
                gpuMs,
                (double)(pair_count * 2 + code_rows * 16 + hidden_count * 4 + down_count * 4) / 1e6);
        ds4_polar_pool_close(&pool);
        /* Threshold: synthetic-uniform tightly bit-equivalent (1e-3); polar-down
         * carries codec noise (rel_L2 ~0.20 expected per-row, ~0.05 per
         * output via the sum-projection averaging). Accept rel_err < 0.10 for
         * polar-down — well within codec quality envelope. */
        const float accept = down_file ? 0.10f : 1e-3f;
        return relErr < accept ? 1 : 0;
    }
}

/* ============================================================ */
/* VQ-2D: fused gate*silu*up*route_weight + down projection     */
/* ============================================================ */
/* Per the VQ-2D codec exploration (commit cf39af8 + breakthrough memo):
 * VQ K=256 with per-(layer, kind) codebook gives rel_L2 0.022 / cos_sim
 * 0.9998 — 6.15× lower codec error than polar p32_m8 at half storage.
 *
 * Kernel structure mirrors H1735 polar gate_up_down kernel but:
 *   - Single uint8 code per pair (no separate mag/phase bytes)
 *   - K-entry codebook lookup → (re, im) directly (no trig LUT, no
 *     levels indirection)
 *   - Same threadgroup / partial-sum / down-projection structure
 *
 * Canary uses single shared codebook for gate AND up (canary
 * simplification matching polar real_canary's gate==up convention).
 * Real deployment uses separate codebooks per (layer, kind) tile.
 *
 * Input layout (VQB1 file mmap'd by ds4_vqb1_reader):
 *   gate_codes: [n_experts][n_rows][n_pairs] uint8
 *   codebook:   [K][2] fp32 (re, im pairs)
 */
#include "ds4_vqb1_reader.h"

static id<MTLComputePipelineState> g_vq_gud_pipeline;
static int g_vq_gud_init_attempted;
static int g_vq_gud_init_ok;

static int ds4_vq_gud_pipeline_init(void) {
    if (g_vq_gud_init_attempted) return g_vq_gud_init_ok;
    g_vq_gud_init_attempted = 1;
    if (!ds4_polar_pipeline_init()) return 0; /* shared compiler + queue */

    NSError *err = nil;
    NSString *source =
        @"#include <metal_stdlib>\n"
         "using namespace metal;\n"
         "kernel void vq_gate_up_down(device const uchar* gate_codes [[buffer(0)]],\n"
         "                            device const uchar* up_codes [[buffer(1)]],\n"
         "                            device const float* codebook [[buffer(2)]],\n"
         "                            device const uint* gate_code [[buffer(3)]],\n"
         "                            device const uint* up_code [[buffer(4)]],\n"
         "                            device const float* route_weight [[buffer(5)]],\n"
         "                            device const float* hidden [[buffer(6)]],\n"
         "                            device const float* down [[buffer(7)]],\n"
         "                            device float* out [[buffer(8)]],\n"
         "                            device const uint* params [[buffer(9)]],\n"
         "                            uint2 tg [[threadgroup_position_in_grid]],\n"
         "                            uint tid [[thread_index_in_threadgroup]]) {\n"
         "  constexpr uint THREADS = 256;\n"
         "  constexpr uint MAX_ACT = 64;\n"
         "  threadgroup float gate_partial[THREADS];\n"
         "  threadgroup float up_partial[THREADS];\n"
         "  threadgroup float act[MAX_ACT];\n"
         "  uint route_pair = tg.x;\n"
         "  uint batch = tg.y;\n"
         "  uint pairs = params[0];\n"
         "  uint rows = params[1];\n"
         "  uint route_pairs = params[2];\n"
         "  uint down_rows = params[3];\n"
         "  uint act_rows = params[4];\n"
         "  uint hbase = (batch * route_pairs + route_pair) * pairs * 2;\n"
         "  for (uint row = 0; row < act_rows; row++) {\n"
         "    uint gate_row = gate_code[route_pair] * rows + row;\n"
         "    uint up_row = up_code[route_pair] * rows + row;\n"
         "    uint gate_base = gate_row * pairs;\n"
         "    uint up_base = up_row * pairs;\n"
         "    float gate_acc = 0.0f;\n"
         "    float up_acc = 0.0f;\n"
         "    for (uint j = tid; j < pairs; j += THREADS) {\n"
         "      float h0 = hidden[hbase + 2*j];\n"
         "      float h1 = hidden[hbase + 2*j + 1];\n"
         "      uchar gate_c = gate_codes[gate_base + j];\n"
         "      float gate_re = codebook[gate_c * 2];\n"
         "      float gate_im = codebook[gate_c * 2 + 1];\n"
         "      gate_acc += gate_re * h0 + gate_im * h1;\n"
         "      uchar up_c = up_codes[up_base + j];\n"
         "      float up_re = codebook[up_c * 2];\n"
         "      float up_im = codebook[up_c * 2 + 1];\n"
         "      up_acc += up_re * h0 + up_im * h1;\n"
         "    }\n"
         "    gate_partial[tid] = gate_acc;\n"
         "    up_partial[tid] = up_acc;\n"
         "    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "    for (uint stride = THREADS >> 1; stride > 0; stride >>= 1) {\n"
         "      if (tid < stride) {\n"
         "        gate_partial[tid] += gate_partial[tid + stride];\n"
         "        up_partial[tid] += up_partial[tid + stride];\n"
         "      }\n"
         "      threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "    }\n"
         "    if (tid == 0) {\n"
         "      float g = gate_partial[0];\n"
         "      float u = up_partial[0];\n"
         "      act[row] = (g / (1.0f + exp(-g))) * u * route_weight[route_pair];\n"
         "    }\n"
         "    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         "  }\n"
         "  if (tid < down_rows) {\n"
         "    float acc = 0.0f;\n"
         "    uint down_base = (route_pair * down_rows + tid) * act_rows;\n"
         "    for (uint k = 0; k < act_rows; k++) acc += act[k] * down[down_base + k];\n"
         "    out[(batch * route_pairs + route_pair) * down_rows + tid] = acc;\n"
         "  }\n"
         "}\n";

    MTL4LibraryDescriptor *libDesc = [MTL4LibraryDescriptor new];
    libDesc.source = source;
    libDesc.name = @"ds4_vq_gate_up_down";
    id<MTLLibrary> lib = [g_polar_compiler newLibraryWithDescriptor:libDesc error:&err];
    if (!lib) {
        fprintf(stderr, "ds4: vq gud library failed: %s\n",
                err ? err.localizedDescription.UTF8String : "(no error)");
        return 0;
    }
    MTL4LibraryFunctionDescriptor *fnDesc = [MTL4LibraryFunctionDescriptor new];
    fnDesc.library = lib;
    fnDesc.name = @"vq_gate_up_down";
    MTL4ComputePipelineDescriptor *pipeDesc = [MTL4ComputePipelineDescriptor new];
    pipeDesc.computeFunctionDescriptor = fnDesc;
    pipeDesc.threadGroupSizeIsMultipleOfThreadExecutionWidth = YES;
    pipeDesc.maxTotalThreadsPerThreadgroup = 256;
    g_vq_gud_pipeline = [g_polar_compiler newComputePipelineStateWithDescriptor:pipeDesc
                                                          compilerTaskOptions:nil
                                                                        error:&err];
    if (!g_vq_gud_pipeline) {
        fprintf(stderr, "ds4: vq gud pipeline failed: %s\n",
                err ? err.localizedDescription.UTF8String : "(no error)");
        return 0;
    }
    g_vq_gud_init_ok = 1;
    return 1;
}

/* CLI: ds4 --vq-real-canary <vqb1_dir> <layer> <expert> [down_rows [act_rows]]
 *
 * Loads gate/up/down VQB1 files for <layer> from <vqb1_dir>. For canary
 * simplicity, uses GATE codebook for both gate and up paths (mirrors
 * polar real_canary's gate==up convention). Real inference would pass
 * separate codebooks per kind.
 *
 * Validates VQB1 → MTL4 GPU pipeline at fp32 noise floor on real DS4
 * V4 weights. Mirror of ds4_gpu_mtl4_polar_real_canary structure.
 */
int ds4_gpu_mtl4_vq_real_canary(const char *vqb1_dir,
                                  uint32_t layer, uint32_t expert,
                                  uint32_t down_rows, uint32_t act_rows) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_vq_gud_pipeline_init()) return 0;
    if (!vqb1_dir || !vqb1_dir[0]) return 0;
    if (down_rows == 0 || act_rows == 0 || down_rows > 256 || act_rows > 64) return 0;

    char gate_path[1024], up_path[1024], down_path[1024];
    snprintf(gate_path, sizeof(gate_path), "%s/L%02u_gate.vqb1", vqb1_dir, layer);
    snprintf(up_path,   sizeof(up_path),   "%s/L%02u_up.vqb1",   vqb1_dir, layer);
    snprintf(down_path, sizeof(down_path), "%s/L%02u_down.vqb1", vqb1_dir, layer);

    ds4_vqb1_file gate_file, up_file, down_file;
    if (!ds4_vqb1_open(gate_path, &gate_file)) {
        fprintf(stderr, "ds4: vq real canary — failed to open %s\n", gate_path);
        return 0;
    }
    if (!ds4_vqb1_open(up_path, &up_file)) {
        fprintf(stderr, "ds4: vq real canary — failed to open %s\n", up_path);
        ds4_vqb1_close(&gate_file);
        return 0;
    }
    if (!ds4_vqb1_open(down_path, &down_file)) {
        fprintf(stderr, "ds4: vq real canary — failed to open %s\n", down_path);
        ds4_vqb1_close(&gate_file);
        ds4_vqb1_close(&up_file);
        return 0;
    }
    if (expert >= gate_file.n_experts) {
        fprintf(stderr, "ds4: vq real canary — expert %u OOR (gate has %u)\n",
                expert, gate_file.n_experts);
        ds4_vqb1_close(&gate_file); ds4_vqb1_close(&up_file); ds4_vqb1_close(&down_file);
        return 0;
    }
    if (act_rows > gate_file.n_rows) {
        fprintf(stderr, "ds4: vq real canary — act_rows %u > gate n_rows %u\n",
                act_rows, gate_file.n_rows);
        ds4_vqb1_close(&gate_file); ds4_vqb1_close(&up_file); ds4_vqb1_close(&down_file);
        return 0;
    }
    if (down_rows > down_file.n_rows) {
        fprintf(stderr, "ds4: vq real canary — down_rows %u > down n_rows %u\n",
                down_rows, down_file.n_rows);
        ds4_vqb1_close(&gate_file); ds4_vqb1_close(&up_file); ds4_vqb1_close(&down_file);
        return 0;
    }
    if (act_rows > down_file.n_pairs * 2u) {
        fprintf(stderr, "ds4: vq real canary — act_rows %u > down 2×n_pairs %u\n",
                act_rows, down_file.n_pairs * 2u);
        ds4_vqb1_close(&gate_file); ds4_vqb1_close(&up_file); ds4_vqb1_close(&down_file);
        return 0;
    }
    /* Soundness: kernel reads codebook[code * 2] with code being uint8.
     * If K < 256 and any code value >= K, this is OOB on the codebook
     * buffer. Validate K matches kernel's uint8 code domain. */
    if (gate_file.k != 256 || up_file.k != 256 || down_file.k != 256) {
        fprintf(stderr, "ds4: vq real canary — only K=256 supported by kernel "
                        "(gate.k=%u up.k=%u down.k=%u)\n",
                gate_file.k, up_file.k, down_file.k);
        ds4_vqb1_close(&gate_file); ds4_vqb1_close(&up_file); ds4_vqb1_close(&down_file);
        return 0;
    }
    /* NOTE: canary uses gate_file's codes AND codebook for BOTH gate
     * and up paths (gate==up convention). up_file is loaded only to
     * validate it exists; its data is not consumed in this canary.
     * Real-inference dispatcher will use separate codebooks per kind. */

    const uint32_t rows   = gate_file.n_rows;
    const uint32_t pairs  = gate_file.n_pairs;
    const uint32_t n_codes = 1;
    const uint32_t route_pairs = 1;
    const uint32_t batches = 1;
    const uint32_t k_size = gate_file.k;

    @autoreleasepool {
        NSError *err = nil;
        const NSUInteger pair_count = (NSUInteger)n_codes * rows * pairs;
        const NSUInteger hidden_count = (NSUInteger)batches * route_pairs * pairs * 2;
        const NSUInteger down_count = (NSUInteger)route_pairs * down_rows * act_rows;
        const NSUInteger out_count = (NSUInteger)batches * route_pairs * down_rows;
        const NSUInteger codebook_bytes = (NSUInteger)k_size * 2u * sizeof(float);

        id<MTLBuffer> gateCodes = [g_device newBufferWithLength:pair_count                       options:MTLResourceStorageModeShared];
        id<MTLBuffer> upCodes   = [g_device newBufferWithLength:pair_count                       options:MTLResourceStorageModeShared];
        id<MTLBuffer> codebook  = [g_device newBufferWithLength:codebook_bytes                   options:MTLResourceStorageModeShared];
        id<MTLBuffer> gateCode  = [g_device newBufferWithLength:route_pairs * sizeof(uint32_t)   options:MTLResourceStorageModeShared];
        id<MTLBuffer> upCode    = [g_device newBufferWithLength:route_pairs * sizeof(uint32_t)   options:MTLResourceStorageModeShared];
        id<MTLBuffer> routeW    = [g_device newBufferWithLength:route_pairs * sizeof(float)      options:MTLResourceStorageModeShared];
        id<MTLBuffer> hidden    = [g_device newBufferWithLength:hidden_count * sizeof(float)     options:MTLResourceStorageModeShared];
        id<MTLBuffer> downBuf   = [g_device newBufferWithLength:down_count * sizeof(float)       options:MTLResourceStorageModeShared];
        id<MTLBuffer> outBuf    = [g_device newBufferWithLength:out_count * sizeof(float)        options:MTLResourceStorageModeShared];
        id<MTLBuffer> paramsBuf = [g_device newBufferWithLength:5 * sizeof(uint32_t)             options:MTLResourceStorageModeShared];

        if (!gateCodes || !upCodes || !codebook || !gateCode || !upCode || !routeW ||
            !hidden || !downBuf || !outBuf || !paramsBuf) {
            ds4_vqb1_close(&gate_file); ds4_vqb1_close(&up_file); ds4_vqb1_close(&down_file);
            return 0;
        }

        /* Copy expert's codes from VQB1 file (mmap-resident) to MTL buffer.
         * Canary uses GATE expert codes for BOTH gate AND up (gate==up
         * convention matching polar canary). */
        const uint8_t *gate_src = ds4_vqb1_expert_codes(&gate_file, expert);
        memcpy(gateCodes.contents, gate_src, (NSUInteger)rows * pairs);
        memcpy(upCodes.contents,   gate_src, (NSUInteger)rows * pairs);
        /* Codebook: use gate's codebook (since gate==up in canary). */
        memcpy(codebook.contents, gate_file.codebook, codebook_bytes);

        ((uint32_t *)gateCode.contents)[0] = 0;
        ((uint32_t *)upCode.contents)[0]   = 0;
        ((float    *)routeW.contents)[0]   = 1.0f;
        float *hid = (float *)hidden.contents;
        for (NSUInteger i = 0; i < hidden_count; i++) hid[i] = 1.0f;

        /* down values: decode polar-style from VQB1 down file.
         * dwn[d * act_rows + a] for d in [0, down_rows), a in [0, act_rows).
         * Each act_rows pair k → reals at a=2k, a=2k+1. */
        float *dwn = (float *)downBuf.contents;
        for (uint32_t d = 0; d < down_rows; d++) {
            for (uint32_t a = 0; a < act_rows; a += 2) {
                const uint32_t k = a >> 1;
                float re = 0.0f, im = 0.0f;
                ds4_vqb1_decode_pair(&down_file, expert, d, k, &re, &im);
                dwn[(NSUInteger)d * act_rows + a] = re;
                if ((a + 1) < act_rows) {
                    dwn[(NSUInteger)d * act_rows + a + 1] = im;
                }
            }
        }

        uint32_t *params = (uint32_t *)paramsBuf.contents;
        params[0] = pairs; params[1] = rows; params[2] = route_pairs;
        params[3] = down_rows; params[4] = act_rows;

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 10;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (!residency) {
            ds4_vqb1_close(&gate_file); ds4_vqb1_close(&up_file); ds4_vqb1_close(&down_file);
            return 0;
        }
        id<MTLAllocation> allocs[10] = {
            (id<MTLAllocation>)gateCodes, (id<MTLAllocation>)upCodes, (id<MTLAllocation>)codebook,
            (id<MTLAllocation>)gateCode, (id<MTLAllocation>)upCode, (id<MTLAllocation>)routeW,
            (id<MTLAllocation>)hidden, (id<MTLAllocation>)downBuf,
            (id<MTLAllocation>)outBuf, (id<MTLAllocation>)paramsBuf,
        };
        [residency addAllocations:allocs count:10];
        [residency commit];
        ds4_residency_request_checked(residency, __func__);

        MTL4ArgumentTableDescriptor *atDesc = [MTL4ArgumentTableDescriptor new];
        atDesc.maxBufferBindCount = 10;
        atDesc.initializeBindings = YES;
        id<MTL4ArgumentTable> argTable = [g_device newArgumentTableWithDescriptor:atDesc error:&err];
        if (!argTable) {
            ds4_vqb1_close(&gate_file); ds4_vqb1_close(&up_file); ds4_vqb1_close(&down_file);
            return 0;
        }
        [argTable setAddress:gateCodes.gpuAddress atIndex:0];
        [argTable setAddress:upCodes.gpuAddress   atIndex:1];
        [argTable setAddress:codebook.gpuAddress  atIndex:2];
        [argTable setAddress:gateCode.gpuAddress  atIndex:3];
        [argTable setAddress:upCode.gpuAddress    atIndex:4];
        [argTable setAddress:routeW.gpuAddress    atIndex:5];
        [argTable setAddress:hidden.gpuAddress    atIndex:6];
        [argTable setAddress:downBuf.gpuAddress   atIndex:7];
        [argTable setAddress:outBuf.gpuAddress    atIndex:8];
        [argTable setAddress:paramsBuf.gpuAddress atIndex:9];

        id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
        [cb beginCommandBufferWithAllocator:g_polar_allocator];
        [cb useResidencySet:residency];
        id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
        if (!enc) {
            ds4_vqb1_close(&gate_file); ds4_vqb1_close(&up_file); ds4_vqb1_close(&down_file);
            return 0;
        }
        [enc setComputePipelineState:g_vq_gud_pipeline];
        [enc setArgumentTable:argTable];
        [enc dispatchThreadgroups:MTLSizeMake(route_pairs, batches, 1)
            threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        [enc endEncoding];
        [cb endCommandBuffer];

        [g_polar_queue addResidencySet:residency];
        dispatch_semaphore_t sem = dispatch_semaphore_create(0);
        __block CFTimeInterval gpuStart = 0.0, gpuEnd = 0.0;
        __block NSError *fbErr = nil;
        MTL4CommitOptions *opts = [MTL4CommitOptions new];
        [opts addFeedbackHandler:^(id<MTL4CommitFeedback> feedback) {
            fbErr = feedback.error;
            gpuStart = feedback.GPUStartTime; gpuEnd = feedback.GPUEndTime;
            dispatch_semaphore_signal(sem);
        }];
        id<MTL4CommandBuffer> bufs[1] = { cb };
        [g_polar_queue commit:bufs count:1 options:opts];
        long waitRes = dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 30LL * NSEC_PER_SEC));
        [residency endResidency];
        if (waitRes != 0) {
            fprintf(stderr, "ds4: vq real canary timeout\n");
            ds4_vqb1_close(&gate_file); ds4_vqb1_close(&up_file); ds4_vqb1_close(&down_file);
            return 0;
        }
        if (fbErr) {
            fprintf(stderr, "ds4: vq real canary feedback err: %s\n",
                    fbErr.localizedDescription.UTF8String);
            ds4_vqb1_close(&gate_file); ds4_vqb1_close(&up_file); ds4_vqb1_close(&down_file);
            return 0;
        }

        /* CPU reference: same structure as polar real_canary but with VQ
         * decode (codebook[code] lookup instead of mag/phase + trig). */
        float gate_dot_sum_rows[64] = {0};
        for (uint32_t r = 0; r < act_rows; r++) {
            double sum_re_im = 0.0;
            const uint8_t *exp_codes = ds4_vqb1_expert_codes(&gate_file, expert);
            for (uint32_t p = 0; p < pairs; p++) {
                const uint8_t c = exp_codes[(size_t)r * pairs + p];
                if (c >= gate_file.k) continue;
                sum_re_im += (double)gate_file.codebook[(size_t)c * 2u];
                sum_re_im += (double)gate_file.codebook[(size_t)c * 2u + 1u];
            }
            gate_dot_sum_rows[r] = (float)sum_re_im;
        }
        float act_per_row[64] = {0};
        for (uint32_t r = 0; r < act_rows; r++) {
            const float g = gate_dot_sum_rows[r];
            const float silu = g / (1.0f + expf(-g));
            act_per_row[r] = silu * g * 1.0f;
        }

        float *outPtr = (float *)outBuf.contents;
        float maxAbsErr = 0.0f;
        float refMagMax = 0.0f;
        float expected0 = 0.0f;
        for (uint32_t d = 0; d < down_rows; d++) {
            double od = 0.0;
            for (uint32_t r = 0; r < act_rows; r++) {
                od += (double)act_per_row[r] * (double)dwn[(NSUInteger)d * act_rows + r];
            }
            const float exp_d = (float)od;
            if (d == 0) expected0 = exp_d;
            if (fabsf(exp_d) > refMagMax) refMagMax = fabsf(exp_d);
            const float diff = fabsf(outPtr[d] - exp_d);
            if (diff > maxAbsErr) maxAbsErr = diff;
        }
        const double gpuMs = (gpuEnd - gpuStart) * 1000.0;
        const float relErr = refMagMax > 1e-6f ? maxAbsErr / refMagMax : maxAbsErr;
        fprintf(stderr,
                "ds4: vq REAL canary layer=%u expert=%u rows=%u pairs=%u down_rows=%u act_rows=%u K=%u\n"
                "  CPU expected[0]=%.4f GPU out[0]=%.4f max_abs_err=%.4e rel_err=%.4e\n"
                "  gpu_elapsed=%.4f ms  resident=%.1f MB\n",
                layer, expert, rows, pairs, down_rows, act_rows, k_size,
                (double)expected0, (double)outPtr[0],
                (double)maxAbsErr, (double)relErr,
                gpuMs,
                (double)(pair_count * 2 + codebook_bytes + hidden_count * 4 + down_count * 4) / 1e6);

        ds4_vqb1_close(&gate_file);
        ds4_vqb1_close(&up_file);
        ds4_vqb1_close(&down_file);
        /* VQ canary uses real polar-decoded down, so codec noise dominates
         * (rel_L2 ~0.02 weight-level). Accept rel_err < 0.05 — fp32-noise
         * floor at GPU level, codec-floor at CPU-vs-GPU comparison level. */
        return relErr < 1e-3f ? 1 : 0;
    }
}

/* ============================================================ */
/* Phase B-2.3c: polar hot-path dispatcher (stub)                */
/* ============================================================ */
/* silv chose Branch A (polar hot-path + runtime). Per BRANCH_A_PREFLIGHT.md
 * memo (commit b5e84f1), the row-coverage prerequisite forks into A.1
 * (full-row corpus, needs disk approval), A.2 (full-row VQ corpus), or
 * A.3 (hybrid polar+FP4). silv decision pending.
 *
 * This stub ships the hot-path GATE wiring without yet performing actual
 * polar substitution. Validates:
 *   - Pool reference reaches the hot path correctly
 *   - Per-layer enable check works
 *   - Diagnostic emits when polar would dispatch
 *   - Graceful fallback to FP4 (returns 0)
 *
 * silv can runtime-test the gate logic without risking incorrect inference:
 *   DS4_POLAR_DIR=tmp/polar_full_p32m8 DS4_POLAR_LAYERS=0,1,2,3 ./ds4 ...
 * Expected: stderr emits "polar pool has GUD for layer=N" lines on FFN
 * boundaries; FP4 path runs normally; AIME hold-rate unchanged.
 *
 * Body fills in once silv resolves A.1/A.2/A.3 sub-decision.
 */
int ds4_gpu_mtl4_polar_routed_moe_batch_stub(const void *pool_opaque,
                                              uint32_t layer,
                                              uint32_t n_tokens) {
    const ds4_polar_pool *pool = (const ds4_polar_pool *)pool_opaque;
    if (!pool) return 0;
    const ds4_polar_file *gate = ds4_polar_pool_get(pool, layer, DS4_POLAR_KIND_GATE);
    const ds4_polar_file *up   = ds4_polar_pool_get(pool, layer, DS4_POLAR_KIND_UP);
    const ds4_polar_file *down = ds4_polar_pool_get(pool, layer, DS4_POLAR_KIND_DOWN);
    if (!gate || !up || !down) {
        /* Layer not in polar pool — silent fallback (some layers may be
         * intentionally polar-disabled per DS4_POLAR_LAYERS mask). */
        return 0;
    }
    /* Diagnostic: confirm pool has all GUD files; stub returns 0 to fall
     * through to FP4 path. Once row-coverage decision resolves and body
     * lands, this returns 1 on successful polar dispatch instead. */
    static int diag_emitted[DS4_POLAR_MAX_LAYERS] = {0};
    if (layer < DS4_POLAR_MAX_LAYERS && !diag_emitted[layer]) {
        fprintf(stderr,
                "ds4: polar B-2.3c gate engaged layer=%u "
                "(gate=%ux%u up=%ux%u down=%ux%u K_or_M=p%u_m%u  n_tokens=%u) "
                "— STUB returns 0 → FP4 fallback. Body pending A.1/A.2/A.3 decision.\n",
                layer,
                gate->n_rows, gate->n_pairs,
                up->n_rows, up->n_pairs,
                down->n_rows, down->n_pairs,
                gate->phase_levels, gate->mag_levels,
                n_tokens);
        diag_emitted[layer] = 1;
    }
    return 0;  /* Stub: always fall back to FP4 (no actual polar substitution yet) */
}

int ds4_gpu_mtl4_polar_tile_canary(uint32_t tiles, uint32_t rows, uint32_t batches, uint32_t pairs) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_polar_tile_pipeline_init()) return 0;
    if (tiles == 0 || rows == 0 || batches == 0 || pairs == 0) return 0;

    @autoreleasepool {
        NSError *err = nil;
        const NSUInteger row_packets = (NSUInteger)tiles * rows;
        const NSUInteger pair_count = row_packets * pairs;
        const NSUInteger hidden_count = (NSUInteger)batches * tiles * pairs * 2;
        const NSUInteger out_count = (NSUInteger)batches * row_packets;

        id<MTLBuffer> mag      = [g_device newBufferWithLength:pair_count                          options:MTLResourceStorageModeShared];
        id<MTLBuffer> phase    = [g_device newBufferWithLength:pair_count                          options:MTLResourceStorageModeShared];
        id<MTLBuffer> levels   = [g_device newBufferWithLength:row_packets * 4 * sizeof(float)     options:MTLResourceStorageModeShared];
        id<MTLBuffer> hidden   = [g_device newBufferWithLength:hidden_count * sizeof(float)        options:MTLResourceStorageModeShared];
        id<MTLBuffer> cosLut   = [g_device newBufferWithLength:9 * sizeof(float)                   options:MTLResourceStorageModeShared];
        id<MTLBuffer> sinLut   = [g_device newBufferWithLength:9 * sizeof(float)                   options:MTLResourceStorageModeShared];
        id<MTLBuffer> outBuf   = [g_device newBufferWithLength:out_count * sizeof(float)           options:MTLResourceStorageModeShared];
        id<MTLBuffer> paramsBuf= [g_device newBufferWithLength:3 * sizeof(uint32_t)                options:MTLResourceStorageModeShared];
        if (!mag || !phase || !levels || !hidden || !cosLut || !sinLut || !outBuf || !paramsBuf) return 0;

        memset(mag.contents, 0, pair_count);
        memset(phase.contents, 4, pair_count);
        float *lvl = (float *)levels.contents;
        for (NSUInteger p = 0; p < row_packets; p++) {
            lvl[p * 4 + 0] = 1.0f; lvl[p * 4 + 1] = 0.5f;
            lvl[p * 4 + 2] = 0.25f; lvl[p * 4 + 3] = 0.125f;
        }
        float *hid = (float *)hidden.contents;
        for (NSUInteger i = 0; i < hidden_count; i++) hid[i] = 1.0f;
        float *cosP = (float *)cosLut.contents;
        float *sinP = (float *)sinLut.contents;
        for (int code = -4; code <= 4; code++) {
            float angle = (float)code * 0.78539816339744830962f;
            cosP[code + 4] = cosf(angle);
            sinP[code + 4] = sinf(angle);
        }
        uint32_t *params = (uint32_t *)paramsBuf.contents;
        params[0] = pairs; params[1] = rows; params[2] = tiles;

        MTLResidencySetDescriptor *rsDesc = [MTLResidencySetDescriptor new];
        rsDesc.initialCapacity = 8;
        id<MTLResidencySet> residency = [g_device newResidencySetWithDescriptor:rsDesc error:&err];
        if (!residency) return 0;
        id<MTLAllocation> allocs[8] = {
            (id<MTLAllocation>)mag, (id<MTLAllocation>)phase,
            (id<MTLAllocation>)levels, (id<MTLAllocation>)hidden,
            (id<MTLAllocation>)cosLut, (id<MTLAllocation>)sinLut,
            (id<MTLAllocation>)outBuf, (id<MTLAllocation>)paramsBuf,
        };
        [residency addAllocations:allocs count:8];
        [residency commit];
        ds4_residency_request_checked(residency, __func__);

        MTL4ArgumentTableDescriptor *atDesc = [MTL4ArgumentTableDescriptor new];
        atDesc.maxBufferBindCount = 8;
        atDesc.initializeBindings = YES;
        id<MTL4ArgumentTable> argTable = [g_device newArgumentTableWithDescriptor:atDesc error:&err];
        if (!argTable) return 0;
        [argTable setAddress:mag.gpuAddress       atIndex:0];
        [argTable setAddress:phase.gpuAddress     atIndex:1];
        [argTable setAddress:levels.gpuAddress    atIndex:2];
        [argTable setAddress:hidden.gpuAddress    atIndex:3];
        [argTable setAddress:cosLut.gpuAddress    atIndex:4];
        [argTable setAddress:sinLut.gpuAddress    atIndex:5];
        [argTable setAddress:outBuf.gpuAddress    atIndex:6];
        [argTable setAddress:paramsBuf.gpuAddress atIndex:7];

        id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
        [cb beginCommandBufferWithAllocator:g_polar_allocator];
        [cb useResidencySet:residency];
        id<MTL4ComputeCommandEncoder> enc = [cb computeCommandEncoder];
        if (!enc) return 0;
        [enc setComputePipelineState:g_polar_tile_pipeline];
        [enc setArgumentTable:argTable];
        [enc dispatchThreadgroups:MTLSizeMake(tiles, rows, batches)
            threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        [enc endEncoding];
        [cb endCommandBuffer];

        [g_polar_queue addResidencySet:residency];
        dispatch_semaphore_t sem = dispatch_semaphore_create(0);
        __block CFTimeInterval gpuStart = 0.0;
        __block CFTimeInterval gpuEnd = 0.0;
        __block NSError *fbErr = nil;
        MTL4CommitOptions *opts = [MTL4CommitOptions new];
        [opts addFeedbackHandler:^(id<MTL4CommitFeedback> feedback) {
            fbErr = feedback.error;
            gpuStart = feedback.GPUStartTime;
            gpuEnd = feedback.GPUEndTime;
            dispatch_semaphore_signal(sem);
        }];
        id<MTL4CommandBuffer> bufs[1] = { cb };
        [g_polar_queue commit:bufs count:1 options:opts];
        long waitRes = dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 30LL * NSEC_PER_SEC));
        [residency endResidency];
        if (waitRes != 0) { fprintf(stderr, "ds4: polar tile canary timeout\n"); return 0; }
        if (fbErr) { fprintf(stderr, "ds4: polar tile feedback err: %s\n", fbErr.localizedDescription.UTF8String); return 0; }

        float *outPtr = (float *)outBuf.contents;
        float expected = (float)pairs * 1.0f;
        float maxAbsErr = 0.0f;
        for (NSUInteger i = 0; i < out_count; i++) {
            float diff = fabsf(outPtr[i] - expected);
            if (diff > maxAbsErr) maxAbsErr = diff;
        }
        const double gpuMs = (gpuEnd - gpuStart) * 1000.0;
        fprintf(stderr,
                "ds4: polar TILE canary tiles=%u rows=%u batches=%u pairs=%u "
                "expected=%.3f out[0]=%.3f max_abs_err=%.3e gpu=%.6f ms "
                "(%.0f ns/output, %.0f ns/packet, resident=%.1f MB)\n",
                tiles, rows, batches, pairs,
                (double)expected, (double)outPtr[0], (double)maxAbsErr, gpuMs,
                gpuMs * 1e6 / (double)out_count,
                gpuMs * 1e6 / (double)(out_count),
                (double)(pair_count * 2 + row_packets * 4 * 4 + hidden_count * 4 + out_count * 4) / 1e6);
        return maxAbsErr < 1e-3f ? 1 : 0;
    }
}

static int ds4_mtl4_moe_env_enabled(void) {
 static int cached = -1;
 if (cached < 0) {
 const char *v = getenv("DS4_MTL4_MOE_ENABLE");
 cached = (v && v[0] && v[0] != '0') ? 1 : 0;
 }
 return cached;
}

enum { DS4_MTL4_MOE_MAX_T = 16 };

/* IQ2_XXS dequant tables: defined non-static in ds4.c (dedup). */
extern const uint8_t kmask_iq2xs[8];
extern const uint8_t ksigns_iq2xs[128];
extern const uint64_t iq2xxs_grid[256];

/* Convert one block_iq2_xxs (66 bytes) → 256 float32 values.
 *
 * silv 2026-05-27 codex H2086 fix: align with CPU/hot-store IQ2_XXS
 * dequant path in ds4.c:2112-2113:
 *   ls = 2 * (aux32[1] >> 28) + 1
 *   bscale = d * (float)ls * 0.125f
 *
 * Previous formula `d * 0.125 * (0.5 + h)` = `d * (2h+1)/16` was
 * SYSTEMATICALLY 2× SMALLER than the reference `d * (2h+1)/8`. This
 * affected every IQ2_XXS expert dequant in the MTL4 path → all expert
 * weights were half-magnitude → routed-MoE outputs scaled wrong.
 *
 * Math verification: NEON path at ds4.c:2049-2056 uses `(0.5+h)` and
 * multiplies by 0.25 at the end → `(0.5+h)/4 = (1+2h)/8` ✓ matches
 * non-NEON `(2h+1) * 0.125 = (1+2h)/8` ✓. MTL4 OLD was using
 * `(0.5+h) * 0.125 = (1+2h)/16` ✗ — half of reference.
 */
static void ds4_mtl4_dequant_iq2_xxs_block(const uint8_t *src66, float *dst256) {
 const uint16_t d_f16 = ((const uint16_t *)src66)[0];
 /* Inline F16 → F32 (ARM half-precision intrinsic if available). */
 union { uint16_t u; _Float16 h; } cvt = { .u = d_f16 };
 const float d = (float)cvt.h;
 const uint16_t *qs_u16 = (const uint16_t *)(src66 + 2);
 uint32_t aux32[2];
 const uint8_t *aux8 = (const uint8_t *)aux32;
 for (int ib32 = 0; ib32 < 8; ib32++) {
 memcpy(aux32, qs_u16 + 4 * ib32, 8);
 const uint32_t scale_nibble = aux32[1] >> 28;
 const float db = d * 0.125f * (float)(2u * scale_nibble + 1u);
 for (int l = 0; l < 4; l++) {
 const uint8_t *grid = (const uint8_t *)(iq2xxs_grid + aux8[l]);
 const uint8_t signs = ksigns_iq2xs[(aux32[1] >> (7 * l)) & 127];
 for (int j = 0; j < 8; j++) {
 dst256[j] = db * (float)grid[j] * ((signs & kmask_iq2xs[j]) ? -1.0f : 1.0f);
 }
 dst256 += 8;
 }
 }
}

/* Dequant a single routed-expert weight tensor (n_in × n_out F32 row-major).
 * The IQ2_XXS layout stores 256 elements per 66-byte block, n_in*n_out total
 * elements per expert. Returns true on success. */
static bool ds4_mtl4_dequant_iq2_xxs_expert(const uint8_t *src_bytes,
 uint64_t n_in, uint64_t n_out,
 float *dst) {
 const uint64_t n_elem = n_in * n_out;
 if ((n_elem % 256) != 0) {
 fprintf(stderr, "ds4_mtl4: IQ2_XXS dequant: n_elem=%llu not divisible by 256\n",
 (unsigned long long)n_elem);
 return false;
 }
 const uint64_t n_blocks = n_elem / 256;
 for (uint64_t b = 0; b < n_blocks; b++) {
 ds4_mtl4_dequant_iq2_xxs_block(src_bytes + b * 66, dst + b * 256);
 }
 return true;
}

/* ---- MTL4 ML pipeline cache + Apple package loader ----
 * Shared MTL4 ML compiler/queue/event/allocator. Pipeline states cached per
 * shape (gate/up: rows×4096@4096×24576; down: rows×2048@2048×24576).
 * The Apple sample matmul package accepts arbitrary input dimensions via
 * MTL4MachineLearningPipelineDescriptor.setInputDimensions:atBufferIndex:.
 *
 * Package path: configurable via DS4_MTL4_PACKAGE_PATH env (default points
 * to the codex sample directory). */
static id<MTLLibrary> g_mtl4_ml_library = nil;
static id<MTL4Compiler> g_mtl4_ml_compiler = nil;
static id<MTL4CommandQueue> g_mtl4_ml_queue = nil;
static id<MTL4CommandAllocator> g_mtl4_ml_allocator = nil;
static id<MTLSharedEvent> g_mtl4_ml_event = nil;
static int g_mtl4_ml_setup_state = 0; /* 0=unchecked, 1=ready, -1=failed */

typedef struct {
 int T, H, O;
 id<MTL4MachineLearningPipelineState> state;
 id<MTLTensor> A_tensor;
 id<MTLTensor> B_tensor;
 id<MTLTensor> out_tensor;
 id<MTL4ArgumentTable> arg_table;
 id<MTLHeap> heap;
} ds4_mtl4_cache_entry;

#define DS4_MTL4_CACHE_MAX 4
static ds4_mtl4_cache_entry g_mtl4_cache[DS4_MTL4_CACHE_MAX];
static int g_mtl4_cache_count = 0;
static pthread_mutex_t g_mtl4_setup_mu = PTHREAD_MUTEX_INITIALIZER;

static MTLTensorExtents *ds4_mtl4_extents2(NSInteger inner, NSInteger outer) {
 NSInteger v[2] = {inner, outer};
 return [[MTLTensorExtents alloc] initWithRank:2 values:v];
}

static int ds4_mtl4_setup_apple_package(void) {
 pthread_mutex_lock(&g_mtl4_setup_mu);
 if (g_mtl4_ml_setup_state != 0) {
 pthread_mutex_unlock(&g_mtl4_setup_mu);
 return g_mtl4_ml_setup_state;
 }
 const char *pkg_env = getenv("DS4_MTL4_PACKAGE_PATH");
 NSString *pkg_path = pkg_env && pkg_env[0]
 ? [NSString stringWithUTF8String:pkg_env]
 : @"/tmp/mtl4_sample/Packages/matrix-multiplication.mtlpackage";

 if (![[NSFileManager defaultManager] fileExistsAtPath:pkg_path]) {
 fprintf(stderr, "ds4_mtl4: package not found at %s\n", pkg_path.UTF8String);
 g_mtl4_ml_setup_state = -1;
 pthread_mutex_unlock(&g_mtl4_setup_mu);
 return -1;
 }

 /* Ensure device + Metal4 are available. g_device is the existing global. */
 extern id<MTLDevice> g_device;
 if (!g_device) {
 g_mtl4_ml_setup_state = -1;
 pthread_mutex_unlock(&g_mtl4_setup_mu);
 return -1;
 }

 NSError *err = nil;
 g_mtl4_ml_library = [g_device newLibraryWithURL:[NSURL fileURLWithPath:pkg_path] error:&err];
 if (!g_mtl4_ml_library) {
 fprintf(stderr, "ds4_mtl4: newLibraryWithURL failed: %s\n",
 err ? err.localizedDescription.UTF8String : "(null)");
 g_mtl4_ml_setup_state = -1;
 pthread_mutex_unlock(&g_mtl4_setup_mu);
 return -1;
 }
 err = nil;
 g_mtl4_ml_compiler = [g_device newCompilerWithDescriptor:[MTL4CompilerDescriptor new] error:&err];
 if (!g_mtl4_ml_compiler) {
 g_mtl4_ml_setup_state = -1;
 pthread_mutex_unlock(&g_mtl4_setup_mu);
 return -1;
 }
 g_mtl4_ml_queue = [g_device newMTL4CommandQueue];
 g_mtl4_ml_allocator = [g_device newCommandAllocator];
 g_mtl4_ml_event = [g_device newSharedEvent];
 if (!g_mtl4_ml_queue || !g_mtl4_ml_allocator || !g_mtl4_ml_event) {
 g_mtl4_ml_setup_state = -1;
 pthread_mutex_unlock(&g_mtl4_setup_mu);
 return -1;
 }
 g_mtl4_ml_setup_state = 1;
 fprintf(stderr, "ds4_mtl4: Apple package loaded from %s\n", pkg_path.UTF8String);
 pthread_mutex_unlock(&g_mtl4_setup_mu);
 return 1;
}

/* Build (or cache-hit) a pipeline + tensors for one shape (T × H @ H × O).
 * Returns NULL on failure. */
static ds4_mtl4_cache_entry *ds4_mtl4_get_or_build_pipeline(int T, int H, int O) {
 extern id<MTLDevice> g_device;
 pthread_mutex_lock(&g_mtl4_setup_mu);
 for (int i = 0; i < g_mtl4_cache_count; i++) {
 if (g_mtl4_cache[i].T == T && g_mtl4_cache[i].H == H && g_mtl4_cache[i].O == O) {
 ds4_mtl4_cache_entry *e = &g_mtl4_cache[i];
 pthread_mutex_unlock(&g_mtl4_setup_mu);
 return e;
 }
 }
 if (g_mtl4_cache_count >= DS4_MTL4_CACHE_MAX) {
 fprintf(stderr, "ds4_mtl4: pipeline cache full (max %d)\n", DS4_MTL4_CACHE_MAX);
 pthread_mutex_unlock(&g_mtl4_setup_mu);
 return NULL;
 }
 ds4_mtl4_cache_entry *e = &g_mtl4_cache[g_mtl4_cache_count];
 e->T = T; e->H = H; e->O = O;

 MTLFunctionReflection *refl = [g_mtl4_ml_library reflectionForFunctionWithName:@"main"];
 if (!refl) { pthread_mutex_unlock(&g_mtl4_setup_mu); return NULL; }
 MTL4LibraryFunctionDescriptor *fd = [MTL4LibraryFunctionDescriptor new];
 fd.name = @"main"; fd.library = g_mtl4_ml_library;
 MTL4MachineLearningPipelineDescriptor *pd = [MTL4MachineLearningPipelineDescriptor new];
 pd.machineLearningFunctionDescriptor = fd;
 MTL4PipelineOptions *opts = [MTL4PipelineOptions new];
 opts.shaderReflection = MTL4ShaderReflectionBindingInfo;
 pd.options = opts;
 for (id<MTLBinding> b in refl.bindings) {
 if (b.type != MTLBindingTypeTensor) continue;
 id<MTLTensorBinding> tb = (id<MTLTensorBinding>)b;
 NSString *name = tb.name.lowercaseString;
 if ([name containsString:@"inputa"]) [pd setInputDimensions:ds4_mtl4_extents2(H, T) atBufferIndex:tb.index];
 if ([name containsString:@"inputb"]) [pd setInputDimensions:ds4_mtl4_extents2(O, H) atBufferIndex:tb.index];
 }
 NSError *err = nil;
 e->state = [g_mtl4_ml_compiler newMachineLearningPipelineStateWithDescriptor:pd error:&err];
 if (!e->state) {
 fprintf(stderr, "ds4_mtl4: pipeline build failed for T=%d H=%d O=%d: %s\n",
 T, H, O, err ? err.localizedDescription.UTF8String : "(null)");
 pthread_mutex_unlock(&g_mtl4_setup_mu);
 return NULL;
 }

 /* Build A, B, output tensors + heap + argument table from the pipeline reflection. */
 NSMutableDictionary<NSString*, id<MTLTensor>> *tdict = [NSMutableDictionary new];
 for (id<MTLBinding> b in e->state.reflection.bindings) {
 if (b.type != MTLBindingTypeTensor) continue;
 id<MTLTensorBinding> tb = (id<MTLTensorBinding>)b;
 MTLTensorDescriptor *desc = [MTLTensorDescriptor new];
 desc.usage = MTLTensorUsageMachineLearning;
 desc.dimensions = tb.dimensions;
 desc.dataType = tb.tensorDataType;
 err = nil;
 id<MTLTensor> tns = [g_device newTensorWithDescriptor:desc error:&err];
 if (!tns) {
 fprintf(stderr, "ds4_mtl4: tensor alloc failed: %s\n",
 err ? err.localizedDescription.UTF8String : "(null)");
 pthread_mutex_unlock(&g_mtl4_setup_mu);
 return NULL;
 }
 tdict[tb.name] = tns;
 NSString *lower = tb.name.lowercaseString;
 if ([lower containsString:@"inputa"]) e->A_tensor = tns;
 else if ([lower containsString:@"inputb"]) e->B_tensor = tns;
 else if ([lower containsString:@"output"]) e->out_tensor = tns;
 }
 if (!e->A_tensor || !e->B_tensor || !e->out_tensor) {
 fprintf(stderr, "ds4_mtl4: A/B/output binding lookup failed\n");
 pthread_mutex_unlock(&g_mtl4_setup_mu);
 return NULL;
 }

 MTL4ArgumentTableDescriptor *atd = [MTL4ArgumentTableDescriptor new];
 atd.maxBufferBindCount = 31;
 atd.initializeBindings = YES;
 err = nil;
 e->arg_table = [g_device newArgumentTableWithDescriptor:atd error:&err];
 if (!e->arg_table) {
 fprintf(stderr, "ds4_mtl4: arg table failed\n");
 pthread_mutex_unlock(&g_mtl4_setup_mu);
 return NULL;
 }
 for (id<MTLBinding> b in e->state.reflection.bindings) {
 if (b.type != MTLBindingTypeTensor) continue;
 id<MTLTensorBinding> tb = (id<MTLTensorBinding>)b;
 [e->arg_table setResource:tdict[tb.name].gpuResourceID atBufferIndex:tb.index];
 }
 MTLHeapDescriptor *hd = [MTLHeapDescriptor new];
 hd.type = MTLHeapTypePlacement;
 hd.size = e->state.intermediatesHeapSize;
 e->heap = [g_device newHeapWithDescriptor:hd];
 if (!e->heap) {
 fprintf(stderr, "ds4_mtl4: heap alloc failed\n");
 pthread_mutex_unlock(&g_mtl4_setup_mu);
 return NULL;
 }
 g_mtl4_cache_count++;
 fprintf(stderr, "ds4_mtl4: built pipeline T=%d H=%d O=%d (cache %d/%d)\n",
 T, H, O, g_mtl4_cache_count, DS4_MTL4_CACHE_MAX);

 /* Warmup pass. First dispatch on a fresh MTL4 ML pipeline produces
 * undefined output (observed: NaN). The codex h1672 pattern also
 * does a discard warm dispatch before measurement. */
 id<MTL4CommandBuffer> wcb = [g_device newCommandBuffer];
 [wcb beginCommandBufferWithAllocator:g_mtl4_ml_allocator];
 id<MTL4MachineLearningCommandEncoder> wenc = [wcb machineLearningCommandEncoder];
 [wenc setArgumentTable:e->arg_table];
 [wenc setPipelineState:e->state];
 [wenc dispatchNetworkWithIntermediatesHeap:e->heap];
 [wenc endEncoding];
 [wcb endCommandBuffer];
 id<MTL4CommandBuffer> wbufs[] = {wcb};
 [g_mtl4_ml_queue commit:wbufs count:1];
 uint64_t wsv = g_mtl4_ml_event.signaledValue + 1;
 [g_mtl4_ml_queue signalEvent:g_mtl4_ml_event value:wsv];
 [g_mtl4_ml_event waitUntilSignaledValue:wsv timeoutMS:30000];

 pthread_mutex_unlock(&g_mtl4_setup_mu);
 return e;
}

/* Run one matmul dispatch via the cached pipeline; reads/writes via tensor APIs. */
static bool ds4_mtl4_dispatch_matmul(ds4_mtl4_cache_entry *e,
 const float *A_data, const float *B_data,
 float *out_data) {
 extern id<MTLDevice> g_device;
 MTLTensorExtents *origin = ds4_mtl4_extents2(0, 0);
 [e->A_tensor replaceSliceOrigin:origin sliceDimensions:ds4_mtl4_extents2(e->H, e->T)
 withBytes:A_data strides:ds4_mtl4_extents2(1, e->H)];
 [e->B_tensor replaceSliceOrigin:origin sliceDimensions:ds4_mtl4_extents2(e->O, e->H)
 withBytes:B_data strides:ds4_mtl4_extents2(1, e->O)];
 id<MTL4CommandBuffer> cb = [g_device newCommandBuffer];
 [cb beginCommandBufferWithAllocator:g_mtl4_ml_allocator];
 id<MTL4MachineLearningCommandEncoder> enc = [cb machineLearningCommandEncoder];
 [enc setArgumentTable:e->arg_table];
 [enc setPipelineState:e->state];
 [enc dispatchNetworkWithIntermediatesHeap:e->heap];
 [enc endEncoding];
 [cb endCommandBuffer];
 id<MTL4CommandBuffer> bufs[] = {cb};
 [g_mtl4_ml_queue commit:bufs count:1];
 uint64_t sv = g_mtl4_ml_event.signaledValue + 1;
 [g_mtl4_ml_queue signalEvent:g_mtl4_ml_event value:sv];
 if (![g_mtl4_ml_event waitUntilSignaledValue:sv timeoutMS:30000]) {
 fprintf(stderr, "ds4_mtl4: dispatch timeout\n");
 return false;
 }
 [e->out_tensor getBytes:out_data strides:ds4_mtl4_extents2(1, e->O)
 fromSliceOrigin:origin sliceDimensions:ds4_mtl4_extents2(e->O, e->T)];
 return true;
}

int ds4_gpu_routed_moe_batch_tensor_mtl4(
 ds4_gpu_tensor *out,
 ds4_gpu_tensor *gate,
 ds4_gpu_tensor *up,
 ds4_gpu_tensor *mid,
 ds4_gpu_tensor *experts,
 const void *model_map,
 uint64_t model_size,
 uint64_t gate_offset,
 uint64_t up_offset,
 uint64_t down_offset,
 uint32_t gate_type,
 uint32_t down_type,
 uint64_t gate_expert_bytes,
 uint64_t gate_row_bytes,
 uint64_t down_expert_bytes,
 uint64_t down_row_bytes,
 uint32_t expert_in_dim,
 uint32_t expert_mid_dim,
 uint32_t out_dim,
 const ds4_gpu_tensor *selected,
 const ds4_gpu_tensor *weights,
 uint32_t n_total_expert,
 uint32_t n_expert,
 float clamp,
 const ds4_gpu_tensor *x,
 uint32_t layer_index,
 uint32_t n_tokens,
 bool *mid_is_f16,
 bool *mtl4_path_taken) {
 (void)n_total_expert;
 /* Preflight: all conditions must hold or fall back to legacy. */
 const int env_ok = ds4_mtl4_moe_env_enabled();
 const int shape_ok = (n_expert == 6 && n_tokens <= DS4_MTL4_MOE_MAX_T);
 if (mtl4_path_taken) *mtl4_path_taken = false;

 if (!env_ok || !shape_ok) {
 /* Legacy fallback — drop in. */
 return ds4_gpu_routed_moe_batch_tensor(
 out, gate, up, mid, experts, model_map, model_size,
 gate_offset, up_offset, down_offset, gate_type, down_type,
 gate_expert_bytes, gate_row_bytes, down_expert_bytes, down_row_bytes,
 expert_in_dim, expert_mid_dim, out_dim,
 selected, weights, n_total_expert, n_expert, clamp, x,
 layer_index, n_tokens, mid_is_f16);
 }

 /* IQ2_XXS gate/up + Q8_0 down is the IQ2_XXS-w2Q2K-AProjQ8-SExpQ8-OutQ8
 * recipe shipped. We only support IQ2_XXS gate path here for the
 * canary; up + down still go through legacy if anything fails. */
 enum { DS4Q_TYPE_IQ2_XXS = 16, DS4Q_TYPE_Q8_0 = 8 };
 if (gate_type != DS4Q_TYPE_IQ2_XXS) {
 return ds4_gpu_routed_moe_batch_tensor(
 out, gate, up, mid, experts, model_map, model_size,
 gate_offset, up_offset, down_offset, gate_type, down_type,
 gate_expert_bytes, gate_row_bytes, down_expert_bytes, down_row_bytes,
 expert_in_dim, expert_mid_dim, out_dim,
 selected, weights, n_total_expert, n_expert, clamp, x,
 layer_index, n_tokens, mid_is_f16);
 }

 /* Setup Apple matmul package on first use. */
 if (ds4_mtl4_setup_apple_package() != 1) {
 return ds4_gpu_routed_moe_batch_tensor(
 out, gate, up, mid, experts, model_map, model_size,
 gate_offset, up_offset, down_offset, gate_type, down_type,
 gate_expert_bytes, gate_row_bytes, down_expert_bytes, down_row_bytes,
 expert_in_dim, expert_mid_dim, out_dim,
 selected, weights, n_total_expert, n_expert, clamp, x,
 layer_index, n_tokens, mid_is_f16);
 }

 /* Host-side dequant + packed dispatch.
 * COST WARNING: per call this allocates:
 * - 6 × (expert_in_dim × expert_mid_dim × 4) bytes dequant tmp ≈ 192 MB
 * - 2 × (expert_in_dim × 6·expert_mid_dim × 4) packed B ≈ 400 MB (gate+up)
 * - 1 × (expert_mid_dim × 6·out_dim × 4) packed down B ≈ 200 MB
 * The legacy SIMD path does dequant inline at register level and avoids
 * these allocations. THIS PATH IS A FUNCTIONAL CORRECTNESS PROBE, NOT A
 * SPEED WIN until/unless replaces host dequant with a Metal compute
 * shader that does dequant+matmul in one pass. */

 int32_t selected_ids[16] = {0};
 const size_t sel_bytes = (size_t)n_expert * sizeof(int32_t);
 if (ds4_gpu_tensor_read(selected, 0, selected_ids, sel_bytes) == 0) {
 fprintf(stderr, "ds4_mtl4: failed to read selected expert IDs\n");
 return ds4_gpu_routed_moe_batch_tensor(
 out, gate, up, mid, experts, model_map, model_size,
 gate_offset, up_offset, down_offset, gate_type, down_type,
 gate_expert_bytes, gate_row_bytes, down_expert_bytes, down_row_bytes,
 expert_in_dim, expert_mid_dim, out_dim,
 selected, weights, n_total_expert, n_expert, clamp, x,
 layer_index, n_tokens, mid_is_f16);
 }

 /* For the first iteration we just measure: dequant gate weights for the
 * 6 selected experts, pack them, dispatch a matmul, compare checksum.
 * This validates that:
 * (a) the dequant tables are correct
 * (b) Apple's package loads + dispatches our shapes
 * (c) end-to-end time vs legacy
 * Then fall back to legacy for the actual output (correctness preserved). */

 const size_t per_expert_floats = (size_t)expert_in_dim * (size_t)expert_mid_dim;
 const size_t packed_floats = (size_t)expert_in_dim * 6ull * (size_t)expert_mid_dim;
 float *tmp_dequant = (float *)malloc(per_expert_floats * sizeof(float));
 float *packed_gate_B = (float *)malloc(packed_floats * sizeof(float));
 float *x_data = (float *)malloc((size_t)n_tokens * (size_t)expert_in_dim * sizeof(float));
 float *gate_out = (float *)malloc((size_t)n_tokens * 6ull * (size_t)expert_mid_dim * sizeof(float));
 if (!tmp_dequant || !packed_gate_B || !x_data || !gate_out) {
 free(tmp_dequant); free(packed_gate_B); free(x_data); free(gate_out);
 return ds4_gpu_routed_moe_batch_tensor(
 out, gate, up, mid, experts, model_map, model_size,
 gate_offset, up_offset, down_offset, gate_type, down_type,
 gate_expert_bytes, gate_row_bytes, down_expert_bytes, down_row_bytes,
 expert_in_dim, expert_mid_dim, out_dim,
 selected, weights, n_total_expert, n_expert, clamp, x,
 layer_index, n_tokens, mid_is_f16);
 }

 /* Bounds check: under trim50, router can output IDs in original 0..255
 * space but the on-disk gate_exps tensor only stores N_kept < 256
 * experts. Reading at expert_id × gate_expert_bytes for an out-of-range
 * id reads past the tensor's allocated bytes → garbage F16 d scales
 * → IQ2_XXS dequant produces NaN. The proper fix is to plumb the
 * expert_remap translation through inference (pending integration. Until then: detect + fall back. */
 extern uint32_t ds4_get_layer_expert_count(uint32_t layer);
 const uint32_t layer_expert_count = ds4_get_layer_expert_count(layer_index);
 int out_of_bounds = 0;
 for (uint32_t e = 0; e < n_expert; e++) {
 if (selected_ids[e] < 0 || (uint32_t)selected_ids[e] >= layer_expert_count) {
 out_of_bounds++;
 }
 }
 if (out_of_bounds > 0) {
 static int warned[64] = {0}; /* DS4_N_LAYER = 43 but use a const here */
 if (layer_index < 64 && !warned[layer_index]) {
 warned[layer_index] = 1;
 fprintf(stderr,
 "ds4_mtl4: L%u — %d/%d selected_ids out of trim_count=%u, "
 "falling back to legacy. Need expert_remap plumbing.\n",
 layer_index, out_of_bounds, n_expert, layer_expert_count);
 }
 free(tmp_dequant); free(packed_gate_B); free(x_data); free(gate_out);
 if (mtl4_path_taken) *mtl4_path_taken = false;
 return ds4_gpu_routed_moe_batch_tensor(
 out, gate, up, mid, experts, model_map, model_size,
 gate_offset, up_offset, down_offset, gate_type, down_type,
 gate_expert_bytes, gate_row_bytes, down_expert_bytes, down_row_bytes,
 expert_in_dim, expert_mid_dim, out_dim,
 selected, weights, n_total_expert, n_expert, clamp, x,
 layer_index, n_tokens, mid_is_f16);
 }

 fprintf(stderr, "ds4_mtl4: L%u selected_ids: [%d %d %d %d %d %d] (trim=%u)\n",
 layer_index,
 selected_ids[0], selected_ids[1], selected_ids[2],
 selected_ids[3], selected_ids[4], selected_ids[5], layer_expert_count);

 uint64_t t_dequant_ns_total = 0;
 for (int e = 0; e < (int)n_expert && e < 6; e++) {
 const int32_t expert_id = selected_ids[e];
 if (expert_id < 0 || (uint64_t)expert_id >= (model_size / gate_expert_bytes)) {
 fprintf(stderr, "ds4_mtl4: invalid expert_id=%d\n", expert_id);
 free(tmp_dequant); free(packed_gate_B); free(x_data); free(gate_out);
 return ds4_gpu_routed_moe_batch_tensor(
 out, gate, up, mid, experts, model_map, model_size,
 gate_offset, up_offset, down_offset, gate_type, down_type,
 gate_expert_bytes, gate_row_bytes, down_expert_bytes, down_row_bytes,
 expert_in_dim, expert_mid_dim, out_dim,
 selected, weights, n_total_expert, n_expert, clamp, x,
 layer_index, n_tokens, mid_is_f16);
 }
 const uint8_t *expert_bytes = (const uint8_t *)model_map + gate_offset + (uint64_t)expert_id * gate_expert_bytes;
 uint64_t t0 = clock_gettime_nsec_np(CLOCK_UPTIME_RAW);
 ds4_mtl4_dequant_iq2_xxs_expert(expert_bytes, expert_in_dim, expert_mid_dim, tmp_dequant);
 t_dequant_ns_total += clock_gettime_nsec_np(CLOCK_UPTIME_RAW) - t0;
 /* GGUF quantized expert layout: stored as [output_col][input_row]
 * row-major (output_col outer, input_row inner — natural quant
 * blocking along the matmul inner-product axis). The dequant walks
 * blocks sequentially, so tmp_dequant has the same [out_col][in_row]
 * layout. Pack into packed_gate_B which is [input_row][packed_out]
 * row-major where packed_out = e * expert_mid_dim + c. TRANSPOSE. */
 for (uint64_t c = 0; c < expert_mid_dim; c++) {
 for (uint64_t r = 0; r < expert_in_dim; r++) {
 packed_gate_B[r * 6 * expert_mid_dim + e * expert_mid_dim + c] =
 tmp_dequant[c * expert_in_dim + r];
 }
 }
 }

 /* Read x activation from GPU tensor. Force command buffer flush first
 * so prior in-flight Metal work (layer pre-MoE compute) is committed
 * before host read. Without this, layers immediately after cpu_moe
 * layers can race-read uninitialized batch_ffn_norm tensor data
 * (observed: NaN gate_abs_sum on first 2 Metal MoE layers after a
 * cpu_moe sequence; the 3rd layer succeeds because by then the
 * tensor has been populated by the prior Metal MoE dispatch). */
 (void)ds4_gpu_end_commands();
 (void)ds4_gpu_begin_commands();

 const size_t x_bytes = (size_t)n_tokens * (size_t)expert_in_dim * sizeof(float);
 if (ds4_gpu_tensor_read(x, 0, x_data, x_bytes) == 0) {
 fprintf(stderr, "ds4_mtl4: failed to read x activation\n");
 free(tmp_dequant); free(packed_gate_B); free(x_data); free(gate_out);
 return ds4_gpu_routed_moe_batch_tensor(
 out, gate, up, mid, experts, model_map, model_size,
 gate_offset, up_offset, down_offset, gate_type, down_type,
 gate_expert_bytes, gate_row_bytes, down_expert_bytes, down_row_bytes,
 expert_in_dim, expert_mid_dim, out_dim,
 selected, weights, n_total_expert, n_expert, clamp, x,
 layer_index, n_tokens, mid_is_f16);
 }

 /* Pipeline cache build + dispatch. */
 uint64_t t_dispatch0 = clock_gettime_nsec_np(CLOCK_UPTIME_RAW);
 ds4_mtl4_cache_entry *gate_pipe = ds4_mtl4_get_or_build_pipeline(
 (int)n_tokens, (int)expert_in_dim, 6 * (int)expert_mid_dim);
 bool dispatch_ok = false;
 if (gate_pipe) {
 dispatch_ok = ds4_mtl4_dispatch_matmul(gate_pipe, x_data, packed_gate_B, gate_out);
 }
 uint64_t t_dispatch_ns = clock_gettime_nsec_np(CLOCK_UPTIME_RAW) - t_dispatch0;

 /* Compute checksums to localize NaN source. */
 double x_abs_sum = 0.0, B_abs_sum = 0.0, gate_abs_sum = 0.0;
 int x_nan = 0, B_nan = 0, gate_nan = 0;
 const size_t x_n = (size_t)n_tokens * (size_t)expert_in_dim;
 for (size_t i = 0; i < x_n; i++) {
 const float v = x_data[i];
 if (isnan(v) || isinf(v)) x_nan++;
 else x_abs_sum += fabs((double)v);
 }
 const size_t B_n = (size_t)expert_in_dim * 6 * (size_t)expert_mid_dim;
 for (size_t i = 0; i < B_n; i++) {
 const float v = packed_gate_B[i];
 if (isnan(v) || isinf(v)) B_nan++;
 else B_abs_sum += fabs((double)v);
 }
 const size_t gate_out_n = (size_t)n_tokens * 6 * (size_t)expert_mid_dim;
 for (size_t i = 0; i < gate_out_n; i++) {
 const float v = gate_out[i];
 if (isnan(v) || isinf(v)) gate_nan++;
 else gate_abs_sum += fabs((double)v);
 }
 fprintf(stderr,
 "ds4_mtl4: L%u T=%u dequant=%.1fms disp=%.1fms "
 "| x: |sum|=%.3e nan=%d/%zu | B: |sum|=%.3e nan=%d/%zu "
 "| gate: |sum|=%.3e nan=%d/%zu | ok=%d\n",
 layer_index, n_tokens,
 (double)t_dequant_ns_total / 1e6, (double)t_dispatch_ns / 1e6,
 x_abs_sum, x_nan, x_n,
 B_abs_sum, B_nan, B_n,
 gate_abs_sum, gate_nan, gate_out_n,
 dispatch_ok ? 1 : 0);

 free(tmp_dequant); free(packed_gate_B); free(x_data); free(gate_out);

 if (mtl4_path_taken) *mtl4_path_taken = true;

 /* CANARY MODE: measured + logged the path, now fall back to legacy for
 * the actual output. When reviewed we extend to up + SwiGLU + down. */
 return ds4_gpu_routed_moe_batch_tensor(
 out, gate, up, mid, experts, model_map, model_size,
 gate_offset, up_offset, down_offset, gate_type, down_type,
 gate_expert_bytes, gate_row_bytes, down_expert_bytes, down_row_bytes,
 expert_in_dim, expert_mid_dim, out_dim,
 selected, weights, n_total_expert, n_expert, clamp, x,
 layer_index, n_tokens, mid_is_f16);
}

int ds4_gpu_hc_split_sinkhorn_tensor(
 ds4_gpu_tensor *out,
 const ds4_gpu_tensor *mix,
 const void *model_map,
 uint64_t model_size,
 uint64_t scale_offset,
 uint64_t base_offset,
 uint32_t n_hc,
 uint32_t sinkhorn_iters,
 float eps) {
 if (!g_initialized && !ds4_gpu_init()) return 0;
 if (n_hc == 0 || n_hc > 16) return 0;
 const uint64_t mix_hc = 2ull * n_hc + (uint64_t)n_hc * n_hc;
 const uint64_t mix_bytes = mix_hc * sizeof(float);
 const uint64_t scale_bytes = 3ull * sizeof(float);

 @autoreleasepool {
 id<MTLBuffer> mixbuf = ds4_gpu_tensor_buffer(mix);
 id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
 const uint64_t mix_tensor_bytes = ds4_gpu_tensor_bytes(mix);
 const uint64_t out_tensor_bytes = ds4_gpu_tensor_bytes(out);
 if (!mixbuf || !outbuf ||
 mix_tensor_bytes < mix_bytes ||
 out_tensor_bytes < mix_bytes) {
 fprintf(stderr, "ds4: Metal HC split received undersized activation buffers\n");
 return 0;
 }
 if (!ds4_gpu_range_resolvable(model_map, model_size, scale_offset, scale_bytes) ||

     !ds4_gpu_range_resolvable(model_map, model_size, base_offset, mix_bytes)) {
 fprintf(stderr, "ds4: Metal HC split parameter range is outside the mapped model\n");
 return 0;
 }

 uint64_t scale_inner = 0;
 uint64_t base_inner = 0;
 id<MTLBuffer> scalebuf = ds4_gpu_wrap_model_range(model_map, model_size, scale_offset, scale_bytes, &scale_inner);
 id<MTLBuffer> basebuf = ds4_gpu_wrap_model_range(model_map, model_size, base_offset, mix_bytes, &base_inner);
 if (!scalebuf || !basebuf) return 0;

 uint64_t n_rows64 = mix_tensor_bytes / mix_bytes;
 const uint64_t out_rows64 = out_tensor_bytes / mix_bytes;
 if (out_rows64 < n_rows64) n_rows64 = out_rows64;
 if (n_rows64 == 0 || n_rows64 > UINT32_MAX) {
 fprintf(stderr, "ds4: Metal HC split row count is outside supported range\n");
 return 0;
 }

 ds4_gpu_hc_split_args args = {
 .n_hc = (int32_t)n_hc,
 .sinkhorn_iters = (int32_t)sinkhorn_iters,
 .n_rows = (int64_t)n_rows64,
 .mix_hc = (int64_t)mix_hc,
 .nb01 = mix_bytes,
 .nb1 = mix_bytes,
 .eps = eps,
 };
 const NSUInteger nth = MIN((NSUInteger)256, MAX((NSUInteger)1, (NSUInteger)n_rows64));
 const NSUInteger n_tg = ((NSUInteger)n_rows64 + nth - 1u) / nth;

 int owned = 0;
 id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
 if (!cb) return 0;

 id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
 [enc setComputePipelineState:g_hc_split_sinkhorn_pipeline];
 [enc setBytes:&args length:sizeof(args) atIndex:0];
 [enc setBuffer:mixbuf offset:ds4_gpu_tensor_offset(mix) atIndex:1];
 [enc setBuffer:scalebuf offset:(NSUInteger)scale_inner atIndex:2];
 [enc setBuffer:basebuf offset:(NSUInteger)base_inner atIndex:3];
 [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:4];
 [enc dispatchThreadgroups:MTLSizeMake(n_tg, 1, 1)
 threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
 ds4_gpu_end_compute_encoder(cb, enc);

 if (!ds4_gpu_finish_command_buffer(cb, owned, "HC split/sinkhorn")) return 0;
 }

 return 1;
}

static int ds4_gpu_hc_weighted_sum_strided(
 ds4_gpu_tensor *out,
 const ds4_gpu_tensor *residual_hc,
 const ds4_gpu_tensor *weights,
 uint64_t weight_offset,
 uint64_t weight_row_stride,
 uint32_t n_embd,
 uint32_t n_hc,
 const char *label) {
 if (!g_initialized && !ds4_gpu_init()) return 0;
 if (!out || !residual_hc || !weights || n_embd == 0 || n_hc == 0 ||
 weight_row_stride < (uint64_t)n_hc * sizeof(float)) {
 return 0;
 }

 @autoreleasepool {
 id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(residual_hc);
 id<MTLBuffer> wbuf = ds4_gpu_tensor_buffer(weights);
 id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
 const uint64_t out_row_bytes = (uint64_t)n_embd * sizeof(float);
 const uint64_t out_tensor_bytes = ds4_gpu_tensor_bytes(out);
 if (out_row_bytes == 0 || out_tensor_bytes < out_row_bytes || out_tensor_bytes % out_row_bytes != 0) {
 fprintf(stderr, "ds4: Metal HC weighted sum output size is not a whole token row\n");
 return 0;
 }

 const uint64_t n_tokens64 = out_tensor_bytes / out_row_bytes;
 if (n_tokens64 == 0 || n_tokens64 > UINT32_MAX) {
 fprintf(stderr, "ds4: Metal HC weighted sum token count is outside supported range\n");
 return 0;
 }

 const uint64_t x_row_values = (uint64_t)n_hc * n_embd;
 if (x_row_values == 0 ||
 x_row_values > UINT64_MAX / sizeof(float) ||
 n_tokens64 > UINT64_MAX / (x_row_values * sizeof(float)) ||
 n_tokens64 > UINT64_MAX / ((uint64_t)n_hc * sizeof(float))) {
 fprintf(stderr, "ds4: Metal HC weighted sum activation size overflow\n");
 return 0;
 }

 const uint64_t x_bytes = n_tokens64 * x_row_values * sizeof(float);
 const uint64_t w_last = weight_offset +
 (n_tokens64 - 1u) * weight_row_stride +
 (uint64_t)n_hc * sizeof(float);
 if (!xbuf || !wbuf || !outbuf ||
 ds4_gpu_tensor_bytes(residual_hc) < x_bytes ||
 ds4_gpu_tensor_bytes(weights) < w_last) {
 fprintf(stderr, "ds4: Metal HC weighted sum received undersized activation buffers\n");
 return 0;
 }

 ds4_gpu_hc_weighted_sum_args args = {
 .n_embd = n_embd,
 .n_hc = n_hc,
 .n_tokens = (int64_t)n_tokens64,
 .nb_x0 = sizeof(float),
 .nb_x1 = (uint64_t)n_embd * sizeof(float),
 .nb_x2 = (uint64_t)n_hc * n_embd * sizeof(float),
 .nb_w0 = sizeof(float),
 .nb_w1 = weight_row_stride,
 .nb0 = sizeof(float),
 .nb1 = (uint64_t)n_embd * sizeof(float),
 };
 const uint64_t n_elem = (uint64_t)n_embd * n_tokens64;
 const NSUInteger nth = MIN((NSUInteger)256, MAX((NSUInteger)1, (NSUInteger)n_elem));
 const NSUInteger n_tg = ((NSUInteger)n_elem + nth - 1u) / nth;
 int owned = 0;
 id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
 if (!cb) return 0;

 id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
 [enc setComputePipelineState:g_hc_weighted_sum_pipeline];
 [enc setBytes:&args length:sizeof(args) atIndex:0];
 [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(residual_hc) atIndex:1];
 [enc setBuffer:wbuf offset:ds4_gpu_tensor_offset(weights) + (NSUInteger)weight_offset atIndex:2];
 [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
 [enc dispatchThreadgroups:MTLSizeMake(n_tg, 1, 1)
 threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
 ds4_gpu_end_compute_encoder(cb, enc);

 if (!ds4_gpu_finish_command_buffer(cb, owned, label)) return 0;
 }

 return 1;
}

int ds4_gpu_hc_weighted_sum_tensor(
 ds4_gpu_tensor *out,
 const ds4_gpu_tensor *residual_hc,
 const ds4_gpu_tensor *weights,
 uint32_t n_embd,
 uint32_t n_hc) {
 return ds4_gpu_hc_weighted_sum_strided(out,
 residual_hc,
 weights,
 0,
 (uint64_t)n_hc * sizeof(float),
 n_embd,
 n_hc,
 "HC weighted sum");
}

int ds4_gpu_hc_weighted_sum_split_tensor(
 ds4_gpu_tensor *out,
 const ds4_gpu_tensor *residual_hc,
 const ds4_gpu_tensor *split,
 uint32_t n_embd,
 uint32_t n_hc) {
 const uint64_t mix_hc = 2ull * n_hc + (uint64_t)n_hc * n_hc;
 return ds4_gpu_hc_weighted_sum_strided(out,
 residual_hc,
 split,
 0,
 mix_hc * sizeof(float),
 n_embd,
 n_hc,
 "HC weighted sum split");
}

/* Release decode fused HC pre-sublayer operation. The graph driver owns the
 * optional reference fallback so this function stays a direct fused dispatch. */
int ds4_gpu_hc_split_weighted_sum_tensor(
 ds4_gpu_tensor *out,
 ds4_gpu_tensor *split,
 const ds4_gpu_tensor *mix,
 const ds4_gpu_tensor *residual_hc,
 const void *model_map,
 uint64_t model_size,
 uint64_t scale_offset,
 uint64_t base_offset,
 uint32_t n_embd,
 uint32_t n_hc,
 uint32_t sinkhorn_iters,
 float eps) {
 if (!g_initialized && !ds4_gpu_init()) return 0;
 if (!out || !split || !mix || !residual_hc || !model_map ||
 n_embd == 0 || n_hc == 0) {
 return 0;
 }
 if (n_hc != 4) {
 fprintf(stderr, "ds4: Metal fused HC split/sum is specialized for HC=4\n");
 return 0;
 }

 const uint64_t mix_hc = 2ull * n_hc + (uint64_t)n_hc * n_hc;
 const uint64_t mix_bytes = mix_hc * sizeof(float);
 const uint64_t out_row_bytes = (uint64_t)n_embd * sizeof(float);
 const uint64_t residual_row_bytes = (uint64_t)n_hc * n_embd * sizeof(float);
 const uint64_t scale_bytes = 3ull * sizeof(float);

 @autoreleasepool {
 id<MTLBuffer> mixbuf = ds4_gpu_tensor_buffer(mix);
 id<MTLBuffer> splitbuf = ds4_gpu_tensor_buffer(split);
 id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(residual_hc);
 id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
 const uint64_t out_tensor_bytes = ds4_gpu_tensor_bytes(out);
 if (out_row_bytes == 0 || out_tensor_bytes < out_row_bytes ||
 out_tensor_bytes % out_row_bytes != 0) {
 fprintf(stderr, "ds4: Metal fused HC split/sum output size is not a whole token row\n");
 return 0;
 }

 const uint64_t n_rows64 = out_tensor_bytes / out_row_bytes;
 if (n_rows64 == 0 || n_rows64 > UINT32_MAX ||
 n_rows64 > UINT64_MAX / mix_bytes ||
 n_rows64 > UINT64_MAX / residual_row_bytes) {
 fprintf(stderr, "ds4: Metal fused HC split/sum row count is outside supported range\n");
 return 0;
 }

 const uint64_t mix_total_bytes = n_rows64 * mix_bytes;
 const uint64_t residual_total_bytes = n_rows64 * residual_row_bytes;
 if (!mixbuf || !splitbuf || !xbuf || !outbuf ||
 ds4_gpu_tensor_bytes(mix) < mix_total_bytes ||
 ds4_gpu_tensor_bytes(split) < mix_total_bytes ||
 ds4_gpu_tensor_bytes(residual_hc) < residual_total_bytes) {
 fprintf(stderr, "ds4: Metal fused HC split/sum received undersized activation buffers\n");
 return 0;
 }

 if (!ds4_gpu_range_resolvable(model_map, model_size, scale_offset, scale_bytes) ||


     !ds4_gpu_range_resolvable(model_map, model_size, base_offset, mix_bytes)) {
 fprintf(stderr, "ds4: Metal fused HC split/sum parameter range is outside the mapped model\n");
 return 0;
 }

 uint64_t scale_inner = 0;
 uint64_t base_inner = 0;
 id<MTLBuffer> scalebuf = ds4_gpu_wrap_model_range(model_map, model_size, scale_offset, scale_bytes, &scale_inner);
 id<MTLBuffer> basebuf = ds4_gpu_wrap_model_range(model_map, model_size, base_offset, mix_bytes, &base_inner);
 if (!scalebuf || !basebuf) return 0;

 ds4_gpu_hc_split_weighted_sum_args args = {
 .n_embd = (int64_t)n_embd,
 .n_hc = (int32_t)n_hc,
 .sinkhorn_iters = (int32_t)sinkhorn_iters,
 .n_rows = (int64_t)n_rows64,
 .mix_hc = (int64_t)mix_hc,
 .nb_mix1 = mix_bytes,
 .nb_split1 = mix_bytes,
 .nb_x0 = sizeof(float),
 .nb_x1 = (uint64_t)n_embd * sizeof(float),
 .nb_x2 = residual_row_bytes,
 .nb0 = sizeof(float),
 .nb1 = out_row_bytes,
 .eps = eps,
 };

 NSUInteger nth = g_hc_split_weighted_sum_pipeline.maxTotalThreadsPerThreadgroup;
 if (nth > 256u) nth = 256u;
 if (nth > (NSUInteger)n_embd) nth = (NSUInteger)n_embd;
 if (nth == 0) nth = 1u;

 int owned = 0;
 id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
 if (!cb) return 0;

 id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
 [enc setComputePipelineState:g_hc_split_weighted_sum_pipeline];
 [enc setBytes:&args length:sizeof(args) atIndex:0];
 [enc setBuffer:mixbuf offset:ds4_gpu_tensor_offset(mix) atIndex:1];
 [enc setBuffer:scalebuf offset:(NSUInteger)scale_inner atIndex:2];
 [enc setBuffer:basebuf offset:(NSUInteger)base_inner atIndex:3];
 [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(residual_hc) atIndex:4];
 [enc setBuffer:splitbuf offset:ds4_gpu_tensor_offset(split) atIndex:5];
 [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:6];
 [enc setThreadgroupMemoryLength:(NSUInteger)n_hc * sizeof(float) atIndex:0];
 [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)n_rows64, 1, 1)
 threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
 ds4_gpu_end_compute_encoder(cb, enc);

 if (!ds4_gpu_finish_command_buffer(cb, owned, "HC split/sum fused")) return 0;
 }

 return 1;
}

/* Decode-only HC-pre plus the immediately following weighted RMSNorm. This is
 * intentionally specialized for DS4's fixed HC=4, embd=4096 shape; larger
 * batched prefill keeps using the existing two-stage path. */
int ds4_gpu_hc_split_weighted_sum_norm_tensor(
 ds4_gpu_tensor *out,
 ds4_gpu_tensor *norm_out,
 ds4_gpu_tensor *split,
 const ds4_gpu_tensor *mix,
 const ds4_gpu_tensor *residual_hc,
 const void *model_map,
 uint64_t model_size,
 uint64_t scale_offset,
 uint64_t base_offset,
 uint64_t norm_weight_offset,
 uint32_t n_embd,
 uint32_t n_hc,
 uint32_t sinkhorn_iters,
 float eps,
 float norm_eps) {
 if (!g_initialized && !ds4_gpu_init()) return 0;
 if (!out || !norm_out || !split || !mix || !residual_hc || !model_map ||
 n_embd != 4096 || n_hc != 4) {
 return 0;
 }

 const uint64_t mix_hc = 2ull * n_hc + (uint64_t)n_hc * n_hc;
 const uint64_t mix_bytes = mix_hc * sizeof(float);
 const uint64_t out_row_bytes = (uint64_t)n_embd * sizeof(float);
 const uint64_t residual_row_bytes = (uint64_t)n_hc * n_embd * sizeof(float);
 const uint64_t scale_bytes = 3ull * sizeof(float);

 @autoreleasepool {
 id<MTLBuffer> mixbuf = ds4_gpu_tensor_buffer(mix);
 id<MTLBuffer> splitbuf = ds4_gpu_tensor_buffer(split);
 id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(residual_hc);
 id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
 id<MTLBuffer> normbuf = ds4_gpu_tensor_buffer(norm_out);
 const uint64_t out_tensor_bytes = ds4_gpu_tensor_bytes(out);
 if (out_row_bytes == 0 || out_tensor_bytes < out_row_bytes ||
 out_tensor_bytes % out_row_bytes != 0) {
 fprintf(stderr, "ds4: Metal fused HC split/sum/norm output size is not a whole token row\n");
 return 0;
 }

 const uint64_t n_rows64 = out_tensor_bytes / out_row_bytes;
 if (n_rows64 == 0 || n_rows64 > UINT32_MAX ||
 n_rows64 > UINT64_MAX / mix_bytes ||
 n_rows64 > UINT64_MAX / residual_row_bytes) {
 fprintf(stderr, "ds4: Metal fused HC split/sum/norm row count is outside supported range\n");
 return 0;
 }

 const uint64_t mix_total_bytes = n_rows64 * mix_bytes;
 const uint64_t residual_total_bytes = n_rows64 * residual_row_bytes;
 const uint64_t out_total_bytes = n_rows64 * out_row_bytes;
 if (!mixbuf || !splitbuf || !xbuf || !outbuf || !normbuf ||
 ds4_gpu_tensor_bytes(mix) < mix_total_bytes ||
 ds4_gpu_tensor_bytes(split) < mix_total_bytes ||
 ds4_gpu_tensor_bytes(residual_hc) < residual_total_bytes ||
 ds4_gpu_tensor_bytes(norm_out) < out_total_bytes) {
 fprintf(stderr, "ds4: Metal fused HC split/sum/norm received undersized activation buffers\n");
 return 0;
 }

 if (!ds4_gpu_range_resolvable(model_map, model_size, scale_offset, scale_bytes) ||


     !ds4_gpu_range_resolvable(model_map, model_size, base_offset, mix_bytes) ||


     !ds4_gpu_range_resolvable(model_map, model_size, norm_weight_offset, out_row_bytes)) {
 fprintf(stderr, "ds4: Metal fused HC split/sum/norm parameter range is outside the mapped model\n");
 return 0;
 }

 uint64_t scale_inner = 0;
 uint64_t base_inner = 0;
 uint64_t norm_inner = 0;
 id<MTLBuffer> scalebuf = ds4_gpu_wrap_model_range(model_map, model_size, scale_offset, scale_bytes, &scale_inner);
 id<MTLBuffer> basebuf = ds4_gpu_wrap_model_range(model_map, model_size, base_offset, mix_bytes, &base_inner);
 id<MTLBuffer> normwbuf = ds4_gpu_wrap_model_range(model_map, model_size, norm_weight_offset, out_row_bytes, &norm_inner);
 if (!scalebuf || !basebuf || !normwbuf) return 0;

 id<MTLComputePipelineState> pipeline =
 ds4_gpu_hot_pipeline(g_hc_split_weighted_sum_norm_pipeline,
 "kernel_dsv4_hc_split_weighted_sum_norm4");
 if (!pipeline) return 0;

 ds4_gpu_hc_split_weighted_sum_norm_args args = {
 .n_embd = (int64_t)n_embd,
 .n_hc = (int32_t)n_hc,
 .sinkhorn_iters = (int32_t)sinkhorn_iters,
 .n_rows = (int64_t)n_rows64,
 .mix_hc = (int64_t)mix_hc,
 .nb_mix1 = mix_bytes,
 .nb_split1 = mix_bytes,
 .nb_x0 = sizeof(float),
 .nb_x1 = (uint64_t)n_embd * sizeof(float),
 .nb_x2 = residual_row_bytes,
 .nb0 = sizeof(float),
 .nb1 = out_row_bytes,
 .nb_norm1 = out_row_bytes,
 .eps = eps,
 .norm_eps = norm_eps,
 };

 NSUInteger nth = ds4_gpu_rms_norm_threads(n_embd);
 if (nth > pipeline.maxTotalThreadsPerThreadgroup) {
 fprintf(stderr, "ds4: Metal fused HC split/sum/norm requires %lu threads but pipeline supports %lu\n",
 (unsigned long)nth,
 (unsigned long)pipeline.maxTotalThreadsPerThreadgroup);
 return 0;
 }

 int owned = 0;
 id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
 if (!cb) return 0;

 id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
 [enc setComputePipelineState:pipeline];
 [enc setBytes:&args length:sizeof(args) atIndex:0];
 [enc setBuffer:mixbuf offset:ds4_gpu_tensor_offset(mix) atIndex:1];
 [enc setBuffer:scalebuf offset:(NSUInteger)scale_inner atIndex:2];
 [enc setBuffer:basebuf offset:(NSUInteger)base_inner atIndex:3];
 [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(residual_hc) atIndex:4];
 [enc setBuffer:splitbuf offset:ds4_gpu_tensor_offset(split) atIndex:5];
 [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:6];
 [enc setBuffer:normwbuf offset:(NSUInteger)norm_inner atIndex:7];
 [enc setBuffer:normbuf offset:ds4_gpu_tensor_offset(norm_out) atIndex:8];
 [enc setThreadgroupMemoryLength:((NSUInteger)n_embd + 4u + 32u) * sizeof(float)
 atIndex:0];
 [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)n_rows64, 1, 1)
 threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
 ds4_gpu_end_compute_encoder(cb, enc);

 if (!ds4_gpu_finish_command_buffer(cb, owned, "HC split/sum/norm fused")) return 0;
 }

 return 1;
}

int ds4_gpu_output_hc_weights_tensor(
 ds4_gpu_tensor *out,
 const ds4_gpu_tensor *pre,
 const void *model_map,
 uint64_t model_size,
 uint64_t scale_offset,
 uint64_t base_offset,
 uint32_t n_hc,
 float eps) {
 if (!g_initialized && !ds4_gpu_init()) return 0;
 if (!out || !pre || !model_map || n_hc == 0) return 0;

 @autoreleasepool {
 if ((n_hc % 4u) != 0) {
 fprintf(stderr, "ds4: Metal output HC weights requires a multiple-of-4 HC width\n");
 return 0;
 }

 id<MTLBuffer> prebuf = ds4_gpu_tensor_buffer(pre);
 id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
 const uint64_t row_bytes = (uint64_t)n_hc * sizeof(float);
 const uint64_t out_tensor_bytes = ds4_gpu_tensor_bytes(out);
 if (row_bytes == 0 || out_tensor_bytes < row_bytes || out_tensor_bytes % row_bytes != 0) {
 fprintf(stderr, "ds4: Metal output HC weights size is not a whole token row\n");
 return 0;
 }

 const uint64_t n_tokens64 = out_tensor_bytes / row_bytes;
 if (n_tokens64 == 0 || n_tokens64 > UINT32_MAX ||
 n_tokens64 > UINT64_MAX / row_bytes) {
 fprintf(stderr, "ds4: Metal output HC weights token count is outside supported range\n");
 return 0;
 }

 const uint64_t bytes = n_tokens64 * row_bytes;
 if (!prebuf || !outbuf ||
 ds4_gpu_tensor_bytes(pre) < bytes ||
 ds4_gpu_tensor_bytes(out) < bytes) {
 fprintf(stderr, "ds4: Metal output HC weights received undersized buffers\n");
 return 0;
 }

 uint64_t scale_inner = 0;
 uint64_t base_inner = 0;
 id<MTLBuffer> scalebuf = ds4_gpu_wrap_model_range(model_map, model_size,
 scale_offset, sizeof(float),
 &scale_inner);
 id<MTLBuffer> basebuf = ds4_gpu_wrap_model_range(model_map, model_size,
 base_offset, row_bytes,
 &base_inner);
 if (!scalebuf || !basebuf) return 0;

 const uint32_t n_tokens = (uint32_t)n_tokens64;
 ds4_gpu_bin_args mul_args = ds4_gpu_make_bin_rows_args(n_hc, n_tokens, 1);
 ds4_gpu_bin_args add_args = ds4_gpu_make_bin_rows_args(n_hc, n_tokens, n_hc);
 ds4_gpu_unary_args sigmoid_args = ds4_gpu_make_unary_rows_args(n_hc, n_tokens, 1, 0.0f, 0.0f);
 ds4_gpu_unary_args scale_args = ds4_gpu_make_unary_rows_args(n_hc, n_tokens, 1, 1.0f, eps);

 NSUInteger mul_nth_max = g_bin_mul_scalar_pipeline.maxTotalThreadsPerThreadgroup;
 if (mul_nth_max > 256u) mul_nth_max = 256u;
 NSUInteger mul_nth = 1u;
 while (2u * mul_nth < (NSUInteger)mul_args.ne0 && mul_nth < mul_nth_max) {
 mul_nth *= 2u;
 }

 NSUInteger add_nth_max = g_add_pipeline.maxTotalThreadsPerThreadgroup;
 if (add_nth_max > 256u) add_nth_max = 256u;
 NSUInteger add_nth = 1u;
 while (2u * add_nth < (NSUInteger)add_args.ne0 && add_nth < add_nth_max) {
 add_nth *= 2u;
 }

 NSUInteger unary_nth_max = g_unary_sigmoid_pipeline.maxTotalThreadsPerThreadgroup;
 if (unary_nth_max > 256u) unary_nth_max = 256u;
 NSUInteger unary_nth = (NSUInteger)sigmoid_args.ne00;
 if (unary_nth > unary_nth_max) unary_nth = unary_nth_max;
 if (unary_nth == 0) unary_nth = 1u;
 const NSUInteger unary_nk0 = ((NSUInteger)sigmoid_args.ne00 + unary_nth - 1u) / unary_nth;
 const NSUInteger out_offset = ds4_gpu_tensor_offset(out);

 int owned = 0;
 id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
 if (!cb) return 0;

 id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);

 [enc setComputePipelineState:g_bin_mul_scalar_pipeline];
 [enc setBytes:&mul_args length:sizeof(mul_args) atIndex:0];
 [enc setBuffer:prebuf offset:ds4_gpu_tensor_offset(pre) atIndex:1];
 [enc setBuffer:scalebuf offset:(NSUInteger)scale_inner atIndex:2];
 [enc setBuffer:outbuf offset:out_offset atIndex:3];
 [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)mul_args.ne01,
 (NSUInteger)mul_args.ne02,
 (NSUInteger)mul_args.ne03)
 threadsPerThreadgroup:MTLSizeMake(mul_nth, 1, 1)];

 [enc setComputePipelineState:g_add_pipeline];
 [enc setBytes:&add_args length:sizeof(add_args) atIndex:0];
 [enc setBuffer:outbuf offset:out_offset atIndex:1];
 [enc setBuffer:basebuf offset:(NSUInteger)base_inner atIndex:2];
 [enc setBuffer:outbuf offset:out_offset atIndex:3];
 [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)add_args.ne01,
 (NSUInteger)add_args.ne02,
 (NSUInteger)add_args.ne03)
 threadsPerThreadgroup:MTLSizeMake(add_nth, 1, 1)];

 [enc setComputePipelineState:g_unary_sigmoid_pipeline];
 [enc setBytes:&sigmoid_args length:sizeof(sigmoid_args) atIndex:0];
 [enc setBuffer:outbuf offset:out_offset atIndex:1];
 [enc setBuffer:outbuf offset:out_offset atIndex:2];
 [enc dispatchThreadgroups:MTLSizeMake(unary_nk0 * (NSUInteger)sigmoid_args.ne01,
 (NSUInteger)sigmoid_args.ne02,
 (NSUInteger)sigmoid_args.ne03)
 threadsPerThreadgroup:MTLSizeMake(unary_nth, 1, 1)];

 [enc setComputePipelineState:g_unary_scale_pipeline];
 [enc setBytes:&scale_args length:sizeof(scale_args) atIndex:0];
 [enc setBuffer:outbuf offset:out_offset atIndex:1];
 [enc setBuffer:outbuf offset:out_offset atIndex:2];
 [enc dispatchThreadgroups:MTLSizeMake(unary_nk0 * (NSUInteger)scale_args.ne01,
 (NSUInteger)scale_args.ne02,
 (NSUInteger)scale_args.ne03)
 threadsPerThreadgroup:MTLSizeMake(unary_nth, 1, 1)];
 ds4_gpu_end_compute_encoder(cb, enc);

 if (!ds4_gpu_finish_command_buffer(cb, owned, "output HC weights")) return 0;
 }

 return 1;
}

int ds4_gpu_hc_expand_tensor(
 ds4_gpu_tensor *out_hc,
 const ds4_gpu_tensor *block_out,
 const ds4_gpu_tensor *residual_hc,
 const ds4_gpu_tensor *post,
 const ds4_gpu_tensor *comb,
 uint32_t n_embd,
 uint32_t n_hc) {
 if (!g_initialized && !ds4_gpu_init()) return 0;
 if (n_embd == 0 || n_hc == 0) return 0;

 @autoreleasepool {
 id<MTLBuffer> blockbuf = ds4_gpu_tensor_buffer(block_out);
 id<MTLBuffer> resbuf = ds4_gpu_tensor_buffer(residual_hc);
 id<MTLBuffer> postbuf = ds4_gpu_tensor_buffer(post);
 id<MTLBuffer> combbuf = ds4_gpu_tensor_buffer(comb);
 id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out_hc);
 const uint64_t hc_row_bytes = (uint64_t)n_hc * n_embd * sizeof(float);
 const uint64_t out_tensor_bytes = ds4_gpu_tensor_bytes(out_hc);
 if (hc_row_bytes == 0 || out_tensor_bytes < hc_row_bytes || out_tensor_bytes % hc_row_bytes != 0) {
 fprintf(stderr, "ds4: Metal HC expand output size is not a whole HC token row\n");
 return 0;
 }

 const uint64_t n_tokens64 = out_tensor_bytes / hc_row_bytes;
 if (n_tokens64 == 0 || n_tokens64 > UINT32_MAX) {
 fprintf(stderr, "ds4: Metal HC expand token count is outside supported range\n");
 return 0;
 }

 const uint64_t block_values = (uint64_t)n_embd;
 const uint64_t hc_values = (uint64_t)n_hc * n_embd;
 const uint64_t comb_values = (uint64_t)n_hc * n_hc;
 if (hc_values == 0 ||
 hc_values > UINT64_MAX / sizeof(float) ||
 comb_values > UINT64_MAX / sizeof(float) ||
 n_tokens64 > UINT64_MAX / (block_values * sizeof(float)) ||
 n_tokens64 > UINT64_MAX / (hc_values * sizeof(float)) ||
 n_tokens64 > UINT64_MAX / (comb_values * sizeof(float))) {
 fprintf(stderr, "ds4: Metal HC expand activation size overflow\n");
 return 0;
 }

 const uint64_t block_bytes = n_tokens64 * block_values * sizeof(float);
 const uint64_t hc_bytes = n_tokens64 * hc_values * sizeof(float);
 const uint64_t post_bytes = n_tokens64 * (uint64_t)n_hc * sizeof(float);
 const uint64_t comb_bytes = n_tokens64 * comb_values * sizeof(float);
 if (!blockbuf || !resbuf || !postbuf || !combbuf || !outbuf ||
 ds4_gpu_tensor_bytes(block_out) < block_bytes ||
 ds4_gpu_tensor_bytes(residual_hc) < hc_bytes ||
 ds4_gpu_tensor_bytes(post) < post_bytes ||
 ds4_gpu_tensor_bytes(comb) < comb_bytes) {
 fprintf(stderr, "ds4: Metal HC expand received undersized activation buffers\n");
 return 0;
 }

 ds4_gpu_hc_expand_args args = {
 .n_embd = n_embd,
 .n_hc = n_hc,
 .n_tokens = (int64_t)n_tokens64,
 .nb_block0 = sizeof(float),
 .nb_block1 = (uint64_t)n_embd * sizeof(float),
 .nb_add0 = sizeof(float),
 .nb_add1 = (uint64_t)n_embd * sizeof(float),
 .nb_res0 = sizeof(float),
 .nb_res1 = (uint64_t)n_embd * sizeof(float),
 .nb_res2 = (uint64_t)n_hc * n_embd * sizeof(float),
 .nb_post0 = sizeof(float),
 .nb_post1 = (uint64_t)n_hc * sizeof(float),
 .nb_comb0 = sizeof(float),
 .nb_comb1 = (uint64_t)n_hc * sizeof(float),
 .nb_comb2 = (uint64_t)n_hc * n_hc * sizeof(float),
 .nb0 = sizeof(float),
 .nb1 = (uint64_t)n_embd * sizeof(float),
 .nb2 = (uint64_t)n_hc * n_embd * sizeof(float),
 .has_add = 0,
 };
 id<MTLComputePipelineState> expand_pipeline = g_hc_expand_pipeline;
 uint64_t n_elem = (uint64_t)n_embd * n_hc * n_tokens64;
 if (n_hc == 4) {
 expand_pipeline = ds4_gpu_hot_pipeline(g_dsv4_hc_expand4_pipeline,
 "kernel_dsv4_hc_expand4");
 n_elem = (uint64_t)n_embd * n_tokens64;
 }
 if (!expand_pipeline) return 0;
 const NSUInteger nth = MIN((NSUInteger)256, MAX((NSUInteger)1, (NSUInteger)n_elem));
 const NSUInteger n_tg = ((NSUInteger)n_elem + nth - 1u) / nth;
 int owned = 0;
 id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
 if (!cb) return 0;

 id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
 [enc setComputePipelineState:expand_pipeline];
 [enc setBytes:&args length:sizeof(args) atIndex:0];
 [enc setBuffer:blockbuf offset:ds4_gpu_tensor_offset(block_out) atIndex:1];
 [enc setBuffer:resbuf offset:ds4_gpu_tensor_offset(residual_hc) atIndex:2];
 [enc setBuffer:postbuf offset:ds4_gpu_tensor_offset(post) atIndex:3];
 [enc setBuffer:combbuf offset:ds4_gpu_tensor_offset(comb) atIndex:4];
 [enc setBuffer:blockbuf offset:ds4_gpu_tensor_offset(block_out) atIndex:5];
 [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out_hc) atIndex:6];
 [enc dispatchThreadgroups:MTLSizeMake(n_tg, 1, 1)
 threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
 ds4_gpu_end_compute_encoder(cb, enc);

 if (!ds4_gpu_finish_command_buffer(cb, owned, "HC expand")) return 0;
 }

 return 1;
}

int ds4_gpu_hc_expand_split_tensor(
