/* ============================================================ */

/* project-side support helpers for set_model_map_ranges */

static int g_skip_next_warmup = 0;

static int ds4_gpu_model_views_cover_range(
 const void *model_map,
 uint64_t model_size,
 uint64_t map_offset,
 uint64_t map_size) {
 for (uint32_t i = 0; i < g_model_view_count; i++) {
 if (g_model_views[i].model_map == model_map &&
 g_model_views[i].model_size == model_size &&
 map_offset >= g_model_views[i].model_offset &&
 map_offset + map_size <= g_model_views[i].model_offset + g_model_views[i].bytes) {
 return 1;
 }
 }
 return 0;
}

static int ds4_gpu_finalize_model_views(void) {
 const int request_residency = getenv("DS4_METAL_NO_RESIDENCY") == NULL;
 const double t0 = ds4_gpu_now_ms();
 if (request_residency) ds4_gpu_progress_begin("requesting Metal residency (may take tens of seconds)");
 if (!ds4_gpu_model_residency_request_views()) {
 if (request_residency) ds4_gpu_progress_failed();
 g_skip_next_warmup = 0;
 return 0;
 }
 if (request_residency) ds4_gpu_progress_done();
 const double t_resident = ds4_gpu_now_ms();

 int warmed = 1;
 const int skip_once = g_skip_next_warmup;
 g_skip_next_warmup = 0;
 const int warm_model_views = getenv("DS4_METAL_NO_RESIDENCY") == NULL &&
 getenv("DS4_METAL_NO_MODEL_WARMUP") == NULL &&
 !skip_once;
 if (warm_model_views) {
 ds4_gpu_progress_begin("warming Metal model views");
 warmed = ds4_gpu_warm_model_views();
 if (warmed) ds4_gpu_progress_done();
 else ds4_gpu_progress_failed();
 }
 const double t_warm = ds4_gpu_now_ms();
 fprintf(stderr,
 "ds4: Metal residency requested in %.3f ms, warmup %.3f ms\n",
 t_resident - t0,
 t_warm - t_resident);
 return warmed;
}

/* silv 2026-05-28 engineer-roster — model_views_clear_for_mmap retired.
 * Used only by set_model_map_ranges (now retired in same cascade). The
 * single-mmap clear path (used by set_model_map_range) calls
 * ds4_gpu_model_residency_clear() which is sufficient. */

/* project-side helpers (M1 Max Metal-residency phase control) */
/* ============================================================ */

int ds4_gpu_set_skip_next_warmup(int skip) {
 const int prev = g_skip_next_warmup;
 g_skip_next_warmup = skip ? 1 : 0;
 return prev;
}

/* silv 2026-05-28 engineer-roster — set_model_map_ranges retired.
 *
 * Used by engine_map_metal_views_with_routed_holes (ds4.c:20961) to create
 * non-contiguous views excluding cpu-moe routed ranges. That caller was
 * collapsed to set_model_map_range (full file) as part of the view/residency
 * separation fix (Metal 8.37 GiB bug). No other callers. Function and
 * header decl retired per DJB/Linus: delete dead code. */

int ds4_gpu_add_model_map_range(const void *model_map, uint64_t model_size, uint64_t map_offset, uint64_t map_size) {
 if (!g_initialized && !ds4_gpu_init()) return 0;
 if (!model_map || model_size == 0) return 0;
 if (map_offset > model_size || map_size == 0 || map_size > model_size - map_offset) return 0;

 @autoreleasepool {
 /* Drain in-flight command buffers that may reference current views
 * before we extend the residency set. */
 (void)ds4_gpu_wait_pending_command_buffers("add_model_map_range");
 /* Skip if the requested range is already covered by an existing view
 * for the same mmap. Idempotent re-add. */
 if (ds4_gpu_model_views_cover_range(model_map, model_size, map_offset, map_size)) {
 return 1;
 }
 if (!ds4_gpu_map_model_views(model_map, model_size, map_offset, map_size)) {
 return 0;
 }
 if (!ds4_gpu_finalize_model_views()) {
 return 0;
 }
 fprintf(stderr,
 "ds4: Metal added auxiliary model views (mmap=%p offset=%llu size=%llu); "
 "total views=%u\n",
 model_map, (unsigned long long)map_offset,
 (unsigned long long)map_size, g_model_view_count);
 return 1;
 }
}


/* ============================================================================
 * CDX3-native decode-matmul canary.
 *
 * This is the first Metal organ for the actual deployed H2370 codec, not the
 * obsolete VQB2 artifact. It copies one real CDX3 record's codebook/scales/
 * bitpacked indices into small MTLBuffers, runs decode+dot directly on GPU,
 * and compares against the C reader's scalar decode. Runtime integration can
 * replace these small buffers with mmap-backed pack subviews.
 * ============================================================================
 */
static NSString * const k_cdx3_decode_matmul_d8_msl =
    @"#include <metal_stdlib>\n"
     "using namespace metal;\n"
     "struct Args {\n"
     "  uint in_dim;\n"
     "  uint out_dim;\n"
     "  uint bits;\n"
     "  uint k;\n"
     "  uint rows;\n"
     "  uint scale_groups;\n"
     "  float scale_log_min;\n"
     "  float scale_log_step;\n"
     "};\n"
     "inline half cdx3_load_f16_le(device const uchar *bytes, ulong off) {\n"
     "  const ushort lo = (ushort)bytes[off + 0ul];\n"
     "  const ushort hi = (ushort)bytes[off + 1ul];\n"
     "  return as_type<half>((ushort)(lo | (hi << 8)));\n"
     "}\n"
     "kernel void cdx3_decode_matmul_d8(\n"
     "  device const half  *codebook [[buffer(0)]],\n"
     "  device const uchar *scales   [[buffer(1)]],\n"
     "  device const uchar *indices  [[buffer(2)]],\n"
     "  device const float *x        [[buffer(3)]],\n"
     "  device float       *out      [[buffer(4)]],\n"
     "  constant Args      &args     [[buffer(5)]],\n"
     "  uint row [[thread_position_in_grid]]) {\n"
     "  if (row >= args.rows || row >= args.out_dim) return;\n"
     "  const uint blocks_per_row = args.in_dim >> 3;\n"
     "  const uint code_mask = (1u << args.bits) - 1u;\n"
     "  float acc = 0.0f;\n"
     "  for (uint block_col = 0; block_col < blocks_per_row; block_col++) {\n"
     "    const ulong block_index = (ulong)row * (ulong)blocks_per_row + (ulong)block_col;\n"
     "    const ulong bit_off = block_index * (ulong)args.bits;\n"
     "    const ulong byte_off = bit_off >> 3;\n"
     "    const uint shift = (uint)(bit_off & 7ul);\n"
     "    uint window = 0u;\n"
     "    window |= ((uint)indices[byte_off + 0ul]) << 0u;\n"
     "    window |= ((uint)indices[byte_off + 1ul]) << 8u;\n"
     "    window |= ((uint)indices[byte_off + 2ul]) << 16u;\n"
     "    window |= ((uint)indices[byte_off + 3ul]) << 24u;\n"
     "    const uint code = (window >> shift) & code_mask;\n"
     "    if (code >= args.k) continue;\n"
     "    const uint scale_index = row * args.scale_groups + ((block_col << 3) >> 7);\n"
     "    const float scale = exp(args.scale_log_min + (float)scales[scale_index] * args.scale_log_step);\n"
     "    const device half *cb = codebook + (ulong)code * 8ul;\n"
     "    const uint x_base = block_col << 3;\n"
     "    acc += scale * (float(cb[0]) * x[x_base + 0] + float(cb[1]) * x[x_base + 1] +\n"
     "                    float(cb[2]) * x[x_base + 2] + float(cb[3]) * x[x_base + 3] +\n"
     "                    float(cb[4]) * x[x_base + 4] + float(cb[5]) * x[x_base + 5] +\n"
     "                    float(cb[6]) * x[x_base + 6] + float(cb[7]) * x[x_base + 7]);\n"
     "  }\n"
     "  out[row] = acc;\n"
     "}\n"
     "kernel void cdx3_decode_matmul_d8_rowtg(\n"
     "  device const half  *codebook [[buffer(0)]],\n"
     "  device const uchar *scales   [[buffer(1)]],\n"
     "  device const uchar *indices  [[buffer(2)]],\n"
     "  device const float *x        [[buffer(3)]],\n"
     "  device float       *out      [[buffer(4)]],\n"
     "  constant Args      &args     [[buffer(5)]],\n"
     "  threadgroup float  *partial  [[threadgroup(0)]],\n"
     "  uint tid [[thread_index_in_threadgroup]],\n"
     "  uint row [[threadgroup_position_in_grid]]) {\n"
     "  if (row >= args.rows || row >= args.out_dim) return;\n"
     "  const uint blocks_per_row = args.in_dim >> 3;\n"
     "  const uint code_mask = (1u << args.bits) - 1u;\n"
     "  float acc = 0.0f;\n"
     "  for (uint block_col = tid; block_col < blocks_per_row; block_col += 256u) {\n"
     "    const ulong block_index = (ulong)row * (ulong)blocks_per_row + (ulong)block_col;\n"
     "    const ulong bit_off = block_index * (ulong)args.bits;\n"
     "    const ulong byte_off = bit_off >> 3;\n"
     "    const uint shift = (uint)(bit_off & 7ul);\n"
     "    uint window = 0u;\n"
     "    window |= ((uint)indices[byte_off + 0ul]) << 0u;\n"
     "    window |= ((uint)indices[byte_off + 1ul]) << 8u;\n"
     "    window |= ((uint)indices[byte_off + 2ul]) << 16u;\n"
     "    window |= ((uint)indices[byte_off + 3ul]) << 24u;\n"
     "    const uint code = (window >> shift) & code_mask;\n"
