     "struct GateUpM1RArgs {\n"
     "  uint in_dim;\n"
     "  uint rows;\n"
     "  uint bits;\n"
     "  uint k;\n"
     "  uint scale_groups;\n"
     "  uint scale_stride;\n"
     "  uint scale_bits;\n"
     "  uint index_stride;\n"
