     "        for (uint sg = 0u; sg < 8u; sg++) total += partial[rr * 8u + sg];\n"
     "        out[ulong(token) * ulong(args.out_token_stride) + ulong(row)] = total;\n"
     "      }\n"
     "    }\n"
     "  }\n"
     "}\n"
